COLLDATA("nasai","ur",[[1031,"عبداللہ بن مسعود رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے ہمیں نماز سکھائی، آپ کھڑے ہوئے اور آپ نے اللہ اکبر کہا، تو جب آپ نے رکوع کرنا چاہا تو اپنے ہاتھوں کو ملا کر اپنے دونوں گھٹنوں کے بیچ کر لیا، اور رکوع کیا، یہ بات سعد رضی اللہ عنہ کو معلوم ہوئی تو انہوں نے کہا: میرے بھائی نے سچ کہا، ہم پہلے ایسا ہی کرتے تھے، پھر ہمیں اس کا یعنی ہاتھوں سے گھٹنوں کو پکڑنے کا حکم دیا گیا۔","الألباني: صحيح",{"u2":"حضرت علقمہ سے منقول ہے، حضرت عبداللہ بن مسعود رضی اللہ عنہ نے فرمایا: اللہ کے رسول صلی اللہ علیہ وسلم نے ہمیں نماز سکھلائی۔ پھر عبداللہ بن مسعود رضی اللہ عنہ اٹھے اور اللہ أکبر کہا۔ جب رکوع کرنے کا ارادہ کیا تو اپنے ہاتھوں کی انگلیوں کو ایک دوسرے میں پھنسا کر ہاتھوں کو گھٹنوں کے درمیان رکھ لیا۔ یہ بات حضرت سعد رضی اللہ عنہ کو پہنچی تو انھوں نے فرمایا، میرے بھائی (ابن مسعود) نے سچ کہا مگر ہم یہ کام پہلے کیا کرتے تھے، پھر (رسول اللہ صلی اللہ علیہ وسلم کی طرف سے) ہمیں گھٹنے پکڑنے کا حکم دیا گیا۔","f2":"اس طریقے کو تطبیق کہتے ہیں جو کہ منسوخ ہے۔ حضرت ابن مسعود رضی اللہ عنہ کو پتہ نہ چلا، اس لیے وہ یہ کرتے تھے مگر فقہائے امت میں سے کسی نے ان کی یہ ببات تسلیم نہیں کی حتی کہ احناف نے بھی جو کہ عموماً ان کی بات رد نہیں کرتے۔"}],[1032,"مصعب بن سعد کہتے ہیں کہ میں نے اپنے والد (سعد بن ابی وقاص رضی اللہ عنہ) کے پہلو میں نماز پڑھی، میں نے رکوع میں اپنے دونوں ہاتھوں کو دونوں گھٹنوں کے درمیان کر لیا، تو انہوں نے مجھ سے کہا: اپنی ہتھیلیاں اپنے دونوں گھٹنوں پہ رکھو، پھر میں نے دوسری بار بھی ایسا ہی کیا، تو انہوں نے میرے ہاتھ پر مارا اور کہا: ہمیں اس سے روک دیا گیا ہے، اور ہاتھوں کو گھٹنوں پہ رکھنے کا حکم دیا گیا ہے۔","الألباني: صحيح",{"u2":"مصعب بن سعد سے روایت ہےے انھوں نے فرمایا: میں نے اپنے والد کے پہلو میں نماز پڑھی اور میں نے اپنے ہاتھ اپنے گھٹنوں کے درمیان رکھ لیے تو والد محترم نے مجھ سے کہا: اپنے ہاتھ اپنے گھٹنوں پر رکھو۔ میں نے ایک دفعہ پھر اسی طرح کیا تو انھوں نے میرے ہاتھ پر مارا اور فرمایا: یقیناً ہمیں اس کام سے روکا گیا ہے، اور ہمیں حکم دیا گیا ہے کہ ہم ہاتھ گھٹنوں پر رکھیں۔"}],[1033,"مصعب بن سعد کہتے ہیں کہ میں نے رکوع کیا، تو اپنے دونوں ہاتھوں کی انگلیوں کو ایک دوسرے میں پیوست کر کے اپنے دونوں گھٹنوں کے درمیان کر لیا، تو میرے والد نے کہا: پہلے ہم ایسا ہی کرتے تھے، پھر ہم اسے اٹھا کر گھٹنوں پر رکھنے لگے۔","الألباني: صحيح",{"u2":"حضرت مصعب بن سعد سے مروی ہے، انھوں نے فرمایا: میں نے رکوع میں تطبیق کی تو میرے والد محترم نے فرمایا: یہ کام ہم پہلے کیا کرتے تھے، پھر ہمیں گھٹنوں کے اوپر ہاتھ رکھنے کے لیے کہا گیا۔","f2":"(۱) شریعت میں نسخ جائز ہے، یعنی پہلے ایک کام کرنے کا حکم دیا گیا اور بعد میں اسے دوسرے حکم کے ذریعے سے منسوخ کر دیا گیا۔ (۲) تطبیق منسوخ ہے۔ (۳) ہاتھ گھٹنوں پر رکھنا مشروع ہے۔ (۴) دوران نماز میں آدمی کو بتلایا جا سکتا ہے کہ ایسے نہ کرو بلکہ سنت طریقہ اس طرح ہے۔ (۵) حسب استطاعت منکر کو ہاتھ سے روکنا چاہیے۔"}],[1034,"عمر رضی اللہ عنہ کہتے ہیں کہ ہتھیلیوں سے گھٹنوں کو پکڑے رکھنا تمہارے لیے مسنون قرار دیا گیا ہے، لہٰذا تم رکوع میں گھٹنوں کو پکڑے رہو۔","الألباني: صحيح الإسناد",{"u2":"حضرت عمر رضی اللہ عنہ بیان کرتے ہیں کہ تمھارے لیے گھٹنوں کو پکڑنے کا طریقہ رائج کیا گیا ہے، لہٰذا گھٹنوں کو پکڑا کرو۔"}],[1035,"ابوعبدالرحمٰن سلمی کہتے ہیں کہ عمر رضی اللہ عنہ نے کہا: سنت تو گھٹنوں کو پکڑنا ہی ہے۔","الألباني: صحيح الإسناد",{"u2":"حضرت عمر رضی اللہ عنہ فرماتے ہیں (رکوع میں) گھٹنوں کو پکڑنا سنت ہے۔","f2":"صحابی کا کسی کام کو یقین کے ساتھ سنت کہنا رسول اللہ صلی اللہ علیہ وسلم کے قول و فعل کے برابر حیثیت رکھتا ہے اور اسے مرفوع حکمی کہا جاتا ہے۔ محدثین کی اصطلاح میں سنت سے مراد، سنت رسول اللہ صلی اللہ علیہ وسلم ہے۔"}],[1036,"سالم البراد کہتے ہیں کہ ہم ابومسعود (عقبہ بن عمرو) کے پاس آئے تو ہم نے ان سے کہا: آپ ہم سے رسول اللہ صلی اللہ علیہ وسلم کی نماز کے بارے میں بیان کیجئے تو وہ ہمارے سامنے کھڑے ہوئے، اور اللہ اکبر کہا، اور جب انہوں نے رکوع کیا تو اپنی ہتھیلیوں کو اپنے دونوں گھٹنوں پہ رکھا، اور انگلیوں کو اس سے نیچے، اور اپنی دونوں کہنیوں کو پہلو سے جدا رکھا یہاں تک کہ ان کی ہر چیز سیدھی ہو گئی، پھر انہوں نے «سمع اللہ لمن حمدہ» کہا، اور کھڑے ہو گئے یہاں تک کہ ان کی ہر چیز سیدھی ہو گئی۔","الألباني: صحيح إلا جملة الأصابع",{"u2":"حضرت سالم بیان کرتے ہیں کہ ہم حضرت ابو مسعود رضی اللہ عنہ کے پاس گئے اور ان سے گزارش کی کہ ہمیں رسول اللہ صلی اللہ علیہ وسلم کی نماز بیان کیجیے۔ آپ ہمارے آگے کھڑے ہوگئے اور اللہ اکبر کہا۔ جب آپ نے رکوع کیا تو اپنی ہتھیلیاں اپنے گھٹنوں پر رکھیں اور انگلیاں اس سے نیچے رکھیں اور اپنی کہنیوں کو پہلوؤں سے دور رکھا حتی کہ آپ کا ہر عضو سیدھا اور درست ہوگیا۔ پھر سمع اللہ لمن حمدہ کہا اور کھڑے ہوگئے حتی کہ آپ کا ہر عضو سیدھا اور درست ہوگیا۔"}],[1037,"ابوعبداللہ سالم بن البرد سے روایت ہے کہ عقبہ بن عمرو رضی اللہ عنہ کہتے ہیں کہ کیا میں تمہارے سامنے ایسی نماز نہ پڑھوں جیسی میں نے رسول اللہ صلی اللہ علیہ وسلم کو پڑھتے دیکھا ہے؟ تو ہم نے کہا: کیوں نہیں! ضرور پڑھیئے، تو وہ کھڑے ہوئے، جب انہوں نے رکوع کیا تو اپنی ہتھیلیوں کو اپنے دونوں گھٹنوں پہ، اور اپنی انگلیوں کو گھٹنوں کے نیچے رکھا، اور اپنے بغلوں کو جدا رکھا یہاں تک کہ ان کی ہر چیز اپنی جگہ پر آ گئی، پھر انہوں نے اپنا سر اٹھایا اور کھڑے ہو گئے، پھر سجدہ کیا اور اپنے بغلوں کو جدا رکھا یہاں تک ان کی ہر چیز اپنی جگہ جم گئی، پھر وہ بیٹھے یہاں تک کہ جسم کا ہر عضو اپنی جگہ پر آ گیا، پھر انہوں نے سجدہ کیا یہاں تک کہ جسم کا ہر ہر عضو اپنی جگہ پر آ گیا، چاروں رکعتیں اسی طرح ادا کیں، پھر انہوں نے کہا: میں نے اسی طرح رسول اللہ صلی اللہ علیہ وسلم کو نماز پڑھتے دیکھا ہے، اور آپ ہمیں اسی طرح پڑھاتے بھی تھے۔","الألباني: صحيح إلا جملة الأصابع",{"u2":"حضرت سالم سے روایت ہے کہ حضرت عقبہ بن عمرو رضی اللہ عنہ نے کہا: کیا میں تمھارے سامنے اس طرح نماز نہ پڑھوں جس طرح میں نے رسول اللہ صلی اللہ علیہ وسلم کو پڑھتے دیکھا ہے؟ ہم نے کہا: کیوں نہیں! آپ کھڑے ہوئے۔ جب رکوع کیا تو اپنی ہتھیلیاں اپنے گھٹنوں پر رکھیں اور اپنی انگلیوں کو گھٹنوں سے نیچے رکھا اور اپنی بغلوں کو کھولا (بازوؤں کو پہلو سے دور رکھا) حتی کہ پ کا ہر عضو سیدھا ہو گیا۔ پھر آپ نے سجدہ کیا اور اپنی بغلوں کو کھولا (بازوؤں کو پہلو سے دور رکھا) حتی کہ آپ کا ہر عضو (اپنی جگہ پر) ٹھہر گیا۔ پھر بیٹھے حتی کہ آپ کا ہر عضو (اپنی جگہ پر) ٹھہر گیا۔ پھر سجدہ کیا حتی کہ ہر عضو (اپنی جگہ پر) ٹھہر گیا۔ پھر آپ نے چاروں رکعات میں اسی طرح کیا۔ پھر فرمایا: میں نے رسول اللہ صلی اللہ علیہ وسلم کو اسی طرح نماز پڑھتے دیکھا ہے اور آپ ہمیں اسی طرح نماز پڑھاتے تھے۔"}],[1038,"ابوعبداللہ سالم براد کہتے ہیں کہ ابومسعود (عقبہ بن عمرو) رضی اللہ عنہ کہنے لگے کہ کیا میں تمہیں نہ دکھاؤں کہ رسول اللہ صلی اللہ علیہ وسلم کیسے نماز پڑھتے تھے؟ تو ہم نے کہا: کیوں نہیں، ضرور دکھایئے، چنانچہ وہ کھڑے ہوئے، اور اللہ اکبر کہا، اور جب رکوع کیا تو اپنے دونوں ہاتھوں کو اپنے دونوں بغلوں سے جدا رکھا، یہاں تک کہ جب ان کی ہر چیز اپنی جگہ پر آ گئی تو انہوں نے اپنا سر اٹھایا، اسی طرح انہوں نے چار رکعتیں پڑھیں، اور کہا: میں نے اسی طرح رسول اللہ صلی اللہ علیہ وسلم کو نماز پڑھتے دیکھا ہے۔","الألباني: صحيح لغيره",{"u2":"حضرت سالم براد سے روایت ہے، حرت ابو مسعود رضی اللہ عنہ نے کہا: کیا میں تمھیں نہ دکھاؤں کہ رسول اللہ صلی اللہ علیہ وسلم کیسے نماز پڑھتے تھے؟ ہم نے کہا: ہاں، ضرور۔ آپ کھڑے ہوئے اور اللہ اکبر کہا۔ پھر جب رکوع کیا تو اپنی بغلوں کو خوب کھولا حتی کہ جب آپ کا ہر عضو (اپنی جگہ پر) جم گیا تو آپ نے اپنا سر اٹھایا۔ پھر چاروں رکعات اسی طرح پڑھیں اور فرمایا: میں نے رسول اللہ صلی اللہ علیہ وسلم کو اسی طرح نماز پڑھتے دیکھا ہے۔"}],[1039,"ابو حمید ساعدی رضی اللہ عنہ کہتے ہیں کہ نبی اکرم صلی اللہ علیہ وسلم جب رکوع کرتے تو پیٹھ اور سر کو برابر رکھتے، نہ تو سر کو بہت اونچا رکھتے اور نہ اسے جھکا کر رکھتے، اور اپنے ہاتھوں کو اپنے دونوں گھٹنوں پہ رکھتے۔","الألباني: صحيح",{"u2":"حضرت ابوحمید ساعدی رضی اللہ عنہ فرماتے ہیں: نبی صلی اللہ علیہ وسلم جب رکوع فرماتے تو میانہ روی اختیار فرماتے، یعنی نہ تو اپنا سر بہت نیچے جھکاتے اور نہ اسے اوپر اٹھاتے (بلکہ پشت کے برابر رکھتے)۔ اور آپ اپنے دونوں ہاتھ اپنے دونوں گھٹنوں پر رکھتے۔","f2":"فائدہ: دیکھیے حدیث نمبر ۱۰۲۹۔"}],[1040,"علی رضی اللہ عنہ کہتے ہیں کہ مجھے نبی اکرم صلی اللہ علیہ وسلم نے قسی ۱؎ اور حریر ۲؎ اور سونے کی انگوٹھی پہننے سے روکا ہے، اور اس بات سے بھی کہ میں رکوع کی حالت میں قرآن پڑھوں۔ دوسری بار راوی نے «أن أقرأ وأنا راكع» کے بجائے «أن أقرأ راكعا» کہا۔\n§وضاحت\n۱؎: ایک ریشمی کپڑا ہے قس کی طرف منسوب ہے جو ایک جگہ کا نام ہے۔ ۲؎: خالص ریشمی کپڑا۔","الألباني: صحيح",{"u2":"حضرت علی رضی اللہ عنہ سے روایت ہے کہ مجھے نبی صلی اللہ علیہ وسلم نے قسی اور ریشمی کپڑے اور سونے کی انگوٹھی پہننے سے روکا ہے اور اس بات سے بھی کہ میں رکوع کی حالت میں قرآن مجید پڑھوں۔","f2":"(۱) قسی کپڑے سے مراد قس (مصر کی ایک بستی) میں بنائے گئے کپڑے ہیں جن میں ریشمی پٹیاں ہوتی تھیں یا جن کا تانا ریشم سے ہوتا تھا اور بانا سوتی۔ چونکہ اس میں ریشم کافی مقدار میں ہوتا تھا، لہٰذا اس سے بھی منع فرما دیا، البتہ اگر ایک آدھ پٹی ریشم کی ہو تو کوئی حرج نہیں، مثلاً: صرف مردوں کے لیے ہے۔ عورتوں کے لیے ریشم اور سونا پہننا جائز ہے۔ حضرت ابوموسیٰ رضی اللہ عنہ فرماتے ہیں: نبیٔ اکرم صلی اللہ علیہ وسلم نے فرمایا: [احل الذھب والحریر لاناث امتی وحرم علی ذکورھا] ’’سونا اور ریشم میری امت کی عورتوں کے لیے حلال کر دیا گیا ہے اور مردوں پر حرام۔‘‘ (جامع الترمھذي، اللباس، حدیث:۱۷۲۰، و سنن النسائی، الزیینۃ، حدیث: ۵۱۵۱، واللفظ لہ)"}],[1041,"علی رضی اللہ عنہ کہتے ہیں کہ نبی اکرم صلی اللہ علیہ وسلم نے مجھے سونے کی انگوٹھی پہننے سے، رکوع کی حالت میں قرآن پڑھنے سے، قسی کے بنے ہوئے ریشمی کپڑے اور کسم میں رنگے ہوئے کپڑے پہننے سے منع فرمایا ہے۔","الألباني: حسن صحيح الإسناد",{"u2":"حضرت علی رضی اللہ عنہ سے روایت ہے کہ مجھے نبی صلی اللہ علیہ وسلم نے سونے کی انگوٹھی پہننے، رکوع میں قراءت قرآن کرنے، قسی اور معصفر (زعفرانی زرد رنگ کا کپڑا) پہننے سے منع کیا ہے۔","f2":"(۱) جب سونے کی انگوٹھی منع ہے تو سونے کے دیگر زیورات بدرجۂ اولیٰ منع ہیں۔ (۲) معصفر کسنبے کے رنگ سے رنگا ہوا کپڑا بھی عورتوں کے لیے جائز ہے، مردوں کےل یے نہیں ورنہ عورتوں سے مشابہت ہوگی۔ پھر اس میں سادھوؤں کے ساتھ بھی مشابہت ہوگی۔ مرد زینت کی بجائے وقار کا زیادہ لحاظ رکھیں۔"}],[1042,"علی رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے مجھے سونے کی انگوٹھی پہننے سے، قسی کے بنے ہوئے ریشمی کپڑے پہننے سے، انتہائی سرخ کپڑے اور کسم میں رنگے ہوئے کپڑے پہننے سے، اور رکوع میں قرآن پڑھنے سے منع کیا ہے، میں یہ نہیں کہتا کہ تمہیں منع کیا ہے۔","الألباني: صحيح",{"u2":"حضرت علی رضی اللہ عنہ سے مروی ہے، اللہ کے رسول صلی اللہ علیہ وسلم نے مجھے ……… میں نہیں کہتا کہ تمھیں ……… سونے کی انگوٹھی، قسی کپڑے، خالص اور انتہائی سرخ اور زعفرانی زرد رنگ کے کپڑے پہننے اور رکوع میں قرآن مجید پڑھنے سے منع فرمایا ہے۔","f2":"(۱) ’’میں نہیں کہتا کہ تمھیں‘‘ حضرت علی رضی اللہ عنہ کا مطلب صرف یہ ہے کہ نبی صلی اللہ علیہ وسلم نے مجھ سے خصوصاً مخاطب ہوکر یہ لفظ فرمائے تھے اور کوئی اس وقت موجود نہ تھا اور میں نے جس طرح نبی صلی اللہ علیہ وسلم سے سنا ہے، بعینہٖ اسی طرح بیان کر رہا ہوں۔ یہ مطلب نہیں کہ یہ حکم صرف میرے لیے ہے، تمھارے لیے نہیں، بلکہ یہ حکم ہر مسلمان کے لیے ہے جیسا کہ دیگر صریح روایات سے ثابت ہے۔ (۲) ’’مقدم‘‘ خالص اور انتہائی سرخ۔ گویا اگر سرخ دھاریاں ہوں باقیرنگ کوئی اور ہو یا ہلکا سرخ ہو (جو عورتیں عموماً نہیں پہنتیں) تو وہ جائز ہے جیسا کہ کئی روایات میں ہے کہ رسول اللہ صلی اللہ علیہ وسلم سرخ حلہ پہنتے تھے۔ گویا وہ دھاری دار تھا۔"}],[1043,"علی رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے مجھے سونے کی انگوٹھی سے اور قسی کے بنے ریشمی کپڑے، کسم میں رنگے کپڑے پہننے سے، اور رکوع کی حالت میں قرآن پڑھنے سے منع کیا ہے۔","الألباني: صحيح",{"u2":"حضرت علی رضی اللہ عنہ سے منقول ہے کہ مجھے رسول اللہ صلی اللہ علیہ وسلم نے قسی اور معصفر (زعفرانی زرد رنگ کا) کپڑا اور سونے کی انگوٹھی پہننے اور رکوع میں قرآن مجید پڑھنے سے منع فرمایا ہے۔"}],[1044,"علی رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے مجھے قسی کے بنے ریشمی کپڑے، اور کسم میں رنگے کپڑے پہننے سے، اور سونے کی انگوٹھی پہننے سے، اور رکوع میں قرآن پڑھنے سے منع کیا ہے۔","الألباني: صحيح",{"u2":"حضرت علی رضی اللہ عنہ سے مروی ہے کہ مجھے رسول اللہ صلی اللہ علیہ وسلم نے قسی، زعفرانی زرد رنگ کے کپڑے اور سونے کی انگوٹھی پہننے اور رکوع میں قرآن مجید پڑھنے سے منع فرمایا ہے۔"}],[1045,"عبداللہ بن عباس رضی اللہ عنہم کہتے ہیں کہ نبی اکرم صلی اللہ علیہ وسلم نے اپنے حجرے کا پردہ اٹھایا، اور لوگ ابوبکر رضی اللہ عنہ کے پیچھے صف باندھے کھڑے تھے، تو آپ صلی اللہ علیہ وسلم نے فرمایا: \"لوگو! نبوت کی خوشخبری سنانے والی چیزوں میں سے کوئی چیز باقی نہیں بچی ہے سوائے سچے خواب کے جسے مسلمان دیکھے یا اس کے لیے کسی اور کو دکھایا جائے\"، پھر فرمایا: \"سنو! مجھے رکوع و سجود میں قرآن پڑھنے سے روکا گیا ہے، رہا رکوع تو اس میں اپنے رب کی بڑائی بیان کرو، اور رہا سجدہ تو اس میں دعا کی کوشش کرو کیونکہ اس میں تمہاری دعا قبول کئے جانے کے لائق ہے\"۔","الألباني: صحيح",{"u2":"حضرت ابن عباس رضی اللہ عنہما سے روایت ہے کہ نبی صلی اللہ علیہ وسلم نے (دروازے کا) پردہ ہٹایا جب کہ لوگ حضرت ابوبکر رضی اللہ عنہ کے پیچھے صفیں باندھے ہوئے تھے۔ آپ نے فرمایا: ’’اے لوگو! نبوت سے مخصوص خوش خبری دینے والی چیزوں میں سے اب نیک اور سچے خواب ہی رہ گئے ہیں جو کوئی مسلمان خود دیکھ لے یا اس کے لیے کسی اور کو نظر آئے۔‘‘ پھر فرمایا: ’’خبردار! مجھے رکوع یا سجدے کی حالت میں قرآن مجید پڑھنے سے روکا گیا ہے، چنانچہ رکوع میں رب تعالیٰ کی عظمت بیان کرو اور سجدے میں دعا مانگنے کی کوشش کرو (پورا زور لگا دو کیونکہ) سجدے میں دعا قبولیت کے زیادہ لائق ہے۔‘‘","f2":"1۔یہ ارشادات رسول اللہ صلی اللہ علیہ وسلم کی حیات مبارکہ کے آخری دن کے ہیں۔ (۲) نبی کو تو خوش خبری وحی کے ذریعے سے بھی دی جا سکتی ہے مگر امتیوں کو صرف خواب یا کبھی کبھار الہام کے ذریعے سے ہی خوش خبری دی جا سکتی ہے۔ چونکہ آپ کی وفات قریب تھی، وحی کا انقطاع ہونے ہی والا تھا، اس لیے یوں ارشاد فرمایا۔ (۳) رکوع میں عظمت کا بیان اور تسبیح زیادہ مناسب ہیں، لہٰذا ان کی طرف زیادہ توجہ دی جائے۔ سجدے میں دعا کا موقع ہے کیونکہ یہ انسان کے تذلل و خشوع اور عاجزی کی انتہائی صورت ہے۔ نماز کے ارکان میں سے مقصود اعظم ے، لہٰذا سجدے میں پوری کوشش اور تندہی سے خوب دعا کی جائے۔ ہر مقالے را مقام دیگر است۔ اگرچہ سجدہ تسبیح کا بھی محل ہے۔"}],[1046,"حذیفہ رضی اللہ عنہ کہتے ہیں کہ میں نے رسول اللہ صلی اللہ علیہ وسلم کے ساتھ نماز پڑھی، آپ نے رکوع کیا تو اپنے رکوع میں «سبحان ربي العظيم» اور سجدے میں «سبحان ربي الأعلى» کہا۔","الألباني: صحيح",{"u2":"حضرت حذیفہ رضی اللہ عنہ سے مروی ہے کہ میں نے رسول اللہ صلی اللہ علیہ وسلم کے ساتھ نماز پڑھی۔ آپ نے رکوع فرمایا تو اپنے رکوع میں [سبحان ربی العظیم] ’’پاک ہے میرا عظمتوں والا رب۔‘‘ اور سجدے میں [سبحان ربی الاعلی] ’’پاک ہے میرا بلند و بالا رب۔‘‘ پڑھا۔","f2":"ایک اور روایت میں یہ تسبیحات کم از کم تین دفعہ پڑھنے کا حکم دیا گیا ہے۔ آخر میں یہ کہ یہ کم از کم رکوع و سجود ہے، لیکن یہ روایت ضعیف ہے۔ دیکھیے: (ضعیف سنن ابی داود (مفصل) للالبانی: حدیث: ۱۵۵)\nصحیح روایت میں بجائے حکم کے رسول اللہ صلی اللہ علیہ وسلم کا ذاتی فعل منقول ہے۔ دیکھیے: (صحیح ابی داود (مفصل) للالبانی، حدیث: ۸۲۸) لہٰذا کم از کم سجدے میں تین تسبیحات افضل ہیں، ضروری نہیں۔ نیز طاق کی قید کے بغیر تین سے زیادہ تسبیحات بھی کہی جا سکتی ہیں۔ اس کی دلیل رسول اللہ صلی اللہ علیہ وسلم کی وہ احادیث ہیں جن میں آپ کے قیام، رکوع اور سجدے کی یکساں مقدار بتائی گئی ہے۔"}],[1047,"ام المؤمنین عائشہ رضی اللہ عنہا کہتی ہیں رسول اللہ صلی اللہ علیہ وسلم رکوع اور سجدے میں «سبحانك ربنا وبحمدك اللہم اغفر لي» \"اے ہمارے رب تیری ذات پاک ہے، اور تیری حمد کے ساتھ ہم تیری تسبیح بیان کرتے ہیں، اے اللہ تو مجھے بخش دے\" کثرت سے پڑھتے تھے۔","الألباني: صحيح",{"u2":"حضرت عائشہ رضی اللہ عنہا فرماتی ہیں: رسول اللہ صلی اللہ علیہ وسلم اپنے رکوع اور سجدے میں اکثر یہ دعا پڑھا کرتے تھے: [سبحان ربنا و بحمدک اللھم اغفرلی] ’’اے ہمارے رب! تو ہر قسم کے نقائص و عیوب سے پاک ہے اور ہر قسم کی تعریفوں کا مستحق ہے۔ اے اللہ مجھے معاف فرما دے۔‘‘","f2":"رسول اللہ صلی اللہ علیہ وسلم اپنی امت کو تعلیم دینے کے لیے یہ دعائیں پڑھتے تھے ورنہ آپ تو گناہوں سے معصوم تھے۔"}],[1048,"ام المؤمنین عائشہ رضی اللہ عنہا کہتی ہیں کہ رسول اللہ صلی اللہ علیہ وسلم رکوع میں «سبوح قدوس رب الملائكة والروح» \"فرشتوں اور جبرائیل امین کا رب ہر نقص و عیب سے پاک اور تمام آلائشوں سے منزہ ہے\"، پڑھتے تھے۔","الألباني: صحيح",{"u2":"حضرت عائشہ رضی اللہ عنہا فرماتی ہیں: رسول اللہ صلی اللہ علیہ وسلم رکوع میں [سبوح قدوس رب الملائکۃ و الروح] ’’بہت پاک ہے، منزہ ہے فرشتوں اور روح (جبریل امین) کا رب۔‘‘ پڑھا کرتے تھے۔","f2":"روح سے کیا مراد ہے؟ کہا جاتا ہے کہ جبریل علیہ السلام یا فرشتوں سے بالا ایک مخلوق جو فرشتوں کو دیکھتی ہے، فرشتے اس کو نہیں دیکھتے یا ارواح انسانیہ۔ لیکن قرآن کریم سے اس کی صراحت ہوتی ہے کہ اس سے مراد جبریل امین ہی ہیں کہ ان کے شرف و مرتبت کی بنا پر بطور خاص فرشتوں کے بعد علیحدہ ذکر کیا۔ ارشاد باری تعالیٰ ہے: (نزل بہ الروح الامین) (الشعراء ۱۹۳:۲۶) ’’اس (قرآن) کو امانت دار فرشتہ لے کر اترا ہے۔‘‘"}],[1049,"عوف بن مالک رضی اللہ عنہ کہتے ہیں کہ میں ایک رات رسول اللہ صلی اللہ علیہ وسلم کے ساتھ (نماز کے لیے) کھڑا ہوا تو جب آپ صلی اللہ علیہ وسلم نے رکوع کیا، تو سورۃ البقرہ پڑھنے کے بقدر رکوع میں ٹھہرے، آپ اپنے رکوع میں «سبحان ذي الجبروت والملكوت والكبرياء والعظمة» \"میں صاحب قدرت و بادشاہت اور صاحب بزرگی و عظمت کی پاکی بیان کرتا ہوں\" پڑھ رہے تھے۔","الألباني: صحيح",{"u2":"حضرت عوف بن مالک رضی اللہ عنہ سے مروی ہے کہ میں رسول اللہ صلی اللہ علیہ وسلم کے ساتھ ایک رات نماز میں کھڑا ہوا۔ جب آپ نے رکوع فرمایا تو سورۂ بقرہ کے بقدر رکوع میں ٹھہرے رہے اور پڑھتے رہے: [سبحان ذی الجبروت والملکوت والبکریاء والعظمۃ] ’’پاک ہے عظیم الشان غلبے اور بڑی بادشاہت والا اور بے انتہا بزرگی (بڑائی) اور عظمت والا رب۔‘‘"}],[1050,"علی بن ابی طالب رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم جب رکوع کرتے تو «اللہم لك ركعت ولك أسلمت وبك آمنت خشع لك سمعي وبصري وعظامي ومخي وعصبي» \"اے اللہ! میں نے تیرے لیے اپنی پیٹھ جھکا دی، اور اپنے آپ کو تیرے حوالے کر دیا، اور میں تجھ پر ایمان لایا، میرے کان، میری آنکھیں، میری ہڈیاں، میرے بھیجے اور میرے پٹھوں نے تیرے لیے عاجزی کا اظہار کیا\" پڑھتے تھے۔","الألباني: صحيح",{"u2":"حضرت علی بن ابو طالب رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم جب رکوع فرماتے تو یوں پڑھتے: [اللھم! لک رکعت ……… و عصبی] ’’اے اللہ! میں تیرے سامنے جھکا، اپنے آپ کو تیرے سپرد کیا اور تجھ پر ایمان لایا۔ میرے کان، آنکھیں، ہڈیاں، مغز اور پٹھے سب تیرے سامنے عجز و نیاز ظاہر کرتے ہیں۔‘‘"}],[1051,"جابر بن عبداللہ رضی اللہ عنہم سے روایت ہے کہ نبی اکرم صلی اللہ علیہ وسلم جب رکوع کرتے تو اس میں «اللہم لك ركعت وبك آمنت ولك أسلمت وعليك توكلت أنت ربي خشع سمعي وبصري ودمي ولحمي وعظمي وعصبي لله رب العالمين» \"اے اللہ! میں نے تیرے لیے ہی اپنا سر جھکا دیا، تیرے اوپر ہی ایمان لایا، میں نے اپنے آپ کو تیرے ہی حوالے کر دیا، تیرے ہی اوپر بھروسہ کیا، تو میرا رب ہے، میرے کان، میری آنکھ، میرا خون، میرا گوشت، میری ہڈیاں اور میرے پٹھے نے اللہ کے لیے جو سارے جہانوں کا رب ہے عاجزی کا اظہار کیا ہے\" پڑھتے تھے۔","الألباني: صحيح",{"u2":"حضرت جابر بن عبداللہ رضی اللہ عنہما سے منقول ہے کہ نبی صلی اللہ علیہ وسلم جب رکوع فرماتے تو یوں کہتے: [اللھم! لک رکعت ……… رب العلمین] ’’اے اللہ! میں تیرے سامنے جھکا، تجھ پر ایمان لایا، اپنے آپ کو تیرے سپرد کیا اور تجھی پر بھروسا کیا۔ تو میرا رب ہے۔ میرے کانوں، آنکھوں، خون، گوشت، ہڈیوں اور پٹھوں نے اللہ عزوجل کے سامنے عجز و نیاز ظاہر کیا جو تمام جہانوں کا پالنے والا ہے۔‘‘"}],[1052,"محمد بن مسلمہ رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم جب نفل پڑھنے کھڑے ہوتے تو جب رکوع میں جاتے تو «اللہم لك ركعت وبك آمنت ولك أسلمت وعليك توكلت أنت ربي خشع سمعي وبصري ولحمي ودمي ومخي وعصبي لله رب العالمين» \"اے اللہ! میں نے تیرے لیے اپنی پیٹھ جھکا دی، تیرے اوپر ایمان لایا، میں نے اپنے آپ کو تیرے سپرد کر دیا، اور تجھ پر بھروسہ کیا، تو میرا رب ہے، میرا کان، میری آنکھ، میرا گوشت، میرا خون، میرا دماغ اور میرے پٹھے نے اللہ رب العالمین کے لیے عاجزی کا اظہار کیا ہے\" پڑھتے۔","الألباني: صحيح",{"u2":"حضرت محمد بن مسلمہ رضی اللہ عنہ سے مروی ہے کہ رسول اللہ صلی اللہ علیہ وسلم جب نفل نماز میں کھڑے ہوتے تو رکوع کے دوران میں یوں عرض پرداز ہوتے: ’’اے اللہ! میں تیرے لیے جھکا، تجھے مانا، تیرا فرماں برادر بنا اور تجھ پر بھروسا کیا۔ تو میرا ہبرب ہے۔ میرے کان، آنکھیں، گوشت، خون، مغز اور پٹھے اللہ رب العالمین کے سامنے عاجزی اور تواضع کرتے ہیں۔‘‘","f2":"اس قسم کے الفاظ سے مقصود کامل خشوع و خضوع کا اظہار ہے۔ خشوع اگرچہ قلبی کیفیت کا نام ہے مگر اس کا اظہار اعضائے ظاہرہ ہی سے ہوتا ہے۔ رکوع اور سجود کے دوران میں نہ صرف یہ الفاظ ورد زبان ہونے چاہئیں بلکہ واقعتاً ہر عضو ظاہراً بھی باری تعالیٰ کے حضور سراپا عجز و نیاز بنا نظر آئے۔ کان اور آنکھ نماز میں کسی اور چیز کی طرف متوجہ نہ ہوں۔ سر اور ہاتھ پاؤں ڈھیلے اور نرم ہوں۔ ان میں بے نیازی اور فخر نہ پایا جائے۔"}],[1053,"رفاعہ بن رافع رضی اللہ عنہ کہتے ہیں کہ ہم رسول اللہ صلی اللہ علیہ وسلم کے ساتھ تھے کہ ایک شخص مسجد میں داخل ہوا، اور اس نے نماز پڑھی، رسول اللہ صلی اللہ علیہ وسلم اسے دیکھ رہے تھے لیکن وہ جان نہیں رہا تھا، وہ نماز سے فارغ ہوا، تو رسول اللہ صلی اللہ علیہ وسلم کے پاس آیا، اور آپ کو سلام کیا، تو آپ نے سلام کا جواب دیا، پھر آپ صلی اللہ علیہ وسلم نے فرمایا: \"جاؤ تم پھر سے نماز پڑھو کیونکہ تم نے نماز نہیں پڑھی\"، میں نہیں جان سکا کہ اس نے دوسری بار میں یا تیسری بار میں کہا کہ قسم ہے اس ذات کی جس نے آپ پر قرآن نازل کیا ہے، میں اپنی کوشش کر چکا، آپ مجھے نماز پڑھنا سکھا دیں، اور پڑھ کر دکھا دیں کہ کیسے پڑھوں، آپ صلی اللہ علیہ وسلم نے فرمایا: \"جب تم نماز کا ارادہ کرو تو وضو کرو اور اچھی طرح وضو کرو، پھر قبلہ رخ کھڑے ہو، پھر اللہ اکبر کہو، پھر قرأت کرو، پھر رکوع کرو یہاں تک کہ تم رکوع کی حالت میں مطمئن ہو جاؤ، پھر اٹھو یہاں تک کہ سیدھے کھڑے ہو جاؤ، پھر سجدہ کرو یہاں تک کہ سجدہ کی حالت میں مطمئن ہو جاؤ، پھر اپنا سر اٹھاؤ یہاں تک کہ اطمینان سے بیٹھ جاؤ، پھر سجدہ کرو یہاں تک کہ سجدہ کی حالت میں مطمئن ہو جاؤ، جب تم ایسا کرو گے تو اپنی نماز پوری کر لو گے، اور اس میں جو کمی کرو گے تو اپنی نماز ہی میں کمی کرو گے\" ۱؎۔\n§وضاحت\n۱؎: مؤلف نے اس سے استدلال کیا ہے کہ آپ نے رکوع :(یا سجدہ ) میں تسبیح کا ذکر نہیں کیا ہے، آپ اس کو صلاۃ سکھا رہے تھے، اس سے معلوم ہوا کہ رکوع :(یا سجدہ ) میں تسبیح ضروری نہیں ہے، لیکن یہ استدلال صحیح نہیں، اس میں بہت سے واجبات کا ذکر نہیں ہے، دراصل اس آدمی میں تعدیل ارکان کی کمی تھی، اسی پر توجہ دلانا مقصود تھا، اس لیے آپ نے اعتدال پر خاص زور دیا، اور بہت سے واجبات کا ذکر نہیں کیا، دیگر روایات میں تسبیحات کا حکم موجود ہے۔","الألباني: حسن صحيح",{"u2":"حضرت رفاعہ بن رافع رضی اللہ عنہ، جوبدری صحابی ہیں، سے روایت ہے کہ ہم رسول اللہ صلی اللہ علیہ وسلم کے ساتھ تھے کہ ایک آدمی مسجد میں آیا اور اس نے نماز پڑھی۔ رسول اللہ صلی اللہ علیہ وسلم اسے دیکھتے رہے جب کہ اسے علم نہ تھا۔ پھر وہ (نماز سے) فارغ ہوا تو رسول اللہ صلی اللہ علیہ وسلم کے پاس آیا اور آپ کو سلام کیا۔ آپ نے سلام کا جواب دیا، پھر فرمایا: ’’واپس جا، پھر نماز پڑھ۔ تو نے نماز نہیں پڑھی۔‘‘ نہ معلوم دوسری یا تیسری دفعہ اس نے کہا: قسم ہے اس ذات کی جس نے آپ پر کتاب اتاری! میں نے تو پوری کوشش سے نماز پڑھی ہے۔ مجھے سکھلا دیجیے اور بتلا دیجیے۔ آپ نے فرمایا: ’’جب تو نماز کا ارادہ کرے تو وضو کر اور اچھی طرح وضو کر۔ پھر کھڑا ہو اور قبلے کی طرف منہ کر۔ پھر اللہ اکبر کہہ۔ پھر قرآن مجید پڑھ۔ پھر رکوع کو حتی کہ اطمینان سے رکوع کرلے۔ پھر سر اٹھا حتی کہ تو سیدھا کھڑا ہو جائے۔ پھر سجدہ کر حتی کہ اطمینان سے سجدہ کرلے۔ پھر سر اٹھا حتی کہ اطمینان سے بیٹھ جائے۔ پھر سجدہ کر حتی کہ اطمینان سے سجدہ کرلے۔ جب تو (ہر رکعت میں) یہ کرلے گا تو اپنی نماز ادا کرلے گا اور جس قدر تو اس میں کمی کرے گا، اپنی نماز میں کمی کرے گا۔","f2":"(۱) مصنف رحمہ اللہ نے اس حدیث سے استدلال کیا ہے کہ رکوع اور سجدے میں تسبیحات فرض نہیں ہیں کیونکہ اس حدیث میں ان کا ذکر نہیں۔ اگر اتفاقاً یا نسیاناً رہ جائیں تو نماز ہو جائے گی، البتہ ……… چھوڑی جائیں لیکن اہل علم نے سجدے اور رکوع کی تسبیحات بربنائے دلیل واجب قرار دی ہیں کیونکہ رسول اللہ صلی اللہ علیہ وسلم کی نماز کی طرح نماز پڑھنے کا حکم ہے۔ (صحیح البخاري، الاذان، حدیث: ۶۳۱) نیز عدم ذکر عدم وجود کو مستلزم نہیں۔ جس شخص سے تسبیحات اتفاقاً یا نسیانا رہ جائیں، وہ نماز کے آخری میں سجود سہو کرے گا۔ (تفصیل کے لیے ملاحظہ ہو کتاب السہو کا ابتدائیہ)۔ (۲) مذکورہ حدیث میں آپ نے فرائض اور واجبات بتلائگے ہیں یا وہ چیزیں ذکر کی ہیں جو وہ شخص صحیح ادا نہیں کرتا تھا جس کی وجہ سے اس کی نماز نہ ہوتی تھی۔ اس روایت کی رو سے بھی رکوع، سجدے، قومے اور جلسے میں اطمینان ضروری ہے۔ ائمہ احناف میں سے امام ابو یوسف رحمہ اللہ اس کے قائل ہیں، دیگر احناف اطمینان کو ضروری نہیں سمجھتے جبکہ حدیث ان کے موقف کا رد کرتی ہے۔ (۳) اس حدیث کے دوسرے طریق میں سورۂ فاتحہ پڑھنے کا صریح حکم ہے، لہٰذا یہاں قرآن مجید سے مراد سورۂ فاتحہ ہی ہے۔ دیکھیے: (سنن ابی داود، الصلاۃ، حدیث: ۸۵۹) (۴) ’’نماز میں کمی کرے گا۔‘‘ یہ الفاظ، ابتدائی الفاظ ’’تو نے نماز نہیں پڑھی۔‘‘ کے مقابلے میں نرم ہیں مگر اکثر چیزوں کا ترک نماز نہ ہونے کو مستلزم ہے۔ مزید فوائد و مسائل کے لیے دیکھیے: (حدیث: ۸۸۵)"}],[1054,"انس رضی اللہ عنہ کہتے ہیں کہ نبی اکرم صلی اللہ علیہ وسلم نے فرمایا: \"جب تم رکوع اور سجدہ کرو تو انہیں اچھی طرح کرو\"۔","الألباني: صحيح",{"u2":"حضرت انس رضی اللہ عنہ سے روایت ہے، نبی صلی اللہ علیہ وسلم نے فرمایا: ’’جب تم رکوع اور سجدہ کرو تو رکوع اور سجود مکمل کیا کرو۔‘‘","f2":"(۱) مکمل کرنے سے مراد اعتدال، اطمینان اور تسبیحات و اذکار کا پڑھنا ہے جن کی تفصیل سابقہ احادیث میں گزر چکی ہے۔ (۲) امام کو گاہے گاہے نماز کے احکام کی تلقین کرتے رہنا چاہیے، خصوصاً جب مقتدی ارکان نماز صحیح طریقے سے ادا نہ کر رہے ہوں۔"}],[1055,"وائل بن حجر رضی اللہ عنہ کہتے ہیں کہ میں نے رسول اللہ صلی اللہ علیہ وسلم کے پیچھے نماز پڑھی، تو دیکھا کہ جب آپ نماز شروع کرتے تو رفع یدین کرتے، اور جب رکوع کرتے، اور «سمع اللہ لمن حمده» کہتے تو بھی اسی طرح کرتے۔ قیس بن سلیم (راوی حدیث) نے دونوں کانوں تک اشارہ کر کے دکھایا۔","الألباني: صحيح الإسناد",{"u2":"حضرت وائل بن حجر رضی اللہ عنہ بیان کرتے ہیں کہ میں نے رسول اللہ صلی اللہ علیہ وسلم کے پیچھے نماز پڑھی تو دیکھا کہ آپ جب نماز شروع فرماتے یا رکوع کو جاتے یا سمع اللہ لمن حمدہ کہتے تو اس طرح رفع الیدین کرتے۔ (راویٔ حدیث) قیس نے کانوں کی طرف اشارہ کیا، یعنی کانوں تک۔","f2":"رفع الیدین کی بحث احادیث ۱۰۲۵، ۱۰۲۶، ۱۰۲۷ میں تفصیلاً گزر چکی ہے۔ یہ قطعاً سنت ہے۔"}],[1056,"مالک بن حویرث رضی اللہ عنہ سے روایت ہے کہ انہوں نے رسول اللہ صلی اللہ علیہ وسلم کو دیکھا کہ آپ رکوع کرتے، اور رکوع سے سر اٹھاتے، تو اپنے دونوں ہاتھ اٹھاتے یہاں تک کہ انہیں اپنے کانوں کی لو کے برابر کر لیتے۔","الألباني: صحيح",{"u2":"حضرت مالک بن حویرث رضی اللہ عنہ سے روایت ہے، انھوں نے نبی صلی اللہ علیہ وسلم کو دیکھا آپ جب رکوع فرماتے یا رکوع سے سر اٹھاتے تو اپنے دونوں ہاتھ اٹھاتے حتی کہ انھیں کانوں کے کناروں کے برابر لے جاتے۔"}],[1057,"عبداللہ بن عمر رضی اللہ عنہم سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم جب نماز شروع کرتے تو اپنے ہاتھ اپنے کندھوں کے بالمقابل اٹھاتے، اور جب رکوع سے سر اٹھاتے تو بھی اسی طرح کرتے، اور جب «سمع اللہ لمن حمده» کہتے تو «ربنا لك الحمد» کہتے، اور دونوں سجدوں کے درمیان اپنے ہاتھ نہیں اٹھاتے تھے۔","الألباني: صحيح",{"u2":"حضرت ابن عمر رضی اللہ عنہما سے مروی ہے کہ رسول اللہ صلی اللہ علیہ وسلم جب نماز شروع فرماتے تو اپنے دونوں ہاتھ اپنے کندھوں کے برابر اٹھاتے اور جب رکوع سے سر اٹھاتے تو پھر اسی طرح کرتے اور جب [سمع اللہ لمن حمدہ] کتے تو [ربنا لک الحمد] کہتے۔ اور آپ سجدوں کے درمیان (سجدے سے اٹھتے اور سجدے کو جاتے وقت) رفع الیدین نہیں کرتے تھے۔"}],[1058,"عبداللہ بن مسعود رضی اللہ عنہ کہتے ہیں کہ کیا میں تمہیں رسول اللہ صلی اللہ علیہ وسلم کی نماز نہ پڑھاؤں؟ چنانچہ انہوں نے ہمیں نماز پڑھائی، تو انہوں نے صرف ایک بار رفع یدین کیا۔","الألباني: صحيح",{"u2":"حضرت علقمہ سے منقول ہے کہ حضرت عبداللہ بن مسعود رضی اللہ عنہ نے فرمایا: کیا میں تمھیں رسول اللہ صلی اللہ علیہ وسلم کی نماز جیسی نماز نہ پڑھاؤں؟ تو انھوں نے نماز پڑھی اور ایک دفعہ سے زائد رفع الیدین نہ کیا۔","f2":"یہ روایت ضعیف ہے۔ مزید دیکھیے، حدیث: ۱۰۲۷۔"}],[1059,"عبداللہ بن عمر رضی اللہ عنہم سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم جب نماز شروع کرتے تو اپنے دونوں ہاتھ اپنے کندھوں کے بالمقابل اٹھاتے، اور جب رکوع کے لیے اللہ اکبر کہتے، اور جب رکوع سے اپنا سر اٹھاتے تب بھی اسی طرح اپنے دونوں ہاتھ اٹھاتے، اور «سمع اللہ لمن حمده ربنا ولك الحمد»کہتے، اور سجدے میں رفع یدین نہیں کرتے تھے۔","الألباني: صحيح",{"u2":"حضرت ابن عمر رضی اللہ عنہما سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم جب نماز شروع فرماتے تو اپنے کندھوں کے برابر ہاتھ اٹھاتے اور جب رکوع کی تکبیر کہتے اور جب رکوع سے اپنا سر اٹھاتے تو پھر انھیں اسی طرح اٹھاتے اور کہتے: [سمع اللہ لمن حمدہ، ربنا ولک الحمد] اور آپ سجدے میں رفع الیدین نہیں کرتے تھے۔"}],[1060,"ابوہریرہ رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم جب رکوع سے اپنا سر اٹھاتے تو «اللہم ربنا ولك الحمد» کہتے۔","الألباني: صحيح",{"u2":"حضرت ابوہریرہ رضی اللہ عنہ سے روایت ہے کہ نبی صلی اللہ علیہ وسلم جب رکوع سے سر اٹھاتے تو [اللھم! ربنا ولک الحمد] کہتے۔","f2":"معلوم ہوا کہ امام رکوع سے اٹھے تو [سمع اللہ لمن حمدہ] بھی کہے اور [ربنا ولک الحمد] بھی۔ اسی طرح اکیلا نماز پڑھنے والا بھی دونوں جملے کہے۔ امام مالک رحمہ اللہ امام کے لیے [ربنا ولک الحمد] کہنے کے ائل نہیں۔ ان کا خیال ہے کہ یہ [سمع اللہ لمن حمدہ] کا جواب ہے، لہٰذا یہ جملہ صرف مقتدی کہیں گے اور امام صرف [سمع اللہ لمن حمدہ] کہے گا مگر یہ صریح احادیث کے خلاف ہے۔ اس قسم کی مناسبات وہاں تلاش کی جاتی ہیں جہاں نص (صریح قرآن و حدیث) مذکور نہ ہو۔"}],[1061,"انس رضی اللہ عنہ سے روایت ہے کہ نبی اکرم صلی اللہ علیہ وسلم گھوڑے سے اپنے داہنے پہلو پر گر پڑے، تو لوگ آپ کی عیادت کرنے آپ کے پاس آئے کہ (اسی دوران) نماز کا وقت ہو گیا، (تو آپ نے انہیں نماز پڑھائی) جب آپ نے نماز پوری کر لی تو فرمایا: \"امام بنایا ہی اس لیے گیا ہے کہ اس کی اقتداء کی جائے، تو جب وہ رکوع کرے تو تم بھی رکوع کرو، اور جب وہ سر اٹھائے تو تم بھی سر اٹھاؤ، اور جب وہ «سمع اللہ لمن حمده» کہے، تو تم «ربنا ولك الحمد» \" کہو ۱؎۔\n§وضاحت\n۱؎: اس حدیث میں اس بات کی دلیل نہیں کہ مقتدی اور امام دونوں «سمع اللہ لمن حمدہ» نہ کہیں جیسا کہ اس میں اس بات کی دلیل نہیں کہ امام اور مقتدی دونوں «سمع اللہ لمن حمدہ» کہیں کیونکہ یہ حدیث اس بات کے بیان کے لیے نہیں آئی ہے کہ اس موقع پر امام یا مقتدی کیا کہیں بلکہ اس حدیث کا مقصد صرف یہ بتانا ہے کہ مقتدی «ربنا لک الحمد» امام کی «سمع اللہ لمن حمدہ» کے بعد پڑھے، اس بات کی تائید اس سے ہوتی ہے کہ نبی اکرم صلی اللہ علیہ وسلم امام ہونے کے باوجود «ربنا لک الحمد» کہتے تھے، اسی طرح آپ صلی اللہ علیہ وسلم کی حدیث «صلّوا کما رأیتمونی اصلي» کا عموم بھی اس بات کا متقاضی ہے کہ مقتدی بھی امام کی طرح «سمع اللہ لمن حمدہ» کہے۔","الألباني: صحيح",{"u2":"حضرت انس رضی اللہ عنہ سے مروی ہے، نبی صلی اللہ علیہ وسلم گھوڑے سے دائیں پہلو پر گر پڑے تو صحابہ بیمار پرسی کے لیے آپ کی خدمت میں حاضر ہوئے۔ نماز کا وقت ہوگیا۔ جب آپ نے نماز پوری کرلی تو فرمایا: ’’امام اس لیے ہوتا ہے کہ اس کی اقتدا کی جائے، لہٰذا جب وہ رکوع کرے تو تم بھی رکوع کرو اور جب وہ سر اٹھائے تو تم بھی سر اٹھاؤ اور جب [سمع اللہ لمن حمدہ] کہے تو تم [ربنا ولک الحمد] کہو۔‘‘","f2":"(۱) جمہور اہل علم نے اس سے استدلال کیا ہے کہ مقتدی صرف [ربنا ولک الحمد] کہے۔ امام شافعی کا خیال ہے کہ مقتدی کو [سمع اللہ لمن حمدہ] بھی کہنا چاہیے تاکہ امام کی اقتدا ہو جائے، پھر [ربنا ولک الحمد] کہے۔ بظاہر یہی موقف راجح ہے کیونکہ مذکورہ حدیث میں [سمع اللہ لمن حمدہ] پڑھنے کی نفی نہیں۔ بلکہ اس میں تو [ربنا ولک الحمد] کے محل کا تعین ہے۔ مقصد یہ ہے کہ مقتدی امام کے سمع اللہ کے ساتھ یا اس سے قبل یہ کلمات نہ کہے بلکہ اس کے بعد کہے۔ اب رہا یہ مسئلہ کہ آیا مقتدی بھی [سمع اللہ لمن حمدہ] کے گا یا نہیں؟ اس حوالے سے اس حدیث میں کوئی صراحت نہیں بلکہ مقتدی کے لیے ان کلمات کی مشروعیت دوسری احادیث کے عموم سے اخذ ہوتی ہے۔ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا ہے [صلوا کما رایتمونی اصلی] ’’نماز اسی طریقے سے پڑھو جیسے تم نے مجھے پڑھتے ہوئے دیکھا ہے، نیز آپ صلی اللہ علیہ وسلم نے ’’مسیئی الصلاۃ‘‘ (نماز کو جلدی جلدی اور غلط طریقے سے پڑھنے والے) سے مخاطب ہوکر فرمایا: [انہ لا تتم صلاۃ لاحد من الناس حتی یتوضا ……… ثم یقول: سمع اللہ لمن حمدہ حتی یستوی قائما……] ’’حقیقت یہ ہے کہ لوگوں میں سے کسی ایک کی بھی نماز اس وقت تک ممکن نہیں ہوتی جب تک کہ وہ اچھی طرح وضو نہ کرے……، پھر سمع اللہ لمن حمدہ نہ کہے، یہاں تک کہ برابر اور اعتدال کے ساتھ کھڑا ہو جائے………‘‘ (سنن ابی داود، الصلاۃ، حدیث: ۸۵۷، و صفۃ الصلاۃ، ص:۱۱۸) اس حدیث کی رو سے امام اور مقتدی وغیرہ سب ا کلمات کے کہنے کے مکلف ہیں۔ واللہ أعلم۔ (۲) [ربنا ولک الحمد] بعض روایات میں بغیر واؤ کے آیا ہے۔ اور بعض میں ’’اللھم‘‘ اور ’’واو‘‘ کے اضافے کے ساتھ بھی، یعنی [ربنا لک الحمد، ربنا ولک الحمد] اور [اللھم ربنا و لک الحمد] تینوں کلمات میں سے کوئی بھی کہے جا سکتے ہیں سب جائز ہے بہتر ہے کہ ادائیگی میں تنوع ہو۔ مزید دیکھیے: (صفۃ صلاۃ، النبی، ص:۱۱۸ للالبانی)"}],[1062,"رفاعہ بن رافع رضی اللہ عنہ کہتے ہیں کہ ایک دن ہم رسول اللہ صلی اللہ علیہ وسلم کے پیچھے نماز پڑھ رہے تھے، جب آپ نے رکوع سے اپنا سر اٹھایا تو «سمع اللہ لمن حمده» کہا، تو آپ کے پیچھے ایک شخص نے «ربنا ولك الحمد حمدا كثيرا طيبا مباركا فيه» \"اللہ کے لیے بہت زیادہ تعریفیں ہیں جو پاکیزہ و بابرکت ہیں\" کہا، جب رسول اللہ صلی اللہ علیہ وسلم نے سلام پھیرا تو آپ صلی اللہ علیہ وسلم نے پوچھا: \"ابھی ابھی (نماز میں) کون بول رہا تھا؟ \"تو اس شخص نے عرض کیا: میں تھا اللہ کے رسول! تو رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"میں نے تیس سے زائد فرشتوں کو دیکھا ان میں سے ہر ایک سبقت لے جانے کی کوشش کر رہا تھا کہ اسے کون پہلے لکھے\"۔","الألباني: صحيح",{"u2":"حضرت رافعہ بن رافع رضی اللہ عنہ سے روایت ہے، فرماتے ہیں: ہم ایک دن رسول اللہ صلی اللہ علیہ وسلمکے پیچھے نماز پڑھ رہے تھے۔ جب آپ نے رکوع سے سر اٹھایا تو کہا [سمع اللہ لمن حمدہ] آپ کے مقتدیوں میں سے ایک آدمی نے (ذرا بلند آواز سے) کہا: [ربنا ولک الحمد حمدا کثیرا طیبا مبارکا فیہ] ’’اے ہمارے رب! تیرے ہی لیے سب تعریفیں ہیں۔ بہت زیادہ، پاکیزہ اور بابرکت تعریفیں۔‘‘ جب اللہ کے رسول صلی اللہ علیہ وسلم نماز سے فارغ ہوئے تو فرمایا: ’’کس شخص نے ابھی کچھ کلام کیا تھا؟‘‘ اس آدمی نے کہا: اے اللہ کے رسول! میں نے۔ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’اللہ کی قسم! میں نے تیس (۳۰) سے زائد فرشتوں کو دیکھا کہ وہ ان کلمات کی طرف ایک دوسرے سے سبقت کر رہے تھے کہ کون انھیں پہلے لکھے۔‘‘ (اور اللہ تعالیٰ کے حضور پیش کرے۔)","f2":"(۱) ان روایات میں مقتدی کے لیے [سمع اللہ لمن حمدہ] کہنے کی نفی ہے نہ ذکر و اثبات، اس لیے دیگر مفصل روایات کی طرف رجوع لازمی ہے، جیسا کہ حدیث: ۱۰۶۳ کے فوائد کے تحت گزر چکا ہے۔ (۲) بعض حضرات نے اس روایت سے ان کلمات کو بلند آواز سے کہنے پر استدلال کیا ہے مگر حیرانی ہے کہ انھوں نے رسول اللہ صلی اللہ علیہ وسلم اور جلیل القدر صحابہ کے طرز عمل کو نظر انداز کر دیا جو آہستہ پڑھتے تھے اور ایک صحابی کے اتفاقی فعل سے استدلال کر لیا، حالانکہ قرین قیاس یہ ہے کہ یہ فعل اس صحابی سے بے اختیار یا اتفاقاً صادر ہوا تھا۔ اگر یہ عام معمول ہوتا تو رسول اللہ صلی اللہ علیہ وسلم استفسار کیوں فرماتے؟ لٰذا یہ کلمات آہستہ ہی کہنے چاہئیں۔"}],[1063,"ابوہریرہ رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"جب امام «سمع اللہ لمن حمده» کہے، تو تم «ربنا ولك الحمد» کہو کیونکہ جس کا کہنا فرشتوں کے کہنے کے موافق ہو گا، اس کے پچھلے تمام گناہ بخش دیئے جائیں گے\"۔","الألباني: صحيح",{"u2":"حضرت ابوہریرہ رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلمنے فرمایا: ’’جب امام [سمع اللہ لمن حمدہ] کہے تو تم [ربنا ولک الحمد] کہو کیونکہ جس آدمی کا یہ قول فرشتوں کے قول کے ساتھ مل گیا، اس کے پہلے سب گناہ معاف کر دیے جاتے ہیں۔‘‘","f2":"معلوم ہوتا ہے کہ انسان پر مقرر فرشتے بھی نماز میں اس کے ساتھ شریک ہوتے ہیں، خصوصاً امام کو جواب دیتے ہیں، مثلاً: امام کی فاتحہ پر آمین کہنا اور [سمع اللہ لمن حمدہ] کے جواب میں [ربنا ولک الحمد] کہنا وغیرہ، لہٰذا مقتدی بھی امام کو جواب دے اور فوراً دے (جیسا کہ جواب کا دستور ہے)۔ اس طرح وہ فرشتوں کی موافقت کی فضیلت حاصل کرے گا۔ اور اللہ تعالیٰ کے نیک بندوں کی معیت کوئی معمولی بات نہیں اور پھر معصوم فرشتوں کی معیت۔ اللہ! اللہ!"}],[1064,"ابوموسی اشعری رضی اللہ عنہ کہتے ہیں کہ نبی اکرم صلی اللہ علیہ وسلم نے ہمیں خطبہ دیا، اور ہمیں ہمارے طریقے بتائے، اور ہماری نماز سکھائی، آپ صلی اللہ علیہ وسلم نے فرمایا: \"جب تم نماز پڑھو تو اپنی صفیں سیدھی کرو، پھر تم میں سے کوئی ایک امامت کرے، اور جب امام اللہ اکبر کہے تو تم بھی اللہ اکبر کہو، اور جب وہ «غير المغضوب عليهم ولا الضالين» کہے، تو تم آمین کہو، اللہ تمہاری دعا قبول کرے گا، اور جب وہ اللہ اکبر کہے، اور رکوع کرے تو تم بھی اللہ اکبر کہو اور رکوع کرو، امام تم سے پہلے رکوع کرے گا، اور تم سے پہلے رکوع سے سر بھی اٹھائے گا، نبی اکرم صلی اللہ علیہ وسلم نے فرمایا: \"تو ادھر کی کمی ادھر پوری ہو جائے گی\"، اور جب وہ«سمع اللہ لمن حمده» کہے، تو تم «اللہم ربنا ولك الحمد» کہو، اللہ تعالی تمہاری پکار سن لے گا ؛ کیونکہ اللہ نے اپنے بنی کی زبان سے فرمایا ہے: اللہ نے اس کی سن لی جس نے اس کی حمد بیان کی، تو جب وہ اللہ اکبر کہے اور سجدہ کرے تو تم بھی اللہ اکبر کہو اور سجدہ کرو، امام تم سے پہلے سجدہ کرے گا، اور تم سے پہلے سجدہ سے سر بھی اٹھائے گا، نبی کریم صلی اللہ علیہ وسلم نے فرمایا: \"تو ادھر کی کمی ادھر پوری ہو جائے گی، جب وہ قعدے میں ہو تو تم میں سے ہر ایک کی پہلی دعا یہ ہو:«التحيات الطيبات الصلوات لله سلام عليك أيها النبي ورحمة اللہ وبركاته سلام علينا وعلى عباد اللہ الصالحين أشهد أن لا إله إلا اللہ وأشهد أن محمدا عبده ورسوله» \"آداب بندگیاں، پاکیزہ خیراتیں، اور صلاتیں اللہ ہی کے لیے ہیں، اے رسول! آپ پر سلام اور اللہ کی رحمت اور اس کی برکتیں نازل ہوں، اور سلام ہو ہم پر اور اللہ کے تمام نیک و صالح بندوں پر، میں گواہی دیتا ہوں کہ اللہ کے سوا کوئی معبود برحق نہیں، اور میں گواہی دیتا ہوں کہ محمد صلی اللہ علیہ وسلم اس کے بندے اور رسول ہیں\" یہ سات کلمے ۱؎ ہیں اور یہ نماز کا سلام ہے\"۔\n§وضاحت\n۱؎: پہلا «التحیات» ہے، دوسرا «الطیبات»، تیسرا «الصلوات»، چوتھا «سلام علیک»، پانچواں «سلام علینا»، چھٹا «أشہد أن لا إلہ إلا اللہ»، اور ساتواں «أشہد أن محمداً عبدہ ورسولہ» ہے۔","الألباني: صحيح م دون قوله سبع",{"u2":"حضرت ابوموسیٰ اشعری رضی اللہ عنہ بیان کرتے ہیں کہ اللہ کے نبی صلی اللہ علیہ وسلم نے ہمیں خطبہ دیا اور ہمارے لیے طریقۂ زندگی بیان فرمایا اور ہمیں نماز سکھلائی، چنانچہ آپ نے فرمایا: ’’جب تم نماز پڑھو تو اپنی صفیں سیدھی کرو۔ پھر تم میں سے ایک شخص جماعت کروائے۔ پھر جب امام اللہ اکبر کہے تو تم بھی تکبیر کہو اور جب وہ (غیر المغضوب علیھم ولا الضالین) کہے تو تم آمین کہو۔ اللہ تعالیٰ (تمھاری دعا) قبول فرمائے گا۔ اور جب وہ اللہ اکبر کہہ کر رکوع کرے تو تم بھی اللہ اکبر کہہ کر رکوع کرو۔ امام تم سے پہلے رکوع کو جاتا ہے اور پہلے سر اٹھاتا ہے۔‘‘ نبی صلی اللہ علیہ وسلم نے فرمایا: ’’تو وہ سبقت اس تاخیر کے بدلے میں ہے۔ اور جب وہ [سمع اللہ لمن حمدہ] کے تو تم [اللھم! ربنا ولک الحمد] کہو۔ اللہ تعالیٰ تمھاری (حمد کو) ضرور سنے گا کیونکہ اللہ تعالیٰ نے اپنے نبی صلی اللہ علیہ وسلم کی زبانی فرمایا ہے کہ اللہ تعالیٰ ہر اس بندے کی بات سنتا ہے جو اس کی حمد کرتا ہے۔ پھر جب وہ اللہ اکبر کہہ کر سجدہ کرے تو تم بھی اللہ اکبر کہہ کر سجدہ کرو کیونکہ امام تم سے پہلے سجدے کو جاتا ہے اور پہلے سر اٹھاتا ہے۔‘‘ نبی صلی اللہ علیہ وسلم نے فرمایا: ’’تو یہ تاخیر اس سبقت کے بدلے میں ہے۔ اور جب وہ تشہد کے لیے بیٹھے تو تم میں سے ہر شخص کی پہلی بات یہ ہونی چاہیے: [التحیات الطیبات الصلوات للہ، سلام علیک ایھا النبی! و رحمۃ اللہ و برکاتہ، سلام علینا و علی عباد اللہ الصالحین، اشھد ان لا الہ الا اللہ و اشھدان محمدا عبدہ و رسولہ] ’’تمام اچھے آداب اور تمام عبادات صرف اللہ کے لیے ہیں۔ اے نبی! آپ پر اللہ تعالیٰ کی سلامتی، رحمتیں اور برکتیں ہوں۔ ہم پر اور اللہ کے تمام نیک بندوں پر بھی اللہ کی سلامتی ہو۔ میں گواہی دیتا ہوں کہ اللہ تعالیٰ کے سوا کوئی سچا معبود نہیں اور میں گواہی دیتا ہوں کہ محمد (صلی اللہ علیہ وسلم) اس کے بندے اور رسول ہیں۔‘‘ یہ سات جملے ہیں اور یہ نماز کے سلام و آداب ہیں۔‘‘","f2":"(۱) ’’آمین کہو‘‘ احناف کہتے ہیں آہستہ کہنی چاہیے کیونکہ یہ دعا ہے اور دعا خفیہ ہونی چاہیے۔ مگر تعجب ہے کہ اصل دعا سورۂ فاتحہ کا آخری حصہ ہے (آمین تو تتمہ ہے) وہ بلند آواز سے پڑھی جاتی ہے مگر تتمۂ دعا آہستہ ہونا چاہیے۔ یہ نکتہ سمجھ میں نہیں آسکا۔ ظاہر بات ہے کہ دعا بلند آواز سے ہو تو آمین بھی بلند آواز سے ہونی چاہیے، اسی لیے جب نماز کے علاوہ دعا کی جاتی ہے تو آمین اونچی کہی جاتی ہے بلکہ زیادہ اونچی کہی جاتی ہے۔ کیا اس وقت وہ دعا نہیں ہوتی؟ صرف نماز ہی میں دعا ہوتی ہے؟ (۲) ’’بدلے میں ہے‘‘ یعنی وہ تم سے پہلے رکوع میں جاتا ہے، اٹھتا بھی اتنی دیر پہلے ہے اور تم جتنی دیر بعد رکوع میں جاتے ہو، اٹھتے بھی اتنی دیر بعد میں ہو، لہٰذا تمھارا رکوع اس کے رکوع کے برابر ہے۔ (۳) [التحیات الصلوات الطیبات] تحیۃ کے لغیو معنی ادب و سلام ہیں۔ کسی کو زندگی کی دعا دیتے وقت کہتے ہیں! [حیاک اللہ] ’’اللہ آپ کو تادیر زندہ و سلامت رکھے۔‘‘ علاوہ ازیں اس کے معنی عظمت و بزرگی، بادشاہت، دوام و بقا اور زندگی بھی کیے گئے ہیں، نیز [التحیات] سے قولی عبادات بھی مراد لی گئی ہیں۔ [الصلوات] صلاۃ کے معنی دعا یا نماز ہیں۔ اس سے یہاں مراد نماز پنجگانہ یا تمام نمازیں یا عبادات فعلیہ ہیں۔ [الطیبات] ہر اچھی بات اور عمدہ کلام کو کہتے ہیں، مثلاً: اللہ کی حمد و ثنا، ذکر الٰہی اور اقوال صالحہ وغیرہ۔ یہاں عام اعمال صالحہ اور مالی عبادات بھی مراد ہوسکتی ہیں۔ واللہ أعلم۔ (۴) آپ نے تشہد سے آگے ذکر نہیں فرمایا؎ اس سے استدلال کیا گیا ہے کہ بس اتنا ہی فرض یا واجب ہے۔ اس سے زائد درود شریف اور دعا واجب نہیں مگر اللہ تعالیٰ نے قرآن مجید میں صلاۃ و سلام کو اکٹھا ذکر کیا ہے۔ مذکورہ تشہد میں سلام تو ہے، صلاۃ نہیں۔ مساوی حیثیت تقاضا کرتی ہے کہ اس کے بعد صلاۃ (درود) بھی واجب ہے۔ نبیٔ اکرم صلی اللہ علیہ وسلم کی امت سے محبت و شفقت اور شفاعت کبریٰ متقاضی ہیں کہ اور نہیں تو کم از کم اپنی نماز ہی میں امت رسولِ رؤف و رحیم کا حق درود کی صورت میں ادا کرے۔ صلی اللہ علیہ وسلم۔ امام شافعی رحمہ اللہ کا یہی مسلک ہے۔ (۵) ’’سات کلمات‘‘ اس طرح ہیں: (۱) التحیات (۲) الصلوات (۳) الطیبات (۳) سلام علی النبی (۵) سلام علی الصالحین (۶) شھادت توحید (۷) شہادت رسالت۔"}],[1065,"براء بن عازب رضی اللہ عنہم سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم کا رکوع کرنا، اور رکوع سے سر اٹھانا اور سجدہ کرنا، اور دونوں سجدوں کے درمیان ٹھہرنا، تقریباً برابر برابر ہوتا تھا ۱؎۔\n§وضاحت\n۱؎: اس سے ثابت ہوتا ہے کہ ان ارکان کو نبی اکرم صلی اللہ علیہ وسلم کامل اعتدال :(اطمینان ) کے ساتھ ادا کیا کرتے تھے، صحیحین کی انس رضی اللہ عنہ کی روایت میں تو یہاں تک ہے کہ نبی اکرم صلی اللہ علیہ وسلم رکوع کے بعد یا دونوں سجدوں کے درمیان اتنا ٹھہرتے کہ کہنے والا یہ تک کہتا :(یعنی سوچتا ) کہ شاید آپ اگلے رکن میں جانا بھول گئے ہیں۔","الألباني: صحيح",{"u2":"حضرت براء بن عازب رضی اللہ عنہما سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم کا رکوع، رکوع سے سر اٹھانے کے بعد قومہ، آپ کا سجدہ اور دو سجدوں کے درمیان بیٹھنا تقریباً برابر ہوتا تھا۔","f2":"یہ حدیث ان حضرات کے لیے لمحۂ فکریہ ہے جو رکوع کے بعد قومہ (کھڑا ہونا) اور دو سجدوں کے درمیان جلسہ (بیٹھنا)میں ٹھہرنا اور دعائیں پڑھنا مکروہ سمجھتے ہیں۔ نماز تو وہی ہے جو سنت رسول اللہ صلی اللہ علیہ وسلم کے ساتھ زیادہ سے زیادہ مطابقت رکھتی ہو، نہ کہ فقہی موشگافیوں سے نماز کا سکون اور حسن ہی زائل ہو جائے اور نماز اٹھک بیٹھک اور چونچیں مارنے کی شبیہ بن جائے۔ اعاذنا اللہ منہ۔"}],[1066,"عبداللہ بن عباس رضی اللہ عنہم سے روایت ہے کہ نبی اکرم صلی اللہ علیہ وسلم جب «سمع اللہ لمن حمده» کہتے، تو «اللہم ربنا لك الحمد ملء السموات وملء الأرض وملء ما شئت من شىء بعد» \"اے اللہ! تیری تعریف ہے، آسمانوں بھر، زمین بھر اور اس کے بعد تو جس چیز بھر چاہے\"کہتے۔","الألباني: صحيح",{"u2":"حضرت ابن عباس رضی اللہ عنہما سے مروی ہے کہ نبی صلی اللہ علیہ وسلم جب (رکوع سے اٹھتے وقت) [سمع اللہ لمن حمدہ] کہتے تو یوں فرماتے: [اللھم! ربنا لک الحمد ……… من شیی بعد] ’’اے اللہ! اے ہمارے رب! تیرے ہی لیے تعریف ہے، اس قدر کہ آسمان و زمین بھر جائیں اور ہر وہ چیز بھر جائے جو تو ان کے بعد چاہے۔‘‘","f2":"(۱) یعنی وہ تعریف اگر مجسم ہو جائے تو سب کچھ سے بڑھ جائے۔ ممکن ہے ثواب کی طرف اشارہ ہو۔ (۲) رکوع کے بعد قومے میں یہ دعا پڑھنا مسنون ہے۔ (۳) رکوع کے بعد اعتدال و اطمینان ضروری ہے کیونکہ اعتدال کے بغیر اس دعا کا قومے میں پڑھنا ممکن نہیں۔ (۴) ہر نمازی کے لیے یہ دعا مستحب ہے، خواہ وہ امام ہو یا مقتدی یا منفرد کیونکہ نبیٔ اکرم صلی اللہ علیہ وسلم نے یہ دعا پڑھی ہے اور آپ صلی اللہ علیہ وسلمنے صحابۂ کرام رضی اللہ عنھم کو حکم دیا کہ ’’نماز اس طرح پڑھو جس طرح تم نے مجھے پڑھتے دیکھا ہے۔‘‘ (صحیح البخاری، الاذان، حدیث: ۶۳۱) آپ کا یہ فرمان پوری امت کے لیے ہے۔ (۵) ہر نماز میں یہ دعا پڑھی جا سکتی ہے، خواہ وہ فرض ہو یا نفل۔ بعض علماء اسے نفلی نماز کے ساتھ خاص کرتے ہیں لیکن تخصیص کی کوئی دلیل نہیں۔ واللہ أعلم۔"}],[1067,"عبداللہ بن عباس رضی اللہ عنہم سے روایت ہے کہ نبی اکرم صلی اللہ علیہ وسلم جب رکوع کے بعد سجدے کا ارادہ کرتے تو «اللہم ربنا ولك الحمد ملء السموات وملء الأرض وملء ما شئت من شىء بعد» \"اے ہمارے رب! تیری تعریف ہے، تیرا شکر ہے آسمان و زمین بھر اور اس کے بعد تو جس چیز بھر چاہے\" کہتے۔","الألباني: صحيح",{"u2":"حضرت ابن عباس رضی اللہ عنہما سے منقول ہے کہ نبی صلی اللہ علیہ وسلم جب رکوع کے بعد سجدہ کرنے کا ارادہ فرماتے تو یوں کہتے: [اللھم! ربنا ولک الحمد ……… من شی بعد] ’’اے اللہ! اے ہمارے پالنے والے! تیرے ہی لیے ہے سب تعریف جو آسمانوں اور زمین کو بھرنے کے برابر ہو اور ہر اس چیز کو بھرنے کے برابر ہو جو تو ان کے بعد چاہے۔‘‘"}],[1068,"ابو سعید خدری رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم جب «سمع اللہ لمن حمده» کہتے، تو «ربنا لك الحمد ملء السموات وملء الأرض وملء ما شئت من شىء بعد أهل الثناء والمجد خير ما قال العبد وكلنا لك عبد لا مانع لما أعطيت ولا ينفع ذا الجد منك الجد» \"اے اللہ، ہمارے رب! تیرا شکر ہے آسمان و زمین بھر، اور اس کے بعد تو جس چیز بھر چاہے، اے لائق تعریف و لائق مجد و شرف! بہتر ہے جو بندے نے کہا، اور ہم سب تیرے بندے ہیں، کوئی روکنے والا نہیں جسے تو دیدے، تیرے مقابلے میں مالداروں کی مالداری کچھ بھی فائدہ نہیں پہنچائے گی\"کہتے۔","الألباني: صحيح",{"u2":"حضرت ابو سعید خدری رضی اللہ عنہ سے روایت ہے، رسول اللہ صلی اللہ علیہ وسلم جب [سمع اللہ لمن حمیدہ] کہتے تو یوں فرماتے: [ربنا لک الحمد ……… منک الحد] ’’اے ہمارے رب! تیرے ہی لیے تعریف ہے آسمانوں اور زمینوں کے بھرنے کے بقدر اور ہر اس چیز کے بھرنے کے بقدر جو تو ان کے بعد چاہے۔ اے بزرگی اور ثنا کی لائق! بہترین بات جو کسی بندے نے کہی، اور ہم سب تیرے بندے ہیں، یہ ہے کہ جو چیز تو دینے کا فیصلہ کرلے کوئی اسے روکنے والا نہیں اور کسی مال والے کو اس کا مال تیرے نزدیک نفع نہیں دے سکتا۔‘‘"}],[1069,"حذیفہ رضی اللہ عنہ سے روایت ہے کہ ایک رات انہوں نے رسول اللہ صلی اللہ علیہ وسلم کے ساتھ نماز پڑھی، جب آپ نے تکبیر کہی تو انہوں نے آپ کو کہتے سنا:«اللہ أكبر ذا الجبروت والملكوت والكبرياء والعظمة» \"اللہ سب سے بڑا صاحب قدرت و سطوت اور صاحب بزرگی و عظمت ہے\"، اور آپ رکوع میں «سبحان ربي العظيم» کہتے، اور جب رکوع سے اپنا سر اٹھاتے تو: «لربي الحمد لربي الحمد»، \"شکر میرے رب کے لیے، شکر میرے رب کے لیے\" کہتے، اور سجدے میں «سبحان ربي الأعلى» کہتے، اور دونوں سجدوں کے درمیان «رب اغفر لي رب اغفر لي» \"اے میرے رب! میری مغفرت فرما، اے میرے رب! میری مغفرت فرما\" کہتے، اور آپ کا قیام کرنا، رکوع کرنا، اور رکوع سے سر اٹھانا، اور آپ کا سجدہ کرنا، اور دونوں سجدوں کے درمیان ٹھہرنا، تقریباً سب برابر برابر ہوتا۔","الألباني: صحيح",{"u2":"حضرت حذیفہ رضی اللہ عنہ سے مروی ہے کہ میں نے ایک رات رسول اللہ صلی اللہ علیہ وسلم کے ساتھ نماز پڑھی۔ جب آپ نے نماز شروع فرمائی تو میں نے آ پکو کہتے سنا: [اللہ اکبر ذالحبروت و الملکوت والکبریاء و العظمۃ] ’’اللہ سب سے بڑا ہے، اے عظیم الشان غلبے اور بادشاہی والے! (بے انتہا) بزرگی (بڑائی) اور عظمت کے مالک!۔‘‘ اور آپ اپنے رکوع میں فرماتے تھے: [سبحان ربی العظیم] ’’پاک ہے میرا عظمت والا رب۔‘‘ اور جب آپ نے رکوع سے سر اٹھایا تو فرمایا: [لربی الحمد لربی الحمد] ’’میرے رب ہی کے لیے ہے سب تعریف۔ میرے رب ہی کے لیے ہے سب تعریف۔‘‘ اور اپنے سجدے میں فرماتے: [سبحان ربی الاعلی] ’’پاک ہے میرا بزرگ و برتر رب۔‘‘ اور دو سجدوں کے درمیان فرماتے: [رب اغفرلی رب اغفرلی] ’’اے میرے رب! مجھے معاف فرما۔ اےمیرے رب! مجھے معاف فرما۔‘‘ اور آپ کا قیام، رکوع، رکوع سے سر اٹھانے کے بعد قومہ، سجدہ اور دو سجدوں کے درمیان وقفہ (جلسۂ استراحت) تقریباً برابر تھے۔"}],[1070,"انس بن مالک رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے ایک مہینے تک رکوع کے بعد دعائے قنوت پڑھی، آپ اس میں رعل، ذکوان اور عصیہ نامی قبائل ۱؎ پر جنہوں نے اللہ اور اس کے رسول کی نافرمانی کی تھی، بد دعا کرتے رہے۔\n§وضاحت\n۱؎: رعل، ذکوان اور عصیّہ تینوں قبائل کے نام ہیں، جنہوں نے نبی اکرم صلی اللہ علیہ وسلم کے قراء کو دھوکہ سے قتل کر دیا تھا، آپ نے ان پر ایک ماہ تک قنوت نازلہ پڑھی تھی، جو رکوع کے بعد پڑھی جاتی ہے، یہ وتر والی قنوت نہیں تھی، وتر والی قنوت میں تو افضل یہ ہے کہ رکوع سے پہلے پڑھی جائے، جائز رکوع کے بعد بھی ہے۔","الألباني: صحيح",{"u2":"حضرت انس بن مالک رضی اللہ عنہ سے مروی ہے، فرماتے ہیں: رسول اللہ صلی اللہ علیہ وسلم نے ایک مہینہ رکوع کے بعد قنوت فرمائی۔ آپ رعل، ذکوان اور عصیہ قبائل پر بددعا کرتے تھے۔ (کیونکہ) انھوں نے اللہ تعالیٰ اور اس کے رسول صلی اللہ علیہ وسلم کی معصیت (نافرمانی) کی تھی","f2":"(۱) ان کے ایک آدمی نے نبی صلی اللہ علیہ وسلم سے دھوکا کرکے کچھ مبغلین حاصل کیے جو سب قرآن کے قاری تھے اور انھیں اپنے علاقے میں لے جاکر ان قبائل سے قتل کرا دیا۔ ایک دوسرے حادثے میں نبی صلی اللہ علیہ وسلم کے دس صحابہ شہید کر دیے گئے۔ یہ واقعات جنگ احد کے بعد قریب ہی پیش آئے تھے۔ جنگ احد میں بھی مسلمانوں کا خاصا نقصان ہوا تھا۔ ان مسلسل جانی نقصانات سے نبی صلی اللہ علیہ وسلم غمگین ہوئے تو آپ نے قنوت نازلہ کا اہتمام فرمایا؎ (نازلہ عربی میں مصیبت کو کہتے ہیں اور قنوت وہ دعا جو کھڑے ہوکر کی جائے۔) آپ مختلف نمازوں میں آخری رکعت میں رکوع کے بعد ہاتھ اٹھا کر بلند آواز سے دعا مانگتے۔ صحابۂ کرام رضی اللہ عنھم بھی شریک دعا ہوتے۔ نبی صلی اللہ علیہ وسلم بعض مشرکین مکہ، دھوکا دینے والے قبائل اور قاتلین قراء کے نام لے کر بددعا فرماتے تھے۔ ایک مہینے تک یہ عمل جاری رہا۔ اس سے یہ معلوم ہوا کہ مخصوص حالات میں کسی شخص یا قبیلے کا نام لے کر بددعا کرنا جائز ہے، تاہم اس سے پہلے جنگ احد کے بعد آپ نے قنوت نازلہ کا اہتمام فرمایا جس میں آپ کا سرزخمی ہوگیا تھا اور ایک رباعی دانت ٹوٹ گیا تھا، اس موقع پر آپ کو ان کی بابت قنوت سے روک دیا گیا۔ یہ دو الگ الگ واقعات اور الگ الگ قنوت ہیں۔ مختلف قبائل کا نام لے کر جو قنوت کی، وہ آیت: (لیس لک من الآمر شییء) (آل عمران ۱۲۸:۳) کے نزدکل کے بعد کا واقعہ ہے، اس لیے حسب ضرورت کسی شخص یا قبیلے کا نام لے کر قنوت نازلہ کر ناجائز ہے۔ لیکن کبھی کبھار، نہ کہ ہمیشہ۔ امام حنیفہ رحمہ اللہ کسی معین شخص یا قبیلے کا نام لے کر اس کے حق میں یا اس کے خلاف دعا کرنے سے منع کرتے ہیں۔ یہ حدیث ان کے موقف کی تائید نہیں کرتی۔ امام شافعی رحمہ اللہ صبح کی نماز میں ہمیشہ قنوت کے قائل ہیں مگر یہ صحابہ میں مختلف فیہ مسئلہ رہا ہے، لہٰذا ایک آدھی روایت کی بنا پر اس پر دوام مناسب نہیں ہے، جب کہ اس کے خلاف بھی روایات موجود ہیں۔ جمہور اہل علم دوام کو غلط سمجھتے ہیں۔ صرف کسی اہم موقع پر جب کوی خصوصی مصیبت نازل ہو، رکوع کے بعد فجر یا کسی اور نماز میں قنوت کرلی جائے۔ دلائل کو جمع کرنے سے یہی نتیجہ نکلتا ہے۔ جب دلائل متعارض معلوم ہوں تو درمیانی راہ نکالنی چاہیے نہ کہ کسی ایک جانب کو لازم کر لیا جائے۔ باقی رہی قنوت وتر تو اس کا ذکر وتر کی بحث میں مناسب ہے۔ ان شاء اللہ وہیں آئے گا۔ (۲) امام ابوحنیفہ رحمہ اللہ نماز میں غیر قرآن الفاظ کے ساتھ دعا کرنا ممنوع قرار دیتے ہیں۔ حدیث ان کے موقف کی تردید کرتی ہے۔ (۳) کفار پر لعنت بھیجنا اور ان کے خلاف بددعا کرنا جائز ہے۔"}],[1071,"ابن سیرین سے روایت ہے کہ انس بن مالک رضی اللہ عنہ سے پوچھا گیا، کیا رسول اللہ صلی اللہ علیہ وسلم نے نماز فجر میں قنوت پڑھی ہے؟ انہوں نے کہا: جی ہاں!(پڑھی ہے) پھر ان سے پوچھا گیا، رکوع سے پہلے یا رکوع کے بعد؟ رکوع کے بعد ۱؎۔\n§وضاحت\n۱؎: اور رکوع سے پہلے کی بھی روایت موجود ہے جیسا کہ ابن ماجہ :(حدیث رقم: ۱۱۸۳ ) میں «نقنت قبل الرکوع وبعدہ» کے الفاظ آئے ہیں اور اس کی سند قوی ہے۔ گویا دونوں طرح جائز ہے۔","الألباني: صحيح",{"u2":"حضرت ابن سیرین سے روایت ہے کہ حضرت انس بن مالک رضی اللہ عنہ سے پوچھا گیا: کیا رسول اللہ صلی اللہ علیہ وسلم نے صبح کی نماز میں قنوت پڑھی ہے؟ آپ نے فرمایا: ہاں۔ پوچھا گیا: رکوع سے پہلے یا بعد؟ آپ نے فرمایا: رکوع کے بعد۔","f2":"یہی وہ قنوت ہے جسے امام شافعی رحمہ اللہ نے صبح کی قنوت سمجھا ہے جب کہ جمہور اہل علم اسے عارضی قنوت نازلہ سمجھتے ہیں۔"}],[1072,"ابن سیرین کہتے ہیں کہ مجھ سے ایک ایسے شخص نے جس نے رسول اللہ صلی اللہ علیہ وسلم کے ساتھ نماز فجر پڑھی تھی، بیان کیا کہ جب آپ صلی اللہ علیہ وسلم نے دوسری رکعت میں «سمع اللہ لمن حمده» کہا تو آپ تھوڑی دیر کھڑے رہے۔","الألباني: صحيح",{"u2":"حضرت ابن سیرین بیان کرتے ہیں کہ مجھے ایک ایسے صحابی (رضی اللہ عنہ) نے بیان کیا جنھوں نے رسول اللہ صلی اللہ علیہ وسلم کے ساتھ نماز صبح پڑھی۔ (ان کے بیان کے مطابق) جب آپ نتے دوسری رکعت میں [سمع اللہ لمن حمدہ] کہا تو آپ کچھ دیر کھڑے رہے۔","f2":"امام صاحب رحمہ اللہ نے شاید کچھ دیر کھڑے رہنے کو قنوت پر محمول کیا ہے، حالانکہ نبی صلی اللہ علیہ وسلم رکوع کے بعد بھی بعض اذکار و اوراد پڑھا کرتے تھے۔ قنوت تو ہاتھ اٹھا کر اور جہراً پڑھی جاتی ہے جیسا کہ روایات میں صراحتاً آیا ہے۔ (مسند أحمد: ۳/۳)"}],[1073,"ابوہریرہ رضی اللہ عنہ کہتے ہیں کہ جب رسول اللہ صلی اللہ علیہ وسلم نے فجر میں دوسری رکعت سے اپنا سر اٹھایا تو آپ نے دعا کی: \"اے اللہ! ولید بن ولید، سلمہ بن ہشام، عیاش بن ابی ربیعہ اور مکہ کے کمزور لوگوں کو دشمنوں کے چنگل سے نجات دے، اے اللہ! قبیلہ مضر پر اپنی پکڑ سخت کر دے، اور ان کے اوپر یوسف علیہ السلام(کی قوم) جیسا سا قحط مسلط کر دے\"۔","الألباني: صحيح",{"u2":"حضرت ابوہریرہ رضی اللہ عنہ سے منقول ہے کہ رسول اللہ صلی اللہ علیہ وسلم جب صبح کی نماز کی دوسری رکعت کے رکوع سے سر اٹھاتے تو فرماتے: ’’اے اللہ! ولید بن ولید، سلمہ بن ہشام، عیاش بن ابو ربیعہ اور مکہ میں دوسرے کمزور اور مظلوم مسلمانوں کو نجات دے۔ اے اللہ! مضر (قریش) پر اپنا عذاب سخت فرما اور اس عذاب کو قحط کی صورت میں نازل فرما جو یوسف علیہ السلام کے دور کے قحط کی طرح ہو۔‘‘","f2":"(۱) الفاظ سے مراحتاً معلوم ہوتا ہے کہ یہ قنوت نازلہ ہے جو آپ ہمیشہ نہیں فرماتے تھے۔ (۲) یوسف علیہ السلام کے قحط سے تشبیہ کا مطلب یہ ہے کہ وہ کئی سال جاری رہا اور ایسا ہی ہوا، ان کے خلاف رسول اللہ صلی اللہ علیہ وسلم کی یہ دعا قبول ہوئی، ان پر قحط سالی آئی اور مضر والے کئی برس تک قحط کی بلا میں گرفتار رہے یہاں تک کہ وہ ہڈیاں، چمڑے اور مردار تک کھانے لگے۔ پھر جب قریش اس قحط سے عاجز آگئے تو ان کا نمائندہ اور سردار ابوسفیان مدینہ منورہ حاضر ہوا اور قحط کے خاتمے کے لیے دعا کی اپیل کی تو نبیٔ رحمت صلی اللہ علیہ وسلم نے غیر مشروط طور پر قحط کے خاتمے کی دعا فرما دی اور قحط دور ہوگیا۔ دیکھیے: (صحیح البخاری، الاستسقاء، حدیث: ۱۰۰۷) (۳) صبح کی نماز میں قنوت نازلہ جائز ہے۔ (۴) قنوت نازلہ رکوع کے بعد ہوگی۔ (۵) کسی کا نام لے کے دعا یا بددعا کرنے سے نماز باطل نہیں ہوتی جیسا کہ احناف کا موقف ہے۔ (۶) قنوت نازلہ بلند آواز سے کرنا مستحب ہے۔ صحیح بخاری میں صراحت ہے کہ آپ بلند آواز سے قنوت کراتے تھے۔ دیکھیے: (صحیح البخاری، التفسیر، حدیث: ۴۵۶۰) نیز سنن ابی داود کی روایت میں ہے: [یومن من خلقہ] ’’آپ کے پیچھے والے آمین کہتے تھے۔‘‘ (سنن ابی داود، الوتر، حدیث: ۱۴۴۳)"}],[1074,"ابوہریرہ رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نماز میں جس وقت «سمع اللہ لمن حمده ربنا ولك الحمد» کہتے تو دعا کرتے، سجدہ میں جانے سے پہلے کھڑے ہو کر، کہتے: «اللہم أنج الوليد بن الوليد وسلمة بن هشام وعياش بن أبي ربيعة والمستضعفين من المؤمنين اللہم اشدد وطأتك على مضر واجعلها عليهم كسني يوسف» \"اے اللہ! ولید بن ولید، سلمہ بن ہشام، عیاش بن ابی ربیعہ اور کمزور مسلمانوں کو دشمنوں کے چنگل سے نجات دے، اے اللہ! قبیلہ مضر پر اپنی پکڑ سخت کر دے، اور ان پر یوسف سا قحط مسلط کر دے\"، پھر آپ اللہ اکبر کہتے اور سجدہ کرتے، ان دنوں قبیلہ مضر رسول اللہ صلی اللہ علیہ وسلم کا مخالف تھا۔","الألباني: صحيح",{"u2":"حضرت ابوہریرہ رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نماز میں جب [سمع اللہ لمن حمدہ ربنا ولک الحمد] پڑھتے تو سجدے میں جانے سے پہلے کھڑے کھڑے دعا فرماتے: [اللھم! انج الولید ……… الخ] ’’اے اللہ! ولید بن ولید، سلمہ بن ہشام، عیاش بن ابو ربیعہ اور دوسرے کمزور مسلمانوں کو نجات عطا فرما۔ اے اللہ! مضر (قریش) پر اپنا عذاب سخت فرما اور اسے یوسف علیہ السلام کے دور کے قحط کی صورت میں نازل فرما۔‘‘ پھر آپ اللہ اکبر کہتے اور سجدے کو جاتے۔ ان دنوں مضر کے بادیہ نشین رسول اللہ صلی اللہ علیہ وسلم کے مخالف تھے۔"}],[1075,"ابوہریرہ رضی اللہ عنہ سے روایت کرتے ہیں کہ انہوں نے کہا کہ میں تمہیں رسول اللہ صلی اللہ علیہ وسلم کی نماز قریب تر کر کے دکھاؤں گا، چنانچہ ابوہریرہ رضی اللہ عنہ «سمع اللہ لمن حمده» کہنے کے بعد ظہر کی آخری رکعت میں اور عشاء میں، اور فجر میں دعائے قنوت پڑھتے، تو مومنوں کے لیے دعا کرتے اور کافروں پر لعنت بھیجتے تھے۔","الألباني: صحيح",{"u2":"حضرت ابوہریرہ رضی اللہ عنہ بیان کرتے ہیں میں تمھیں ضرور اللہ کے رسول صلی اللہ علیہ وسلم کی نماز سمجھاؤں گا تو حضرت ابوہریرہ رضی اللہ عنہ ظہر، عشاء اور صبح کی نمازوں کی آخری رکعت میں [سمع اللہ لمن حمدہ] کہنے کے بعد قنوت پڑھتے جس میں ایمان والوں کے لیے دعائیں کرتے اور کافروں کو لعنت کرتے تھے۔"}],[1076,"براء بن عازب رضی اللہ عنہم سے روایت ہے کہ نبی اکرم صلی اللہ علیہ وسلم فجر میں اور مغرب میں دعائے قنوت پڑھتے تھے۔ عبیداللہ بن سعید کی روایت میں «أن النبي صلى اللہ عليه وسلم» کے بجائے «أن رسول اللہ صلى اللہ عليه وسلم» ہے۔","الألباني: صحيح",{"u2":"حضرت براء بن عازب رضی اللہ عنہما سے مروی ہے کہ نبی صلی اللہ علیہ وسلم صبح اور مغرب کی نماز میں قنوت پڑھا کرتے تھے۔","f2":"صحیح بات یہ ہے کہ یہ قنوت نازلہ تھی جو آپ نے مختلف نمازوں میں ضرورت کے وقت کی ہے مگر بعض حضرات نے اسے قنوت نازلہ کی بجائے صبح اور مغرب کی قنوت لازمہ قرار دیا ہے، یعنی ان دو نمازوں میں آپ ہمیشہ قنوت فرماتے تھے۔ مگر مغرب کی قنوت کے ترک پر تو اتفاق و اجماع امت ہے۔ کوئی محدث یا فقیہ بھی قنوت نازلہ کے علاوہ مغرب کی قنوت کا قائل نہیں، البتہ امام شافعی اور بعض محدثین (ہمیشہ) فجر کی قنوت کے قائل ہیں۔ اس روایت کو دیکھیں تو دونوں نمازیں برابر ہیں۔ اگر مغرب میں منسوخ ہے تو فجر میں کیوں منسوخ نہیں؟ اور یہی صحی بات ہے کہ قنوت نازلہ تو باقی ہے مگر قتنوت فرض (فجر اور مغرب کی قنوت) باقی نہیں ہے۔ جس روایت سے صبح کی نماز میں قنوت ثابت ہوتی ہے، اسے قنوت نازلہ پر محمول کیا جائے گا، یعنی نبی صلی اللہ علیہ وسلم آخر زندگی تک صبح کی نماز میں بوقت ضرورت قنوت نازلہ کرتے تھے۔ اس طرح سب احادیث میں تطبیق ہو جائے گی۔"}],[1077,"انس رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے ایک مہینہ تک دعائے قنوت پڑھی۔ شعبہ کی روایت میں ہے آپ نے چند لوگوں پر لعنت بھیجی، اور ہشام کی روایت میں ہے کہ آپ صلی اللہ علیہ وسلم عرب کے کچھ قبیلوں پر رکوع کے بعد بد دعا فرماتے تھے، پھر آپ نے اسے چھوڑ دیا، یہ قول ہشام کا ہے، اور شعبہ قتادہ سے اور قتادہ انس رضی اللہ عنہ سے بیان کرتے ہیں کہ نبی اکرم صلی اللہ علیہ وسلم نے ایک مہینہ تک قنوت پڑھی، آپ رعل، ذکوان اور لحیان قبائل پر لعنت بھیج رہے تھے۔","الألباني: صحيح",{"u2":"حضرت انس رضی اللہ عنہ سے منقول ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے ایک مہینہ رکوع کے بعد قنوت فرمائی۔ آپ چند لوگوں کے نام لے کر ان پر لعنت کرتے تھے اور عرب کے کچھ قبائل کا نام لے کر بددعا کرتے تھے۔ پھر آپ نے قنوت کرنا ترک کر دی۔ ایک روایت میں ہے کہ نبی صلی اللہ علیہ وسلم نے ایک مہینے تک قنوت فرمائی۔ آپ رعل، ذکوان اور لحیان (نامی قبائل) پر لعنت کرتے تھے"}],[1078,"عبداللہ بن عمر رضی اللہ عنہم سے روایت ہے کہ انہوں نے نبی اکرم صلی اللہ علیہ وسلم کو جس وقت آپ نے فجر کی نماز میں آخری رکعت سے اپنا سر اٹھایا کچھ منافقوں پر لعنت بھیجتے ہوئے سنا، آپ کہہ رہے تھے: «اللہم العن فلانا وفلانا» \"اے اللہ! تو فلاں فلاں کو رسوا کر\"، تو اللہ تعالی نے یہ آیت نازل فرمائی: «ليس لك من الأمر شىء أو يتوب عليهم أو يعذبهم فإنهم ظالمون» \"اے محمد! آپ کے اختیار میں کچھ نہیں، اللہ چاہے تو ان کی توبہ قبول کرے یا عذاب دے، کیونکہ وہ ظالم ہیں\" (آل عمران: ۱۲۸)۔","الألباني: صحيح",{"u2":"حضرت عبداللہ بن عمر رضی اللہ عنہما سے مروی ہے کہ انھوں نے نبی صلی اللہ علیہ وسلم سے سنا، آپ نے جب صبح کی نماز میں آخری رکعت کے رکوع سے سر اٹھایا تو فرمایا: [اللھم! العن فلانا و فلانا] ’’اے اللہ! فلاں اور فلاں پر لعنت فرما۔‘‘ آپ منافقین میں سے کچھ لوگوں کا نام لے لے کر بددعا کرتے تھے تو اللہ تعالیٰ نے یہ آیت اتاری: (لیس لک من الامرشیء اویتوب علیھم اویعذبھم فانھم ظلمون) ’’آپ کے لیے اس معاملے میں کوئی اختیار نہیں۔ (یہ اللہ تعالیٰ کا کام ہے کہ) وہ انھیں توبہ کی توفیق دے یا انھیں عذاب دے۔ بلاشبہ وہ ظالم ہیں۔‘‘","f2":"حافظ ابن حجر رحمہ اللہ نے صراحت کی ہے کہ فأنزل اللہ راوی کا ادراج ہے، اس لیے اس آیت کو قنوت نازلہ سے رکنے کا سبب قرار نہیں دیا جا سکتا۔ دیکھیے: (فتح الباری: ۲۸۶/۸، حدیث: ۴۵۶۰۔ مزید دیکھیے: فوائد حدیث: ۱۰۷۱)"}],[1079,"انس رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے ایک مہینہ تک دعائے قنوت پڑھی، آپ عرب کے ایک قبیلے پر بد دعا کر رہے تھے، پھر آپ نے اسے ترک کر دیا۔","الألباني: صحيح",{"u2":"حضرت انس رضی اللہ عنہ سے منقول ہے کہ رسول اللہ صلی اللہ علیہ وسلمنے ایک ماہ قنوت فرمائی۔ آپ عرب کے قابئل میں سے ایک قبلے کے خلاف بددعا کرتے تھے۔ پھر آپ نے قنوت چھوڑ دی۔","f2":"ایک نہیں بلکہ کئی قبیلوں کے خلاف بددعا کرتے تھے۔ (دیکھیے، روایت: ۱۰۷۸"}],[1080,"ابو مالک اشجعی (سعد) اپنے والد (طارق بن اشیم) سے کہتے ہیں کہ میں نے رسول اللہ صلی اللہ علیہ وسلم کے پیچھے نماز پڑھی تو آپ نے دعائے قنوت نہیں پڑھی، ابوبکر رضی اللہ عنہ کے پیچھے نماز پڑھی تو انہوں نے بھی دعائے قنوت نہیں پڑھی، عمر رضی اللہ عنہ کے پیچھے نماز پڑھی تو انہوں نے بھی دعائے قنوت نہیں پڑھی، عثمان رضی اللہ عنہ کے پیچھے نماز پڑھی تو انہوں نے بھی دعائے قنوت نہیں پڑھی، اور علی رضی اللہ عنہ کے پیچھے نماز پڑھی تو انہوں نے بھی دعائے قنوت نہیں پڑھی، پھر انہوں نے کہا: میرے بیٹے! یہ (یعنی: مداومت) بدعت ہے ۱؎۔\n§وضاحت\n۱؎: قنوت نازلہ فجر میں بوقت ضرورت پڑھی گئی تھی، پھر چھوڑ دی گئی، اس لیے مداومت :(ہمیشہ پڑھنے ) کو انہوں نے بدعت کہا، ضرورت پڑنے پر اب بھی پڑھی جا سکتی ہے۔","الألباني: صحيح",{"u2":"حضرت ابو مالک اشجعی نے اپنے والد محترم (طارق بن اشیم) رضی اللہ عنہ سے بیان کیا، انھوں نے فرمایا: میں نے رسول اللہ صلی اللہ علیہ وسلم کے پیچھے نماز پڑھی، آپ نے قنوت نہ فرمائی۔ میں نے ابوبکر رضی اللہ عنہ کے پیچھے نماز پڑھی، انھوں نے بھی قنوت نہ کی۔ میں نے عمر رضی اللہ عنہ کے پیچھے نماز پڑھی، انھوں نے بھی قنوت نہ کی۔ میں نے عثمان رضی اللہ عنہ کے پیچھے نماز پڑھی، انھوں نے بھی قنوت نہ کی۔ میں نے علی رضی اللہ عنہ کے پیچھے نماز پڑھی، آپ نے بھی قنوت نہ کی۔ پھر فرمایا: اے بیٹے! یہ بدعت ہے۔","f2":"ان صحابی کے علم میں نبی صلی اللہ علیہ وسلم اور خلفائے راشدین کا قنوت فرمانا نہیں آسکا، اس لیے انھوں نے اسے بدعت قرار دیا۔ یا پھر ان کا مطلب یہ ہے کہ قنوت پر دوام بدعت ہے کیونکہ رسول اللہ صلی اللہ علیہ وسلم بوقت ضرورت قنوت نازلہ پڑھتے تھے۔ (مزید دیکھیے، حدیث: ۱۰۷۷)"}],[1081,"جابر بن عبداللہ رضی اللہ عنہم کہتے ہیں کہ ہم ظہر کی نماز رسول اللہ صلی اللہ علیہ وسلم کے ساتھ پڑھتے تھے، میں نماز میں ہی ایک مٹھی کنکری اپنے ہاتھ میں لے لیتا، اسے ٹھنڈا کرتا، پھر اسے دوسرے ہاتھ میں پلٹ دیتا، تو جب سجدہ کرتا تو اسے اپنی پیشانی کے نیچے رکھ لیتا۔","الألباني: حسن",{"u2":"حضرت جابر بن عبداللہ رضی اللہ عنہما سے روایت ہے، فرماتے ہیں: ہم رسول اللہ صلی اللہ علیہ وسلم کے ساتھ ظہر کی نماز پڑھا کرتے تھے تو میں اپنی مٹھی میں کچھ کنکریاں پکڑ لیتا تھا تاکہ انھیں ٹھنڈا کروں۔ پھر (جب ہاتھ جلنے لگتا تو) انھیں دوسری ہتھیلی میں منتقل کر لیتا تھا۔ پھر جب میں سجدہ کرتا تو انھیں اپنے ماتھے کے نیچے رکھ لیتا۔","f2":"(۱) زمین گرم ہوتی تھی۔ براہ راست شدید گرم زمین پر ماتھا رکھنا انتہائی مشکل تھا، لہٰذا نسبتاً ٹھنڈی کنکریاں بچھا کر ان پر ماتھا رکھ لیتے۔ رسول اللہ صلی اللہ علیہ وسلم کا سجدہ بھی لمبا ہوتا تھا۔ معلوم ہوتا ہے نماز یا نمازی کی مصلحت کے لیے نماز کے علاوہ کوئی فعل کرنا پڑے تو کوئی حرج نہیں۔ فعل کی حد بندی ممکن نہیں ہے، البتہ ایسا مشغول نہ ہو کہ دیکھنے والا اسے نماز سے خارج تصور کرے۔ (۲) یہ بھی ثابت ہوا کہ نماز ظہر جلدی ادا کرنی چاہیے اور اسے اس قدر لیٹ نہیں کرنا چاہیے کہ زمین ٹھنڈی ہونے کا انتظار کیا جائے۔ اس طرح تو اس کا وقت نکل جائے گا۔ حدیث میں جو ابراد ظہر کا حکم ہے، اس سے مراد یہ ہے کہ زوال کے بعد تھوڑا بہت انتظار کر لیا جائے تاکہ عین زوال شمس کے وقت دھوپ کی جو شدت اور تمازت ہوتی ہے، اس میں قدرے کمی آ جائے اور سائے ڈھل جائیں تاکہ لوگ آسانی کے ساتھ مسجد میں آسکیں، ورنہ گرمی اور زمین کی تپش تو عصر کے وقت بھی ختم نہیں ہوتی۔ (۳) دوران نماز میں تکلیف اور ضرر کی تلافی کی جا سکتی ہے، اس طرح کے عمل سے نماز باطل نہیں ہوتی۔ (۴) نماز کا اہتمام ضروری ہے اگرچہ اس کے لیے مشقت برداشت کرنی پڑے۔ (۵) ان تمام سہولیات و مراعات کو زیر استعمال لایا جا سکتا ہے جو خشوع میں اضافے کا باعث ہوں۔ (۶) کسی صحابی کا یہ کہنا کہ ’’ہم ایسے کیا کرتے تھے‘‘ مرفوع کے حکم میں ہے۔ لیکن یہاں اس سے بھی قوی قرینہ موجود ہے۔ وہ یہ کہ حضرت جابر بن عبداللہ رضی اللہ عنہ نبیٔ اکرم صلی اللہ علیہ وسلم کے پیچھے نماز پڑھ رہے تھے اور آپ صلی اللہ علیہ وسلم نمازیوں کو اپنے پیچھے سے بھی دیکھتے تھے اور آپ صلی اللہ علیہ وسلم نے انھیں منع نہیں فرمایا۔ اس اعتبار سے اس کا مرفوع ہونا زیادہ قوی ہے۔ واللہ اعلم۔"}],[1082,"مطرف کہتے ہیں کہ میں نے اور عمران بن حصین رضی اللہ عنہما دونوں نے علی بن ابی طالب رضی اللہ عنہ کے پیچھے نماز پڑھی، جب وہ سجدہ کرتے تو اللہ اکبر کہتے، اور جب سجدہ سے اپنا سر اٹھاتے تو اللہ اکبر کہتے، اور جب دو رکعتیں پڑھ کر اٹھتے تو اللہ اکبر کہتے، جب وہ نماز پڑھ چکے تو عمران رضی اللہ عنہ نے میرا ہاتھ پکڑا اور کہا: انہوں نے مجھے محمد صلی اللہ علیہ وسلم کی نماز یاد دلا دی۔","الألباني: صحيح",{"u2":"حضرت مطرف سے روایت ہے کہ حضرت عمران بن حصین رضی اللہ عنہ نے اور میں نے حضرت علی بن ابو طالب رضی اللہ عنہ کے پیچھے نماز پڑھی۔ آپ جب سجدہ کرتے تو اللہ اکبر کہتے اور جب سجدے سے سر اٹھاتے، تب بھی اللہ اکبر کہتے اور جب دو رکعتوں سے اٹھتے، تب بھی اللہ اکبر کہتے۔ جب آپ نے نماز پوری کرلی تو حضرت عمران بن حصین رضی اللہ عنہ نے میرا ہاتھ پکڑا اور فرمایا: اللہ کی قسم! ان صاحب نے مجھے محمد صلی اللہ علیہ وسلم کی نماز یاد کرا دی ہے۔","f2":"(۱) پیچھے گزر چکا ہے کہ صحابۂ کرام رضی اللہ عنھم ہی کے دور میں بعض ائمہ نے تکبیر کہنے میں سستی شروع کر دی تھی۔ یا تو کہتے ہی نہیں تھے یا بہت آہستہ بلکہ زیر لب کتے تھے۔ یہ نزاکت تھی، کوئی عذر نہ تھا، لہٰذا ایسا کرنا مذموم تھا۔ ہاں عذر ہو تو الگ بات ہے، جیسے حضرت عثمان رضی اللہ عنہ کے بارے میں کہا گیا ہے کہ بڑھاپے کی وجہ سے ان کی تکبیر کی آواز پچھلی صفوں کو سنائی نہ دیتی تھی۔ (۲) حضرت علی بن ابو طالب رضی اللہ عنہ کی فضیلت ثابت ہوتی ہے کہ وہ کس قدر سنت نبوی کے محافظ اور عامل تھے کہ جب اکثر لوگ تکبیرات انتقال چھوڑ چکے تھے بلکہ بعض ان کی مشروعیت کا انکار بھی کرتے تھے، ایسے وقت میں انھوں نے ان کا حای (انھیں زندہ) کیا۔"}],[1083,"عبداللہ بن مسعود رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم ہر جھکنے اور اٹھنے میں اللہ اکبر کہتے تھے ۱؎، اور آپ اپنے دائیں اور بائیں دونوں طرف سلام پھیرتے، ابوبکر و عمر رضی اللہ عنہم بھی ایسا ہی کرتے تھے۔\n§وضاحت\n۱؎: مراد یہ ہے کہ اکثر جھکتے اور اٹھتے وقت «اللہ اکبر» کہتے، ورنہ رکوع سے اٹھتے وقت «اللہ اکبر» نہیں کہتے تھے، بلکہ اس کے بجائے«سمع اللہ لمن حمدہ» کہتے۔","الألباني: صحيح",{"u2":"حضرت عبداللہ بن مسعود رضی اللہ عنہ سے مروی ہے کہ رسول اللہ صلی اللہ علیہ وسلم ہر جھکنے اور اٹھنے کے وقت اللہ اکبر کہتے تھے اور آخر میں دائیں بائیں دونوں طرف سلام پھیرتے تھے۔ حضرت ابوبکر اور حضرت عمر رضی اللہ عنہما بھی ایسے ہی کیا کرتے تھے۔","f2":"’’ہر جھکنے اور اٹھنے کے وقت۔‘‘ البتہ اس سے رکوع سے اٹھنا مستثنیٰ ہے کہ وہاں اللہ اکبر کی بجائے [سمع اللہ لمن حمدہ] مسنون ہے۔ گویا ایک آدھ کو اکثر کے تابع کر دیا۔"}],[1084,"حکیم رضی اللہ عنہ کہتے ہیں کہ میں نے رسول اللہ صلی اللہ علیہ وسلم سے اس بات پر بیعت کی کہ میں کھڑے کھڑے ہی سجدے میں گروں گا ۱؎۔\n§وضاحت\n۱؎: یعنی رکوع سے واپس قیام میں جاؤں گا، اور سیدھا کھڑا ہو جانے کے بعد سجدہ کے لیے جھکوں گا۔ :(دونوں سجدوں کے درمیان رفع یدین کے ذکر کے بغیر یہ حدیث رقم: ۸۸۱ میں گزر چکی ہے )","الألباني: صحيح الإسناد",{"u2":"حضرت حکیم رضی اللہ عنہ بیان کرتے ہیں کہ میں نے اللہ کے رسول صلی اللہ علیہ وسلم کے ساتھ عہد کیا تھا کہ میں سجدے میں نہیں جاؤں گا مگر سیدھا کھڑا ہوکر۔","f2":"یعنی رکوع ہی سے سیدھا یا رکوع سے مکمل سیدھا کھڑے ہوئے بغیر سجدے میں نہیں جاؤں گا بلکہ رکوع سے سیدھا کھڑا ہوں گا، پھر سجدے میں گروں گا۔ اس جملے کے اور بھی کئی معانی کیے گئے ہیں، مثلاً: میں نہیں مروں گا مگر اسلام پر ثابت قدمی کی حالت میں وغیرہ۔ مگر پہلا معنی ہی مناسب ہے۔ واللہ اعلم۔"}],[1085,"مالک بن حویرث رضی اللہ عنہ سے روایت ہے کہ انہوں نے نبی اکرم صلی اللہ علیہ وسلم کو نماز میں جب آپ رکوع کرتے، اور جب رکوع سے اپنا سر اٹھاتے، اور جب سجدہ کرتے، اور جب سجدہ سے اپنا سر اٹھاتے ۱؎ رفع یدین کرتے دیکھا، یہاں تک کہ آپ اپنے دونوں ہاتھوں کو اپنے دونوں کانوں کی لو کے بالمقابل کر لیتے ۲؎۔\n§وضاحت\n۱؎: اس سے ثابت ہوتا ہے کہ آپ کبھی کبھار سجدہ میں جاتے اور سجدہ سے سر اٹھاتے وقت بھی رفع یدین کرتے تھے۔ ۲؎: گرچہ بعض علماء نے \"دونوں سجدوں میں جاتے اور ان سے سر اٹھاتے وقت رفع الیدین\" والے اس ٹکڑے کی تصحیح کی ہے، مگر اکثر علماء اور رفع یدین کے قائل ائمہ نے اس ٹکڑے کی تضعیف کی ہے، اس کے راوی \"قتادہ\" مدلس ہیں، اور انہوں نے اسے عنعنہ سے روایت کیا ہے اس باب میں دیگر روایات بھی کلام سے خالی نہیں ہیں، جب کہ سجدہ میں رفع یدین کرنے والی ابن عمر رضی اللہ عنہم کی روایت صحیحین کی ہے۔","الألباني: صحيح",{"u2":"حضرت مالک بن حویرث رضی اللہ عنہ سے روایت ہے، انھوں نے نبی صلی اللہ علیہ وسلم کو دیکھا آپ اپنی نماز میں جب رکوع کرتے یا رکوع سے سر اٹھاتے یا سجدے میں جاتے یا سجدے سے سر اٹھاتے تو اپنے دونوں ہاتھ اٹھاتے حتی کہ انھیں کانوں کے کناروں کے برابر کرتے۔"}],[1086,"مالک بن حویرث رضی اللہ عنہ سے روایت ہے کہ انہوں نے نبی اکرم صلی اللہ علیہ وسلم کو اپنے دونوں ہاتھ اٹھاتے ہوئے دیکھا، انہوں نے اسی کے مثل روایت ذکر کی۔","الألباني: صحيح",{"u2":"حضرت مالک بن حویرث رضی اللہ عنہ سے روایت ہے، انھوں نے نبی صلی اللہ علیہ وسلم کو دیکھا کہ آپ نے اپنے دونوں ہاتھ اٹھائے (رفع الیدین کیا)۔ پھر اسی سابقہ (روایت) کی مثل بیان کیا۔"}],[1087,"مالک بن حویرث رضی اللہ عنہ سے روایت ہے کہ نبی اکرم صلی اللہ علیہ وسلم جب نماز میں داخل ہو جاتے .... پھر آگے انہوں نے اسی طرح کی حدیث ذکر کی، اس میں انہوں نے یہ اضافہ کیا ہے کہ \"جب آپ صلی اللہ علیہ وسلم رکوع کرتے تو بھی ایسا ہی کرتے، اور جب رکوع سے سر اٹھاتے تو بھی، اور جب سجدہ سے سر اٹھاتے تو بھی\"۔","الألباني: صحيح",{"u2":"حضرت مالک بن حویرث رضی اللہ عنہ سے مروی ہے، انھوں نے نبی صلی اللہ علیہ وسلم کو دیکھا، آآ جب نماز شروع فرماتے۔ پھر اسی (سابقہ حدیث) کی طرح بیان کیا۔ اس میں اتنا زیادہ کیا، اور جب رکوع کرتے، تب بھی ایسے ہی کرتے اور جب رکوع سے سر اٹھاتے، پھر بھی ایسے ہی کرتے اور جب سجدے سے سر اٹھاتے، تب بھی ایسے ہی کرتے۔","f2":"حضرت مالک بن حویرث رضی اللہ عنہ کی مذکورہ روایات میں سجدے میں جاتے وقت اور سجدے سے سر اٹھاتے وقت رفع الیدین کرنے کا ذکر ہے، لیکن یہ تینوں روایات ضعیف ہیں جس کی تفصیل تخریج میں موجود ہے۔ اس کے برعکس بالکل صحیح روایات میں سجدے کے رفع الیدین کی نفی آئی ہے۔ ان میں سے ایک روایت اگلے باب میں آ رہی ہے۔ ان صحیح روایات کو چھو ڑکر ایک ضعیف یا متنازع فیہ روایت پر عمل کرنا دانش مندی نہیں۔"}],[1088,"عبداللہ بن عمر رضی اللہ عنہم کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نماز شروع کرتے، اور جب رکوع کرتے، اور جب رکوع سے اپنا سر اٹھاتے، تو اپنے دونوں ہاتھ اٹھاتے اور سجدہ کرنے میں ایسا نہیں کرتے تھے۔","الألباني: صحيح",{"u2":"حضرت عبداللہ بن عمر رضی اللہ عنہا بیان کرتے ہیں کہ اللہ کے رسول صلی اللہ علیہ وسلم جب نماز شروع فرماتے، جب رکوع کرتے اور جب رکوع سے اٹھتے تو رفع الیدین کرتے۔ لیکن سجدے میں (جاتے یا سجدے سے اٹھتے وقت) ایسا نہیں کرتے تھے۔"}],[1089,"وائل بن حجر رضی اللہ عنہ کہتے ہیں کہ میں نے رسول اللہ صلی اللہ علیہ وسلم کو دیکھا کہ جب آپ سجدہ کرتے تو اپنے ہاتھوں سے پہلے اپنے گھٹنے رکھتے، اور جب اٹھتے تو اپنے گھٹنوں سے پہلے اپنے ہاتھ اٹھاتے۔","الألباني: ضعيف",{"u2":"حضرت وائل بن حجر رضی اللہ عنہ سے روایت ہے، انھوں نے فرمایا: میں نے رسول اللہ صلی اللہ علیہ وسلم کو دیکھا جب آپ سجدہ کرتے تو اپنے گھٹنے، اپنے ہاتھوں سے پہلے رکھتے۔ اور جب اٹھتے تو اپنے ہاتھ گھٹنوں سے پہلے اٹھاتے۔"}],[1090,"ابوہریرہ رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"کیا تم میں سے کوئی اپنی نماز کا قصد کرتا ہے تو وہ بیٹھتا ہے جیسے اونٹ بیٹھتا ہے؟\" ۱؎۔\n§وضاحت\n۱؎: آپ صلی اللہ علیہ وسلم کا یہ ارشاد \"استفھام انکاری\" ہے، یعنی ایسا نہیں کرنا چاہیئے، یعنی اونٹ کے بیٹھنے کی طرح نماز میں نہیں بیٹھنا چاہیئے، اور یہ واضح رہے کہ چوپایوں کے گھٹنے ان کے اگلے دونوں پاؤں میں ہوتے ہیں، اونٹ پہلے اپنے اگلے پاؤں رکھتا ہے یعنی گھٹنے پہلے رکھتا ہے، اور انسان کو نماز میں اونٹ کی طرح بیٹھنے سے منع کیا گیا ہے، اس لیے انسان اونٹ کی مخالفت کرتے ہوئے پہلے اپنے ہاتھ رکھے پھر گھٹنے۔","الألباني: صحيح",{"u2":"حضرت ابوہریرہ رضی اللہ عنہ سے منقول ہے، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’(کیا) تم میں سے ایک آدمی نماز میں بیٹھنا چاہتا ہے، پھر وہ اونٹ کی طرح بیٹھتا ہے؟‘‘"}],[1091,"ابوہریرہ رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"جب تم میں سے کوئی سجدہ کرے تو اپنے گھٹنوں سے پہلے اپنا ہاتھ زمین پر رکھے، اور وہ اونٹ کے بیٹھنے کی طرح نہ بیٹھے\"۔","الألباني: صحيح",{"u2":"حضرت ابوہریرہ رضی اللہ عنہ سے مروی ہے، اللہ کے رسول صلی اللہ علیہ وسلم نے فرمایا: ’’جب تم میں سے کوئی آدمی سجدہ کرنے لگے تو اپنے ہاتھ اپنے گھٹنوں سے پہلے زمین پر رکھے اور اونٹ کی طرح نہ بیٹھے۔‘‘","f2":"باب کی تیسری روایت دوسری روایت کی تفصیل ہے اور یہ پہلی روایت کے بالکل الٹ ہے۔ پہلی روایت اکثر محدثین کے نزدیک ضعیف ہے جیسا کہ محقق کتاب نے بھی اسے سنداً ضعیف قرار دیا ہے، تاہم بعض نے اسے صحیح بھی کہا ہے، اس لیے ان کے نزدیک دونوں طرح جائز ہے کیونکہ ان کے خیال میں دونوں روایات صحیح ہیں۔ احناف وغیرہ نے حضرت وائل بن حجر رضی اللہ عنہ کی روایت کو ترجیح دی ہے کیونکہ جو عضو زمین کے زیادہ قریب ہے، وہ پہلے لگنا چاہیے اور جو دور ہے، وہ بعد میں۔ اکثر محدثین نے حضرت ابوہریرہ رضی اللہ عنہ کی روایت کو ترجیح دی ہے کیونکہ حضرت وائلرضی اللہ عنہ کی روایت پر عمل کرنے سے اونٹ سے مشابہت ہوتی ہے اور اس مشابہت سے روکا گیا ہے۔ لیکن صحیح بات یہ ہے کہ ہاتھ پہلے رکھنے چاہئیں گھٹنے بعد میں کیونکہ یہ فطرت انسانیہ کے مطابق ہے۔ اللہ تعالی ٰنے انسان کو سہمارے کے لیے ہاتھ دیے ہیں۔ جانور تو مجبور ہیں کہ ان کے پاس ہاتھ نہیں ہیں، لہٰذا وہ بغیر سہارے کے بیٹھتے اٹھتے ہیں بلکہ سب کام بغیر ہاتھوں کے کرتے ہیں: کھانا، پینا، مارنا وغیرہ۔ مگر انسان کے لیے ہاتھوں کا استعمال ضروری ہے ورنہ جانوروں سے مشابہت ہو جائے گی۔ حدی ثمیں اونٹ کا ذکر ہے۔ اونٹ بیٹھتے وقت پہلے گھٹنے زمین پر رکھتا ہے۔ اگر گھٹنے پہلے رکھے جائیں تو ہاتھوں کا سہارا نہ ہونے کی وجہ سے گھٹنے اونٹ کی طرح زمین پر ٹکیں گے۔ بوڑھوں کے لیے مشکل بھی ہے اور چوٹ لگنے یا گرنے کا خطرہ بھی، لہٰذا اٹھتے بیٹھتے وقت ہاتھوں کا سہارا چاہیے، یعنی بیٹھتے وقت پہلے ہاتھ رکھیں، پھر گھٹنے اور اٹھتے وقت پہلے گھٹنے اٹھائیں، پھر ہاتھ۔ یاد رہے! اونٹ (بلکہ سب جانوروں) کے گھٹنے اگلے پاؤں میں ہتے ہیں، شکلا بھی، فعلا بھی، اور پچھلی ٹانگیں انسانوں کے بازوؤں جیسی ہوتی ہیں۔ چونکہ اونٹ سیدھا گھٹنوں پر بیٹھتا ہے، اس لیے اس کا خاص ذکر کیا گیا ہے اور اس کی مشابہت سے روکا گیا ہے۔ واللہ أعلم۔"}],[1092,"عبداللہ بن عمر رضی اللہ عنہم کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"دونوں ہاتھ سجدہ کرتے ہیں جس طرح چہرہ سجدہ کرتا ہے، لہٰذا جب تم میں کا کوئی اپنا چہرہ زمین پر رکھے تو اپنے دونوں ہاتھ بھی رکھے، اور جب اسے اٹھائے تو ان دونوں کو بھی اٹھائے\"۔","الألباني: صحيح",{"u2":"حضرت ابن عمر رضی اللہ عنہما سے روایت ہے اور انھوں نے اسے رسول اللہ صلی اللہ علیہ وسلم کی طرف منسوب کیا ہے کہ آپ نے فرمایا: ’’تحقیق دونوں ہاتھ چہرے کی طرح سجدہ کرتے ہیں۔ جب تم میں سے کوئی شخص اپنا چہرہ زمین پر رکھے تو اپنے دونوں ہاتھ بھی رکھے اور جب چہرہ اٹھائے تو انھیں بھی اٹھا لے۔‘‘","f2":"مقصود یہ ہے کہ سجدے میں صرف چہرہ زمین پر لگانا کافی نہیں بلکہ دونوں ہاتھ بھی زمین پر چہرے کے ارد گرد رکھے ہونے چاہئیں تاکہ ان کا بھی سجدہ ہوسکے۔ اگلی روایت میں اس کی مزید وضاحت ہے۔"}],[1093,"عبداللہ بن عباس رضی اللہ عنہم کہتے ہیں کہ نبی اکرم صلی اللہ علیہ وسلم کو حکم دیا گیا کہ آپ سات اعضاء ۱؎ پر سجدہ کریں، اور اپنے بال اور کپڑے نہ سمیٹیں ۲؎۔\n§وضاحت\n۱؎: سات اعضاء سے مراد پیشانی ناک کے ساتھ، دونوں ہاتھ، دونوں گھٹنے اور دونوں پاؤں ہیں، جیسا کہ اگلی حدیث میں اس کی تفسیر آ رہی ہے۔ ۲؎: بالوں کو سمیٹنا یہ ہے کہ سب کو اکٹھا کر کے جوڑا باندھ لے، یا دستار میں رکھ لے، اور کپڑوں کا سمیٹنا یہ ہے کہ سجدے یا رکوع میں جاتے وقت کپڑوں کو اس خیال سے سمیٹے کہ کپڑوں میں گرد نہ لگے۔","الألباني: صحيح",{"u2":"حضرت ابن عباس رضی اللہ عنہما سے روایت ہے، انھوں نے فرمایا: نبی صلی اللہ علیہ وسلم کو حکم دیا گیا کہ سات اعضاء پر سجدہ کریں اور نماز کے دوران میں اپنے بالوں اور کپڑوں کو اکٹھا نہ کریں۔","f2":"(۱) سات اعضاء، یعنی دو ہاتھ، دو گھٹنے، دو پاؤں اور چہرہ، یعنی پیشانی (ناک سمیت) یہ سب اعضاء زمین پر لگنے چاہئیں۔ تھوڑی دیر کے لیے کوئی عضو کسی وجہ سے اٹھ جائے تو الگ بات ہے۔ مجموعی طور پر سجدہ ان سات اعضاء کے ساتھ ہونا چاہیے۔ (۲) سجدے میں جاتے وقت بال یا کپڑوں کو مٹی سے بچانے کے لیے اکٹھا نہیں کرنے چاہئیں بلکہ انھیں زمین پر لگنے دیں۔ اس عاجزی پیدا ہوگی، تکبر کی نفی ہوگی، نیز وہ بھی سجدہ کرتے ہیں، اکٹھا کرنے سے ان کا سجدہ نہیں ہوگا۔"}],[1094,"عباس بن عبدالمطلب رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"جب بندہ سجدہ کرتا ہے تو اس کے ساتوں اعضاء: اس کا چہرہ، اس کے دونوں ہاتھ، دونوں گھٹنے، اور دونوں پیر بھی سجدہ کرتے ہیں\" ۱؎۔\n§وضاحت\n۱؎: ناک چہرہ کا ایک جزء ہے اس لیے پیشانی اور ناک دونوں سے سجدہ کرنا ضروری ہے۔","الألباني: صحيح",{"u2":"حضرت عباس بن عبدالمطلب رضی اللہ عنہ سے مروی ہے، انھوں نے رسول اللہ صلی اللہ علیہ وسلم کو یہ فرماتے سنا: ’’جب انسان سجدہ کرتا ہے تو اس کے ساتھ سات اعضاء سجدہ کرتے ہیں: اس کا چہرہ، اس کی دو ہتھیلیاں، اس کے دو گھٹنے اور اس کے دو پاؤں۔‘‘","f2":"چہرے سے مراد، ناک سمیت پیشانی ہے جیسا کہ اگلی روایات سے واضح ہے۔"}],[1095,"ابو سعید خدری رضی اللہ عنہ کہتے ہیں کہ میری آنکھوں نے رسول اللہ صلی اللہ علیہ وسلم کو دیکھا کہ (رمضان کی) اکیسویں رات کی صبح کو آپ کی پیشانی اور ناک پر پانی اور مٹی کا نشان تھا، یہ ایک لمبی حدیث کا اختصار ہے ۱؎۔\n§وضاحت\n۱؎: تفصیل سے یہی حدیث باب السہو :(۱۳۵۷ ) میں وارد ہوئی ہے۔","الألباني: صحيح",{"u2":"حضرت ابو سعید خدری رضی اللہ عنہ سے منقول ہے، فرمایا: (رمضان المبارک کی) اکیسویں رات کی صبح کو میری آنکھوں نے رسول اللہ صلی اللہ علیہ وسلم کے ماتھے اور ناک پر پانی اور مٹی، یعنی کیچڑ کے نشانات دیکھے۔ یہ روایت مختصر ہے۔","f2":"سجدے میں ماتھے کا زمین پر لگنا ضروری ہے کیونکہ سجدے کے معنی ہی ماتھا زمین پر رکھنا ہیں، الا یہ کہ کوئی عذر ہو، مثلاً: پھوڑا پھنسی ہو یا کمر یا سر میں تکلیف ہو یا آنکھ کا آپریشن کرایا ہو یا اس کے علاوہ جو چیزی بھی ماتھا زمین پر رکھنے سے مانع ہو۔"}],[1096,"عبداللہ بن عباس رضی اللہ عنہم سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"مجھے حکم دیا گیا ہے کہ سات اعضاء: پیشانی اور ناک، دونوں ہتھیلی، دونوں گھٹنے، اور دونوں پیر پر سجدہ کروں، اور بال اور کپڑے نہ سمیٹوں\"۔","الألباني: صحيح",{"u2":"حضرت ابن عباس رضی اللہ عنہما سے روایت ہے، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’مجھے حکم دیا گیا ہے کہ میں سات اعضاء پر سجدہ کروں اور میں بال اور کپڑے نہ سمیٹوں۔ (سات اعضاء یہ ہیںJ ماتھا اور ناک، دو ہاتھ، دو گھٹنے اور دو قدم۔‘‘","f2":"اس حدیث میں ماتھا اور ناک ایک عضو شمار کیے گئے ہیں۔ گویا دونوں مل کر ایک عضو بنتے ہیں کیونکہ دونوں ایک عضو، یعنی چہرے کے اجزا ہیں، لہٰذا دونوں کو زمین پر لگنا چاہیے۔ امام ابوحنیفہ رحمہ اللہ کے نزدیک دونوں میں سے کسی ایک کا لگنا کافی ہے کیونکہ کوئی عضو بھی مکمل تو لگ نہیں سکتا، کچھ حصہ ہی لگتا ہے۔ جب یہ دونوں ایک عضو ہیں تو پھر ان دونوں میں سے کسی ایک کا کچھ حصہ لگنا کافی ہے مگر احادیث اس موقف کی تائید نہیں کرتیں۔ صحیح بات یہی ہے کہ دونوں کو لگنا چاہیے۔"}],[1097,"عبداللہ بن عباس رضی اللہ عنہم کہتے ہیں کہ نبی اکرم صلی اللہ علیہ وسلم نے فرمایا: \"مجھے سات ہڈیوں پر سجدہ کرنے کا حکم دیا گیا ہے: پیشانی پر، اور آپ نے اپنے ہاتھ سے ناک پر کا اشارہ کیا، اور دونوں ہتھیلیوں، دونوں گھٹنے، اور دونوں پیر کے کناروں یعنی انگلیوں پر۔","الألباني: صحيح",{"u2":"حضرت ابن عباس رضی اللہ عنہما سے روایت ہے، نبی صلی اللہ علیہ وسلم نے فرمایا: ’’مجھے حکم دیا گیا ہے کہ میں سات اعضاء پر سجدہ کروں: ماتھے پر‘‘ اور (یہ کہتے ہوئے) آپ نے اپنی ناک کی طرف اشارہ کیا ’’دونوں ہاتھوں پر، دونوں گھٹنوں پر اور دونوں پاؤں کے اطراف پر۔‘‘","f2":"اس روایت میں ’’عظم‘‘ کا لفظ ہے جس کے معنی ہڈی کے ہوتے ہیں مگر مراد عضو ہی ہے اگرچہ ایک عضو کئی ہڈیوں اور جوڑوں پر مشتمل ہو، مثلاً: ہاتھ، پاؤں وغیرہ۔"}],[1098,"عبداللہ بن عباس رضی اللہ عنہم سے روایت ہے کہ نبی اکرم صلی اللہ علیہ وسلم کو سات اعضاء پر سجدہ کرنے کا حکم دیا گیا، اور بالوں اور کپڑوں کو سمیٹنے سے روکا گیا: اپنی دونوں ہتھیلیوں، دونوں گھٹنے اور انگلیوں کے سروں پر۔ سفیان کہتے ہیں: ابن طاؤس نے اپنے دونوں ہاتھ پیشانی پر رکھے، اور انہیں اپنی ناک پر گزارا، اور کہا: یہ سب ایک ہے۔ امام نسائی کہتے ہیں: یہ الفاظ محمد بن منصور کے ہیں۔","الألباني: صحيح",{"u2":"حضرت ابن عباس رضی اللہ عنہما سے مروی ہے، نبی صلی اللہ علیہ وسلم کو حکم دیا گیا کہ پ سات اعضاء پر سجدہ کریں ……… اور آپ کو بال اور کپڑے سمیٹنے سے روکا گیا ……… دونوں ہاتھوں پر، دونوں گھٹنوں پر اور دونو پاؤں کی انگلیوں کے کناروں پر۔ (حدیث کے راوی) سفیان نے کہا: ابن طاؤس نے اپنے دونوں ہاتھ اپنی پیشانی پر رکھے اور انھیں ناک پر سے گزارا اور فرمایا: یہ ایک عضو ہے۔ (امام نسائی نے فرمایا) یہ (امام نسائی نے فرمایا) لفظ (میرے استاذ) محمد بن منصور کے ہیں۔","f2":"امام نسائی رحمہ نے یہ روایت دو استادوں سے سنی۔ ایک محمد بن منصور اور دوسرے عبداللہ بن محمد ہیں۔ روایت میں بیان کردہ الفاظ محمد بن منصور کے ہیں۔ عبداللہ بن محمد کے الفاظ اس سے کچھ مختلف ہوسکتے ہیں، اگرچہ معنی دونوں کے ایک ہی ہیں۔"}],[1099,"عباس بن عبدالمطلب رضی اللہ عنہ سے روایت ہے کہ انہوں نے رسول اللہ صلی اللہ علیہ وسلم کو فرماتے سنا: \"جب بندہ سجدہ کرتا ہے تو اس کے ساتھ اس کے ساتوں اعضاء یعنی اس کا چہرہ، دونوں ہتھیلی، دونوں گھٹنے اور دونوں پیر سجدہ کرتے ہیں\"۔","الألباني: صحيح",{"u2":"حضرت عباس بن عبدالمطلب رضی اللہ عنہ سے مروی ہے کہ انھوں نے رسول اللہ صلی اللہ علیہ وسلم کو فرماتے سنا: ’’جب بندہ سجدہ کرتا ہے تو اس کے ساتھ سات اعضاء سجدہ کرتے ہیں: اس کا چہرہ، اس کے دونوں ہاتھ (ہتھیلیاں) اس کے دونوں گھٹنے اور اس کے دونوں قدم۔‘‘"}],[1100,"ام المؤمنین عائشہ رضی اللہ عنہا کہتی ہیں کہ ایک رات مجھے رسول اللہ صلی اللہ علیہ وسلم بستر پہ نہیں ملے تو میں تلاش کرتی ہوئی آپ تک پہنچی، آپ سجدے میں تھے، آپ کے دونوں قدم کھڑے تھے، اور آپ یہ دعا پڑھ رہے تھے: «اللہم إني أعوذ برضاك من سخطك وبمعافاتك من عقوبتك وبك منك لا أحصي ثناء عليك أنت كما أثنيت على نفسك» \"اے اللہ! میں پناہ مانگتا ہوں تیری رضا مندی کی تیری ناراضگی سے، تیرے عفو و درگزر کی تیری سزا اور عقوبت سے، اور تیری پناہ چاہتا ہوں تیرے غضب سے، میں تیری تعریف کی طاقت نہیں رکھتا، تو ویسے ہی ہے جیسے تو نے اپنی تعریف بیان کی ہے\"۔","الألباني: صحيح",{"u2":"حضرت عائشہ رضی اللہ عنہا فرماتی ہیں کہ میں نے ایک رات رسول اللہ صلی اللہ علیہ وسلم کو بستر پر نہ پایا۔ (میں نے ٹٹولنا شروع کیا) میرا ہاتھ آپ کو لگا تو آپ سجدے میں تھے اور آپ کے دونوں پاؤں کھڑے تھے اور آپ پڑھ رہے تھے: [اللھم! انی اعوذ برضاک……… کما اثئیت علی نفسک] ’’اے اللہ! میں تیرے غصے سے (بچنے کے لیے) تیری رضا مندی کی پناہ میں آتا ہوں اور تیری سزا سے (بچنے کے لیے) تیری معافی کی پناہ میں آتا ہوں اور تجھ (تیرے عذاب) سے (بچنے کے لیے) تیری (رحمت کی) پناہ میں آتا ہوں۔ میں تیری پوری تعریف نہیں کرسکتا۔ تو اسی طرح ہے جس طرح تو نے ود اپنی تعریف کی ہے۔‘‘","f2":"سجدے کی حالت میں فطری طور پر پاؤں کھڑے ہی ہوتے ہیں۔ اس فطرت کو قائم رہنا چاہیے، یعنی پاؤں کو کسی ایک طرف بچھایا نہ جائے بلکہ پاؤں سیدھے کھڑے ہوں اور ایڑیاں ملی ہوئی ہوں، درمیان میں فاصلہ نہ ہو۔ انگلیاں جس قدر مڑ سکیں انھیں قبلہ رخ موڑ لیا جائے۔ جو نہ مڑ سکیں انھیں زمین پر لگا لیا جائے۔ چھوٹی انگلیاں زمین پر نہ لگ سکیں تو کوئی حرج نہیں۔"}],[1101,"ابو حمید ساعدی رضی اللہ عنہ کہتے ہیں کہ نبی اکرم صلی اللہ علیہ وسلم جب سجدہ کرنے کے لیے زمین کی طرف جھکتے تو اپنے بازوؤں کو اپنی بغل سے الگ رکھتے، اور اپنے پیر کی انگلیوں کو کھلا رکھتے - یہ ایک لمبی حدیث کا اختصار ہے۔","الألباني: صحيح",{"u2":"حضرت ابو حمید ساعدی رضی اللہ عنہ بیان کرتے ہیں کہ نبی صلی اللہ علیہ وسلم جب سجدہ کرتے ہوئے زمین پر گرتے تو اپنے بازو بغلوں سے دور رکھتے اور اپنے پاؤں کی انگلیوں کو (قبلے کی طرف) موڑ لیتے۔ یہ روایت مختصر ہے۔"}],[1102,"وائل بن حجر رضی اللہ عنہ کہتے ہیں کہ میں مدینہ آیا تو میں نے (اپنے جی میں) کہا کہ میں رسول اللہ صلی اللہ علیہ وسلم کی نماز ضرور دیکھوں گا (کہ آپ کیسے نماز پڑھتے ہیں تو میں نے دیکھا) آپ صلی اللہ علیہ وسلم نے اللہ اکبر کہا، اور اپنے دونوں ہاتھ اٹھائے یہاں تک کہ میں نے آپ کے دونوں انگوٹھوں کو آپ کی دونوں کانوں کے قریب دیکھا، اور جب آپ نے رکوع کرنے کا ارادہ کیا تو \"اللہ اکبر\" کہا، اور اپنے دونوں ہاتھ اٹھائے، پھر آپ نے رکوع سے اپنا سر اٹھایا، اور «سمع اللہ لمن حمده» کہا، پھر آپ نے \"اللہ اکبر\" کہا، اور سجدہ کیا، آپ کے دونوں ہاتھ آپ کی دونوں کانوں کی اس جگہ تک اٹھے جہاں تک آپ نے شروع نماز میں انہیں اٹھایا تھا (یعنی انہیں دونوں کانوں کے بالمقابل اٹھایا)۔","الألباني: صحيح",{"u2":"حضرت وائل بن حجر رضی اللہ عنہ بیان کرتے ہیں کہ میں مدینہ منورہ آیا تو میں نے (اپنے دل میں) کہا کہ میں رسول اللہ صلی اللہ علیہ وسلم کی نماز کو بغور دیکھوں گا۔ (میں نے دیکھا کہ) آپ نے اللہ اکبر کہا اور اپنے ہاتھ اٹھائے حتی کہ میں نے آپ کے اگنوٹھے آپ کے کانوں کے قریب دیکھے۔ جب آپ نے رکوع کرنے کا ارادہ کیا تو اللہ أکبر کہا اور اپنے دونوں ہاتھ اٹھائے، پھر اپنا سر (رکوع سے) اٹھایا تو آپ نے کہا: [سمع اللہ لمن حمدہ] پھر اللہ اکبر کہا اور سجدہ کیا تو آپ کے دونوں ہاتھ کانوں سے اسی جگہ تھے جہاں نماز شروع کرتے وقت تھے۔ (یعنی کانوں کے برابر تھے)۔","f2":"آغاز نماز میں رفع الیدین کانوں کے برابر بھی کیا جا سکتا ہے اور کندھوں کے برابر بھی۔ اسی طرح سجدے میں ہاتھ کانوں کے برابر بھی رکھے جا سکتے ہیں اور کندھوں کے برابر بھی اور اس تطبیق کے مطابق بھی جو رفع الیدین کے بارے میں بیان ہوچکی ہے۔"}],[1103,"انس رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"تم میں کوئی شخص سجدے میں اپنے دونوں بازو (زمین پر) کتے کے بچھانے کی طرف نہ بچھائے\"۔","الألباني: حسن صحيح",{"u2":"حضرت انس رضی اللہ عنہ سے روایت ہے، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’تم میں سے کوئی آدمی سجدے کی حالت میں اپنے ازو اس طرح زمین پر نہ پھیلائے جس طرح کتا پھیلاتا ہے۔‘‘","f2":"نماز میں بلکہ عموماً بھی جانوروں کی مشابہت منع ہے، خصوصاً حرام جانوروں کی۔ کتاب جب زمنی پر بیٹھتا یا لیٹتا ہے تو اپنے گلے بازو زمین پر بچھا لیتا ہے۔ نمازی کو اپنے بازو زمین سے، رانوں سے اور پہلو سے اٹھا کر دور رکھنے چاہئیں۔"}],[1104,"ابواسحاق سبیعی کہتے ہیں کہ براء رضی اللہ عنہ نے ہمیں سجدہ کر کے دکھایا تو انہوں نے اپنے دونوں ہاتھ زمین پر رکھے، اور اپنی سرین اٹھائے رکھی، اور کہا: میں نے رسول اللہ صلی اللہ علیہ وسلم کو ایسے ہی کرتے دیکھا ہے۔","الألباني: ضعيف",{"u2":"حضرت ابو اسحاق نے کہا کہ حضرت براء بن عازب نے ہمیں سجدہ کرنے کا طریقہ بیان کیا تو اپنے دونوں ہاتھ زمین پر رکھے، سرین کو اونچا کیا اور فرمایا: میں نے رسول اللہ صلی اللہ علیہ وسلم کو اسی طرح (سجدہ) کرتے دیکھا ہے۔"}],[1105,"براء رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم جب نماز پڑھتے تو اپنے دونوں بازو کھلا رکھتے، اور انہیں اپنے پہلوؤں سے دور رکھتے، اور اپنا پیٹ زمین سے اٹھائے رکھتے۔","الألباني: صحيح",{"u2":"حضرت براء بن عازب رضی اللہ عنہ سے مروی ہے، رسول اللہ صلی اللہ علیہ وسلم جب نماز میں سجدہ کرتے تو اپنے دونوں بازو کھولتے، انھیں اپنے پہلوؤں سے دور رکھتے اور پیٹ کو زمین سے اونچا رکھتے۔","f2":"’’کھولتے‘‘ کا مطلب یہ ہے کہ بازوؤں کو پہلوؤں سے دور رکھتے، زمین سے بھی اونچا رکھتے اور پیٹ کو رانوں سے اٹھا کر رکھتے۔ سجدہ زمین پر بچھ کر نہیں کرنا چاہیے بلکہ اونچا رہے۔ اس مسئلے میں مرد اور عورت کا کوئی فرق نہیں۔ بعض فقہاء نے خالص رائے کے ساتھ عورت کے لیے مینڈک کی طرح زمین سے چمٹ کر سجدہ کرنا تجویز کیا ہے، مگر یاد رکھنا چاہیے کہ دین کسی کی رائے کی بنیاد پر نہیں بلکہ وحی کی بنیاد پر قائم ہوا ہے، اس لیے صراحتاً منقول چیز کے مقابلے میں رائے کا استعمال مذموم اور ایسا قول مردود ہے۔ تفصیل کے لیے ملاحظہ ہو، حافظ صلاح الدین یوسف حفظہ اللہ کی تالیف ’’کیا مرد اور عورت کی نماز میں فرق ہے؟‘‘ طبع دارالسلام۔"}],[1106,"عبداللہ بن مالک ابن بحینہ رضی اللہ عنہم سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم جب نماز پڑھتے تو اپنے دونوں ہاتھوں کے بیچ کشادگی رکھتے، یہاں تک کہ آپ کے بغل کی سفیدی ظاہر ہو جاتی۔","الألباني: صحيح",{"u2":"حضرت عبداللہ بن مالک ابن بحینہ رضی اللہ عنہ سے منقول ہے کہ رسول اللہ صلی اللہ علیہ وسلم جب نماز میں سجدہ فرماتے تو اپنے بازو کھولتے حتی کہ آپ کی بغلوں کی سفیدی نظر آتی۔","f2":"نبی صلی اللہ علیہ وسلم بغلوں کے بال صاف رکھتے تھے، اس لیے سفید چمڑا نظر آتا تھا یا بالوں کے اردگرد کی سفیدی مراد ہوگی۔ واللہ أعلم۔"}],[1107,"ابوہریرہ رضی اللہ عنہ کہتے ہیں کہ اگر میں رسول اللہ صلی اللہ علیہ وسلم کے سامنے ہوتا تو میں آپ کی دونوں بغل ضرور دیکھتا ہوتا ۱؎۔ ابومجلز کہتے ہیں کہ گویا انہوں نے یہ بات اس وجہ سے کہی ہے کیونکہ وہ نماز میں موجود تھے۔\n§وضاحت\n۱؎: مطلب یہ ہے کہ آپ صلی اللہ علیہ وسلم سجدے میں اپنے دونوں ہاتھ اس قدر کشادہ رکھتے کہ آپ کی دونوں بغل کی سفیدی دکھائی دیتی۔","الألباني: صحيح",{"u2":"حضرت ابوہریرہ رضی اللہ عنہ بیان کرتے ہیں کہ اگر میں (مقتدی ہونے کی بجائے) رسول اللہ صلی اللہ علیہ وسلم کے سامنے ہوتا تو میں (آپ کے سجدہ فرمانے کے وقت) آپ کی بغلیں دیکھ لیتا۔ ابومجلز (راوی) نے کہا: معلوم ہوتا ہے، ابوہریرہ رضی اللہ عنہ اس وقت نماز میں تھے، اس لیے یوں فرمایا۔"}],[1108,"عبداللہ بن اقرم رضی اللہ عنہ کہتے ہیں کہ میں نے رسول اللہ صلی اللہ علیہ وسلم کے ساتھ نماز پڑھی، جب آپ سجدہ کرتے تو مجھے آپ کی دونوں بغل کی سفیدی نظر آتی۔","الألباني: صحيح",{"u2":"حضرت عبداللہ بن اقرم رضی اللہ عنہ بیان کرتے ہیں کہ میں نے رسول اللہ صلی اللہ علیہ وسلم کے ساتھ نمازیں پڑھیں۔ جب آپ سجدہ فرماتے تو میں آپ کی بغلوں کی سفیدی دیکھتا تھا۔"}],[1109,"ام المؤمنین میمونہ رضی اللہ عنہا سے روایت ہے کہ نبی اکرم صلی اللہ علیہ وسلم جب سجدہ کرتے تو اپنے ہاتھ اپنے پہلو سے جدا رکھتے یہاں تک کہ اگر کوئی بکری کا بچہ آپ کے ہاتھوں کے نیچے سے گزرنا چاہتا تو گزر جاتا۔","الألباني: صحيح",{"u2":"حضرت میمونہ رضی اللہ عنہا سے روایت ہے کہ نبی صلی اللہ علیہ وسلم جب سجدہ فرماتے تو اپنے دونوں ہاتھوں کو اتنا کشادہ رکھتے کہ اگر بھیڑ بکری کا چھوٹا سا بچہ آپ کے بازوؤں کے نیچے سے گزرنا چاہتا تو گزر سکتا تھا۔","f2":"(۱)ہاتھوں کو پہلوؤں سے خوب دور رکھنا چاہیے، اسی طرح پیٹ کو رانوں سے اٹھا کر رکھنا چاہیے۔ (۲) یہ ہیئت خشوع و خضوع اور تواضع کے زیادہ قریب ہے۔ (۳) امہات المومنین کی فضیلت کہ انھوں نے نبیٔ اکرم صلی اللہ علیہ وسلم کے طریقۂ عبادت کو بغور دیکھا اور سمجھا، بعد ازاں امت تک ایسے واضح انداز سے پہنچایا کہ کسی قسم کا ابہام باقی نہ رہا……… رضی اللہ عنھن………"}],[1110,"انس رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"سجدے میں اپنی ہیئت درمیانی رکھو ۱؎ اور تم میں سے کوئی اپنے دونوں ہاتھوں کو کتے کی طرح نہ پھیلائے\" - یہ الفاظ اسحاق بن راہویہ کے ہیں۔\n§وضاحت\n۱؎: سجدہ میں اپنی ہیئت درمیانی رکھنے کا مطلب یہ ہے کہ دونوں ہتھیلیوں کو زمین پر رکھے، اور کہنیوں کو زمین سے اور پیٹ کو ران سے الگ رکھے۔","الألباني: صحيح",{"u2":"حدیث انس رضی اللہ عنہ سے مروی ہے، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’سجدے میں اعتدال اختیار کرو اور کئوی شخص اپنے بازو اس طرح زمین پر نہ بچھائے جس طرح کتا بچھاتا ہے۔‘‘ یہ لفظ حضرت اسحاق بن ابراہیم کے ہیں۔","f2":"اس وضاحت کی ضرورت اس لیے پیش آئی کہ اس روایت کو امام نسائی رحمہ اللہ نے دو سندوں سے بیان کیا ہے۔ دونوں سندیں حضرت قتادہ پر متفق ہوتی ہیں۔ پہلی سند حضرت اسحاق بن ابراہیم سے ہے اور دوسری حضرت اسماعیل بن مسعود سے۔ (مزید دیکھیے، حدیث: ۱۰۲۹)"}],[1111,"ابومسعود رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"وہ نماز کفایت نہیں کرتی جس میں آدمی رکوع اور سجدے میں اپنی پیٹھ سیدھی نہ رکھے\"۔","الألباني: صحيح",{"u2":"حضرت ابو مسعود رضی اللہ عنہ سے منقول ہے، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’وہ نماز درست نہیں ہوتی جس میں نمازی رکوع اور سجدے کے دوران میں اپنی کمر کو سیدھا نہ کرے۔‘‘","f2":"دیکھیے حدیث نمبر ۱۰۲۸۔"}],[1112,"عبدالرحمٰن بن شبل رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے تین باتوں سے منع کیا ہے: ایک کوے کی طرح ٹھونگ مارنے سے، دوسری درندوں کی طرح ہاتھ بچھانے سے، اور تیسری یہ کہ آدمی نماز کے لیے ایک جگہ خاص کر لے جیسے اونٹ اپنے بیٹھنے کی جگہ کو خاص کر لیتا ہے۔","الألباني: حسن",{"u2":"حضرت عبدالرحمٰن بن شبل رضی اللہ عنہ سے مروی ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے تین چیزوں سے منع فرمایا: کوے کی طرح ٹھونگیں مارنے سے، درندے کی طرح بازو بچھانے سے اور آدمی نماز کے لیے ایک ہی جگہ مقرر کرلے، جیسے اونٹ (بیٹھنے کے لیے) ایک جگہ مقرر کر لیتا ہے۔","f2":"(۱)مذکورہ روایت کو محقق کتاب نے سنداً ضعیف قرار دیا ہے جبکہ دیگر محققین نے اسے شواہد کی بنا پر حسن قرار دیا ہے، نیز علامہ اتیوبی شارح سنن النسائی نے مذکورہ حدیث کے پہلے اور دوسرے جز کو شاہد کی بنا پر صحیح قرار دیا ہے اور شیخ البانی اور شارح سنن النسائی نے اس پر تفصیلی بحث کی ہے جس سے معلوم ہوتا ہے کہ مذکورہ روایت سنداً ضعیف ہونے کے باوجود معنا صحیح ہے۔ تفصیل کے لیے دیکھیے: (سلسلۃ الأحادیث الصحیحۃ: ۱۵۷،۱۵۶/۳، رقم: ۱۱۶۸، و ذخیرۃ العقبی شرح سنن النسائی: ۳۴۳-۳۳۷/۱۳) (۲) کوے کی طرح ٹھونگیں مارنے سے مراد بہت ہلکا سجدہ کرنا ہے حتی کہ دیکھنے والا سمجھے ٹھونگیں مار رہا ہے۔ بلکہ سجدے میں کم از کم تین دفعہ تسبیح پڑھنی چاہیے۔ یہ نہیں کہ ایک تسبیح جاتےہوئے، دوسری تسبیح سجدے میں اور تیسری اٹھتے ہوئے پڑھے کیونکہ یہ تو حقیقتاً سجدے میں ایک دفعہ تسبیح ہے۔ (۳) بازو بچھانے سے مراد یہ ہے کہ سجدے یمں بازو زمین پر رکھ دے جس طرح کتا وغیرہ لیٹنے کی حالت میں زمین پر اپنے بازو کھول کر رکھ دیتا ہے اور منہ بھی زمین پر رکھ لیتا ہے۔ (۴) ایک جگہ مقرر کرنے سے مراد یہ ہے کہ وہ کسی اور جگہ نماز نہ پڑھے حتی کہ اگر کوئی دوسرا شخص اس جگہ آکھڑا ہو تو اسے ہٹا کر وہاںکھڑا ہو یا اس سے ناراض ہو، البتہ امام اور مؤذن اس سے مستثنیٰ ہیں کہ ان کے لیے مجبوری ہے۔"}],[1113,"عبداللہ بن عباس رضی اللہ عنہم سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"مجھے حکم دیا گیا ہے کہ میں سات اعضاء پر سجدہ کروں، اور بال اور کپڑے نہ سمیٹوں\"۔","الألباني: صحيح",{"u2":"حضرت ابن عباس رضی اللہ عنہما سے مروی ہے، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’مجھے حکم دیا گیا ہے کہ میں سات اعضاء پر سجدہ کروں اور (سجدے میں جاتے وقت) بال اور کپڑے نہ سمیٹوں۔‘‘","f2":"عرب لوگ عموماً سر کے بال بڑے رکھتے تھے اور کھلی آستینوں والی قمیص پہنتے تھے۔ سجدے میں جاتے تو بالوں اور آستینوں کو مٹی سے بچانے کے لیے یعض لوگ بالوں کو بار بار سمیٹتے اور انھیں اکٹھا کرتے یا انھیں سر پر کچھے کی صورت میں باندھ لیتے۔ اسی طرح وہ آستینیں چڑھا لیتے چونکہ یہ غیر ضروری حرکت ہے جو نماز میں منع ہے، لہٰذا اس سے روک دیا گیا، البتہ اگر پہلے سے بال باندھ لیے گئے ہوں یا آستینیں چڑھالی گئی ہوں اور نماز کے دوران میں کچھ نہ کیا جائے تو بعض علماء کے نزدیک جائز ہے مگر اگلی حدیث ان کے موقف کی تردید کرتی ہے۔ معلوم ہوتا ہے کہ نماز میں مٹی سے بچنے کی قصداً کوشش کرنا تکبر کے ذیل میں آتا ہے بلکہ ہر عضو کو جو زمین پر لگتا ہے، لگنے دے۔ مٹی کا لگنا تکبر کی نفی ہے اور طبیعت میں تواضع پیدا ہوتی ہے ورنہ نمازی کس کس چیز کو مٹی سے بچائے گا؟ چہرے کو؟ ہاتھوں کو؟ گھٹنوں کو؟ پاؤں کو؟ ازار کو؟ پگڑی کو؟ مٹی تو ضرور ہی لگے گی۔"}],[1114,"عبداللہ بن عباس رضی اللہ عنہم سے روایت ہے کہ انہوں نے عبداللہ بن حارث رضی اللہ عنہ کو اس حالت میں نماز پڑھتے دیکھا کہ ان کے سر میں پیچھے جوڑا بندھا ہوا تھا، تو وہ کھڑے ہو کر اسے کھولنے لگے، جب عبداللہ بن حارث رضی اللہ عنہ سلام پھیر چکے تو ابن عباس رضی اللہ عنہم کے پاس آئے، اور کہنے لگے: آپ کو میرے سر سے کیا مطلب تھا؟ تو انہوں نے کہا کہ میں نے رسول اللہ صلی اللہ علیہ وسلم کو فرماتے سنا ہے: \"اس کی مثال اس آدمی جیسی ہے جو نماز پڑھ رہا ہو اور اس کے ہاتھ بندھے ہوں\"۔","الألباني: صحيح",{"u2":"حضرت عبداللہ بن عباس رضی اللہ عنہما نے عبداللہ بن حارث کو نماز پڑھتے دیکھا جب کہ وہ سر کے بالوں کا جوڑا بنا کر اسے پیچھے باندھے ہوئے تھے۔ آپ اٹھے اور بالوں کا جوڑا (گچھا) کھولنے لگے۔ عبداللہ بن حارث نماز سے فارغ ہوئے تو ابن عباس رضی اللہ عنہما کی طرف متوجہ ہوکر کہنے لگے: آپ کو میرے بالوں سے کیا شکایت تھی؟ (جو آپ نے انھیں کھولا) انھوں نے فرمایا: میں نے رسول اللہ صلی اللہ علیہ وسلم کو یہ فرماتے ہوئے سنا: ’’اس قسم کے نمازی کی مثال اس شخص کی طرح ہے جو پیچھے بندھے ہوئے ہاتھوں (کسی مشکوں) سے نماز پڑھتا ہے۔‘‘","f2":"(۱)جس طرح پیچھے بندھے ہوئے ہاتھوں والا بہت ناقص نماز پڑھتا ہے، اسی طرح بندھے ہوئے بالوں والا اپنے بالوں کو ثواب سے محروم رکھتا ہے، بخلاف اس کے اگر وہ بال زمین پر لگتے تو ان کا بھی سجدہ شمار ہوتا اور انھیں ثواب ملتا۔ گویا نماز سے پہلے بھی بالوں کا جوڑا نہیں بنا ہونا چاہیے، چہ جائیکہ کوئی نماز میں ایسے کرے۔ (۲) خلاف شرع کام ہوتا دیکھ کر موقع ہی پر تنبیہ کر دینی چاہیے، خواہ مخواہ یا بالکل سکوت نہیں کرنا چاہیے۔ (۳) برائی کو ہاتھ سے مٹانے کی طاقت ہو تو اسے ہاتھ سے مٹا دینا چاہیے۔ (۴) خبر واحد حجت ہے۔"}],[1115,"عبداللہ بن عباس رضی اللہ عنہم کہتے ہیں کہ نبی اکرم صلی اللہ علیہ وسلم کو سات ہڈیوں پر سجدہ کرنے کا حکم دیا گیا ہے، اور بال اور کپڑے سمیٹنے سے منع کیا گیا ہے۔","الألباني: صحيح",{"u2":"حضرت ابن عباس رضی اللہ عنہما بیان کرتے ہیں کہ نبی کو حکم دیا گیا کہ سات اعضاء پر سجدہ کریں اور منع کیا گیا بال یا کپڑے اکٹھے کرنے (سمیٹنے) سے۔","f2":"اگر کپڑا پہلے سے اکٹھا کیا ہوا ہے جیسا نماز سے قبل آستینیں چڑھائی جائیں تو بعض علماء کے نزدیک کوئی حرج نہیں لیکن حدیث کے الفاظ میں اس مفہوم کی گنجائش نہیں ہے، لہٰذا پہلے بھی ایسے نہ کیا جائے۔"}],[1116,"انس رضی اللہ عنہ کہتے ہیں کہ جب ہم رسول اللہ صلی اللہ علیہ وسلم کے پیچھے ظہر کی نماز پڑھتے تو گرمی سے بچنے کے لیے اپنے کپڑوں پر سجدہ کرتے تھے۔","الألباني: صحيح",{"u2":"حضرت انس رضی اللہ عنہ فرماتے ہیں کہ جب ہم رسول اللہ صلی اللہ علیہ وسلم کے پیچھے دوپہر کے وقت سخت گرمی میں نماز پڑھتے تو گرمی سے بچنے کے لیے اپنے کپڑوں پر سجدہ کر لیا کرتے تھے۔","f2":"اگر الگ کپڑا مراد ہے جیسے آج کل مصلیٰ وغیرہ ہوتا ہے تو پھر ظاہر ہے کوئی اشکال و اعتراض نہیں۔ ان پر بلاشک و شبہ نماز پڑھی جا سکتی ہے، البتہ اگر پہنے ہوئے کپڑے مراد ہوں، مثلاً: آستینیں آگے بڑھا کر ان پر ہاتھ رکھ لیے جائیں اور پگڑی نیچے کرکے اس پر ماتھا رکھ لیا جائےتو ضرورت کے وقت یہ بھی جائز ہے، مثلاً: سخت گرمی یا سردی سے بچنا،البتہ مٹی سے چہرے اور ہتھیلیوں کو بچانے کے لیے ایسا کرنا ممنوع ہے کہ یہ تکلف ہے جبکہ سری گرمی سے بچنا انسان کی ضرورت ہے۔"}],[1117,"انس رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"تم رکوع اور سجدہ پوری طرح کرو، اللہ کی قسم! میں اپنی پیٹھ کے پیچھے سے تمہیں رکوع اور سجدہ کی حالت میں دیکھتا ہوں\"۔","الألباني: صحيح",{"u2":"حضرت انس رضی اللہ عنہ سے روایت ہے، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا:’’رکوع اور سجدہ مکمل کرو۔ اللہ کی قسم! میں تمھیں اپنے پیچھے تمھارے رکوع اور سجدے میں دیکھتا ہوں۔‘‘","f2":"(۱)رکوع اور سجدہ نماز کی جان ہیں۔ انھیں پورے پداب و سنن سمیت ادا کرنا انھیں مکمل کرنا ہے۔ اعتدال و اطمینان اختیار کیا جائے۔ سجدے کو کھلا کیا جائے۔ تسبیحات و اذکار خشوع و خضوع سے کیے جائیں۔ (۲) رکوع اور سجدے کی حالت میں نبی صلی اللہ علیہ وسلم کا پیچھے مقتدیوں کو دیکھ لینا، آپ کا معجزہ تھا۔ بعض نے اسے کنکھیوں سے دیکھنے سے تعبیر کیا ہے لیکن یہ صحیح نہیں۔ کنکھیوں سے زیادہ دور تک نہیں دیکھا جا سکتا، جب کہ آپ کا فرمان مطلق ہے، یعنی سب نمازیوں کو آپ دیکھ سکتے تھے، صرف چند افراد کو نہیں۔"}],[1118,"علی بن ابی طالب رضی اللہ عنہ کہتے ہیں کہ مجھے میرے محبوب صلی اللہ علیہ وسلم نے تین باتوں سے منع کیا ہے، میں نہیں کہتا کہ لوگوں کو بھی منع کیا ہے، مجھے سونے کی انگوٹھی پہننے سے، قسی کے بنے ہوئے ریشمی کپڑے پہننے سے، اور کُسم میں رنگے ہوئے گہرے سرخ کپڑے پہننے سے منع کیا ہے، اور میں رکوع اور سجدے کی حالت میں قرآن نہیں پڑھتا۔","الألباني: صحيح",{"u2":"حضرت علی بن ابو طالب رضی اللہ عنہ فرماتے ہیں کہ مجھے میرے حبیب صلی اللہ علیہ وسلم نے تین چیزوں سے منع فرمایا ہے، میں یہ نہیں کہتا کہ سب لوگوں کو منع فرمایا ہے، سونے کی انگوٹھی پہننے سے، قسی اور زعفرانی زرد رنگ کا کپڑا پہننے سے اور سجدے یا رکوع کی حالت میں قرآن مجید پڑھنے سے۔","f2":"فوائد کے لیے دیکھیے حدیث نمبر: ۱۰۴۱، ۱۰۴۲، ۱۰۴۳۔"}],[1119,"علی رضی اللہ عنہ کہتے ہیں کہ مجھے رسول اللہ صلی اللہ علیہ وسلم نے رکوع اور سجدے کی حالت میں قرآن پڑھنے سے منع کیا ہے۔","الألباني: صحيح",{"u2":"حضرت علی رضی اللہ عنہ فرماتے ہیں کہ مجھے رسول اللہ صلی اللہ علیہ وسلم نے رکوع اور سجدے کی حالت میں قرآن مجید پڑھنے سے روکا ہے۔"}],[1120,"عبداللہ بن عباس رضی اللہ عنہم کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے اپنی اس بیماری میں جس میں آپ کی وفات ہوئی پردہ ہٹایا، آپ کا سر مبارک کپڑے سے بندھا ہوا تھا، آپ صلی اللہ علیہ وسلم نے تین بار فرمایا: \"اے اللہ! میں نے پہنچا دیا (پھر فرمایا:) نبوت کی خوش خبر یوں میں سے سوائے سچے خواب کے جسے بندہ خود دیکھتا ہے یا اس کے لیے کوئی اور دیکھتا ہے کوئی اور چیز باقی نہیں رہ گئی ہے، سنو! مجھے رکوع اور سجدے میں قرآن پڑھنے سے منع کیا گیا ہے، تو جب تم رکوع کرو تو اپنے رب کی عظمت بیان کرو، اور جب سجدہ کرو تو دعا میں کوشش کرو کیونکہ یہ حالت اس لائق ہے کہ تمہاری دعا قبول کی جائے\"۔","الألباني: صحيح",{"u2":"حضرت عبداللہ بن عباس رضی اللہ عنہما فرماتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے اپنے مرض وفات میں گھر کی کھڑکی کا پردہ ہٹایا۔ آپ کا سر مبارک پٹی سے باندھا ہوا تھا۔ آپ نے فرمایا: ’’اے اللہ! میں نے تیرا دین لوگوں تک پہنچا دیا (تین دفعہ فرمایا۔) اے لوگو! نبوت کے ذریعے سے خوش خبری دینے والی چیزوں میں سے صرف نیک خواہب ہی رہ گئے ہیں جنھیں کوئی شخص دیکھ لے یا اس کے لیے کسی دوسرے کو نظر آئیں۔ خبردار! مجھے رکوع اور سجدے میں قرآن مجید پڑھنے سے روک دیا گیا ہے، لہٰذا جب تم رکوع کرو تو اپنے رب کی عظمت بیان کرو (تسبیحات پڑھو) اور جب سجدہ کرو تو پوری کوشش سے دعا کرو کیونکہ سجدے کی دعا قبولیت کے بہت لائق ہے۔‘‘","f2":"فوائد کے لیے دیکھیے، حدیث نمبر: ۱۰۴۶۔"}],[1121,"عبداللہ بن عباس رضی اللہ عنہم کہتے ہیں کہ میں نے اپنی خالہ ام المؤمنین میمونہ بنت حارث رضی اللہ عنہا کے پاس رات گزاری، اور رسول اللہ صلی اللہ علیہ وسلم بھی اس رات کو ان ہی کے پاس رہے، میں نے آپ کو دیکھا کہ آپ اپنی حاجت کے لیے اٹھے، مشک کے پاس آئے، اور اس کا بندھن کھولا، پھر وضو کیا جو دو وضوؤں کے درمیان تھا، (یعنی شرعی وضو نہیں تھا)، پھر آپ اپنے بستر پہ آئے، اور سو گئے، پھر دوسری بار اٹھے، مشک کے پاس آئے، اور اس کا بندھن کھولا، پھر وضو کیا یہ(شرعی) وضو تھا، پھر آپ صلی اللہ علیہ وسلم اٹھ کر نماز پڑھنے لگے، آپ اپنے سجدے میں یہ دعا پڑھ رہے تھے: «اللہم اجعل في قلبي نورا واجعل في سمعي نورا واجعل في بصري نورا واجعل من تحتي نورا واجعل من فوقي نورا وعن يميني نورا وعن يساري نورا واجعل أمامي نورا واجعل خلفي نورا وأعظم لي نورا» \"اے اللہ! میرے دل کو منور کر دے، میرے کانوں کو نور (روشنی) سے بھر دے، میری آنکھوں کو روشن کر دے، میرے نیچے نور کر دے، میرے اوپر نور کر دے، میرے دائیں نور کر دے، میرے بائیں نور کر دے، میرے آگے نور کر دے، میرے پیچھے نور کر دے، اور میرے لیے نور کو عظیم کر دے\"، پھر آپ سو گئے یہاں تک کہ خراٹے لینے لگے، پھر بلال رضی اللہ عنہ آئے، اور آپ صلی اللہ علیہ وسلم کو نماز کے لیے جگایا۱؎۔\n§وضاحت\n۱؎: حدیث سے ظاہر ہوتا ہے کہ یہ دعا آپ نے تہجد کے سجدے میں پڑھی تھی، اس لیے تہجد یا نوافل میں اس طرح کی لمبی دعائیں پڑھے، فرائض میں خصوصاً جب امام ہو تو مختصر دعائیں پڑھے جن میں سے بعض کا تذکرہ آگے آ رہا ہے، ان میں سے معروف دعا «سبحان ربي الأعلی» ہے۔","الألباني: صحيح",{"u2":"حضرت ابن عباس رضی اللہ عنہما سے روایت ہے کہ میں نے اپنی خالہ میمونہ بنت حارث رضی اللہ عنہما کے گھر رات گزاری۔ رسول اللہ صلی اللہ علیہ وسلم بھی ان کے پاس وہیں آرام فرما تھے۔ میں نے آپ صلی اللہ علیہ وسلم کو دیکھا کہ آپ قضائے حاجت کے لیے اٹھے۔ پھر آپ مشکیزے کے پاس آئے، اس کا بند کھولا، پھر درمیانہ سا وضو کیا۔ پھر اپنے بستر پر تشریف لائے اور سو گئے۔ پھر دوبارہ اٹھے اور مشکیزے کے پاس گئے، اس کا بند کھولا، پھر مکمل وضو فرمایا، پھر کھڑے ہوکر نماز پڑھنے لگے۔ آپ اپنے سجدے میں کہتے تھے: [اللھم! اجعل فی قلبی ……… واعظم لی نورا] ’’اے اللہ! میرے دل کو منور فرما۔ میرے کان منور فرما۔ میری آنکھیں روشن کر دے۔ مجھ پر اوپر نیچے سے نور برسا۔ میرے دائیں بائیں کو منور فرما۔ مجھے آگے پیچھے سے پرنور فرما اور مجھے عظیم نور عطا فرما۔‘‘ پھر (نماز مکمل کرنے کے بعد) آپ سو گئے حتی کہ خراٹے بھرنے لگے۔ کچھ دیر بعد حضرت بلال رضی اللہ عنہ آئے اور پ کو نماز کے لیے جگایا۔","f2":"(۱) حضرت ابن عباس رضی اللہ عنہما نے نبی صلی اللہ علیہ وسلم کی نماز دیکھنے کے لیے قصداً یہ رات آپ صلی اللہ علیہ وسلم کے حجرۂ مبارکہ میں گزاری تھی اور اس کے لیے باقاعدہ حضرت میمونہ رضی اللہ عنہما اور ان کے توسط سے رسول اللہ صلی اللہ علیہ وسلم سے اجازت طلب کی تھی۔ (۲) درمیانہ وضو سونے کے لیے تھا۔ نماز کے لیے ہوتا تو آپ مکمل وضو فرماتے جیسا کہ بعد میں کیا۔ (۳) یہاں نور سے مراد علم، ہدایت اور ایمان ہے کیونکہ قرآن مجید اور احادیث میں متعدد مقامات پر لفظ نور ان معانی میں استعمال ہوا ہے۔"}],[1122,"ام المؤمنین عائشہ رضی اللہ عنہا کہتی ہیں کہ رسول اللہ صلی اللہ علیہ وسلم اپنے رکوع اور سجدے میں «سبحانك اللہم ربنا وبحمدك اللہم اغفر لي\"اے اللہ! ہمارے رب! تو پاک ہے اور ہم تیری تعریف کے ساتھ تیری تسبیح بیان کرتے ہیں، اے اللہ تو مجھے بخش دے\"کہہ رہے تھے، آپ قرآن کی عملی تفسیر فرما رہے تھے ۱؎۔\n§وضاحت\n۱؎: کیونکہ قرآن میں اللہ تعالی کا ارشاد ہے: «فسبح بحمد ربک» \" آپ اپنے رب کی حمد کے ساتھ تسبیح کیجئے \" آپ اسی حکم کی تعمیل میں یہ دعا پڑھ رہے تھے۔","الألباني: صحيح",{"u2":"حضرت عائشہ رضی اللہ عنہما فرماتی ہیں کہ رسول اللہ صلی اللہ علیہ وسلم اپنے رکوع اور سجدے میں یہ پڑھا کرتے تھے: [سبحانک اللھم! ربنا وبحمدک اللھم! اغفرلی] ’’اے اللہ! ہمارے رب! تو ہر قسم کے عیوب و نقائص سے پاک ہے اور تمام خوبیوں کا حامل ہے۔ اے اللہ! مجھے معاف فرم۔‘‘ آپ قرآن پر عمل کرتے تھے۔\nحضرت عائشہ رضی اللہ عنہا فرماتی ہیں: رسول اللہ صلی اللہ علیہ وسلم اپنے رکوع اور سجدے میں یہ دعا پڑھتے تھے: [سبحانک اللھم! ربنا و بحمدک اللھم! اغفرلی] ’’اے اللہ! ہمارے رب! تو ہر قسم کے عیوب و نقائص سے پاک ہے اور ہر قسم کی خوبیوں اور تعریفوں والا ہے۔ اے اللہ! مجھے معاف فرما۔‘‘ آپ قرآن پر عمل فرماتے تھے۔","f2":"رسول اللہ صلی اللہ علیہ وسلم کی حیات طیبہ ک آخری زمانے میں سورۃ النصر اتری جس میں اشارہ فرمایا گیا کہ آپ جس مقصد کے لیے تشریف لائے تھے، وہ پورا ہوچکا۔ اب آپ ساری توجہ اپنے رب کی تسبیح و تحمید کی طرف مبذول فرمائیں اور بخشش طلب کریں۔ آپ کی وفات قریب ہے۔ رسول اکرم صلی اللہ علیہ وسلم نے ان ہدایات کے پیش نظر رکوع اور سجدے میں م ندرجہ بالا دعا کثرت سے شروع فرمائی۔ حضرت عائشہ رضی اللہ عنہا کے الفاظ: [یتاول القرآن] ’’آپ قرآن پر عمل کرتے تھے۔‘‘ میں اسی کی طرف اشارہ ہے۔\nبعض نسخوں میں اس دعا میں آخری لفظ [اللھم اغفرلی] نہیں ہے۔ اس لحاظ سے یہ پچھلی حدیث کی دعا سے مختلف ہے۔ ہمارے نسخے کے لحاظ سے دونوں میں کوئی فرق نہیں جب کہ فرق ہونا چاہیے تاکہ ’’اور قسم کی دعا‘‘ بن سکے۔ واللہ اعلم۔"}],[1123,"ام المؤمنین عائشہ رضی اللہ عنہا کہتی ہیں کہ رسول اللہ صلی اللہ علیہ وسلم رکوع اور سجدے میں «سبحانك اللہم ربنا وبحمدك اللہم اغفر لي» \"اے اللہ ہمارے رب! تو پاک ہے اور ہم تیری تعریف کے ساتھ تیری تسبیح بیان کرتے ہیں، اے اللہ تو مجھے بخش دے\" کہہ رہے تھے، آپ صلی اللہ علیہ وسلم قرآن کی عملی تفسیر فر مار ہے تھے۔","الألباني: صحيح"],[1124,"ام المؤمنین عائشہ رضی اللہ عنہا کہتی ہیں کہ ایک رات رسول اللہ صلی اللہ علیہ وسلم مجھے اپنی خواب گاہ میں نہیں ملے، تو میں آپ کو تلاش کرنے لگی، اور مجھے گمان ہوا کہ شاید آپ اپنی کسی لونڈی کے پاس چلے گئے ہیں کہ اچانک میرا ہاتھ آپ پر پڑا، آپ سجدے میں تھے، اور کہہ رہے تھے: «اللہم اغفر لي ما أسررت وما أعلنت» \"اے اللہ! بخش دے میرے ان گناہوں کو جنہیں میں نے چھپا کر کیا ہے اور جنہیں میں نے اعلانیہ کیا ہے\"۔","الألباني: صحيح",{"u2":"حضرت عائشہ رضی اللہ عنہا فرماتی ہیں: (ایک دفعہ) میں نے رسول اللہ صلی اللہ علیہ وسلم کو بستر پر نہ پایا تو میں آپ کو ڈھونڈنے لگی۔ میں نے خیال کیا کہ آپ اپنی کسی لونڈی کے پاس چلے گئے ہوں گے۔ (میں نے ٹٹولنا شروع کیا) تو میرا ہاتھ آپ کو لگا۔ آپ سجدے کی حالت میں تھے اور پڑھ رہے تھے: [اللھم! اغفرلی ما اسررت وما اعلنت] ’’اے اللہ! میرے گناہ معاف فرما جو میں نے چھپ کر کیے اور جو میں نے علانیہ کیے۔‘‘","f2":"حضرت عائشہ رضی اللہ عنہا کا یہ گمان عورت کی فطرت کے مطابق ہے ورنہ رسول اللہ صلی اللہ علیہ وسلم سب سے زیادہ محبت حضرت عائشہ سے فرماتے تھے۔ دیکھیے: (صحیح البخاری، فضائل اصحاب النبی صلی اللہ علیہ وسلم، حدیث: ۳۶۶۲، و صحیح مسلم، فضائل الصحابۃ، حدیث: ۲۳۸۴) آپ انھیں چھوڑ کر کہاں جاسکتے تھے؟ دراصل یہ دلیل ہے کہ حضرت عائشہ رضی اللہ عنہا کو بھی رسول اللہ صلی اللہ علیہ وسلم سے انتہا درجے کی محبت تھی۔ اس قسم کے ایک اور موقع پر آپ نے فرمایا تھا، ’’کیا تو سمجھتی ہے کہ اللہ اور اس کا رسول تجھ پر ظلم کریں گے؟‘‘ (صحیح مسلم، الجنائز، حدیث: ۹۷۴)"}],[1125,"ام المؤمنین عائشہ رضی اللہ عنہا کہتی ہیں کہ میں نے ایک رات رسول اللہ صلی اللہ علیہ وسلم کو اپنے بستر پر موجود نہیں پایا، میں نے گمان کیا کہ شاید آپ اپنی کسی لونڈی کے پاس چلے گئے ہیں، چنانچہ میں نے آپ کو تلاش کیا، تو کیا دیکھتی ہوں کہ آپ سجدہ میں ہیں اور کہہ رہے ہیں: «رب اغفر لي ما أسررت وما أعلنت»\"اے میرے رب! میرے تمام گناہوں کو جو میں نے چھپے اور کھلے کئے ہیں بخش دے\"۔","الألباني: صحيح",{"u2":"حضرت عائشہ رضی اللہ عنہا سے روایت ہے، انھوں نے فرمایا: (ایک رات) میں نے رسول اللہ صلی اللہ علیہ وسلم کو نہ پایا تو میں نے سمجھا کہ آپ اپنی کسی بیوی یا لونڈی کے پاس چلے گئے ہوں گے۔ میں نے آپ کو تلاش کرنا شروع کر دیا تو آپ سجدے میں تھے، یہ دعا فرما رہے تھے: ’’اے میرے رب! مجھے معاف فرما دے، وہ گناہ جو میں نے چھپ کر کیے اور جو میں نے علانیہ کیے۔‘‘","f2":"حدیث کے متن میں لفظ [جواری] ہے جس کے عام معنی لونڈیاں کیے جاتے ہیں۔ ویسے اس کے معنی بیوی بھی کیے جا سکتے ہیں کیونکہ یہ لفظ آزاد عورت کے لیے بھی احادیث میں استعمال ہوا ہے۔ لونڈی کی باری مقرر نہیں ہوتی جب کہ بیوی کی (اگر ایک سے زائد ہوں) باری مقرر ہوتی ہے، لہٰذا کسی بیوی کی باری کے دن اپنی لونڈی کے پاس جانا منع نہیں، دوسری بیوی کے پاس جانا منع ہے۔ شاید اسی لیے لونڈی کا لفظ بولا ورنہ بدگمانی کی کوئی حد نہیں ہوتی۔"}],[1126,"علی رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم جب سجدہ کرتے تو کہتے: «اللہم لك سجدت ولك أسلمت وبك آمنت سجد وجهي للذي خلقه وصوره فأحسن صورته وشق سمعه وبصره تبارك اللہ أحسن الخالقين» \"اے اللہ! میں نے تیرے لیے اپنی پیشانی زمین سے ٹیک دی، اور تیرے ہی لیے میں اسلام لایا، اور تجھی پر میں ایمان لایا، میرے چہرے نے سجدہ کیا، اس ذات کے لیے جس نے اسے پیدا کیا، اور اس کی صورت گری کی، اور اچھی صورت گری کی، اور جس نے اس کے کان اور اس کی آنکھیں پھاڑیں، اللہ بڑی برکت والا ہے، اور سب سے بہترین پیدا کرنے والا ہے\"۔","الألباني: صحيح",{"u2":"حضرت علی رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم جب سجدہ کرتے تو فرماتے: [اللھم! لک سحدت ……… احسن الخالقین] ’’اے اللہ! میں نے تیرےہی لیے سجدہ کیا اور تیرے ہی لیے مطیع ہوا اور تجھی پر ایمان لایا۔ میرے چہرے نے اس ذات کے لیے سجدہ کیا جس نے اسے پیدا کیا، اس کی صورت بنائی اور اچھی صورت بنائی اور اس میں کان اور آنکھیں بنائیں۔ بابرکت ہے اللہ جو سب سے بہتر پیدا کرنے والا ہے۔‘‘"}],[1127,"جابربن عبداللہ رضی اللہ عنہم کہتے ہیں کہ نبی اکرم صلی اللہ علیہ وسلم اپنے سجدے میں کہتے تھے: «اللہم لك سجدت وبك آمنت ولك أسلمت وأنت ربي سجد وجهي للذي خلقه وصوره وشق سمعه وبصره تبارك اللہ أحسن الخالقين» \"اے اللہ! میں نے تیرے لیے اپنی پیشانی زمین پر ٹیک دی، تیرے ہی اوپر ایمان لایا، تیرے ہی لیے میں مسلمان ہوا، تو ہی میرا رب ہے، میرے چہرہ نے اس ذات کے لیے سجدہ کیا جس نے اسے پیدا کیا، اور اس کی صورت گری کی، اور جس نے اس کے کان اور اس کی آنکھیں بنائیں، بڑی برکتوں والا ہے، اللہ سب سے بہترین پیدا کرنے والا ہے)۔","الألباني: صحيح الإسناد",{"u2":"حضرت جابر بن عبداللہ رضی اللہ عنہما سے مروی ہے کہ نبی صلی اللہ علیہ وسلم اپنے سجدے میں یہ پڑھتے تھے: [اللھم! لک سجدت ……… احسن الخالقین] ’’اے اللہ! میں نے تیرے ہی لیے سجدہ کیا اور تجھی پر ایمان لایا اور تیرے ہی لیے مطیع ہوا۔ تو میرا ہب ہے۔ میرے چہرے نے اس ذات کے لیے سجدہ کیا جس نے اسے پیدا کیا اور اس کی صورت بنائی اور اس میں کان اور آنکھیں بنائیں۔ بابرکت ہے اللہ تعالیٰ جو سب سے بہتر پیدا کرنے والا ہے۔‘‘"}],[1128,"محمد بن مسلمہ رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم جب رات میں اٹھتے تو نفل پڑھتے، اور جب سجدہ کرتے تو کہتے: «اللہم لك سجدت وبك آمنت ولك أسلمت اللہم أنت ربي سجد وجهي للذي خلقه وصوره وشق سمعه وبصره تبارك اللہ أحسن الخالقين»\"اے اللہ! میں نے تیرے ہی لیے سجدہ کیا، تجھی پر میں ایمان لایا، تیرے لیے میں مسلمان ہوا، اے اللہ! تو ہی میرا رب ہے، میرے چہرہ نے اس ذات کے لیے سجدہ کیا جس نے اسے پیدا کیا، اور اس کی صورت گری کی، اور اس کے کان اور اس کی آنکھیں بنائیں، اللہ بڑی برکتوں والا، سب سے بہترین پیدا کرنے والا ہے\"۔","الألباني: صحيح الإسناد",{"u2":"حضرت محمد بن مسلمہ رضی اللہ عنہ سے منقول ہے کہ رسول اللہ صلی اللہ علیہ وسلم جب رات کو اٹھتے تو نفل پڑھتے۔ جب سجدہ کرتے تو کہتے: [اللھم لک سجدت ……… احسن الخالقین] ’’اے اللہ! میں نے تیرے ہی لیے سجدہ کیا، تجھی پر ایمان لایا، اپنے آپ کو تیرے سپرد کیا۔ اے اللہ! تو میرا رب ہے۔ میرے چہرے نے اس ذات کے لیے سجدہ کیا جس نے اسے پیدا کیا اور اس کی صورت بنائی اور اس میں آنکھ اور کان بنائے۔ بابرکت ہے اللہ سب سے بہتر پیدا کرنے والا۔‘‘"}],[1129,"ام المؤمنین عائشہ رضی اللہ عنہا سے روایت ہے کہ نبی اکرم صلی اللہ علیہ وسلم رات کو تلاوت قرآن کے سجدوں میں کہتے: «سجد وجهي للذي خلقه وشق سمعه وبصره بحوله وقوته» \"میرے چہرہ نے سجدہ کیا اس ذات کے لیے جس نے اسے پیدا کیا، اور اس کے کان اور اس کی آنکھیں اپنی قوت و طاقت سے بنائیں\"۔","الألباني: صحيح",{"u2":"حضرت عائشہ رضی اللہ عنہا سے منقول ہے کہ نبی صلی اللہ علیہ وسلم رات کی نماز میں سجدۂ تلاوت کے دوران میں یہ دعا پڑھتے تھے: [سجد وجھی للذی خلقہ …… وقوتہ] ’’میرے چہرے نے اس ذات کے لیے سجدہ کیا جس نے اسے پیدا کیا اور اپنی تدبیر اور قوت سے اس میں آنکھ اور کان پیدا کیے۔‘‘","f2":"مذکورہ روایت کو محقق کتاب نے سنداً ضعیف قرار دیا ہے اور مزید لکھا ہے اس حدیث کا شاہد صحیح مسلم وغیرہ میں ہے۔ بنا بریں معلوم ہوا کہ مذکورہ روایت سنداً ضعیف ہونے کے باوجود شواہد کی بنا پر صحیح اور قابل عمل ہے۔ واللہ اعلم۔"}],[1130,"ام المؤمنین عائشہ رضی اللہ عنہا کہتی ہیں کہ ایک رات میں نے رسول اللہ صلی اللہ علیہ وسلم کو (بستر پر) موجود نہیں پایا، تو دیکھا کہ آپ سجدے کی حالت میں ہیں، اور آپ کے دونوں قدموں کے پنجے قبلہ رخ ہیں، تو میں نے آپ کو سجدہ میں کہتے سنا: «أعوذ برضاك من سخطك وأعوذ بمعافاتك من عقوبتك وأعوذ بك منك لا أحصي ثناء عليك أنت كما أثنيت على نفسك» \"میں پناہ مانگتا ہوں تیری رضا مندی کی تیری ناراضگی سے، میں پناہ مانگتا ہوں تیری معافی کی تیری سزا سے، اور میں پناہ مانگتا ہوں تیری تجھ سے، میں تیری حمد و ثنا کا حق نہیں ادا کر سکتا، تو ایسے ہی ہے جیسے تو نے اپنی تعریف خود کی ہے\"۔","الألباني: صحيح",{"u2":"حضرت عائشہ رضی اللہ عنہا سے روایت ہے، فرماتی ہیں: ایک رات میں نے رسول اللہ صلی اللہ علیہ وسلم کو (بستر پر) نہ پایا۔ (تلاش کیا) تو آپ سجدے کی حالت میں ملے اور آپ کی انگلیاں قبلے کی طرف مڑی ہوئی تھیں۔ میں نے سنا، آپ فرما رہے تھے: [اعوذ برضاک من سخطک ……… علی نفسک] ’’(اے اللہ!) میں تیرے غصے سے (بچنے کے لیے) تیری رضا مندی کی پناہ میں آتا ہوں۔ اور تیری سزا سے (بچنے کے لیے) تیری معافی کی پناہ میں آتا ہوں۔ اور تجھ سے (تیرے عذاب سے بچنے کے لیے) تیری پناہ میں آتا ہوں۔ میں تیری پوری تعریف نہیں کرسکتا۔ تو اسی طرح ہے جس طرح تو نے خود اپنی تعریف کی ہے۔‘‘","f2":"اپنی تعریف آپ کرنا ہم میں معیوب ہے کیونکہ مبالغہ آرائی اور تکبر کا ڈر ہے۔ اللہ تعالیٰ کے حق میں ہر مبالغہ حقیقت ہے اور اللہ تعالیٰ ہر بزرگی اور بڑائی کا مالک ہے۔ اسے تکبر جچتا ہے، لہٰذا وہ اپنی تعریف آپ کرتا ہے۔"}],[1131,"ام المؤمنین عائشہ رضی اللہ عنہا کہتی ہیں کہ میں نے رسول اللہ صلی اللہ علیہ وسلم کو ایک رات (بستر پر) موجود نہیں پایا، تو میں نے گمان کیا کہ آپ اپنی کسی دوسری بیوی کے پاس چلے گئے ہیں، پھر میں نے آپ کو تلاش کیا تو اچانک کیا دیکھتی ہوں کہ آپ رکوع یا سجدہ کی حالت میں کہہ رہے ہیں: «سبحانك اللہم وبحمدك لا إله إلا أنت» \"اے اللہ! تو پاک ہے، میں تیری تعریف کے ساتھ تیری تسبیح بیان کرتا ہوں، نہیں ہے کوئی معبود برحق مگر تو ہی\"، تو وہ کہنے لگیں: میرے ماں باپ آپ پر فدا ہوں! میں کس خیال میں تھی اور آپ کس حال میں ہیں۔","الألباني: صحيح",{"u2":"حضرت عائشہ رضی اللہ عنہا سے روایت ہے، فرماتی ہیں: ایک رات میں نے رسول اللہ صلی اللہ علیہ وسلم کو (بستر پر) نہ پایا تو میں نے سوچا آپ اپنی کسی دوسری بیوی کے پاس گئے ہوں گے۔ میں نے آپ کو ٹٹولنا شرع کیا تو آپ رکوع یا سجدے کی حالت میں تھے اور پڑھ رہے تھے: [سبحانک اللھم! و بحمدک لا الہ الا انت] ’’اے اللہ! تو پاک ہے اور تعریفوں والا ہے۔ تیرے سوا کوئی سچا معبود نہیں۔‘‘ میں نے کہا: میرے ماں باپ آپ پر قربان! میں کس خیال میں تھی اور آپ کس شان میں ہیں؟","f2":"ان دنوں گھروں میں چراغ نہ ہوتے تھے۔ ہوں بھی تو بجھا کر سوتے تھے، اس لیے نوبت یہاں تک پہنچی۔"}],[1132,"عوف بن مالک رضی اللہ عنہ کہتے ہیں کہ میں نبی اکرم صلی اللہ علیہ وسلم کے ساتھ اٹھا، پہلے آپ نے مسواک کی، پھر وضو کیا، پھر کھڑے ہوئے اور نماز پڑھنے لگے، تو آپ نے سورۃ البقرہ شروع کی، آپ جب بھی کسی رحمت کی آیت سے گزرتے تو ٹھہرتے اور اللہ تعالی سے اس پر رحمت کا سوال کرتے، اور جب بھی عذاب کی کسی آیت سے گزرتے تو ٹھہرتے، اور اس کے عذاب سے اس کی پناہ مانگتے، پھر آپ نے رکوع کیا، تو رکوع میں اپنے قیام کے بقدر ٹھہرے رہے، آپ اپنے رکوع میں کہہ رہے تھے: «سبحان ذي الجبروت والملكوت والكبرياء والعظمة» پھر آپ نے اپنے رکوع کے بقدر سجدہ کیا، اور اپنے سجدے میں آپ کہہ رہے تھے: «سبحان ذي الجبروت والملكوت والكبرياء والعظمة»، پھر آپ نے دوسری رکعت میں سورۃ آل عمران پڑھی، پھر ایک اور سورۃ پڑھی، پھر ایک اور سورۃ پڑھی، آپ نے اسی طرح کیا۔","الألباني: صحيح",{"u2":"حضرت عوف بن مالک رضی اللہ عنہ بیان کرتے ہیں کہ میں نبی صلی اللہ علیہ وسلم کے ساتھ نماز کے لیے اٹھا۔ آپ نے سب سے پہلے مسواک فرمائی اور وضو کیا۔ پھر کھڑے ہوکر نماز شروع فرمائی۔ (سورۂ فاتحہ کے بعد) آپ نے سورۂ بقرہ شروع کی۔ آپ جب بھی کوئی رحمت والی آیت پڑھتے تو رکتے اور رحمت کا سوال فرماتے اور عذاب کی آیت پڑھتے تو رکتے اور عذاب سے پناہ مانگتے۔ پھر آپ نے رکوع فرمایا اور اپنے قیام کے برابر رکوع میں ٹھہرے۔ آپ رکوع میں یہ دعا پڑھتے: [سبحان ذی الجبروت و الملکوت والکبریاء و العظمۃ] ’’پاک ہے عظیم قوت، بادشاہی، بزرگی والا اور عظمت کا مالک۔‘‘ پھر آپ نے رکوع کے برابر سجدہ فرمایا اور اپنے سجدے میں بھی یہی پڑھتے رہے: ’’پاک ہے عظیم الشان قوت، بے مثال بادشاہی بے انتہا بزرگی اور عظمت کا مالک۔‘‘ پھر دوسری رکعت میں آپ نے آل عمران پڑھی۔ پھر ایک اور سورت، پھر ایک اور سورت اور اس (رکعت) میں بھی آپ نے (رکوع و سجود) ایسے ہی کیا۔"}],[1133,"حذیفہ رضی اللہ عنہ کہتے ہیں کہ میں نے ایک رات رسول اللہ صلی اللہ علیہ وسلم کے ساتھ نماز پڑھی، تو آپ نے سورۃ البقرہ شروع کر دی، آپ نے سو آیتیں پڑھ لیں لیکن رکوع نہیں کیا، اور آگے بڑھ گئے، میں نے اپنے جی میں کہا: لگتا ہے کہ آپ اسے دونوں رکعتوں میں ختم کر دیں گے، لیکن آپ برابر آگے بڑھتے رہے، تو میں نے اپنے جی میں کہا کہ آپ اسے ختم کر کے ہی پھر رکوع کریں گے، لیکن آپ سورت ختم کر کے آگے بڑھ گئے یہاں تک کہ پوری سورۃ نساء آپ نے پڑھ ڈالی، پھر سورۃ اٰل عمران بھی پڑھ ڈالی، پھر تقریباً اپنے قیام ہی کے برابر رکوع میں رہے، اپنے رکوع میں کہہ رہے تھے: «سبحان ربي العظيم سبحان ربي العظيم سبحان ربي العظيم» پھر آپ نے اپنا سر اٹھایا، اور «سمع اللہ لمن حمده ربنا لك الحمد» کہا، اور دیر تک کھڑے رہے، پھر آپ نے سجدہ کیا تو دیر تک سجدہ میں رہے، آپ سجدے میں کہہ رہے تھے: «سبحان ربي الأعلى سبحان ربي الأعلى سبحان ربي الأعلى» جب آپ کسی خوف کی یا اللہ تعالی کی بڑائی کی آیت پر سے گزرتے، تو اللہ کا ذکر کرتے یعنی اس کی حمد و ثنا کرتے۔","الألباني: صحيح",{"u2":"حضرت حذیفہ رضی اللہ عنہ فرماتے ہیں کہ میں نے ایک رات رسول اللہ صلی اللہ علیہ وسلم کے ساتھ نماز پڑھی۔ آپ نے (سورۂ فاتحہ کے بعد) سورۂ بقرہ شروع کی۔ آپ نے سو آیات پڑھ لیں مگر رکوع نہ فرمایا بلکہ قراءت جاری رکھی۔ میں نے سوچا: آپ دو رکعات میں پوری کرلیں گے مگر آپ نے قراءت جاری رکھی۔ میں نے (دل میں) کہا: یہ سورت ختم کرکے رکوع فرمائیں گے مگر آپ پڑھتے رہے حتی کہ سورۂ نساء بھی پڑھ ڈالی۔ پھر سورۂ آل عمران پڑھی، پھر تقریباً اپنے قیام کے برابر رکوع فرمایا۔ اپنے رکوع میں کہتے رہے: [سبحان ربی العظیم، سبحان ربی العظیم، سبحان ربی العظیم] پر سر اٹھایا اور فرمایا: [سمع اللہ لمن حمدہ ربنا لک الحمد] اور بہت دیر تک کھڑے (کچھ پڑھتے) رہے۔ پھر سجدہ فرمایا اور بہت لمبا سجدہ فرمایا۔ اور سجدے میں پڑھتے رہے: [سبحان ربی الاعلی، سبحان ربی الاعلی، سبحان ربی الاعلی] آپ جونہی کوئی ڈرانے والی یا اللہ تعالیٰ کی عظمت والی آیت پڑھتے تو (اس کے مناسب) دعا اور اللہ کا ذکر فرماتے۔","f2":"(۱) آپ نے سورۂ نساء پہلے پڑھی، آل عمران بعد میں۔ اس سے معلوم ہوا کہ قراءت میں سورتوں کی ترتیب میں تقدیم و تاخیر جائز ہے۔ (۲) اس حدیث میں رکوع اور سجدے کی مذکورہ تسبیحات مختصر اور جامع ہیں، اس لیے امت میں یہی رائج ہوچکی ہیں مگر اس کا یہ مطلب نہیں کہ فرض نماز میں ان کے علاوہ دوسری تسبیحات یا ادعیہ جائز ہی نہیں بلکہ اپنے ذوق اور جماعت کی صورت میں، مقتدیوں اور امام کا لحاظ رکھتے ہوئے کوئی سی تسبیحات پڑھی جا سکتی ہیں۔ (۳) قراءت قرآن کے وقت الفاظ و معانی کی طرف پوری توجہ دینا اور پھر ان سے متاثر ہونا، اللہ تعالیٰ کی رحمت و مغفرت کا سوال، سزا اور عذاب سے تعوذ، صالحین کی معیت اور مفسدین سے بچاؤ، دخول جنت اور جہنم سے نجات کی دعائیں کرنا نمازی کے خشوع خضوع کی دلیل ہے اور یہی نماز سے مطلوب ہے۔ اس میں فرض اور نفل نماز کا کوئی فرق نہیں، البتہ مقتدیوں کا لحاظ رکھنا چاہیے۔ (۴) کیا مقتدی بھی امام کی قراءت میں کسی سوال کا جواب، حکم کی بجا آوری اور رحمت کی دعا وغیرہ کرسکتے ہیں؟ علمائے امت کا اس میں اختلاف ہے۔ کچھ عدم جواز کے قائل ہیں اور کچھ نے عمومات سے استدلال کرتے ہوئے جواز کا فتویٰ دیا ہے۔ راجح بات یہ معلوم ہوتی ہے کہ صرف قاری جواب دے گا کیونکہ حدیث میں صرف رسول اللہ صلی اللہ علیہ وسلم کے جواب دینے کا ذکر ہے اور رسول اللہ صلی اللہ علیہ وسلم خود قراءت کر رہے تھے کیونکہ آپ امام تھے۔ اسی طرح منفرد بھی جواب دے گا کیونکہ وہ بھی خود قراءت کرتا ہے، مقتدی جواب نہیں دے گا کیونکہ وہ فاتحہ کے علاوہ قراءت نہیں کرتا۔ واللہ أعلم۔"}],[1134,"ام المؤمنین عائشہ رضی اللہ عنہا کہتی ہیں کہ رسول اللہ صلی اللہ علیہ وسلم اپنے رکوع اور سجدے میں «سبوح قدوس رب الملائكة والروح» \"تمام فرشتے اور جبرائیل کا رب ہر نقص و عیب سے پاک ہے\" کہتے۔","الألباني: صحيح",{"u2":"حضرت عائشہ رضی اللہ عنہا فرماتی ہیں: رسول اللہ صلی اللہ علیہ وسلم اپنے رکوع اور سجدے میں یہ تسبیح پڑھتے تھے: [سبوح قدوس رب الملائکۃ والروح] ’’بہت پاک ہے، منزہ ہے فرشتوں اور روح (جبریل امین) کا رب۔‘‘","f2":"فوائد کے لیے دیکھیے، حدیث نمبر: ۱۰۴۹۔"}],[1135,"سعید بن جبیر کہتے ہیں کہ میں نے انس بن مالک رضی اللہ عنہ کو کہتے سنا کہ میں نے اس نوجوان یعنی عمر بن عبدالعزیز سے بڑھ کر رسول اللہ صلی اللہ علیہ وسلم کی نماز کے مشابہ نماز کسی کی نہیں دیکھی، تو ہم نے ان کے رکوع میں دس تسبیحوں کا، اور سجدے میں بھی دس تسبیحوں کا اندازہ لگایا۔","الألباني: حسن الإسناد إن شاء الله",{"u2":"حضرت انس بن مالک رضی اللہ عنہ فرماتے ہیں کہ میں نے کسی کو اس جوان، یعنی حضرت عمر بن عبدالعزیز سے بڑھ کر رسول اللہ صلی اللہ علیہ وسلم کی نماز کے مشابہ نماز پڑھتے نہیں دیکھا۔ ہم نے رکوع اور سجدے میں ان کی تسبیحات کا اندازہ دس تسبیحات کا لگایا۔","f2":"اس اندازے میں چھوٹی تسبیحات، یعنی [سبحان ربی الاعلی] مراد ہیں۔ تین اور دس کے درمیان تسبیحات ایک درمیانے درجے کا رکوع اور سجدہ ہے۔ اسی پر عمل کرنے سے آدمی افراط و تفریط سے محفوظ رہ سکتا ہے۔ بعض روایات میں آپ صلی اللہ علیہ وسلم کا عمل تین تسبیحات کا ہے۔ جس سے استدلال کرتے ہوئے علمائے کرام کہتے ہیں کہ یہ تعداد کم از کم ہے۔ زیادہ سے زیادہ کی کوئی حد نہیں۔ واللہ أعلم۔"}],[1136,"رفاعہ بن رافع رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم بیٹھے تھے، اور ہم لوگ آپ کے اردگرد تھے، اتنے میں ایک شخص آیا اور وہ قبلہ رخ ہو کر نماز پڑھنے لگا، جب وہ اپنی نماز پوری کر چکا تو آیا، اور رسول اللہ صلی اللہ علیہ وسلم اور لوگوں کو سلام کیا، رسول اللہ صلی اللہ علیہ وسلم نے اس سے فرمایا: \"تم پر بھی سلامتی ہو، جاؤ پھر سے نماز پڑھو، کیونکہ تم نے نماز نہیں پڑھی\"، تو وہ گیا، اور اس نے جا کر پھر سے نماز پڑھی، اور رسول اللہ صلی اللہ علیہ وسلم اس کی نماز کو کنکھیوں سے دیکھ رہے تھے لیکن وہ یہ جان نہیں رہا تھا کہ اس میں وہ کیا غلطی کر رہا ہے؟ تو جب وہ اپنی نماز پوری کر چکا تو آیا، اور اس نے رسول اللہ صلی اللہ علیہ وسلم اور لوگوں کو سلام کیا، رسول اللہ صلی اللہ علیہ وسلم نے پھر اس سے فرمایا: \"تم پر بھی سلامتی ہو، جاؤ پھر سے نماز پڑھو، کیونکہ تم نے نماز نہیں پڑھی\"، چنانچہ اس نے دو یا تین بار نماز دہرائی، پھر اس شخص نے پوچھا: اللہ کے رسول! میری نماز میں آپ نے کیا خامی پائی ہے؟ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"تم میں سے کسی کی نماز پوری نہیں ہوتی جب تک کہ وہ اچھی طرح وضو نہ کر لے جس طرح اللہ تعالی نے اس کے کرنے کا حکم دیا ہے، وہ اپنا چہرہ دھوئے، اپنے دونوں ہاتھ کہنیوں سمیت دھوئے، اپنے سر کا مسح کرے، اور اپنے دونوں پیر ٹخنوں سمیت دھوئے، پھر اللہ تعالی کی بڑائی کرے (یعنی تکبیر تحریمہ کہے) اور اس کی حمد و ثناء اور بزرگی بیان کرے\" (یعنی دعائے ثناء پڑھے)۔ ہمام کہتے ہیں: میں نے اسحاق کو «ويحمد اللہ ويمجده ويكبره» بھی کہتے سنا ہے، وہ کہتے ہیں: میں نے دونوں طرح سے انہیں کہتے سنا ہے۔ آگے آپ صلی اللہ علیہ وسلم نے فرمایا: \"اور قرآن میں سے حسب توفیق اور مرضی الٰہی جو آسان ہو پڑھے، پھر \"اللہ اکبر\" کہے، اور رکوع کرے یہاں تک کہ اس کے تمام جوڑ اپنی جگہ آ جائیں، اور ڈھیلے پڑ جائیں، پھر «سمع اللہ لمن حمده» کہے، پھر سیدھا کھڑا ہو جائے یہاں تک اس کی پیٹھ برابر ہو جائے، پھر \"اللہ اکبر\" کہے، اور سجدہ کرے یہاں تک کہ وہ اپنا چہرہ زمین پر ٹکا دے\"، (میں نے اسحاق کو \"اپنی پیشانی بھی\" کہتے سنا ہے)، \"اور تمام جوڑ اپنی جگہ آ جائیں اور ڈھیلے پڑ جائیں، پھر اللہ اکبر کہے، اور اپنا سر اٹھائے یہاں تک کہ اپنی سرین پر سیدھا ہو کر بیٹھ جائے، اور اپنی پیٹھ سیدھی کر لے، پھر \"اللہ اکبر\" کہے، اور سجدہ کرے یہاں تک کہ وہ اپنا چہرہ زمین سے اچھی طرح ٹکا دے، اور ڈھیلا پڑ جائے، اگر اس نے اس طرح نہیں کیا تو اس کی نماز پوری نہیں ہوئی\" ۱؎۔\n§وضاحت\n۱؎: مؤلف نے اس سے سجدے میں تسبیحات نہ پڑھنے پر استدلال اس طرح کیا ہے کہ اس میں تسبیحات کا ذکر نہیں ہے، مگر آپ صلی اللہ علیہ وسلم نے اس میں دیگر بہت سی واجبات کا بھی ذکر نہیں کیا ہے، یہاں صرف تعدیل ارکان پر توجہ دلانا مقصود ہے۔","الألباني: صحيح",{"u2":"حضرت رفاعہ بن رافع رضی اللہ عنہ سے روایت ہے، فرماتے ہیں: ایک بار ایسا ہوا کہ رسول اللہ صلی اللہ علیہ وسلم (مسجد میں) بیٹھے تھے اور ہم آپ کے اردگرد (حلقہ باندھے ہوئے) تھے۔ اتنے میں ایک آدمی آیا اور وہ مسجد کی قبلے والی دیوار کے پاس جا کر نماز پڑھنے لگا۔ جب اس نے نماز مکمل کرلی تو وہ آیا اور رسول اللہ صلی اللہ علیہ وسلم کو اور سب لوگوں کو سلام کیا۔ رسول اللہ صلی اللہ علیہ وسلم نے سلام کا جواب دیا اور فرمایا: ’’جاپھر نماز پڑھ کیونکہ تو نے نماز نہیں پڑھی۔‘‘ وہ گیا اور پھر نماز پڑھی۔ رسول اللہ صلی اللہ علیہ وسلم اس کی نماز کو بغور دیکھتے رہے۔ اسے علم نہیں تھا کہ آپ اس کی کون سی غلطی پکڑ رہے ہیں۔ جب وہ نماز پڑھ چکا تو پھر آیا اور رسول اللہ صلی اللہ علیہ وسلم کو اور سب لوگوں کو سلام کیا۔ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’وعلیک، جا نماز پڑھ، تو نے نماز نہیں پڑھی۔‘‘ اس نے دو یا تین دفعہ نماز پڑھی۔ آخر اس نے کہا: اے اللہ کے رسول! آپ نے میری نماز میں کیا غلطی محسوس فرمائی ہے؟ آپ نے فرمایا: ’’تم میں سے کسی کی نماز مکمل نہیں ہوتی جب تک وہ اچھی طرح وضو نہ کرے جس طرح کہ اللہ تعالیٰ نے اسے حکم دیا ہے، یعنی وہ اپنا چہرہ اور کہنیوں تک ہاتھ دھوئے۔ اپنے سر کا مسح کرے اور ٹخنوں تک پاؤں دھوئے۔ پھر اللہ اکبر کہے اور اللہ عزوجل کی حمد اور بزرگی بیان کرے (ثنا پڑھے)۔ اور جو قرآن اسے آسان ہو، جو اسے اللہ تعالیٰ نے سکھلایا ہے اور اسے توفیق دی ہے، پڑھے۔ پھر اللہ اکبر کہہ کر رکوع کرے حتی کہ اس کے جوڑ مطمئن ہو جائیں اور اپنی موجودہ جگہ پر ٹھہر جائیں۔ پھر وہ (سمع اللہ لمن حمدہ) کہہ کر سیدھا کھڑا ہو جائے اور اپنی پشت کو بالکل اپنی اصلی حالت میں کرے۔ پھر اللہ اکبر کہہ کر سجدہ کرے حتی کہ اپنے چہرے کو اچھی طرح زمین پر جمائے حتی کہ اس کے جوڑ مطمئن اور پرسکون ہ جائیں اور اپنی اپنی جگہ ٹھہر جائیں۔ پھر اللہ اکبر کہہ کر سر اٹھائے اور مقعد (سرین) پر اچھی طرح بیٹھ جائے اور اپنی کمر کو بالکل سیدھا کرلے۔ پھر اللہ اکبر کہہ کر سجدہ کرے اور اپنے چہرے یا ماتھے کو زمین پر جمائے اور ٹکائے۔ جب تک (نماز میں) ایسے نہ کرے، اس کی نماز پوری نہیں ہوتی۔‘‘","f2":"اس روایت میں رکوع اور سجدے کی تسبیحات کا ذکر نہیں۔ اس سے مصنف رحمہ اللہ نے استنباط کیا ہے کہ تسبیحات فرض نہیں۔ ان کے بغیر بھی نماز ہو جاتی ہے لیکن عدم ذکر عدم وجود کو مستلزم نہیں۔ ہوسکتا ہے راوی نے کسی وجہ سے اس کی تفصیل ترک کر دی ہو، پھر اس میں کونسے تمام فرائض و واجبات کا احاطہ ہے۔ استنباط مسائل ہمیشہ ایک موضوع کی مجموعی احادیث دیکھ کر ہونا چاہیے، اس لیے تسبیحات ضرور پڑھنی چاہئیں۔ (مزید تفصیلات کے لیے دیکھیے، فوائد حدیث: ۱۰۵۴)"}],[1137,"ابوہریرہ رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"بندہ اپنے رب سے سب سے زیادہ قریب سجدہ کی حالت میں ہوتا ہے، لہٰذا(سجدے میں) تم لوگ بکثرت دعا کیا کرو\"۔","الألباني: صحيح",{"u2":"حضرت ابوہریرہ رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’بندہ اپنے رب عزوجل کے سب سے زیادہ قریب سجدے کی حالت میں ہوتا ہے، لہٰذا سجدے میں خوب دعا کیا کرو۔‘‘","f2":"(۱) نماز کا اصل مقصد سجدہ ہے، باقی تمہید اور خاتمہ ہے، لہٰذا سجدے میں مکمل سکون و اطمینان ہونا چاہیے۔ (۲) بعض حضرات دعا کے لیے نماز سے الگ صرف سجدے کو بھی مناسب خیال کرتے ہیں لیکن اس کا سنت سے ثبوت نہیں ملتا۔ ہاں سجدۂ شکر مسنون ہے۔ (۳) یہاں قرب سے جسمانی یا مکانی قرب مراد نہیں بلکہ رتبے اور عزت و شرف والا قرب مراد ہے کیونکہ شیطان سجدے سے انکار کرکے ذلیل و رسوا ہوا اور انسان شیطان کی مخالفت، یعنی سجدہ کرکے عزت و رتبہ حاصل کرسکتا ہے۔"}],[1138,"ربیعہ بن کعب اسلمی رضی اللہ عنہ کہتے ہیں کہ میں رسول اللہ صلی اللہ علیہ وسلم کے پاس آپ کے وضو اور آپ کی حاجت کا پانی لے کر آتا تھا، تو ایک بار آپ صلی اللہ علیہ وسلم نے فرمایا: \"جو مانگنا ہو مجھ سے مانگو\"، میں نے کہا: میں جنت میں آپ کی رفاقت چاہتا ہوں، آپ صلی اللہ علیہ وسلم نے فرمایا: \"اس کے علاوہ اور بھی کچھ؟\"میں نے عرض کیا: بس یہی، تو آپ صلی اللہ علیہ وسلم نے فرمایا: \"تو اپنے اوپر کثرت سجدہ کو لازم کر کے میری مدد کرو\" ۱؎۔\n§وضاحت\n۱؎: یعنی کثرت سے سجدے کیا کرو اس لیے کہ نماز کی عبادت اللہ تعالی کو بہت پسند ہے، شاید تمہاری کثرت سجود سے مجھے تمہارے لیے اپنی رفاقت کی سفارش کا موقع مل جائے۔","الألباني: صحيح",{"u2":"حضرت ربیعہ بن کعب اسلمی رضی اللہ عنہ بیان کرتے ہیں کہ میں رسول اللہ صلی اللہ علیہ وسلم کے پاس آپ کے وضو کا پانی اور دوسری ضروریات مہیا کیا کرتا تھا۔ آپ نے فرمایا: ’’مجھ سے (کچھ) مانگ۔‘‘ میں نے کہا: جنت میں آپ کی رفاقت مانگتا ہوں۔ آپ نے فرمایا: ’’کوئی اور چیز؟‘‘ میں نے کہا: بس یہی مانگتا ہوں۔ آپ نے فرمایا: ’’اس سلسلے میں تو سجدوں (نفل نماز) کی کثرت کے ذریعے سے میری مدد کر۔‘‘","f2":"(۱) ملوم ہوا صرف سفارش اور دوسروں کی دعا پڑھ اعتماد کافی نہیں بلکہ خود بھی کچھ مشکلات برداشت کرنی چاہئیں تاکہ سفارش اور دعا کا صحیح محل بن سکے۔ سفارش اور دعا کی وجہ جوازی بھی تو ہونی چاہیے۔ (۲) خشوع و خضوع کے ساتھ سجدہ اصلاح نفس کا بہترین نسخہ ہے جو نبی صلی اللہ علیہ وسلم نے تجویز فرمایا۔ (۳) جنت میں جانے کے لیے اصلاح نفس ازحد ضروری ہے۔ (۴) مراتب عالیہ کا حصول نفس امارہ کی مخالفت ہی سے ممکن ہے۔ (۵) اس حدیث مبارکہ سے نفلی نماز کی فضیلت بھی ثابت ہوتی ہے۔ (۶) جنت میں کچھ عام لوگ بھی انبیاء کے ساتھ ہوں گے۔"}],[1139,"معدان بن طلحہ یعمری کہتے ہیں کہ میں نے رسول اللہ صلی اللہ علیہ وسلم کے غلام ثوبان رضی اللہ عنہ سے ملاقات کی، تو میں نے کہا: مجھے کوئی ایسا عمل بتائیے جو مجھے فائدہ پہنچائے، یا مجھے جنت میں داخل کرے، وہ تھوڑی دیر خاموش رہے پھر میری طرف متوجہ ہوئے، اور کہنے لگے: تم سجدوں کو لازم پکڑو کیونکہ میں نے رسول اللہ صلی اللہ علیہ وسلم کو فرماتے سنا: \"جب بندہ اللہ تعالی کے لیے ایک سجدہ کرتا ہے تو اللہ عزوجل اس کے بدلے، اس کا ایک درجہ بلند کرتا ہے، اور ایک گناہ مٹا دیتا ہے\"۔ معدان کہتے ہیں: پھر میں ابو الدرداء رضی اللہ عنہ سے ملا اور میں نے ان سے وہی سوال کیا جو ثوبان رضی اللہ عنہ سے کر چکا تھا، تو انہوں نے بھی مجھ سے یہی کہا: تم سجدوں کو لازم پکڑو کیونکہ میں نے رسول اللہ صلی اللہ علیہ وسلم کو فرماتے سنا ہے کہ \"جب بندہ اللہ تعالی کے لیے ایک سجدہ کرتا ہے، تو اللہ تعالی اس کے بدلے اس کا ایک درجہ بلند کرتا ہے، اور ایک گناہ مٹا دیتا ہے\"۔","الألباني: صحيح",{"u2":"حضرت معدان بن طلحہ یعمری بیان کرتے ہیں کہ میں رسول اللہ صلی اللہ علیہ وسلم کے آزاد کردہ غلام حضرت ثوبان رضی اللہ عنہ سے ملا اور گزارش کی: مجھے ایسا عمل بتائیے جو مجھے نفع دے یا مجھے جنت میں داخل کر دے۔ پ کچھ دیر خاموش رہے، پھر میری طرف متوجہ ہوئے اور فرمایا: کثرت سجود کو لازم پکڑ کیونکہ میں نے رسول اللہ صلی اللہ علیہ وسلم کو یہ فرماتے ہوئے سنا ہے: ’’جو بندہ اللہ تعالیٰ کے لیے سجدے کرتا ہے، اللہ تعالیٰ اس سجدے کی وجہ سے اس کا درجہ بلند فرماتا ہے اور ایک غلطی معاف فرماتا ہے۔‘‘ معدان نے کہا: پھر میں حضرت ابودرداء رضی اللہ عنہ سے ملا اور ان سے بھی وہی سوال کیا جو حضرت ثوبان رضی اللہ عنہ سے کیا تھا۔ انھوں نے بھی فرمایا: سجدے (کثرت کے ساتھ) کیا کر کیونکہ میں نے رسول اللہ صلی اللہ علیہ وسلم کو فرماتے سنا ہے: ’’جو بندہ خالص اللہ تعالیٰ کے لیے سجدہ کرتا ہے تو اللہ تعالیٰ اس سجدے کی بنا پر اس کا درجہ بلند فرماتا ہے اور اس کی غلطی (یا غلطیاں) معاف فرماتا ہے۔‘‘","f2":"(۱) سلف صالحین کی فضیلت کہ وہ حصول جنت کے لیے کس قدر کوشاں اور حریص تھے کہ اکثر و بیشتر ان کے سوالات کا محور آخرت ہوتی تھی۔ (۲) عالم دین کو سوال کا جواب دینے میں جلدی نہیں کرنی چاہیے بلکہ پہلے سوچنا چاہیے۔ جب دلائل معحضر ہوں تب جواب دے۔"}],[1140,"عطاء بن یزید کہتے ہیں کہ میں ابوہریرہ رضی اللہ عنہ اور ابوسعید کے پاس بیٹھا ہوا تھا، تو ان دونوں میں سے ایک نے شفاعت کی حدیث بیان کی، اور دوسرے خاموش رہے، انہوں نے کہا: فرشتے آئیں گے، شفاعت کریں گے، اور انبیاء و رسل بھی شفاعت کریں گے، نیز انہوں نے پل صراط کا ذکر کیا، اور کہا کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا ہے: \"پل صراط پار کرنے والا سب سے پہلا شخص میں ہوں گا\" جب اللہ تعالی اپنی مخلوق کے فیصلوں سے فارغ ہو گا، اور جہنم سے جسے نکالنا چاہے گا نکال لے گا، تو اللہ فرشتوں کو اور رسولوں کو حکم دے گا کہ وہ شفاعت کریں، قابل شفاعت لوگ اپنی نشانیوں سے پہچان لیئے جائیں گے، آگ ابن آدم کی ہر چیز کھا جائے گی سوائے سجدہ کی جگہ کے، پھر ان پر چشمہ حیات کا پانی انڈیلا جائے گا، تو وہ اگنے لگیں گے جیسے سیلاب کے خش و خاشاک میں دانہ اگتا ہے ۱؎۔\n§وضاحت\n۱؎: جس طرح سیلاب کے کوڑا کرکٹ میں دانہ اُگ کر جلد ہی ترو تازہ ہو جاتا ہے، اسی طرح یہ لوگ بھی اس پانی کی برکت سے بھلے چنگے ہو جائیں گے، اور آگ کے نشانات مٹ جائیں گے۔","الألباني: صحيح",{"u2":"حضرت عطاء بن یزید بیان کرتے ہیں کہ میں حضرت ابوہریرہ اور حضرت ابو سعید رضی اللہ عنہما کے پاس بیٹھا تھا۔ ان میں سے ایک نے شفاعت والی حدیث سنائی اور دوسرا خاموش بیٹھا تھا۔ اس (صحابی) نے فرمایا: فرشتے آئیں گے اور سفارش کریں گے۔ تمام رسول علیہم السلام بھی سفارش فرمائیں گے۔ پھر انھوں نے پل صراط کا ذکر کرکے کہا کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’میں سب سے پہلے گزروں گا۔ پھر جب اللہ تعالیٰ بندوں کے درمیان انصاف کرکے ےفارغ ہو جائے گا اور جنھیں آگ سے نکالنا چاہے گا، انھیں نکالنے لگے گا تو فرشتوں اور رسولوں کو سفارش کرنے کا حکم دے گا تو انھیں ان کے (سجدوں کے) نشانات سے پہچانا جائے گا کیونکہ آگ انسان کے ہر عضو کو جلا دے گی مگر سجدے والی جگہوں کو نہ جلا سکے گی، چنانچہ (جہنم سے نکال کر) ان پر آب حیات ڈالا جائے گا، تو وہ ایسے (خوب صورت) اگیں گے جیسے سیلابی کوڑا کرکٹ میں دانہ اگتا ہے۔‘‘","f2":"(۱) صراط یا عرف عام میں پل صراط، جہنم کے اوپر رکھا جائے گا جس پر سے سب لوگ گزریں گے حتی کہ انبیاء علیہم السلام بھی، مگر اعلیٰ درجے کے لوگوں کو جہنم کا پتہ تک بھی نہیں چلے گا جبکہ گناہ گاروں کو وہ صراط اور اس کی رکاوٹیں روکیں گی، کھینچیں گی، زخمی کریں گی۔ کچھ تو زخمی ہوکر نجات پا جائیں گے اور جنت میں چلے جائیں گے، باقی جہنم میں گر جائیں گے۔ کفار و منافقین تو ہمیشہ کے لیے جہنم کا ایندھن بنے رہیں گے اور گناہ گار مومنین میلے سونے کی طرح آگ میں جلیں گے۔ جب گناہ اور ان کے اثرات جل جائیں گے اور نیکیاں باقی رہ جائیں گی تو انھیں نکال کر آب حیات میں، جو جنت سے لایا جائے گا، رکھا جائے گا۔ جب وہ جنتیوں جیسے خوب صورت ہو جائیں گے تو انھیں جنت میں لے جایا جائے گا جیسا کہ بھٹی میں سونے کے ساتھ ہوتا ہے۔ (۲) سیلابی کوڑا کرکٹ میں روئیدگی کی قوت بہت زیادہ ہوتی ہے، لہٰذا سیلاب ختم ہونے کے بعد اس کوڑا کرکٹ میں رہ جانے والے دانے بہترین اور بہت جلدی اور خوب صورت اگتے ہیں۔ اسی طرح جنت کا آب حیات آگ کے اثرات کو ختم کرکے انھیں چمکتے سونے کی طرح خوب صورت بنا دے گا تو پھر وہ جنت میں جائیں گے۔ (۳) جس طرح آگ سارا میل کچیل کھا جاتی ہے، سونے کو نہیں کھاتی، بالکل اسی طرح جہنم کی آگ گناہ اور گناہ کے اثرات کھائے گی۔ نیکی، ایمان اور ان کے اثرات نہیں کھا سکے گی، لہٰذا اس میں کوئی عقلی اشکال نہیں۔ بخلاف اس کے کافر چونکہ سراپا گناہ ہیں، لہٰذا جہنم انھیں ایندھن کی طرح مکمل طور پر جلائے گی۔ گویا کافر جلانے کے لیے جہنم میں ڈالے جائیں گے جب کہ گناہ گار مومن صفائی کےل یے، لہٰذا دونوں اسی فرق سے پہچانے جائیں گے۔ (۴) صحابۂ کرام رضی اللہ عنھم ادب کے کمال درجے پر فائز تھے کہ جب ایک بات کرتا تو دوسرے خاموشی سے سنتے اگرچہ انھیں پہلے سے اس بات کا پتہ ہوتا۔ (۵) رسولوں اور فرشتوں کے لیے شفاعت کا ثبوت۔ معتزلہ اور خوارج اس کا انکار کرتے ہیں۔ حدیث ان کے موقف کی تردید کرتی ہے۔ (۶) پل صراط کا ثبوت، نیز یہ کہ مومنین بھی اس پر سے گزریں گے۔ (۷) نبی اکرم صلی اللہ علیہ وسلم اور آپ کی امت کی فضیلت کا بیان کہ وہ تمام امتوں سے پہلے پل صراط سے گزرے گی۔ (۸) بعض مومن اپنے گناہوں کی سزا پانے کے لیے جہنم میں ڈالے جائیں گے، بعد میں اللہ تعالیٰ ان پر رحم فرمائے گا اور انھیں جہنم سے نکال کر جنت میں داخل کرے گا۔ (۹) مومن لوگوں کے عذاب کی کیفیت کفار سے مختلف ہوگی کہ ان کے سارے جسم کو آگ جلائے گی جبکہ مومن کے اعضائے سجود آگ سے محفوظ رہیں گے اور یہی ان کی پہچان کی نشانی ہوگی۔ سفارشی انھیں اسی نشانی سے پہچان کر آگ سے نکالیں گے۔"}],[1141,"شداد رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم مغرب اور عشاء کی دونوں نمازوں میں سے کسی ایک نماز کے لیے نکلے، اور حسن یا حسین کو اٹھائے ہوئے تھے، جب آپ نماز پڑھانے کے لیے آگے بڑھے تو انہیں (زمین پر) بٹھا دیا، پھر آپ نے نماز کے لیے تکبیر تحریمہ کہی، اور نماز شروع کر دی، اور اپنی نماز کے دوران آپ نے ایک سجدہ لمبا کر دیا، تو میں نے اپنا سر اٹھایا تو کیا دیکھتا ہوں کہ بچہ رسول اللہ صلی اللہ علیہ وسلم کی پیٹھ پر ہے، اور آپ سجدے میں ہیں، پھر میں اپنے سجدے کی طرف دوبارہ پلٹ گیا، جب رسول اللہ صلی اللہ علیہ وسلم نے نماز پوری کر لی تو لوگوں نے عرض کیا: اللہ کے رسول! آپ نے نماز کے درمیان ایک سجدہ اتنا لمبا کر دیا کہ ہم نے سمجھا کوئی معاملہ پیش آ گیا ہے، یا آپ پر وحی نازل ہونے لگی ہے، آپ صلی اللہ علیہ وسلم نے فرمایا: \"ان میں سے کوئی بات نہیں ہوئی تھی، البتہ میرے بیٹے نے مجھے سواری بنا لی تھی تو مجھے ناگوار لگا کہ میں جلدی کروں یہاں تک کہ وہ اپنی خواہش پوری کر لے\"۔","الألباني: صحيح",{"u2":"حضرت شداد رضی اللہ عنہ بیان کرتے ہیں کہ مغرب یا عشاء کی نماز کے لیے اللہ کے رسول صلی اللہ علیہ وسلم تشریف لائے تو آپ نے حضرت حسن یا حسین رضی اللہ عنہما کو اٹھا رکھا تھا۔ رسول اللہ صلی اللہ علیہ وسلم (نماز پڑھانے کے لیے) آگے بڑھے اور بچے کو نیچے بٹھا دیا۔ پھر نماز کے لیے تکبیر تحریمہ کہی اور نماز شروع کر دی۔ نماز کے دوران میں آپ نے ایک سجدہ بہت لمبا کر دیا۔ میں نے سر اٹھا کر دیکھا تو بچہ رسول اللہ صلی اللہ علیہ وسلم کی پشت پر بیٹھا تھا اور آپ سجدے میں تھے۔ میں دوبارہ سجدے میں چلا گیا۔ جب رسول اللہ صلی اللہ علیہ وسلم نے نماز پوری فرمائی تو لوگوں نے گزارش کی: اے اللہ کے رسول! آپ نے نماز کے دوران میں ایک سجدہ اس قدر لمبا کیا کہ ہم نے سمجھا کوئی حادثہ ہوگیا ہے یا آپ کو وحی آنے لگی ہے۔ آپ نے فرمایا: ’’ایسا کچھ بھی نہیں ہوا بلکہ میرا بیٹا میری پشت پر سوار ہوگیا تو میں نے پسند نہ کیا کہ اسے جلدی میں ڈالوں (فوراً اتار دوں) حتی کہ وہ اپنا دل خوش کرلے۔‘‘","f2":"(۱) ’’حادثہ‘‘ مرض یا وفات سے کنایہ ہے، تبھی تو صحابی کو تشویش ہوئی اور سر اٹھا کر دیکھا۔ (۲) بلاوجہ سجدے کے درمیان سر اٹھانا منع ہے مگر کوئی عذر ہو، مثلاً: پیشانی کے نیچے کوئی تکلیف دہ چیز آگئی ہو یا سر میں شدید درد محسوس ہو یا امام کی حالت دیکھنا مقصود ہو تو ضرورت کے مطابق سر اٹھایا جا سکتا ہے۔ عذر ختم ہونے پر دوبارہ سجدے میں چلا جائے۔ یہ دو سجدے نہیں بنیں گے، ایک ہی رہے گا کیونکہ نیت معتبر ہے۔ (۳) بچوں کی خوشی کا اس قدر لحاظ رکھنا رسول اللہ صلی اللہ علیہ وسلم جیسے در یتیم ہی سے ہوسکتا ہے۔ یقیناً ایسا فعل دگنے ثواب کا حامل ہے کہ عبادت میں بھی اضافہ ہوا اور اللہ تعالیٰ کی چھوٹی سی مخلوق کی دل جوئی بھی ہوئی۔ (۴) قرابت کے اعتبار سے نواسے کو بیٹا کہنا درست ہے اگرچہ وہ وراثت کے اعتبار سے بیٹے کی طرح نہیں ہوتا۔"}],[1142,"عبداللہ بن مسعود رضی اللہ عنہ کہتے ہیں کہ میں نے رسول اللہ صلی اللہ علیہ وسلم کو ہر جھکنے، اٹھنے، کھڑے ہونے اور بیٹھنے میں \"اللہ اکبر\" کہتے دیکھا، اور آپ اپنے دائیں اور بائیں \"السلام علیکم ورحمۃ اللہ وبرکاتہ\" کہتے ہوئے سلام پھیرتے یہاں تک کہ آپ کے گال کی سفیدی دکھائی دیتی، اور میں نے ابوبکر و عمر رضی اللہ عنہم کو بھی ایسے ہی کرتے دیکھا ہے۔","الألباني: صحيح",{"u2":"حضرت عبداللہ بن مسعود رضی راللہ عنہ فرماتے ہیں: میں نے رسول اللہ صلی اللہ علیہ وسلم کو دیکھا، آپ ہر جھکتے، اٹھتے، بیٹھتے اور کھڑے ہوتے وقت اللہ اکبر کہتے تھے اور اپنے دائیں بائیں [السلام علیکم و رحمۃ اللہ] ’’تم پر اللہ تعالیٰ کی سلامتی اور رحمت ہو۔‘‘ کہتے حتی کہ آپ کے رخسار کی سفیدی نظر آتی تھی۔ اور میں نے حضرت ابوبکر و عمر رضی اللہ عنہما کو بھی اسی طرح کرتے دیکھا۔","f2":"فوائد کے لیے دیکھیے: حدیث نمبر: ۱۰۸۴۔"}],[1143,"مالک بن حویرث رضی اللہ عنہ سے روایت ہے کہ نبی اکرم صلی اللہ علیہ وسلم جب نماز شروع کرتے تو اپنے دونوں ہاتھ اٹھاتے، اور جب رکوع کرتے تو بھی ایسا ہی کرتے، اور جب رکوع سے سر اٹھاتے تو بھی ایسا ہی کرتے، اور جب سجدہ سے سر اٹھاتے تو بھی ایسا ہی کرتے یعنی اپنے دونوں ہاتھ اٹھاتے ۱؎۔\n§وضاحت\n۱؎: دیکھئیے حاشیہ حدیث رقم: ۱۰۸۶۔","الألباني: صحيح",{"u2":"حضرت مالک بن حویرث رضی اللہ عنہ سے روایت ہے کہ نبی صلی اللہ علیہ وسلم جب نماز شروع فرماتے تو اپنے دونوں ہاتھ اٹھاتے اور جب رکوع کرتے تو ایسے کرتے اور جب رکوع سے سر اٹھاتے تو ایسے کرتے اور جب سجدے سے اپنا سر اٹھاتے تو ان سب میں ایسے ہی کرتے، یعنی رفع الیدین کرتے۔","f2":"سجدے میں رفع الیدین کرنے والی سب روایات ضعیف ہیں۔ مزید دیکھیے، حدیث: ۱۰۸۸۔"}],[1144,"عبداللہ بن عمر رضی اللہ عنہم کہتے ہیں کہ نبی اکرم صلی اللہ علیہ وسلم جب نماز شروع کرتے تو اللہ اکبر کہتے، اور اپنے دونوں ہاتھ اٹھاتے تھے، اور جب رکوع کرتے تو بھی، اور رکوع کے بعد بھی، اور دونوں سجدوں کے درمیان نہیں اٹھاتے تھے۔","الألباني: صحيح",{"u2":"حضرت ابن عمر رضی اللہ عنہما سے روایت ہے، انھوں نے فرمایا: نبی صلی اللہ علیہ وسلم جب نماز شروع فرماتے تو اللہ اکبر کہتے اور رفع الیدین کرتے۔ اسی طرح جب رکوع میں جاتے اور رکوع سے سر اٹھاتے (تب بھی ایسا ہی کرتے۔) لیکن دو سجدوں کے درمیان رفع الیدین نہیں کرتے تھے۔","f2":"یہ روایت صحیح ہے، اس لیے سجدے میں رفع الیدین کرنا صحیح نہیں ہے۔"}],[1145,"حذیفہ رضی اللہ عنہ کہتے ہیں کہ وہ نبی اکرم صلی اللہ علیہ وسلم کے پاس پہنچے اور آپ کے پہلو میں جا کر کھڑے ہو گئے، آپ نے «اللہ أكبر ذو الملكوت والجبروت والكبرياء والعظمة» کہا، پھر آپ نے سورۃ البقرہ پڑھی، پھر رکوع کیا، آپ کا رکوع تقریباً آپ کے قیام کے برابر رہا، اور آپ نے رکوع میں:«سبحان ربي العظيم سبحان ربي العظيم» کہا، اور جب آپ صلی اللہ علیہ وسلم نے اپنا سر اٹھایا تو: «لربي الحمد لربي الحمد» کہا، اور آپ اپنے سجدہ میں «سبحان ربي الأعلى سبحان ربي الأعلى» اور دونوں سجدوں کے درمیان «رب اغفر لي رب اغفر لي» کہتے تھے۔","الألباني: صحيح",{"u2":"حضرت حذیفہ رضی اللہ عنہ سے مروی ہے کہ وہ نبی صلی اللہ علیہ وسلم کے پاس پہنچے (تو آپ نماز پڑھ رہے تھے) اور وہ نبی صلی اللہ علیہ وسلم کے ساتھ پہلو میں کھڑے ہوگئے۔ آپ نے فرمایا: [اللہ اکبر ذوالملکوت والجبروت والکبریاء والعظمۃ] ’’اللہ سے بڑا ہے، وہ بادشاہی، عظیم الشان قوت، بے انتہا بزرگی اور عظمت کا مالک ہے۔‘‘ پھر آپ نے (سورئہ فاتحہ کے بعد) سورۂ بقرہ تلاوت فرمائی۔ پھر رکوع فرمایا۔ آپ کا رکوع تقریباً آپ کے قیام کے برابر تھا۔ آپ نے رکوع میں (بار بار) پڑھا: [سبحان ربی العظیم، سبحان ربی العظیم] اور جب رکوع سے سر اٹھایا تو (سمع اللہ لمن حمدہ کہنے کے بعد) فرمایا: [لربی االحمد، لربی الحمد] ’’میرے رب کے لیے ہی سب تعریفیں ہیں، میرے رب کے لیے ہی سب تعریفیں ہیں۔‘‘ اور آپ اپنے سجدے میں پڑھتے رہے: [سبحان ربی الاعلی، سبحان ربی الاعلی] اور آپ دو سجدوں کے درمیان پڑھتے رہے: [رب الغرلی رب اغفرلی] ’’اے میرے رب! مجھے معاف فرما دے۔ اے میرے رب! مجھے معاف فرما دے۔‘‘","f2":"دو سجدوں کے درمیان رب اغفرلی، رب افغلری پڑھنا بھی صحیح ہے بلکہ عام معروف دعا سے سند کے اعتبار سے یہ زیادہ قوی ہے۔ واللہ اعلم۔"}],[1146,"نضر بن کثیر ابوسہل ازدی کہتے ہیں کہ عبداللہ بن طاؤس نے منی میں مسجد خیف میں میرے پہلو میں نماز پڑھی، تو انہوں نے جب پہلا سجدہ کیا، اور سجدے سے اپنا سر اٹھایا تو اپنے دونوں ہاتھوں کو چہرے کے بالمقابل اٹھایا، مجھے یہ بات عجیب لگی تو میں نے وہیب بن خالد سے کہا کہ یہ ایسا کام کر رہے ہیں جو میں نے کبھی کسی کو کرتے نہیں دیکھا؟، تو وہیب نے ان سے کہا: آپ ایسا کام کرتے ہیں جسے ہم نے کسی کو کرتے نہیں دیکھا؟ اس پر عبداللہ بن طاؤس نے کہا: میں نے اپنے والد کو ایسا کرتے دیکھا ہے، اور میرے والد نے کہا: میں نے عبداللہ بن عباس رضی اللہ عنہم کو ایسا کرتے دیکھا ہے، اور عبداللہ بن عباس رضی اللہ عنہم نے کہا: میں نے رسول اللہ صلی اللہ علیہ وسلم کو ایسا کرتے دیکھا ہے۔","الألباني: صحيح",{"u2":"ابو سہل ازدی بیان کرتے ہیں کہ حضرت عبداللہ بن طاؤس نے منیٰ کی مسجد خیف میں میرے ساتھ نماز پڑھی۔ انھوں نے جب پہلا سجدہ کرنے کے بعد سر اٹھایا تو اپنے دونوں ہاتھ اپنے چہرے کے سامنے اٹھائے۔ میں نے اس فعل کو درست نہ سمجھا۔ میں نے (اپنے ساتھی) وہیب بن خالد سے کہا کہ یہ ایسا کام کرتے ہیں جو میں نے کسی اور کو کرتے نہیں دیکھا۔ وہیب نے ان سے کہا، آپ ایسا کام کرتے ہیں جو میں نے کسی اور کو کرتے نہیں دیکھا۔ عبداللہ بن طاؤس نے کا: میں نے اپنے والد محترم کو ایسے کرتے دیکھا ہے اور انھوں نے فرمایا: میں نے حضرت ابن عباس رضی اللہ عنہما کو ایسے کرتے دیکھا ہے اور حضرت عبداللہ بن عباس رضی اللہ عنہما نے نے فرمایا: ’’میں نے رسول اللہ صلی اللہ علیہ وسلم کو ایسے کرتے دیکھا ہے۔","f2":"(۱) اس روایت کے راوی ابوسہل ازدی ضعیف ہیں، لہٰذا یہ حدیث غیر معتبر ہے، خصوصاً اس لیے کہ یہ انتہائی صحیح احادیث، جو کہ صحیح بخاری، صحیح مسلم اور دیگر کتب احادیث میں مذکور ہیں، کے خلاف ہے۔ ان احادیث میں صراحتاً سجدوں کے درمیان رفع الیدین کی نفی آئی ہے۔ دیکھیے: (صحیح البخاری، الاذان، حدیث: ۷۳۵، و صحیح مسلم، الصلاۃ، حدیث: ۳۹۰) ان احادیث کو چھوڑ کر ایسی کمزور حدیث پر کسی مسئلے کی بنیاد رکھنا اہل علم کے شایان شان نہیں۔ (۲) سلف صالحین دین کے معاملے میں اس قدر حساس اور محتاط تھے کہ کوئی نئی ہوتی چیز دیکھ کر فوراً اس کا انکار کر دیتے یا اس کی دلیل پوچھتے۔ (۳) جس شخص سے اس کے کسی کام کے متعلق پوچھا جائے تو اسے غصے سے جواب نہیں دینا چاہیے بلکہ اس کی دلیل پیش کرکے حجت قائم کرنی چاہیے۔"}],[1147,"ام المؤمنین میمونہ رضی اللہ عنہا کہتی ہیں کہ رسول اللہ صلی اللہ علیہ وسلم جب سجدہ کرتے تو اپنے دونوں ہاتھ اپنے پہلو سے جدا رکھتے یہاں تک کہ آپ کے پیچھے آپ کے بغل کی سفیدی نظر آتی، اور جب بیٹھتے تو اپنی بائیں ران زمین پر لگا کر بیٹھتے۔","الألباني: صحيح",{"u2":"حضرت میمونہ رضی اللہ عنہما فرماتی ہیں کہ رسول اللہ صلی اللہ علیہ وسلم جب سجدہ کرتے تو اپنے بازوؤں کو کھولتے حتی کہ پیچھے سے بغلوں کی سفیدی نظر آتی تھی اور جب بیٹھتے تھے تو بائیں ران پر اطمینان سے بیٹھتے۔","f2":"اس حدیث سے ثابت ہوتا ہے کہ نماز میں بائیں ران پر بیٹھنا مسنون ہے۔ یہ حکم عام ہے اور نماز کے تمام جلسات کو شامل ہے، سوائے اس جلسے کے جسے دلیل کے ساتھ مستثنیٰ کیا گیا ہو جیسا کہ آخری تشہد ہے۔ دوسری روایت سے اس کا استثنا ثابت ہے اور اس میں تورک مسنون ہے، یعنی بائیں پاؤں کو دائیں پنڈلی کے نیچے سے گزار کر بائیں سرین پر بیٹھنا۔ امام صاحب کا اس حدیث سے استدلال واضح ہے کہ دو سجدوں کے درمیان بائیں ران پر بیٹھنا چاہیے کیونکہ یہ جلسہ بھی ان جلسات میں سے ہے جس کے بارے میں کوئی خاص روایت وارد نہیں ہوئی، سوائے اس روایت کے، لہٰذا اس روایت پر عمل کرتے ہوئے دو سجدوں کے درمیان بائیں ران پر بیٹھنا چاہیے۔ صحیح مسلم کی ایک روایت (۵۳۶) میں ایڑیوں پر بیٹھنے کو مسنون قرار دیا گیا ہے اور علمائے کرام نے اس سے دو سجدوں کے درمیان بیٹھنا مراد لیا ہے۔ اس اعتبار سے وہ روایت اس روایت کے خلاف ہے۔ ان کے درمیان تطبیق اس طرح ہے کہ دو سجدوں کے درمیان دونوں طرح بیٹھنا درست ہے لیکن پہلا طریقہ افضل ہے کیونکہ آپ صلی اللہ علیہ وسلم کا اکثر عمل یہی ہے۔ بخلاف آخری تشہد کے کہ اس میں دونوں طرح درست نہیں بلکہ تورک ہی مسنون ہے کیونکہ آپ صلی اللہ علیہ وسلم کا عمل یہی ہے۔ واللہ اعلم۔ مزید دیکھیے حدیث نمبر: ۱۱۰۶، ۱۱۰۷۔"}],[1148,"براء رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم کی نماز یعنی آپ کا رکوع، سجدہ، رکوع سے سر اٹھانے کے بعد کا قیام اور دونوں سجدوں کے درمیان کا بیٹھنا تقریباً سب برابر برابر ہوتا۔","الألباني: صحيح",{"u2":"حضرت براء بن عازب رضی اللہ عنہما فرماتے ہیں: رسول اللہ صلی اللہ علیہ وسلم کی نماز میں آپ کا رکوع اور سجدہ اور رکوع سے سر اٹھانے کے بعد قیام اور دو سجدوں کے درمیان جلسہ (بیٹھنا) تقریباً برابر ہوتے تھے۔"}],[1149,"عبداللہ بن مسعود رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم ہر اٹھتے، جھکتے، کھڑے ہوتے اور بیٹھتے وقت اللہ اکبر کہتے، اور ابوبکر و عمر اور عثمان رضی اللہ عنہم بھی۔","الألباني: صحيح",{"u2":"حضرت عبداللہ بن مسعو د رضی اللہ عنہ بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم ہر اٹھنے، جھکنے اور قیام و قعود (کھڑے ہونے اور بیٹھنے) کے وقت اللہ اکبر کہتے تھے اور حضرت ابوبکر و عمرو عثمان رضی اللہ عنھم بھی ایسے ہی کرتے تھے۔","f2":"د\nیکھیے حدیث نمبر: ۱۰۸۴۔"}],[1150,"ابوہریرہ رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم جب نماز کے لیے اٹھتے تو جس وقت کھڑے ہوتے «اللہ اکبر» کہتے، پھر جب رکوع کرتے تو«اللہ اکبر» کہتے، پھر جس وقت اپنی پیٹھ رکوع سے اٹھاتے تو «سمع اللہ لمن حمده» کہتے، پھر کھڑے ہو کر کہتے: «ربنا لك الحمد» پھر جب سجدہ کے لیے جھکتے تو «اللہ اکبر» کہتے، پھر جب سجدہ سے سر اٹھاتے تو «اللہ اکبر» کہتے، پھر جب (دوسرا) سجدہ کرتے تو «اللہ اکبر» کہتے، پھر جب سجدہ سے سر اٹھاتے تو «اللہ اکبر» کہتے، پھر پوری نماز میں ایسا ہی کرتے یہاں تک کہ آپ اسے پوری کر لیتے، اور جس وقت دوسری رکعت سے بیٹھنے کے بعد اٹھتے تو (بھی)«اللہ اکبر» کہتے۔","الألباني: صحيح",{"u2":"حضرت ابوہریرہ رضی اللہ عنہ فرماتے ہیں: رسول اللہ صلی اللہ علیہ وسلم جب نماز کے لیے کھڑے ہوتے تو اللہ اکبر کہتے۔ پھر جب رکوع فرماتے تو اللہ اکبر کہتے۔ پھر جب رکوع سے اپنی پشت اٹھاتے تو [سمع اللہ لمن حمدہ] کہتے۔ پھر کھڑے کھڑے کہتے: [ربنا لک الحمد] پھر جب سجدے کے لیے جھکتے تو اللہ اکبر کہتے۔ پھر جب سجدے سے سر اٹھاتے تو اللہ اکبر کہتے۔ پھر جب دوسرا سجدہ کرتے تو اللہ اکبر کہتے۔ پھر جب سجدے سے سر اٹھاتے تو اللہ اکبر کہتے۔ پھر ساری نماز میں ایسے ہی کرتے حتی کہ اسے مکمل فرماتے۔ اور جب دو رکعتوں کے بعد بیٹھ کر اٹھتے تو اللہ اکبر کہتے۔"}],[1151,"ابوقلابہ کہتے ہیں کہ ابوسلیمان مالک بن حویرث رضی اللہ عنہ ہماری مسجد میں آئے اور کہنے لگے: میں تمہیں دکھانا چاہتا ہوں کہ میں نے رسول اللہ صلی اللہ علیہ وسلم کو کیسے نماز پڑھتے دیکھا ہے، تو وہ پہلی رکعت میں آخری سجدہ سے اپنا سر اٹھاتے وقت بیٹھے (جلسہ استراحت کرتے) ۱؎۔\n§وضاحت\n۱؎: اس بیٹھک کو جلسہ استراحت کہتے ہیں، کچھ لوگوں کا کہنا ہے کہ یہ مسنون نہیں، اور اس روایت کا جواب یہ دیتے ہیں کہ آپ اسے بالقصد نہیں کرتے تھے بلکہ اخیر عمر میں کبر سنی کی وجہ سے ایسا کرتے تھے، لیکن یہ صحیح نہیں کیونکہ صحیحین کی روایت میں اس کے کرنے کا حکم آیا ہے، اور جو روایتیں اس کے خلاف آئی ہیں وہ ضعیف اور ناقابل اعتبار ہیں، اور اگر نبی اکرم صلی اللہ علیہ وسلم اور بعض صحابہ کرام رضی اللہ عنہم سے اس کا ترک تسلیم بھی کر لیا جائے تو یہ اس کے مسنون ہونے کے منافی نہیں، کیونکہ جو چیز واجب نہ ہو اسے کبھی کبھی ترک کرنا جائز ہے۔","الألباني: صحيح",{"u2":"حضرت ابو قلابہ سے روایت ہے کہ حضرت مالک بن حویرث رضی اللہ عنہ ہماری مسجد میں تشریف لائے اور فرمایا: میں چاہتا ہوں، میں تمھیں دکھاؤں کہ میں نے اللہ کے رسول صلی اللہ علیہ وسلم کو کیسے نماز پڑھتے دیکھا ہے۔ انھوں نے کہا: آپ نے جب پہلی رکعت میں دوسرے سجدے سے سر اٹھایا تو بیٹھ گئے۔"}],[1152,"مالک بن حویرث رضی اللہ عنہ کہتے ہیں کہ میں نے رسول اللہ صلی اللہ علیہ وسلم کو نماز پڑھتے دیکھا، جب آپ اپنی نماز کی طاق رکعتوں میں ہوتے تو جب تک بیٹھ کر سیدھے نہیں ہو جاتے نہیں اٹھتے۔","الألباني: صحيح",{"u2":"حضرت مالک بن حویرث رضی اللہ عنہ فرماتے ہیں: میں نے رسول اللہ صلی اللہ علیہ وسلم کو نماز پڑھتے دیکھا۔ جب آپ اپنی نماز کی طاق رکعت میں ہوتے تو آپ کھڑے نہیں ہوتے تھے حتی کہ پہلے سیدھے بیٹھ جاتے۔","f2":"طاق رکعت کے بعد اگلی رکعت کے لیے کھڑے ہونے سے قبل سیدھا بیٹھنا جلسۂ استراحت کہلاتا ہے اور یہ ضروری ہے۔ اس حدیث کے علاوہ اور بھی کئی احادیث میں اس کا صراحتاً ذکر ہے۔ قولاً بھی اور فعلاً بھی۔ بعض حضرات جو اس کے قائل نہیں وہ اسے نبی صلی اللہ علیہ وسلم کے بڑھاپے پر محمول کرتے ہیں کہ بڑھاپے کی وجہ سے آپ کو بیٹھنا پڑتا تھا، نماز کی سنت کے طور پر نہیں۔ مگر ان کے پاس اس تاویل کی کوئی دلیل نہیں جب کہ آنکھوں سے دیکھنے والے صحابۂ کرام رضی اللہ عنھم تو اسے بڑھاپے کی بنا پر نہیں سمجھتے تھے جیسا کہ حضرت ابوحمید رضی اللہ عنہ کا دس صحابہ کے سامنے رسول اللہ صلی اللہ علیہ وسلم کی نماز کے بیان میں اس امر کا ذکر کرنا اور ان صحابہ کا خاموش رہنا واضح دلیل ہے۔ مسیی الصلاۃ والی قولی روایت بھی صریح ہے۔ اگر کسی روایت میں اس کا ذکر نہیں ہے تو وہ اختصار کے پیش نظر ہے۔ کسی چیز کا حکم مجموعی طور پر احادیث سے اخذ کرنا چاہیے، لہٰذا کسی حدیث میں اس کا عدم ذکر اس کے وجوب کے خلاف نہیں۔ صحابۂ کرام رضی اللہ عنھم کا خیال بعد والوں کے خیال سے یقیناً زیادہ معتبر ہے۔ ویسے نبی صلی اللہ علیہ وسلم بڑھاپے مں بھی اتنے کمزور نہیں ہوئے تھے کہ ایک مسلمہ مسئلے کو چھوڑنا یا تبدیل کرنا پڑ گیا۔"}],[1153,"ابوقلابہ کہتے ہیں کہ مالک بن حویرث رضی اللہ عنہ ہمارے پاس آتے تو کہتے: کیا میں تمہیں رسول اللہ صلی اللہ علیہ وسلم کی نماز کے بارے میں نہ بتاؤں؟ تو وہ بغیر وقت کے نماز پڑھتے، جب وہ پہلی رکعت میں دوسرے سجدے سے اپنا سر اٹھاتے تو بیٹھ کر سیدھے ہو جاتے، پھر کھڑے ہوتے تو زمین پر اپنا ہاتھ ٹیکتے۔","الألباني: صحيح",{"u2":"ابو قلابہ سے روایت ہے کہ حضرت مالک بن حویرث رضی اللہ عنہ ہمارے پاس آئے تھے اور کہتے تھے: کیا میں تمھارے سامنے اللہ کے رسول صلی اللہ علیہ وسلم کی نماز نہ بیان کروں؟ پھر وہ کسی فرض نماز کے وقت کے علاوہ (نفل) نماز پڑھتے۔ جب وہ پہلی رکعت کے دوسرے سجدے سے سر اٹھاتے تو سیدھے بیٹھتے، پھر کھڑے ہوتے اور زمین پر ہاتھوں کا سہارا لیتے۔","f2":"(۱) حدیث نمبر ۱۰۹۲ میں ذکر ہوچکا ہے کہ ہاتھ انسان کو سہارے کا کام دیتے ہیں اور ہاتھوں کے سہارے کے بغیر اٹھنا یا بیٹھنا اونٹ بلکہ عام جانوروں کی مشابہت سے جو مناسب نہیں۔ سنن ابوداود کی ایک روایت میں سہارے سے منع کیا گیا ہے۔ اسے حافظ ابن حجر رحمہ اللہ نے ضعیف قرار دیا ہے۔ شیخ البانی رحمہ اللہ نے اسے منکر قرار دیا ہے۔ دیکھیے، (ضعیف سنن أبن داود، رقم: ۹۹۲) (۲) بالقبع یہ بھی معلوم ہوا کہ اٹھتے وقت گھٹنے پہلے اٹھائے جائیں گے اور ہاتھ بعد میں کیونکہ سہارا بعد میں ہٹایا جاتا ہے اور اسی میں سہولت ہے۔ بوڑھے بھی آسانی سے اٹھ سکیں گے۔"}],[1154,"وائل بن حجر رضی اللہ عنہ کہتے ہیں کہ میں نے رسول اللہ صلی اللہ علیہ وسلم کو دیکھا کہ جب آپ سجدہ کرتے تو گھٹنوں کو ہاتھ سے پہلے زمین پر رکھتے، اور جب اٹھتے تو اپنے ہاتھوں کو گھٹنوں سے پہلے اٹھاتے۔ ابوعبدالرحمٰن (نسائی) کہتے ہیں: اسے شریک سے یزید بن ہارون کے علاوہ کسی اور نے روایت نہیں کیا ہے، واللہ تعالی اعلم۔","الألباني: ضعيف",{"u2":"حضرت وائل بن حجر رضی اللہ عنہ سے روایت ہے کہ میں نے رسول اللہ صلی اللہ علیہ وسلم کو دیکھا، جب آپ سجدہ کرتے تو اپنے دونوں گھٹنے اپنے دونوں ہاتھوں سے پہلے رکھتے اور جب اٹھتے تو دونوں ہاتھ گھٹنوں سے پہلے اٹھاتے۔\nابوعبدالرحمن (امام نسائی) رحمہ اللہ بیان کرتے ہیں کہ یہ روایت شریک سے یزید بن ہارون کے علاوہ کسی نے بھی اس طرح بیان نہیں کی۔ واللہ تعالی اعلم۔","f2":"(۱) یاں شریک سے قاضی شریک مراد ہیں۔ اس روایت کو اس طرح بیان کرنے میں وہ متفرد ہیں۔ ثقہ راوی (مثلا: ہام) اس روایت کو مرسل، یعنی صحابی کے بغیر براہ راست نبیٔ اکرم صلی اللہ علیہ وسلم سے بیان کرتے ہیں۔ قاضی شریک حافظے کے لحاظ سے اتنے قوی نہیں کہ ان کی منفرد روایت کو قبول کیا جاسکے۔ امام صاحب کا مقصود یہ ہے کہ یہ روایت مرسل ہے، متصل نہیں، معتبر نہیں۔ دوسرے محدثین، مثلاً: امام ترمذی، دارقطنی اور بیہقی رحمہم اللہ بھی اس فیصلے میں امام صاحب کے ساتھ ہیں۔ (۲) اس حدیث کی دیگر اسناد میں حضرت وائل صحابی کا ذکر نہیں ہے۔ ان کا ذکر کرنے والے راوی متکلم فیہ ہیں، لہٰذا یہ روایت متنازع فیہ ہے۔ حدیث نمبر: ۱۱۵۴ معتبر ہے۔ اس مسئلے پر مزید بحث اس سے قبل فوائد حدیث نمبر: ۱۰۹۲ میں ہوچکی ہے۔ ملاحظہ فرمائیں۔"}],[1155,"ابوسلمہ کہتے ہیں کہ ابوہریرہ رضی اللہ عنہ انہیں نماز پڑھاتے تھے، تو جب جب جھکتے اور اٹھتے «اللہ اکبر» کہتے، پھر جب وہ سلام پھیر کر پلٹتے تو کہتے: قسم اللہ کی، میں تم میں نماز کے اعتبار سے رسول اللہ صلی اللہ علیہ وسلم سے سب سے زیادہ مشابہت رکھتا ہوں۔","الألباني: صحيح",{"u2":"حضرت ابوسلمہ سے روایت ہے کہ حضرت ابوہریرہ رضی اللہ عنہ ہمیں نماز پڑھاتے تو جب بھی (رکوع اور سجدے کے لیے) جھکتے اور (سجدے سے) اٹھتے تو اللہ اکبر کہتے۔ جب نماز سے فارغ ہوتے تو فرماتے: اللہ کی قسم! یقیناً میں اپنی نماز میں تم سب سے بڑھ کر رسول اللہ صلی اللہ علیہ وسلم کی مشابہ ہوں۔","f2":"دوسرے سجدے سے اٹھتے وقت اللہ اکبر کہنا کھڑے ہونے کے لیے کافی ہے اگرچہ درمیان میں جلسۂ استراحت بھی ہو۔ الگ تکبیر کی ضرورت نہیں کیونکہ جلسۂ استراحت تو معمولی ہوتا ہے، ہاں اگر دوسری رکعت کے آخر میں تشہد کے بعد انھیں تو الگ تکبیر کہنی ہوگی کیونکہ وہ الگ رکن ہے۔"}],[1156,"ابوبکر بن عبدالرحمٰن اور ابوسلمہ بن عبدالرحمٰن سے روایت ہے کہ ان دونوں نے ابوہریرہ رضی اللہ عنہ کے پیچھے نماز پڑھی، جب انہوں نے رکوع کیا تو اللہ اکبر کہا، پھر رکوع سے اپنا سر اٹھایا تو «سمع اللہ لمن حمده ربنا ولك الحمد» کہا، پھر سجدہ کیا تو «اللہ اکبر» کہا، اور سجدہ سے اپنا سر اٹھایا تو «اللہ اکبر» کہا، پھر جس وقت رکعت پوری کر کے کھڑے ہوئے تو «اللہ اکبر» کہا، پھر کہا: اس ذات کی قسم جس کے ہاتھ میں میری جان ہے، میں نماز میں ازروئے مشابہت تم میں رسول اللہ صلی اللہ علیہ وسلم سے سب سے زیادہ قریب ہوں، برابر آپ کی نماز ایسے رہی یہاں تک کہ آپ دنیا سے رخصت ہو گئے، یہ الفاظ «سّوار» کے ہیں۔","الألباني: صحيح",{"u2":"حضرت ابوبکر بن عبدالرحمن اور ابوسلمہ بن عبدالرحمن سے روایت ہے کہ انھوں نے حضرت ابوہریرہ رضی اللہ عنہ کے پیچھے نماز پڑھی۔ انھوں نے جب رکوع کیا تو اللہ اکبر کہا۔ جب رکوع سے سر اٹھایا تو [سمع اللہ لمن حمدہ، ربنا ولک الحمد] کہا۔ پھر سجدے میں گئے تو اللہ اکبر کہا۔ سجدے سے سر اٹھایا تو اللہ اکبر کہا۔ پھر جب رکعت سے اٹھے تو اللہ اکبر کہا۔ پھر فرمایا: قسم ہے اس ذات کی جس کے ہاتھ میں میری جان ہے! میں نماز میں تم سب سے بڑھ کر رسول اللہ صلی اللہ علیہ وسلم کے مشابہ ہوں اور آپ صلی اللہ علیہ وسلم کی نماز یہی رہی حتی کہ آپ دنیا سے جدا ہوگئے (فوت ہوگئے)۔ یہ لفظ حضرت سوار کے ہیں۔","f2":"اس روایت میں امام نسائی رحمہ اللہ کے دو استاد ہیں۔ نصر بن علی اور سوار بن عبداللہ۔ روایت میں بیان کردہ الفاظ حضرت سوار کے ہیں اگرچہ حضرت نصر کے الفاظ بھی معناً ان سے مختلف نہیں۔"}],[1157,"عبداللہ بن عمر رضی اللہ عنہم کہتے ہیں کہ نماز کی سنت میں سے یہ بات ہے کہ تم اپنے بائیں پیر کو بچھاؤ اور دائیں کو کھڑا رکھو۔","الألباني: صحيح",{"u2":"حضرت عبداللہ بن عمر رضی اللہ عنہما فرماتے ہیں: تحقیق نماز میں (بیٹھنے کا) طریقہ یہ ہے کہ تو اپنا بایاں پاؤں بچھائے اور دایاں پاؤں کھڑا کرے۔","f2":"(۱) حدیث میں پہلے یا دوسرے تشہد کی تخصیص نہیں، اسی لیے احناف ہر تشہد میں اسی طرح بیٹھنے کے قائل ہیں مگر دیگر صحیح روایات میں آخری تشہد کی الگ کیفیت ہے جسے تورک کہتے ہیں۔ دیکھیے: (صحیح البخاری، الاذان، حدیث: ۸۲۸) تورک کی تفصیل کے لیے دیکھیے، حدیث: ۱۲۶۳ اور اس کا فائدہ۔ بنابریں اس طریقے کو پہلے تشہد پر محمول کیا جائے گا۔ یہی مصنف رحمہ اللہ کا مقصود ہے (۲) عبادات وغیرہ میں صحابی کا کسی فعل کو سنت کہنا رسول اکرم صلی اللہ علیہ وسلم کے کسی قول و فعل ہی کا بیان ہوتا ہے، لہٰذا حجت ہے۔"}],[1158,"عبداللہ بن عمر رضی اللہ عنہم کہتے ہیں کہ نماز کی سنت میں سے دائیں پیر کو کھڑا رکھنا، اور اس کی انگلیوں کو قبلہ رخ رکھنا اور بائیں پیر پر بیٹھنا ہے۔","الألباني: صحيح",{"u2":"حضرت عبداللہ بن عمر رضی اللہ عنہما فرماتے ہیں: نماز میں (بیٹھنے کا) طریقہ یہ ہے کہ تو دائیں پاؤں کو کھڑا کرے اور اس کی انگلیاں قبلہ رخ کرے اور بائیں پاؤں پر بیٹھے۔"}],[1159,"وائل بن حجر رضی اللہ عنہ کہتے ہیں کہ میں رسول اللہ صلی اللہ علیہ وسلم کے پاس آیا تو میں نے آپ کو دیکھا کہ جب آپ نماز شروع کرتے تو اپنے دونوں ہاتھ اٹھاتے یہاں تک کہ اپنے دونوں کندھوں کے بالمقابل کر لیتے، اور جب رکوع کرنے کا ارادہ کرتے تو بھی ایسے ہی اٹھاتے، اور جب دو رکعت پڑھ کر بیٹھتے تو بائیں پیر کو بچھا دیتے، اور دائیں کو کھڑا رکھتے، اور اپنے دائیں ہاتھ کو دائیں ران پر رکھتے، اور (شہادت کی) انگلی دعا کے لیے کھڑی رکھتے، اور اپنے بائیں ہاتھ کو اپنی بائیں ران پر رکھتے۔ وائل رضی اللہ عنہ کہتے ہیں: پھر میں آئندہ سال ان لوگوں کے پاس آیا، تو میں نے لوگوں کو جبوں کے اندر اپنے ہاتھ اٹھاتے ہوئے دیکھا۔","الألباني: صحيح الإسناد",{"u2":"حضرت وائل بن حجر رضی اللہ عنہ بیان کرتے ہیں کہ میں رسول اللہ صلی اللہ علیہ وسلم کے پاس آیا تو میں نے دیکھا کہ آپ جب نماز شروع فرماتے اور جب رکوع کا ارادہ فرماتے تو اپنے دونوں ہاتھ اٹھاتے حتی کہ انھیں کندھوں کے برابر فرماتے اور جب دو رکعتوں کے بعد بیٹھتے تو بائیں پاؤں کو بچھاتے اور دائیں کو کھڑا کرتے اور اپنا دایاں ہاتھ اپنی دائیں ران پر رکھتے اور اپنی (تشہد کی) انگلی دعائے تشہد کے لیے اٹھاتے اور بایاں ہاتھ بائیں ران پر رکھتے۔ پھر میں اگلے سال آیا تو میں نے دیکھا کہ صحابۂ کرام رضی اللہ عنھم اپنے اپنے جبوں میں رفع الیدین کرتے تھے۔","f2":"(۱) حضرت وائل بن حجر رضی اللہ عنہ پہلی دفعہ غزوۂ تبوک کے بعد ۹ھ میں آئے تھے اور مسلمان ہوئے۔ پھر دوبارہ (اس روایت کے مطابق) اگلے سا، یعنی ۱۰ھ میں آئے۔ یہ رمضان یا شوال کی بات ہے۔ رسول اللہ صلی اللہ علیہ وسلم کی وفات تک چھ سات ماہ بنتے ہیں۔ گویا وفات سے اتنا عرصہ قبل تک تو نبی صلی اللہ علیہ وسلم اور صحابۂ کرام رضی اللہ عنھم رفع الیدین کیا کرتے تھے۔ منسوخ کب ہوا؟ بینوا توجروا۔ (۲) تشہد پڑھتے وقت انگشت شہادت سے اشارہ کرنا چاہیے اور یہ انگلی سلام پھیرنے تک اٹھی رہنی چاہیے اور بسا اوقات کسی نماز میں سلام پھیرنے تک پورے تشہد میں بدستور حرکت بھی دی جا سکتی ہے۔ اس کی تفصیل حدیث نمبر ۸۹۰ اور اس کے فوائد و مسائل میں گزر چکی ہے۔"}],[1160,"عبداللہ بن عمر رضی اللہ عنہم سے روایت ہے کہ انہوں نے ایک شخص کو دیکھا کہ وہ نماز کی حالت میں اپنے ہاتھ سے کنکریاں ہٹا رہا ہے، تو جب وہ سلام پھیر چکا تو عبداللہ بن عمر رضی اللہ عنہم نے اس سے کہا: جب تم نماز میں رہو تو کنکریوں کو ادھر ادھر مت کرو کیونکہ یہ شیطان کی طرف سے ہے، البتہ اس طرح کرو جیسے رسول اللہ صلی اللہ علیہ وسلم کرتے تھے، اس نے پوچھا: آپ کیسے کرتے تھے؟ تو انہوں نے اپنا داہنا ہاتھ اپنی دائیں ران پر رکھا، اور اپنی اس انگلی سے جو انگوٹھے سے متصل ہے قبلہ کی طرف اشارہ کیا، اور اپنی نگاہ اسی انگلی پر رکھی، پھر کہا: میں نے رسول اللہ صلی اللہ علیہ وسلم کو اسی طرح کرتے دیکھا ہے ۱؎۔\n§وضاحت\n۱؎: اس سے سلام پھیرنے تک برابر شہادت کی انگلی سے اشارہ کرنے کا ثبوت ملتا ہے، اشارہ کرنے کے بعد انگلی کے گرا لینے یا «لا الٰہ» پر اٹھانے اور«الا اللہ» پڑھ کر گرا لینے کی کوئی دلیل حدیث میں نہیں ہے۔","الألباني: حسن صحيح",{"u2":"حضرت عبداللہ بن عمر رضی اللہ عنہما سے روایت ہے، انھوں نے ایک آدمی کو دیکھا جو اپنے ہاتھ سے نماز میں کنکریوں سے کھیل رہا تھا۔ جب وہ فارغ ہوا تو اس سے حضرت عبداللہ بن عمر رضی اللہ عنہما نے کہا: نماز میں کنکریوں کو نہ چھوا کر، اس لیے کہ یہ شیطان کی طرف سے ہے۔ لیکن اس طرح کر جس طرح رسول اللہ صلی اللہ علیہ وسلم کیا کرتے تھے۔ اس نے کہا: آپ صلی اللہ علیہ وسلم کیسے کیا کرتے تھے؟ حضرت عبداللہ بن عمر رضی اللہ عنہما نے اپنا دایاں ہاتھ اپنی دائیں ران پر رکھا اور انگوٹھے کے ساتھ والی انگلی سے قبلے (سامنے) کی طرف اشارہ کیا اور اپنی نظر اس پر ٹکائی۔ پھر فرمایا: میں نے رسول اللہ صلی اللہ علیہ وسلم کو ایسے کرتے دیکھا ہے۔","f2":"(۱) تشہد میں دائیں ہاتھ کی انگشت شہادت کھلی رکھی جاتی ہے اور باقی ہاتھ بند رکھا جاتا ہے۔ اور انگشت شہادت سے اشارے کی صورت بنائی جاتی ہے۔ گویا کسی چیز کی طرف اشارہ کیا جا رہا ہے۔ نظر اشارے پر ٹکی رہے۔ (نیز دیکھیے، حدیث: ۸۹۰) (۲) کوئی شخص خلاف سنت کام کر رہا ہو تو اس کی اصلاح کرنی چاہیے۔"}],[1161,"عبداللہ بن زبیر رضی اللہ عنہم کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم جب دوسری یا چوتھی رکعت میں بیٹھتے تو اپنے دونوں ہاتھ اپنے گھٹنوں پہ رکھتے پھر اپنی(شہادت کی) انگلی سے اشارہ کرتے۔","الألباني: صحيح",{"u2":"حضرت عبداللہ بن زبیر رضی اللہ عنہما فرماتے ہیں: رسول اللہ صلی اللہ علیہ وسلم جب دو یا چار رکعات کے بعد بیٹھتے تو اپنے ہاتھ اپنے گھٹنوں پر رکھتے۔ پھر انگلی سے اشارہ فرماتے تھے۔","f2":"تشہد میں اشارے کی کیفیت، سنیت اور مقام کی بحث حدیث نمبر ۸۹۰ اور اس کے فوائد میں تفصیل سے بیان ہوچکی ہے۔ خلاصہ یہ ہے کہ دائیں ہاتھ کی انگشت شہادت کو اشارے کے انداز میں شروع قعدے سے آخر تک کھڑا رکھا جائے۔ بعض لوگ کہتے ہیں کہ اشھدان لا الہ پر انگلی کو اٹھا لے یا حرکت دے اور پھر الا اللہ پر نیچے کرلے۔ لیکن اس کی کوئی دلیل نہیں۔ احادیث سے یہی معلوم ہوتا ہے کہ آخر وقت، یعنی سلام پھیرنے تک انگلی برابر اٹھی رہے اور بسا اوقات کسی نماز میں انگلی سلام پھیرنے تک پورے تشہد میں حرکت میں رہے۔ یہ دونوں طریقے درست اور مسنون ہیں۔ واللہ اعلم۔"}],[1162,"عبداللہ بن مسعود رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے ہمیں سکھایا کہ جب ہم دوسری رکعت میں بیٹھیں تو «التحيات لله والصلوات والطيبات السلام عليك أيها النبي ورحمة اللہ وبركاته السلام علينا وعلى عباد اللہ الصالحين أشهد أن لا إله إلا اللہ وأشهد أن محمدا عبده ورسوله» \"تمام بزرگیاں اللہ تعالی کے لیے ہیں، تمام دعائیں اور صلاتیں اور تمام پاک چیزیں بھی، اے نبی! آپ پر سلامتی ہو، اور اللہ کی رحمت اور اس کی برکتیں نازل ہوں، اور سلامتی ہو ہم پر اور اللہ کے نیک بندوں پر، میں گواہی دیتا ہوں کہ اللہ کے سوا کوئی حقیقی معبود نہیں، اور میں گواہی دیتا ہوں کہ محمد اس کے بندے اور اس کے رسول ہیں\" کہیں۔","الألباني: صحيح",{"u2":"حضرت عبداللہ بن مسعود رضی اللہ عنہ بیان کرتے ہیں کہ ہمیں رسول اللہ صلی اللہ علیہ وسلم نے تعلیم دی کہ جب ہم دو رکعتوں کے بعد بیٹھیں تو یہ پڑھیں: [التحیات للہ …… و رسولہ] ’’تمام آداب (قولی عبادات)، دعائیں (یا بدنی عبادات) اور اچھے افعال و کلمات (یا مالی عبادات) اللہ تعالٰ کے لیے ہیں۔ اے نبی! آپ پر اللہ تعالیٰ کی طرف سے سلامتی، رحمت اور برکتیں ہوں۔ ہم پر اور اللہ کے دوسرے تمام نیک بندوں پر سلامتی ہو۔ میں گواہی دیتا ہوں کہ اللہ تعالیٰ کے سوا کوئی سچا معبود نہیں۔ اور میں گواہی دیتا ہوں کہ محمد (صلی اللہ علیہ وسلم) اللہ کے بندے اور رسول ہیں۔‘‘\nحضرت عبداللہ بن مسعود رضی اللہ عنہ بیان کرتے ہیں کہ ہم اللہ کے رسول صلی اللہ علیہ وسلم کے ساتھ رہتے تھے۔ (پہلے) ہم کچھ نہیں جانتے تھے تو رسول اللہ صلی اللہ علیہ وسلم نے ہمیں فرمایا: ’’ہر جلسے، یعنی تشہد میں کہو: [التحیات للہ و الصلوات و الطیبات، السلام علیکم ایھا النبی و رحمۃ اللہ و برکاتہ، السلام علینا و علی عباد اللہ الصالحین، اشھد ان لا الہ الا اللہ و اشھدان محمدا عبدہ و رسولہ]\nحضرت عبداللہ بن مسعود رضی اللہ عنہ فرماتے ہیں ہم رسول اللہ صلی اللہ علیہ وسلم کے ساتھ نماز پڑھتے تھے تو کہتے تھے: [السلام علی اللہ، السلام علی جبریل، السلام علی میکائیل] رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’تم [السلام علی اللہ] نہ کہو کیونکہ اللہ تعالیٰ تو خود سلام ہے، بلکہ تم کہو: [التحیات للہ والصلوات والطیبات، السلام علیک ایھا النبی و رحمۃ اللہ و برکاتہ السلام علینا و علی عباد اللہ الصالحین، اشھد ان لا الہ الا اللہ و اشھد ان محمدا عبدہ و رسولہ]۔","f2":"(۱) [التحیات، الصلوات، الطیبات] ک معاین کے بارے میں تفصیل کے لیے دیکھیے: حدیث نمبر ۱۰۶۵ کا فائدہ نمبر ۳۔ (۲) معلوم ہوا پہلے تشہد میں اتنا پڑھ لینا بھی کافی ہے، تاہم نوافل میں نبی صلی اللہ علیہ وسلم سے پہلے تشہد میں درود شریف کا پڑھنا بھی ثابت ہے، اس لیے پہلے تشہد میں بھی درود شریف کا پڑھنا مستحب ہے۔ (مزید تفصیل کے لیے دیکھیے، تفسیر ’’احسن البیان‘‘ میں (ان اللہ و ملائکتہ یصلون علی النبی……… الایۃ) (الاحزاب ۵۶:۳۳) کی تفسیر) باقی رہیں دعائیں تو اس کا محل نماز کا آخری تشہد ہے۔\nدیکھیے، حدیث نمبر: ۱۱۶۹۔"}],[1163,"عبداللہ بن مسعود رضی اللہ عنہ کہتے ہیں کہ ہم نہیں جانتے تھے کہ ہر دو رکعت (کے بعد قعدہ) میں کیا کہیں، سوائے اس کے کہ ہم اپنے رب کی پاکی بیان کریں، اور اس کی بڑائی اور حمد و ثنا کریں، حالانکہ محمد صلی اللہ علیہ وسلم نے خیر کے فواتح اور خواتم سکھا دئیے ہیں (یعنی وہ ساری باتیں سکھا دی ہیں جن میں خیر و بھلائی ہیں) آپ صلی اللہ علیہ وسلم نے فرمایا: \"جب تم ہر دو رکعت کے بعد بیٹھو تو کہو: «التحيات لله والصلوات والطيبات السلام عليك أيها النبي ورحمة اللہ وبركاته السلام علينا وعلى عباد اللہ الصالحين أشهد أن لا إله إلا اللہ وأشهد أن محمدا عبده ورسوله» تم میں سے ہر ایک کو چاہیئے کہ اسے جو دعا بھی اچھی لگے اختیار کرے، اور اللہ عزوجل سے دعا کرے۔","الألباني: صحيح",{"u2":"حضرت عبداللہ بن مسعود رضی اللہ عنہ بیان کرتے ہیں کہ ہم (پہلے پہل) نہیں جانتے تھے کہ دو رکعتوں کے بعد (بیٹھ کر) کیا پڑھیں مگر ہم تسبیح، تکبیر اور اپنے رب کی حمد پڑھتے رہتے تھے۔ حضرت محمد صلی اللہ علیہ وسلم نے ہمیں نیکی کی ابتدا و انتہا (نیکی کے تمام امور) کی تعیم دی۔ آپ نے فرمایا: ’’جب تم ہر دو رکعتوں کے بعد بیٹھو تو یہ پڑھو: [التحیات للہ والصلوات………] تمام آداب، دعائیں اور اچھے کلمات اللہ تعالیٰ ہی کے لیے ہیں۔ اے نبی! آپ پر اور اللہ تعالیٰ کے دوسرے نیک بندوں پر بھی سلامتی ہو۔ میں گواہی دیتا ہوں کہ اللہ تعالیٰ کے سوا کوئی حقیقی معبود نہیں اور میں گواہی دیتا ہوں کہ محمد (صلی اللہ علیہ وسلم) اس کے بندے اور رسول ہیں۔‘‘ اور تم میں سے ہر آدمی وہ دعاا منتخب کرے جو اسے زیادہ اچھی لگے۔ پھر اللہ تعالیٰ سے وہ دعا کرے۔‘‘","f2":"اگر دو رکعتوں کے بعد سلم پھیرنا ہو تو درود شریف کے بعد دعا بھی کی جائے گی۔"}],[1164,"عبداللہ بن مسعود رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے ہمیں صلاۃ کا تشہد اور حاجت کا تشہد دونوں سکھایا، رہا صلاۃ کا تشہد تو وہ «التحيات لله والصلوات والطيبات السلام عليك أيها النبي ورحمة اللہ وبركاته السلام علينا وعلى عباد اللہ الصالحين أشهد أن لا إله إلا اللہ وأشهد أن محمدا عبده ورسوله» ہے۔","الألباني: صحيح",{"u2":"حضرت عبداللہ بن مسعود رضی اللہ عنہ بیان کرتے ہیں کہ ہمیں رسول اللہ صلی اللہ علیہ وسلم ن نماز میں (پڑھنے کے لیے) تشہد اور دوسری ضروریات کے لیے تشہد سکھایا۔ نماز والا تشہد تو یہ ہے: [التحیات للہ و الصلوات………] ’’تمام قولی عبادات، بدنی عبادات اور مالی عبادات اللہ تعالیٰ کے لیے ہیں۔ اے نبی! آپ پر اللہ تعالیٰ کی طرف سے سلامتی، رحمت اور برکتیں ہوں۔ ہم پر اور اللہ کے نیک بندوں پر بھی سلامتی ہو۔ میں گواہی دیتا ہوں کہ اللہ کے سوا کوئی حقیقی معبود نہیں اور میں گواہی دیتا ہوں کہ محمد (صلی اللہ علیہ وسلم) اس کے بندے اور رسول ہیں۔‘‘"}],[1165,"یحیی بن آدم کہتے ہیں کہ میں نے سفیان (سفیان ثوری) کو یہی تشہد فرض اور نفل دونوں میں پڑھتے سنا، اور وہ کہتے تھے کہ ہم سے اسحاق نے بیان کیا انہوں نے ابو احوص سے انہوں نے عبداللہ بن مسعود رضی اللہ عنہ سے اور انہوں نے نبی اکرم صلی اللہ علیہ وسلم سے روایت کیا ہے، نیز اسے ہم سے منصور اور حماد نے بیان کیا اور ان دونوں نے ابووائل سے روایت کیا اور انہوں نے عبداللہ ابن مسعود سے اور ابن مسعود رضی اللہ عنہ نے نبی اکرم صلی اللہ علیہ وسلم سے۔","الألباني: صحيح",{"u2":"حضرت یحییٰ بن آدم بیان کرتے ہیں کہ میں نے حضرت سفیان کو یہ تشہد فرض اور نفل دونوں قسم کی نماز میں پڑھتے سنا اور وہ کہتے تھے: ہمیں (یہ تتشہد) ابواسحاق نے ابوالاحوص سے، انھوں (ابوالاحوص) نے حضرت عبداللہ بن مسعود رضی اللہ عنہ سے، انھوں نے نبی صلی اللہ علیہ وسلم سے بیان کیا۔"}],[1166,"عبداللہ بن مسعود رضی اللہ عنہ کہتے ہیں کہ ہم رسول اللہ صلی اللہ علیہ وسلم کے ساتھ تھے، ہم کچھ نہیں جانتے تھے تو رسول اللہ صلی اللہ علیہ وسلم نے ہم سے فرمایا:\"تم ہر جلسہ میں «التحيات لله والصلوات والطيبات السلام عليك أيها النبي ورحمة اللہ وبركاته السلام علينا وعلى عباد اللہ الصالحين أشهد أن لا إله إلا اللہ وأشهد أن محمدا عبده ورسوله» کہو۔","الألباني: صحيح",{"u2":"حضرت عبداللہ بن مسعود رضی اللہ عنہ سے مروی ہے کہ ہمیں رسول اللہ صلی اللہ علیہ وسلم نے یہ تتشہد اس طرح سکھایا جس طرح قرآن مجید کی کوئی سورت سکھاتے تھے۔ (جب آپ نے مجھے یہ تشہد سکھایا تو) میری ہتھیلی آپ صلی اللہ علیہ وسلم کے دونوں مبارک ہاتھوں کے درمیان تھی: [التحیات للہ و الصلوات والطیبات، السلام علیک ایھا النبی و رحمۃ اللہ و برکاتہ، السلام علینا و علی عباد اللہ الصالحین، اشھد ان لا الہ الا اللہ و اشھد ان محمدا عبدہ و رسولہ]","f2":"حضرت عبداللہ بن مسعود رضی اللہ عنہ کی ہتھیلی آپ کے مبارک ہاتھوں میں شفقت اور تعلیم کی طرف توجہ کے لیے تھی۔ معلوم ہوا کسی وجہ سے کسی کے ہاتھ کو دونوں ہاتھوں سے پکڑا جا سکتا ہے، مثلاً: بطور احترام۔ امام خباری رحمہ اللہ اس روایت کو دو ہاتھ سے مصافحے کے باب میں لائے ہیں۔ گویا وہ بتا رہے ہیں کہ وہ ہاتھوں سے مصافحہ کرنے کا اگر کوئی ثبوت ہے تو یہی ہے جو کہ درحقیقت ثبوت نہیں۔ یقیناً مصافحہ ایک ہاتھ سے مکمل ہو جاتا ہے مگر کسی اور وجہ سے اگر دوسرا ہاتھ ساتھ لگایا جائے، مثلاً: بطور احترام یا شفقت یا تفہیم وغیرہ تو یہ الگ امر ہے اور جائز ہے، البتہ یہ مصافحے کا جز نہیں۔ مصافحہ تو ایک ہاتھ ہی سے مسنون ہے اور خود مصافحے کا لفظ بھی اسی معنی پر دلالت کرتا ہے کیونکہ مصافحے کے معنی ہیں: ہتھیلی کا ہتھیلی سے ملنا۔ اس میں دونوں ہاتھوں کا کوئی تصور نہیں ہے۔ تفصیل کے لیے ملاحظہ ہو، مولانا عبدالرحمٰن مبارکپوری رحمہ اللہ کی کتاب (المقالۃ الحسنی فی سنیۃ المصافحۃ بالید الیمنی)"}],[1167,"عبداللہ بن مسعود رضی اللہ عنہ کہتے ہیں کہ ہم نہیں جانتے تھے کہ جب ہم صلاۃ پڑھیں تو کیا کہیں، تو نبی اکرم صلی اللہ علیہ وسلم نے ہمیں جامع کلمات سکھائے، آپ نے ہم سے فرمایا: کہو: «التحيات لله والصلوات والطيبات السلام عليك أيها النبي ورحمة اللہ وبركاته السلام علينا وعلى عباد اللہ الصالحين أشهد أن لا إله إلا اللہ وأشهد أن محمدا عبده ورسوله» علقمہ کہتے ہیں کہ میں نے ابن مسعود رضی اللہ عنہ کو دیکھا کہ وہ ہمیں یہ کلمات اسی طرح سکھاتے تھے جیسے وہ ہمیں قرآن سکھاتے تھے۔","الألباني: حسن صحيح",{"u2":"حضرت عبداللہ بن مسعود رضی اللہ عنہ فرماتے ہیں کہ ہم نہیں جانتے تھے کہ نماز پڑھیں تو کیا کہیں۔ رسول اللہ صلی اللہ علیہ وسلم نے ہمیں جامع کلمات سکھلائے اور ہم سے فرمایا: ’’تم یوں کہو: [التحیات للہ والصلوات والطیبات السلام علیکم ایھا النبی و رحمۃ اللہ و برکاتہ، السلام علینا و علی عباد اللہ الصالحین، اشھد ان لا الہ الا اللہ و اشھد ان محمدا عبدہ رسولہ] حضرت علقمہ نے کہا: میں نے دیکھا کہ حضرت ابن مسعود رضی اللہ عنہ یہ کلمات ہمیں اس طرح سکھاتے جیسے قرآن سکھاتے تھے۔ (لفظ لفظ حفظ کرواتے تھے۔)"}],[1168,"عبداللہ بن مسعود رضی اللہ عنہ کہتے ہیں کہ جب ہم رسول اللہ صلی اللہ علیہ وسلم کے ساتھ نماز پڑھتے تو کہتے: «السلام على اللہ السلام على جبريل السلام على ميكائيل» تو رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: «السلام على اللہ» نہ کہو کیونکہ اللہ تعالی سراپا سلام ہے بلکہ یوں کہو: «التحيات لله والصلوات والطيبات السلام عليك أيها النبي ورحمة اللہ وبركاته السلام علينا وعلى عباد اللہ الصالحين أشهد أن لا إله إلا اللہ وحده لا شريك له وأشهد أن محمدا عبده ورسوله»۔","الألباني: شاذ بزيادة وحده لا شريك له",{"u2":"حضرت عبداللہ بن مسعود رضی اللہ عنہ سے مروی ہے کہ جب ہم رسول اللہ صلی اللہ علیہ وسلم کے ساتھ نماز پڑھتے تو ہم (تشہد میں) کہتے: [السلام علی اللہ، السلام علی جبریل السلام علی میکائیل] اللہ تعالیٰ پر سلام ہو، جبریل پر سلام ہو، میکائیل پر سلام ہو تو رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’تم یہ نہ کہو کہ اللہ تعالیٰ پر سلام ہو، کیونکہ اللہ تعالیٰ تو خود سلامتی کا منبع ہے بلکہ تم یوں کہو: [التحیات للہ والصلوات………] ’’تمام آداب، نمازیں اور اچھے کلمات اللہ تعالیٰ کے لیے ہیں۔ اے نبی! آپ پر اللہ تعالیٰ کی طرف سے سلام، رحمت اور برکات ہوں۔ ہم پر اور اللہ تعالیٰ کے نیک بندوں پر بھی سلام ہو۔ میں گواہی دیتا ہوں کہ اللہ تعالیٰ کے سوا کوئی سچا معبود نہیں۔ وہ اکیلا ہے۔ اس کا کوئی شریک نہیں۔ اور میں گواہی دیتا ہوں کہ محمد (صلی اللہ علیہ وسلم) اس کے بندے اور اس کے رسول ہیں۔‘‘\nحضرت حطان بن عبداللہ سے روایت ہے کہ ہم نے حضرت ابو موسیٰ رضی اللہ عنہ کے ساتھ نماز پڑھی تو انھوں نے بیان کیا کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’جب امام قعدے میں ہو تو تم میں سے ہر آدمی کی پہلی بات یہ ہونی چاہیے: [التحیات للہ الطیبات ……… ورسولہ] ’’تمام آداب اللہ تعالیٰ کے لیے ہیں اور تمام اچھے کلمات اور دعائیں بھی اللہ کے لیے ہیں۔ اے نبی! آپ پر اللہ تعالیٰ کا سلام، رحمت اور برکتیں ہوں۔ ہم پر اور اللہ کے نیک بندوں پر بھی سلام ہو۔ میں گواہی دیتا ہوں کہ اللہ تعالیٰ کے سوا کوئی حقیقی معبود نہیں۔ وہ اکیلا ہے۔ اس کا کوئی شریک نہیں۔ اور میں گواہی دیتا ہوں کہ محمد (صلی اللہ علیہ وسلم) اس کے بندے اور رسول ہیں۔‘‘","f2":"اکیلے اکیلے کا نام لینے کی بجائے عباد اللہ الصالحین میں سب فرشتے اور نیک انسان آ جاتے ہیں، لہٰذا یہی درست ہے، البتہ رسول اللہ صلی اللہ علیہ وسلم کی شان الگ ہے، انھیں نہ صرف خصوصاً سلام کہا جائے گا بلکہ خطاب کے صیغے سے انھیں سلام پہنچایا جائے گا ……… صلی اللہ علیہ وسلم……… علاوہ ازیں تشہد میں آپ کو صیغۂ خطاب کے ساتھ سلام اس لیے عرض نہیں کیا جاتا کہ آپ سنتے ہیں، بلکہ صرف اس لیے یہ الفاظ [السلام علیک ایھا النبی] پڑھے جاتے ہیں کہ آپ نے مسلمانوں کو تشہد اسی طرح پڑھنے کا حکم دیا ہے، اس لیے آپ کے حکم کی تعمیل میں یہ الفاظ صرف اس موقع پر پڑھے جاتے ہیں"}],[1169,"ابن مسعود رضی اللہ عنہ کہتے ہیں کہ ہم رسول اللہ صلی اللہ علیہ وسلم کے ساتھ نماز پڑھتے تو کہتے: «السلام على اللہ السلام على جبريل السلام على ميكائيل» تو رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: «السلام على اللہ» نہ کہو کیونکہ اللہ تعالی سراپا سلام ہے بلکہ یوں کہو: «التحيات لله والصلوات والطيبات السلام عليك أيها النبي ورحمة اللہ وبركاته السلام علينا وعلى عباد اللہ الصالحين أشهد أن لا إله إلا اللہ وأشهد أن محمدا عبده ورسوله»۔","الألباني: صحيح"],[1170,"عبداللہ بن مسعود رضی اللہ عنہ کہتے ہیں نبی اکرم صلی اللہ علیہ وسلم تشہد میں «التحيات لله والصلوات والطيبات السلام عليك أيها النبي ورحمة اللہ وبركاته السلام علينا وعلى عباد اللہ الصالحين أشهد أن لا إله إلا اللہ وأشهد أن محمدا عبده ورسوله» کہتے۔","الألباني: صحيح",{"u2":"حضرت عبداللہ بن مسعود رضی اللہ عنہ سے روایت ہے کہ نبی صلی اللہ علیہ وسلم نے ہمیں تشہد کے بارے میں بتلایا: [التحیات للہ و الصلوات والطیبات، السلام علیک ایھا النبی و رحمۃ اللہ و برکاتہ، السلام علینا و علی عباد اللہ الصالحین، اشھد ان لا الہ الا اللہ و اشھد ان محمدا عبدہ و رسولہ]\nابو عبدالرحمن (امام نسائی) رحمہ اللہ بیان کرتے ہیں کہ (اس روایت میں) ابو ہاشم کا ذکر غریب ہے۔","f2":"(۱) ا حدیث کو امام شعبہ رحمہ اللہ سلیمان، منصور، حماد اور مغیرہ سے بیان کرتے ہیں اور یہ سب ابووائل سے بیان کرتے ہیں۔ امام نسائی رحمہ اللہ فرماتے ہیں کہ اس روایت میں شعبہ کے اساتذہ میں ابو ہاشم کا ذکر درست نہیں کیونکہ انھوں نے یہ روایت ابووائل سے بیان نہیں کی، مذکورہ چار اساتذہ ہی سے بیان کی ہے۔ واللہ أعلم۔ (۲) غریب حدیث وہ ہوتی ہے جس کی سند کے کسی طبقے میں ایک راوی رہ جائے۔ مزید دیکھیے: (جلد اول میں اصطلاحات محدثین)"}],[1171,"عبداللہ بن مسعود رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم ہمیں تشہد سکھاتے جیسے ہمیں قرآن کی سورۃ سکھاتے تھے اور میری ہتھیلی آپ کی دونوں ہتھیلیوں کے درمیان ہوتی (آپ فرماتے: کہو) «التحيات لله والصلوات والطيبات السلام عليك أيها النبي ورحمة اللہ وبركاته السلام علينا وعلى عباد اللہ الصالحين أشهد أن لا إله إلا اللہ وأشهد أن محمدا عبده ورسوله»۔","الألباني: صحيح"],[1172,"ابوموسی اشعری رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے ہم سے خطاب کیا، تو اس میں آپ نے ہمیں ہمارا طریقہ سکھایا، اور ہم سے ہماری صلاۃ کی تشریح فرمائی، اور فرمایا: \"اپنی صفیں درست کرو، پھر تم میں کا کوئی امامت کرے، تو جب وہ «اللہ اکبر» کہے تو تم بھی «اللہ اکبر» کہو، اور وہ «ولا الضالين» کہے تو تم «آمین» کہو، اللہ تعالی تمہاری یہ دعا قبول کرے گا، اور جب امام «اللہ اکبر» کہے، اور رکوع کرے تو تم بھی «اللہ اکبر» کہو اور رکوع کرو، امام تم سے پہلے رکوع کرے گا، اور تم سے پہلے رکوع سے اپنا سر اٹھائے گا، ادھر کی تاخیر ادھر پوری ہو جائے گی، اور جب وہ «سمع اللہ لمن حمده» کہے تو تم«ربنا لك الحمد» کہو، اللہ تعالی تمہاری سنے گا، اللہ تعالی نے نبی اکرم صلی اللہ علیہ وسلم کی زبان پر فرمایا ہے: اللہ نے اس کی سن لی جس نے اس کی تعریف کی، پھر جب امام «اللہ اکبر» کہے، اور سجدہ کرے تو تم بھی «اللہ اکبر» کہو اور سجدہ کرو، امام تم سے پہلے سجدہ کرے گا، اور تم سے پہلے سجدے سے سر اٹھائے گا، ادھر کی تاخیر ادھر پوری ہو جائے گی\" ۱؎ اور جب امام قاعدے میں ہو تو تم میں سے ہر ایک کی زبان پہ پہلی دعا یہ ہو: «التحيات الطيبات الصلوات لله السلام عليك أيها النبي ورحمة اللہ وبركاته السلام علينا وعلى عباد اللہ الصالحين أشهد أن لا إله إلا اللہ وأشهد أن محمدا عبده ورسوله»۔\n§وضاحت\n۱؎: یعنی امام تم سے جتنا پہلے سجدہ میں گیا اتنا ہی پہلے وہ سجدہ سے اٹھ گیا، اس طرح تمہاری اور امام کی نماز برابر ہو گئی۔","الألباني: صحيح",{"u2":"حضرت (ابو موسیٰ) اشعری رضی اللہ عنہ فرماتے ہیں: اللہ کے رسول صلی اللہ علیہ وسلم نے ہمیں خطبہ دیا۔ ہمیں ہمارے طریقے بتائے اور ہماری نماز ہمارے لیے بیان فرمائی، پھر آپ صلی اللہ علیہ وسلم نے فرمایا: ’’اپنی صفیں سیدھی اور درست کرو۔ پھر تم میں سے ایک آدمی تمھاری امامت کرائے۔ جب وہ اللہ اکبر کہے تو تم اللہ اکبر کہو اور جب وہ ولاالضالین کہے تو تم آمین کہو۔ اللہ تعالیٰ تم سے قبول فرمائے گا۔ جب وہ تکبیر کہہ کر رکوع کرے تو تم بھی تکبیر کہہ کر رکوع کرو۔ امام تم سے پہلے رکوع کو جاتا ہے اور پہلے سر اٹھاتا ہے۔ یہ تاخیر اس سبقت کے بدلے میں ہے۔ اور جب وہ (سمع اللہ لمن حمدہ) کہے تو تم [ربنا ولک الحمد] کہو۔ اللہ تعالیٰ تمھاری (حمد) سنے گا کیونکہ اللہ تعالیٰ نے اپنے نبی صلی اللہ علیہ وسلم کی زبانی ارشاد فرمایا ہے کہ اللہ تعالیٰ اس شخص کی بات سنتا ہے جو اس کی تعریف کرتا ہے۔ پھر جب امام اللہ اکبر کہہ کر سجدہ کرتا ہے تو تم بھی اللہ اکبر کہہ کر سجدہ کرو۔ امام تم سے پہلے سجدے کو جاتا ہے اور پہلے سر اٹھاتا ہے۔ یہ تاخیر اس سبقت کے بدلے میں ہے۔ پھر جب امام قعدے میں ہو تو تم میں سے ہر آدمی کو سب سے پہلے یہ کہنا چاہیے: [التحیات الطیبات ……… ورسولہ] ’’تمام پاکیزہ آداب اللہ تعالیٰ کے لیے ہیں، دعائیں اور نمازیں بھی۔ اے نبی! آپ پر اللہ تعالیٰ کا سلام، رحمت اور برکتیں ہوں۔ ہم پر اور اللہ کے نیک بندوں پر بھی سلام ہو۔ میں گواہی دیتا ہوں کہ اللہ کے سوا کوئی سچا معبود نہیں اور میں گواہی دیتا ہوں کہ محمد (صلی اللہ علیہ وسلم) اس کے بندے اور رسول ہیں۔‘‘"}],[1173,"حطان بن عبداللہ سے روایت ہے کہ ان لوگوں نے ابوموسی اشعری رضی اللہ عنہ کے ساتھ نماز پڑھی، تو انہوں نے کہا کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا ہے کہ جب امام قاعدے میں ہو تو تم میں سے ہر ایک کی زبان پہ پہلی دعا یہ ہو: «التحيات لله الطيبات الصلوات لله السلام عليك أيها النبي ورحمة اللہ وبركاته السلام علينا وعلى عباد اللہ الصالحين أشهد أن لا إله إلا اللہ وحده لا شريك له وأشهد أن محمدا عبده ورسوله» ۱؎۔\n§وضاحت\n۱؎: ابوموسی اشعری رضی اللہ عنہ سے مروی ان دونوں تشہدوں میں فرق یہ ہے کہ اس دوسری میں «التحیات» کے بعد «للہ» کا اضافہ ہے۔","الألباني: صحيح"],[1174,"عبداللہ بن عباس رضی اللہ عنہم کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم ہمیں تشہد سکھاتے جیسے ہمیں قرآن پڑھنا سکھاتے تھے، آپ کہتے تھے: «التحيات المباركات الصلوات الطيبات لله سلام عليك أيها النبي ورحمة اللہ وبركاته سلام علينا وعلى عباد اللہ الصالحين أشهد أن لا إله إلا اللہ وأشهد أن محمدا عبده ورسوله»۔\n§وضاحت\n۱؎: تمام کلمات کے اندر واؤ پوشیدہ ہے، یعنی: «التحیات والمبارکات والصلوات والطیبات للہ» واؤ کو اختصاراً حذف کر دیا گیا ہے۔","الألباني: صحيح",{"u2":"حضرت ابن عباس رضی اللہ عنہما بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم ہمیں تشہد اس طرح سکھاتے تھے جس طرح قرآن سکھاتے تھے اور آپ فرماتے تھے: [التحیات المبارکات ……… ورسولہ] ’’بابرکت آداب، تمام اچھے کلمات اور پاکیزہ دعائیں سب اللہ کے لیے ہیں۔ اے نبی! آپ پر سلام ہو اور اللہ تعالیٰ کی رحمت اور برکتیں ہوں۔ ہم پر اور اللہ تعالیٰ کے نیک بندوں پر بھی سلام ہو۔ میں گواہی دیتا ہوں کہ اللہ کے سوا کوئی حقیقی معبود نہیں۔ اور میں گواہی دیتا ہوں کہ محمد (صلی اللہ علیہ وسلم) اس کے بندے اور رسول ہیں۔‘‘"}],[1175,"جابر رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم ہمیں تشہد پڑھنا سکھاتے جیسے ہمیں قرآن کی سورۃ پڑھنا سکھاتے، فرماتے: «بسم اللہ وباللہ التحيات لله والصلوات والطيبات السلام عليك أيها النبي ورحمة اللہ وبركاته السلام علينا وعلى عباد اللہ الصالحين أشهد أن لا إله إلا اللہ وأشهد أن محمدا عبده ورسوله أسأل اللہ الجنة وأعوذ باللہ من النار»۔","الألباني: ضعيف",{"u2":"حضرت جابر رضی اللہ عنہ سے مروی ہے کہ رسول اللہ صلی اللہ علیہ وسلم ہمیں تشہد اس طرح سکھاتے تھے جس طرح ہمیں قرآن مجید کی سورت سکھاتے تھے: [بس اللہ و باللہ التحیات ……… من النار] ’’اللہ کے بابرکت نام اور اللہ تعالیٰ کی مدد اور توفیق کے ساتھ تمام آداب (یا قولی عبادتیں)، تمام دعائیں اور نمازیں (یا بدنی عبادات) اور تمام اچھے کلمات و افعال (یا مالی عبادات) اللہ تعالیٰ کے لیے ہیں۔ اے نبی! آپ پر اللہ کی طرف سے سلام رحمت اور برکتیں ہوں۔ ہم پر اور اللہ کے نیک بندوں پر بھی سلام ہو۔ میں گواہی دیتا ہوں کہ اللہ تعالیٰ کے سوا کوئی حقیقی معبود نہیں۔ اور میں گواہی دیتا ہوں کہ محمد (صلی اللہ علیہ وسلم) اس کے بندے اور رسول ہیں۔ میں اللہ تعالیٰ سے جنت مانگتا ہوں اور آگ سے اللہ کی پناہ چاہتا ہوں۔‘‘","f2":"(۱) تام قسم کے تشہد ایک جیسے ہیں۔ کہیں کہیں معمولی لفظی فرق ہے۔ معنی میں کوئی فرق نہیں۔ (۲) تمام تشہد تین چیزوں پر مشتمل ہیں: اللہ کی مجد و ثنا، نبیٔ اکرم صلی اللہ علیہ وسلم اوردوسرے صالحین پر سلام اور شہادتین (توحید و رسالت۔) (۳) آخری قسم کے تشہد کے شروع اور آخر میں اضافے (زائد کلمات) ہیں۔ شروع میں بسم اللہ اور پخر میں سوال و تعوذ، مگر اس حدیث کا راوی ایمن بن نابل متفرد ہے۔ کسی نے اس کی موافقت نہیں کی، لہٰذا یہ غیر معتبر ہے، یعنی یہ حدیث ضعیف ہے۔ (۴) تمام قسم کے تشہدات میں نبیٔ اکرم صلی اللہ علیہ وسلم کو بصیغۂ خطاب سلام کہا گیا ہے۔ یہ آپ صلی اللہ علیہ وسلم کی خصوصیت ہے ورنہ خطاب سے نماز فاسد ہو جاتی ہے۔ کہا جا سکتا ہے کہ صرف صیغہ خطاب کا ہے مقصود خطاب نہیں بلکہ دعا ہے کیونکہ آپ خود بھی انھی الفاظ سے تشہد پڑھا کرتے تھے۔ ان الفاظ کو پڑھتے وقت یہ عقیدہ نہیں ہونا چاہیے کہ آپ سلام سن رہے ہیں۔ ہاں، آپ کو پہنچایا جائے تو الگ بات ہے۔ اسی طرح آپ کے جوابی سلام کا بھی کوئی ذکر نہیں۔ (۵) [عبدہ و رسولہ] معلوم ہوتا ہے کہ آپ کے اوصاف فاضلہ میں سے یہ دو وصف سب سے اعلیٰ ہیں، تبھی انھیں شہادتین میں داخل کیا گیا جو کہ کسی کے ایمان کی دلیل ہیں۔ [عبد] بہت بڑا اعزاز ہے، اس لیے ہر افضل مقام میں اس کا ذکر کیا گیا ہے، مثلاً: معراج و اسرا وغیرہ۔ دیکھیے سورۂ بنی اسرائیل اور سورۂ نجم (اسری بعیدہ) (بنی اسرائیل ۱:۱۷) اور (فاوحی الی عبدہ) (النجم ۱۰:۵۳)"}],[1176,"عبداللہ بن مسعود رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم دوسری رکعت میں ایسا بیٹھتے جیسے گرم پتھر پر بیٹھے ہوں، راوی نے کہا: میں نے کہا: اٹھنے تک؟ تو انہوں نے (استاد نے) کہا: ہاں! یہی مراد ہے۔","الألباني: ضعيف",{"u2":"حضرت عبداللہ بن مسعود رضی اللہ عنہ فرماتے ہیں: نبی صلی اللہ علیہ وسلم دو رکعتوں کے بعد اتنا ہلکا بیٹھتے تھے گویا گرم پتھر پر بیٹھے ہیں۔ (یعنی جلدی کھڑے ہو جاتے۔)\nراویٔ حدیث ابو عبیدہ بیان کرتے ہیں کہ میں نے پوچھا: یہاں تک کہ اٹھ کھڑے ہوئے۔ انھوں نے فرمایا: ہاں، یہی مراد ہے۔","f2":"یہ روایت ضعیف ہے، تاہم ابن ابی شیبہ میں تمیم بن سلمہ کی صحیح سند سے مروی ہے کہ حضرت ابوبکر اور حضرت ابن عمر رضی اللہ عنہما کا پہلے تشہد میں بیٹھنا ایسے ہوتا تھا کہ گویا گرم پتھر پر بیٹھے ہوں۔ دیکھیے: (التلخیص الجبیر: ۲۶۳/۱) اس سے معلوم ہوتا ہے کہ دو رکعتوں کے بعد صرف تشہد پڑھنا کافی ہے، تاہم اس کے بعد درود شریف بھی پڑھ لیا جائے تو بہتر ہے، یعنی پہلے تشہد میں بھی درود شریف کا پڑھنا مستحب ہے، جیسا کہ پیچھے گزر چکا ہے۔ واللہ أعلم۔ مزید تفصیل کے لیے دیکھیے: (صفۃ صلاۃ النبی صلی اللہ علیہ وسلم للالبانی، ص:۴۵)"}],[1177,"ابن بحینہ (عبداللہ بن مالک) رضی اللہ عنہ کہتے ہیں کہ نبی اکرم صلی اللہ علیہ وسلم نے نماز پڑھائی، تو دوسری رکعت میں جس میں آپ بیٹھنا چاہتے تھے کھڑے ہو گئے، اور اپنی نماز جاری رکھی، یہاں تک کہ نماز کے آخر میں سلام پھیرنے سے پہلے آپ صلی اللہ علیہ وسلم نے دو سجدہ کیا، پھر سلام پھیرا۔","الألباني: صحيح",{"u2":"حضرت مالک ابن بحینہ رضی اللہ عنہ سے روایت ہے کہ نبی صلی اللہ علیہ وسلم نے (ایک دفعہ) نماز پڑھی تو دو رکعتوں کے بعد (بھول کر) کھڑے ہوگئے لیکن پھر نماز میں جاری رہے (واپس نہ ہوئے) حتی کہ جب نماز کے پخر میں پہنچے تو آپ نے سلام پھیرنے سے قبل دو سجدے (سجود سہو) کیے، پھر سلام پھیرا۔"}],[1178,"ابن بحینہ رضی اللہ عنہ سے روایت ہے کہ نبی اکرم صلی اللہ علیہ وسلم نے نماز پڑھائی، تو دوسری رکعت میں کھڑے ہو گئے، لوگوں نے سبحان اللہ کہا، لیکن آپ نے نماز جاری رکھی، اور جب نماز سے فارغ ہوئے تو دو سجدہ کیا، پھر سلام پھیرا۔","الألباني: صحيح",{"u2":"حضرت مالک ابن بحینہ رضی اللہ عنہ سے مروی ہے کہ نبی صلی اللہ علیہ وسلم نے (ایک دفعہ) نماز پڑھی تو دو رکعتوں کے بعد (بھول کر) کھڑے ہوگئے۔ لوگوں نے سبحان اللہ کہا مگر آپ جاری رہے (دوبارہ نہ بیٹھے) پھر جب نماز سے فارغ ہوئے تو دو سجدے کیے۔ پھر سلام پھیرا۔","f2":"(۱) اس واقعے سے جمہور علماء نے استدلال کیا ہے کہ پہلا تشہد فرض نہیں۔ اگر فرض ہوتا تو صحابہ کے توجہ دلانے پر نبی صلی اللہ علیہ وسلم لوٹ آتے مگر آپ کا آگے جاری رہنا اور پخر میں سجدۂ سہو کرنا دلیل ہے کہ یہ فرض نہیں، جبکہ بعض علمائے محققین کے نزدیک پہلا تشہد بھی واجب ہے۔ ہاں اگر بھول کر رہ جائے تو اس واجب کی سجودِ سہو سے تلافی ہوسکتی ہے جیسا کہ مندرجہ بالا حدیث سے ظاہر ہوتا ہے، نیز سنن ابوداود میں اس کا حکم منقول ہے: رسول اللہ صلی اللہ علیہ وسلم نے ’’مسیئی الصلاۃ‘‘ کو فرمایا تھا: [جلست فی وسط الصلاۃ فاطمئن و افترش فخذک الیسری ثم تشھد……] ’’جب تم نماز کے دوران میں بیٹھو تو اطمینان سے بیٹھو اور اپنی بائیں ران بچھا لو، پھر تشہد پڑھو……‘‘ (سنن أبي داود، الصلاۃ، حدیث: ۸۶۰) اس کے بعد رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: [ثم اذا قمت فمئل ذلک حتی تفرغ من صلاتک] ’’پھر جب کھڑے ہو تو پہلے کی طرح کرو حتی کہ اپنی نماز سے فارغ ہو جاؤ۔‘‘ ائمہ میں سے امام لیث، اسحاق بن راہویہ، مشہور قول کے مطابق امام احمد بھی اسی کے قائل ہیں۔ امام شافعی کا ایک قول بھی یہی ہے، اور احناف سے بھی وجوب کی ایک روایت ملتی ہے۔ تفصیل کے لیے دیکھیے: (فتح الباری: ۳۱۰/۲، تحت حدیث: ۸۲۹، و ذخیرۃ العقبی، شرح سنن النسائي: ۱۴۴،۱۴۳/۱۱) (۲) اگر کوئی رکن رہ جائے، مثلاً: رکوع تو واپس لوٹنا ضروری ہے یا آخر میں پوری رکعت دہرانی پڑے گی۔ البتہ یہ اس وقت ہے جب بھول کر اٹھ کھڑا ہوا۔ اگر کوئی بھول کر سیدھا کھڑا ہو جائے اور اسے یاد آ جائے تو واپس نہ لوٹے بلکہ آخر میں سہو کے دو سجدے کرلے، پھر سلام پھیرے اور اگر ابھی تھوڑا سا اٹھا تھا، یعنی بیٹھنے کے قریب تھا، ابھی ٹانگیں سیدھی نہیں ہوئی تھیں کہ یاد آگیا تو بیٹھ جائے اور تشہد پڑھے۔ سجدۂ سہو کی ضرورت نہیں، البتہ اگر آخری تشہد بھول کر کھڑا وہ جائے تو جب بھی یاد آئے، واپس لوٹے اور پخر میں سجدۂ سہو کرے۔ (۲) اس میں احناف کا رد ہے جو کہ ایک سلام کے بعد سجدۂ سہو کرتے ہیں۔ (۳) مقتدی بھی امام کے ساتھ سجدۂ سہو کرے گا اگرچہ مقتدی کو سہو نہ ہوا ہو، صرف امام ہی کو ہوا ہو۔ (۴) سجدۂ سہو کے بعد تشہد نہیں۔ (سججود سہو کی تفصیل کے لیے ملاحظہ ہو کتاب السہو کا ابتدائیہ) (۵) بتقاضائے بشریت انبیاء علیہم السلام کوبھی سہو اور نسیان لاحق ہوا ہے لیکن وحی کے پہنچانے میں قطعا نہیں۔"}],[1179,"عبدالرحمٰن بن اصم کہتے ہیں کہ انس بن مالک رضی اللہ عنہ سے نماز میں اللہ اکبر کہنے کے سلسلہ میں پوچھا گیا، تو انہوں نے کہا: اللہ اکبر کہے جب رکوع میں جائے، اور جب سجدہ میں جائے، اور جب سجدہ سے سر اٹھائے، اور جب دوسری رکعت سے اٹھے۔ حطیم نے پوچھا: آپ نے اسے کس سے سن کر یاد کیا ہے، تو انہوں نے کہا: نبی اکرم صلی اللہ علیہ وسلم، ابوبکر اور عمر رضی اللہ عنہم سے، پھر وہ خاموش ہو گئے، تو حطیم نے ان سے کہا، اور عثمان رضی اللہ عنہ سے بھی؟ انہوں نے کہا: اور عثمان رضی اللہ عنہ سے بھی۔","الألباني: صحيح الإسناد",{"u2":"حضرت عبدالرحمن بن اصم سے روایت ہے کہ حضرت انس بن مالک رضی اللہ عنہ سے نماز میں تکبیروں کے بارے میں پوچھا گیا تو انھوں نے فرمایا: تکبیر (اللہ اکبر) کہے جب رکوع کرے، جب سجدہ کرے، جب سجدے سے سر اٹھائے اور جب دو رکعتوں سے کھڑا ہو۔ حطیم نے ان سے پوچھا کہ یہ بات آپ نے کس سے یاد رکھی ہے؟ انھوں نے فرمایا: نبی صلی اللہ علیہ وسلم، حضرت ابوبکر اور حضرت عمر رضی اللہ عنہما سے، پھر خاموش ہوگئے۔ حطیم نے کہا: حضرت عثمان رضی اللہ عنہ سے بھی؟ فرمایا: ’’ہاں، حضرت عثمان رضی اللہ عنہ سے بھی۔","f2":"تکبیر تحریمہ تو متفق علیہ ہے، نیز اس میں کوئی سستی نہیں کرتا تھا، اس لیے اس کا ذکر نہیں کیا۔ باقی تکبیرات میں بعض ائمہ سستی کر جاتے تھے، اس لیے ان کا ذکر فرما دیا۔"}],[1180,"مطرف بن عبداللہ کہتے ہیں کہ علی بن ابی طالب رضی اللہ عنہ نے نماز پڑھی، تو وہ ہر جھکنے اور اٹھنے میں اللہ اکبر کہتے تھے، اور تکبیر پوری کرتے تھے (اس میں کوئی کمی نہیں کرتے تھے) تو عمران بن حصین رضی اللہ عنہما نے کہا: اس شخص نے مجھے رسول اللہ صلی اللہ علیہ وسلم کی نماز یاد دلا دی۔","الألباني: صحيح",{"u2":"حضرت مطرف بن عبداللہ سے مروی ہے کہ حضرت علی بن ابی طالب رضی اللہ عنہ نے نماز پڑھی تو وہ ہر جھکنے اور اٹھنے کے وقت پوری تکبیر کہتے تھے۔ حضرت عمران بن حصین رضی اللہ عنہ نے فرمایا: یقینا انھوں نے مجھے رسول اللہ صلی اللہ علیہ وسلم کی نماز یاد کرا دی ہے۔","f2":"دیکھیے، حدیث: ۱۰۸۳۔"}],[1181,"ابو حمید ساعدی رضی اللہ عنہ کہتے ہیں کہ نبی اکرم صلی اللہ علیہ وسلم جب دونوں رکعتوں سے کھڑے ہوتے تو اللہ اکبر کہتے، اور رفع یدین کرتے یہاں تک کہ دونوں ہاتھوں کو اپنے مونڈھوں کے برابر لے جاتے، جیسے وہ نماز شروع کرتے وقت کرتے تھے۔","الألباني: صحيح",{"u2":"حضرت ابو حمید ساعدی رضی اللہ عنہ بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم جب دو رکعتوں کے بعد کھڑے ہوتے تو اللہ اکبر کہتے اور اپنے دونوں ہاتھ اٹھاتے حتی کہ انھیں اپنے کندھوں کے برابر کرتے تھے جیسا کہ آپ نے نماز شروع کرتے وقت کیا تھا","f2":"یہ رفع الیدین بھی صحیح احادیث سے ثابت ہے اگرچہ بعض احادیث میں اس کا ذکر نہیں ہے لیکن ہر بات کا ہر حدیث میں ذکر ہونا ضروری نہیں۔ اگر کسی بھی صحیح حدیث میں کسی بات کا ذکر ہو اور وہ واضح روایات کے منافی نہ ہو تو اس پر عمل واجب ہوتا ہے، لہٰذا یہ رفع الیدین بھی سنت ہے، اگرچہ امام شافعی رحمہ اللہ اس کے قائل نہیں۔ اگلی حدیث میں بھی اس رفع الیدین کا اثبات ہے۔ (مزید تفصیل کے لیے ملاحظہ ہو، حدیث: ۸۷۷ کے فوائد و مسائل)"}],[1182,"عبداللہ بن عمر رضی اللہ عنہم کہتے ہیں کہ نبی اکرم صلی اللہ علیہ وسلم اپنے دونوں ہاتھوں کو اٹھاتے تھے جب نماز میں داخل ہوتے، اور جب رکوع کا ارادہ کرتے، اور جب رکوع سے اپنا سر اٹھاتے، اور دو رکعتوں کے بعد جب کھڑے ہوتے تو بھی اپنے ہاتھوں کو مونڈھوں کے بالمقابل اٹھاتے تھے۔","الألباني: صحيح",{"u2":"حضرت ابن عمر رضی اللہ عنہما سے منقول ہے کہ نبی صلی اللہ علیہ وسلم جب نماز شروع کرتے تو رفع الیدین فرماتے اور جب رکوع کا ارادہ فرماتے اور جب رکوع سے سر اٹھاتے اور جب دو رکعتوں کے بعد کھڑے ہوتے تو اسی طرح کندھوں تک اپنے دونوں ہاتھ اٹھاتے۔ (یعنی رفع الیدین فرماتے)۔","f2":"رفع الیدین کندھوں تک بھی ہوسکتا ہے، کانوں کے کناروں تک بھی جیسا کہ پیچھے حدیث: ۸۷۹ کے فائدے میں ذکر ہوچکا ہے"}],[1183,"سہل بن سعد رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم قبیلہ بنی عمرو بن عوف کے درمیان صلح کرانے گئے تھے کہ نماز کا وقت ہو گیا، تو مؤذن ابوبکر رضی اللہ عنہ کے پاس آیا، اور اس نے ان سے لوگوں کو جمع کر کے ان کی امامت کرنے کے لیے کہا (چنانچہ انہوں نے امامت شروع کر دی) اتنے میں رسول اللہ صلی اللہ علیہ وسلم تشریف لے آئے، اور صفوں کو چیر کر اگلی صف میں آ کر کھڑے ہو گئے، لوگ ابوبکر رضی اللہ عنہ کو تالیاں بجانے لگے تاکہ انہیں رسول اللہ صلی اللہ علیہ وسلم کی آمد کی خبر دے دیں، جب لوگوں نے کثرت سے تالیاں بجائیں تو انہیں احساس ہوا کہ نماز میں کوئی چیز ہو گئی ہے، تو وہ متوجہ ہوئے، تو کیا دیکھتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم تشریف لے آئے ہیں ابوبکر رضی اللہ عنہ نماز میں کسی اور طرف دھیان نہیں کرتے تھے رسول اللہ صلی اللہ علیہ وسلم نے انہیں اشارہ کیا کہ جیسے ہو ویسے ہی رہو، رسول اللہ صلی اللہ علیہ وسلم کے اس کہنے پر ابوبکر رضی اللہ عنہ نے اپنے دونوں ہاتھ اٹھا کر اللہ کی حمد و ثنا کی، پھر وہ الٹے پاؤں پیچھے آ گئے، اور رسول اللہ صلی اللہ علیہ وسلم آگے بڑھ گئے، پھر آپ نے نماز پڑھائی، جب آپ نماز سے فارغ ہوئے تو ابوبکر رضی اللہ عنہ سے پوچھا: \"تم نے نماز کیوں نہیں پڑھائی، جب میں نے تمہیں اشارہ کر دیا تھا؟\" تو ابوبکر رضی اللہ عنہ نے کہا: ابوقحافہ کے بیٹے کو یہ بات زیب نہیں دیتی کہ وہ رسول اللہ صلی اللہ علیہ وسلم کی امامت کرے، پھر آپ صلی اللہ علیہ وسلم نے لوگوں سے کہا: \"تمہیں کیا ہو گیا تھا کہ تم تالیاں بجا رہے تھے، تالیاں تو عورتوں کے لیے ہے\"، پھر آپ صلی اللہ علیہ وسلم نے فرمایا: \"جب تمہیں تمہاری نماز میں کوئی چیز پیش آ جائے، تو تم \"سبحان اللہ\" کہو\"۔","الألباني: صحيح",{"u2":"حضرت سہل بن سعد رضی اللہ عنہ سے مروی ہے، انھوں نے فرمایا: رسول اللہ صلی اللہ علیہ وسلم بنو عمرو بن عوف (اہل قباء) کے درمیان صلح کروانے تشریف لے گئے۔ (عصر کی) نماز کا وقت ہوگیا تو مؤذن حضرت ابوبکر رضی اللہ عنہ کے پاس آیا اور کہا کہ لوگوں کو اکٹھا کریں اور امامت فرمائیں۔ (نماز شروع ہوتے ہی) رسول اللہ صلی اللہ علیہ وسلم تشریف لے آئے۔ آپ صفوں کو چیرتے ہوئے پہلی صف میں آ کھڑے ہوئے۔ لوگوں نے ابوبکر کو مطلمع کرنے کے لیے تالیاں بجانا شروع کر دیں تاکہ انھیں رسو اللہ صلی اللہ علیہ وسلم (کی تشریف آوری) کے بارے میں مطلع کریں۔ حضرت ابوبکر رضی اللہ عنہ نماز میں ادھر ادھر توجہ نہیں فرماتے تھے۔ جب انھوں نے زیادہ ہی تالیاں بجائیں تو ان کی سمجھ میں آیا کہ نماز میں کوئی مشکل پیش آئی ہے۔ انھوں نے توجہ کی تو وہاں رسول اللہ صلی اللہ علیہ وسلم تھے۔ رسول اللہ صلی اللہ علیہ وسلم نے انھیں اشارہ فرمایا کہ آپ اپنی حالت میں رہیں تو حضرت ابوبکر رضی اللہ عنہ نے ہاتھ اٹھائے اور آپ کے اس فرمان پر اللہ تعالیٰ کی حمد و ثنا کی، پھر الٹے پاؤں پیچھے ہٹے۔ رسول اللہ صلی اللہ علیہ وسلم آگے بڑھے اور نماز پڑھائی۔ جب آپ نماز سے فارغ ہوئے تو ابوبکر رضی اللہ عنہ سے فرمایا: ’’جب میں نے تمھیں اشارہ کر دیا تھا تو پھر تمھیں کس چیز نے نماز پڑھانے سے روکا؟‘‘ حضرت ابوبکر رضی اللہ عنہ نے عرض کیا: ابو قحافہ کے بیٹے کو لائق اور مناسب نہ تھا کہ رسول اللہ صلی اللہ علیہ وسلم کا امام بنتا۔ پھر آپ نے لوگوں سے فرمایا: ’’کیا وجہ ہے کہ تم نے تالیاں بجانا شروع کر دیں، تالیاں بجانے کا حکم تو عورتوں کے لیے ہے؟ جب تمھیں نماز میں کوئی مشکل پیش آئے تو سبحان اللہ کہا کرو۔‘‘","f2":"اس رفع الیدین سے مراد تکبیر والا رفع الیدین نہیں بلکہ دعا والا رفع الیدین ہے جس میں ہتھیلیوں کا رخ قبلہ کی بجائے چہرے کی طرف ہوتا ہے۔ یہ روایت پیچھے گزر چکی ہے۔ (دیکھیے، فوائد حدیث: ۷۸۵)"}],[1184,"جابر بن سمرہ رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم ہمارے پاس تشریف لائے، اور ہم نماز میں اپنے ہاتھ اٹھا اٹھا کر سلام کر رہے تھے ۱؎ تو آپ نے فرمایا: \"لوگوں کو کیا ہو گیا ہے کہ نماز میں اپنے ہاتھ اٹھا رہے ہیں گویا وہ شریر گھوڑوں کی دم ہیں، نماز میں سکون سے رہا کرو\"۔\n§وضاحت\n۱؎: جیسا کہ اگلی روایت میں «فنسلم بأیدینا» کے الفاظ آ رہے ہیں۔","الألباني: صحيح",{"u2":"حضرت جابر بن سمرہ رضی اللہ عنہ سے روایت ہے، انھوں نے فرمایا: رسول اللہ صلی اللہ علیہ وسلم ہمارے پاس تشریف لائے تو ہم نماز (کے اختتام پر سلام) میں ہاتھ اٹھا رہے تھے۔ آپ نے فرمایا: ’’انھیں کیا ہوا ہے کہ نماز میں ہاتھ اٹھا رہے ہیں گویا کہ وہ سرکش گھوڑوں کی دمیں ہیں؟ نماز میں سکون اختیار کرو۔‘‘"}],[1185,"جابر بن سمرہ رضی اللہ عنہ کہتے ہیں کہ ہم لوگ نبی اکرم صلی اللہ علیہ وسلم کے پیچھے نماز پڑھتے، اور اپنے ہاتھ اٹھا کر سلام کرتے تھے، اس پر آپ نے فرمایا: \"ان لوگوں کو کیا ہو گیا ہے کہ یہ اپنے ہاتھ اٹھا اٹھا کر سلام کرتے ہیں گویا کہ یہ شریر گھوڑوں کی دم ہیں، کیا ان کے لیے یہ کافی نہیں کہ وہ اپنے ہاتھ اپنی ران پر رکھیں پھر«السلام عليكم، السلام عليكم» کہیں\"۔","الألباني: صحيح",{"u2":"حضرت جابر بن سمرہ رضی اللہ عنہ سے مروی ہے، انھوں نے فرمایا: ہم نبی صلی اللہ علیہ وسلم کے پیچھے نماز پڑھتے تھے تو ہاتھوں سے سلام کرتے تھے۔ آپ نے فرمایا: ’’انھیں کیا ہوا ہے کہ ہاتھوں سے سلام کر رہے ہیں گویا کہ وہ سرکش گھوڑوں کی دمیں ہیں؟ کیا انھیں کافی نہیں کہ اپنے ہاتھ اپنی رانوں پر رکھے رہیں اور (زبان سے) کہہ دیں: [السلام علیکم، السلام علیکم]","f2":"(۱) پہلی روایت مختصر ہے، اس میں صرف رفع الیدین کا ذکر ہے، یہ دوسری روایت اس کی تفصیل ہے۔ اس میں وضاحت ہے کہ یہ ہاتھ اٹھانا سلام کے وقت تھا۔ ابتدا میں صحابۂ کرام رضی اللہ عنہم [السلام علیکم] کہتے وقت ہاتھ بھی اٹھاتے جیسے کسی دور کھڑے آدمی کو زبان کے ساتھ ہاتھ سے بھی سلام کا اشارہ کر دیتے ہیں تاکہ اگر سن نہ سکے تو اشارے سے سمجھ جائے۔ اور یہ بعض صحابۂ کرام رضی اللہ عنہم کا اپنا اجتہادی فعل تھا۔ (۲) بعض احناف نے اس واضح صورت حال کو نظر انداز کرکے دونوں حدیثوں کو الگ الگ کر دیا کہ پہلی روایت میں مطلق رفع الیدین پر انکار کیا گیا ہے اور دوسری روایت میں سلام والے رفع الیدین پر، حالانکہ محدثین کا اتفاق ہے کہ یہ دونوں ایک ہی چیز کا بیان ہیں۔ ایک میں اختصار ہے، دوسری میں تفصیل۔ دونوں ایک ہی صحابی سے مروی ہیں۔ سیاق اسی کا مؤید ہے۔ (۳) بعض احناف نے دونوں روایات کو ایک تسلیم کرنے کے باوجود یہ کہا ہے: ’’بہرحال ہاتھ اٹھانے پر آپ کا اظہار ناراضی اور سکون کا حکم دینا رکوع وغیرہ کے رفع الیدین کے بھی خلاف ہے کیونکہ وہ بھی تو سکون کے منافی ہے۔‘‘ ادب کے ساتھ گزارش ہے کہ آپ کے یہ الفاظ اور اظہارِ ناراضی تکبیر تحریمہ، قنوت وتر اور عیدین کے رفع الیدین کے خلاف کیوں نہیں؟ کیا وہ سکون کے منافی نہیں؟ اگر آپ کے یہ الفاظ رکوع وغیرہ کے رفع الیدین کو منسوخ کرتے ہیں تو حضرات اپنی بھی خیر منائیے۔ یہ الفاظ مندرجہ بالا رفع الیدین (جن کے آپ قائل و فاعل ہیں) کو بھی منسوخ کرتے ہیں، پھر تو رفع الیدین کلیتاً منسوخ ہے۔ جہاں وہ تین وہاں ہمارے تین۔ اللہ اللہ خیرسلا۔ (۴) حقیقت یہ ہے کہ یہ الفاظ صرف سلام کے وقت دائیں طرف ہاتھ اٹھانے (نہ کہ قبلہ رخ) اور بائیں طرف سلام کہتے وقت ہاتھ بائیں طرف اٹھانے کے خلاف ہیں۔ انھی ہاتھ اٹھانے کو گھوڑوں کی دم اٹھانے سے تشبیہ دی گئی ہے کیونکہ رکوع وغیرہ کے رفع الیدین کو تو خود احناف بھی سنت سمجھتے ہیں، صرف منسوخ سمجھتے ہیں۔ گویا نبی صلی اللہ علیہ وسلم اور صحابۂ کرام رضی اللہ عنہم پہلے کیا کرتے تھے، بعد می منسوخ ہوگیا۔ کیا وہ رفع الیدین جو آپ کی پیروی میں کیے گئے، ان الفاظ کا مصداق بن سکتے ہیں؟ کیا نبی صلی اللہ علیہ وسلم اپنے ہی فعل کو سرکش گھوڑوں کی دم ہلانے سے تشبیہ دے سکتے ہیں؟ کلا واللہ! ہر منصف مزاج شخص ان روایات کا وہی مطلب سمجھے گا جو محدثین نے قرار دیا ہے کہ یہ انکار صرف سلام کے رفع الیدین پر ہے جو قبلہ رخ نہیں تھا، یعنی مسنون رفع الیدین کے مشابہ بھی نہیں تھا بلکہ یہ دائیں بائیں ہاتھ اٹھانا تھا جس طرح گھوڑا کبھی دائیں اور کبھی بائیں دم ہلاتا ہے۔ (رفع الیدین کی مزید تفصیل کے لیے دیکھیے، احادیث: ۸۷۷ - ۸۸۰، ۱۰۲۵، ۱۰۲۷)"}],[1186,"صحابی رسول صہیب رضی اللہ عنہ کہتے ہیں کہ میں رسول اللہ صلی اللہ علیہ وسلم کے پاس سے گزرا، اور آپ نماز پڑھ رہے تھے تو میں نے آپ کو سلام کیا، تو آپ نے مجھے اشارے سے جواب دیا، (ابن عمر رضی اللہ عنہم کہتے ہیں) اور میں یہی جانتا ہوں کہ صہیب رضی اللہ عنہ نے کہا کہ آپ صلی اللہ علیہ وسلم نے اپنی انگلی سے اشارہ کیا۔","الألباني: صحيح",{"u2":"صحابیٔ رسول حضرت صہیب رضی اللہ عنہ سے مروی ہے، انھوں نے فرمایا: میں رسول اللہ صلی اللہ علیہ وسلم کے پاس سے گزرا جب کہ آپ نماز پڑھ رہے تھے۔ میں نے آپ کو سلام کہا تو آپ نے مجھے انگلی کے اشارے سے جواب دیا۔","f2":"اس باب کی روایات کا حاصل یہ ہے کہ ابتدائے اسلام میں نماز میں حسب ضرورت کلام کرنے کی اجازت تھی، اس کے پیش نظر بعض صحابہ نے نبی صلی اللہ علیہ وسلم کو جب کہ آپ نماز پڑھ رہے تھے، سلام کیا، لیکن اس وقت نماز میں کلام کرنے سے روکا جا چکا تھا، اس لیے آپ نے لفظاً سلام کا جواب نہیں دیا، صرف اشارے سے سلام کا جواب دیا اور سلام پھیرنے کے بعد آپ نےب عض صحابہ سے اتعذار بھی کیا کہ آپ نے لفظاً سلام کا جواب اس لیے نہیں دیا کہ کہ اب نماز میں کلام کرنا ممنوع ہوچکا ہے، تاہم اس کے باوجود آپ نے اشارے سے جواب دیا۔ فقہائے محدثین اور شارحین حدیث نے ان احادیث سے یہی استدلال کیا ہے کہ نمازی کو سلام کرنا جائز ہے، اسے ممنوع قرار دینا صریح احادیث کے خلاف ہے۔ دیکھیے: (شرح صحیح مسلم للنووي، باب تحریم الکلام: ۵/۳۷، وسبل السلام، باب شروط الصلاۃ: ۱/۲۶۴، و عون المعبود، باب رد السلام: ۲/۲۹۲، والسنن الکبریٰ للبیھقی، باب الاشارۃ برد السلام، و باب کیفیۃ الاشارۃ بالید: ۲/۲۵۸-۲۶۰، وغیرھا) باقی رہا یہ مسئلہ کہ جواب میں اشارہ کس طرح کیا جائے گا؟ تو احادیث ہی میں اس کی چار شکلیں مذکور ہیں، ہتھیلی کے ساتھ، ہاتھ کے ساتھ، انگلی کے ساتھ اور سر کے ساتھ، اس لیے یہ ساری شکلیں جائز ہیں۔ دیکھیے (عون المعبود، باب رد السلام: ۲/۲۹۲)"}],[1187,"عبداللہ بن عمر رضی اللہ عنہم کہتے ہیں کہ نبی اکرم صلی اللہ علیہ وسلم مسجد قباء میں نماز پڑھنے کے لیے داخل ہوئے، تو لوگ ان کے پاس سلام کرنے کے لیے آئے، میں نے صہیب صلی اللہ علیہ وسلم سے پوچھا (وہ آپ کے ساتھ تھے) کہ نبی اکرم صلی اللہ علیہ وسلم سے جب سلام کیا جاتا تھا تو آپ کیسے جواب دیتے تھے؟ تو انہوں نے کہا: آپ اپنے ہاتھ سے اشارہ کرتے تھے۔","الألباني: صحيح",{"u2":"حضرت ابن عمر رضی اللہ عنہما بیان کرتے ہیں کہ نبی صلی اللہ علیہ وسلم مسجد قباء میں نماز پڑھنے کے لیے داخل ہوئے۔ کچھ لوگ آئے، آپ کو سلام کہنے لگے۔ میں نے صہیب رضی اللہ عنہ سے پوچھا، کیونکہ وہ آپ کے ساتھ تھے، کہ پھر نبی صلی اللہ علیہ وسلم کیا کرتے تھے، جب آپ کو سلام کہا جاتا تھا؟ انھوں نے فرمایا: آپ ہاتھ سے اشارہ فرماتے تھے۔"}],[1188,"عمار بن یاسر رضی اللہ عنہما سے روایت ہے کہ انہوں نے رسول اللہ صلی اللہ علیہ وسلم کو سلام کیا، اور آپ نماز پڑھ رہے تھے، تو آپ نے انہیں (اشارے سے)جواب دیا۔","الألباني: صحيح الإسناد",{"u2":"حضرت عمار بن یاسر رضی اللہ عنہ سے روایت ہے، انھوں نے رسول اللہ صلی اللہ علیہ وسلم کو سلام کہا جبکہ آپ نماز میں تھے تو آپ نے (اشارے سے) جواب دیا۔"}],[1189,"جابر رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے مجھے کسی ضرورت کے لیے بھیجا، جب میں (واپس آیا تو) میں نے آپ کو نماز پڑھتے ہوئے پایا، تو میں نے (اسی حالت میں) آپ کو سلام کیا، تو آپ نے مجھے اشارے سے جواب دیا، جب آپ نماز پڑھ چکے تو مجھے بلایا، اور فرمایا: \"تم نے ابھی مجھے سلام کیا تھا، اور میں نماز پڑھ رہا تھا\"، اور اس وقت آپ پورب کی طرف رخ کیے ہوئے تھے ۱؎۔\n§وضاحت\n۱؎: مقصود یہ ہے کہ اس وقت آپ کا چہرہ قبلہ کی طرف نہیں تھا اس لیے مجھے یہ اندازہ نہیں ہو سکا کہ آپ نماز میں ہیں، اس لیے آپ نے بعد میں بلا کر وضاحت کی، اور پورب کی طرف رخ ہونے کی وجہ یہ تھی کہ آپ اس وقت اپنی سواری پر تھے، اور سواری قبلہ سے پورب کی طرف متوجہ ہو گئی تھی۔","الألباني: صحيح",{"u2":"حضرت جابر رضی اللہ عنہ بیان کرتے ہیں کہ مجھے نبی صلی اللہ علیہ وسلم نے کسی کام سے بھیجا، میں واپس آیا تو میں نے آپ کو نماز کی حالت میں پایا۔ میں نے آپ کو سلام کیا، آپ نے میری طرف اشارہ کیا۔ پھر آپ جب نماز سے فارغ ہوئے تو مجھے بلایا اور فرمایا: ’’تم نے ابھی مجھے سلام کیا تھا جب کہ میں نماز پڑھ رہا تھا۔‘‘ اصل میں آپ اس وقت مشرق کی طرف جا رہے تھے۔","f2":"’’مشرق کی طرف‘‘ سے مراد یہ ہے کہ آپ بیت اللہ کی طرف رخ کرکے نماز نہیں پڑھ رہے تھے کیونکہ مدینے میں قبلہ تو جنوب کی طرف ہے لیکن سفر کے دوران میں نفل نماز کے لیے قبلہ رخ ہونا ضروری نہیں۔ صرف آغاز میں سواری کا رخ قبلے کی طرف کرنا ضروری ہے، بعد میں چاہے سواری کا رخ جدھر بھی ہو جائے، نماز پڑھتے رہنا چاہیے۔ اس سے نمازی کو سلام کرنے اور نمازی کا اشارے سے جواب دینا بھی ثابت ہوتا ہے۔"}],[1190,"جابر رضی اللہ عنہ کہتے ہیں کہ مجھے نبی اکرم صلی اللہ علیہ وسلم نے (کسی ضرورت سے) بھیجا، میں (لوٹ کر) آپ کے پاس آیا تو آپ (سواری پر) مشرق یا مغرب کی طرف جا رہے تھے، میں نے آپ کو سلام کیا تو آپ نے اپنے ہاتھ سے اشارہ کیا، میں واپس ہونے لگا تو آپ نے مجھے آواز دی: \"اے جابر!\" (تو میں نے نہیں سنا)پھر لوگوں نے بھی مجھے جابر کہہ کر (بلند آواز سے) پکارا، تو میں آپ کے پاس آیا، اور آپ سے عرض کیا: اللہ کے رسول! میں نے آپ کو سلام کیا مگر آپ نے مجھے جواب نہیں دیا، تو آپ صلی اللہ علیہ وسلم نے فرمایا: \"میں نماز پڑھ رہا تھا\"۔","الألباني: صحيح لغيره",{"u2":"حضرت جابر رضی اللہ عنہ سے روایت ہے کہ مجھے نبی صلی اللہ علیہ وسلم نے (کسی کام سے) بھیجا۔ میں واپس آیا تو آپ مشرق یا مغرب کی طرف تشریف لے جا رہے تھے۔ میں نے سلام کہہ دیا۔ آپ نے اپنے ہاتھ سے اشارہ کیا۔ میں نے پھر سلام کہا تو آپ نے پھر ہاتھ سے اشارہ کیا۔ میں چلا گیا۔ (کچھ دیر بعد) آپ نے مجھے آواز دی: ’’اے جابر!‘‘ لوگوں نے بھی آوازیں دیں۔ جابر جابر! میں حاضر ہوا تو میں نے عرض کیا: اے اللہ کے رسول! میں نے آپ کو سلام کہا تھا، آپ نے جواب نہیں دیا۔ آپ نے فرمایا: ’’میں نماز پڑھ رہا تھا۔‘‘","f2":"یہ روایت پہلی روایت ہی کی تفصیل ہے۔ گویا حضرت جابر یہ نہ سمجھ سکے کہ اشارہ سلام کا جواب ہے۔ کیونکہ یہ زبان کے ساتھ جواب دینے سے نہی کا ابتدائی دور تھا۔"}],[1191,"ابوذر رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"جب تم میں سے کوئی نماز کے لیے کھڑا ہو تو وہ کنکری پر ہاتھ نہ پھیرے، کیونکہ رحمت اس کا سامنا کر رہی ہوتی ہے\"۔","الألباني: ضعيف",{"u2":"حضرت ابوذر رضی اللہ عنہ سے روایت ہے، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’جب تم میں سے کوئی شخص نماز میں ہو تو کنکریاں نہ چھوئے کیونکہ رحمت الٰہی اس کی طرف متوجہ ہوتی ہے۔‘‘","f2":"چونکہ نماز دراصل اللہ تعالیٰ سے سرگوشی کر نا ہے۔ کسی سے باتیں کرتے ہوئے ادھر ادھر متوجہ ہونا اور فضول کام کرنا اس سے بے توجہی ہے۔ ظاہر ہے جب کوئی شخص نماز میں اللہ تعایلٰ سے بے توجہی کرتا ہے تو اللہ تعالیٰ بھی اس سے منہ پھیر لے گا اور وہ شخص رحمت الٰہی سے محروم رہے گا، البتہ اگر ضرورت ہو، مثلاً: سجدے کے لیے جگہ ہموار کرنا مقصود ہو تو صرف ایک دفعہ کنکریاں ہموار کرسکتا ہے، ورنہ وہ سارے سجدے میں بے چین رہے گا اور نماز کا خشوع ختم ہو جائے گا۔"}],[1192,"معیقب رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا ہے: \"اگر تمہیں (کنکریوں پر) ہاتھ پھیرنا ضروری ہی ہو تو ایک بار پھیر سکتے ہو\"۔","الألباني: صحيح",{"u2":"حضرت معیقیب رضی اللہ عنہ سے مرووی ہے، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’اگر تجھے ضرور کنکریوں کو ہموار کرنا پڑے تو ایک دفعہ کرلے (بار بار نہ کر)۔‘‘"}],[1193,"انس بن مالک رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"لوگوں کو کیا ہو گیا ہے کہ وہ نماز میں اپنی نگاہوں کو آسمان کی جانب اٹھاتے ہیں\"، آپ نے بڑی سخت بات اس سلسلہ میں کہی یہاں تک کہ آپ نے فرمایا: \"وہ اس سے باز آ جائیں ورنہ ان کی نظریں اچک لی جائیں گی\"۔","الألباني: صحيح",{"u2":"حضرت انس بن مالک رضی اللہ عنہ سے روایت ہے، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’کیا وجہ ہے، کچھ لوگ نماز میں اپنی نظریں آسمان کی طرف اٹھاتے ہیں۔‘‘ پھر آپ نے اس کے بارے میں سخت الفاظ ارشاد فرمائے، حتی کہ فرمایا: ’’لوگ اس کام سے باز آ جائیں ور نہ ان کی نظریں اچک لی جائیں گی۔‘‘","f2":"(۱) عام طور پر لوگ دعا میں نظر اوپر اٹھاتے ہیں۔ نماز سے باہر تو کوئی حرج نہیں، البتہ نماز میں چونکہ نظر کی جگہ مقرر ہے، لہٰذا نماز میں منع ہے، نیز یہ آدابِ نماز کے خلاف ہے کہ نظر قبلے (سامنے) سے ادھر ادھر ہٹے۔ (۲) جو بندہ منکرات کا ارتکاب کرے، اسے سخت کلام کے ساتھ زجر و توبیخ کی جا سکتی ہے، نیز جس بندے کو تنبیہ کرنا مقصود ہو، اس کا نام لیے بغیر ہی تمام لوگوں کو مخاطب کرکے مطلق بات کرنی چاہیے جیسا کہ نبی صلی اللہ علیہ وسلم اگر کسی میں کوئی خلاف شرع بات دیکھتے تو اس کا نام لیے بغیر یوں خطاب فرماتے: [ما بال أقوام] ’’لوگوں کا کیا خیال ہے!‘‘ یہ اس لیے کہ اس کی رسوائی نہ ہو، نیز اگر کسی کا نام تمام لوگوں کے سامنے لے کر اسے کسی برائی سے روکا جائے تو بسا اوقات یہ اندازِ نصیحت اسے ہٹ دھرمی اور مزید ارتکاب گناہ پر آمادہ کرتا ہے، لہٰذا ناصح اور داعی کو چاہیے کہ حکمت بھرے انداز اور وصف ستر (کسی کے عیب پر پردہ ڈالنے) کو اپنائے تو اس سے اس کی نصیحت مؤثر ہوگی۔"}],[1194,"ایک صحابی رسول رضی اللہ عنہ کہتے ہیں کہ انہوں نے رسول اللہ صلی اللہ علیہ وسلم کو فرماتے سنا: \"جب تم میں سے کوئی نماز میں ہو تو وہ اپنی نظروں کو آسمان کی طرف نہ اٹھائے، ایسا نہ ہو کہ اس کی نظر اچک لی جائے\"۔","الألباني: صحيح",{"u2":"حضرت عبیداللہ بن عبداللہ سے روایت ہے کہ نبی صلی اللہ علیہ وسلم کے صحابہ میں سے ایک صحابی نے مجھ سے بیان کیا کہ انھوں نے رسول اللہ صلی اللہ علیہ وسلم کو فرماتے ہئے سنا: ’’جب تم میں سے کوئی شخص نماز میں ہو تو اپنی نظر آسمان کی طرف نہ اٹھائے (کہیں ایسا نہ ہو) کہ وہ اچک لی جائے۔‘‘","f2":": ضروری نہیں کہ دنیا ہی میں اس فعل پر نظر اچک لی جائے بلکہ آخرت میں بھی یہ سزا مل سکتی ہے بلکہ زیادہ قرین قیاس یہی ہے۔"}],[1195,"ابوذر رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"برابر اللہ بندے پر اس کی نماز میں متوجہ رہتا ہے اس وقت تک جب تک کہ وہ ادھر ادھر متوجہ نہیں ہوتا، اور جب وہ رخ پھیر لیتا ہے تو اللہ بھی اس سے پھر جاتا ہے\"۔","الألباني: ضعيف",{"u2":"حضرت ابوذر رضی اللہ سے منقول ہے، فرماتے ہیں: رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’نماز کی حالت میں اللہ تعالیٰ اپنے بندے کی طرف متوجہ رہتا ہے جب تک وہ ادھر ادھر نہ دیکھے۔ جب وہ اپنا منہ ادھر ادھر کرتا ہے تو اللہ تعالیٰ اس سے توجہ منقطع فرما لیتا ہے۔‘‘","f2":"(۱)نماز میں ادھر ادھر جھانکنا سخت منع ہے۔ (۲) اس حدیث مبارکہ سے نماز کی فضیلت و اہمیت بھی واضح ہوتی ہے کہ نماز اللہ تعالیٰ کا اپنے بندے پر متوجہ ہونے کا سبب ہے اور یہ اللہ تعالیٰ کا اپنے بندے پر کمال لطف و کرم ہے۔ (۳) نماز میں جھانکنا اللہ تعالیٰ سے اعراض کرنا ہے۔ جب بندہ اللہ کی رحمت سے خود ہی منہ موڑتا ہے تو اللہ تعالیٰ بھی اس سے اعراض فرما لیتا ہے، لہٰذا نماز میں کسی طرف جھانکا نہیں جاسکتا۔ ہاں، نماز میں کسی مجبوری کی وجہ سے جھانکنا پڑے تو الگ بات ہے، مثلاً: امام کا کسی ضرورت کے تحت مقتدیوں کی طرف یا مقتدیوں کا ضرورت کی بنا پر امام کی طرف جھانکنا۔ ان صورتوں میں بھی کنکھیوں ہی سے کام لینا چاہیے، نہ کہ پورا منہ قبلے سے ہٹا لیا جائے، جیسا کہ اگلے باب کی حدیث میں آ رہا ہے"}],[1196,"ام المؤمنین عائشہ رضی اللہ عنہا کہتی ہیں کہ میں نے رسول اللہ صلی اللہ علیہ وسلم سے نماز میں ادھر ادھر دیکھنے کے متعلق پوچھا تو آپ نے فرمایا: \"یہ چھینا جھپٹی ہے جسے شیطان اس سے نماز میں کرتا ہے\"۔","الألباني: صحيح",{"u2":"حضرت عائشہ رضی اللہ عنہا فرماتی ہیں کہ میں نے رسول اللہ صلی اللہ علیہ وسلم سے نماز میں ادھر ادھر دیکھنے کے بارے میں سوال کیا تو آپ نے فرمایا: ’’یہ اچکنا ہے کہ شیطان اسے نماز سے اچک لیتا ہے۔‘‘","f2":"نماز میں ادھر ادھر دیکھنا بہت قبیح فعل ہے جس کا نماز پر بہت برا اثر پڑتا ہے۔ (جیسے کسی جانور سے درندہ کچھ گوشت نوچ کر لے جائے تو وہ جانور فوراً مرتا بھی نہیں، بچتا بھی نہیں، اگر بچے بھی تو وہ جانور بہت ناقص ہو جاتا ہے) اس لیے اس فعل کی نسبت شیطان کی طرف کر دی گئی۔ ویسے بھی اس قسم کے افعال شیطانی وسوسے کا نتیجہ ہوتے ہیں۔"}],[1197,"اس سند سے بھی ام المؤمنین عائشہ رضی اللہ عنہا نبی اکرم صلی اللہ علیہ وسلم سے اسی کے مثل روایت کرتی ہیں۔","",{"u2":"حضرت اشعث کی یہ روایت زائدہ کی بجائے ابو الاحوص سے بھی ہمیں عمرو بن علی نے اسی طرح بیان فرمائی۔"}],[1198,"اس سند سے بھی عائشہ رضی اللہ عنہا سے اسی جیسی حدیث مروی ہے۔","",{"u2":"حضرت اشعث کی یہی روایت عمرو بن علی نے ہمیں اسی طرح بیان فرمائی، لیکن اس میں زائدہ اور ابوالاحوص کی بجائے اسرائیل کا واسطہ ذکر کیا جب کہ ابو الشعثاء کی بجائے ابو عطیہ کا ذکر کیا۔"}],[1199,"ام المؤمنین عائشہ رضی اللہ عنہا کہتی ہیں کہ نماز میں ادھر ادھر دیکھنا چھینا جھپٹی ہے جسے شیطان نماز میں اس سے کرتا ہے۔","الألباني: صحيح موقوف",{"u2":"حضرت عائشہ رضی اللہ عنہا فرماتی ہیں کہ نماز میں ادھر ادھر دیکھنا شیطان کی لوٹ کھسوٹ ہے جو وہ انسان کی نماز (میں) سے کرتا ہے۔‘‘"}],[1200,"جابر رضی اللہ عنہ کہتے ہیں (ایک مرتبہ) رسول اللہ صلی اللہ علیہ وسلم بیمار ہوئے، تو ہم نے آپ کے پیچھے نماز پڑھی، آپ بیٹھ کر نماز پڑھا رہے تھے، اور ابوبکر رضی اللہ عنہ زور سے تکبیر کہہ کر لوگوں کو آپ کی تکبیر سنا رہے تھے، (نماز میں) آپ ہماری طرف متوجہ ہوئے تو آپ نے ہمیں دیکھا کہ ہم کھڑے ہیں، آپ نے ہمیں بیٹھنے کا اشارہ کیا، تو ہم بیٹھ گئے، اور ہم نے آپ کی امامت میں بیٹھ کر نماز پڑھی، جب آپ نے سلام پھیرا تو فرمایا: \"ابھی ابھی تم لوگ فارس اور روم والوں کی طرح کر رہے تھے، وہ لوگ اپنے بادشاہوں کے سامنے کھڑے رہتے ہیں، اور وہ بیٹھے رہتے ہیں، تو تم ایسا نہ کرو، اپنے اماموں کی اقتداء کرو، اگر وہ کھڑے ہو کر نماز پڑھیں تو تم کھڑے ہو کر پڑھو، اور اگر بیٹھ کر پڑھیں بھی بیٹھ کر پڑھو\" ۱؎۔\n§وضاحت\n۱؎: یہ واقعہ مرض الموت والے واقعے سے پہلے کا ہے، مرض الموت والے واقعے میں آپ نے بیٹھ کر امامت کرائی اور لوگوں نے کھڑے ہو کر آپ کے پیچھے نماز پڑھی، اور آپ نے اس بارے میں کچھ نہیں کہا، اس لیے وہ اب منسوخ ہے، اور نماز میں آپ صلی اللہ علیہ وسلم کا التفات کرنا آپ کی خصوصیات میں سے تھا، امت کے لیے آپ کا فرمان حدیث رقم: ۱۱۹۷ میں گزرا۔","الألباني: صحيح",{"u2":"حضرت جابر رضی اللہ عنہ بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم بیمار ہوگئے۔ ہم نے آپ کے پیچھے نماز پڑھی۔ آپ بیٹھے تھے اور حضرت ابوبکر رضی اللہ عنہ لوگوں کو آپ کی تکبیر سناتے تھے۔ آپ نے ہمیں کھڑے دیکھا۔ آپ نے ہمیں بیٹھنے کا اشارہ فرمایا۔ ہم بیٹھ گئے اور ہم نے آپ کے پیچھے بیٹھ کر نماز پڑھی۔ جب آپ نے سلام پھیرا تو فرمایا: ’’ابھی تم فارسیوں اور رومیوں جیسا کام کر رہے تھے۔ وہ اپنے بادشاہوں کے سامنے کھڑے رہتے ہیں جب کہ بادشاہ بیٹھے رہتے ہیں۔ تم ایسے نہ کرو۔ اپنے اماموں کی پیروی کرو۔ اگر وہ کھڑے ہو کر نماز پڑھیں تو تم بھی کھڑے ہوکر نماز پڑھو اور اگر وہ بیٹھ کر نماز پڑھیں تو تم بھی بیٹھ کر نماز پڑھو۔‘‘","f2":"(۱)امام کا بوقت ضرورت مقتدیوں کو کنکھیوں سے دیکھنا جائز ہے۔ (تفصیل دیکھیے، حدیث: ۱۱۹۶) (۲) بیٹھ کر نماز پڑھانے والے امام کے پیچھے مقتدی بیٹھ کر نماز پڑھیں یا کھڑے ہوکر؟ اس کی تفصیل دیکھیے، حدیث: ۸۳۳۔ (۳) یہ واقعہ آپ کے مرض الموت کا نہیں کیونکہ اس واقعہ کے بارے میں صراحت ہے کہ حضرت ابوبکر رضی اللہ عنہ اور مقتدی سب کھڑے تھے۔ (یہ الگ مسئلہ ہے کہ امام نبی صلی اللہ علیہ وسلم تھے یا ابوبکر؟ اس کے لیے دیکھیے: کتاب الامامۃ کا ابتدائیہ) یہ واقعہ پہلی کسی بیماری کے دوران کا ہے۔"}],[1201,"عبداللہ بن عباس رضی اللہ عنہم کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم اپنی نماز میں دائیں بائیں متوجہ ہوتے تھے ۱؎ لیکن آپ اپنی گردن اپنی پیٹھ کے پیچھے نہیں موڑتے تھے۔\n§وضاحت\n۱؎: اسے نفل نماز پر محمول کرنا اولی ہے، جیسا کہ سنن ترمذی میں انس رضی اللہ عنہ کی حدیث میں اس کی صراحت ہے، اور فرض میں بوقت اشد ضرورت ایسا کیا جا سکتا ہے جیسا کہ اگلی حدیث میں آ رہا ہے۔","الألباني: صحيح",{"u2":"حضرت ابن عباس رضی اللہ عنہما فرماتے ہیں کہ اللہ کے رسول صلی اللہ علیہ وسلم نماز میں دائیں بائیں دیکھ کیا کرتے تھے مگر اپنی گردن موڑ کر پچھلی طرف نہیں کرتے تھے۔","f2":"یہاں کنکھیوں سے دیکھنا مراد ہے جس سے چہرہ قبلہ رخ سے نہیں ہٹتا۔ اگر منہ موڑ کر دیکھنا مراد ہو تو یہ پہلے دور کی بات ہوگی، اب اس کی اجازت نہیں کیونکہ (الذین ھم فی صلوتھم خاشعون) (المؤمنون ۲:۲۳) کے خلاف ہے۔ منہ موڑٗنے سے گردن مڑے گی جو کہ جائز نہیں۔ ضرورت کے تحت کنکھیوں سے دیکھنا فرض نماز میں بھی ہوسکتا ہے اور نفل میں بھی۔"}],[1202,"ابوہریرہ رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے نماز (کی حالت) میں دو کالوں کو یعنی سانپ اور بچھو کو مارنے کا حکم دیا ہے۔","الألباني: صحيح",{"u2":"حضرت ابوہریرہ رضی اللہ عنہ بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے نماز میں دو سیاہ جانور (سانپ اور بچھو) قتل کرنے کا حکم دیا ہے۔"}],[1203,"ابوہریرہ رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے نماز میں دو کالوں کو مارنے کا حکم دیا۔","الألباني: صحيح",{"u2":"حضرت ابوہریرہ رضی اللہ عنہ بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے نماز میں دو سیاہ جانور (سانپ اور بچھو) قتل کرنے کا حکم دیا ہے","f2":"حکم سے مراد رخصت اور اجازت ہے کیونکہ یہ دونوں موذی جانور ہیں اور موذی جانور کو قتل کر دینا چاہیے، پہلے اس سے کہ وہ نقصان پہنچائے۔ قتل نہ کرنے کی صورت میں ساری نماز کے دوران میں توجہ سانپ بچھو کی طرف ہی رہے گی اور نماز میں خلل واقع ہوگا، اس لیے رخصت ہے کہ سانپ اور بچھو قتل کر دیے جائیں۔ باقی رہی یہ بات کہ اس فعل قتل سے نمازی کی نماز ٹوٹ جائے گی یا نہیں؟ تو علماء کی ایک جماعت نے الفاظِ حدیث کے پیش نظر یہی کہا ہے کہ اس سے نماز باطل نہیں ہوگی۔ صاحبِ سبل السلام کہتے ہیں: ’’یہ حدیث اس بات کی دلیل ہے کہ جو فعل ان کے قتل کے لیے ناگزیر ہے، اس سے نماز باطل نہیں ہوگی، چاہے وہ عمل قلیل ہو یا کثیر۔ دیکھیے: (سبل السلام، باب شروط الصلاۃ)"}],[1204,"ابوقتادہ رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نماز پڑھ رہے تھے، اور نماز کی حالت میں (اپنی نواسی) امامہ رضی اللہ عنہا کو اٹھائے ہوئے تھے، جب آپ سجدہ میں گئے تو انہیں اتار دیا، اور جب کھڑے ہوئے تو انہیں اٹھا لیا۔","الألباني: صحيح",{"u2":"حضرت ابوقتادہ رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم اپنی نواسی امامہ رضی اللہ عنہا کو اٹھا کر نماز پڑھ لیا کرتے تھے۔ جب آپ سجدہ کرتے تو اسے اتار دیتے اور جب کھڑے ہوتے تو اسے اٹھا لیتے۔","f2":"یہ امامہ رضی اللہ عنہا رسول اللہ صلی اللہ علیہ وسلم کی نواسی اور آپ کی بیٹی حضرت زینب رضی اللہ عنہا کی بیٹھی تھیں۔ ان کے والد ابوالعاص رضی اللہ عنہ کفر کی وجہ سے مکے میں رہ گئے تھے۔ جنگ بدر میں قیدی ہوئے تو نبی صلی اللہ علیہ وسلم نے انھیں اس شرط پر چھوڑ دیا کہ زینب کو بھیج دیں۔ انھوں نے جاتے ہی وعدے کے مطابق زینب رضی اللہ عنہا کو بحفاظت مدینہ منورہ پہنچا دیا۔ باپ دور ہونے کی وجہ سے نبی صلی اللہ علیہ وسلم امامہ سے خصوصی شفقت فرماتے تھے، اسی لیے کبھی کبھار وہ آپ کی گود میں مسجد میں آ جایا کرتی تھیں۔ یہ ابوالعاص رضی اللہ عنہ صلح حدیبیہ سے پہلے مسلمان ہوکر مدینہ منورہ آگئے تو آپ نے سابقہ نکاح قائم ہونے کی وجہ سے حضرت زینب رضی اللہ عنہا کو ان کی زوجیت میں رکھا۔ آپ نے بعض اوقات اس داماد (ابوالعاص) کو برسر منبر تعریف بھی فرمائی۔ رضی اللہ عنہ و أرضاہ۔ (تفصیل کے لیے دیکھیے، فوائد حدیث: ۷۱۲)"}],[1205,"ابوقتادہ رضی اللہ عنہ کہتے ہیں کہ میں نے نبی اکرم صلی اللہ علیہ وسلم کو دیکھا کہ آپ لوگوں کی امامت کر رہے ہیں، اور امامہ بنت ابی العاص رضی اللہ عنہم کو اپنے کندھے پر اٹھائے ہوئے ہیں، جب آپ رکوع میں گئے تو انہیں اتار دیا، اور جب سجدے سے فارغ ہوئے تو انہیں پھر اٹھا لیا۔","الألباني: صحيح",{"u2":"حضرت ابوقتادہ رضی اللہ عنہ بیان کرتے ہیں کہ میں نے دیکھا کہ نبی صلی اللہ علیہ وسلم لوگوں کو جماعت کروا رہے ہیں اور آپ نے امامہ بنت ابوالعاص کو اپنے کندھے پر اٹھا رکھا ہے۔ جب رکوع فرماتے تو بچی کو اتار دیتے اور جب سجدے سے فارغ ہوتے تو دوبارہ اٹھا لیتے۔","f2":"بعض علماء کا خیال ہے کہ بچے کو اٹھا کر نماز نہیں پڑھنی چاہیے کہ بچے کے جسم کی پاکیزگی کا یقین نہیں ہوتا۔ وہ حضرات اس اصول سے غافل ہوگئے کہ جب تک ظاہری نجاست نہ ہو تو بچے یا کسی بھی چیز کو پاک ہی تصور کیا جائے گا، نیز یہ ضرورت کی حالت میں ہے۔ ضرورت کی حالت میں ایسے امکانات مدنظر نہیں رکھے جاتے ورنہ زندگی اجیرن ہو جائے گی۔ بعض افاضل نے (شاید مذاقاً) کہا ہے کہ ’’بچی کو اٹھانے کی صورت میں رفع الیدین کہا گیا؟‘‘ ہم کہتے ہیں، جہاں پہلا گیا۔ حقیقت یہ ہے کہ آپ رکوع سے پہلے بچی کو اتار دیا کرتے تھے جیسا کہ حدیث میں ذکر ہے۔"}],[1206,"ام المؤمنین عائشہ رضی اللہ عنہا کہتی ہیں کہ میں نے دروازہ کھلوانا چاہا، اس وقت رسول اللہ صلی اللہ علیہ وسلم نفل نماز پڑھ رہے تھے، دروازہ قبلہ کی طرف پڑ رہا تھا، آپ اپنے دائیں جانب یا بائیں جانب (چند قدم) چلے، اور آپ نے دروازہ کھولا، پھر آپ اپنی جگہ پر واپس لوٹ آئے۔","الألباني: حسن",{"u2":"حضرت عائشہ رضی اللہ عنہا فرماتی ہیں کہ میں نے دروازہ کھٹکھٹایا۔ اللہ کے رسول صلی اللہ علیہ وسلم نفل نماز پڑھ رہے تھے۔ دروازہ قبلے کی جانب تھا۔ آپ نے تھوڑا سا دائیں یا بائیں چل کر دروازہ کھول دیا اور پھر اپنی نماز کی جگہ پر واپس چلے گئے۔","f2":"(۱)نفل نماز میں کچھ رعایت ہوتی ہے۔ ویسے بھی نبی صلی اللہ علیہ وسلم کا چہرہ قبلے سے تبدیل نہیں ہوا۔ چند قدم اٹھانے کی اجازت ہے۔ فرض نماز میں حضرت ابوبکر صدیق رضی اللہ عنہ کا پیچھے آنا اور رسول اللہ صلی اللہ علیہ وسلم کا آگے چلنا اس کی دلیل ہے۔ لیکن یہ یاد رہے کہ یہ رخصت ضرورت کے وقت ہی ہے۔ بلاوجہ چلنا نماز ضائع کر دے گا۔ (۲) محقق کتاب نے اس روایت کو سنداً ضعیف قرار دیا ہے جبکہ دیگر محققین نے اسے شواہد کی بنا پر حسن قرار دیا ہے اور انہی کی رائے اقرب الی الصواب معلوم ہوتی ہے۔ واللہ أعلم۔ مزید تفصیل کے لیے دیکھیے: (سنن أبي داود (مفصل) للألباني: ۴/۷۷، حدیث: ۸۵۵، والموسوعۃ الحدیثیۃ مسند الإمام أحمد: ۴۲/۳۲۰، ۳۲۱) (۳) جب گھر میں اور کئوی نہ ہو اور دروازہ قبلے کی جانب ہو تو نماز پڑھنے والا دروازہ کھول سکتا ہے۔"}],[1207,"ابوہریرہ رضی اللہ عنہ کہتے ہیں کہ نبی اکرم صلی اللہ علیہ وسلم نے فرمایا: \"سبحان اللہ کہنا مردوں کے لیے ہے، اور تالی بجانا عورتوں کے لیے ہے\"۔ ابن مثنی نے «في الصلاة» کا اضافہ کیا ہے (یعنی نماز میں)۔","الألباني: صحيح",{"u2":"حضرت ابوہریرہ رضی اللہ عنہ سے روایت ہے، نبی صلی اللہ علیہ وسلم نے فرمایا: ’’نماز میں (امام کو متوجہ کرنے کے لیے) سبحان اللہ کہنا مردوں کے لیے ہے اور تالی بجانا عورتوں کے لیے ہے۔‘‘","f2":"فائدہ: دیکھیے، حدیث: ۷۸۵۔"}],[1208,"ابوہریرہ رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا ہے: \"سبحان اللہ کہنا مردوں کے لیے ہے، اور تالی بجانا عورتوں کے لیے ہے\"۔","الألباني: صحيح",{"u2":"حضرت ابوہریرہ رضی اللہ عنہ سے روایت ہے، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’سبحان اللہ کہنا مردوں کے لیے ہے اور تالی بجانا عورتوں کے لیے۔‘‘"}],[1209,"ابوہریرہ رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"سبحان اللہ (کہنا) مردوں کے لیے ہے، اور دستک دینا عورتوں کے لیے ہے\"۔","الألباني: صحيح",{"u2":"حضرت ابوہریرہ رضی اللہ عنہ سے مروی ہے، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’سبحان اللہ کہنا مردوں کے لیے ہے اور تالی بجانا عورتوں کے لیے۔‘‘"}],[1210,"ابوہریرہ رضی اللہ عنہ کہتے ہیں کہ نبی اکرم صلی اللہ علیہ وسلم نے فرمایا: \"سبحان اللہ کہنا مردوں کے لیے ہے، اور تالی بجانا عورتوں کے لیے ہے\"۔\nابوجعد ضمری رضی اللہ عنہ (جنہیں صحابی ہونے کا شرف حاصل ہے) کہتے ہیں کہ نبی اکرم صلی اللہ علیہ وسلم نے فرمایا: \"جس نے تین جمعہ سستی سے چھوڑ دیا، اللہ تعالی اس کے دل پر مہر لگا دے گا\" ۱؎۔\n§وضاحت\n۱؎: یعنی اس کا دل خیر اور ہدایت کے قبول کرنے کی صلاحیت سے محروم کر دئیے جائیں گے۔","الألباني: صحيح",{"u2":"حضرت ابوہریرہ رضی اللہ عنہ سے منقول ہے، نبی صلی اللہ علیہ وسلم نے فرمایا: ’’سبحان اللہ کہنا مردوں کے لیے ہے اور تالی بجانا عورتوں کے لیے۔‘‘","f2":"مندرجہ بالا چاروں روایات میں ہے کہ مرد سبحان اللہ کہیں اور عورتیں تالی بجائیں۔"}],[1211,"علی رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم کی طرف سے میرے لیے ایک گھڑی ایسی مقرر تھی کہ میں اس میں آپ کے پاس آیا کرتا تھا، جب میں آپ کے پاس آتا تو اجازت مانگتا، اگر میں آپ کو نماز پڑھتے ہوئے پاتا تو آپ کھنکھارتے، تو میں اندر داخل ہو جاتا، اگر میں آپ کو خالی پاتا تو آپ مجھے اجازت دیتے۔","الألباني: ضعيف الإسناد",{"u2":"حضرت علی رضی اللہ بیان کرتے ہیں کہ میرے لیے ایک وقت مقرر تھا جب میں اللہ کے رسول صلی اللہ علیہ وسلم کے پاس حاضر ہوا کرتا تھا۔ جب میں آپ کے پاس آتا تو اجازت طلب کرتا۔ اگر میں آپ کو نماز کی حالت میں پاتا تو آپ کھنکار دیتے اور میں داخل ہو جاتا اور اگر میں آپ کو فراغت میں پاتا تو آپ مجھے اجازت عنایت فرماتے۔"}],[1212,"علی رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم کے پاس میرے آنے کے دو وقت تھے، ایک رات میں اور ایک دن میں، جب میں رات میں آپ کے پاس آتا (اور آپ نماز وغیرہ میں مشغول ہوتے) تو آپ میرے لیے کھنکھارتے ۱؎۔\n§وضاحت\n۱؎: یعنی کھنکھار کر اندر آنے کی اجازت دیتے، اور بعض نسخوں میں «تنحنح» کے بجائے «سبّح» ہے، اور یہ زیادہ قرین قیاس ہے کیونکہ اس کے بعد والی روایت میں ہے کہ کھنکھارنا عدم اجازت کی علامت تھی، یہ بھی ممکن ہے کہ اس کی دو ہیئت رہی ہو ایک اجازت پر دلالت کرتی رہی ہو، اور دوسری عدم اجازت پر، واللہ اعلم۔","الألباني: ضعيف الإسناد",{"u2":"حضرت علی رضی اللہ عنہ فرماتے ہیں: میرے لیے رسول اللہ صلی اللہ علیہ وسلم کے پاس جانے کے دو وقت مقرر تھے۔ ایک دن کو اور ایک رات کو۔ جب میں رات کو آپ کی خدمت میں حاضر ہوتا تو آپ کھنکار دیتے۔"}],[1213,"نجی کہتے ہیں کہ مجھ سے علی رضی اللہ عنہ نے کہا کہ رسول اللہ صلی اللہ علیہ وسلم کے یہاں میرا ایسا مقام و مرتبہ تھا جو مخلوق میں سے کسی اور کو میسر نہیں تھا، چنانچہ میں آپ کے پاس ہر صبح تڑکے آتا اور کہتا «السلام عليك يا نبي اللہ» \"اللہ کے نبی! آپ پر سلامتی ہو\" اگر آپ کھنکھارتے تو میں اپنے گھر واپس لوٹ جاتا، اور نہیں تو میں اندر داخل ہو جاتا۔","الألباني: ضعيف الإسناد",{"u2":"حضرت علی رضی اللہ عنہ فرماتے ہیں: رسول اللہ صلی اللہ علیہ وسلم کے نزدیک میرے لیے خصوصی مرتبہ و مقام تھا جو کسی دوسرے کا نہ تھا۔ میں ہر رات سحری کے وقت آپ کے پاس جاتا اور کہتا [اسلام علیک یا نبی اللہ] اگر آپ کھنکھارتے تو میں واپس گھر آجاتا ورنہ آپ کے پاس (اندر) چلا جاتا تھا۔","f2":"محقق کتاب نے پہلی دو روایتوں کو صحیح اور تیسری کو حسن قرار دیا ہے لیکن دیگر محققین کے نزدیک یہ حکم محل نظر ہے کیونکہ یہ روایات اولاً منقطع، ثانیاً سنداً و متنا مضطرب ہیں، لہٰذا تینوں روایات ضعیف ہیں۔ ان روایات کا مدار عبداللہ بن نجی پر ہے جو کہ متکلم فیہ راوی ہے۔ یحییٰ بن معین فرماتے ہیں: عبداللہ بن نجی نے حضرت علی رضی اللہ عنہ سے یہ روایت نہیں سنی۔ تفصیل کے لیے دیکھیے: (ذخیرۃ العقبی شرح سنن النسائي: ۱۴/۲۲۵)"}],[1214,"عبداللہ بن الشخیر رضی اللہ عنہ کہتے ہیں کہ میں نبی اکرم صلی اللہ علیہ وسلم کے پاس آیا، اس وقت آپ نماز پڑھ رہے تھے، اور آپ کے پیٹ سے ایسی آواز آ رہی تھی جیسے ہانڈی ابل رہی ہو یعنی آپ رو رہے تھے ۱؎۔\n§وضاحت\n۱؎: اس سے نماز میں اللہ کے خوف سے رونے کا جواز ثابت ہوا۔","الألباني: صحيح",{"u2":"حضرت مطرف اپنے والد (حضرت عبداللہ بن شخیر رضی اللہ عنہ) سے بیان کرتے ہیں، انھوں نے فرمایا: میں نبی صلی اللہ علیہ وسلم کے پاس آیا جب کہ آپ نماز پڑھ رہے تھے اور آپ کے سینے سے ایسی آواز آ رہی تھی جیسے ہنڈیا ابل رہی ہو، یعنی آپ رو رہے تھے۔","f2":"اللہ تعالیٰ کے خوف سے رونا نماز کا اصل مقصود ہے۔ عبادت چشم پرنم کی ہے۔ اصل نماز ہی یہ ہے کہ دل پر خوف باری تعالیٰ، خشیت الٰہی، ذکر آخرت اور جنت و جہننم کی یاد غالب آ جائے اور آنکھوں سے آنسو چھلکیں۔ ہاں، کسی تکلیف کی بنا پر یاد نبوی نقصان یا کسی کی یاد کی بنا پر روئے تو نماز کے منافی ہے۔"}],[1215,"ابو الدرداء رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نماز پڑھنے کھڑے ہوئے تو ہم نے آپ کو کہتے سنا: «أعوذ باللہ منك» \"میں اللہ کی پناہ چاہتا ہوں تجھ سے\" پھر آپ نے فرمایا: «ألعنك بلعنة اللہ» \"میں تجھ پر اللہ کی لعنت کرتا ہوں\" تین بار آپ نے ایسا کہا، اور اپنا ہاتھ پھیلایا گویا آپ کوئی چیز پکڑنی چاہ رہے ہیں، جب آپ نماز سے فارغ ہوئے تو ہم نے عرض کیا: اللہ کے رسول! ہم نے آپ کو نماز میں ایک ایسی بات کہتے ہوئے سنا جسے ہم نے اس سے پہلے آپ کو کبھی کہتے ہوئے نہیں سنا، نیز ہم نے آپ کو دیکھا کہ آپ اپنا ہاتھ پھیلائے ہوئے ہیں؟ تو آپ نے فرمایا: \"اللہ کا دشمن ابلیس آگ کا ایک شعلہ لے کر آیا تاکہ اسے میرے چہرے پر ڈال دے، تو میں نے تین بار کہا: میں اللہ کی پناہ چاہتا ہوں تجھ سے، پھر میں نے تین بار کہا: میں تجھ پر اللہ کی لعنت بھیجتا ہوں، پھر بھی وہ پیچھے نہیں ہٹا، تو میں نے ارادہ کیا کہ اس کو پکڑ لوں، اللہ کی قسم! اگر ہمارے بھائی سلیمان (علیہ السلام) کی دعا نہ ہوتی، تو وہ صبح کو اس (کھمبے) سے بندھا ہوا ہوتا، اور اس سے اہل مدینہ کے بچے کھیل کرتے\"۔","الألباني: صحيح",{"u2":"حضرت ابودرداء رضی اللہ عنہ سے روایت ہے، انھوں نے فرمایا: رسول اللہ صلی اللہ علیہ وسلم کھڑے نماز پڑھ رہے تھے کہ اچانک ہم نے آپ کو یہ فرماتے سنا: [أعوذ باللہ منک] ’’میں تجھ سے اللہ کی پناہ مانگتا ہوں۔‘‘ پھر آپ نے تین دفعہ فرمایا: [العنک بلعنۃ اللہ] ’’میں تجھ پر اللہ تعالیٰ کی لعنت بھیجتا ہوں۔‘‘ نیز آپ نے اپنا ہاتھ آگے بڑھایا گویا کہ کوئی چیز پکڑ رہے ہیں۔ جب آپ نماز سے فارغ ہوئے تو ہم نے کہا: اے اللہ کے رسول! ہم نے آج آپ کو نماز میں ایسے الفاظ کہتے سنا ہے جو اس سے پہلے کبھی نہیں سنے اور ہم نے آپ کو دیکھا کہ پ نے اپنا ہاتھ آگے بڑھایا تھا۔ آپ نے فرمایا: ’’اللہ کا دشمن ابلیس آگ کا ایک بھڑکتا ہوا شعلہ لے کر آیا تھا تاکہ میرے چہرے پر ڈال دے تو میں نے تین دفعہ کہا: [أعوذ باللہ منک] ’’میں تجھ سے اللہ کی پناہ مانگتا ہوں۔‘‘ پھر میں نے کہا: [العنک بلعنۃ اللہ] ’’میں تجھ پر اللہ کی لعنت بھیجتا ہوں۔‘‘ لیکن وہ پیچھے نہ ہٹا۔ تین دفعہ ایسا ہوا۔ آخر میں نے اسے پکڑنے کا ارادہ کیا۔ اللہ کی قسم! اگر میرے بھائی حضرت سلیمان علیہ السلام نے دعا نہ کی ہوتی تو اسے ستون سے باندھ دیا جاتا اور صبح اہل مدینہ کے بچے اس سے کھیلتے۔‘‘","f2":"(۱)اس روایت سے معلوم ہوا کہ شیطان پر لعنت بھیجنا اور اس سے تعوذ، خواہ صیغۂ خطاب کے ساتھ ہی ہو، نماز کو باطل نہیں کرتا کیونکہ اس سے مقصود خطاب نہیں ہوتا بلکہ لعنت وغیرہ مقصود ہوتی ہے۔ ہاں، اگر نماز میں جنوں سے کلام مقصود ہو تو نماز باطل ہو جائے گی۔ (۲) شیطان دراصل نبی صلی اللہ علیہ وسلم کو ڈرانا چاہتا تھا مگر اسے آپ کی روحانی قوت کا اندازہ نہ تھا۔ (۳) حضرت سلیمان علیہ السلام نے دعا کی تھی: ’’اے اللہ! مجھے ایسی حکومت عطا فرما جو میرے بعد کسی کو نہ ملے۔‘‘ (ص ۳۵:۳۸) اس حکومت کی ایک خصوصیت جنوں پر غلبہ بھی تھا۔ اگر نبی صلی اللہ علیہ وسلم اس جن کو پکڑ لیتے اور اسے ستون سے باندھ دیتے تو یہ ان کے اختصاص اور دعا کے منافی ہوتا کیونکہ اللہ تعالیٰ سلیمان علیہ السلام کی دعا قبول فرما چکا تھا۔ (۴) ممکن ہے وہ انسانی شکل میں آیا ہو اور آپ کے پکڑنے سے وہ آدمی کی صورت میں رہ جاتا۔ تبھی اسے باندھا جاتا اور بچوں کے لیے شغل کا موقع فراہم ہوتا ورنہ اصلی صورت میں تو یہ ممکن نہیں۔ (۵) قیدی کو مسجد میں باندھنا جائز ہے۔"}],[1216,"ابوہریرہ رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نماز کے لیے کھڑے ہوئے، آپ کے ساتھ ہم (بھی) کھڑے ہوئے، تو ایک اعرابی نے کہا (اور وہ نماز میں مشغول تھا): «اللہم ارحمني ومحمدا ولا ترحم معنا أحدا» \"اے اللہ! میرے اوپر اور محمد پر رحم فرما، اور ہمارے ساتھ کسی اور پر رحم نہ فرما\" ۱؎جب رسول اللہ صلی اللہ علیہ وسلم نے سلام پھیرا تو آپ نے اعرابی سے فرمایا: \"تو نے ایک کشادہ چیز کو تنگ کر دیا\"، آپ اس سے اللہ کی رحمت مراد لے رہے تھے۔\n§وضاحت\n۱؎: گرچہ یہ جملہ لوگوں کی عام دنیوی باتوں میں سے نہیں ہے، جو نماز میں ممنوع ہیں بلکہ ایک دعا ہے اور نماز میں دعا جائز ہے، لیکن پھر بھی غیر مناسب دعا ہے اس لیے آپ نے اس پر نکیر فرمائی۔","الألباني: صحيح",{"u2":"حضرت ابوہریرہ رضی اللہ عنہ فرماتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نماز کے لیے کھڑے ہوئے۔ ہم بھی آپ کے ساتھ کھڑے ہوئے ایک اعرابی نے دوران نماز میں کہا: [اللھم! ارحمنی…………] ’’اے اللہ! مجھ پر اور محمد صلی اللہ علیہ وسلم پر رحم فرما اور ہمارے علاوہ کسی اور پر رحم نہ فرما۔‘‘ جب رسول اللہ صلی اللہ علیہ وسلم نے سلام پھیرا تو اس اعرابی سے فرمایا: ’’تو نے ایک وسیع چیز کو تنگ کر دیا۔‘‘ آپ کا مقصد تھا کہ اللہ کی رحمت تو بہت وسیع ہے۔","f2":"(۱)اعرابی کا یہ کلام کسی انسان سے کلام نہیں تھا کہ اس سے نماز میں نقص پڑتا۔ یہ مسنون اور مقررہ دعاؤں میں سے نہیں ہے، اسی لیے باب کے عنوان میں قوسین کے ذریعے سے وضاحت کی گئی ہے۔ باب کا مقصد یہ ہے کہ اس قسم کا کلام اگرچہ نماز میں مناسب نہیں مگر چونکہ اللہ تعالیٰ ہی سے خطاب ہے، لہٰذا اس سے نماز باطل نہ ہوگی۔ ویسے نماز میں مسنون اور منقول دعاؤں سے تجاوز نہیں کرنا چاہیے۔ ممکن ہے اپنی طرف سے بنائی ہوئی دعا درست نہ ہو۔ (۲) دعا جامع اور وسعت کی حامل ہونی چاہیے، چنانچہ ایسی دعا کرنا درست نہیں جس میں اللہ تعالیٰ کے وسیع فضل و کرم کو محدود کر دیا جائے۔"}],[1217,"ابوہریرہ رضی اللہ عنہ سے روایت ہے کہ ایک اعرابی مسجد میں داخل ہوا، اور اس نے دو رکعت نماز پڑھی، پھر اس نے (نماز ہی میں) کہا: «اللہم ارحمني ومحمدا ولا ترحم معنا أحدا» \"اے اللہ! مجھ پر اور محمد پر رحم فرما، اور ہمارے ساتھ کسی اور پر رحم نہ فرما\" تو رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"تو نے ایک کشادہ چیز کو تنگ کر دیا\"۔","الألباني: صحيح",{"u2":"حضرت ابوہریرہ رضی اللہ عنہ سے روایت ہے کہ ایک اعرابی مسجد میں داخل ہوا۔ اس نے دو رکعتیں پڑھیں، پھر کہنے لگا: [اللھم! ارحمنی………] ’’اے اللہ! مجھ پر اور محمد صلی اللہ علیہ وسلم پر رحم فرما۔ ہمارے ساتھ کسی اور پر رحم نہ فرما۔‘‘ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’تو نے ایک وسیع چیز کو تنگ کر دیا۔‘‘","f2":"’’تو نے ایک وسیع چیز کو تنگ کر دیا۔‘‘ اللہ کی رحمت انسان کے وہم و گمان میں نہیں آسکتی۔ اس میں کوئی تحدید نہیں، لہٰذا مانگتے وقت شرمانا چاہیے نہ دل چھوٹا کرنا چاہیے۔ امکان و عدم امکان کی بحث ہمارے لیے ہے۔ اللہ تعالیٰ کے سامنے ہر چیز حاضر اور موجود ہے۔ انسان دل کھول کر مانگے۔ اسباب کا وجود بھی حق تعالیٰ کے ہاتھ میں ہے۔ وہ خود مہیا فرمائے گا، البتہ یہ ضروری ہے کہ سائل مانگنے والی شکل بنائے"}],[1218,"معاویہ بن حکم سلمی رضی اللہ عنہ کہتے ہیں کہ میں نے عرض کیا: اللہ کے رسول! ہمارا جاہلیت کا زمانہ ابھی ابھی گزرا ہے، پھر اللہ تعالی اسلام کو لے آیا، ہم میں سے کچھ لوگ ایسے ہیں جو برا شگون لیتے ہیں! آپ نے فرمایا: \"یہ محض ایک خیال ہے جسے لوگ اپنے دلوں میں پاتے ہیں، تو یہ ان کے آڑے نہ آئے\" ۱؎ معاویہ بن حکم نے کہا: اور ہم میں بعض لوگ ایسے ہیں جو کاہنوں کے پاس جاتے ہیں! تو آپ نے فرمایا: \"تم لوگ ان کے پاس نہ جایا کرو\"، پھر معاویہ رضی اللہ عنہ نے کہا: اللہ کے رسول! اور ہم میں سے کچھ لوگ (زمین پر یا کاغذ پر آئندہ کی بات بتانے کے لیے) لکیریں کھینچتے ہیں! آپ نے فرمایا: \"نبیوں میں سے ایک نبی بھی لکیریں کھینچتے تھے، تو جس شخص کی لکیر ان کے موافق ہو تو وہ صحیح ہے\"۔ معاویہ رضی اللہ عنہ کہتے ہیں: میں رسول اللہ صلی اللہ علیہ وسلم کے ساتھ نماز پڑھ ہی رہا تھا کہ اسی دوران اچانک قوم میں سے ایک آدمی کو چھینک آ گئی، تو میں نے (زور سے) «يرحمك اللہ» \"اللہ تجھ پر رحم کرے\" کہا، تو لوگ مجھے گھور کر دیکھنے لگے، میں نے کہا: «واثكل أمياه» \"میری ماں مجھ پر روئے\"، تم لوگوں کو کیا ہو گیا ہے کہ تم مجھے گھور رہے ہو؟ لوگوں نے (مجھے خاموش کرنے کے لیے) اپنے ہاتھوں سے اپنی رانوں کو تھپتھپایا، جب میں نے انہیں دیکھا کہ وہ مجھے خاموش کر رہے ہیں تو میں خاموش ہو گیا، پھر جب رسول اللہ صلی اللہ علیہ وسلم نماز سے فارغ ہوئے تو آپ نے مجھے بلایا، میرے ماں باپ آپ پر فدا ہوں، نہ تو آپ نے مجھے مارا، نہ ہی مجھے ڈانٹا، اور نہ ہی برا بھلا کہا، میں نے اس سے پہلے اور اس کے بعد آپ سے اچھا اور بہتر معلم کسی کو نہیں دیکھا، آپ نے فرمایا: \"ہماری اس نماز میں لوگوں کی گفتگو میں سے کوئی چیز درست نہیں، نماز تو صرف تسبیح، تکبیر اور قرأت قرآن کا نام ہے\"، پھر میں اپنی بکریوں کی طرف آیا جنہیں میری باندی احد پہاڑ اور جوانیہ ۲؎ میں چرا رہی تھی، میں (وہاں) آیا تو میں نے پایا کہ بھیڑیا ان میں سے ایک بکری اٹھا لے گیا ہے، میں (بھی) بنو آدم ہی میں سے ایک فرد ہوں، مجھے (بھی) غصہ آتا ہے جیسے انہیں آتا ہے، چنانچہ میں نے اسے ایک چانٹا مارا، پھر میں لوٹ کر رسول اللہ صلی اللہ علیہ وسلم کے پاس آیا، میں نے آپ کو اس واقعہ کی خبر دی، تو آپ نے مجھ پر اس کی سنگینی واضح کی، تو میں نے عرض کیا: اللہ کے رسول! کیا میں اس کو آزاد نہ کر دوں؟ آپ صلی اللہ علیہ وسلم نے فرمایا: \"اسے بلاؤ\"، تو رسول اللہ صلی اللہ علیہ وسلم نے اس سے پوچھا: \"اللہ کہاں ہے؟\" اس نے جواب دیا: آسمان کے اوپر، آپ نے پوچھا: \"میں کون ہوں؟\" اس نے کہا: آپ اللہ کے رسول ہیں، آپ صلی اللہ علیہ وسلم نے فرمایا: \"یہ مومنہ ہے، تو تم اسے آزاد کر دو\"۔\n§وضاحت\n۱؎: یعنی یہ بدشگونی انہیں کسی کام سے جس کے کرنے کا انہوں نے ارادہ کیا ہو نہ روکے۔ ۲؎: احد پہاڑ کے قریب ایک جگہ کا نام ہے۔","الألباني: صحيح",{"u2":"حضرت معاویہ بن حکم سلمی رضی اللہ عنہ فرماتے ہیں کہ میں نے کہا: اے اللہ کے رسول! ہم نے جاہلیت ابھی تازہ تازہ چھوڑی ہے اور اللہ تعالیٰ نے اسلام بھیجا ہے۔ ہم میں سے کچھ لوگ بدشگونی پکڑتے ہیں۔ آپ نے فرمایا: ’’یہ ایک بے حقیقت چیز ہے جسے وہ اپنے دلوں میں محسوس کرتے ہیں، لہٰذا یہ انھیں ان کے کام کاج سے نہ روکے۔‘‘ (میں نے کہا:) اور ہم میں سے کچھ لوگ کاہنوں کے پاس جاتے ہیں۔ آپ نے فرمایا: ’’ان کے پاس مت جایا کرو۔‘‘ میں نے کہا: اے اللہ کے رسول! اور ہم میں سے کچھ لوگ خط کھینچتے ہیں۔ آپ نے فرمایا: ’’نبیوں میں سے ایک نبی (علیہ السلام) خط کھینچا کرتے تھے۔ جو شخص ان کے مطابق خط کھینچے، وہ تو ٹھیک ہے (اور باقی غلط)۔‘‘ معاویہ رضی اللہ عنہ کہتے ہیں کہ ایک دفعہ میں رسول اللہ صلی اللہ علیہ وسلم کے ساتھ نماز پڑھ رہا تھا کہ ایک آدمی کو چھینک آگئی۔ میں نے [برحمک اللہ] ’’اللہ تعالیٰ تجھ پر رحم فرمائے‘‘ کہہ دیا۔ لوگ مجھے گھور گھور کر دیکھنے لگے۔ میں نے (پریشان ہوکر) کہا: ہائے! میری ماں مجھے گم کرے! (یعنی میں مر جاؤں) تمھیں کیا ہوا ہے کہ تم مجھے اس طرح دیکھ رہے ہو؟ لوگ (بے بسی سے) اپنے رانوں پر ہاتھ مارنے لگے (کیونکہ وہ نماز کی وجہ سے بول نہیں سکتے تھے۔) جب میں نے محسوس کیا کہ وہ مجھے چپ کرا رہے ہیں تو آخر میں چپ ہوگیا۔ جب رسول اللہ صلی اللہ علیہ وسلم نماز سے فارغ ہوئے تو مجھے بلایا۔ میرے ماں باپ آپ پر فدا ہوں! آپ نے مجھے مارا، نہ جھڑکا، نہ برا بھلا کہا۔ واللہ! میں نے آپ سے پہلے یا بعد کوئی استاد آپ سے زیادہ اچھے انداز میں تعلیم دینے والا نہیں دیکھا۔ آپ نے (شفقت سے) فرمایا: ’’ہماری اس نماز میں لوگوں کی کسی قسم کی بات کرنا جائز اور درست نہیں۔ نماز تو صرف تسبیحات، تکبیرات اور تلاوت قرآن کا نام ہے۔‘‘ حضرت معاویہ نے کہا: پھر ایک دفعہ میں اپنی کچھ بکریاں دیکھنے گیا جنھیں میری ایک لونڈی جبل احد اور جوانیہ کی طرف چرایا کرتی تھی۔ میں نے اچھی طرح جائزہ لیا تو پتہ چلا کہ ایک بکری کو بھیڑیا لے گیا ہے، میں بھی اولاد آدم میں سے ایک آدمی تھا، مجھے غصہ آ گیا جس طرح لوگوں کو غصہ آتا ہے۔ میں نے اسے تھپڑ مار دیا۔ پھر (مجھے ندامت ہوئی تو) میں رسول اللہ صلی اللہ علیہ وسلم کے پاس گیا اور آپ کو سارا واقعہ بتایا۔ آپ نے اسے میری بہت بڑی غلطی قرار دیا تو میں نے کہا: اے اللہ کے رسول! کیا میں اسے آزاد ہی نہ کر دوں؟ آپ نے فرمایا: ’’اسے میرے پاس بلاؤ۔‘‘ (میں اسے لایا تو) رسول اللہ صلی اللہ علیہ وسلم نے اس سے پوچھا: ’’اللہ تعالیٰ کہاں ہے؟‘‘ اس نے کہا: آسمان میں (یعنی اوپر)۔ آپ نے فرمایا: ’’میں کون ہوں؟‘‘ اس نے کہا: آپ اللہ کے رسول ہیں۔ آپ نے فرمایا: ’’یہ مومنہ عورت ہے، اسے آزاد کر دو۔‘‘","f2":"(۱) جاہلیت سے مراد اسلام سے ماقبل کے رواج ہیں۔ عموماً ان کی بنیاد جاہلیت پر تھی، لہٰذا انھیں جاہلیت کہا گیا ہے۔ (۲) ’’بے حقیقت چیز ہے۔‘‘ یعنی اس کی کوئی بنیاد نہیں، صرف ان کا دلی وہم ہے۔ بعض نے اس جملے کے یہ معنی بھی کیے ہیں کہ ’’ایسے خیالات تو دل میںآ ہی جایا کرتے ہیں، اس میں کوئی گناہ نہیں۔ ہاں: ایسے خیالات کی بنا پر وہ اپنے کام کاج سے نہ رکیں۔‘‘ (۲) ’’کاہن‘‘ غیب کی باتیں بتانے والے کو کہا جاتا ہے، خواہ وہ جنوں کی مدد سے بتائیں یا نجوم و خطوط اور لکیروں کی مدد سے یا اٹکل اور ظن و تخمین سے۔ چونکہ ان کی بات کی صحت یقینی نہیں ہوتی، لہٰذا ان سے پوچھنا اور ان کی بات پر یقین کرنا شریعت اسلامیہ میں منع ہے۔ ان کی غلط باتیں بسا اوقات باہمی تعلقات کی خرابی اور فساد کا موجب بنتی ہیں۔ عقیدہ الگ خراب ہوتا ہے، البتہ کبھی فراست و ذہانت کی بنا پر صحیح نتیجے تک پہنچ جانے والے کو بھی کاہن کہہ دیا جاتا ہے، حالانکہ یہ مذموم نہیں، خصوصاً جب کہ ان کی بات دوسرے دلائل سے بالکل صحیح ثابت ہو جائے۔ جیسے حضرت سلیمان علیہ السلام، حضرت محمد صلی اللہ علیہ وسلم، حضرت عمر و علی رضی اللہ عنہما اور قاضی شریح و ایاس رحمہا اللہ وغیرہ کے واقعات مشہور ہیں۔ لیکن فراست والی بات بھی اسی وقت صحیح ہوگی جب بعد میں وہ صحیح ثابت ہو جائے ورنہ کسی صاحب فراست کی بات کو آنکھیں بند کرکے تسلیم نہیں کیا جا سکتا۔ بہرحال کہانت حرام ہے اور اسے ماننا بھی، نیز کہانت کی طرح بدشگونی لینا بھی حرام ہے۔ (۴) ’’ایک نبی خط کھینچا کرتے تھے۔‘‘ واللہ اعلم وہ کیسے خط کھینچتے تھے؟ کیا حساب تھا؟ کہیں صراحت نہیں ہے، لہٰذا شریعت اسلامیہ میں یہ قطعاً ممنوع ہے۔ (۵) ’’نماز میں لوگوں کی کسی قسم کی بات کرنا درست نہیں‘‘ مذکورہ صحابی اس وقت اس مسئلے سے واقف نہیں تھے، لہٰذا انھیں معذور سمجھا اور قضا کا حکم نہیں دیا ورنہ آپ کے الفاظ صراحتاً ثابت کر رہے ہیں کہ اس صورت میں نماز نہ ہوگی۔ (۶) ’’جوانیہ‘‘ مدینہ منورہ کے شمال میں احد پہاڑ کے قریب ایک جگہ کا نام ہے۔ (۷) ’’بڑی غلطی‘‘ کیونکہ وہ لوگنڈی بھیڑیے کے سامنے بے بس تھی اور بے قصور تھی۔ (۸) ’’آسمان میں‘‘ مذکورہ حدیث سے معلوم ہوا کہ کسی سے پوچھا جا سکتا ہے، اللہ تعالیٰ کہاں ہے؟ اور جواب میں آسمان یا عرش کا نام لیا جا سکتا ہے۔ اس سے اللہ تعالیٰ کی کوئی توہین نہیں ہوگی۔ اسی طرح اللہ تعالیٰ کی طرف اوپر کو اشارہ کیا جا سکتا ہے۔ اس کے عرش پر مستوی ہونے کو بیان کیا جا سکتا ہے۔ اس سے اللہ تعالیٰ نہ تو کسی جگہ کا محتاج ہو جائے گا نہ اس میں مقید۔ قرآن مجید اور احادیث صحیحہ میں اس کے نظائر موجود ہیں، مثلاً: ارشاد باری ہے: (ام امنتم من فی السماء) (الملک ۱۷:۶۷) اسی طرح (الرحمن علی العرشن استوی) (طہ ۵:۲۰) نیز حدیث شریف میں ہے: [ارحموا أھل الارض یرحمکم من في السمآء] (سنن أبي داود، الأدب، حدیث: ۴۹۴۱) بعض لوگ جنھیں اللہ تعالیٰ کی فکر اللہ تعالیٰ اور اس کے رسول صلی اللہ علیہ وسلم سے بھی بڑھ کر ہے، اس قسم کی عبارات کو اللہ تعالیٰ کے حق میں جائز نہیں سمجھتے مگر یہ ان کی بے علمی ہے۔ ان مسائل میں سلف صالحین (صحابہ و تابعین) اور محدثین کا مسلک ہی صحیح ہے کہ اللہ تعالیٰ کی صفات جو قرآن مجید اور احادیث صحیحیہ و صریح سے ثابت ہیں، انھیں بلاجھجک مانا جائے، بولا جائے اور کسی قسم کی تاویل نہ کی جائے، نہ ان میں بحث کی جائے کیونکہ یہ چیزیں انسان کی عقل سے ماوراء ہیں۔ ان کی حقیقت اللہ عزوجل کے سپرد کر دی جائے۔ تشبیہ دی جائے نہ انکار کیا جائے، بلکہ قیامت کا انتظار کیا جائے کہ اس دن ہر چیز واضح ہو جائے گی، آنکھوں کے سامنے ہوگی، کہیں اس دن ندامت نہ ہو۔ (۹) ’’یہ مومنہ عورت ہے۔‘‘ معلوم ہوتا ہے کہ اگر کسی کفارے وغیرہ میں غلام آزاد کرنا ہو تو وہ مومن ہونا چاہیے۔ قرآن مجید میں بھی بغض مقامات پر قید ہے: (تحریر رقبۃ مومنۃ) (النسآء ۹۲:۴) باقی مقامات پر بھی یہ قید معتبر ہوگی۔ نفل آزادی میں بھی مومن کو آزاد کرنا افضل ہے، ضروری نہیں۔ (۱۰) خادموں اور ملازموں کے ساتھ نرمی و شفقت سے پیش آنا چاہیے اگر کبھی کبھار سختی ہو جائے تو ان کی دلجوئی بھی کرنی چاہیے"}],[1219,"زید بن ارقم رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم کے زمانہ میں (شروع میں) آدمی نماز میں اپنے ساتھ والے سے ضرورت کی باتیں کر لیا کرتا تھا، یہاں تک کہ آیت کریمہ: «حافظوا على الصلوات والصلاة الوسطى وقوموا لله قانتين» \"محافظت کرو نمازوں کی، اور بیچ والی نماز کی، اور اللہ کے لیے خاموش کھڑے رہو\" نازل ہوئی تو (اس کے بعد سے) ہمیں خاموش رہنے کا حکم دے دیا گیا (البقرہ: ۲۳۸)۔","الألباني: صحيح",{"u2":"حضرت زید بن ارقم رضی اللہ عنہ بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم کے (ابتدائی) دور میں لوگ نماز میں اپنے ساتھی سے ضرورت کی بات کر لیتے تھے حتی کہ یہ آیت اتری: (حافظوا علی الصلوت و الصلوۃ الوسطی و قومو اللہ فنتین) ’’تم سب نمازوں کی حفاظت کرو اور خاص طور پر افضل نماز کی اور اللہ کے سامنے فرماں بردار ہوکر کھڑے رہو۔‘‘ تو ہمیں (اس قسم کی باتوں سے) خاموش رہنے کا حکم دیا گیا۔","f2":"(۱)’’ضرورت کی بات‘‘ مثلاً: سلام کا جواب، چھینک پر دعا، نماز سے متعلقہ وضاحتوغیرہ، نہ کہ گھریلو باتیں یا کاروباری باتیں۔ (۲) ’’افضل نماز‘‘ حدیث: ۴۷۳ میں گزر چکا ہے کہ اس سے مراد عصر کی نماز ہے۔ اس کے متعلق اور اقوال بھی ہیں مگر راجح قول یہی ہے۔ تفصیل کے لیے دیکھیے: (ذخیرۃ العقبی شرح سنن النسائي: ۶/۱۵۷-۱۶۲، حدیث: ۴۷۳) (۳) ’’خاموش رہنے کا حکم‘‘ یعنی اپنے ساتھی سے باتیں کرنے سے، نہ کہ مطلقاً کہ اذکار و اور ادیا قراءت فاتحہ بھی ممنوع ہو جائیں۔ ایسی تو کوئی نماز ہی نہیں جس میں کچھ نہ پڑھا جائے اور مکمل خاموشی ہو۔ ہاں! جماعت کی صورت میں جہر سے روکا گیا ہے۔ (۴) شریعت میں نسخ ثابت ہے۔ (۵) کلام کسی بھی قسم کا ہو اس سے نماز باطل ہو جاتی ہے۔"}],[1220,"عبداللہ بن مسعود رضی اللہ عنہ کہتے ہیں کہ میں نبی اکرم صلی اللہ علیہ وسلم کے پاس آتا تھا، اور آپ نماز پڑھ رہے ہوتے تھے تو میں آپ کو سلام کرتا، تو آپ مجھے جواب دیتے، (ایک بار) میں آپ کے پاس آیا، اور میں نے آپ کو سلام کیا، آپ نماز پڑھ رہے تھے تو آپ نے مجھے جواب نہیں دیا، جب آپ نے سلام پھیرا، تو لوگوں کی طرف اشارہ کیا، اور فرمایا: \"اللہ نے نماز میں ایک نیا حکم دیا ہے کہ تم لوگ (نماز میں) سوائے ذکر الٰہی اور مناسب دعاؤں کے کوئی اور گفتگو نہ کرو، اور اللہ کے لیے یکسو ہو کر کھڑے رہا کرو\"۔","الألباني: صحيح",{"u2":"حضرت عبداللہ بن مسعود رضی اللہ عنہ فرماتے ہیں کہ میں نبی صلی اللہ علیہ وسلم کے پاس آیا کرتا تھا جب کہ آپ نماز پڑھ رہے ہوتے۔ میں آپ کو سلام کہتا تو آپ مجھے سلام کا جواب دے دیا کرتے تھے۔ ایک دن میں آیا اور آپ نماز پڑھ رہے تھے۔ میں نے آپ کو سلام کہا، آپ نے مجھے جواب نہیں دیا۔ جب آپ نے سلام پھیرا تو لوگوں کی طرف اشارہ کیا اور فرمایا: ’’(اے لولو!) اللہ تعالیٰ نے نماز کے بارے میں ایک نیا حکم جاری کیا ہے کہ تم (نماز میں) اللہ کے ذکر اور نماز کے مناسب الفاظ کے علاوہ کوئی کلام نہ کرو اور اللہ تعالیٰ کے سامنے عاجزی اور سکون سے کھڑے رہو","f2":"اس حدیث کو امام سفیان ثوری رحمہ اللہ سے ان کے دو شاگرد ابن ابی غتیۃ (یحییٰ بن عبدالملک) اور قاسم بن یزید بیان کرتے ہیں لیکن اس حدیث کے الفاظ قاسم بن یزید کے ہیں، ابن غتیۃ اس حدیث کو بالمعنی روایت کرتے ہیں"}],[1221,"عبداللہ بن مسعود رضی اللہ عنہ کہتے ہیں کہ ہم نبی اکرم صلی اللہ علیہ وسلم کو سلام کرتے تھے، تو آپ ہمیں سلام کا جواب دیتے تھے، یہاں تک کہ ہم سر زمین حبشہ سے واپس آئے تو میں نے آپ کو سلام کیا، تو آپ نے مجھے جواب نہیں دیا، تو مجھے نزدیک و دور کی فکر لاحق ہوئی ۱؎ لہٰذا میں بیٹھ گیا یہاں تک کہ جب آپ نے نماز ختم کر لی تو فرمایا: \"اللہ تعالی جب چاہتا ہے نیا حکم دیتا ہے، اب اس نے یہ نیا حکم دیا ہے کہ (اب) نماز میں گفتگو نہ کی جائے\"۔\n§وضاحت\n۱؎: یعنی میرے دل میں طرح طرح کے وسوسے آنے لگے۔","الألباني: حسن صحيح",{"u2":"حضرت ابن مسعود رضی اللہ عنہ فرماتے ہیں کہ ہم (پہلے پہل) نبی صلی اللہ علیہ وسلم کو (نماز کی حالت میں) سلام کر دیا کرتے تھے اور آپ جواب بھی دے دیا کرتے تھے حتی کہ ہم حبشہ کے علاقے سے واپس آئے تو میں نے آپ کو (نماز کی حالت میں) سلام کیا۔ آپ نے مجھے جواب نہ دیا۔ مجھے تو قریب اور دور کی سوچیں آنے لگیں (کہ جواب نہ دینے کی کیا وجہ ہوسکتی ہے؟) میں بیٹھ گیا حتی کہ جب آپ نے نماز پوری فرمائی تو فرمایا: ’’بلاشبہ اللہ تعالیٰ جو چاہتا ہے، نیا حکم جاری فرماتا ہے اور اللہ تعالیٰ نے یہ نیا حکم جاری کیا ہے کہ نماز میں بات چیت نہ کی جائے۔‘‘"}],[1222,"عبداللہ بن بحینہ رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے ہم کو دو رکعت نماز پڑھائی، پھر آپ کھڑے ہو گئے اور بیٹھے نہیں، تو لوگ (بھی) آپ کے ساتھ کھڑے ہو گئے، جب آپ نے نماز مکمل کر لی، اور ہم آپ کے سلام پھیرنے کا انتظار کرنے لگے، تو آپ نے اللہ اکبر کہا، اور سلام پھیرنے سے پہلے بیٹھے بیٹھے دو سجدے کیے، پھر آپ نے سلام پھیرا۔","الألباني: صحيح",{"u2":"حضرت عبداللہ ابن بحینہ رضی اللہ عنہ فرماتے ہیں: رسول اللہ صلی اللہ علیہ وسلم نے ہمیں دو رکعتیں پڑھائیں، پھر اٹھ کھڑے ہوئے، بیٹھے نہیں۔ لوگ بھی آپ کے ساتھ کھڑے ہوگئے۔ جب آپ نے نماز مکمل فرما لی اور ہم آپ کے سلام کے انتظار میں تھے تو آپ نے اللہ اکبر کہہ کر دو سجدے کیے جب کہ آپ سلام سے قبل بیٹھے تھے۔ پھر آپ نے سلام پھیرا"}],[1223,"عبداللہ ابن بحینہ رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نماز میں کھڑے ہو گئے حالانکہ آپ کو تشہد کے لیے بیٹھنا چاہیئے تھا، تو آپ نے سلام پھیرنے سے پہلے بیٹھے بیٹھے دو سجدے کئے۔","الألباني: صحيح",{"u2":"حضرت عبداللہ ابن بحینہ سے روایت ہے، رسول اللہ صلی اللہ علیہ وسلم نماز میں (دو رکعتوں کے بعد) کھڑے ہوگئے، حالانکہ آپ نے بیٹھنا تھا تو آپ نے (آخر میں) سلام سے پہلے بیٹھے بیٹھے دو سجدے کیے۔","f2":"مذکورہ احادیث میں سجود و سہو سلام سے پہلے کرنے کا ذکر ہے لیکن اہل علم کا اس مسئلے کی بابت دیگر احادیث میں مختلف طریقے بیان ہونے کی وجہ سے اختلاف ہے۔ امام شوکانی رحمہ اللہ نے اس مسئلے کے متعلق اہل علم کے آٹھ اقوال نقل کیے ہیں جس کی تفصیل اسی کتاب کے ابتدائیے میں گزر چکی ہے۔"}],[1224,"ابوہریرہ رضی اللہ عنہ کہتے ہیں کہ نبی اکرم صلی اللہ علیہ وسلم نے ہم کو شام کی دونوں نمازوں (ظہر یا عصر) میں سے کوئی ایک نماز پڑھائی، لیکن میں بھول گیا (کہ آپ نے کون سی نماز پڑھائی تھی) تو آپ نے ہمیں دو رکعتیں پڑھائیں پھر سلام پھیر دیا، پھر آپ مسجد میں لگی ایک لکڑی کی جانب گئے، اور اس پر اپنا ہاتھ رکھا، ایسا محسوس ہو رہا تھا کہ گویا آپ غصہ میں ہیں، اور جلد باز لوگ مسجد کے دروازے سے نکل گئے، اور کہنے لگے: نماز کم کر دی گئی ہے، لوگوں میں ابوبکر اور عمر رضی اللہ عنہم (بھی) تھے، لیکن وہ دونوں ڈرے کہ آپ سے اس سلسلہ میں پوچھیں، لوگوں میں ایک شخص تھے جن کے دونوں ہاتھ لمبے تھے، انہیں \"ذوالیدین\" (دو ہاتھوں والا) کہا جاتا تھا، انہوں نے عرض کیا: اللہ کے رسول! آپ بھول گئے ہیں یا نماز ہی کم کر دی گئی ہے؟ آپ صلی اللہ علیہ وسلم نے فرمایا: \"نہ تو میں بھولا ہوں، اور نہ نماز ہی کم کی گئی ہے\"، آپ نے (لوگوں سے) پوچھا: \"کیا ایسا ہی ہے جیسے ذوالیدین کہہ رہے ہیں؟\" لوگوں نے عرض کیا: جی ہاں، (ایسا ہی ہے) چنانچہ آپ(مصلے پر واپس آئے) اور وہ (دو رکعتیں) پڑھیں جنہیں آپ نے چھوڑ دیا تھا، پھر سلام پھیرا، پھر اللہ اکبر کہا اور اپنے سجدوں کے جیسا یا ان سے لمبا سجدہ کیا، پھر آپ نے اپنا سر اٹھایا، اور اللہ اکبر کہا، اور اپنے سجدوں کی طرح یا ان سے لمبا سجدہ کیا، پھر اپنا سر اٹھایا پھر اللہ اکبر کہا۔","الألباني: صحيح",{"u2":"حضرت ابوہریرہ رضی اللہ عنہ بیان کرتے ہیں کہ نبی صلی اللہ علیہ وسلم نے ہمیں ظہر اور عصر میں سے کوئی ایک نماز پڑھائی۔ لیکن میں بھول گیا کہ وہ کون سی تھی؟ آپ صلی اللہ علیہ وسلم نے ہمیں دو رکعتیں پڑھا کر سلام پھیر دیا۔ پھر آپ مسجد میں رکھی ہوئی ایک لکڑی کی طرف گئے اور اپنا ہاتھ اس پر رکھ لیا۔ یوں لگتا تھا جیسے آپ غصے میں ہوں۔ کچھ جلد باز لوگ مسجد کے دروازوں سے نکل بھی گئے اور کہنے لگے: نماز کم ہوگئی۔ لوگوں (نمازیوں) میں ابوبکر اور عمر رضی اللہ عنہما بھی شامل تھے مگر آپ سے (اس مسئلے میں) بات چیت کرنے سے وہ بھی ڈرے رہے۔ لوگوں میں ایک لمبے ہاتھوں والا شخص تھا جسے ذوالیدین (لمبے ہاتھوں والا) کہا جاتا تھا، اس نے کہا: اے اللہ کے رسول! آپ بھول گئے یا نماز کم ہوگئی؟ آپ نے فرمایا: ’’میں بھولا ہوں نہ نماز کم ہوئی ہے۔‘‘ (ذوالیدین نے کہا: ایک کام تو ضرور ہوا ہے۔) آپ نے (لوگوں سے) پوچھا: ’’کیا بات اسی طرح ہے جیسے ذوالیدین کہتا ہے؟‘‘ انھوں نے کہا: جی ہاں۔ آپ (مصلے پر) تشریف لائے اور جو نماز باقی رہ گئی تھی، پڑھائی، پھر سلام پھیر اور اللہ اکبر کہا اور عام سجدے کی طرح یا اس سے کچھ لمبا سجدہ کیا، پھر سر اٹھایا اور اللہ اکبر کہا، پھر اللہ اکبر کہہ کر دوسرا سجدہ کیا، عام سجدے کی طرح یا اس سے کچھ لمبا، پھر سر اٹھایا اور اللہ اکبر کہا۔","f2":"(۱)’’میں بھول گیا‘‘ یہ بھولنے والے حضرت ابوہریرہ رضی اللہ عنہ ہیں یا ان کے شاگرد محمد بن سیرین رحمہ اللہ۔ (۲) ’’غصے میں‘‘ دراصل یہ آپ کی طبع لطیف پر نماز کے سہو کا اثر تھا جسے غصہ خیال کیا گیا۔ (۳) ’’ڈرے رہے‘‘ اللہ! اللہ! کیا کہنے آپ کے رعب کے کہ آپ کے بے تکلف اور قریب ترین دوست بلکہ یار غار بھی آپ سے ڈر رہے ہیں۔ دراصل وہ آپ کے مقام و مرتبہ سے کماحقہ آگاہ تھے۔ اس لیے دوستی اور بے تکلفی کے باوجود بھی آپ کے احترام کو ملحوظ رکھتے تھے۔ وہ جتنے زیادہ قریبی تھے اتنا ہی زیادہ آپ کے ادب و احترام کا خیال کرتے تھے۔ (۴) حضرت ذوالیدین اور دیگر صحابۂ کرام رضی اللہ عنہم کا رسول اکرم صلی اللہ علیہ وسلم سے باتیں کرنا جب کہ ابھی کچھ نماز باقی تھی، دلیل ہے کہ نماز کو مکمل سمجھ کر کلام یا کوئی اور عمل کرنا معاف ہے۔ نماز دہرانے کی ضرورت نہیں۔ آخر میں سجود سہو کافی ہیں۔ احناف ایسی صورت میں نماز نئے سرے سے پڑھنے کے قائل ہیں اور اس حدیث کو ابتدائی دور سے متعلق بتاتے ہیں جب کلام (نماز میں) منع تھا، حالانکہ اس حدیث کے راوی ابوہریرہ رضی اللہ عنہ ہیں جو اس نماز میں مقتدی بھی تھے۔ اور ان کا اسلام ۷ھ کا ہے جب کہ کلام کی حرمت تو بہت ابتدائی دور کی بات ہے۔ (۵) انسان ہونے کے لحاظ سے نبی صلی اللہ علیہ وسلم کو بھی نسیان لاحق ہوسکتا ہے جس طرح دوسرے انسانی عوارض، مثلاً: بیماری وغیرہ۔ اللہ تعالیٰ نے نہ بھولنے کی ضمانت قرآن مجید کے بارے میں دی ہے۔ ویسے وہاں بھی (الا ماشآء اللہ) کی صراحت ہے۔ (۶) یہ سجدے آپ نے سلام کے بعد ادا کیے ہیں۔ گویا سجدۂ سہو سلام کے بعد بھی ہوسکتا ہے اور پہلے بھی۔ جس کی تفصیل ابتدائیہ میں گزر چکی ہے۔ (۷) جب واقعہ ثقات کی ایک مجلس کا ہو اور عادتاً سبھی کا غافل ہونا محال ہو اور ان میں سے ایک ثقہ دوسروں کی نسبت کچھ زیادہ بیان کرے تو اس اکیلے کی بات قبول نہیں کرنی چاہیے جب تک کہ اس کی دیگر ہم نشین تصدیق نہ کر دیں۔ (۸) اس حدیث سے استصحاب پر عمل کا جواز ثابت ہوتا ہے۔ استصحاب کا مطلب ہے پہلے سے موجود حکم پر ثابت رہنا تاوقتیکہ کوئی نیا حکم آ جائے جو پہلے حکم کو تبدیل یا منسوخ کر دے۔ ذوالیدین نے اسی بنا پر سوال کیا، باوجود اس کے کہ نبیٔ اکرم صلی اللہ علیہ وسلم کا عمل ایک شرعی حیثیت رکھتا ہے اور اصل عدم سہو ہے اور نسخ بھی ممکن تھا۔ باقی صحابۂ کرام رضی اللہ عنہم جو خاموش رہے، وہ سابقہ حکم کے بارے میں متردد تھے کہ آیا وہ مسنوخ ہوگیا ہے یا کہ نہیں۔ اور جو صحابہ جلدی چلے گئے انہوں نے یقینی طور پر سمجھ لیا کہ پہلا حکم منسوخ ہوگیا ہے اور نماز کم ہوگئی ہے۔ اس سے احکام شرعیہ میں اجتہاد کا جواز ثابت ہوتا ہے۔ (۹) نماز میں کئی بار بھولنے کی وجہ سے متعدد دفعہ سجود سہو کرنے کی ضرورت نہیں، صرف ایک ہی دفعہ کافی ہیں۔ تفصیل کے لیے اسی کتاب کا ابتدائیہ ملاحظہ فرمائیے۔"}],[1225,"ابوہریرہ رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے دو ہی رکعت پر نماز ختم کر دی، تو آپ سے ذوالیدین نے عرض کیا: اللہ کے رسول! کیا نماز کم کر دی گئی ہے یا آپ بھول گئے ہیں؟، تو رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"کیا ذوالیدین سچ کہہ رہے ہیں؟\" لوگوں نے کہا: جی ہاں، تو رسول اللہ صلی اللہ علیہ وسلم کھڑے ہوئے، پھر آپ نے دو (رکعت مزید) پڑھائی، پھر سلام پھیرا، پھر آپ نے اللہ اکبر کہہ کر اپنے سجدوں کی طرح یا اس سے لمبا سجدہ کیا، پھر اپنا سر اٹھایا، پھر اپنے سجدوں کی طرح یا اس سے لمبا دوسرا سجدہ کیا، پھر اپنا سر اٹھایا۔","الألباني: صحيح",{"u2":"حضرت ابوہریرہ رضی اللہ عنہ سے روایت ہے (ایک دفعہ) رسول اللہ صلی اللہ علیہ وسلم نے دو رکعتو ں پر سلام پھیر دیا تو ذوالیدین نے آپ سے کہا: اے اللہ کے رسول! کیا نماز کم ہوگئی یا آپ بھول گئے؟ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’کیا ذوالیدین صحیح کہتا ہے؟‘‘ لوگوں نے کہا: جی ہاں۔ آپ صلی اللہ علیہ وسلم اٹھے اور دو رکعتیں مزید پڑھائیں، پھر سلام پھیرا۔ پھر اللہ أکبر کہہ کر اپنے عام سجدے کی طرح یا اس سے لمبا سجدہ کیا، پھر سر اٹھایا، پھر اپنے عام سجدے کی طرح یا اس سے کچھ لمبا سجدہ فرمایا، پھر سر اٹھایا۔"}],[1226,"ابوہریرہ رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے ہمیں نماز عصر پڑھائی، تو دو ہی رکعت میں سلام پھیر دیا، ذوالیدین کھڑے ہوئے، اور عرض کیا: اللہ کے رسول! کیا نماز کم کر دی گئی ہے یا آپ بھول گئے ہیں؟ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"(ان دونوں میں سے) کوئی بات بھی نہیں ہوئی ہے\"، ذوالیدین نے کہا: اللہ کے رسول! ان دونوں میں سے کوئی ایک بات ضرور ہوئی ہے، چنانچہ رسول اللہ صلی اللہ علیہ وسلم لوگوں کی طرف متوجہ ہوئے، اور آپ نے ان سے پوچھا: \"کیا ذوالیدین سچ کہہ رہے ہیں؟\" لوگوں نے کہا: جی ہاں، (سچ کہہ رہے ہیں) تو رسول اللہ صلی اللہ علیہ وسلم نے نماز میں سے جو رہ گیا تھا، اسے پورا، کیا پھر سلام پھیرنے کے بعد بیٹھے بیٹھے دو سجدے کیے۔","الألباني: صحيح",{"u2":"حضرت ابوہریرہ رضی اللہ عنہ بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے ہمیں عصر کی نماز پڑھائی اور دو رکعتیں پر سلام پھیر دیا۔ ذوالیدین اٹھ کھڑے ہوئے اور کہا: اے اللہ کے روسل! کیا نماز کم ہوگئی یا آپ بھول گئے؟ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’کچھ بھی نہیں ہوا۔‘‘ انھوں نے کہا: اے اللہ کے رسول! کچھ تو ہوا ہے۔ رسول اللہ صلی اللہ علیہ وسلم لوگوں کی طرف متوجہ ہوئے اور فرمایا: ’’کیا ذوالیدین نے درست کہا ہے؟‘‘ لوگوں نے کہا: جی ہاں۔ رسول اللہ صلی اللہ علیہ وسلم نے باقی ماندہ نماز مکمل کی، پھر سلام پھیرنے کے بعد بیٹھے بیٹھے دو سجدے کیے۔"}],[1227,"ابوہریرہ رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے نماز ظہر دو رکعت پڑھائی، پھر آپ نے سلام پھیر دیا، تو لوگ کہنے لگے کہ نماز کم کر دی گئی ہے، تو آپ کھڑے ہوئے، اور دو رکعت مزید پڑھائی، پھر سلام پھیرا پھر دو سجدے کئے۔","الألباني: صحيح",{"u2":"حضرت ابوہریرہ رضی اللہ عنہ سے مروی ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے ظہر کی نماز کی دو رکعتیں پڑھا کر سلام پھیر دیا۔ لوگوں نے کہا: کیا نماز کم ہوگئی؟ آپ اٹھے اور دو رکعتیں مزید پڑھیں، پھر سلامپ ھیرا، پھر دو سجدے کیے","f2":"پیچھے گزر چکا ہے کہ حضرت ابوہریرہ رضی اللہ عنہ بھول گئے تھے کہ کون سی نماز تھی، ظہر یا عصر؟ اس لیے کہہ ظہر کہا، کہیں عصر۔ مگر اس سے اصل مسئلے پر کوئی اثر نہیں پڑتا کیونکہ دونوں نمازیں ایک جیسی ہیں"}],[1228,"ابوہریرہ رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے ایک دن نماز پڑھائی تو آپ نے دو ہی رکعت پر سلام پھیر دیا، پھر جانے لگے تو آپ کے پاس ذوالشمالین ۱؎ آئے، اور کہنے لگے: اللہ کے رسول! کیا نماز کم کر دی گئی ہے یا آپ بھول گئے ہیں؟ تو آپ نے فرمایا: \"نہ تو نماز کم کی گئی ہے اور نہ ہی میں بھولا ہوں\"، اس پر انہوں نے عرض کیا: قسم ہے اس ذات کی جس نے آپ کو حق کے ساتھ بھیجا ہے، ان دونوں میں سے ضرور کوئی ایک بات ہوئی ہے، رسول اللہ صلی اللہ علیہ وسلم نے (لوگوں سے) پوچھا: \"کیا ذوالیدین سچ کہہ رہے ہیں؟\" لوگوں نے کہا: جی ہاں، تو آپ صلی اللہ علیہ وسلم نے لوگوں کو دو رکعتیں اور پڑھائیں۔\n§وضاحت\n۱؎: ذوالشمالین کا نام عمیر بن عبد عمرو اور کنیت ابو محمد ہے، یہ غزوہ بدر میں شہید کر دئیے گئے تھے، اور ذوالیدین کا نام خرباق اور کنیت ابو العریان ہے، ان کی وفات عمر رضی اللہ عنہ کے عہد خلافت میں ہوئی، سہو والے واقعہ میں ذوالشمالین کا ذکر راوی کا وہم ہے، صحیح ذوالیدین ہے، بعض لوگوں نے دونوں کو ایک ثابت کرنے کی کوشش کی ہے جو صحیح نہیں۔","الألباني: صحيح",{"u2":"حضرت ابوہریرہ رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے ایک دن نماز پڑھی اور دو رکعتوں پر سلام پھیر دیا اور اٹھ کر چلے گئے تو ذوالشمالین رضی اللہ عنہ آپ کو جاکر ملے اور عرض کیا: اے اللہ کے رسول! کیا نماز کم ہوگئی یا آپ بھول گئے؟ آپ نے فرمایا: ’’نماز کم ہوئی ہے نہ میں بھولا ہوں۔‘‘ اس نے کہا: کیوں نہیں (کچھ تو ہوا ہے۔) قسم اس ذات کی جس نے آپ کو حق کے ساتھ بھیجا ہے! رسول اللہ صلی اللہ علیہ وسلم نے (لوگوں سے مخاطب ہوکر) فرمایا: ’’کیا ذوالیدین درست کہہ رہا ہے؟‘‘ لوگوں نے کہا: ہاں۔ تو آپ نے لوگوں کو دو رکعتیں مزید پڑھائیں"}],[1229,"ابوہریرہ رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم (نماز میں) بھول گئے، تو آپ نے دو ہی رکعت پر سلام پھیر دیا، تو آپ سے ذوالشمالین نے عرض کیا: اللہ کے رسول! کیا نماز کم کر دی گئی ہے یا آپ بھول گئے ہیں؟ رسول اللہ صلی اللہ علیہ وسلم نے (لوگوں سے) پوچھا: \"کیا ذوالیدین سچ کہہ رہے ہیں؟\" لوگوں نے کہا: جی ہاں، (سچ کہہ رہے ہیں) تو رسول اللہ صلی اللہ علیہ وسلم کھڑے ہوئے، پھر آپ نے نماز پوری کی۔","الألباني: صحيح الإسناد",{"u2":"حضرت ابوہریرہ رضی اللہ عنہ سے مروی ہے، انھوں نے فرمایا کہ رسول اللہ صلی اللہ علیہ وسلم بھول گئے اور دو رکعتوںپر سلامپ ھیر دیا تو ذوالشمالین نے آپ سے کہا: اے اللہ کے رسول! کیا نماز کم ہوگئی یا آپ بھول گئے ہیں؟ رسول اللہ صلی اللہ علیہ وسلم نے لوگوں سے پوچھا: ’’کیا ذوالیدین درست کہہ رہا ہے؟‘‘ انھوں نے کہا: ہاں۔ تو رسول اللہ صلی اللہ علیہ وسلم کھڑے ہوئے اور نماز مکمل فرمائی","f2":"حافظ ابن حجر رحمہ اللہ فرماتے ہیں: روایات کے ظاہر سے یہی معلوم ہوتا ہے کہ ابوہریرہ رضی اللہ عنہ اس واقعہ میں حاضر تھے جبکہ امام طحاوی رحمہ اللہ نے اسے مجاز پر محمول کیا ہے۔ وہ فرماتے ہی کہ ابوہریرہ رضی اللہ عنہ کے اس قول ’’ہمیں نماز پڑھائی‘‘ کا مطلب ہے کہ مسلمانوں کو نماز پڑھائی۔ ان کی اس توجیہ کی وجہ امام زہری رحمہ اللہ کا یہ قول ہے کہ صاحب قصہ ذوالشمالین بدر کے دن شہید ہوگئے تھے، لہٰذا یہ واقعہ غزوئہ بدر سے پہلے کا ہے جبکہ ابوہریرہ رضی اللہ عنہ غزوۂ بدر کے پانچ سال بعد اسلام لائے۔ لیکن ائمہ حدیث کا اتفاق ہے کہ اس میں امام زہری رحمہ اللہ کو وہم ہوا ہے جیسا کہ ابن عبدالبر وغیرہ نے یہ قول نقل کیا ہے، وہ اسے ذوالشمالین کا قصہ قرار دیتے ہیں لیکن ذوالشمالین تو بدر کے دن شہید ہوگئے تھے، ان کا تعلق بنو خزاعہ سے تھا اور ان کا نام عمیر بن عبد عمرو تھا اور ذوالیدین بنو سلیم کے فرد تھے، ان کا نام خرباق تھا اور وہ نبیٔ اکرم صلی اللہ علیہ وسلم کے بعد لمبا عرصہ حیات رہے۔ صحیح مسلم میں ابو سلمہ کے واسطے سے ابوہریرہ رضی اللہ عنہ کی روایات کے الفاظ اس طرح ہیں: [فقام رجل من بني سلیم] ’’بنو سلیم کا ایک آدمی کھڑا ہوا۔‘‘ (صحیح مسلم، المساجد، حدیث: ۵۷۳) اور زہری کے واسطے سے ابوہریرہ رضی اللہ عنہ کی روایت کے الفاظ ہیں: [فقام ذوالشمالین] ’’ذوالشمالین کھڑا ہوا۔‘‘ حالانکہ وہ جنگ بدر میں شہید کر دیے گئے تھے۔ اسی وجہ سے انھوں نے اسے جنگ بدر سے پہلے کا واقعہ قرار دیا ہے۔\nبعض اہل علم کا خیال ہے کہ یہ دو واقعات ہیں: پہلا ذوالشمالین (عمیر بن عبد عمرو) اور دوسرا ذوالیدین (خرباق) کا۔ پہلے واقعے کو ابوہریرہ رضی اللہ عنہ نے مرسل بیان کیا ہے اور دوسرے میں وہ خود حاضر تھے۔ جمع و تطبیق کی خاطر اس کا بھی احتمال ہے۔ اور اس کے متعلق ایک قول یہ بھی ہے کہ اس اشتباہ کی وجہ یہ ہے کہ آپ کبھی ذوالشمالین کو ذوالیدین کہہ لیتے تھے اور کبھی ذوالیدین کو ذوالشمالین کہہ لیتے تھے۔ لیکن اس قول کی بنیاد کمزور ہے، نیز امام طحاوی رحمہ اللہ کا اسے مجاز پر محمول کرنا درست معلوم نہیں ہوتا کیونکہ صحیح مسلم میں ابوہریرہ رضی اللہ عنہ کے صریح الفاظ منقول ہیں: [بینما أنا اصلی مع النبی صلی اللہ علیہ وسلم …………] ’’ایک دفعہ میں نے نبیٔ اکرم صلی اللہ علیہ وسلم کے ساتھ نماز پڑھی………‘‘ (صحیح مسلم، المساجد، حدیث: ۵۷۳) اور کبار محدثین کا اس بات پر اتفاق ہے کہ ذوالشمالین رضی اللہ عنہ ذوالیدین رضی اللہ عنہ کے علاوہ دوسرے آدمی ہیں۔ اسی بات کی صراحت امام شافعی رحمہ اللہ نے ’’اختلاف الحدیث‘‘ میں کی ہے۔\nحافظ ابن حجر رحمہ اللہ فرماتے ہیں: میرے نزدیک راجح یہی ہے کہ یہ ایک ہی واقعہ ہے اگرچہ الفاظ کے مختلف ہونے کی وجہ سے امام ابن خزیمہ وغیرہ کا رجحان تعدد واقعات کی طرف ہے کیونکہ ابوہریرہ رضی اللہ عنہ کی روایت میں ہے کہ آپ نے دو رکعتوں کے بعد سلام پھیرا، پھر مسجد میں ایک لکڑی کی طرف کھڑے ہوگئے اور عمران بن حصین رضی اللہ عنہ کی روایت میں ہے کہ آپ نے تین رکعتوں کے بعد سلام پھیرا، پھر آپ گھر چلے گئے۔ مزید دیکھیے: (فتح الباري: ۳/۱۲۶، ۱۳۱، ۱۳۲، تحت حدیث: ۱۲۲۷، ۱۲۲۹)"}],[1230,"ابوہریرہ رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے (ہم کو) ظہر یا عصر پڑھائی، تو آپ نے دو ہی رکعت میں سلام پھیر دیا، اور اٹھ کر جانے لگے، تو آپ سے ذوالشمالین بن عمرو نے عرض کیا: اے اللہ کے رسول! کیا نماز کم کر دی گئی ہے یا آپ بھول گئے ہیں؟ نبی اکرم صلی اللہ علیہ وسلم نے (لوگوں سے) پوچھا:\"ذوالیدین کیا کہہ رہے ہیں؟\" لوگوں نے کہا: وہ سچ کہہ رہے ہیں، اللہ کے نبی! تو آپ نے ان دو رکعتوں کو جو باقی رہ گئی تھیں لوگوں کے ساتھ پورا کیا۔","الألباني: صحيح الإسناد",{"u2":"حضرت ابوہریرہ رضی اللہ عنہ سے منقول ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے ظہر یا عصر کی نماز پڑھائی اور دو رکعتوں کے بعد سلام پھیر دیا اور اٹھ کر چل دیے تو ذوالشمالین بن عمرو رضی اللہ عنہ نے آپ سے کہا: کیا نماز کم ہوگئی یا آپ بھول گئے؟ نبی صلی اللہ علیہ وسلم نے فرمایا ’’ذوالیدین کیا کہتا ہے؟‘‘ انھوں نے کہا: اے اللہ کے رسول! سچ کہتا ہے۔ آپ نے پھر وہ دو رکعتیں مکمل فرمائیں جو رہ گئی تھیں","f2":"اس روایت میں دو غلطیاں ہیں۔ ایک تو ذوالشمالین بن عبد عمرو ہونا چاہیے، دوسرے اس ذوالشمالین کا ذکر راوی کی غلطی اور شذوذ ہے۔ یہ تو بدر میں شہید ہونے والے ذوالشمالین ہیں جو اس واقعے سے بہت پہلے کے ہیں"}],[1231,"ابوبکر بن سلیمان بن ابی حثمہ سے روایت ہے کہ انہیں یہ بات پہنچی ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے دو رکعت پڑھائی، تو ذوالشمالین نے آپ سے عرض کیا، آگے حدیث اسی طرح ہے۔ ابن شہاب زہری کہتے ہیں کہ مجھے یہ خبر سعید بن مسیب نے ابوہریرہ کے واسطہ سے دی ہے، وہ (زہری) کہتے ہیں: نیز مجھے اس کی خبر ابوسلمہ بن عبدالرحمٰن اور ابوبکر بن عبدالرحمٰن بن حارث اور عبیدالرحمن بن عبداللہ نے بھی دی ہے۔\nأَخْبَرَنَا أَبُو دَاوُدَ، قَالَ: حَدَّثَنَا يَعْقُوبُ، قَالَ: حَدَّثَنَا أَبِي، عَنْ صَالِحٍ، عَنِ ابْنِ شِهَابٍ، أَنَّ أَبَا بَكْرِ بْنَ سُلَيْمَانَ بْنِ أَبِي حَثْمَةَ أَخْبَرَهُ أَنَّهُ بَلَغَهُ، أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: صَلَّى رَكْعَتَيْنِ، فَقَالَ لَهُ ذُو الشِّمَالَيْنِ نَحْوَهُ، قَالَ ابْنُ شِهَابٍ: أَخْبَرَنِي هَذَا الْخَبَرَ سَعِيدُ بْنُ الْمُسَيِّبِ، عَنْ أَبِي هُرَيْرَةَ، قَالَ: وَأَخْبَرَنِيهِ أَبُو سَلَمَةَ بْنُ عَبْدِ الرَّحْمَنِ، وَأَبُو بَكْرِ بْنُ عَبْدِ الرَّحْمَنِ بْنِ الْحَارِثِ، وَعُبَيْدُ اللَّهِ بْنُ عَبْدِ اللَّهِ.\nابوبکر بن سلیمان بن ابی حثمہ سے روایت ہے کہ انہیں یہ بات پہنچی ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے دو رکعت پڑھائی، تو ذوالشمالین نے آپ سے عرض کیا، آگے حدیث اسی طرح ہے۔ ابن شہاب زہری کہتے ہیں کہ مجھے یہ خبر سعید بن مسیب نے ابوہریرہ کے واسطہ سے دی ہے، وہ (زہری) کہتے ہیں: نیز مجھے اس کی خبر ابوسلمہ بن عبدالرحمٰن اور ابوبکر بن عبدالرحمٰن بن حارث اور عبیدالرحمن بن عبداللہ نے بھی دی ہے۔","الألباني: صحيح الإسناد — الألباني: صحيح الإسناد",{"u2":"حضرت ابوبکر بن سلیمان بن ابوحثمہ نے ابن شہاب کو بتایا کہ مجھے یہ خبر پہنچی ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے دو رکعتیں پڑھیں (اور سلام پھیر دیا) تو ذوالشمالین نے آپ سے گزارش کی۔ (باقی روایت حسب سابق ہے) حضرت ابن شہاب زہری بیان کرتے ہیں کہ مجھے یہ روایت حضرت سعید بن مسیب نے حضرت ابوہریرہ رضی اللہ عنہ سے بیان فرمائی، نیز مجھے یہ روایت حضرت ابوسلمہ بن عبدالرحمٰن، ابوبکر بن عبدالرحمٰن بن حارث اور عبیداللہ بن عبداللہ نے بھی بیان فرمائی۔","f2":"مندرجہ بالا واقعہ حضرت ابوہریرہ ری اللہ عنہ سے مرووی ہے جیسا کہ سابقہ احادیث سے صاف معلوم ہو رہا ہے۔ مگر اس روایت (۱۲۳۲) میں حضرت ابوبکر بن سلیمان نے حضرت ابوہریرہ رضی اللہ عنہ کا نام صراحتاً ذکر نہیں کیا بلکہ فرمایا: مجھے یہ واقعہ پہنچا ہے، واسطے کا ذکر نہیں کیا، جب کہ سابقہ حدیث میں انھوں نے واقعہ حضرت ابوہریرہ رضی اللہ عنہ کا نام لے کر بیان کیا ہے۔ اس سے روایت کی اسنادی حیثیت میں فرق نہیں پڑتا کیونکہ ایک جگہ ذکر نہ کرنا دوسری جگہ ذکر کرنے کے مخالف نہیں۔ امام نسائی رحمہ اللہ کا اس روایت کو ذکر کرنے کا مقصد امام زہری پر روایت کے متصل و مرسل ہونے کے اختلاف کو بیان کرنا ہے۔ واللہ أعلم۔"}],[1232,"سعید بن مسیب، ابوسلمہ، ابوبکر بن عبدالرحمٰن اور ابن ابی حثمہ چاروں ابوہریرہ رضی اللہ عنہ سے روایت کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے اس دن نہ تو سلام سے پہلے سجدہ (سہو) کیا، اور نہ ہی اس کے بعد۔","الألباني: شاذ",{"u2":"حضرت ابوہریرہ رضی اللہ عنہ سے روایت ہے، انھوں نے فرمایا: رسول اللہ صلی اللہ علیہ وسلم نے اس دن نہ سلام سے پہلے سجدے کیے نہ بعد میں۔"}],[1233,"عراک بن مالک ابوہریرہ رضی اللہ عنہ سے روایت کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے ذوالیدین والے دن سلام پھیرنے کے بعد دو سجدے کئے۔","الألباني: صحيح الإسناد",{"u2":"حضرت ابوہریرہ رضی اللہ عنہ سے روایت ہے، نبی صلی اللہ علیہ وسلم نے ذوالیدین والے واقعہ کے دن سلام کے بعد دو سجدے کیے"}],[1234,"محمد بن سیرین ابوہریرہ رضی اللہ عنہ سے، اور وہ رسول اللہ صلی اللہ علیہ وسلم اسی کے مثل روایت کرتے ہیں۔","الألباني: صحيح الإسناد",{"u2":"(امام نسائی رحمہ اللہ بیان کرتے ہیں:) ہمیں یہ روایت عمرو بن سواد بن اسود نے ابن وہب سے، انھوں نے عمرو بن حارث سے، انھوں نے قتادہ عن محمد ابن سیرین عن أبی ھریرۃ عن رسول اللہ صلی اللہ علیہ وسلم کی سند سے بھی اسی طرح بیان فرمائی۔","f2":"حدیث: ۱۲۳۳، جس میں سجدۂ سہو نہ کرنے کا ذکر ہے، ضعیف ہے۔ ائمہ حفاظ نے اسے امام زہری رحمہ اللہ کا اپنا کلام قرار دیا ہے۔ صحیح روایات میں سجدۂ سہو کرنے کا ذکر ہے۔ تفصیل کے لیے دیکھیے: (ذخیرۃ العقبی شرح سنن النسائي: ۱۵/۵-۷)"}],[1235,"ابن سیرین ابوہریرہ رضی اللہ عنہ سے روایت کرتے ہیں کہ نبی اکرم صلی اللہ علیہ وسلم نے بھول ہو جانے کی صورت میں سلام پھیرنے کے بعد سجدہ (سہو) کیا۔","الألباني: صحيح الإسناد",{"u2":"حضرت ابوہریرہ رضی اللہ عنہ سے مروی ہے کہ نبی صلی اللہ علیہ وسلم نے سہو کے (اس)واقعہ میںسلام کے بعد سجدے کیے"}],[1236,"عمران بن حصین رضی اللہ عنہما سے روایت ہے کہ نبی اکرم صلی اللہ علیہ وسلم نے ان لوگوں کو نماز پڑھائی، آپ کو سہو ہو گیا، تو آپ نے دو سجدے (سہو کے) کیے، پھر سلام پھیرا ۱؎۔\n§وضاحت\n۱؎: یہ سلام سجدہ سہو سے نکلنے کے لیے تھا، کیونکہ دیگر تمام روایات میں یہ صراحت ہے کہ آپ نے سلام پھیرا، پھر سجدہ سہو کیا :(پھر اس کے لیے سلام پھیرا ) نماز میں رکعات کی کمی بیشی کے سبب جو سجدہ سہو آپ نے کئے ہیں، وہ سب سلام کے بعد میں ہیں، جیسا کہ اگلی حدیث میں ہے، ہاں ان سجدوں کے بعد تشہد کے بارے میں تینوں احادیث ضعیف ہیں کما في التعلیقات السلفیۃ۔","الألباني: صحيح",{"u2":"حضرت عمران بن حصین رضی اللہ عنہ سے منقول ہے کہ نبی صلی اللہ علیہ وسلم نے انھیں نماز پڑھائی۔ آپ کو سہو ہو گیا۔ آپ نے دو سجدے کیے، پھر سلام پھیرا۔","f2":"اس حدیث میں سہو کی صراحت نہیں کہ کون سا تھا؟ تشہد والا یا دو رکعتوں والا؟ پہلی صورت میں دو سجدے سلام سے پہلے اور دوسری صورت میں سلام کے بعد کیے جائیں گے۔ روایات میں صراحت ہے، مبہم روایت کو صریح روایات پر محمول کیا جائے گا۔"}],[1237,"عمران بن حصین رضی اللہ عنہما کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے عصر کی تین رکعت پر سلام پھیر دیا، پھر آپ اپنے حجرے میں چلے گئے، تو آپ کی طرف اٹھ کر خرباق نامی ایک شخص گئے اور پوچھا: اللہ کے رسول! کیا نماز کم ہو گئی ہے؟ تو آپ غصہ کی حالت میں اپنی چادر گھسیٹتے ہوئے باہر تشریف لائے، اور پوچھا:\"کیا یہ سچ کہہ رہے ہیں؟\" لوگوں نے کہا: جی ہاں، تو آپ کھڑے ہوئے، اور (جو چھوٹ گئی تھی) اسے پڑھایا پھر سلام پھیرا، پھر اس رکعت کے (چھوٹ جانے کے سبب) دو سجدے کیے، پھر سلام پھیرا۔","الألباني: صحيح",{"u2":"حضرت عمران بن حصین رضی اللہ عنہ بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے (ایک دفعہ) عصر کی نماز میں تین رکعات پر سلام پھیر دیا۔ پھر اپنے گھر میں داخل ہوگئے۔ ایک آدمی آپ کی طرف بڑھا۔ اس کا نام خرباق تھا۔ اس نے کہا: اے اللہ کے رسول! نماز کم ہوگئی؟ آپ غصے میں اپنی اوپر والی چادر گھسیٹتے ہوئے باہر نکلے اور فرمایا: ’’کیا یہ درست کہتا ہے؟‘‘ لوگوں نے کہا: ہاں۔ آپ مصلے پر کھڑے ہوئے اور رہ جانے والی رکعت پڑھائی۔ پھر سلام پھیرا۔ پھر سہو کے دو سجدے کیے۔ پھر سلام پھیرا۔","f2":"مصنف رحمہ اللہ کا انداز ظاہر کر رہا ہے کہ وہ اس روایت کے واقعہ کو حضرت ابوہریرہ رضی اللہ عنہ والی روایت والا واقعہ ہی سمجھ رہے ہیں مگر دونوں کی تفصیلات میں کچھ اختلاف ہے۔ پہلی روایات میں دو رکعت پر سلام کا ذکر ہے۔ اس روایت میں تین رکعات پر سلام منقول ہے۔ پہلی روایت کے مطابق آپ مسجد ہی میں رہے، گھر نہیں گئے۔ اس روایت کے مطابق آپ گھر چلے گئے تھے۔ حافظ ابن حجر رحمہ اللہ کا رجحان اس طرف ہے کہ یہ ایک ہی واقعہ ہے جیسا کہ پیچھے ذکر ہوا۔ اور ابن خزیمہ رحمہ اللہ وغیرہ کے نزدیک یہ مختلف واقعات ہیں کیونکہ روایات کے ظاہر سے یہی معلوم ہوتا ہے۔ واللہ أعلم"}],[1238,"ابو سعید خدری رضی اللہ عنہ کہتے ہیں کہ نبی اکرم صلی اللہ علیہ وسلم نے فرمایا: \"جب تم میں سے کسی کو اس کی نماز میں شک ہو جائے تو وہ شک کو چھوڑ دے، اور یقین پر بنا کرے، جب اسے نماز کے پورا ہونے کا یقین ہو جائے تو وہ بیٹھے بیٹھے دو سجدے کر لے، (اب) اگر اس نے پانچ رکعتیں پڑھیں ہوں گی تو (یہ) دونوں سجدے اس کی نماز کو جفت بنا دیں گے، اور اگر اس نے چار رکعتیں پڑھی ہوں گی تو (یہ) دونوں سجدے شیطان کی ذلت و خواری کے موجب ہوں گے\"۔","الألباني: حسن صحيح",{"u2":"حضرت ابو سعید رضی اللہ عنہ سے مرووی ہے، نبی صلی اللہ علیہ وسلم نے فرمایا: ’’جب تم میں سے کسی کو اپنی نماز میں شک پڑ جائے تو وہ شک دور کرے اور یقین پر بنیاد رکھے (یعنی یقین کے مطابق نماز جاری رکھے۔) جب اسے نماز مکمل ہونے کا یقین ہو جائے تو بیٹھاب یٹھا دو سجدے کرے۔ اگر اس نے پانچ (رکعات) پڑھی ہوں گی تو یہ دو سجدے اس کی نماز کو جفت بنا دیں گے۔ اور اگر اس نے چار (رکعات) پڑھی ہوں گی تو یہ دو سجدے شیطان کو ذلیل کرنے کا سبب بنیں گے۔‘‘","f2":"(۱)’’شک دور کرے۔‘‘ اگر تین اور چار میں شک ہو تو تین سمجھے کیونکہ کم کا یقین اور زائد میں شک ہوتا ہے۔ (۲) ’’جفت بنا دیں گے۔‘‘ یعنی دو سجدے ایک رکعت کے قائم مقام ہو جائیں گے اور پانچویں رکعت سے مل کر دو نفل بن جائیں گے اور پہلی چار رکعتیں فرض ہوں گی، البتہ احناف کے نزدیک اس صورت میں ضروری ہے کہ ہر اس رکعت کے بعد بیٹھ کر تشہد پڑھے جس کا چوتھی ہونا ممکن ہو، یعنی آخری اور اس سے پہلی دونوں میں بیٹھے اور تشہد پڑھے ورنہ ساری نماز نفل ہو جائے گی۔ محدثین اور جمہور اہل علم کے نزدیک یہ ضروری نہیں کیونکہ یہ بھی ممکن ہے کہ وہ چوتھی کو تیسری سمجھ کر سیدھا اٹھ کھڑا ہوا ہو اور شک بعد میں پڑا ہو۔ اس صورت میں آخری سے پہلی میں بیٹھنے کا امکان ہی نہیں۔ اور اکثر ایسے ہی ہوتا ہے، لہٰذا احناف کا قول غیر ضروری تشدد ہے جس کی دلیل سنت سے نہیں ملتی، صرف قیاس کے زور سے اتنا سخت فتویٰ نہیں دینا چاہیے۔ (۳) ’’شیطان کی رسوائی اور ذلت‘‘ کیونکہ سہو شیطان کی کوششوں ہی سے ہوا تھا مگر نمازی نے مزید دو سجدے کیے۔ گویا شیطان کا وسوسہ نمازی کے لیے دو سجدوں کے اضافے کا ذریعہ بن گیا جب کہ سجدے کے انکار ہی سے شیطان زاندۂ درگاہ ہوا تھا، لہٰذا اس کا رسوا اور ذلیل ہونا لازمی امر ہے۔ شاید اسی نکتے کی بنا پر سہو کا تدارک سجدے سے مشروع کیا گیا ہے۔"}],[1239,"ابو سعید خدری رضی اللہ عنہ کہتے ہیں کہ نبی اکرم صلی اللہ علیہ وسلم نے فرمایا: \"جب تم میں سے کوئی (نماز پڑھتے وقت) نہ جان پائے کہ اس نے تین رکعتیں پڑھی ہیں یا چار، تو اسے ایک رکعت اور پڑھ لینی چاہیئے، پھر وہ ان سب کے بعد بیٹھے بیٹھے دو سجدے کر لے، (اب) اگر اس نے پانچ رکعتیں پڑھی ہوں گی، تو یہ دونوں سجدے اس کی نماز کو جفت بنا دیں گے، اور اگر اس نے چار رکعتیں پڑھی ہوں گی تو یہ دونوں سجدے شیطان کی ذلت و خواری کا اور اسے غیظ و غضب میں مبتلا کرنے کا سبب بنیں گے\"۔","الألباني: صحيح",{"u2":"حضرت ابو سعید خدری رضی اللہ عنہ سے روایت ہے، نبی صلی اللہ علیہ وسلم نے فرمایا: ’’جب تم میں سے کسی کو پتہ نہ چلے کہ اس نے تین (رکعات) پڑھی ہیں یا چار؟ تو وہ ایک رکعت مزید پڑھ کرب یٹھے بیٹھے دو سجدے کرے۔ اگر اس نے پانچ (رکعات) پڑھی ہوں گی تو یہ سجدے اس کی نماز کو جفت بنا دیں گے اور اگر چار پڑھی ہیں تو یہ شیطان کی ذلت کا سبب ہوں گے۔‘‘"}],[1240,"عبداللہ بن مسعود رضی اللہ عنہ کہتے ہیں کہ نبی اکرم صلی اللہ علیہ وسلم نے فرمایا: \"جب تم میں سے کسی کو اس کی نماز میں شک ہو جائے تو اسے چاہیئے کہ وہ (غور و فکر کے بعد) اس چیز کا قصد کرے جسے اس نے درست سمجھا ہو، اور اسی پر اتمام کرے، پھر اس کے بعد یعنی دو سجدے کرے\"، راوی کہتے ہیں: آپ کے بعض حروف کو میں اس طرح سمجھ نہیں سکا جیسے میں چاہ رہا تھا۔","الألباني: صحيح",{"u2":"حضرت عبداللہ بن مسعود رضی اللہ عنہ سے منقول ہے، نبی صلی اللہ علیہ وسلم نے فرمایا: ’’جب تم میں سے کسی کو اپنی نماز میں شک پڑ جائے تو اسے صحیح صورت حال جاننے کی کوشش کرنی چاہیے، پھر وہ اپنی نماز مکمل کرے، پھر دو سجدے کرے۔‘‘\n(امام نسائی رحمہ اللہ فرماتے ہیں:) میں اس روایت کے بعض الفاظ (اپنے استاد گرامی سے) اس طرح نہیں سمجھ سکا جس طرح میری خواہش تھی","f2":"(۱)گویا بعض الفاظ صحیح طرح سمجھ میں نہیں آئے، اسی لیے امام صاحب نے حدیث: ۱۲۴۲ میں یہی روایت ایک اور استاد کے واسطے سے بیان کی تاکہ وہ شک دور ہو جائے اور روایت مستند بن جائے۔ (۲) پچھلی روایت میں مطلقاً ’’اقل‘‘ پر اعتماد کرنے کا حکم تھا مگر اس روایت میں مزید صراحت ہے کہ وہ سوچے کون سی بات صحیح ہے؟ اگر کسی ایک بات پر یقین ہو جائے تو درست ورنہ اقل (کم) پر اعتماد کیا جائے گا کیونکہ وہ قطعاً یقینی ہے۔"}],[1241,"عبداللہ بن مسعود رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"جب تم میں سے کسی کو اس کی نماز میں شک ہو جائے تو اسے چاہیئے کہ وہ غور و فکر کرے، (اور ظن غالب کو تلاش کرے) اور نماز سے فارغ ہو جانے کے بعد دو سجدے کر لے\" ۱؎۔\n§وضاحت\n۱؎: سجدہ سہو کے بارے میں اہل علم میں اختلاف ہے کہ آدمی اسے سلام سے پہلے کرے یا سلام کے بعد، بعض لوگوں کی رائے ہے کہ اسے سلام کے بعد کرے، یہ قول سفیان ثوری اور اہل کوفہ کا ہے، اور بعض لوگوں نے کہا ہے کہ اسے سلام سے پہلے کرے، یہی قول اکثر فقہائے مدینہ مثلاً یحیی بن سعید، ربیعہ اور شافعی وغیرہ کا ہے، اور بعض لوگ کہتے ہیں کہ جب نماز میں زیادتی ہوئی ہو تو سلام کے بعد کرے، اور جب کمی رہ گئی ہو تو سلام سے پہلے کرے، یہ قول مالک بن انس کا ہے، اور امام احمد کہتے ہیں کہ جس صورت میں جس طرح پر سجدہ سہو نبی اکرم صلی اللہ علیہ وسلم سے مروی ہے اس صورت میں اسی طرح سجدہ سہو کرنا چاہیئے، وہ کہتے ہیں کہ جب دو رکعت کے بعد کھڑے ہو جائے تو ابن بحینہ کی حدیث کے مطابق سلام سے پہلے سجدہ کرے، اور جب ظہر کی نماز پانچ رکعت پڑھ لے تو وہ سجدہ سہو سلام کے بعد کرے، اور اگر ظہر و عصر کی نماز میں دو ہی رکعت میں سلام پھیر دے تو ایسی صورت میں سلام کے بعد سجدہ سہو کرے، اس طرح جس صورت میں جیسے رسول اللہ صلی اللہ علیہ وسلم کا فعل موجود ہے اس پر اسی طرح عمل کرے، اور جس صورت میں رسول اللہ صلی اللہ علیہ وسلم سے کوئی فعل مروی نہ ہو تو اس میں سجدہ سہو سلام سے پہلے کرے۔","الألباني: صحيح",{"u2":"حضرت عبداللہ بن مسعود رضی اللہ عنہ سے روایت ہے، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’جب تم میں سے کسی کو اپنی نماز میں شک پڑ جائے تو وہ صحیح بات جاننے کی کوشش کرے اور فارغ ہونے کے بعد دو سجدے کرے۔‘‘"}],[1242,"عبداللہ بن مسعود رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے نماز پڑھائی تو آپ نے کچھ بڑھایا گھٹا دیا، جب آپ نے سلام پھیرا تو ہم نے پوچھا: اللہ کے رسول! کیا نماز میں کوئی نئی بات ہوئی ہے؟ آپ نے فرمایا: \"اگر نماز کے سلسلہ میں کوئی نیا حکم آیا ہوتا تو میں تمہیں اسے بتاتا، البتہ میں بھی انسان ہی ہوں، جس طرح تم لوگ بھول جاتے ہو، مجھ سے بھی بھول ہو سکتی ہے، لہٰذا تم میں سے کسی کو نماز میں کچھ شک ہو جائے تو اسے چاہیئے کہ وہ اس چیز کو دیکھے جو صحت و درستی کے زیادہ لائق ہے، اور اسی پر اتمام کرے، پھر سلام پھیرے، اور دو سجدے کر لے\"۔","الألباني: صحيح",{"u2":"حضرت عبداللہ بن مسعود رضی اللہ عنہ سے مروی ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے ایک نماز پڑھی جس میں آپ سے زیادتی یا کمی ہوگئی۔ جب آپ نے سلام پھیرا تو آپ سے پوچھا گیا: کیا نماز کے بارے میں کوئی نیا حکم آ گیا ہے؟ آپ نے فرمایا: ’’اگر نماز کے بارے میں کوئی نیا حکم آیا ہوتا تو میں تمھیں بتا دیتا۔ لیکن میں بھی ایک انسان ہوں، جس طرح تم بھول جاتے ہو، میں بھی بھول جاتا ہوں۔ جس آدمی کو بھی اپنی نماز میں شک پڑ جائے تو وہ دیکھے کون سی بات صحت کے زیادہ قریب ہے۔ پھر اس کے مطابق اپنی نماز مکمل کرے۔ پھر سلام پھیرے اور (سہو کے) دو سجدے کرے","f2":"(۱)آگے آ رہا ہے کہ نماز میں آپ سے اضافہ ہوگیا تھا، یعنی ظہر کی نماز پانچ رکعت پڑھی گئی تھی۔ (۲) اگر سجدۂ سہو سلام کے بعد ہو تو وہ سلام دونوں طرف ہونا چاہیے، نہ کہ ایک طرف جیسا کہ احناف کا عمومی رواج ہے کیونکہ مطلق سلام کا لفظ دو سلام پر ہی محمول ہوگا جو کہ نماز میں مشروع ہو معہود ہیں۔ محققین احناف اسی کے قائل ہیں۔ (۳) جب لوگ کوئی نئی چیز دیکھیں تو اس کے متعلق پوچھنے میں کوئی حرج نہیں اور امام یا حاکم کو بھی اس کا برا نہیں منانا چاہیے بلکہ خوش دلی سے اس کا جواب دینا چاہیے"}],[1243,"عبداللہ بن مسعود رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے نماز پڑھائی، آپ نے اس میں کچھ بڑھا، یا گھٹا دیا، تو جب آپ نے سلام پھیرا تو ہم نے پوچھا: اللہ کے نبی! کیا نماز کے متعلق کوئی نیا حکم آیا ہے؟ تو آپ نے فرمایا: \"وہ کیا ہے؟\" تو ہم نے آپ سے اس چیز کا ذکر کیا جو آپ صلی اللہ علیہ وسلم نے کیا تھا، تو آپ نے اپنا پاؤں موڑا، قبلہ رخ ہوئے، اور سہو کے دو سجدے کیے، پھر ہماری طرف متوجہ ہو کر فرمایا: \"اگر نماز کے متعلق کوئی نئی چیز ہوتی تو میں تمہیں اس کی خبر دیتا\"، پھر فرمایا: \"میں انسان ہی تو ہوں، جیسے تم بھولتے ہو، میں بھی بھولتا ہوں، لہٰذا تم میں سے کسی کو نماز میں کوئی شک ہو جائے تو غور و فکر کرے، اور اس چیز کا قصد کرے جس کو وہ درست سمجھ رہا ہو، پھر وہ سلام پھیرے، پھر سہو کے دو سجدے کرے\"۔","الألباني: صحيح",{"u2":"حضرت عبداللہ بن مسعود رضی اللہ عنہ سے منقول ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے کوئی نماز پڑھی۔ اس میں آپ سے زیادتی یا کمی ہوگئی۔ جب آپ نے سلام پھیرا تو ہم نے کہا: اے اللہ کے نبی! کیا نماز میں کوئی نیا حکم آگیا ہے؟ آپ نے فرمایا: ’’کیا ہوا؟‘‘ ہم نے آپ سے پوری بات ذکر کی۔ آپ نے اپنا پاؤں موڑا اور قبلے کی طرف منہ کیا اور سہو کے دو سجدے کیے۔ پھر ہماری طرف متوجہ ہوئے اور فرمایا: ’’اگر نماز کے بارے میں کوئی نیا حکم آ جاتا تو میں تمھیں بتلا دیتا۔‘‘ پھر فرمایا: ’’میں بھی ایک انسان ہوں، بھول سکتا ہوں جس طرح تم بھول جاتے ہو، لہٰذا جس آدمی کو اپنی نماز میں شک پڑ جائے، وہ صحیح صورت حال جاننے کی کوشش کرے۔ پھر سلام پھیر دے۔ پھر سہو کے دو سجدے کرے۔‘‘","f2":"(۱)آپ سے دراصل نماز ظہر میں اضافہ ہوگیا تھا۔ اضافے کی صورت میں سجود سہو کی مذکورہ صورت پر عمل ہوگا۔ (۲) جب نماز میں شک پڑ جائے تو آدمی کو حقیقت حال معلوم کرنے کے لیے غور و فکر کرنا چاہیے، اس سے نماز خراب نہیں ہوتی۔ (۳) رسول اللہ صلی اللہ علیہ وسلم نے اللہ کے پیغامات کو مکمل طور پر پہنچا دیا ہے۔ آپ پر جب بھی کوئی نئی وحی آتی تو آپ فوراً صحابۂ کرام رضی اللہ عنہم کو اس سے آگاہ فرما دیتے تھے، لہٰذا جو چیز اس وقت دین تھی، آج بھی وہی دین ہے، اس میں کمی بیشی کی گنجائش نہیں"}],[1244,"عبداللہ بن مسعود رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے ظہر کی نماز پڑھائی، پھر آپ ان کی طرف متوجہ ہوئے، تو لوگوں نے عرض کیا: کیا نماز کے متعلق کوئی نئی چیز واقع ہوئی ہے؟ آپ صلی اللہ علیہ وسلم نے پوچھا: \"وہ کیا؟\" تو لوگوں نے آپ کو جو آپ نے کیا تھا بتایا، تو آپ صلی اللہ علیہ وسلم نے (اسی حالت میں) اپنا پاؤں موڑا، اور آپ قبلہ رخ ہوئے، اور دو سجدے کیے، پھر سلام پھیرا، پھر آپ (دوبارہ) لوگوں کی طرف متوجہ ہوئے، اور فرمایا: \"میں انسان ہی تو ہوں اسی طرح بھولتا ہوں جیسے تم بھولتے ہو، تو جب میں بھول جاؤں تو تم مجھے یاد دلا دو\"، آپ صلی اللہ علیہ وسلم نے فرمایا: \"اگر نماز میں کوئی چیز ہوئی ہوتی تو میں تمہیں اسے بتاتا\"، نیز آپ نے فرمایا: \"جب تم میں سے کسی کو اس کی نماز میں وہم ہو جائے تو اسے چاہیئے کہ وہ سوچے، اور اس چیز کا قصد کرے جو درستی سے زیادہ قریب ہو، پھر اسی پر اتمام کرے، پھر دو سجدے کرے\"۔","الألباني: صحيح",{"u2":"حضرت عبداللہ بن مسعود رضی اللہ عنہ سے مروی ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے ظہر کی نماز پڑھائی (آپ سے ایک رکعت زائد پڑھی گئی) پھر آپ نے اپنا چہرہ لوگوں کی طرف فرمایا تو لوگوں نے کہا: کیا نماز میں کوئی تبدیلی آگئی ہے؟ آپ نے فرمایا: ’’کیا ہوا؟‘‘ تو انھوں نے آپ کو پوری بات بتائی۔ آپ نے اپنا پاؤں موڑا اور قبلے کی طرف منہ کیا اور دو سجدے کیے، پھر سلام پھیرا، پھر ان کی طرف متوجہ ہوکر فرمایا: ’’میں بھی ایک انسان ہوں۔ بھول جاتا ہووں جیسے تم بھول جاتے ہو۔ جب میں بھول جاؤں تو مجھے یاد دلا دیا کرو۔ اگر نماز کے بارے میں کوئی تبدیلی ہوئی ہوتی تو میں تمھیں بتا دیتا۔‘‘ نیز فرمایا ’’جب تم میں سے کسی کو نماز میں وہم پڑ جائے تو وہ بہت زیادہ درست بات معلوم کرے اور اس کے حساب سے نماز مکمل کرے، پھر دو سجدے کرے۔‘‘","f2":"’’مجھے یاد دلا دیا کرو۔‘‘ معلوم ہوتا ہے کہ جب آپ پانچویں رکعت کے لیے (بھول کر) اٹھے تو صحابۂ اکرام رضی اللہ عنہم نے آپ کو متنبہ نہیں کیا۔ انھوں نے خیال کیا کہ شاید نماز میں اضافے کا حکم آگیا ہے، حالانکہ ایسی بات ہوتی تو رسول اللہ صلی اللہ علیہ وسلم پہلے مطلع فرما دیتے"}],[1245,"عبداللہ بن مسعود رضی اللہ عنہ کہتے ہیں جسے اپنی نماز میں وہم ہو جائے تو اسے صحیح اور صواب جاننے کی کوشش کرنی چاہیئے، پھر فارغ ہونے کے بعد بیٹھے بیٹھے دو سجدہ کرے۔","الألباني: صحيح",{"u2":"حضرت عبداللہ بن مسعود رضی اللہ عنہ بیان کرتے ہیں کہ جسے نماز میں وہم ہو جائے تو وہ درست بات تلاش کرے، پھر نماز مکمل کرنے کے بعد بیٹھے بیٹھے دو سجدے کرے"}],[1246,"عبداللہ بن مسعود رضی اللہ عنہ کہتے ہیں کہ جسے کچھ شک یا وہم ہو جائے تو اسے صحیح اور صواب جاننے کی کوشش کرنی چاہیئے، پھر دو سجدے کرے۔","الألباني: صحيح",{"u2":"حضرت عبداللہ بن مسعود رضی اللہ عنہ سے منقول ہے کہ جسے (نماز میں) شک یا وہم پڑ جائے تو وہ درست بات تلاش کرے، پھر دو سجدے کرے"}],[1247,"ابراہیم نخعی کہتے ہیں کہ لوگ کہتے تھے کہ جب کسی آدمی کو وہم ہو جائے تو اسے صحیح و صواب جاننے کی کوشش کرنی چاہیئے، پھر دو سجدے کرے۔","الألباني: صحيح الإسناد موقوف",{"u2":"حضرت ابراہیم نخعی رحمہ اللہ بیان کرتے ہیں کہ لوگ (صحابۂ کرام) کہتے تھے: جب نمازی کو وہم ہو جائے تو وہ درست بات تلاش کرے، پھر دو سجدے کرے"}],[1248,"عبداللہ بن جعفر رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"جس شخص کو اس کی نماز میں شک ہو جائے، تو وہ سلام پھیرنے کے بعد دو سجدے کرے\"۔","الألباني: ضعيف",{"u2":"حضرت عبداللہ بن جعفر رضی اللہ عنہ سے روایت ہے، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’جس شخص کو نماز میں شک ہو تو وہ سلام پھیرنے کے بعد دو سجدے کرے۔‘‘"}],[1249,"عبداللہ بن جعفر رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"جو اپنی نماز میں شک کرے تو وہ سلام پھیرنے کے بعد دو سجدے کرے\"۔","الألباني: ضعيف",{"u2":"حضرت عبداللہ بن جعفر رضی اللہ عنہ سے منقول ہے، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’جس آدمی کو نماز میں شک پڑ جائے تو وہ سلام پھیرنے کے بعد دو سجدے کرے۔‘‘"}],[1250,"عبداللہ بن جعفر رضی اللہ عنہ سے روایت ہے کہ نبی اکرم صلی اللہ علیہ وسلم نے فرمایا: \"جو اپنی نماز میں شک کرے تو وہ سلام پھیرنے کے بعد دو سجدے کرے\"۔","الألباني: ضعيف",{"u2":"حضرت عبداللہ بن جعفر رضی اللہ عنہ سے مروی ہے، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’جو شخص اپنی نماز میں شک کرے تو وہ سلام پھیرنے کے بعد دو سجدے کرے۔‘‘"}],[1251,"عبداللہ بن جعفر رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"جو اپنی نماز میں شک کرے تو وہ دو سجدے کرے\"، حجاج کی روایت میں ہے: \"سلام پھیرنے کے بعد دو سجدے کرے\"، اور روح کی روایت میں ہے: \"بیٹھے بیٹھے (دو سجدے کرے)\"۔","الألباني: ضعيف",{"u2":"حضرت عبداللہ بن جعفر رضی اللہ عنہ سے روایت ہے، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’جس شخص کو اپنی نماز میں شک ہو جائے تو وہ سلام کے بعد بیٹھے بیٹھے دو سجدے کرے۔‘‘","f2":"حدیث: ۱۲۴۶ سے ۱۲۵۲ تک روایات مختصر ہیں۔ ان کا صحیح مفہوم سمجھنے کے لیے ان سے اوپر والی تفصیلی روایات سے مدد لی جائے، یعنی شک کی صورت میں صحیح بات جاننے یا ’’اقل‘‘ پر اعتماد کرنے کے بعد نماز مکمل کرے۔ پھر سلام پھیرنے کے بعد سہو کے دو سجدے کرے اور سلام پھیر دے۔ دیکھیے: (صحیح مسلم، المساجد، حدیث: ۵۷۲) نماز زیادہ پڑھی جانے کی صورت میں صرف دو سجدے کافی ہیں"}],[1252,"ابوہریرہ رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"جب تم میں کوئی کھڑا ہو کر نماز پڑھتا ہے تو شیطان اس کے پاس آتا ہے، اور اس پر اس کی نماز کو گڈمڈ کر دیتا ہے، یہاں تک کہ وہ نہیں جان پاتا کہ اس نے کتنی نماز پڑھی ہے، لہٰذا جب تم میں سے کوئی ایسا محسوس کرے تو بیٹھے بیٹھے دو سجدے کرے\"۔","الألباني: صحيح",{"u2":"حضرت ابوہریرہ رضی اللہ عنہ سے روایت ہے، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’جب تم میں سے کوئی نماز پڑھنے کھڑا ہوتا ہے تو شیطان آکر اس پر اس کی نماز مشتبہ کر دیتا ہے حتی کہ اسے پتہ نہیں چلتا کہ کتنی نماز پڑھی ہے؟ جب تم میں سے کوئی شخص یہ صورت حال پائے تو (یقین کے مطابق نماز مکمل کرکے سلام پھیرے اور) بیٹھے بیٹھے دو سجدے کرے۔‘‘"}],[1253,"ابوہریرہ رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"جب نماز کے لیے اذان دی جاتی ہے تو شیطان ہوا خارج کرتے ہوئے پیٹھ پھیر کر بھاگتا ہے، پھر جب اقامت کہہ دی جاتی ہے تو وہ واپس لوٹ آتا ہے یہاں تک کہ آدمی کے دل میں گھس کر وسوسے ڈالتا ہے، یہاں تک کہ وہ جان نہیں پاتا کہ اس نے کتنی نماز پڑھی، لہٰذا جب تم میں سے کوئی اس قسم کی صورت حال دیکھے تو وہ دو سجدے کرے\"۔","الألباني: صحيح",{"u2":"حضرت ابوہریرہ رضی اللہ عنہ سے مروی ہے، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’جب نماز کے لیے اذان کہی جاتی ہے تو شیطان گوز مارتا ہوا بھاگ جاتا ہے۔ جب اقامت پوری ہو جاتی ہے تو واپس آ جاتا ہے حتی کہ نمازی اور اس کے دل کے درمیان حائل ہو جاتا ہے یہاں تک کہ اسے پتہ نہیں چلتا کہ میں نے کتنی نماز پڑھی ہے؟ جب تم میں سے کوئی شخص یہ صورت حال دیکھے (محسوس کرے) تو (نماز یقین کے مطابق مکمل کرنے کے بعد) دو سجدے کرے۔‘‘","f2":"(۱)شیطان کا گوز مارتا اذان کا اثر بھی ہوسکتا ہے (جیسے گدھے پر زیادہ بوجھ لدا ہو تو وہ گوز مارتا ہے) یا اس لیے کہ اذان نہ سن سکے (گوز کی آواز کی وجہ سے) یا یہ کنایہ ہے کہ اذان شیطان کے لیے بہت پریشان کن ہے۔ (۲) دیگر روایات میں اذان کے بعد واپسی اور پھر اقامت کے موقع پر بھاگنے کا بھی ذکر ہے۔ دیکھیے: (صحیح البخاری، الأذان، حدیث: ۶۰۸، و صحیح مسلم، الصلاۃ، حدیث: ۲۸۷) یہ روایت مختصر ہے۔"}],[1254,"عبداللہ بن مسعود رضی اللہ عنہ کہتے ہیں کہ نبی اکرم صلی اللہ علیہ وسلم نے ظہر کی نماز پانچ (رکعت) پڑھی، تو آپ سے عرض کیا گیا: کیا نماز میں زیادتی کر دی گئی ہے؟ تو آپ نے پوچھا: \"وہ کیا؟\" لوگوں نے کہا: آپ نے پانچ (رکعت) پڑھی ہے، تو آپ نے اپنا پاؤں موڑا اور دو سجدے کیے۔","الألباني: صحيح",{"u2":"حضرت عبداللہ بن مسعود رضی اللہ عنہ بیان کرتے ہیں کہ نبی صلی اللہ علیہ وسلم نے ظہر کی پانچ رکعتیں پڑھا دیں۔ آپ سے عرض کیا گیا: کیا نماز میں اضافہ ہوگیا ہے؟ آپ نے فرمایا: ’’کیا ہوا؟‘‘ لوگوں نے عرض کیا: آپ نے پانچ رکعتیں پڑھی ہیں۔ آپ نے اپنا پاؤں موڑا (یعنی قبلہ رخ ہوئے) اور دو سجدے کیے"}],[1255,"عبداللہ بن مسعود رضی اللہ عنہ کہتے ہیں کہ نبی اکرم صلی اللہ علیہ وسلم نے لوگوں کو ظہر کی نماز پانچ رکعت پڑھائی، تو لوگوں نے عرض کیا: آپ نے پانچ (رکعت)پڑھائی ہے، تو آپ نے سلام پھیرنے کے بعد بیٹھے بیٹھے دو سجدے کیے۔","الألباني: صحيح",{"u2":"حضرت عبداللہ بن مسعود رضی اللہ عنہ سے مروی ہے کہ نبی صلی اللہ علیہ وسلم نے ہمیں ظہر کی نماز پانچ رکعتیں پڑھا دیں۔ لوگوں نے کہا: آپ نے پانچ پڑھی ہیں تو آپ نے سلام پھیرنے کے بعد بیٹھے بیٹھے دو سجدے کیے"}],[1256,"ابراہیم بن سوید کہتے ہیں کہ علقمہ نے پانچ (رکعت) نماز پڑھی، تو ان سے (اس زیادتی کے بارے میں) کہا گیا، تو انہوں نے کہا: میں نے (ایسا) نہیں کیا ہے، تو میں نے اپنے سر کے اشارہ سے کہا: کیوں نہیں؟ آپ نے ضرور کیا ہے، انہوں نے کہا: اور تم اس کی گواہی دیتے ہو اے اعور! تو میں نے کہا: ہاں (دیتا ہوں) تو انہوں نے دو سجدے کیے، پھر انہوں نے عبداللہ بن مسعود رضی اللہ عنہ سے روایت کی کہ نبی اکرم صلی اللہ علیہ وسلم نے پانچ (رکعتیں) پڑھیں، تو لوگ ایک دوسرے سے کھسر پھسر کرنے لگے، ان لوگوں نے آپ صلی اللہ علیہ وسلم سے پوچھا: کیا نماز میں اضافہ کر دیا گیا ہے؟ آپ نے فرمایا: \"نہیں\"، لوگوں نے آپ کو بتایا (کہ آپ نے پانچ رکعتیں پڑھی ہیں)، تو آپ صلی اللہ علیہ وسلم نے اپنا پاؤں موڑا، اور دو سجدے کیے، پھر فرمایا: \"میں انسان ہی ہوں، میں (بھی) بھول سکتا ہوں جس طرح تم بھولتے ہو\"۔","الألباني: صحيح",{"u2":"ابراہیم بن سوید سے روایت ہے کہ حضرت علقمہ نے ایک دفعہ پانچ رکعتیں پڑھا دیں۔ انھیں بتایا گیا تو وہ کہنے لگے: میں نے تو ایسا نہیں کیا۔ میں نے سر کے اشارے سے کہا: کیوں نہیں؟ (آپ نے کیا ہے) وہ کہنے لگے: اے اعور! تو بھی ایسے ہی کہتا ہے؟ میں نے کہا: ہاں۔ پھر انھوں نے دو سجدے کیے۔ پھر انھوں نے حضرت عبداللہ بن مسعود رضی اللہ عنہ کے واسطے سے حدیث بیان کی کہ نبی صلی اللہ علیہ وسلم نے بھی (ایک دفعہ) پانچ رکعات پڑھا دی تھیں۔ لوگ ایک دوسرے سے کانا پھوسی کرنے لگے۔ انھوں نے آپ سے کہا: کیا نماز میں اضافہ ہوگیا ہے؟ آپ نے فرمایا: ’’نہیں۔‘‘ انھوں نے آپ کو بتایا تو آپ نے اپنے پاؤں سیدھے (قبلہ رخ) کیے اور دو سجدے کیے، پھر فرمایا: ’’میں بھی ایک انسان ہوں۔ جس طرح تم بھولتے ہو، میں بھی بھول جاتا ہوں۔‘‘"}],[1257,"مالک بن مغول کہتے ہیں کہ میں نے (عامری شراحیل) شعبی کو کہتے ہوئے سنا کہ علقمہ بن قیس سے نماز میں سہو ہو گیا، تو لوگوں نے آپ سے میں گفتگو کرنے کے بعد ان سے اس کا ذکر کیا، تو انہوں نے پوچھا: کیا ایسا ہی ہے، اے اعور! (ابراہیم بن سوید نے) کہا: ہاں، تو انہوں نے اپنا حبوہ ۱؎ کھولا، پھر سہو کے دو سجدے کیے، اور کہنے لگے: اسی طرح رسول اللہ صلی اللہ علیہ وسلم نے کیا ہے، (مالک بن مغول) نے کہا: اور میں نے حکم (ابن عتیبہ) کو کہتے ہوئے سنا کہ علقمہ نے پانچ (رکعتیں) پڑھی تھیں۔\n§وضاحت\n۱؎: حبوہ: ایک طرح کی بیٹھک ہے جس میں سرین کو زمین پر ٹکا کر دونوں رانوں کو دونوں ہاتھ سے باندھ لیا جاتا ہے۔","الألباني: صحيح",{"u2":"حضرت شعبی بیان کرتے ہیں کہ حضرت علقمہ بن قیس اپنی نماز میں بھول گئے۔ ان کے کلام وغیرہ کرنے کے بعد لوگوں نے ان سے ذکر کیا تو کہنے لگے: اے اعور! کیا ایسے ہی ہوا ہے؟‘‘ اس نے کہا: جی ہاں۔ انھوں نے اپنی گوٹھ کھولی، پھر سہو کے دو سجدے کیے اور کہنے لگے: رسول اللہ صلی اللہ علیہ وسلم نے ایسے کیا تھا۔ (راویٔ حدیث) مالک بن مغول نے کہا: میں نے حضرت حکم بن عتبیہ فرماتے سنا کہ علقمہ نے (سہواً) پانچ رکعتیں پڑھ لی تھیں۔","f2":"اصل روایت تو مالک بن مغول نے حضرت شعی سے بیان کی ہے جس میں صرف سہو کا ذکر ہے۔ یہ وضاحت نہیں کہ کیا سہو ہوا تھا؟ یہ وضاحت حضرت حکم کی روایت میں ہے کہ وہ سہواً پانچ رکعات پڑھ چکے تھے۔ شعی اور حکم دونوں حرت علقمہ کے شاگرد ہیں۔"}],[1258,"ابراہیم سے روایت ہے کہ علقمہ نے پانچ (رکعتیں) پڑھیں، جب انہوں نے سلام پھیرا، تو ابراہیم بن سوید نے کہا: ابو شبل (علقمہ)! آپ نے پانچ رکعتیں پڑھی ہیں، انہوں نے کہا: کیا ایسا ہوا ہے اے اعور؟ (انہوں نے کہا: ہاں) تو علقمہ نے سہو کے دو سجدے کیے، پھر کہا: اسی طرح رسول اللہ صلی اللہ علیہ وسلم نے کیا ہے۔","الألباني: صحيح",{"u2":"ابراہیم بن سوید سے مروی ہے کہ حضرت علقمہ نے پانچ رکعتیں پڑھ لیں۔ میں نے کہا: اے ابوشبل! (علقمہ کی کنیت ہے) آپ نے پانچ رکعتیں پڑھی ہیں۔ کہنے لگے: اے اعور! کیا حقیقتاً ایسے ہی ہے؟ پھر انھوں نے سہو کے دو سجدے کیے۔ پھر کہنے لگے: اللہ کے رسول صلی اللہ علیہ وسلم نے ایسے ہی کیا تھا۔"}],[1259,"عبداللہ بن مسعود رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے شام کی دونوں نمازوں (یعنی ظہر اور عصر) میں سے کوئی ایک نماز پانچ رکعت پڑھائی، تو آپ سے کہا گیا: کیا نماز میں اضافہ کر دیا گیا ہے؟ آپ نے پوچھا: \"وہ کیا؟\" لوگوں نے عرض کیا: آپ نے پانچ رکعتیں پڑھی ہیں تو آپ صلی اللہ علیہ وسلم نے فرمایا: \"میں انسان ہی تو ہوں، میں بھی بھولتا ہوں جس طرح تم بھولتے، ہو اور مجھے بھی یاد رہتا ہے جیسے تمہیں یاد رہتا ہے\"، پھر آپ نے دو سجدے کیے، اور پیچھے کی طرف پلٹے۔","الألباني: حسن صحيح",{"u2":"حضرت عبداللہ بن مسعود رضی اللہ عنہ سے منقول ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے پچھلے پہر کی دو نمازوں (ظہر اور عصر) میں سے کوئی ایک نماز پانچ رکعت پڑھا دی۔ آپ سے پوچھا گیا: کیا نماز میں اضافہ ہوگیا ہے؟ آپ نے فرمایا: ’’کیا ہوا؟‘‘ انھوں نے کہا: آپ نے پانچ رکعتیں پڑھی ہیں۔ آپ نے فرمایا: ’’میں بھی ایک انسان ہوں۔ بھول جاتا ہوں جس طرح تم بھول جاتے ہو اور یاد رکھتا ہوں جس طرح تم یاد رکھتے ہو۔‘‘ پھر آپ نے دو سجدے فرمائے اور تشریف لے گئے","f2":"(۱)مندرجہ بالا تمام روایات میں پانچ رکعات پڑھنے کا ذکر ہے۔ رسول اکرم صلی اللہ علیہ وسلم نے بھی پانچ پڑھیں اور علقمہ نے بھی۔ ظاہر ہے چوتھی کو تیسری سمجھ کر ہی پانچویں پڑھی ہوگی، لہٰذا وہ (حقیقتاً) چوتھی میں نہیں بیٹھے ہوں گے۔ احناف کے نزدیک ایسی صورت میں فرضیت باطل ہو جاتی ہے مگر یہ صریح روایات ان کے موقف کی تردید کرتی ہیں۔ اس کا ان کے پاس کوئی جواب نہیں، الا یہ مانا جائے کہ رسول اللہ صلی اللہ علیہ وسلم اور علقمہ کو دو دو سہو ہوئے۔ پہلے چوتھی کو دوسری سمجھ کر بیٹھے۔ پھر صرف ایک رکعت پڑھ کر گویا تیسری میں ہی بیٹھ گئے۔ مگر یہ بہت بعید اور محض تکلف ہے۔ صحیح بات وہی ہے جو اوپر گزری۔ روایت کے ناقل حضرت عبداللہ بن مسعود رضی اللہ عنہ ہیں۔ ابن مسعود اور علقمہ دونوں احناف کے لیے حجت ہیں۔ (۲) ان روایات میں کلام کے بعد سجدۂ سہو کرنے کا ذکر ہے۔ اس کے بھی احناف قائل نہیں بلکہ یہ تو سلام سے متصل بعد سجدۂ سہو کے قائل ہیں اور سلام بھی صرف ایک طرف۔ فاصلہ اور کلام کی صورت میں اعادے کے قائل ہیں مگر ان کے اپنے ائمہ کی یہ روایات ان کے خلاف ہیں۔ (دونوں مسائل کی مزید تفصیل دیکھیے، حدیث: ۱۲۲۵، ۱۲۳۹)"}],[1260,"یوسف سے روایت ہے کہ معاویہ رضی اللہ عنہ نے لوگوں کے آگے نماز پڑھی (یعنی ان کی امامت کی) تو وہ نماز میں کھڑے ہو گئے، حالانکہ انہیں بیٹھنا چاہیئے تھا، تو لوگوں نے سبحان اللہ کہا، پر وہ کھڑے ہی رہے، اور نماز پوری کر لی، پھر بیٹھے بیٹھے دو سجدے کیے، پھر منبر پر بیٹھے، اور کہا: میں نے رسول اللہ صلی اللہ علیہ وسلم کو فرماتے سنا ہے: \"جو اپنی نماز میں سے کوئی چیز بھول جائے تو وہ ان دونوں سجدوں کی طرح سجدے کر لے\" ۱؎۔\n§وضاحت\n۱؎: ایک تو یہ حدیث سند کے اعتبار سے ضعیف ہے، دوسرے اس میں مذکور بھول بالکل عام نہیں ہے، بلکہ رکن کے سوا کسی اور چیز کی بھول مراد ہے، معاویہ رضی اللہ عنہ قعدہ اولی بھولے تھے جو رکن نہیں ہے، اس طرح کی بھول کا کفارہ سجدہ سہو ہو سکتا ہے، جیسا کہ اگلی حدیث میں آ رہا ہے۔","الألباني: ضعيف",{"u2":"حضرت یوسف (اموی) رحمہ اللہ سے روایت ہے کہ حضرت معاویہ رضی اللہ عنہ نے انھیں امام بن کر نماز پڑھائی۔ وہ نماز میں (ایک مقام پر) کھڑے ہوگئے جبکہ انھیں بیٹھنا چاہیے تھا۔ لوگوں نے [سبحان اللہ] کہا لیکن وہ کھڑے رہے۔ پھر انھوں نے نماز پوری کرنے کے بعد بیٹھے بیٹھے دو سجدے کیے۔ پھر منبر پر بیٹھ گئے اور فرمایا: میں نے رسول اللہ صلی اللہ علیہ وسلم کو یہ فرماتے سنا: ’’جو شخص اپنی نماز میں سے کچھ بھول جائے تو وہ ان دو سجدوں کی طرح سجدے کرے","f2":"یہ سہو دو رکعتوں کے بعد تشہد بھولنے کا سہو تھا۔ اس میں یہی طریقہ ہے کہ اگر امام کھڑا ہو جائے تو [سبحان اللہ] سننے کے باوجود واپس نہ بیٹھے بلکہ نماز جاری رکھے۔ آخر میں سلام سے پہلے سہو کے دوس جدے کرے۔ ہر سہو میں ایسے نہیں ہوتا۔ جیسا کہ پیچھے وضاحت ہوچکی ہے"}],[1261,"عبداللہ بن بحینہ رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم ظہر کی دوسری رکعت کے بعد (بغیر قعدہ کے) کھڑے ہو گئے، پھر (واپس) نہیں بیٹھے، پھر جب آپ نے اپنی نماز پوری کر لی تو جو تشہد آپ بھول گئے تھے اس کے عوض بیٹھے بیٹھے سلام پھیرنے سے پہلے دو سجدے کیے، اور ہر سجدہ میں اللہ اکبر کہا، آپ کے ساتھ لوگوں نے (بھی) یہ دونوں سجدے کیے۔","الألباني: صحيح",{"u2":"حضرت عبداللہ ابن بحینہ سے روایت ہے کہ نبی صلی اللہ علیہ وسلم ظہر کی دو رکعتوں کے بعد (بیٹھنے کی بجائے) سیدھے کھڑے ہوگئے۔ پھر (توجہ دلانے پر بھی) واپس نہ بیٹھے۔ جب نماز پوری فرما لی تو سلام پھیرنے سے پہلے بیٹھے بیٹھے دو سجدے کیے۔ ہر سجدے میں اللہ اکبر کہتے تھے۔ لوگوں نے بھی آپ کے ساتھ سجدے کیے۔ یہ اس قعدے کی جگہ تھے جو آپ بھول گئے تھے۔"}],[1262,"ابو حمید ساعدی رضی اللہ عنہ کہتے ہیں کہ نبی اکرم صلی اللہ علیہ وسلم جب ان دو رکعتوں میں ہوتے تھے جن میں نماز ختم ہوتی ہے، تو آپ (قعدہ میں) اپنا بایاں پاؤں(داہنی طرف) نکال دیتے، اور اپنی ایک سرین پر ٹیک لگا کر بیٹھتے پھر سلام پھیرتے ۱؎۔\n§وضاحت\n۱؎: اس بیٹھک کو تورک کہتے ہیں، اس سے پتہ چلا کہ قعدہ اخیرہ میں اس طرح بیٹھنا سنت ہے، بعض لوگ اسے کبرسنی پر محمول کرتے ہیں لیکن اس پر محمول کرنے کے لیے ان کے پاس کوئی صحیح دلیل نہیں، نیز بعض لوگوں کا یہ کہنا بھی درست نہیں کہ فجر کے قعدہ اخیرہ میں تورک ثابت نہیں، اس حدیث کے الفاظ سے صراحت کے ساتھ یہ ثابت ہو رہا ہے کہ \"قعدہ اخیرہ\" میں تورک کرتے تھے، اب خواہ یہ قعدہ اخیرہ فجر و مغرب کا ہو یا چار رکعتوں والی نمازوں کا۔","الألباني: صحيح",{"u2":"حضرت ابوحمید ساعدی رضی اللہ عنہ سے مروی ہے، انھوں نے فرمایا: نبی صلی اللہ علیہ وسلم ان دو رکعتوں کے بعد جن پر نماز ختم ہوتی ہے (تشہد میں بیٹھتے وقت) اپنا بایاں پاؤں دائیں طرف (پنڈلی کے نیچے سے) باہر نکال لیتے اور سرین پر (زور دے کر) بیٹھتے، پھر سلام پھیرتے۔","f2":"اس طریقے سے بیٹھنے کو شرعی اصلاح میں تورک کہتے ہیں، یعنی پاؤں پر بیٹھنے کی بجائے براہ راست نیچے بیٹھے اور بایاں پاؤں دائیں طرف نکال لے۔ سلام والے تشہد میں تورک سنت ہے جیسا کہ اس روایت میں صراحت ہے مگر احناف اسے نبی صلی اللہ علیہ وسلم کے بڑھاپے پر محمول کرتے ہیں لیکن اس کی کوئی دلیل پیش نہیں کرتے۔ نبی صلی اللہ علیہ وسلم کے تورک کرنے کو بڑھاپے کی حالت پر محمول کرنے والے حضرات سے یہ سوال کیا جا سکتا ہے کہ کیا چوتھی صدی سے لے کر آج تک آپ کا کوئی بزرگ اس قدر بوڑھا نہیں ہوا کہ اسے بھی رسول اللہ صلی اللہ علیہ وسلم کی طرح تورک کرنا پڑے؟ اگر یہ وجہ ہوتی تو صحابۂ کرام رضی اللہ عنہم ہم سے زیادہ اس بات کا ادراک فرماتے۔ تعجب کی بات ہے، یہ حدیث دس صحابۂ کرام رضی اللہ عنہم کی ایک جماعت میں بیان کی گئی ہے۔ ان میں سے کسی نے یہ توجیہ نہیں کی مگر بعد والے ان کی غلطیاں نکال رہے ہیں۔ سبحان اللہ۔ البتہ اگر جماعت کی صورت میں جگہ تنگ ہو اور تورک سے دوسرے نمازیوں کو مشکل پیش آتی ہو تو نہ کرنے کی بھی گنجائش ہے لیکن عام حالات میں یہی سنت ہے۔ حضرت ابوحمید رضی اللہ عنہ کی روایت بہت مفصل ہے۔ کسی مبہم روایت کی وجہ سے اسے چھوڑا نہیں جاسکتا"}],[1263,"وائل بن حجر رضی اللہ عنہ کہتے ہیں کہ میں نے رسول اللہ صلی اللہ علیہ وسلم کو دیکھا، جب آپ نماز شروع کرتے تو اپنے دونوں ہاتھ اٹھاتے، اور جب رکوع میں جاتے اور رکوع سے اپنا سر اٹھاتے (تو بھی اسی طرح اٹھاتے) اور جب آپ (قعدہ میں) بیٹھتے تو بایاں (پاؤں) لٹاتے، اور دایاں (پاؤں) کھڑا رکھتے، اور اپنا بایاں ہاتھ اپنی بائیں ران پر اور دایاں ہاتھ دائیں ران پر رکھتے، اور درمیان والی انگلی اور انگوٹھے دونوں کو ملا کر گرہ بناتے، اور اشارہ کرتے ۱؎۔\n§وضاحت\n۱؎: اس حدیث میں یہ صراحت نہیں ہے کہ یہ بیان آخری قعدہ کے بارے میں ہے، اس لیے باب سے مناسبت واضح نہیں، یا یہ مراد ہے کہ یہ بیان دونوں قعدوں کے بارے میں ہے، تو یہ بھی درست نہیں، کیونکہ ابو حمید ساعدی رضی اللہ عنہ کی حدیث صحیحین کی ہے نیز تورک کے بارے میں واضح ہے۔","الألباني: صحيح",{"u2":"حضرت وائل بن حجر رضی اللہ بیان کرتے ہیں کہ میں نے رسول اللہ صلی اللہ علیہ وسلم کو دیکھا کہ پ جب نماز شروع فرماتے، جب رکوع فرماتے اور جب رکوع سے سر اٹھاتے تو رفع الیدین کرتے۔ اور آپ جب بیٹھتے تو بائیں پاؤں کو بچھاتے اور دایاں کھڑا کرتے اور اپنا بایاں ہاتھ اپنی بائیں ران پر رکھتے اور دایاں ہاتھ دائیں ران پر رکھتے اور انگوٹھے اور درمیانی انگلی سے حلقہ بناتے اور (انگشت شہادت سے) اشارہ فرماتے","f2":"اس روایت میں بیٹھنے کا عام طریقہ بیان کیا گیا ہے مگر اوپر والی روایت میں سلام والے تشہد میں بیٹھنے کا مخصوص طریقہ بیان کیا گیا ہے اور یہ اصول ہے کہ مفصل روایت پر عمل کیا جاتا ہے اور مبہم کو مفصل پر محمول کیا جاتا ہے"}],[1264,"وائل بن حجر رضی اللہ عنہ سے روایت ہے کہ انہوں نے نبی اکرم صلی اللہ علیہ وسلم کو دیکھا کہ آپ نماز میں بیٹھے تو آپ نے اپنا بایاں پاؤں بچھایا، اور اپنے دونوں ہاتھ اپنی دونوں رانوں پر رکھا، اور شہادت کی انگلی سے اشارہ کیا، آپ اس کے ذریعہ دعا کر رہے تھے۔","الألباني: صحيح الإسناد",{"u2":"حضرت وائل بن حجر رضی اللہ عنہ سے روایت ہے کہ انھوں نے نبی صلی اللہ علیہ وسلم کو دیکھا، آپ نماز میں بیٹھے اور اپنا بایاں پاؤں بچھایا اور اپنے دونوں بازو اپنی رانوں پر رکھے اور تشہد پڑھتے وقت انگشت شہادت سے اشارہ فرمایا۔","f2":"قرائن سے یہ پہلا تشہد معلوم ہوتا ہے۔ اشارے وغیرہ کی کیفیت کی تفصیل کے لیے دیکھیے حدیث: ۸۹۰، ۱۱۶۲۔"}],[1265,"وائل بن حجر رضی اللہ عنہ کہتے ہیں کہ میں نے (اپنے جی میں) کہا کہ میں رسول اللہ صلی اللہ علیہ وسلم کو دیکھ کر رہوں گا کہ آپ نماز کیسے پڑھتے ہیں، تو (میں نے دیکھا کہ) رسول اللہ صلی اللہ علیہ وسلم کھڑے ہوئے، اور قبلہ رو ہوئے اور اپنے دونوں ہاتھوں کو اتنا اٹھایا کہ وہ آپ کے کانوں کے بالمقابل ہو گئے، پھر اپنے دائیں(ہاتھ) سے اپنے بائیں (ہاتھ) کو پکڑا، پھر جب رکوع میں جانے کا ارادہ کیا تو ان دونوں کو پھر اسی طرح اٹھایا، اور اپنے ہاتھوں کو اپنے گھٹنوں پر رکھا، پھر جب رکوع سے اپنا سر اٹھایا تو پھر ان دونوں کو اسی طرح اٹھایا، پھر جب سجدہ کیا تو اپنے سر کو اپنے دونوں ہاتھوں کے درمیان اسی جگہ پر رکھا ۱؎، پھر آپ بیٹھے تو اپنا بایاں پاؤں بچھایا، اور اپنا بایاں ہاتھ اپنی بائیں ران پر رکھا، اور اپنی دائیں کہنی کو اپنی دائیں ران سے دور رکھا، پھر اپنی دو انگلیاں بند کیں، اور حلقہ بنایا، اور میں نے انہیں اس طرح کرتے دیکھا۔ بشر نے داہنے ہاتھ کی شہادت کی انگلی سے اشارہ کیا، اور انگوٹھے اور درمیانی انگلی کا حلقہ بنایا۔\n§وضاحت\n۱؎: یعنی اپنا سر اس طرح رکھا کہ دونوں ہاتھ دونوں کانوں کے بالمقابل ہو گئے۔","الألباني: صحيح",{"u2":"حضرت وائل بن حجر رضی اللہ عنہ بیان کرتے ہیں کہ (ایک دفعہ) میں نے (اپنے دل میں) کہا کہ واللہ! میں اللہ کے رسول صلی اللہ علیہ وسلم کی نماز کو بغور دیکھوں گا کہ آپ کیسے نماز پڑھتے ہیں؟ رسول اللہ صلی اللہ علیہ وسلم کھڑے ہوئے، قبلے کی طرف منہ فرمایا اور اپنے دونوں ہاتھ اٹھائے حتی کہ وہ کانوں کے برابر ہوگئے۔ پھر آپ نے اپنے بائیں ہاتھ کو دائیں سے پکڑ لیا۔ جب آپ نے رکوع کا ارادہ فرمایا تو انھیں پھر اسی طرح اٹھایا اور اپنے ہاتھ اپنے گھٹنوں پر رکھے، چنانچہ جب رکوع سے سر اٹھایا تو دونوں ہاتھ پھر اسی طرح اٹھائے، پھر جب سجدہ کیا تو اپنا سر اپنے ہاتھوں کے ساتھ رفع الیدین والی کیفیت میں رکھا۔ (جہاں تک ہاتھ اٹھائے تھے، وہیں تک ہاتھ سجدے میں سر کے قریب رہے) پھر آپ بیٹھ گئے اور اپنا بایاں پاؤں بچھایا اور اپنا بایاں ہاتھ بائیں ران پر رکھا اور دائیں کہنی کا کنارہ اپنی دائیں ران پر رکھا۔ دو (چھنگلی اور اس کے ساتھ والی) انگلیاں بند کیں اور انگوٹھے اور درمیانی انگلی سے حلقہ بنایا اور انگشت شہادت سے اشارہ کیا","f2":"تفصیل کے لیے دیکھیے، حدیث: ۸۹۰۔"}],[1266,"علی بن عبدالرحمٰن کہتے ہیں کہ میں نے ابن عمر رضی اللہ عنہم کے بغل میں نماز پڑھی، تو میں کنکریوں کو الٹنے پلٹنے لگا، (نماز سے فارغ ہونے پر) انہوں نے مجھ سے کہا: (نماز میں) کنکریاں مت پلٹو، کیونکہ کنکریاں کو الٹنا پلٹنا شیطان کی جانب سے ہے، (بلکہ) اس طرح کرو جس طرح میں نے رسول اللہ صلی اللہ علیہ وسلم کو کرتے دیکھا ہے، میں نے کہا: آپ نے رسول اللہ صلی اللہ علیہ وسلم کو کیسے کرتے دیکھا ہے؟، انہوں نے کہا: اس طرح سے، اور انہوں نے دائیں پیر کو قعدہ میں کھڑا کیا، اور بائیں پیر کو لٹایا ۱؎، اور اپنا دایاں ہاتھ اپنی دائیں ران پر اور بایاں ہاتھ اپنی بائیں ران پر رکھا، اور شہادت کی انگلی سے اشارہ کیا ۲؎۔\n§وضاحت\n۱؎: دائیں پاؤں کو کھڑا کر کے بائیں پاؤں کو بچھا کر اس پر بیٹھنے والی ساری روایتیں مبہم ہیں، اور ابوحمید رضی اللہ عنہ والی روایت کہ جس میں قعدہ اخیرہ میں تورک کا ذکر ہے، مفصل ہے اس لیے انصاف کا تقاضا یہ ہے کہ مبہم کو مفصل پر محمول کیا جائے۔ ۲؎: دونوں قعدوں میں دائیں ہاتھ کے انگوٹھے اور درمیانی انگلی کا حلقہ بنا کر دائیں گھٹنے پر رکھنا، اور شہادت کی انگلی سے اشارہ کرنا سنت ہے اس اشارہ کا کوئی وقت متعین نہیں ہے، شروع تشہد سے اخیر تک اشارہ کرتے رہنا چاہیئے، اور اس اشارہ میں کبھی انگلی کو حرکت دینا اور کبھی نہ دینا دونوں ثابت ہے، اس بابت تمام روایات کا یہی حاصل ہے، صرف «أشھد أن لا إلہ إلا اللہ» پر اشارہ کرنا ثابت نہیں ہے۔","الألباني: صحيح",{"u2":"حضرت علی بن عبدالرحمٰن بیان کرتے ہیں کہ میں نے حضرت ابن عمر رضی اللہ عنہما کے پاس نماز پڑھی۔ میں کنکریوں کو الٹ پلٹ کرنے لگا تو مجھے ابن عمر رضی اللہ عنہما کہنے لگے: کنکریوں کو نہ چھیڑو کیونکہ کنکریوں سے کھیلنا شیطانی فعل ہے بلکہ اس طرح کرو جیسے میں نے رسول اللہ صلی اللہ علیہ وسلم کو کرتے دیکھا۔ میں نے کہا: آپ نے رسول اللہ صلی اللہ علیہ وسلم کو کیسے کرتے دیکھا ہے؟ فرمایا: ایسے۔ پھر ابن عمر رضی اللہ عنہما نے اپنا دایاں پاؤں کھڑا کیا اور بائیں کو بچھایا اور اپنا دایاں ہاتھ اپنی دائیں ران پر رکھا اور بایاں ہاتھ اپنی بائیں ران پر رکھا اور آپ نے شہادت کی انگلی سے اشارہ کیا۔"}],[1267,"علی بن عبدالرحمٰن کہتے ہیں کہ ابن عمر رضی اللہ عنہم نے مجھے نماز میں کنکریوں سے کھیلتے دیکھا تو نماز سے فارغ ہونے کے بعد انہوں نے مجھے منع کیا، اور کہا: اس طرح کیا کرو جس طرح رسول اللہ صلی اللہ علیہ وسلم کرتے تھے، میں نے کہا: آپ صلی اللہ علیہ وسلم کس طرح کرتے تھے؟ کہا: جب آپ صلی اللہ علیہ وسلم نماز میں بیٹھتے تو اپنی دائیں ہتھیلی اپنی دائیں ران پر رکھتے ۱؎، اور اپنی سبھی انگلیاں سمیٹے رکھتے، اور اپنی اس انگلی سے جو انگوٹھے کے قریب ہے اشارہ کرتے، اور اپنی بائیں ہتھیلی اپنی بائیں ران پر رکھتے ۲؎۔\n§وضاحت\n۱؎: اور ایک روایت میں ہے اپنے داہنے گھٹنے پر۔ ۲؎: اور ایک روایت میں ہے اپنے بائیں گھٹنے پر۔","الألباني: صحيح",{"u2":"حضرت علی بن عبدالرحمن بیان کرتے ہیں کہ مجھے حضرت ابن عمر رضی اللہ عنہما نے نماز کے دوران میں کنکریوں سے کھیلتے دیکھا۔ جب وہ نماز سے فارغ ہوئے تو انھوں نے مجھے روکا اور فرمایا: اس طرح کرو جیسے رسول اللہ صلی اللہ علیہ وسلم کرتے تھے۔ میں نے کہا آپ کیسے کرتے تھے؟ انھوں نے فرمایا: آپ جب نماز میں بیٹھتے تو اپنی دائیں ہتھیلی کو (دائیں) ران پر رکھتے اور اپنی تمام انگلیاں بند کر لیتے اور اس انگلی سے اشارہ فرماتے جو انگوٹھے کے ساتھ ملتی ہے اور اپنا بایاں ہاتھ اپنی بائیں ران پر رکھتے","f2":"دائیں ہاتھ کو رکھنے کا ایک یہ بھی انداز ہے کہ سب انگلیاں بند کرلی جائیں اور انگوٹھے کا سرا شہادت والی انگلی کی جڑ میں رکھا جائے، صرف شہادت والی انگلی کھلی رکھی جائے۔"}],[1268,"وائل بن حجر رضی اللہ عنہ کہتے ہیں کہ میں نے (اپنے جی میں) کہا کہ میں رسول اللہ صلی اللہ علیہ وسلم کی نماز کو دیکھوں گا کہ آپ کیسے پڑھتے ہیں؟ تو میں نے دیکھا، پھر انہوں نے آپ صلی اللہ علیہ وسلم کے نماز پڑھنے کی کیفیت بیان کی، اور کہا: پھر آپ صلی اللہ علیہ وسلم بیٹھے اور آپ صلی اللہ علیہ وسلم نے اپنا بایاں پیر بچھایا، اور اپنی بائیں ہتھیلی اپنی بائیں ران اور گھٹنے پر رکھا، اور اپنی دائیں کہنی کے سرے کو اپنی دائیں ران پر کیا، پھر اپنی انگلیوں میں سے دو کو سمیٹا، اور (باقی انگلیوں میں سے دو سے)حلقہ بنایا، پھر اپنی شہادت کی انگلی اٹھائی تو میں نے آپ صلی اللہ علیہ وسلم کو دیکھا کہ آپ اسے ہلا رہے تھے، اس کے ذریعہ دعا مانگ رہے تھے۔","الألباني: صحيح",{"u2":"حضرت وائل بن حجر رضی اللہ عنہ سے روایت ہے، انھوں نے فرمایا: میں نے ارادہ کیا کہ میں ضرور اللہ کے رسول صلی اللہ علیہ وسلم کی نماز کو بغور دیکھوں گا کہ آپ کیسے نماز پڑھتے ہیں۔ میں نے غور سے دیکھا…… پھر انھوں نے بیان کیا کہ ……… پھر آپ بیٹھے اور اپنا بایاں پاؤں بچھایا اور اپنی بائیں ہتھیلی اپنی بائیں ران اور گھٹنے پر رکھی اور اپنی دائیں کہنی کا کنارہ اپنی دائیں ران پر رکھا۔ پھر (اپنے دائیں ہاتھ کی) دو انگلیاں بند کیں اور (درمیانی انگلی اور انگوٹھے سے) حلقہ بنایا۔ پھر اپنی انگشت شہادت کو اٹھایا۔ میں نے آپ کو دیکھا، آپ اسے حرکت دیتے تھے اور اس کے ساتھ دعا کرتے تھے۔ یہ روایت مختصر ہے۔","f2":"انگلی کو حرکت دینے کے بارے میں تفصیل پیچھے گزر چکی ہے۔ ملاحظہ فرمائیے حدیث: ۸۹۰ کے فوائد و مسائل۔"}],[1269,"عبداللہ بن عمر رضی اللہ عنہم سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم جب نماز میں بیٹھتے تو آپ اپنے دونوں ہاتھوں کو اپنے دونوں گھٹنوں پر رکھ لیتے، اور جو انگلی انگوٹھے سے لگی ہوتی اسے اٹھاتے، اور اس سے دعا مانگتے، اور آپ کا بایاں ہاتھ آپ کے بائیں گھٹنے پر پھیلا ہوتا تھا، (یعنی: بائیں ہتھیلی کو حلقہ بنانے کے بجائے اس کی ساری انگلیاں بائیں گھٹنے پر پھیلائے رکھتے تھے)۔","الألباني: صحيح",{"u2":"حضرت ابن عمر رضی اللہ عنہما سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم جب نماز میں بیٹھتے تو اپنے دونوں ہاتھ اپنے گھٹنوں پر رکھتے اور انگوٹھے کے ساتھ والی انگلی اٹھاتے اور اس کے ساتھ دعا کرتے اور بائیں ہاتھ کو کھول کر گھٹنے پر رکھتے","f2":"بعض روایات میں ران پر ہاتھ رکھنے کا ذکر ہے اور بعض میں گھٹنے پر۔ تطبیق یوں ممکن ہے کہ تہھیلی ران پر ہو اور انگلیاں گھٹنے پر۔ بعض روایات میں یہ طریقہ صراحتاً بھی منقول ہے۔ جیسا کہ حدیث: ۱۲۶۹ میں ہے۔ اگرچہ ران والی روایات کا لحاظ رکھتے ہوئے بعض حضرات نے پورا ہاتھ ران پر رکھنا بھی جائز قرار دیا ہے مگر اولیٰ یہی ہے کہ سب روایات پر عمل کیا جائے۔"}],[1270,"عبداللہ بن زبیر رضی اللہ عنہم سے روایت ہے کہ نبی اکرم صلی اللہ علیہ وسلم جب دعا کرتے تو اپنی انگلی سے اشارہ کرتے تھے، اور اسے ہلاتے نہیں تھے ۱؎۔ ابن جریج کہتے ہیں کہ عمرو نے (اس میں) اضافہ کیا ہے، انہوں نے کہا کہ عامر بن عبداللہ بن زبیر نے مجھے خبر دی، وہ اپنے باپ سے روایت کرتے ہیں کہ انہوں نے نبی اکرم صلی اللہ علیہ وسلم کو دیکھا کہ آپ اسی طرح دعا کرتے، اور آپ اپنے بائیں ہاتھ سے اپنے بائیں پاؤں کو تھامے رہتے تھے۔\n§وضاحت\n۱؎: حدیث کے اس ٹکڑے \"اور اس کو ہلاتے نہیں تھے\" کو بعض علماء نے \"شاذ\" قرار دیا ہے، اور بعض اس کا یہ معنی بیان کرتے ہیں کہ \"کبھی بھی نہیں ہلاتے تھے، اور صرف اشارہ پر اکتفاء کرتے تھے\" یا یہ مطلب ہے کہ صرف اشارہ کے عمل کو وائل رضی اللہ عنہ نے \"ہلاتے رہتے تھے\" سے تعبیر کر دیا ہے، اور ابن زبیر رضی اللہ عنہم نے اصل حقیقت بیان کر دی ہے، یعنی اشارہ کرتے تھے ہلاتے نہیں تھے، ہمارے خیال میں: تمام روایات کا خلاصہ یہ ہے کہ آپ اشارہ تو بلاتعیین وقت کرتے تھے، رہی ہلانے کی بات تو کبھی ہلاتے تھے اور کبھی نہیں ہلاتے تھے، جس نے جو دیکھا اسے بیان کر دیا، یا مطلب یہ ہے کہ اشارہ میں انگلی کا ہل جانا بالکل ممکن ہے اس کو وائل رضی اللہ عنہ نے \"ہلاتے تھے\" سے تعبیر کر دیا، اصل کام اشارہ تھا۔","الألباني: شاذ بزيادة ولا يحركها",{"u2":"حضرت عبداللہ بن زبیر رضی اللہ عنہ سے منقول ہے کہ نبی صلی اللہ علیہ وسلم جب دعا کرتے (تشہد پڑھتے) تو اپنی انگلی سے اشارہ کرتے اور اسے حرکت نہیں دیتے تھے۔ دوسری روایت میں عبداللہ بن زبیر رضی اللہ عنہ سے یہ مروی ہے کہ انھوں نے نبی صلی اللہ علیہ وسلم کو دیکھا آپ اسی طرح دعا کرتے تھے اور آپ اپنا بایاں ہاتھ (کھول کر) اپنی بائیں ٹانگ پر رکھتے تھے اور اس پر بوجھ ڈالتے تھے","f2":"[ولا یحرکھا] ’’اور اسے حرکت نہ دیتے تھے‘‘ کے اضافے کے ساتھ یہ روایت شاذ ہے۔ شیخ البانی رحمہ اللہ فرماتے ہیں: اس حدیث کی سند حسن ہے لیکن [ولا یحرکھا] کا اضافہ شاذ ہے۔ اسے ابن عجلان سے بیان کرنے میں زیاد بن سعد متفرد ہے۔ اور ثقات کی ایک جماعت نے اس کی مخالفت کی ہے، وہ اس طرح کہ جب انھوں نے ابن عجلان سے یہ حدیث بیان کی ہے تو اس اضافے کے بغیر نقل کی ہے اور ابن عجلان کی دو ثقات نے متابعت کی ہے۔ انھوں نے بھی عامر بن عبداللہ سے اس زیادتی کے بغیر یہ روایت بیان کی ہے، اس لیے ابن قیم رحمہ اللہ نے فرمایا: ’’اس کی صحت محل نظر ہے۔‘‘ مزید برآں یہ کہ اس اضافے کی مخالفت وائل بن حجر رضی اللہ عنہ کی حدیث سے بھی ہوتی ہے، جس میں ہے کہ پھر آپ علیہ الصلوۃ والسلام نے اپنی انگلی اٹھائی۔ میں نے آپ کو دیکھا کہ پ اسے حرکت دے رہے تھے اور اس کے ساتھ دعا کرتے تھے۔ تفصیل کے لیے دیکھیے: (ضعیف سنن أبي داود (مفصل) للألباني، حدیث: ۱۷۵) الغرض مذکورہ زیادتی ضعیف اور شاذ ہے جبکہ باقی حدیث درجۂ قبول کو پہنچتی ہے۔ اگرچہ محقق کتاب نے پوری روایت کو سنداً ضعیف قرار دیا ہے۔ واللہ اعلم۔"}],[1271,"نمیر خزاعی رضی اللہ عنہ کہتے ہیں میں نے رسول اللہ صلی اللہ علیہ وسلم کو دیکھا کہ آپ نماز میں اپنا دایاں ہاتھ اپنی دائیں ران پر رکھے ہوئے تھے، اور اپنی انگلی سے اشارہ کر رہے تھے۔","الألباني: صحيح",{"u2":"حضرت نمیر خزاعی رضی اللہ عنہ سے روایت ہے، انھوں نے فرمایا: میں نے رسول اللہ صلی اللہ علیہ وسلم کو دوران نماز میں دایاں ہاتھ دائیں ران پر رکھے ہوئے دیکھا۔ آپ اپنی انگلی سے اشارہ فرما رہے تھے۔","f2":"تشہد (پہلا ہو یا آخری اس) میں دایاں ہاتھ شروع ہی سے اس طرح رکھا جاتا ہے کہ تین انگلیاں اور انگوٹھا بند اور انگشت شہادت کھلی ہوتی ہے۔ اور یہ کیفیت تکبیر یا سلام تک قائم رہتی ہے۔ انگشت شہادت کو شروع تشہد سے آخر تک بغیر خم کے اشارے کے انداز میں سیدھا کھڑا بھی کرسکتے ہیں اور مسلسل حرکت بھی دے سکتے ہیں۔ دونوں طریقے جائز اور ثابت ہیں۔ بلکہ حرکت الگ چیز ہے اور اشارہ الگ، لہٰذا اکثر اشارہ (کیونکہ زیادہ روایات میں اشارے کا ذکر ہے) اور کبھی کبھار مسلسل حرکت دے لینی چاہیے جیسا کہ تفصیل پیچھے گزر چکی ہے۔ دیکھیے، حدیث: ۸۹۰ کے فوائد و مسائل"}],[1272,"ابوہریرہ رضی اللہ عنہ سے روایت ہے کہ ایک آدمی اپنی دو انگلیوں سے اشارہ کر رہا تھا تو رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"ایک سے (اشارہ) کرو ایک سے\"۔","الألباني: صحيح",{"u2":"حضرت ابوہریرہ رضی اللہ عنہ سے منقول ہے، ایک آدمی اپنی دو انگلیوں سے اشارہ کر رہا تھا تو رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’ایک انگلی سے اشارہ کر۔ ایک انگلی سے اشارہ کر۔‘‘","f2":"دو انگلیوں سے اشارہ یا تو دائیں ہاتھ ہی کی دو انگلیوں سے ہوگا اور یہ بھی ممکن ہے کہ دونوں ہاتھوں کی انگوٹھے ک ےساتھ والی انگلیوں کے ساتھ ہو چونکہ یہ اشارہ توحید کا عملی اظہار ہے، لہٰذا ایک انگلی ہی سے ہونا چاہیے"}],[1273,"سعد رضی اللہ عنہ کہتے ہیں کہ میرے پاس سے رسول اللہ صلی اللہ علیہ وسلم گزرے، اور میں (تشہد میں) اپنی انگلیوں ۱؎ سے (اشارہ کرتے ہوئے) دعا کر رہا تھا، تو آپ نے فرمایا: \"ایک سے (اشارہ) کرو ایک سے\"، اور آپ نے شہادت کی انگلی سے اشارہ کیا۔\n§وضاحت\n۱؎: اس سے پہلے والی روایت میں، دو انگلیوں سے اشارہ کرنے کا ذکر ہے اس لیے اسے اقل جمع یعنی دو پر محمول کیا جائے گا، یا یہ مانا جائے کہ یہ دو الگ الگ واقعات ہیں، واللہ اعلم۔","الألباني: صحيح",{"u2":"حضرت سعد رضی اللہ عنہ بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم میرے پاس گزرے جبکہ میں اپنی کئی انگلیوں سے اشارہ کر رہا تھا۔ آپ صلی اللہ علیہ وسلم نے فرمایا: ’’ایک سے کر۔ ایک سے کر۔‘‘ اور آپ نے اپنی (دائیں ہاتھ کی) انگشت شہادت کے ساتھ اشارہ کیا۔","f2":"(۱)ممکن ہے پہلی حدیث میں بھی حضرت سعد رضی اللہ عنہ ہی کا واقعہ ہو تو پھر کئی انگلیوں سے مراد ایک سے زائد، یعنی دو ہوں گی ورنہ یہ الگ الگ واقعات ہیں۔ (۲) مذکورہ روایات کو محقق کتاب نے سندا ضعیف قرار دیا ہے جبکہ دیگر محققین نے انھیں صحیح قرار دیا ہے۔ محقق عصر شیخ البانی رحمہ اللہ نے صحیح سنن ابی داود (مفصل) میں اس موضوع پر سیر حاصل بحث کی ہے جس سے معلوم ہوتا ہے کہ مذکورہ دونوں روایتیں صحیح ہیں۔ بنا بریں معلوم ہوا کہ اشارہ ایک ہی انگلی سے کرنا چاہیے۔ واللہ أعلم۔ مزید تفصیل کے لیے دیکھیے: (صحیح سنن النسائي: ۱/۴۰۷، رقم: ۱۲۷۱ ۱۲۷۲، و سنن أبي داود (مفصل): ۵/۲۳۵، ۲۳۶، رقم: ۱۲۴۴)"}],[1274,"نمیر رضی اللہ عنہ کہتے ہیں کہ انہوں نے رسول اللہ صلی اللہ علیہ وسلم کو نماز میں بیٹھے ہوئے دیکھا، اس حال میں کہ آپ اپنا دایاں ہاتھ اپنی دائیں ران پر رکھے ہوئے تھے، اور اپنی شہادت کی انگلی اٹھائے ہوئے تھے، اور آپ نے اسے کچھ جھکا رکھا تھا، اور آپ دعا کر رہے تھے۔","الألباني: منكر بزيادة الإحناء",{"u2":"حضرت نمیر خزاعی رضی اللہ عنہ نے بیان کیا کہ انھوں نے رسول اللہ صلی اللہ علیہ وسلم کو نماز میں بیٹھے ہوئے دیکھا۔ آپ نے اپنا دایاں بازو اپنی دائیں ران پر رکھا تھا اور اپنی انگشت شہادت اٹھا رکھی تھی، البتہ اسے کچھ جھکایا ہوا تھا اور آپ تشہد پڑھ رہے تھے۔","f2":"محقق کتاب نے اس روایت کو سنداً حسن کہا ہے جبکہ دیگر محققین نے [قد احناھا شیئا] کے علاوہ باقی روایت کو صحیح قرار دیا ہے۔ شیخ البانی رحمہ اللہ نے ان الفاظ کو منکر کہا ہے اور موسوعۃ الحدیثیۃ کے محققین نے ان الفاظ کے علاوہ باقی روایت کو صحیح لغیرہ قرار دیا ہے۔ بنا بریں مذکورہ روایت ان الفاظ کے علاوہ قابل عمل ہے۔ واللہ أعلم، مزید تفصیل کے لیے دیکھیے: (ضعیف سنن أبي داود (مفصل): ۹/۳۷۱، رقم: ۱۷۶، والموسوعۃ الحدیثیۃ مسند الإمام أحمد: ۲۵/۲۰۰-۲۰۱، رقم: ۱۵۸۶۶)"}],[1275,"عبداللہ بن زبیر رضی اللہ عنہما سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم جب تشہد میں بیٹھتے تھے تو اپنی بائیں ہتھیلی بائیں ران پر رکھتے، اور شہادت کی انگلی سے اشارہ کرتے، آپ کی نگاہ آپ کے اشارہ سے آگے نہیں بڑھتی تھی۔","الألباني: حسن صحيح",{"u2":"حضرت عبداللہ بن زبیر رضی اللہ عنہما سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم جب تشہد میں بیٹھتے تو اپنی بائیں ہتھیلی اپنی بائیںران پر رکھتے اور (دائیں ہاتھ کی) انگشت شہادت سے اشارہ فرماتے۔ آپ کی نظر اشارے سے آگے نہیں جاتی تھی۔","f2":"(۱)دوسری روایات جن کے مطابق نظر سجدہ گاہ میں رہنی چاہیے وہ قیام و رکوع کے بارے میں ہیں اور یہ روایت تشہد کے بارے میں ہے، لہٰذا ان میں کوئی تعارض نہیں، یعنی دورانِ قیام و رکوع نظر سجدہ گاہ میں ہونی چاہیے اور دوران تشہد اشارے پر۔ (۲) اشارے اور حرکت کی بحث حدیث ۸۹۰ میں گزر چکی ہے"}],[1276,"ابوہریرہ رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"نماز میں دعا کے وقت لوگ اپنی نگاہوں کو آسمان کی طرف اٹھانے سے باز آ جائیں، ورنہ ان کی نگاہیں اچک لی جائیں گی\"۔\n§وضاحت\n۱؎: یہ ممانعت حالت نماز میں ہے، نماز سے باہر دعا کرنے والا آسمان کی طرف نظر اٹھا سکتا ہے۔","الألباني: صحيح",{"u2":"حضرت ابوہریرہ رضی اللہ عنہ سے مروی ہے، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’لوگ نماز کے دوران میں دعا کے وقت آسمان کی طرف نظریں اٹھانے سے باز آ جائیں ورنہ ان کی نظریں اچک لی جائیں گی۔‘‘","f2":"فوائد و مسائل کے لیے دیکھیے، احادیث: ۱۱۹۴، ۱۱۹۵۔"}],[1277,"ابن مسعود رضی اللہ عنہ کہتے ہیں کہ ہم لوگ نماز میں تشہد کے فرض کئے جانے سے پہلے «السلام على اللہ السلام على جبريل وميكائيل» \"سلام ہو اللہ پر، سلام ہو جبرائیل اور میکائیل پر\" کہا کرتے تھے، تو رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"تم لوگ اس طرح نہ کہو، کیونکہ اللہ تو خود سلام ہے، بلکہ یوں کہو:«التحيات لله والصلوات والطيبات السلام عليك أيها النبي ورحمة اللہ وبركاته السلام علينا وعلى عباد اللہ الصالحين أشهد أن لا إله إلا اللہ وأشهد أن محمدا عبده ورسوله» \"تمام قولی، فعلی اور مالی عبادتیں اللہ ہی کے لیے ہیں، اے نبی آپ پر اللہ کی جانب سے سلامتی ہو، اور آپ پر اس کی رحمتیں اور اس کی برکتیں نازل ہوں، سلامتی ہو ہم پر اور اللہ کے نیک بندوں پر، میں گواہی دیتا ہوں کہ نہیں ہے کوئی معبود برحق سوائے اللہ کے، اور میں گواہی دیتا ہوں کہ محمد (صلی اللہ علیہ وسلم) اس کے بندے اور اس کے رسول ہیں\"۔","الألباني: صحيح",{"u2":"حضرت عبداللہ بن مسعود رضی اللہ عنہ بیان کرتے ہیں کہ تشہد فرض ہونے سے پہلے ہم کہا کرتے تھے: [السلام علی اللہ، السلام علی جبریل و میکائیل] ’’اللہ پر سلام ہو۔ جبریل و میکائیل پر سلام ہو۔‘‘ تو رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’ایسے نہ کہو کیونکہ اللہ عزوجل خود سلام ہے، لیکن یوں کہو: [التحیات للہ……… ورسولہ] ’’تمام آداب (یا قولی عبادات) اور تمام دعائیں اور نمازیں (یا بدنی عبادات) اور پاکیزہ کلمات (یا مالی عبادات) اللہ تعالیٰ کے لیے ہیں۔ اے نبی! آپ پر اللہ تعالیٰ کا سلام، رحمت اور برکتیں ہوں۔ ہم پر اور اللہ تعالیٰ کے نیک بندوں پر بھی سلام ہو۔ میں گواہی دیتا ہوں کہ اللہ تعالیٰ کے سوا کوئی حقیقی معبود نہیں اور میں گواہی دیتا ہوں کہ محمد (صلی اللہ علیہ وسلم) اس کے بندے اور رسول ہیں۔‘‘","f2":"مزید تفصیل کے لیے دیکھیے فوائد حدیث: ۱۰۶۵۔"}],[1278,"عبداللہ بن عباس رضی اللہ عنہم کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم ہمیں تشہد اسی طرح سکھاتے تھے جیسے آپ ہمیں قرآن کی سورت سکھاتے تھے۔","الألباني: صحيح",{"u2":"حضرت ابن عباس رضی اللہ عنہ سے مروی ہے کہ رسول اللہ صلی اللہ علیہ وسلم ہمیں تشہد اس طرح سکھاتے تھے جس طرح قرآن مجید کی کوئی سورت سکھاتے تھے۔","f2":"معین اور مسنون اوراد و وظائف میں حتی الامکان کمی بیشی اور تبدیلی سے اجتناب کرنا چاہیے حتی کہ لفظ ’’نبی‘‘ کی جگہ لفظ ’’رسول‘‘ بھی نہ کہا جائے۔ قرآن مجید کی طرح تعلیم دینے کا یہی مطلب ہے۔ اسی طرح اذان اور ادعیۂ مسنونہ بعینہٖ پڑھنی چاہئیں، ورنہ تحریف کا الزام آئے گا، البتہ مطلق دعائیں اپنی پسند کے مطابق کی جا سکتی ہیں اگرچہ قرآن و حدیث میں منقول دعائیں بہرحال جامع، مبارک اور بہتر ہیں۔\nباب ۴۳: تشہد کیسے پڑھا جائے؟"}],[1279,"عبداللہ بن مسعود رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"اللہ عزوجل خود سلام ہے، لہٰذا جب تم میں سے کوئی (تشہد میں) بیٹھے تو وہ یوں کہے: «التحيات لله والصلوات والطيبات السلام عليك أيها النبي ورحمة اللہ وبركاته السلام علينا وعلى عباد اللہ الصالحين أشهد أن لا إله إلا اللہ وأشهد أن محمدا عبده ورسوله» \"تمام قولی، فعلی اور مالی عبادتیں اللہ ہی کے لیے ہیں، اے نبی آپ پر سلام ہو، اور اللہ کی رحمتیں اور برکتیں آپ پر نازل ہوں، سلامتی ہو ہم پر، اور اللہ کے نیک بندوں پر، میں گواہی دیتا ہوں کہ نہیں ہے کوئی حقیقی معبود سوائے اللہ کے، اور میں گواہی دیتا ہوں کہ محمد اس کے بندے اور اس کے رسول ہیں\" پھر اس کے بعد اسے اختیار ہے جو چاہے دعا کرے\"۔","الألباني: صحيح",{"u2":"حضرت عبداللہ بن مسعود رضی اللہ عنہ سے روایت ہے، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’بلاشبہ اللہ تعالیٰ خود السلام ہے (لہٰذا السلام علی اللہ نہ کہو بلکہ) جب تم میں سے کوئی (قعدے میں) بیٹھے تو یوں کہے: [التحیات للہ و الصلوات ……… عبدہ و رسولہ] ’’تمام آداب، سب دعائیں اور سارے پاکیزہ کلمات اللہ تعالیٰ کے لیے ہیں۔ اے نبی! آپ پر سلام ہو اور اللہ کی رحمت و برکات نازل ہوں۔ ہم پر اور اللہ تعالیٰ کے نیک بندوں پر سلام ہو۔ میں گواہی دیتا ہوں کہ اللہ تعالیٰ کے سوا کوئی حقیقی معبود نہیں اور حضرت محمد (صلی اللہ علیہ وسلم) اس کے بندے اور رسول ہیں۔‘‘ پھر اس کے بعد وہ اپنی پسند کے مطابق دعا کرے۔‘‘","f2":"تشہد کی بحث کے لیے دیکھیے، حدیث ۱۱۷۶۔"}],[1280,"ابوموسی اشعری رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے ہمیں خطبہ دیا تو آپ نے ہمیں ہمارے طریقے بتائے، اور ہم سے ہماری نماز کے طریقے بیان کیے، آپ نے فرمایا: \"جب تم نماز کے لیے کھڑے ہو تو اپنی صفوں کو درست کرو، پھر تم میں سے کوئی تمہاری امامت کرے، جب وہ «اللہ اکبر» کہے، تو تم بھی «اللہ اکبر» کہو، اور جب وہ «ولا الضالين» کہے تو تم آمین کہو، اللہ تمہاری اس کی ہوئی دعا کو قبول کرے گا، پھر جب وہ «اللہ اکبر» کہے اور رکوع کرے، تو تم بھی «اللہ اکبر» کہو اور رکوع کرو، بیشک امام تم سے پہلے رکوع کرے گا، اور تم سے پہلے سر اٹھائے گا\"، تو ادھر کی کمی ادھر سے پوری ہو جائے گی، اور جب وہ «سمع اللہ لمن حمده» کہے تو تم «اللہم ربنا لك الحمد» \"اے اللہ! ہمارے رب تیرے ہی لیے تمام حمد ہے\" کہو، اس لیے کہ اللہ نے اپنے نبی کریم صلی اللہ علیہ وسلم کی زبان سے کہلوا دیا ہے کہ اس نے اپنے حمد کرنے والے کی حمد سن لی ہے، پھر جب وہ «اللہ اکبر» کہے اور سجدہ کرے، تو تم بھی «اللہ اکبر» کہو اور سجدہ کرو، بیشک امام تم سے پہلے سجدہ میں جائے گا، اور تم سے پہلے سر اٹھائے گا\"، تو ادھر کی کمی ادھر پوری ہو جائے گی، اور جب وہ قعدہ میں ہو تو تم میں سے ہر ایک کو یہ کہنا چاہیئے: «التحيات الطيبات الصلوات لله السلام عليك أيها النبي ورحمة اللہ وبركاته السلام علينا وعلى عباد اللہ الصالحين أشهد أن لا إله إلا اللہ وأشهد أن محمدا عبده ورسوله» \"تمام قولی، فعلی، اور مالی عبادتیں اللہ کے لیے ہیں، سلام ہو آپ پر اے نبی! اور اللہ کی رحمت اور برکت آپ پر نازل ہو، سلامتی ہو ہم پر اور اللہ کے نیک بندوں پر، میں گواہی دیتا ہوں کہ نہیں ہے کوئی معبود برحق سوائے اللہ کے، اور میں گواہی دیتا ہوں کہ محمد اس کے بندے اور رسول ہیں\"۔","الألباني: صحيح",{"u2":"حضرت ابو موسیٰ اشعری رضی اللہ عنہ بیان کرتے ہیں کہ تحقیق رسول اللہ صلی اللہ علیہ وسلم نے ہمیں خطبہ دیا۔ ہمیں ہمارے طریقے سکھلائے اور ہمارے لیے ہماری نماز بیان فرمائی اور فرمایا: ’’جب تم نماز کے لیے کھڑے ہو تو اپنی صفیں سیدھی کرو۔ پھر تم میں سے کوئی شخص تمھارا امام بنے۔ جب بھی وہ اللہ أکبر کہے تو تم بھی اللہ أکبر کہو اور جب وہ (ولا الضالین) کہے تو تم آمین کہو۔ اللہ تعالیٰ تمھاری دعا قبول فرمائے گا۔ پھر جب وہ اللہ اکبر کہے اور رکوع کرے تو تم بھی اللہ اکبر کہو اور رکوع کرو۔ امام تم سے پہلے رکوع کو جاتا ہے اور تم سے پہلے سر اٹھاتا ہے۔‘‘ نبی صلی اللہ علیہ وسلم نے فرمایا: ’’یہ سبقت اس سبقت کے مقابلے میں ہے۔ اور جب وہ [مع اللہ لمن حمدہ] کہے تو تم (ربنا لک الحمد] کہو۔ اللہ تعالیٰ نے اپنے نبی صلی اللہ علیہ وسلم کی زبانی فرمایا ہے کہ اللہ تعالیٰ اس شخص کی بات سنتا ہے جو اس کی حمد کرے۔ پھر جب وہ اللہ اکبر کہے اور سجدہ کرے تو تم بھی اللہ اکبر کہو اور سجدہ کرو۔ امام تم سے پہلے سجدے کو جاتا ہے اور تم سے پہلے سر اٹھاتا ہے۔‘‘ نبی صلی اللہ علیہ وسلم نے فرمایا: ’’یہ سبقت اس سبقت کے مقابلے میں ہے۔ (تمھارے اور امام کے سجدے کی مقدار میں کوئی فرق نہیں پڑے گا۔) اور جب امام قعدے میں بیٹھے تو تمھیں یوں کہنا چاہیے: [التحیات الطیبات الصلوات للہ ……… عبدہ ورسولہ] ’’تمام آداب، پاکیزہ کلمات اور دعائیں اللہ تعالیٰ کے لیے ہیں۔ اے نبی! آپ پر اللہ تعالیٰ کی طرف سے سلام رحمت اور برکتیں ہوں۔ ہم پر سلام ہو اور اللہ کے تمام نیک بندوں پر بھی۔ اور میں گواہی دیتا ہوں کہ اللہ تعالیٰ کے سوا کوئی حقیقی معبود نہیں اور میں گواہی دیتا ہوں کہ حضرت محمد (صلی اللہ علیہ وسلم) اس کے بندے اور رسول ہیں۔‘‘"}],[1281,"جابر بن عبداللہ رضی اللہ عنہم کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم ہم کو تشہد اسی طرح سکھاتے تھے، جس طرح آپ ہمیں قرآن کی سورت سکھاتے تھے«بسم اللہ وباللہ التحيات لله والصلوات والطيبات السلام عليك أيها النبي ورحمة اللہ وبركاته السلام علينا وعلى عباد اللہ الصالحين أشهد أن لا إله إلا اللہ وأن محمدا عبده ورسوله وأسأل اللہ الجنة وأعوذ به من النار» \"اللہ کے نام سے اور اسی کے واسطے سے، تمام قولی فعلی اور مالی عبادتیں اللہ ہی کے لیے ہیں، سلام ہو آپ پر اے نبی! اور اللہ کی رحمت اور برکت نازل ہو آپ پر، سلامتی ہو ہم پر اور اللہ کے نیک بندوں پر، میں گواہی دیتا ہوں کہ نہیں ہے کوئی معبود برحق سوائے اللہ کے اور یہ کہ محمد اس کے بندے اور اس کے رسول ہیں، اور میں اللہ سے جنت مانگتا ہوں، اور آگ (جہنم)سے اس کی پناہ چاہتا ہوں۔ ابوعبدالرحمٰن (امام نسائی) کہتے ہیں: ہم کسی کو نہیں جانتے جس نے اس روایت پر ایمن بن نابل کی متابعت کی ہو، ایمن ہمارے نزدیک قابل قبول ہیں، لیکن حدیث میں غلطی ہے، ہم اللہ سے توفیق کے طلب گار ہیں۔","الألباني: ضعيف",{"u2":"حضرت جابر بن عبداللہ رضی اللہ عنہ سے مروی ہے، انھوں نے فرمایا: رسول اللہ صلی اللہ علیہ وسلم ہمیں اس طرح تشہد سکھاتے تھے جیسے ہمیں قرآن مجید کی سورت سکھاتے تھے: [بسم اللہ و باللہ التحیات ……… واأعوذ بہ من النار] ’’اللہ تعالیٰ کے نام کے ساتھ اور اللہ تعالیٰ کی مدد کے ساتھ۔ تمام آداب، دعائیں اور پاکیزہ کلمات اللہ تعالیٰ کے لیے ہیں۔ اے نبی! آپ پر اللہ تعالیٰ کا سلام، رحمت اور برکتیں ہوں۔ ہم پر اور اللہ تعالیٰ کے تمام نیک بندوں پر سلام ہو۔ میں گواہی دیتا ہوں کہ اللہ تعالیٰ کے سوا کوئی حقیقی معبود نہیں اور حضرت محمد (صلی اللہ علیہ وسلم) اس کے بندے اور رسول ہیں۔ میں اللہ تعالیٰ سے جنت مانگتا ہوں اور جہنم سے اس کی پناہ چاہتا ہوں۔‘‘\nامام ابو عبدالرحمٰن نسائی رحمہ اللہ بیان کرتے ہیں کہ ہم نہیں جانتے کہ کسی دوسرے راوی نے اس روایت میں ایمن بن نابل کی موافقت کی ہو۔ ایمن ہمارے نزدیک معتبر راوی ہے، لیکن یہ روایت درست نہیں۔ اور توفیق اللہ تعالیٰ کی مدد ہی سے ملتی ہے","f2":"اس روایت میں تشہد کے آغاز میں [بسم اللہ و باللہ] کا اضافہ ہے جو کسی اور راوی نے بیان نہیں کیا۔ اسی طرح آخر میں جنت و جہنم والے جملے بھی صرف اسی روایت میں ہیں اور کوئی راوی اس میں موافقت نہیں کرتا، لہٰذا یہ اضافے غریب اور شاذ ہیں، اس لیے معتبر نہیں، اگرچہ ایمن بن نابل ثقہ راوی ہے۔ ثقہ راوی کی روایت بھی اسی وقت معتبر ہوگی جب وہ کثیر ثقات یا اپنے سے اوثق (زیادہ ثقہ) راوی کے خلاف نہ ہو۔ بہرحال یہ روایت ضعیف ہے۔ (دیکھیے بعینہٖ یہی حدیث نمبر ۱۱۷۶ میں)"}],[1282,"عبداللہ بن مسعود رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"اللہ تعالی کے کچھ فرشتے ہیں جو زمین میں گھومتے رہتے ہیں، وہ مجھ تک میرے امتیوں کا سلام پہنچاتے ہیں\"۔","الألباني: صحيح",{"u2":"حضرت عبداللہ بن مسعود ری اللہ عنہ سے روایت ہے، رسول اللہ صلی اللہ علیہ وسلم بیان کرتے ہیں کہ ’’تحقیق اللہ تعالیٰ نے کچھ فرشتے مقرر کر رکھے ہیں جو زمین میں ہر وقت چلتے پھرتے رہتے ہیں۔ وہ مجھے میری امت کی طرف سے سلام پہنچاتے ہیں۔‘‘","f2":"(۱)نماز میں آپ پر سلام پڑھنا فرض ہے، آگے پیچھے بھی آپ پر سلام پڑھنا ایک بہت بڑی فضیلت ہے اور یہی مرتبہ آپ پر صلاۃ (درود) کا ہے کیونکہ یہ قرآنی حکم ہے: (یایھا الذین امنوا صلوا علیہ وسلموا تسلیما) (الأحزاب ۵۶:۳۳) صلی اللہ علیہ وسلم۔ (۲) نبیٔ اکرم صلی اللہ علیہ وسلم پر درود کے علاوہ اکیلا سلام پڑھنا بھی درست ہے، یعنی اگر کوئی شخص صلی اللہ علیہ یا علیہ السلام اکیلا اکیلا کہہ دے تو جائز ہے۔ (۳) اس حدیث مبارکہ میں نبیٔ اکرم صلی اللہ علیہ وسلم پر کثرت سے سلام پڑھنے کی ترغیب ہے۔ (۴) اس حدیث مبارکہ سے نبیٔ اکرم صلی اللہ علیہ وسلم کا بلند مرتبہ اور عزت و عظمت واضح ہے کہ اللہ تعالیٰ نے فرشتوں کی ڈیوٹی لگا رکھی ہے کہ جو آپ پر سلام پڑھے، فرشتے اس کا سلام آپ تک پہنچائیں۔ (۵) اس شخص کی فضیلت بھی اس سے ثابت ہوتی ہے جو آپ صلی اللہ علیہ وسلم پر سلام پڑھتا ہے اور اس کا سلام نبیٔ اکرم صلی اللہ علیہ وسلم تک پہنچایا جاتا ہے، پھر آپ صلی اللہ علیہ وسلم بنفس نفیس اس کا جواب دیتے ہیں جیسا کہ ابوہریرہ رضی اللہ عنہ فرماتے ہیں، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’جو شخص بھی مجھے سلام کہتا ہے، اللہ مجھ پر میری روح لوٹا دیتا ہے اور میں اس کے سلام کا جواب دیتا ہوں۔‘‘ (سنن أبي داود، المناسک، حدیث: ۲۰۴۱) یہ حدیث حسن درجے کی ہے۔ ’’روح لوٹانے‘‘ کی کئی ایک تاویلات کی گئی ہیں مگر اول و آخر یہی ہے کہ یہ عالم برزخ کا معاملہ ہے، اسے دنیا کی زندگی پر قیاس کرنا درست نہیں، علاوہ ازیں یہ متشابہات میں سے ہے۔ ہم کوئی اطمینان بخش تفصیل و توجیہ کرنے سے قاصر ہیں۔ واللہ أعلم۔"}],[1283,"ابوطلحہ رضی اللہ عنہ سے روایت ہے کہ ایک دن رسول اللہ صلی اللہ علیہ وسلم تشریف لائے، آپ کے چہرے پر خوشی کے آثار تھے، ہم نے عرض کیا: ہم آپ کے چہرے پر خوشی کے آثار دیکھ رہے ہیں؟ آپ نے فرمایا: \"یہ اس لیے کہ میرے پاس فرشتہ آیا اور اس نے کہا: اے محمد! آپ کا رب کہتا ہے: کیا آپ کے لیے یہ خوشی کی بات نہیں کہ جو کوئی آپ پر ایک بار صلاۃ (درود) بھیجے گا، تو میں اس پر دس بار صلاۃ (درود) بھیجوں گا ۱؎، اور جو کوئی آپ پر ایک بار سلام بھیجے گا، میں اس پر دس بار سلام بھیجوں گا\"۔\n§وضاحت\n۱؎: نبی اکرم صلی اللہ علیہ وسلم پر اللہ تعالی کے صلاۃ :(درود ) بھیجنے کا مطلب آپ صلی اللہ علیہ وسلم کی مدح و ستائش اور تعظیم کرنا ہے، اور فرشتوں وغیرہ کے صلاۃ :(درود ) بھیجنے کا مطلب اللہ تعالی سے اس مدح وستائش اور تعظیم میں طلب زیادتی ہے۔","الألباني: حسن",{"u2":"حضرت ابو طلحہ رضی اللہ عنہ سے منقول ہے کہ رسول اللہ صلی اللہ علیہ وسلم ایک دن تشریف لائے جب کہ آپ کے چہرۂ انور پر سرور جھلک رہا تھا۔ ہم نے کہا: ہم آپ کے چہرۂ اقدس پر خوشی کے آثار دیکھ رہے ہیں۔ آپ نے فرمایا: ’’میرے پاس ایک فرشتہ آیا اور اس نے کہا: ’’اے محمد! تحقیق آپ کا رب تعالیٰ فرماتا ہے: کیا آپ کو یہ بات پسند نہیں کہ جو شخص بھی آپ پر درود پڑھے گا، میں اس پر دس دفعہ رحمت کروں گا؟ اور جو بھی آپ پر سلام کہے گا، میں اس پر دس بار سلام نازل کروں گا۔‘‘","f2":"(۱) اللہ! اللہ! کس قدر فضیلت ہے نبیٔ پاک صلی اللہ علیہ وسلم پر درود سلام پڑھنے کی کہ اللہ تعالیٰ خوش ہوکر اس بندے پر اپنی شان کے مطابق دس رحمتیں اور دس بار سلام نازل فرماتا ہے۔ نبی صلی اللہ علیہ وسلم کی رضامندی اور شفاعت مستزاد ہے۔ درود سے مراد نبیٔ کامل کے لیے رحمت کی دعا کرنا اور سلام سے مراد آپ پر سلامتی کی دعا کرنا ہے۔ خصوصی مرتبے کی وجہ سے مخصوص نام درود و سلام رکھ دیا گیا۔ یہ دعائیں بھی نتیجتاً اپنے لیے ہیہیں کیونکہ آپ کے لیے دعا دراصل امت کے لیے ہے۔ امت کی شان بڑھے گی۔ (۲) اس حدیث مبارکہ میں اللہ تعالیٰ کے اس امت پر عظیم احسان کا تذکرہ ہے کہ جو شخص ایک مرتبہ نبی صلی اللہ علیہ وسلم پر درود بھیجتا ہے، اللہ تعالیٰ اس پر دس رحمتیں بھیجتا ہے اور جو ایک مرتبہ آپ پر سلام پڑھتا ہے اللہ تعالیٰ اس پر دس مرتبہ سلام بھیجتا ہے۔ (۳) اللہ کا انعام اور فضل پاکر خوش ہونا چاہیے اور چہرے پر خوشی کے واضح آثار نظر آنے چاہئیں"}],[1284,"فضالہ بن عبید رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے ایک آدمی کو نماز میں دعا کرتے ہوئے سنا، اس نے نہ تو اللہ کی بزرگی بیان کی، اور نہ ہی نبی اکرم صلی اللہ علیہ وسلم پر صلاۃ و سلام (درود) بھیجا، تو رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"اے نمازی! تم نے جلد بازی کر دی\"، پھر رسول اللہ صلی اللہ علیہ وسلم نے اسے سکھایا (کہ کس طرح دعا کی جائے) اور اسی طرح رسول اللہ صلی اللہ علیہ وسلم نے ایک آدمی کو نماز کی حالت میں اللہ کی بزرگی اور حمد بیان کرتے، اور نبی اکرم صلی اللہ علیہ وسلم پر صلاۃ و سلام (درود) بھیجتے سنا تو فرمایا: \"آپ دعا کریں آپ کی دعا قبول کی جائے گی، اور مانگو آپ کو دیا جائے گا\"۔","الألباني: صحيح",{"u2":"حضرت فضالہ بن عبید رضی اللہ عنہ بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے ایک آدمی آدمی کو نماز میں دعا کرتے سنا جس نے نہ اللہ تعالیٰ کی حمد بیان کی اور نہ نبی صلی اللہ علیہ وسلم پر درود پڑھا تو رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’اے نمازی! تو نے جلدی کی ہے۔‘‘ پھر رسول اللہ صلی اللہ علیہ وسلم نے لوگوں کو دعا کا طریقہ سکھایا، پھر آپ نے ایک آدمی کو دعا کرتے ہوئے سنا، اس نے پہلے اللہ تعالیٰ کی بزرگی اور تعریف بیان کی، پھر نبی صلی اللہ علیہ وسلم پر درود پڑھا۔ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’اب تو دعا کر، قبول ہوگی اور مانگ تجھے دیا جائے گا۔‘‘","f2":"(۱) نماز کے آخری تشہد میں درود پڑھنے پر تو سب امت کا اتفاق ہے، البتہ وجوب و استحباب میں اختلاف ہے۔ محدثین (عمومی طور پر) نماز میں درود کو واجب سمجھتے ہیں کیونکہ صلاۃ کا ساتھی سلام سب کے نزدیک واجب ہے تو درود بھی واجب ہوگا کیونکہ دونوں کا حکم اکٹھا ہے۔ (صلوا علیہ و سلموا تسلیما) (الأحزاب ۵۶:۳۳) نیز آپ نے اسے تشہد کی طرح سکھلایا ہے جیسے کہ اگلی روایت میں صراحت ہے: [أمیرنا ان نصلي علیک] نیز مطلقاً صلاۃ و سلام تو سب کے نزدیک فرض ہے کیونکہ یہ قرآنی حکم ہے۔ نماز کے علاوہ اس فرض کے لیے کون سا موقع مناسب ہوگا؟ احناف اور کچھ موالک اسے فرض اور واجب نہیں سمجھتے۔ یہ موقف مرجوح ہے۔ احتیاط پہلے مسلک ہی میں ہے کہ اسے کسی حال میں چھوڑا نہ جائے۔ (۲) نماز کے علاوہ عام دعا میں بھی پہلے حمد و ثنا کی جائے پھر درود پڑھا جائے اور پھر دعا کی جائے۔ (۳) مذکورہ آیت قرآنی (صلوا علیہ………) کے عموم سے علمائ کے ایک گروہ نے یہ بھی استدلال کیا ہے کہ تشہد اول میں بھی درود شریف پڑھا جائے اور سنن نسائی کی ایک روایت میں بھی نفلی نماز کے تشہد اول میں نبی صلی اللہ علیہ وسلم سے درود پڑھنے کا ثبوت موجود ہے۔ (سنن النسائي مع التعلیقات السلفیۃ، قیام اللیل، کیف الوتر بتسح، حدیث: ۱۱۷۲۱/۲۰۲۔ مزید تفصیل کے لیے ملاحظہ ہو: ’’احسن البیان‘‘ مطبوعہ الریاض، سعودی عرب، سورۃ الاحزاب ۵۶:۳۳ کے ذیل میں) (۴) نماز میں دعا کرنا مشروع ہے۔ (۵) دعا کرنے سے پہلے اللہ تعالیٰ کی حمد و ثنا بیان کرنا اور نبیٔ اکرم صلی اللہ علیہ وسلم پر درود پڑھنا قبولیت دعا کے اسباب میں سے ہے، لہٰذا دعا کرنے والے کو چاہیے کہاپنی حاجت برآری کے لیے پہلے اللہ کی حمد بیان کرے، پھر نبیٔ اکرم صلی اللہ علیہ وسلم پر درود پڑھے، پھر جو چاہے مانگے، اللہ تعالیٰ اس کی دعا قبول کرے گا۔ إن شاء اللہ تعالی"}],[1285,"ابومسعود انصاری رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم سعد بن عبادہ رضی اللہ عنہ کی بیٹھک میں ہمارے پاس تشریف لائے، تو آپ سے بشر بن سعد رضی اللہ عنہ نے عرض کیا: اللہ کے رسول! اللہ نے ہمیں آپ پر صلاۃ (درود) بھیجنے کا حکم دیا ہے تو ہم آپ پر کیسے صلاۃ (درود) بھیجیں؟ رسول اللہ صلی اللہ علیہ وسلم خاموش رہے یہاں تک کہ ہماری یہ خواہش ہونے لگی کہ کاش انہوں نے آپ سے نہ پوچھا ہوتا، پھر آپ نے فرمایا: کہو «اللہم صل على محمد وعلى آل محمد كما صليت على آل إبراهيم وبارك على محمد وعلى آل محمد كما باركت على آل إبراهيم في العالمين إنك حميد مجيد» \"اے اللہ! محمد اور آل محمد پر اسی طرح صلاۃ (درود) بھیج جس طرح تو نے آل ابراہیم پر صلاۃ (درود) بھیجا ہے، اور برکتیں نازل فرما محمد پر اور آل محمد پر اسی طرح جیسے تو نے آل ابراہیم پر تمام عالم میں برکتیں نازل فرمائی ہیں، بلاشبہ تو ہی تعریف اور بزرگی کے لائق ہے) اور سلام بھیجنا تو تم جانتے ہی ہو\"۔","الألباني: صحيح",{"u2":"حضرت ابو مسعود انصاری رضی اللہ عنہ بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم ہمارے پاس حضرتسعد بن عباد رضی اللہ عنہ کی بیٹھک میں تشریف لائے۔ بشیر بن سعد رضی اللہ عنہ نے عرض کیا: اے اللہ کے رسول! اللہ تعالیٰ نے ہمیں آپ پر درود پڑھنے کا حکم دیا ہے۔ ہم آپ پر کیسے درود پڑھیں؟ رسول اللہ صلی اللہ علیہ وسلم خاموش ہوگئے حتی کہ ہم نے تمنا کی کہ وہ آپ سے نہ پوچھتے۔ کچھ دیر کے بعد آپ نےفرمایا: ’’تم یوں کہو: [اللھم! صلی علی محمد……… علی آل ابراھیم فی العلمین انک حمید مجید] ’’اے اللہ! محمد (صلی اللہ علیہ وسلم) اور ان کی آل پر خصوصی رحمت فرما جیسا کہ تو نے ابراہیم (علیہ السلام) کی آل پر خصوصی رحمت فرمائی۔ اور محمد (صلی اللہ علیہ وسلم) اور آپ کی آل پر برکات نازل فرما جیسا کہ تو نے ابراہیم (علیہ السلام) کی آل پر تمام جہانوں میں برکتیں نازل فرمائیں۔ یقیناً تو ہی قابل تعریف اور بزرگی والا ہے۔‘‘ اور سلام اس طرح پڑھو جیسے تمھیں سکھایا گیا ہے۔","f2":"(۱) ’’حکم دیا گیا ہے۔‘‘ صحابہ کا آپ سے درود کے بارے میں اس طرح سوال کرنا اور سوال و جواب میں سلام کا حوالہ اس بات کی دلیل ہے کہ یہ سوال نماز کے بارے میں تھا کیونکہ سلام تو نماز ہی میں واجب ہے۔ (۲) آل سے مراد آپ کے مسلم قریبی رشتہ دار یا متبعین، یعنی صحابہ یا کلامت ہے۔ یہ لفظ ان تینوں معانی میں استعمال ہوا ہے۔ (۳) در ود میںحضرت ابراہیم علیہ السلام کا حوالہ یا تو اس لیے ہے کہ وہ آپ کے جد امجد ہیں یا اس کے لیے کہ تمام آسمانی مذاہب (اسلام، یہودیت، عیسائیت) انھیں اپنا امام مانتے ہیں۔ (۴) آپ نے جو بھی درود سکھایا اس میں حضرت ابراہیم علیہ السلام کا حوالہ ضرور ہے، اس لیے جمیع امت کا اتفاق ہے کہ ہر قسم کی نماز میں درود ابراہیمی ہی پڑھا جائے گا۔ نماز کے علاوہ بھی ابراہیمی درود ہی بہتر ہے اگرچہ کوئی اور درود بھی، جو حدیث سے ثابت ہو، پڑھا جا سکتا ہے۔ (۵) تمام جہانوں سے مراد دنیا و آخرت دونوں ہیں۔ (۶) اس حدیث مبارکہ سے نبی صلی اللہ علیہ وسلم کے عجز و انکسار اور خصائل حمیدہ کا پتہ چلتا ہے، آپ اپنے صحابۂ کرام رضی اللہ عنہم کا احترام کرتے تھے اور ان سے اپنائیت کا اظہار کرتے ہوئے ان کے پاس تشریف لے جاتے تھے۔ (۷) صحابۂ کرام رضی اللہ عنہم کو اگر کوئی شرعی مسئلہ درپیش ہوتا تو وہ اپنی طرف سے شریعت سازی نہیں کرتے تھے بلکہ رسول اللہ صلی اللہ علیہ وسلم کی طرف رجوع کرتے تھے، اس لیے ہمیں بھی چاہیے کہ اگر ہمیں کوئی مسئلہ درپیش ہو تو قرآن و سنت سے رہنمائی لیں، اپنے اجتہادات اور قیاس آرائیوں کی طرف سبقت نہ کریں۔ (۸) نبیٔ اکرم صلی اللہ علیہ وسلم سے اگر کوئی سائل سوال کرتا اور اس کا جواب ابھی تک اللہ نے آپ کو بتایا نہ ہوتا تو آپ وحی کا انتظار کرتے تھے جیسا کہ اللہ تعالیٰ نے فرمایا: (وما ینطق عن الھویo ان ھو الا وحی یوحیo) (النجم ۳:۵۳، ۴) ’’اور وہ (اپنی) خواہش سے نہیں بولتا۔ وہ وحی ہی تو ہے جو اس کی طرف بھیجی جاتی ہے۔‘‘ (۹) اس حدیث مبارکہ سے دوسرے انبیاء پر صلاۃ (درود) پڑھنا ثابت ہوتا ہے"}],[1286,"ابومسعود انصاری رضی اللہ عنہ کہتے ہیں کہ نبی اکرم صلی اللہ علیہ وسلم سے عرض کیا گیا: ہمیں آپ پر صلاۃ (درود) و سلام بھیجنے کا حکم دیا گیا ہے، رہا سلام تو اسے ہم جان چکے ہیں، مگر ہم آپ پر صلاۃ (درود) کس طرح بھیجیں؟ آپ نے فرمایا: \"کہو «اللہم صل على محمد كما صليت على آل إبراهيم اللہم بارك على محمد كما باركت على آل إبراهيم» \"اے اللہ! محمد پر تو اسی طرح صلاۃ (درود) و رحمت بھیج جس طرح تو نے آل ابراہیم پر بھیجا ہے، اے اللہ! محمد پر تو اسی طرح برکتیں نازل فرما جس طرح تو نے آل ابراہیم پر برکتیں نازل فرمائی ہیں\"۔","الألباني: صحيح الإسناد",{"u2":"حضرت ابو مسعود انصاری رضی اللہ عنہ سے روایت ہے کہ نبیٔ اکرم صلی اللہ علیہ وسلم سے کہا گیا: ہمیں حکم دیا گیا ہے کہ ہم آپ پر درود و سلام پڑھیں، سلام تو ہم جان چکے ہیں درود کیسے پڑھیں؟ آپ نے فرمایا: ’’تم کہو: [اللھم! صلی علی محمد ……… علی آل إبراہیم] ’’اے اللہ! محمد (صلی اللہ علیہ وسلم) پر خصوصی رحمتیں فرما جیسے تو نے آل ابراہیم پر رحمتیں فرمائیں۔ اے اللہ! محمد (صلی اللہ علیہ وسلم) پر برکتیں نازل فرما جس طرح تو نے ابراہیم (علیہ السلام) کی آل پر برکتیں نازل فرمائیں۔‘‘"}],[1287,"کعب بن عجرہ رضی اللہ عنہ کہتے ہیں کہ ہم نے عرض کیا: اللہ کے رسول! آپ پر سلام بھیجنا تو ہم جان چکے ہیں، صلاۃ (درود) کیسے بھیجیں؟ آپ نے فرمایا: اس طرح کہو: «اللہم صل على محمد وعلى آل محمد كما صليت على آل إبراهيم إنك حميد مجيد اللہم بارك على محمد وعلى آل محمد كما باركت على آل إبراهيم إنك حميد مجيد» \"اے اللہ! محمد اور آل محمد پر تو اسی طرح صلاۃ (درود) بھیج جیسے تو نے آل ابراہیم پر بھیجا ہے، یقیناً تو تعریف اور بزرگی کے لائق ہے، اے اللہ! محمد اور آل محمد پر اسی طرح برکتیں نازل فرما جس طرح تو نے آل ابراہیم پر نازل فرمائی ہیں، یقیناً تو حمید و مجید یعنی تعریف اور بزرگی کے لائق ہے\"۔ ابن ابی لیلی نے کہا: اور ہم لوگ «وعلينا معهم» \"اور ان لوگوں کے ساتھ ہم پر بھی\" کہتے تھے۔ ابوعبدالرحمٰن (نسائی) کہتے ہیں: یہ سند ہمارے شیخ قاسم نے ہم سے اپنی کتاب سے بیان کی ہے، اور یہ غلط ہے ۱؎۔\n§وضاحت\n۱؎: اس کی وجہ اگلی روایت میں امام نسائی خود بیان کر رہے ہیں۔","الألباني: صحيح",{"u2":"حضرت کعب بن عجزہ رضی اللہ عنہ بیان کرتے ہیں کہ ہم نے کہا: اے اللہ کے رسول! (تشہد میں) آپ پر سلام پڑھنا تو ہم جان چکے ہیں، لیکن درود کیسے پڑھیں؟ آپ نے فرمایا: ’’تم یوں کہو: [اللھم! صل علی محمد ……… حمید مجید] ’’اے اللہ!محمد (صلی اللہ علیہ وسلم) اور آپ کی آل پر رحمتیں نازل فرما جیسے تو نے ابراہیم (علیہ السلام) کی آل پر رحمتیں نازل فرمائی ہیں۔ یقیناً تو تعریف اور بزرگی والا ہے۔ اے اللہ! محمد (صلی اللہ علیہ وسلم) اور آپ کی آل پر برکتیں نازل فرما جس طرح تو نے ابراہیم (علیہ السلام) کی آل پر برکتیں نازل فرمائیں۔ یقیناً تو تعریف اور بزرگی والا ہے۔‘‘\n(راوی) ابن ابی لیلیٰ نے کہا: ہم ساتھ ہی یہ بھی کہتے تھے: ان کے ساتھ ساتھ ہم پر بھی (رحمتیں اور برکتیں نازل فرما۔)\nامام ابو عبدالرحمٰن (نسائی) رحمہ اللہ بیان کرتے ہیں کہ یہ حدیث بھی ہمارے استاد گرامی (قاسم بن زکریا) نے اپنی کتاب سے دیکھ کر بیان کی تھی مگر اس کی سند غلط ہے","f2":"(۱) اس غلطی کی وضاحت آئندہ روایت میں آ رہی ہے کہ سلیمان کے استاد عمرو بن مرہ نہیں بلکہ حکم ہیںجیسا کہ حدیث: ۱۲۸۹ کی سند سے صاف معلوم ہو رہا ہے۔ لطیفہ یہ ہے کہ یہ روایت بھی قاسم بن زکریا ہی سے ہے۔ گویا انھوں نے ایک دفعہ سلیمان کے استاد کا نام عمرو بن مرہ بتایا، ایک دفعہ حکم۔ لیکن پہلی سند غلط ہے دوسری صحیح ہے کیونکہ اس کی تائید دوسرے راوی بھی کرتے ہیں، مثلاً: (دیکھیے حدیث: ۱۲۹۰ کی سند) واللہ أعلم۔ (۲) یہ آخری الفاظ انھوں نے بطور دعا مزید کہے جن کا اصل حدیث سے کوئی تعلق نہیں، یعنی یہ درود کا حصہ نہیں۔"}],[1288,"کعب بن عجرہ رضی اللہ عنہ کہتے ہیں کہ ہم نے عرض کیا: اللہ کے رسول! آپ پر سلام بھیجنے کو ہم جان چکے ہیں مگر آپ پر صلاۃ (درود) کس طرح بھیجیں؟ تو آپ نے فرمایا: کہو \" «اللہم صل على محمد وعلى آل محمد كما صليت على إبراهيم وآل إبراهيم إنك حميد مجيد وبارك على محمد وعلى آل محمد كما باركت على إبراهيم وآل إبراهيم إنك حميد مجيد» \"اے اللہ! تو صلاۃ (درود) بھیج محمد اور آل محمد پر اسی طرح جس طرح تو نے ابراہیم اور آل ابراہیم پر بھیجا ہے، یقیناً تو حمید و مجید یعنی قابل تعریف اور بزرگ ہے، اور برکتیں نازل فرما محمد اور آل محمد پر اسی طرح جیسے تو نے ابراہیم اور آل ابراہیم پر نازل فرمائی ہیں، یقیناً تو حمید و مجید یعنی قابل تعریف اور بزرگ ہے\"۔ عبدالرحمٰن بن ابی لیلی کہتے ہیں: اور ہم «وعلينا معهم» \"اور ان لوگوں کے ساتھ ہم پر بھی\" بھی کہتے تھے۔ ابوعبدالرحمٰن نسائی کہتے ہیں: یہ سند اس سے پہلے والی سے زیادہ قرین صواب ہے (یعنی \"عمرو\" کی جگہ \"حکم\" کا ہونا) اور ہم قاسم کے علاوہ کسی اور کو نہیں جانتے جس نے عمرو بن مرہ کا ذکر کیا ہو، «واللہ اعلم» ۱؎۔\n§وضاحت\n۱؎: اگلی سند میں بھی \" حکم \" ہی ہے۔","الألباني: صحيح",{"u2":"حضرت کعب بن عجرہ رضی اللہ عنہ سے مروی ہے، وہ کہتے ہیں: ہم نے کہا: اے اللہ کے رسول! آپ پر سلام تو ہم جان چکے ہیں لیکن آپ پر درود کیسے ہے؟ آپ نے فرمایا: ’’تم کہو: [اللھم! صلی علی محمد ……… حمید مجید] ’’اے اللہ! محمد (صلی اللہ علیہ وسلم) اور آپ کی آل پر خصوصی رحمت نازل فرما جیسے تو نےحضرت ابراہیم (علیہ السلام) اور ان کی آل پر رحمت نازل فرمائی۔ یقیناً تو تعریف اور بزرگی والا ہے۔ اور محمد (صلی اللہ علیہ وسلم) اور آپ کی آل پر برکتیں نازل فرما جس طرح تو نے ابراہیم (علیہ السلام) اور ان کی آل پر نازل فرمائیں۔ یقیناً تو تعریف اور بزرگی والا ہے۔‘‘\n(راوی) عبدالرحمن نے کہا: ہم یہ بھی کہتے تھے: اور ان کے ساتھ ساتھ ہم پر بھی (رحمتیں اور برکتیں نازل فرما۔)\nامام ابو عبدالرحمن (نسائی) رحمہ اللہ بیان کرتے ہیں کہ یہ سند پہلی سند کے مقابلے میں زیادہ درست ہے۔ ہم نہیں جانتے کہ حضرت قاسم کے علاوہ کسی نے اس حدیث میں عمرو بن مرہ کا ذکر کیا ہو۔ واللہ أعلم"}],[1289,"ابن ابی لیلی کہتے ہیں کہ مجھ سے کعب بن عجرہ رضی اللہ عنہ نے کہا کہ کیا میں تمہیں ایک ہدیہ نہ دوں، ہم نے رسول اللہ صلی اللہ علیہ وسلم سے عرض کیا: اللہ کے رسول! ہم آپ پر سلام بھیجنے کا طریقہ جان چکے ہیں، مگر ہم آپ پر صلاۃ (درود) کیسے بھیجیں؟ تو آپ نے فرمایا: \"کہو «اللہم صل على محمد وآل محمد كما صليت على آل إبراهيم إنك حميد مجيد اللہم بارك على محمد وآل محمد كما باركت على آل إبراهيم إنك حميد مجيد»\"اے اللہ! درود بھیج محمد اور آل محمد پر جیسے تو نے آل ابراہیم پر بھیجا ہے یقیناً تو حمید و مجید یعنی قابل تعریف اور بزرگی والا ہے، اے اللہ! برکتیں نازل فرما محمد پر اور آل محمد پر جیسے تو نے آل ابراہیم پر نازل فرمائی ہیں، یقیناً تو حمید و مجید یعنی قابل تعریف اور بزرگی والا ہے\"۔","الألباني: صحيح",{"u2":"حضرت ابن ابی لیلیٰ سے روایت ہے، انھوں نے کہا کہ حضرت کعب بن عجرہ رضی اللہ عنہ نے مجھ سے فرمایا: میں تجھے تحفہ نہ دوں؟ (اوروہ یہ ہے کہ) ہم نے کہا: اے اللہ کے رسول! آپ پر سلام پڑھنا تو ہم جان چکے ہیں لیکن آپ پر درود کیسے پڑھیں؟ آپ نے فرمایا: ’’تم کہو [اللھم! صلی علی محمد ……… حمید مجید] ’’اے اللہ! محمد (صلی اللہ علیہ وسلم) اور آپ کی آل پر خصوصی رحمتیں نازل فرما جس طرح تو نے ابراہیم (علیہ السلام) کی آل پر رحمتیں نازل فرمائیں۔ یقیناً تو تعریف اور بزرگی والا ہے۔ اے اللہ! محمد (صلی اللہ علیہ وسلم) اور آپ کی آل پر برکتیں نازل فرما جس طرح تو نے ابراہیم (علیہ السلام) کی آل پر برکتیں نازل فرمائیں۔ یقیناً تو تعریف اور بزرگی والا ہے۔‘‘"}],[1290,"طلحہ رضی اللہ عنہ کہتے ہیں کہ ہم نے عرض کیا: اللہ کے رسول! آپ پر صلاۃ (درود و رحمت) کیسے بھیجا جائے، تو آپ نے فرمایا: کہو «اللہم صل على محمد وعلى آل محمد كما صليت على إبراهيم وآل إبراهيم إنك حميد مجيد وبارك على محمد وعلى آل محمد كما باركت على إبراهيم وآل إبراهيم إنك حميد مجيد» \"اے اللہ! صلاۃ (درود) بھیج محمد اور آل محمد پر ایسے ہی جیسے تو نے ابراہیم اور آل ابراہیم پر بھیجا، بلاشبہ تو حمید و مجید یعنی قابل تعریف اور بزرگی والا ہے، اور برکتیں نازل فرما محمد اور آل محمد پر، ایسے ہی جیسے تو نے ابراہیم اور آل ابراہیم پر نازل فرمائی ہیں، بلاشبہ تو حمید و مجید یعنی لائق تعریف اور بزرگی والا ہے\"۔","الألباني: صحيح",{"u2":"حضرت طلحہ رضی اللہ عنہ بیان کرتے ہیں کہ ہم نے کہا: اے اللہ کے رسول! آپ پر درود کیسے پڑھا جائے؟ آپ نے فرمایا: ’’تم کہو: [اللھم! صلی علی محمد ___ حمید مجید] ’’اے اللہ! محمد (صلی اللہ علیہ وسلم) اور آپ کی آل پر خصوصی رحمتیں نازل فرما جس طرح تو نے ابراہیم (علیہ السلام) اور ان کی آل پر رحمتیں نازل فرمائیں۔ یقیناً تو تعریف اور بزرگی والا ہے۔ اور محمد (صلی اللہ علیہ وسلم) اور آپ کی آل پر برکتیں نازل فرما جس طرح تو نے ابراہیم (علیہ السلام) اور ان کی آل پر برکتیں نازل فرمائیں۔ یقیناً تو تعریف اور بزرگی والا ہے۔‘‘"}],[1291,"طلحہ رضی اللہ عنہ کہتے ہیں کہ ایک آدمی نبی اکرم صلی اللہ علیہ وسلم کے پاس آیا، اور اس نے عرض کیا: اللہ کے نبی! ہم آپ پر صلاۃ (درود) کس طرح بھیجیں؟ آپ نے فرمایا: \"کہو: «اللہم صل على محمد وعلى آل محمد كما صليت على إبراهيم إنك حميد مجيد وبارك على محمد وعلى آل محمد كما باركت على إبراهيم إنك حميد مجيد» \"اے اللہ! صلاۃ (درود) بھیج محمد پر اور آل محمد پر ویسے ہی جیسے تو نے ابراہیم پر بھیجا ہے، بلاشبہ تو حمید و مجید یعنی لائق تعریف اور بزرگی والا ہے، اور برکتیں نازل فرما محمد اور آل محمد پر ویسے ہی جیسے تو نے ابراہیم پر نازل فرمائی ہیں، بلاشبہ تو حمید و مجید یعنی لائق تعریف اور بزرگی والا ہے\"۔","الألباني: صحيح",{"u2":"حضرت طلحہ رضی اللہ عنہ سے روایت ہے کہ ایک آدمی نبی (صلی اللہ علیہ وسلم) کے پاس آیا اور کہنے لگا: اے اللہ کے نبی! ہم آپ پر درود کیسے پڑھیں؟ آپ نے فرمایا: ’’تم کہو: [اللھم! صلی علی محمد ___ حمید مجید] ’’اے اللہ! محمد (صلی اللہ علیہ وسلم) اور آپ کی آل پر خصوصی رحمتیں نازل فرما جس طرح تو نے ابراہیم (علیہ السلام) اور ان کی آل پر رحمتیں نازل فرمائیں۔ یقیناً تو تعریف اور بزرگی والا ہے۔ اور محمد (صلی اللہ علیہ وسلم) اور آپ کی آل پر برکتیں نازل فرما جس طرح تو نے ابراہیم (علیہ السلام) اور ان کی آل پر برکتیں نازل فرمائیں۔ یقیناً تو تعریف اور بزرگی والا ہے۔‘‘"}],[1292,"موسی بن طلحہ کہتے ہیں کہ میں نے زید بن خارجہ رضی اللہ عنہ سے پوچھا، وہ کہتے ہیں کہ میں نے رسول اللہ صلی اللہ علیہ وسلم سے پوچھا، تو آپ نے فرمایا: \"مجھ پر صلاۃ(درود و رحمت) بھیجو، اور دعا میں کوشش کرو، اور کہو: «اللہم صل على محمد وعلى آل محمد» \"اے اللہ! صلاۃ (درود و رحمت) بھیج محمد پر اور آل محمد پر\"۔","الألباني: صحيح",{"u2":"حضرت موسیٰ بن طلحہ بیان کرتے ہیں کہ میں نے حضرت زید بن خارجہ رضی اللہ عنہ سے پوچھا، انھوں نے فرمایا: میں نے رسول اللہ صلی اللہ علیہ وسلم سےپوچھا تھا تو آپ نے فرمایا تھا: ’’مجھ پر درود پڑھو اور خوب کوشش سے دعا کرو اور کہو:[اللھم! صلی علی محمد و علی آل محمد] ’’اے اللہ!محمد (صلی اللہ علیہ وسلم) اور آل محمد پر خصوصی رحمتیں نازل فرما۔‘‘"}],[1293,"ابو سعید خدری رضی اللہ عنہ کہتے ہیں کہ ہم نے عرض کیا: اللہ کے رسول! آپ پر سلام بھیجنے کا طریقہ تو ہم جان چکے ہیں، پر مگر آپ پر صلاۃ (درود و رحمت) کیسے بھیجیں؟ آپ صلی اللہ علیہ وسلم نے فرمایا: \"اس طرح کہو: «اللہم صل على محمد عبدك ورسولك كما صليت على إبراهيم وبارك على محمد وآل محمد كما باركت على إبراهيم» \"اے اللہ! درود و رحمت بھیج اپنے بندے اور رسول محمد پر جس طرح تو نے ابراہیم پر بھیجا ہے، اور برکتیں نازل فرما محمد اور آل محمد پر ویسے ہی جیسے تو نے ابراہیم پر نازل فرمائی ہیں\"۔","الألباني: صحيح",{"u2":"حضرت ابو سعید خدری رضی اللہ عنہ سے مروی ہے، وہ فرماتے ہیں: ہم نے کہا: اے اللہ کے رسول! آپ پر سلام پڑھنا تو ہم نے جان لیا ہے مگر آپ پر درود کیسے ہے؟ آپ نے فرمایا: ’’تم کہو [اللھم! صلی علی محمد عبدک ……… علی ابراھیم] ’’اے اللہ! اپنے بندے اور رسول محمد (صلی اللہ علیہ وسلم) پر خصوصی رحمت نازل فرما، جس طرح تو نے ابراہیم (علیہ السلام) پر رحمت نازل فرمائی۔ اور محمد (صلی اللہ علیہ وسلم) اور آل محمد (صلی اللہ علیہ وسلم) پر برکت نازل فرما جس طرح تو نے ابراہیم (علیہ السلام) پر برکت نازل فرمائی۔‘‘"}],[1294,"ابو حمید ساعدی رضی اللہ عنہ کہتے ہیں کہ ان لوگوں (صحابہ) نے عرض کیا: اللہ کے رسول! ہم آپ پر صلاۃ (درود و رحمت) کیسے بھیجیں؟ تو رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"کہو: «اللہم صل على محمد وأزواجه وذريته»، یہ صرف حارث کی روایت میں ہے «كما صليت على آل إبراهيم وبارك على محمد وأزواجه وذريته»۔ یہ دونوں کی روایت میں ہے «كما باركت على آل إبراهيم إنك حميد مجيد»۔ ابوعبدالرحمٰن (نسائی) کہتے ہیں: قتیبہ نے اس حدیث کو مجھ سے دو بار بیان کیا، اور شاید کہ ان سے کچھ حصہ اس حدیث کا چھوٹ گیا ہے۔","الألباني: صحيح",{"u2":"حضرت ابوحمید ساعدی رضی اللہ عنہ سے روایت ہے، لوگوںنے کہا: اے اللہ کے رسول! ہم آپ پر درود کیسے پڑھیں؟ تو رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’تم یوں کہو: [اللھم! صل علی محمد و ازواجہ و ذریتہ] ’’اے اللہ! محمد (صلی اللہ علیہ وسلم)، آپ کی بیویوں اور آپ کی نسل پر رحمتیں نازل فرما۔‘‘ حارث کی حدیث میں یہ لفظ بھی ہیں: [کما صلیت ……… و ذریتہ] ’’جس طرح تو نے ابراہیم (علیہ السلام) کی آل پر رحمتیں نازل فرمائیں اور محمد (صلی اللہ علیہ وسلم)، آپ کی بیویوں اور آپ کی نسل پر برکتیں نازل فرما۔‘‘ یہاں سےپھر دونوں راوی متفق ہیں: [کما بارکت ……… حمید مجید] ’’جس طرح تو نے ابراہیم (علیہ السلام) کی آل پر برکتیں نازل فرمائیں۔ یقیناً تو تعریف اور بزرگی والا ہے۔‘‘\nامام ابو عبدالرحمن نسائی رحمہ اللہ بیان کرتے ہیں کہ ہمیں یہ حدیث حضرت قتیبہ نے دو دفعہ بیان فرمائی۔ معلوم یوں ہوتا ہے کہ ان سے ایک سطر رہ گئی۔‘‘","f2":"(۱) اس روایت میں امام صاحب کے دو استاد ہیں۔ قتیبہ اور حارث بن مسکین۔ قتیبہ کی روایت میں بعض الفاظ رہ گئے ہیں جو حارث بن مسکین نے بیان کیے ہیں۔ امام صاحب نے اس کی صراحت کی ہے۔ راویت کے الفاظ پڑھنے سے صاف معلوم ہوتا ہے کہ حضرت قتیبہ سے پڑھتے وقت ایک سطر چھوٹ گئی ہے کیونکہ [اللھم صل] کے بعد (کما بارکت] تو نہیں آسکتا بلکہ [کما صلیت] ہی آسکتا ہے۔ (۲) مندرجہ بالا احادیث میں درود کے جو الفاظ بیان کیے گئے ہیں، ان میں معمولی لفظی فرق ہے جس کی کوئی حیثیت نہیں۔ ان میں سے کوئی سے الفاظ بھی پڑھ لیے جائیں، کوئی حرج نہیں،البتہ درود ابراہیمی ہو جیسا کہ روایات سے ظاہر ہے۔"}],[1295,"ابوطلحہ رضی اللہ عنہ سے روایت ہے کہ ایک دن رسول اللہ صلی اللہ علیہ وسلم تشریف لائے، اور آپ کے چہرے پر خوشی و مسرت جھلک رہی تھی، آپ نے فرمایا:\"یہ (خوشی اس لیے ہے کہ) میرے پاس جبرائیل علیہ السلام آئے، اور کہنے لگے: اے محمد! کیا آپ کے لیے یہ خوشی کا باعث نہیں کہ آپ کی امت میں سے جو کوئی بھی آپ پر صلاۃ (درود و رحمت) بھیجے گا تو میں اس پر دس بار درود بھیجوں گا، اور جو کوئی آپ کے امتیوں میں سے آپ پر سلام بھیجے گا میں تو اس پر دس بار سلام بھیجوں گا\"۔","الألباني: حسن",{"u2":"حضرت ابوطلحہ رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم ایک دن آئے تو آپ کے چہرے پر خوشی کے آثار نظر آ رہے تھے۔ (ہمارے استفسار پر) آپ نے فرمایا: ’’جبریل میرے پاس آئے اور کہنے لگے: اے محمد! کیا آپ کے لیے یہ بات خوش کن نہیں ہے کہ آپ کی امت میں سے جو شخص بھی آپ پر درود پڑھے گا، میں اس پر دس بار رحمت اتاروں گا اور آپ کی امت میں سے جو شخص بھی آپ پر سلام پھڑے گا، میں اس پر دس دفعہ سلام نازل کروں گا۔‘‘","f2":"دیکھیے، حدیث: ۱۲۸۴۔"}],[1296,"ابوہریرہ رضی اللہ عنہ کہتے ہیں کہ نبی اکرم صلی اللہ علیہ وسلم نے فرمایا: \"جو شخص مجھ پر ایک (مرتبہ) صلاۃ (درود و رحمت) بھیجے گا اللہ اس پر دس مرتبہ صلاۃ(درود و رحمت) بھیجے گا\"۔","الألباني: صحيح",{"u2":"حضرت ابوہریرہ سے مروی ہے، نبی صلی اللہ علیہ وسلم نے فرمایا: ’’جو شخص مجھ پر ایک دفعہ درود پڑھے گا، اللہ تعالیٰ اس پر دس دفعہ رحمت نازل فرمائےگا۔‘‘"}],[1297,"انس بن مالک رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"جو شخص میرے اوپر ایک بار صلاۃ (درود و رحمت) بھیجے گا، تو اللہ اس پر دس بار صلاۃ(درود و رحمت) بھیجے گا، اور اس کے دس گناہ معاف اور دس درجے بلند کر دیئے جائیں گے\"۔","الألباني: صحيح",{"u2":"حضرت انس بن مالک رضی اللہ عنہ سے منقول ہے، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’جو شخص مجھ پر ایک دفعہ درود پڑھےگا، اللہ تعالیٰ اس پر دس رحمتیںنازل فرمائے گا اور اس کی دس غلطیاں معاف کر دی جائیں گی اور اس کے دس درجےبلند کیے جائیں گے۔‘‘","f2":"اس حدیث میں سابقہ احادیث سے زائد فضیلت اور ثواب کا بیان ہے اور یہ اللہ تعالیٰ کا کرم ہے۔ اللہ تعالیٰ کے حبیب صلی اللہ علیہ وسلم پر درود پڑھنے والا اللہ تعالیٰ کو بہت پسند ہے۔ کیوں نہ ہو؟ حبیب الحبیب حبیب۔ درود پڑھنا أعظم القربات ’’نیک کاموں میں سب سے عظیم‘‘ ہے اور افضل دعا ہے۔"}],[1298,"عبداللہ بن مسعود رضی اللہ عنہ کہتے ہیں کہ جب ہم رسول اللہ صلی اللہ علیہ وسلم کے ساتھ نماز میں بیٹھتے تو کہتے: سلام ہو اللہ پر اس کے بندوں کی طرف سے، سلام ہو فلاں پر اور فلاں پر، تو رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: «السلام على اللہ» نہ کہو، کیونکہ اللہ تو خود ہی سلام ہے، ہاں جب تم میں سے کوئی قعدہ میں بیٹھے تو چاہیئے کہ وہ کہے: «التحيات لله والصلوات والطيبات السلام عليك أيها النبي ورحمة اللہ وبركاته السلام علينا وعلى عباد اللہ الصالحين» \"تمام قولی، فعلی اور مالی عبادتیں اللہ ہی کے لیے ہیں، اے نبی! آپ پر سلام ہو اور اللہ کی رحمت اور برکتیں نازل ہوں، ہم پر اور اللہ کے نیک بندوں پر سلام ہو\" کیونکہ جب تم اس طرح کہو گے تو زمین و آسمان میں رہنے والے ہر نیک بندے کو یہ شامل ہو گا، (پھر کہے): «أشهد أن لا إله إلا اللہ وأشهد أن محمدا عبده ورسوله» \"میں گواہی دیتا ہوں کہ نہیں ہے کوئی حقیقی معبود سوائے اللہ کے، اور میں گواہی دیتا ہوں کہ محمد اس کے بندے اور اس کے رسول ہیں\"پھر اس کے بعد اپنی پسندیدہ دعا جو بھی چاہے کرے\"۔","الألباني: صحيح",{"u2":"حضرت عبداللہ بن مسعود رضی اللہ عنہ بیان کرتے ہیں کہ جب ہم نماز میں رسول اللہ صلی اللہ علیہ وسلم کےپیچھے (تشہد میں) بیٹھتے تھے تو ہم کہتے تھے: اللہ کے بندوں کی طرف سے اللہ تعالیٰ پر سلام ہو، فلاںپر سلام اور فلاںپر سلام۔ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’تم [السلام علی اللہ] نہ کہو کیونکہ اللہ تعالیٰ تو خود سلام ہے بلکہ جب تم میں سے کوئی شخص (قعدےمیں) بیٹھے تو وہ کہے: [التحیات للہ ……… ورسولہ] ’’تمام آداب (قولی عبادات) اور تمام دعائیں (فعلی عبادات) اور تمام اچھے کلمات (مالی عبادات) اللہ تعالیٰ کے لیے ہیں۔ اے نبی! آپ پر سلام ہو اور اللہ تعالیٰ کی رحمت و برکات ہوں۔ ہم پر اور اللہ تعالیٰکے نیک بندوں پر بھی سلام ہو۔ جب تم یہ الفاظ کہو گے تو یہ سلام اور دعا آسمان و زمین میں اللہ تعالیٰکے ہر نیک بندے کو پہنچ جائیں گے۔ میں گواہی دیتا ہوں کہ اللہ تعالیٰ کے سوا کوئی (حقیقی) معبود نہیں۔ اور میں گواہی دیتا ہوں کہ محمد صلی اللہ علیہ وسلم اللہ تعالیٰ کے بندے اور رسول ہیں۔‘‘ پھر اس کے بعد (درود پڑھ کر) جو (منقول) دعا اسے زیادہ پسند ہو، منتخب کرے اور پڑھے","f2":"(۱) اگرچہ حدیث میں مطلق دعا کا ذکر ہے مگر بعض چیزیں خود بخود مفہوم ہوتی ہیں، یعنی دعا سے پہلے درود پڑھا جائے گا جیسا کہ گزشتہ روایات سے واضح ہے، مثلاً: حدیث نمبر ۱۲۸۵۔ اسی طرح دعا سے مراد بھی منقول اور ماثور دعا ہے، نہ کہ ہر آدمیاپنی مرضی کے مطابق دعائیں بناتا رہے۔ جب نماز کے ہر رکن کے لیے منقول ذکر ہونا ضروری ہے تو یہاں کیسے غیر منقول دعا مراد ہوگی؟ ویسے بھی اپنی طرف سے بنائی ہوئی دعا کی صحت کا یقین نہیں ہوتا اور نماز میں مشکوک چیز نہیں ہونی چاہیے۔ واللہ أعلم۔ (۲) درود شریف پڑھنے سے اللہ کے حکم کی تعمیل ہوتی ہے۔ (۳) نبیٔ اکرم صلی اللہ علیہ وسلم پر صلاۃ پڑھنے میں بندہ اپنے رب کی موافقت کرتا ہے اگرچہ اللہ کا آپ پر صلاۃ پڑھنے کا مطلب یہ ہے کہ اللہ تعالیٰ فرشتوں کے ہاں آپ کی تعریف و توصیف کرتا ہے اور ہمارے اور فرشتوں کے صلاۃ پڑھنے سے مراد دعا ہے۔ (۴) جو بندہ ایک دفعہ نبیٔ اکرم صلی اللہ علیہ وسلم پر درود پڑھتا ہے، اللہ تعالیٰ اس پر دس رحمتیں نازل فرماتا ہے، دس نیکیاں عطا فرماتا ہے۔ دس درجے بلند ہو جاتے ہیں اور اس کے دس گناہ مٹا دیے جاتے ہیں۔ (۵) جب بندہ اللہ کے حضور دعا مانگتا اور اس سے پہلے درود پڑھتا ہے تو اس کی دعا قبول ہنے کی زیادہ امید ہوتی ہے۔ (۶) درود شریف قیامت والے دن نبیٔ رحمت صلی اللہ علیہ وسلم کی شفاعت، آپ کی رفاقت اور گناہوںکی معافی کا ذریعہ ہوگا۔ (۷) اسکے نہ پڑھنے سے آدمی قیامت کے دن حسرت اور افسوس کرے گا۔ (۸) اس کے پڑھنے سے فاقوں اور مصیبتوں سے نجات ملتی ہے۔ (۹) اس کے پڑھنے سے جنت کا راستہ آسان ہ جاتا ہے۔ (۱۰) آپ پر درود نہ بھیجنے والا بخیل ہے۔ (۱۱) آپ کا نام سن کر درود نہ پڑھنے والے کے لیے جبریل علیہ السلام اور حضرت محمد صلی اللہ علیہ وسلم نے بددعا فرمائی۔ (۱۲) اس کے پڑھنے سے فرشتے دعائے رحمت کرتے ہیں۔ (۱۳) اس کے پڑھنے سے رسول اللہ صلی اللہ علیہ وسلم کا قرب نصیب ہوگا"}],[1299,"انس بن مالک رضی اللہ عنہ کہتے ہیں کہ ام سلیم رضی اللہ عنہا نبی اکرم صلی اللہ علیہ وسلم کے پاس آئیں، اور عرض کیا: اللہ کے رسول! مجھے کچھ ایسے کلمات سکھا دیجئیے جن کے ذریعہ میں اپنی نماز میں دعا کیا کروں، تو آپ نے فرمایا: \"دس بار «سبحان اللہ»، دس بار «الحمد لله»، دس بار «اللہ أكبر» کہو، اس کے بعد تم اللہ سے اپنی حاجت مانگو، وہ ہاں، ہاں کہے گا\"، (یعنی جو تم مانگو گی وہ تمہیں دے گا)۔","الألباني: حسن الإسناد",{"u2":"حضرت انس بن مالک رضی اللہ عنہ سے روایت ہے، انھوں نے فرمایا: حضرت ام سلیم رضی اللہ عنہا نبی صلی اللہ علیہ وسلم کے پاس آئیں اور کہا: اے اللہ کے رسول! مجھے کچھ ایسے کلمات سکھا دیجیے جن کے ساتھ میں نماز میں دعا کیا کروں۔ آپ نے فرمایا: ’’دس دفعہ سبحان اللہ پڑھا کر اور دس دفعہ الحمدللہ پڑھا کر اور دس دفعہ اللہ أکبر پڑھا کر۔ پھر اللہ سے اپنی حاجت طلب کر۔ اللہ تعالیٰ فرمائے گا: ہاں! ہاں! (میں نے تیری حاجت قبول کی)۔‘‘","f2":"یہ حدیث مذکور میں یہ کہیں نہیں کہ یہ ذکر تشہد کے بعد کیا جائے گا، دیگر روایات میں صراحت ہے کہ یہ ذکر سلام کے بعد کیا جائے گا۔ (دیکھیے، حدیث: ۱۳۴۹) یا اس جملہ (نماز میں دعا کیا کروں۔ فی صلاتی) میں صلاۃ سے مراد دعا لی جائے۔ مطلب یہ ہوگا کہ مجھے ایسے کلمات سکھا دیجیے جو میں اپنی دعا میں پڑھا کروں۔ رسول اللہ صلی اللہ علیہ وسلم کا جواب اس معنی کی تائید کرتا ہے۔ امام نسائی رحمہ اللہ کا استنباط محل نظر ہے (کہ یہ ذکر سلامسے پہلے ہے) بلکہ یہذکر بھی نماز کے بعد ہے اور ذکرکے بعد دعا بھی نماز کے بعد ہے۔ واللہ أعلم۔"}],[1300,"انس بن مالک رضی اللہ عنہ کہتے ہیں کہ میں رسول اللہ صلی اللہ علیہ وسلم کے ساتھ (مسجد میں) بیٹھا ہوا تھا، اور ایک آدمی کھڑا نماز پڑھ رہا تھا، جب اس نے رکوع اور سجدہ کر لیا، اور تشہد سے فارغ ہو گیا، تو اس نے دعا کی، اور اپنی دعا میں اس نے کہا: «اللہم إني أسألك بأن لك الحمد لا إله إلا أنت المنان بديع السموات والأرض يا ذا الجلال والإكرام يا حى يا قيوم إني أسألك» \"اے اللہ! میں تجھ سے مانگتا ہوں اس لیے کہ تیرے ہی لیے تمام تعریفیں ہیں، نہیں ہے کوئی معبود برحق سوائے تیرے، تو بہت احسان کرنے والا ہے، تو ہی آسمانوں اور زمین کا پیدا کرنے اور وجود میں لانے والا ہے، اے عظمت و جلال اور احسان والے، ہمیشہ زندہ و باقی رہنے والے!، میں تجھی سے مانگتا ہوں۔ یہ سنا تو نبی اکرم صلی اللہ علیہ وسلم نے اپنے صحابہ سے کہا: \"تم جانتے ہو اس نے کن لفظوں سے دعا کی ہے؟\" انہوں نے کہا: اللہ اور اس کے رسول زیادہ جانتے ہیں، آپ صلی اللہ علیہ وسلم نے فرمایا: \"قسم ہے اس ذات کی جس کے ہاتھ میں میری جان ہے، اس نے تو اللہ سے اس کے اسم اعظم کے ذریعہ دعا کی ہے جس کے ذریعہ دعا کی جاتی ہے تو وہ قبول کرتا ہے، اور جب اس کے ذریعہ مانگا جاتا ہے تو وہ دیتا ہے\"۔","الألباني: صحيح",{"u2":"حضرت انس بن مالک رضی اللہ عنہ بیان کرتے ہیں کہ میں رسول اللہ صلی اللہ علیہ وسلم کے ساتھ بیٹھا تھا اور ایک آدمی کھڑا نماز پڑھ رہا تھا۔ جب اس نے رکوع اور سجدہ کر لیا اور تشہد بھی پڑھ لیا تو اس نے دعا کی اور اپنی دعا میں کہا: [اللھم! انی اسئلک بان لک الحمد……… الخ] ’’اے اللہ! میں تجھ سے سوال کرتا ہوں اس بنا پر کہ تیرے لیے ہی تعریف ہے۔ تیرے سوا کوئی (حقیقی) معبود نہیں۔ تو بہت احسان کرنے والا ہے۔ آسمانوں اور زمینوں کو بلا مادہ پیدا کرنے والا ہے۔ اےبزرگی و عزت والے! اے زندہ و جاوید! اے سب کو قائم رکھنے والے! بے شک میں تجھ سے سوال کرتا ہوں۔‘‘ نبی صلی اللہ علیہ وسلم نے اپنے صحابہ سے فرمایا: ’’تم جانتے ہو اس نے کن لفظوں سے دعا کی؟‘‘ انھوں نے کہا: اللہ تعالیٰ اور اس کا رسول بخوبی جانتے ہیں۔ آپ نے فرمایا: ’’اس ذات کی قسم جس کے ہاتھ میں میری جان ہے! اس نے اللہ تعالیٰ کے اس اسم اعظم کے ساتھ دعا کی ہے کہ جب اس کے ساتھ اللہ کو پکارا جائے تو وہ ضرور جواب دیتا ہے اور جب اس کے ساتھ کچھ مانگا جائے تو ضرور عطا فرماتا ہے۔‘‘"}],[1301,"محجن بن ادرع رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم مسجد میں گئے، تو دیکھا کہ ایک آدمی اپنی نماز پوری کر چکا ہے، اور تشہد میں ہے اور کہہ رہا ہے:«اللہم إني أسألك يا اللہ بأنك الواحد الأحد الصمد الذي لم يلد ولم يولد ولم يكن له كفوا أحد أن تغفر لي ذنوبي إنك أنت الغفور الرحيم» \"اے اللہ! میں تجھ سے مانگتا ہوں، اے اللہ تجھی سے، اس لیے کہ تو ہی ایک ایسا تن تنہا بے نیاز ہے جس نے نہ تو کسی کو جنا ہے، اور نہ ہی وہ جنا گیا ہے، اور نہ ہی اس کا کوئی ہمسر ہے، لہٰذا تو میرے گناہوں کو بخش دے، تو ہی غفور و رحیم یعنی بخشنے والا اور رحم کرنے والا ہے\" تو رسول اللہ صلی اللہ علیہ وسلم نے تین بار فرمایا: \"اس کے گناہ بخش دیے گئے\"۔","الألباني: صحيح",{"u2":"حضرت محجن بن ادرع بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم مسجد میں داخل ہوئے جب کہ ایک آدمی اپنی نماز مکمل کر چکا تھا اور تشہد کی حالت میں تھا۔ اس نے کہا: [اللھم! انی اسئلک یا اللہ! ___ الغفور الرحیم] ’’اے اللہ! میں تجھ سے سوال کرتا ہوں اس بنا پر کہ تو واحد ہے۔ یکتا اور بے نیاز ہے، جس نے نہ کسی کو جنا اور نہ وہ جنا گیا، اور نہ کوئی اس کا ہمسر ہے، کہ تو میرے گناہ معاف فرما دے۔ بلاشبہ تو ہی بہت زیادہ بخشنے والا، نہایت رحم کرنے والا ہے۔‘‘ رسول اللہ صلی اللہ علیہ وسلم نے تین مرتبہ فرمایا: ’’تحقیق اسے معاف کر دیا گیا۔‘‘","f2":"(۱) رسولِ اکرم صلی اللہ علیہ وسلم کی زبان مبارک سے یہ عظیم خوش خبری نہ صرف حضرت محجن رضی اللہ عنہ کے لیے تھی بلکہ ہر اس شخص کے لیے ہے جو اس انداز سے دعا کرے۔ یہ دعا بھی اسم اعظم کے ساتھ ہی ہے کیونکہ مذکورہ اوصاف باری تعالیٰ کی ذات بے مثال کے ساتھ خاص ہیں۔ کسی میں ان کا شمہ بھی نہیں پایا جاتا۔ (۲) نماز سے فارغ ہوکر اذکار کرنے کے بعد دعا کرنا مستحسن امر ہے۔ (۳) اپنی حاجت کا مطالبہ کرنے سے پہلے مذکورہ الفاظ کہنے سے اللہ تعالیٰ بندے کی دعا ضرور قبول فرماتا ہے، بشرطیکہ اس میں بقیہ شرائط موجود ہوں، مثلاً: اس کا کھانا، پینا اور لباس حلال کا ہو۔ (۴) اللہ تعالیٰ کے تمام نام ہی مقدس و بابرکت ہیں لیکن ان میں سے بعض ایسے بھی ہیں جن کی تاثیر باقی سے بڑھ کر ہے۔ واللہ أعلم"}],[1302,"ابوبکر صدیق رضی اللہ عنہ سے روایت ہے کہ انہوں نے رسول اللہ صلی اللہ علیہ وسلم سے عرض کیا: آپ مجھے کوئی ایسی دعا سکھا دیجئیے جس کے ذریعہ میں اپنی نماز میں دعا مانگا کروں، تو آپ نے فرمایا: کہو: «اللہم إني ظلمت نفسي ظلما كثيرا ولا يغفر الذنوب إلا أنت فاغفر لي مغفرة من عندك وارحمني إنك أنت الغفور الرحيم» \"اے اللہ! بیشک میں نے اپنے اوپر بہت ظلم کیا ہے، اور سوائے تیرے گناہوں کو کوئی بخش نہیں سکتا، لہٰذا تو اپنی خاص مغفرت سے مجھے بخش دے، اور مجھ پر رحم کر، یقیناً تو غفور و رحیم یعنی بہت بخشنے والا اور رحم کرنے والا ہے\"۔","الألباني: صحيح",{"u2":"حضرت ابوبکر صدیق رضی اللہ عنہ نے رسول اللہ صلی اللہ علیہ وسلم سے گزارش کی کہ مجھے کوئی ایسی دعا سکھا دیجیے جو میں اپنی نماز میں کروں۔ آپ نے فرمایا: ’’یوں کہا کرو: [اللھم! انی ظلمت ……… الرحیم] ’’اے اللہ! میں نے اپنی جان پر بہت زیادہ ظلم کیا ہے اور تیرے سوا کوئی گناہ معاف نہیں کرسکتا، لہٰذا میرے لیے اپنی طرف سے بخشش فرما اور مجھ پر رحم فرما۔ بلاشبہ تو ہی بہت زیادہ معاف کرنے والا، نہایت رحم کرنے والا ہے۔‘‘","f2":"(۱) ہر انسان پر تقصیر ہے، لہٰذا اپنے قصور کا اعتراف کرتے رہنا چاہیے، خواہ علم ہو یا نہ۔ بندے کی شان یہی ہے، خواہ صدیق ہی ہو، نیز یہ دعا تو ہر امتی کے لیے ہے۔ ظلم کثیر سے مراد گناہوں اور غلطیوں کی کثرت ہے جس سے کوئی امتی محفوظ نہیں ہے۔ واللہ أعلم۔ (۲) اس حدیث مبارکہ سے اس موقف کی تردید ہوتی ہے کہ مومن کا لفظ صرف اسی شخص پر بولا جا سکتا ہے جس کے ذمے کوئی گناہ نہ ہو۔ ابوبکر صدیق رضی اللہ عنہ اس امت میں سب سے بڑے مومن تھے لیکن نبیٔ اکرم صلی اللہ علیہ وسلم نے انھیں یہ دعا سکھائی۔"}],[1303,"معاذ بن جبل رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے میرے دونوں ہاتھ پکڑے، اور فرمایا: \"اے معاذ! میں تم سے محبت کرتا ہوں\"، تو میں نے عرض کیا: اور میں بھی آپ سے محبت کرتا ہوں اللہ کے رسول! تو رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"پھر تو تم ہر نماز میں یہ دعا پڑھنا نہ چھوڑو «رب أعني على ذكرك وشكرك وحسن عبادتك» اے میرے رب! اپنے ذکر اور شکر پر، اور اپنی حسن عبادت پر میری مدد فرما\"۔","الألباني: صحيح",{"u2":"حضرت معاذ بن جبل رضی اللہ عنہ سے مروی ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے میرا ہاتھ پکڑا اور فرمایا: ’’اے معاذ! میں تجھ سے محبت کرتا ہوں۔‘‘ میں نے عرض کیا: ’’اے اللہ کے رسول! میں بھی آپ سے محبت کرتا ہوں۔ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’پھر تو کسی نماز میں یہ دعا کرنا نہ چھوڑ: [رب أعنی علی ذکرک……] ’’اے میرے رب! میری مدد فرما کہ میں تیرا ذکر کروں اور تیرا شکر کروں اور تیری عبادت اچھی طرح بنا سنوار کے کروں۔‘‘","f2":"(۱) مذکورہ الفاظ کے ساتھ نماز میں دعا کرنا مشروع ہے۔ (۲) اس حدیث میں [في کل صلاۃ] ’’ہر نماز میں‘‘ کے الفاظ ہیں، دیگر روایات میں [في دبر کل صلاۃ] ’’ہر نماز کے بعد‘‘ کے الفاظ ہیں۔ دونوں روایتوں میں تعارض نہیں بلکہ اس میں وسعت ہے کہ بندہ سلام کے بعد بھی یہ دعا پڑھ سکتا ہے اور سلام سے پہلے بھی، اس لیے کہ دبر کے معنی ’’ہرچیز کا آخر‘‘ بھی ہیں اور ’’بعد‘‘ بھی ہیں۔ واللہ أعلم۔ (۳) حضرت معاذ رضی اللہ عنہ کی فضیلت کہ نبی صلی اللہ علیہ وسلم ان سے محبت کرتے تھے۔ (۴) اس سے یہ بھی ثابت ہوا کہ اگر کسی بندے کو دوسرے سے محبت ہو تو اسے بتا دینا چاہیے، اس سے محبت میں پائیداری اور دوام ہو جاتا ہے۔ (۵) بندہ ہر وقت اللہ کی اطاعت و فرماں برداری کے لیے اس سے مدد مانگتا رہے کیونکہ گناہ سے بچنے اور نیکی کرنے کی طاقت اس کی توفیق کے بغیر ممکن نہیں"}],[1304,"شداد بن اوس رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم اپنی نماز میں کہتے تھے: «اللہم إني أسألك الثبات في الأمر والعزيمة على الرشد وأسألك شكر نعمتك وحسن عبادتك وأسألك قلبا سليما ولسانا صادقا وأسألك من خير ما تعلم وأعوذ بك من شر ما تعلم وأستغفرك لما تعلم» \"اے اللہ! میں معاملہ میں تجھ سے ثابت قدمی کا، اور راست روی میں عزیمت کا سوال کرتا ہوں، اور تجھ سے تیری نعمتوں کے شکر اور تیری حسن عبادت کی توفیق مانگتا ہوں، اور تجھ سے تمام برائیوں اور آلائشوں سے پاک و صاف دل، اور سچ کہنے والی زبان کا طلب گار ہوں، اور تجھ سے ان چیزوں کی بھلائی کا سوال کرتا ہوں جنہیں تو جانتا ہے، اور ان چیزوں کی برائی سے تیری پناہ چاہتا ہوں جنہیں تو جانتا ہے، اور میں تجھ سے ان گناہوں کی مغفرت طلب کرتا ہوں جو تیرے علم میں ہیں\"۔","الألباني: ضعيف",{"u2":"حضرت شداد بن اوس رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم اپنی نماز میں یہ دعا پڑھتے تھے: [اللھم إنی أسئلک التثبت ……… لما تعلم] ’’اے اللہ! میں تجھ سے سوال کرتا ہوں کہ میں دین کے معاملے میں ثابت قدم رہوں اور ہدایت کے حصول میں پرعزم رہوں اور میں تجھ سے سوال کرتا ہوں کہ تیری نعمتوں کا شکر ادا کروں اور تیری عبادت اچھے طریقے سے کروں اور میں تجھ سے قلب سلیم اور سچی زبان مانگتا ہوں۔ اور تجھ سے میں ہر اس چیز کی خیر مانگتا ہوں جو تو جانتا ہے اور ہر اس چیز کے شر سے تیری پناہ چاہتا ہوں جو تو جانتا ہے اور تجھ سے ہر اس گناہ کی عافی مانگتا ہں جو تو جانتا ہے۔‘‘","f2":"’’قلب سلیم‘‘ سے مراد وہ دل ہے جو اللہ تعالیٰ کے حق میں شرک و نفاق اور ریا سے محفوظ ہو اور بندوں کے حق میں حسد، کینہ، بغض، حرص اور ہوس سے پاک ہو اور نیکی کی طرف راغب ہو۔ واللہ أعلم"}],[1305,"سائب کہتے ہیں کہ عمار بن یاسر رضی اللہ عنہما نے ہمیں نماز پڑھائی تو اس میں اختصار سے کام لیا، قوم میں سے کچھ لوگوں نے ان سے کہا: آپ نے نماز ہلکی کر دی ہے، راوی کو شک ہے «خففت» کہا یا «أوجزت» (ہلکی کر دی یا مختصر کر دی) تو انہوں نے کہا: اس کے باوجود میں نے اس میں ایسی دعائیں پڑھی ہیں جن کو میں نے رسول اللہ صلی اللہ علیہ وسلم سے سنا ہے، تو جب وہ جانے کے لیے کھڑے ہوئے تو قوم میں سے ایک آدمی ان کے پیچھے ہو لیا (وہ کوئی اور نہیں میرے والد تھے مگر انہوں نے اپنا نام چھپایا ہے) ۱؎ اس نے ان سے اس دعا کے بارے میں سوال کیا، پھر آ کر لوگوں کو اس کی خبر دی، وہ دعا یہ تھی: «اللہم بعلمك الغيب وقدرتك على الخلق أحيني ما علمت الحياة خيرا لي وتوفني إذا علمت الوفاة خيرا لي اللہم وأسألك خشيتك في الغيب والشهادة وأسألك كلمة الحق في الرضا والغضب وأسألك القصد في الفقر والغنى وأسألك نعيما لا ينفد وأسألك قرة عين لا تنقطع وأسألك الرضاء بعد القضاء وأسألك برد العيش بعد الموت وأسألك لذة النظر إلى وجهك والشوق إلى لقائك في غير ضراء مضرة ولا فتنة مضلة اللہم زينا بزينة الإيمان واجعلنا هداة مهتدين» \"اے اللہ! میں تیرے علم غیب اور تمام مخلوق پر تیری قدرت کے واسطہ سے تجھ سے سوال کرتا ہوں کہ تو مجھے اس وقت تک زندہ رکھ جب تک تو جانے کہ زندگی میرے لیے باعث خیر ہے، اور مجھے موت دیدے جب تو جانے کہ موت میرے لیے بہتر ہے، اے اللہ! میں غیب و حضور دونوں حالتوں میں تیری مشیت کا طلب گار ہوں، اور میں تجھ سے خوشی و ناراضگی دونوں حالتوں میں کلمہ حق کہنے کی توفیق مانگتا ہوں، اور تنگ دستی و خوشحالی دونوں میں میانہ روی کا سوال کرتا ہوں، اور میں تجھ سے ایسی نعمت مانگتا ہوں جو ختم نہ ہو، اور میں تجھ سے ایسی آنکھوں کی ٹھنڈک کا طلبگار ہوں جو منقطع نہ ہو، اور میں تجھ سے تیری قضاء پر رضا کا سوال کرتا ہوں، اور میں تجھ سے موت کے بعد کی راحت اور آسائش کا طالب ہوں، اور میں تجھ سے تیرے دیدار کی لذت، اور تیری ملاقات کے شوق کا طالب ہوں، اور پناہ چاہتا ہوں تجھ سے اس مصیبت سے جس پر صبر نہ ہو سکے، اور ایسے فتنے سے جو گمراہ کر دے، اے اللہ! ہم کو ایمان کے زیور سے آراستہ رکھ، اور ہم کو راہ نما اور ہدایت یافتہ بنا دے\"۔","الألباني: صحيح",{"u2":"حضرت سائب بیان کرتے ہیں کہ حضرت عمار بن یاسر رضی اللہ عنہ نے ہمیں ایک نماز پڑھائی اور بڑی مختصر پڑھائی۔ کچھ لوگوں نے ان سے کہا کہ آپ نے بڑی ہلکی اور مختصر نماز پڑھائی ہے۔ آپ کہنے لگے: اس کے باوجود میں نے نماز میں بہت سی دعائیں پڑھی ہیں جو میں نے اللہ کے رسول صلی اللہ علیہ وسلم سے سنیں۔ جب وہ اٹھے تو ایک آدمی ان کے پیچھے چلا……… وہ خود حضرت سائب ہی تھے، لیکن انھوں نے اپنا نام پوشیدہ رکھا……… اور ان سے وہ دعائیں پوچھیں۔ پھر واپس آکر اس نے لوگوں کو بتائیں۔ (ایک دعا یہ تھی:) [اللھم! بعلمک الغیب ……… واجعلنا ھداۃ مھتدین] ’’اے اللہ! چوکہ تو علم غیب جانتا ہے اور تمام مخلوقات پر قدرت رکھتا ہے، اس لیے (میں تجھ سے سوال کرتا ہوں کہ) تو مجھے اس وقت تک زندہ رکھ جب تک میرے لیے زندہ رہنا بہتر ہے اور مجھے اس وقت فوت کر دینا جب میرے لیے وفات بہتر سمجھے۔ اور اے اللہ! میں تجھ سے باطناً اور ظاہراً تیرے ڈر کا سوال کرتا ہوں اور رضا مندی و ناراضی ہر حال میں سچی اور حکمت بھری بات کہنے کا سوال کرتا ہوں۔ اور فقیری و امیری میںمیانہ روی اختیار کرنے کی توفیق مانگتا ہوں اور تجھ سے ایسی نعمتوں کا سوال کرتا ہوں جو کبھی ختم نہ ہوں۔ اور ایسی آنکھ کی ٹھنڈک (خوشی و لذت) مانگتا ہوں جو کبھی منقطع نہ ہو۔ اور راضی برضا و قضا رہنے کا سوال کرتا ہوں۔ اور موت کے بعد لذیذ زندگی مانگتا ہوں۔ اور تیرے روئے اقدس کے دیدار کے مزے اور تیری ملاقات کے شوق کا طلب گار ہوں، بغیر اس کے کہ کسی نقصان دہ مصیبت میں پھنسوں یا کسی گمراہ کن فتنے میں مبتلا ہوں۔ اے اللہ! ہمیں ایمان کی زینت سے آراستہ فرما اور ہمیں ہدایت یافتہ (اور گمراہوں کو) راہ دکھلانے والے بنا دے۔‘‘"}],[1306,"قیس بن عباد کہتے ہیں کہ عمار بن یاسر رضی اللہ عنہما نے لوگوں کو نماز پڑھائی، اور اسے ہلکی پڑھائی، تو گویا کہ لوگوں نے اسے ناپسند کیا، تو انہوں نے کہا: کیا میں نے رکوع اور سجدے پورے پورے نہیں کیے ہیں؟ لوگوں نے کہا: کیوں نہیں، ضرور کیا ہے، پھر انہوں نے کہا: سنو! میں نے اس میں ایسی دعا پڑھی ہے جس کو نبی اکرم صلی اللہ علیہ وسلم پڑھا کرتے تھے وہ یہ ہے: «اللہم بعلمك الغيب وقدرتك على الخلق أحيني ما علمت الحياة خيرا لي وتوفني إذا علمت الوفاة خيرا لي وأسألك خشيتك في الغيب والشهادة وكلمة الإخلاص في الرضا والغضب وأسألك نعيما لا ينفد وقرة عين لا تنقطع وأسألك الرضاء بالقضاء وبرد العيش بعد الموت ولذة النظر إلى وجهك والشوق إلى لقائك وأعوذ بك من ضراء مضرة وفتنة مضلة اللہم زينا بزينة الإيمان واجعلنا هداة مهتدين» \"اے اللہ! میں تیرے علم غیب اور تمام مخلوق پر تیری قدرت کے واسطہ سے تجھ سے سوال کرتا ہوں کہ تو مجھے اس وقت تک زندہ رکھ جب تک تو جانے کہ زندگی میرے لیے باعث خیر ہے، اور مجھے موت دیدے جب تو جانے کہ موت میرے لیے بہتر ہے، اے اللہ! میں غیب و حضور دونوں حالتوں میں تیری خشیت کا طلب گار ہوں، اور میں تجھ سے خوشی و ناراضگی دونوں حالتوں میں کلمہ اخلاص کی توفیق مانگتا ہوں، اور میں تجھ سے ایسی نعمت مانگتا ہوں جو ختم نہ ہو، اور میں تجھ سے ایسی آنکھوں کی ٹھنڈک کا طلبگار ہوں جو منقطع نہ ہو، اور میں تجھ سے تیری قضاء پر رضا کا سوال کرتا ہوں، اور میں تجھ سے موت کے بعد کی راحت اور آسائش کا طلبگار ہوں، اور میں تجھ سے تیرے دیدار کی لذت، اور تیری ملاقات کے شوق کا طلبگار ہوں، اور پناہ چاہتا ہوں تیری اس مصیبت سے جس پر صبر نہ ہو سکے، اور ایسے فتنے سے جو گمراہ کر دے، اے اللہ! ہم کو ایمان کے زیور سے آراستہ رکھ، اور ہم کو راہنما و ہدایت یافتہ بنا دے\"۔","الألباني: صحيح",{"u2":"حضرت قیس بن عباد بیان کرتے ہیں کہ حضرت عمار بن یاسر رضی اللہ عنہ نے لوگوں کو ہلکی نماز پڑھائی۔ گویا کہ لوگوں نے اسے عجیب سمجھا۔ آپ نے فرمایا: کیا میں نے رکوع اور سجدے مکمل نہیں کیے؟ لوگوں نے کہا: کیوں نہیں (وہ تو ٹھیک ہیں۔) آپ نے فرمایا: میں نے نماز میں وہ دعا پڑھی ہے جو رسول اللہ صلی اللہ علیہ وسلم نماز میں پڑھا کرتے تھے: [اللھم بعلمک الغیب ……… ھداۃ مھتدین] ’’اے اللہ! چونکہ تو غیب جانتا ہے اور مخلوق پر قدرت کاملہ رکھتا ہے، لہٰذا (میں تجھ سے سوال کرتا ہوں کہ) تو مجھے اتنی دیر تک زندہ رکھ جب تک زندگی میرے لیے بہتر ہو اور اس وقت فوت کر دینا جب تو میرے لیے وفات بہتر سمجھے۔ میں تجھ سے خلوت و جلوت میں تیرا ڈر مانگتا ہوں اور رضا مندی وناراضی میں کلمۂ حق کہنے کی توفیق مانگتا ہوں۔ اور تجھ سے وہ نعمت مانگتا ہوں جو ختم نہ ہو اور آنکھ کی وہ ٹھنڈک (لذت و سرور) جو کبھی منقطع نہ ہو اور تقدیر پر راضی رہنے، موت کے بعد پر سرور زندگی اور تیرے روئے اقدس کی زیارت کی لذت اور تیری ملاقات کا شوق مانگتا ہوں اور ہر نقصان دہ مصیبت اور ہر گمراہ کن فتنے سے تیری پناہ طلب کرتا ہوں۔ اے اللہ! ہمیں ایمان کی زینت سے مزین فرما اور ہمیں ہدایت یافتہ (اور گمراہوں کے لیے) راہ دکھلانے والا (راہنما) بنا دے","f2":"(۱) دونوں روایات میں معمولی لفظی فرق ہے، معنی دونوں کے ایک ہیں۔ یہ انتہائی جامع دعا ہے۔ (۲) بعض روایات میں موت کی خواہش کرنے سے منع کیا گیا ہے۔ دیکھیے: (صحیح البخاري، النمني، حدیث: ۷۲۳۵-۷۲۳۳) اور ان روایات میں موت کی دعا مذکور ہے۔ ان دونوں مںی تطبیق یہ ہے کہ بیماری وغیرہ یا دوسرے دنیوی مصائب کی وجہ سے موت کی خواہش کرنا منع ہے، اگر آدمی کو دین میں خرابی یا فتنے کا ڈر ہو تو ایسے حالات میں مذکورہ الفاظ کے ساتھ دعا کرسکتا ہے۔ (۳) جب تک انسان زندہ رہے اپنی خیر و بھلائی کی دعا کرتا رہے۔ (۴) مومنوں کو اللہ تعالیٰ کا دیدار نصیب ہوگا اور وہ اللہ کو بغیر کسی رکاوٹ کے دیکھیں گے"}],[1307,"فروہ بن نوفل کہتے ہیں کہ میں نے ام المؤمنین عائشہ رضی اللہ عنہا سے عرض کیا کہ آپ مجھ سے ایسی چیز بیان کیجئیے جس کے ذریعہ رسول اللہ صلی اللہ علیہ وسلم اپنی نماز میں دعا کرتے رہے ہوں، تو وہ کہنے لگیں: ہاں، سنو، رسول اللہ صلی اللہ علیہ وسلم کہتے تھے: «اللہم إني أعوذ بك من شر ما عملت ومن شر ما لم أعمل» \"اے اللہ! میں تجھ سے اس کام کی برائی سے پناہ چاہتا ہوں جو میں نے کیا ہے، اور اس کام کی برائی سے جو میں نے نہیں کیا ہے\"۔","الألباني: صحيح",{"u2":"حضرت فردہ بن نوفل بیان کرتے ہیں کہ میں نے حضرت عائشہ رضی اللہ عنہا سے کہا:مجھے کوئی ایسی چیز بیان کیجیے جس کے ساتھ رسول اللہ صلی اللہ علیہ وسلم اپنی نماز میں دعا فرمایا کرتے تھے۔ انھوں نے کہا: ضرور، رسول اللہ صلی اللہ علیہ وسلم یوں پڑھا کرتے تھے: [اللھم! انی عوذبک من شرما عملت ومن شرما لم أعمل] ’’اے اللہ! میں تیری پناہ چاہتا ہوں ان برے کاموں کے شر سے جو میں نے کیے اور جو ابھی نہیں کیے۔‘‘","f2":"(۱) یہ معنی بھی ہوسکتے ہیں کہ برے کام کرنے اور نیک کام نہ کرنے کے شر سے اللہ کی پناہ چاہتا ہوں۔ تیسرے معنی یہ ہوسکتے ہیں کہ میں اپنے کاموں کے شر سے بھی تیری پناہ چاہتا ہوں اور ان کاموں اور چیزوں کے شر سے بھی جن کا میرے عمل سے تعلق نہیں۔ وہ دوسرے لوگوں کا فعل ہو یا اللہ تعالیٰ کا، یعنی قضا و قدر۔ دوسروں لوگوں کے فعل (مثلاً: ان کے حسد، بغض، معصیت وغیرہ) سے بھی تو انسان کو شر پہنچ سکتا ہے۔ واللہ أعلم۔ (۲) نبی صلی اللہ علیہ وسلم اکثر اللہ تعالیٰ کی پناہ طلب کرتے رہتے تھے۔ آپ نے اس سے امت کو یہ تعلیم دی ہے کہ ہمہ وقت اللہ کی پناہ طلب کرتے رہا کرو کیونکہ اللہ کی پکڑ سے صرف جانب وخاسر لوگ ہی بے خوف ہوتے ہیں۔"}],[1308,"ام المؤمنین عائشہ رضی اللہ عنہا کہتی ہیں کہ میں نے رسول اللہ صلی اللہ علیہ وسلم سے قبر کے عذاب کے بارے میں دریافت کیا تو آپ نے فرمایا: \"ہاں، قبر کا عذاب برحق ہے\"، اس کے بعد میں نے رسول اللہ صلی اللہ علیہ وسلم کو کوئی نماز پڑھتے ہوئے نہیں دیکھا جس میں آپ نے قبر کے عذاب سے پناہ نہ مانگی ہو۔","الألباني: صحيح",{"u2":"حضرت عائشہ رضی اللہ عنہا فرماتی ہیں کہ میں نے رسول اللہ صلی اللہ علیہ وسلم سے قبر کے عذاب کے بارے میں پوچھا تو آپ نے فرمایا: ’’ہاں، عذاب قبر برحق ہے۔‘‘ حضرت عائشہ رضی اللہ عنہا بیان کرتی ہیں کہ اس کے بعد میں نے رسول اللہ صلی اللہ علیہ وسلم کو جو بھی نماز پڑھتے دیکھا، آپ اس میں عذاب قبر سے پناہ مانگتے تھے۔","f2":"(۱) عذاب قبر سے مراد قبر کا جہنم سے کچھ حد تک متعلق ہو جانا ہے جس کی بنا پر قبر کی زندگی اجیرن ہو جائے گی، نیز جوابات نہ آنے پر فرشتوں کی طرف سے سزا اور بعض اعمال کی جزوی سزا، مثلاً: پیشاب کے چھینٹوں سے پرہیز نہ کرنا اور چغلیاں کرنا قبر میں بھی سزا کا مستوجب بناتا ہے۔ اس قسم کا عذاب سب کو نہیں ہوگا۔ اللہ تعالیٰ کے نیک بندے اس سے محفوظ رہیں گے۔ بلکہ اس کے مقابل انھیں ثواب قبر ہوگا۔ واللہ أعلم۔ (۲) نماز میں عذاب قبر سے پناہ مانگنا مشروع ہے۔ (۳) اس حدیث مبارکہ سے ثابت ہوتا ہے کہ عذاب قبر برحق ہے۔ (۴) اس سے یہ بھی معلوم ہوا کہ اللہ تعالیٰ نے نبیٔ اکرم صلی اللہ علیہ وسلم کی اگلی پچھلی ساری لغزشیں معاف کر دیں تھیں: [قد غفرلہ ما تقدم من ذنبہ و ماتاخر] اس کے باوجود آپ کس قدر اللہ کے عذاب سے ڈرتے تھے اور استغفار کرتے رہتے تھے جبکہ ہم گناہوں کی دلدل میں پھنسے ہوئے ہیں، ہمیں تو بالا ولیٰ کثرت سے استغفار اور توبہ کرتے رہنا چاہیے اور اللہ کی پکڑ سے پناہ مانگنی چاہیے۔"}],[1309,"ام المؤمنین عائشہ رضی اللہ عنہا کہتی ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نماز میں دعا مانگتے: «اللہم إني أعوذ بك من عذاب القبر وأعوذ بك من فتنة المسيح الدجال وأعوذ بك من فتنة المحيا والممات اللہم إني أعوذ بك من المأثم والمغرم» \"اے اللہ! میں تجھ سے پناہ مانگتا ہوں قبر کے عذاب سے، اور پناہ مانگتا ہوں مسیح دجال کے فتنہ سے، اور میں تیری پناہ چاہتا ہوں زندگی اور موت کے فتنہ سے، اے اللہ! میں تجھ سے گناہ اور قرض سے پناہ چاہتا ہوں\" تو کہنے والے نے آپ سے کہا: آپ قرض سے اتنا زیادہ کیوں پناہ مانگتے ہیں، تو آپ صلی اللہ علیہ وسلم نے فرمایا: \"آدمی جب مقروض ہوتا ہے تو بات کرتا ہے تو جھوٹ بولتا ہے، اور وعدہ کرتا ہے تو اس کے خلاف کرتا ہے\"۔","الألباني: صحيح",{"u2":"حضرت عائشہ رضی اللہ عنہا فرماتی ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نماز میں یہ دعا پڑھتے تھے: [اللھم! إنی أعوذبک من عذاب القبر ……… والمغرم] ’’اے اللہ! میں قبر کے عذاب سے تیری پناہ چاہتا ہوں اور مسیح دجال کے فتنہ و آزمائش سے تیری پناہ چاہتا ہوں اور زندگی اور موت کے فتنے سے تیری پناہ چاہتا ہوں اور اے اللہ! میں گناہ اور قرض (یا گناہوں کے بوجھ) سے تیری پناہ چاہتا ہوں۔‘‘ کسی کہنے والے نے آپ سے کہا: آپ قرض سے کس قدر زیادہ پناہ طلب کرتے ہیں! آپ نے فرمایا: ’’جب کوئی آدمی مقروض ہو جاتا ہے، پھر بات کرتا ہے تو جھوٹ بولتا ہے اور وعدہ کرتا ہے تو وعدہ خلافی کرتا ہے۔‘‘","f2":"(۱) ’’مسیح دجال‘‘ احادیث صحیحہ سے معلوم ہوتا ہے کہ قیامت سے قبل ایک شخص دنیا پر غلبہ حال کر لے گا۔ وہ دنیوی طور پر ترقی یافتہ ہوگا اور لوگوں کو اپنے سائنسی و دیگر کمالات سے مرعوب کرے گا۔ دینی طور پر وہ رب ہونے کا دعویٰ کرے گا اور سب لوگوں کو اپنا کلمہ پڑھوانے کی کوشش کرے گا۔ سخت دغا باز اور دھوکے باز ہوگا۔ یہ دجال کے معنی ہیں۔ مسیحاسے اس لیے کہا گیا ہے کہ وہ ممسوح العین (کانا) ہوگا۔ یہودی اسے اپنا نجات دہندہ قرار دیں گے۔ وہ اسی کے انتظار میں ہیں، ورنہ حقیقی مسیح تو کب کا آچکا جسے انھوں نے نہ مانا۔ اس جعلی مسیح کو مانیں گے جو ان میں سے ہوگا۔ دونوں آنکھوں سے عیب ناک ہوگا۔ یہودیوں نے حقیقی مسیح عیسیٰ علیہ السلام کو سولی دینے کی ناپاک جسارت کی تو اللہ تعالیٰ نے انھیں یہودیوں کے شر سے بچانے کے لیے زندہ آسمان پر اٹھا لیا اور قیامت کے نزدیک اللہ تعالیٰ انھیں پھر زمین پر اتارے گا، وہ اس جعلی دھوکے باز مسیح کو قتل کر کے اس کی مسیحیت کا بھانڈا پھوڑ دیں گے اور دنیا کو اس کے ظلم و ستم سے نجات دلائیں گے۔ اس کے قتل سے یہودیت کا خاتمہ ہو جائے گا اور عیسائیت کو عیسیٰ علیہ السلام اپنی زبانی اور اپنے ہاتھوں سے ختم کر دیں گے۔ عیسائیت کے نشان صلیب اور خنزیر کا نام و نشان مٹائیں گے۔ خالص اسلام کا بول بالا ہوگا۔ ان شاء اللہ۔ (۲) ’’زندگی کا فتنہ‘‘ یہ ہے کہ انسان زندگی میں رب تعالیٰ کا نافرمان رہے۔ دین حق سے برگشتہ رہے۔ زندگی کی خوش نمائیوں میں کھو کر حق تعالیٰ سے غافل رہے۔ اور ’’موت کا فتنہ‘‘ یہ ہے کہ مرتے وقت شیطان گمراہ کر دے۔ کلمۂ توحید نصیب نہ ہو۔ بری حالت پر موت آئے۔ العیاذ باللہ۔ ممکن ہے اس عذاب قبر، یعنی سوال و جواب میں ناکامی مراد ہو۔ یا مقلب القلوب نسبت قلوبنا علی دینک۔ (۳) اپنے وسائل سے بڑھ کر قرض اٹھانا کہ بعد میں اس ادا نہ کیا جاسکے، درست نہیں ہے۔ (۴) وعدہ خلافی کرنا اور جھوٹ بولنا حرام ہے۔ (۵) مذکورہ اشیاء سے اللہ تعالیٰ کی پناہ مانگتے رہنا چاہیے۔"}],[1310,"ابوہریرہ رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"جب تم میں سے کوئی تشہد پڑھے، تو وہ چار چیزوں سے اللہ کی پناہ چاہے: جہنم کے عذاب سے، قبر کے عذاب سے، زندگی اور موت کے فتنے سے، اور مسیح دجال کے شر سے، پھر وہ اپنے لیے جو جی چاہے دعا کرے\"۔","الألباني: صحيح",{"u2":"حضرت ابوہریرہ رضی اللہ عنہ سے مروی ہے، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’جب تم میں سے کوئی نمازی تشہد پڑھ چکے تو ان چار چیزوں سے اللہ تعالیٰ کی پناہ طلب کرے: جہنم کے عذاب، قبر کے عذاب، زندگی اور موت کی آزمائش اور مسیح دجال کے شر سے، پھر اس کے بعد (منقول دعاؤں میں سے) اپنے لیے اپنی پسندیدہ دعا کرے۔‘‘","f2":"بعض حضرات نے ظاہر الفاظ سے استدلال کرتے ہوئے اس تعوذ کو واجب قرار دیا ہے، ابن حزم اور امام طاوس رحمہا اللہ کا یہی موقف ہے۔ شیخ البانی رحمہ اللہ بھی اس کے قائل ہیں۔ دیکھیے: (اصل صفۃ الصلاۃ: ۹۹۸/۳، ۹۹۹) جبکہ جمہور اہل علم کی دلیل وہ احادیث ہیں جن میں ہے کہ آپ نے اس کے بغیر نماز پڑھی یا سکھلائی ہے یا اسے کامل قرار دیا ہے۔ اس ایک روایت کے ایسے معنی مراد نہیں لیے جا سکتے جو باقی تمام احادیث کے خلاف ہوں، لہٰذا جمہور اہل علم کے نزدیک اس دعا کا پڑھنا مستحب ہے۔ اس قسم کے (امر و حکم کے) الفاظ استحباب و تاکید کے لیے بھی آ جایا کرتے ہیں۔ باقی احادیث کے پیش نظر یہاں یہی معنی مراد ہیں۔ واللہ أعلم۔"}],[1311,"جابر رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم تشہد کے بعد اپنی نماز میں کہتے تھے: «أحسن الكلام كلام اللہ وأحسن الهدى هدى محمد صلى اللہ عليه وسلم» \"سب سے عمدہ کلام اللہ کا کلام ہے، اور سب سے بہتر طریقہ محمد صلی اللہ علیہ وسلم کا طریقہ ہے\"۔","الألباني: صحيح الإسناد",{"u2":"حضرت جابر رضی اللہ عنہ سے منقول ہے کہ رسول اللہ صلی اللہ علیہ وسلم اپنی نماز میں تشہد کے بعد یہ الفاظ کہتے تھے: (وأحسن الکلام کلام اللہ و أحسن الھدی ھدی محمد صلی اللہ علیہ وسلم] ’’سب سے بہترین کلام اللہ تعالیٰ کا کلام ہے اور سب سے اچھا طریقہ محمد صلی اللہ علیہ وسلم کا طریقہ ہے۔‘‘","f2":"خطبۂ وعظ میں تشہد کے بعد تو یہ الفاظ بہت جچتے ہیں کیونکہ یہ وعظکی تمہید ہیں مگر نماز کے تشہد کے بعد ان الفاظ کی مناسبت معلوم نہیں ہوتی۔ امام نسائی رحمہ اللہ کا اس حدیث سے نماز والے تشہد کے بعد اس ذکر کے پڑھنے کااستدلال کرنا محل نظر ہے۔ اس سےمراد خطبے کا تشہد (شہادتین) ہے جیسا کہ مسند احمد کی روایت سے صراحت ہوتی ہے: [کان یقول في خطبتہ بعد التشھد: ان احسن الحدیث کتاب اللہ عزوجل واحسن الھدی ھدی محمد………] ’’نبی صلی اللہ علیہ وسلم اپنے خطبے میں شہادتینکے بعد یہ الفاظ: [ان احسن الحدیث………] پڑھا کرتے تھے۔‘‘ (مسند أحمد: ۳۱۹/۳) نیز یہاں’’الصلاۃ‘‘ سے مراد خطبہ ہے جیسا کہ مندرجہ بالا حدیث سے ظاہر ہوا۔ اور خطبے کی صلاۃ اس لیے کہا کہ یہ اس کے مقدمات اور مبادیات میں سے ہے، جیسا کہ خطبہ جمعہ ہے۔ واللہ أعلم۔ مزید دیکھیے: (ذخیرۃ العقبی شرح النسائي: ۲۶۴/۱۵)"}],[1312,"حذیفہ رضی اللہ عنہ سے روایت ہے کہ انہوں نے ایک آدمی کو دیکھا کہ وہ نماز پڑھ رہا ہے، اور اچھی طرح نہیں پڑھ رہا ہے، اس میں وہ کمی کر رہا ہے، تو حذیفہ رضی اللہ عنہ نے اس سے پوچھا: اس طرح سے نماز تم کب سے پڑھ رہے ہو؟ اس نے کہا: چالیس سال سے، تو انہوں نے کہا: تم نے چالیس سال سے کامل نماز نہیں پڑھی، اور اگر تم اسی طرح نماز پڑھتے ہوئے مر جاتے تو تمہارا خاتمہ محمد صلی اللہ علیہ وسلم کی ملت کے علاوہ پر ہوتا، پھر انہوں نے کہا: آدمی ہلکی نماز پڑھے لیکن پوری اور اچھی پڑھے۔\n§وضاحت\n۱؎: نماز میں تطفیف :(تقصیر و کوتاہی ) یہ ہے کہ رکوع، و سجود اور قیام کو قدر واجب سے کم کرے، اور دونوں سجدوں کے بیچ میں اچھی طرح سے نہ ٹھہرے اسی طرح رکوع کے بعد سیدھا کھڑا نہ ہو، یہ مذموم ہے، اور نماز میں تخفیف یہ ہے کہ رکوع، سجود اور قیام وغیرہ اچھی طرح کرے، لیکن لمبی سورتوں کے بجائے مختصر سورتیں پڑھے، ایسا کرنا درست ہے اس میں کوئی قباحت نہیں۔","الألباني: صحيح الإسناد",{"u2":"حضرت حذیفہ رضی اللہ عنہ سے روایت ہے، انھوں نے ایک آدمی کو ناقص نماز پڑھتے دیکھا۔ حضرت حذیفہ نے اس سے پوچھا: تو کتنے عرصے سے ایسی نماز پڑھ رہا ہے؟ اس نے کہا: چالیس سال سے۔ آپ نے فرمایا: یقین کر چالیس سال سے تو نے نماز پڑھی ہی نہیں اور اگر تو اسی قسم کی نماز پڑھتا پڑھتا مر جاتا تو حضرت محمد صلی اللہ علیہ وسلم کے دین پر فوت نہ ہوتا۔ پھر آپ کہنے لگے: بلاشبہ انسان ہلکی نماز پڑھنے کے باوجود مکمل اور اچھے طریقے سے نماز پڑھ سکتا ہے۔","f2":"(۱) وہ شخص نماز تیز تیز پڑھتا تھا اور اطمینان و سکون نہیں کرتا تھا۔ بخاری میں ہے: [لایتم الرکوع والسجود] ’’وہ رکوع و سجود مکمل نہیں کر رہا تھا‘‘ (صحیح البخاري، الأذان، حدیث: ۷۹۱) یہ روایت مصنف عبدالرزاق (حدیث: ۳۷۳۲، ۳۷۳۳) میں بھی ہے۔ اس میں ہے کہ وہ ٹھونگیں مار رہا تھا۔ ’’ینقرفیھا‘‘ ایک اور روایت میں اس قسم کینماز کو ’’ٹھونگے مارنے‘‘ سے تشبیہ دی گئی ہے اور اسے منافق کی نماز بھی کہا گیا ہے۔ (صحیح مسلم، المساجد، حدیث: ۶۲۲) اس لیے حضرت حذیفہ رضی اللہ عنہ نے اس نماز کو کالعدم قرار دیا ہے اور جب نماز ہی نہ ہوئی تو اس کی موت اسلام کی موت نہیں کیونکہ نماز کے بغیر دین نہیں۔ ممکن ہے آپ نے زجر کے طور پر سخت الفاظ استعمال کیے ہوں تاکہ وہ کامل نماز پڑھے۔ (۲) ہلکی نماز سے مراد قراءت میں تخفیف ہے۔ رکوع، قومہ، سجدہ اور جلسہ مکمل ہونے چاہئیں، یعنی تمام ارکان میں سکون و اطمینان اختیار کیا جائے۔ (۳) نماز میں کمی کرنا یاناقص ادا کرنا حرام ہے۔ (۴) جو شخص نماز کے ارکان و واجبات مکمل نہ کرے، اسے بے نماز ہی شمار کیا جائے گا۔ (۵) جب صحابی سنۃ محمد افطرۃ محمد کہے تو وہحدیث مرفوع کے حکم میں ہوتی ہے۔"}],[1313,"یحیی اپنے چچا بدری صحابی سے روایت کرتے ہیں کہ انہوں نے ان سے بیان کیا کہ ایک آدمی مسجد میں آیا اور نماز پڑھنے لگا، رسول اللہ صلی اللہ علیہ وسلم اسے دیکھ رہے تھے، اور ہم نہیں سمجھ رہے تھے، جب وہ نماز پڑھ کر فارغ ہوا، تو وہ رسول اللہ صلی اللہ علیہ وسلم کے پاس آیا، اور آ کر اس نے آپ کو سلام کیا، آپ نے (جواب دینے کے بعد) فرمایا: \"واپس جاؤ دوبارہ نماز پڑھو کیونکہ تم نے نماز نہیں پڑھی ہے\"، چنانچہ وہ واپس گیا، اور اس نے پھر سے نماز پڑھی، پھر وہ رسول اللہ صلی اللہ علیہ وسلم کے پاس آیا، آپ صلی اللہ علیہ وسلم نے پھر فرمایا: \"واپس جاؤ اور پھر سے نماز پڑھو کیونکہ تم نے (ابھی بھی) نماز نہیں پڑھی ہے\"، دو یا تین بار ایسا ہوا تو اس آدمی نے آپ سے عرض کیا: اللہ کے رسول! قسم ہے اس ذات کی جس نے آپ کو عزت دی ہے، میں اپنی بھر کوشش کر چکا ہوں لہٰذا آپ مجھے سکھا دیجئیے، آپ صلی اللہ علیہ وسلم نے فرمایا: \"جب تم نماز پڑھنے کا ارادہ کرو تو وضو کرو اور اچھی طرح سے وضو کرو، پھر قبلہ رو ہو کر تکبیر تحریمہ کہو، پھر قرآن پڑھو، پھر رکوع کرو اور اطمینان سے رکوع کرو، پھر رکوع سے سر اٹھاؤ یہاں تک کہ سیدھے کھڑے ہو جاؤ پھر سجدہ کرو یہاں تک کہ اطمینان سے سجدہ کر لو، پھر سجدہ سے سر اٹھاؤ یہاں تک کہ اطمینان سے بیٹھ جاؤ، پھر سجدہ کرو یہاں تک کہ اطمینان سے سجدہ کر لو، پھر سر اٹھاؤ، پھر اس کے بعد دوسری رکعت میں اسی طرح کرو یہاں تک کہ تم نماز سے فارغ ہو جاؤ\"۔","الألباني: حسن صحيح",{"u2":"ایک بدری صحابی (حضرت رفاعہ بن رافع) رضی اللہ نے بیان کیا کہ ایک آدمی مسجد میں داخل ہوا اور نماز پڑھنے لگا اور رسول اللہ صلی اللہ علیہ وسلم اسے بغور دیکھنے لگے۔ ہمیں اس بات کا پتہ نہیں تھا۔ جب وہ نماز سے فارغ ہوا تو رسول اللہ صلی اللہ علیہ وسلم کی طرف آیا اور سلام کہا۔ آپ نے فرمایا: ’’واپس جا، دوبارہ نماز پڑھ، تو نے نماز نہیں پڑھی۔‘‘ وہ واپس گیا اور دوبارہ نماز پڑھی، پھر رسول اللہ صلی اللہ علیہ وسلم کے پاس آیا۔ آپ نے پھر فرمایا: ’’واپس جا، پھر نماز پڑھ، تو نے نماز نہیں پڑھی۔‘‘ دو تین دفعہ ایسا ہی ہوا۔ آخر وہ آدمی کہنے لگا: اے اللہ کے رسول! قسم اس ذات کی جس نے آپ کو عزت بخشی! میں تو (بار بار نماز پڑھ کر) تھک گیا ہوں، لہٰذا مجھے سکھا دیجیے۔ آپ نے فرمایا: ’’جب تو نماز کے ارادے سے کھڑا ہو تو وضو کر اور اچھی طرح وضو کر، پھر قبلے کی طرف منہ کر اور اللہاکبر کہہ، پھر قراءت کر، پھر رکوع کر اور اطمینان سے رکوع کر، پھر سر اٹھا حتی کہ سیدھا کھڑا ہو جائے، پھر سجدہ کر حتی کہ اطمینان سے سجدہ کرے، پھر سر اٹھا حتی کہ تو اطمینان سے بیٹھ جائے، پھر سجدہ کر حتی کہ اطمینان سے سجدہ کرے، پھر سر اٹھا، پھر (ہر رکعت میں) ایسے ہی کر حتی کہ تو اپنی نماز سے فارغ ہو جائے۔‘‘","f2":"اس حدیث میں رسول اللہ صلی اللہ علیہ وسلم نے نماز کے فرض کام بیان کیے ہیں یا وہ کام جن میںوہ صحابی سستی کرتا تھا۔ دونوں صورتوں میں ان کاموں کے بغیر نماز نہیں ہوتی کیونکہ آپ نے فرمایا تھا: ’’تیری نماز نہیں ہوئی۔‘‘ (باقی مباحث کے لیے دیکھیے، حدیث: ۱۰۵۴)"}],[1314,"یحیی بن خلاد بن رافع بن مالک انصاری کہتے ہیں کہ مجھ سے میرے چچا بدری صحابی روایت کرتے ہیں وہ کہتے ہیں کہ میں رسول اللہ صلی اللہ علیہ وسلم کے ساتھ مسجد میں بیٹھا ہوا تھا کہ ایک آدمی مسجد میں داخل ہوا، اور اس نے دو رکعت نماز پڑھی، پھر وہ آیا، اور اس نے نبی اکرم صلی اللہ علیہ وسلم کو سلام کیا، آپ صلی اللہ علیہ وسلم اسے نماز پڑھتے ہوئے دیکھ رہے تھے، آپ نے سلام کا جواب دیا، پھر اس سے فرمایا: \"واپس جاؤ اور نماز پڑھو کیونکہ تم نے نماز نہیں پڑھی ہے\"، چنانچہ وہ واپس آیا، اور پھر سے اس نے نماز پڑھی، پھر وہ دوبارہ آیا اور اس نے نبی اکرم صلی اللہ علیہ وسلم کو سلام کیا، آپ نے اسے جواب دیا، پھر فرمایا: \"واپس جاؤ اور نماز پڑھو کیونکہ تم نے نماز نہیں پڑھی ہے\"، یہاں تک کہ تیسری یا چوتھی بار میں اس نے عرض کیا: قسم ہے اس ذات کی جس نے آپ پر کتاب نازل کی ہے، میں اپنی کوشش کر چکا ہوں، اور میری خواہش ہے آپ مجھے (صحیح نماز پڑھنے کا طریقہ) دکھا، اور سکھا دیجئیے، آپ نے فرمایا: \"جب تم نماز کا ارادہ کرو تو پہلے اچھی طرح وضو کرو پھر قبلہ رو ہو کر تکبیر تحریمہ کہو پھر قرآت کرو پھر رکوع میں جاؤ اور رکوع میں رہو یہاں تک کہ تمہیں اطمینان ہو جائے، پھر سر اٹھاؤ یہاں تک کہ تم سیدھے کھڑے ہو جاؤ، پھر سجدہ میں جاؤ اور اطمینان سے سجدہ کرو، پھر سر اٹھاؤ یہاں تک کہ تم آرام سے بیٹھ جاؤ، پھر سجدہ کر اور سجدہ میں رہو یہاں تک کہ تمہیں اطمینان ہو جائے، پھر سر اٹھاؤ تو جب تم اپنی نماز کو اس نہج پر پورا کرو گے تو وہ مکمل ہو گی، اور اگر تم نے اس میں سے کچھ کمی کی تو تم اپنی نماز میں کمی کرو گے۔","الألباني: صحيح",{"u2":"ایک بدری صحابی (حضرت رفاعہ بن رافع) رضی اللہ عنہ نے فرمایا: میں رسول اللہ صلی اللہ علیہ وسلم کے ساتھ مسجد میں بیٹھا تھا کہ ایک آدمی داخل ہوا اور اس نے دو رکعتیں پڑھیں، پھر وہ نبی صلی اللہ علیہ وسلم کے پاس آیا اور آپ کو سلام کہا جب کہ نبی صلی اللہ علیہ وسلم اسے نماز میں دیکھتے رہے تھے۔ آپ نے اسے سلام کا جواب دیا اور فرمایا: ’’واپس جا، دوبارہ نماز پڑھ، تو نے نماز نہیں پڑھی۔‘‘ وہ واپس گیا، پھر نماز پڑھی، پھر نبی صلی اللہ علیہ وسلم کے پاس آیا اور آپ کو سلام کہا۔ آپ نے اسے سلام کا جواب دیا اور فرمایا: ’’واپس جا، پھر نماز پڑھ، تو نے نماز نہیں پڑھی۔ حتی کہ تیسری یا چوتھی دفعہ ہوئی تو اس نے کہا: قسم اس ذات کی جس نے آپ پر کتاب اتاری! میں تو (بار بار نماز پڑھ کر) تھک گیا ہوں۔ میری خواہش ہے کہ آپ مجھے (نماز پڑھ کر) دکھائیں اور مجھے سکھلا دیں۔ آپ نے فرمایا: ’’جب تو نمز کا ارادہ کرے تو وضو کر اور بہترین وضو کر، پھر قبلے کی طرف منہ کر اور اللہ أکبر کہہ، پھر قرآن (کم از کم فاتحہ) پڑھ، پھر رکوع کر حتی کہ تجھے رکوع میں اطمینان حاصل ہو، پھر سر اٹھا حتی کہ سیدھا کھڑا ہوجائے، پھر سجدہ کر حتی کہ تجھے سجدے میں اطمینان حاصل ہو، پھر سر اٹھا حتی کہ تو اطمینان سے بیٹھ جائے، پھر دوسرا سجدہ کر حتی کہ تجھے سجدے میں اطمینان حاصل ہو، پھر سر اٹھا، پھر جب تو اس طریقے سے نماز مکمل کرلے تو تیری نماز مکمل اور صحیح ہو جائے گی۔ اور جو تو ان کاموں میں کمی کرے گا تو یقیناً اپنی نماز ہی میں نقص ڈالےگا۔‘‘","f2":"بعض روایات میں صراحت ہے کہ اس نے تین دفعہ نماز پڑھی تھی۔ (مزید تفصیل کے لیے دیکھیے، حدیث: ۱۰۵۴)"}],[1315,"سعد بن ہشام کہتے ہیں کہ میں نے عرض کیا: ام المؤمنین! مجھے رسول اللہ صلی اللہ علیہ وسلم کے وتر کے بارے میں بتائیے، تو انہوں نے کہا: ہم آپ کے (تہجد کے)لیے مسواک اور وضو کا پانی تیار رکھتے تھے تو اللہ تعالی جب آپ کو رات میں بیدار کرنا چاہتا بیدار کر دیتا، آپ اٹھ کر مسواک کرتے، اور وضو کرتے، اور آٹھ رکعتیں پڑھتے ۱؎، ان میں صرف آٹھویں رکعت میں بیٹھتے، اللہ عزوجل کا ذکر کرتے، اور دعائیں کرتے، پھر اتنی اونچی آواز میں آپ سلام پھیرتے کہ ہمیں سنا دیتے۔\n§وضاحت\n۱؎: یہ رواۃ میں سے کسی راوی کا وہم ہے جیسا کہ مؤلف آگے چل کر حدیث رقم ۱۶۰۲ میں اس پر تنبیہ کریں گے، صحیح \"نو رکعتیں\" ہے۔","الألباني: صحيح",{"u2":"حضرت سعد بن ہشام بیان فرماتے ہیں کہ میں نے حضرت عائشہ رضی اللہ عنہا سے کہا: اے ام المومنین! مجھے رسول اللہ صلی اللہ علیہ وسلم کے وتر (رات کی نفل نماز) کے بارے میں بتائیے۔ انھوں نے فرمایا: ہم آپ کے لیے آپ کی مسواکِ اور وضو کا پانی تیار کرکے رکھ دیتے تھے۔ جب اللہ تعالیٰ چاہتا آپ کو جگاتا۔ آپ اٹھ کر مسواک کرتے، وضو فرماتے اور آٹھ رکعات پڑھتے۔ ان میں آپ تشہد کے لیےنہیں بیٹھتے تھے مگر آٹھویں رکعت کے بعد۔ پھر اللہ تعالیٰکا ذکر فرماتے اور دعائیں پڑھتے۔ پھراتنی آواز سے سلام کہتے کہ ہم سن لیتے۔","f2":"(۱) ’’نہیں بیٹھتے تھے‘‘گویا نفل نمازم یں اگر ہر دو رکعت کے بعد نہ بیٹھے، صرف آخری رکعت کے بعد بیٹھ جائے اور تشہد وغیرہ پڑھ لے تو کافی ہے، نماز میں ہو جائے گی، البتہ فرض نماز میں ہر دو رکعت کے بعد تشہد بیٹھنا چاہیے۔ اگربھول جائے تو نماز ہو جائے گی مگر سجدۂ سہو ضروری ہے۔ قصداً چھوڑے تو نماز دہرائے۔ (۲) ’’آٹھ رکعات پڑھتے‘‘ وتر اس کےعلاوہ پڑھتے۔ وتر (طاق نماز) پڑھنے کے بعد پہلے پڑھے ہوئے سب نوافل بھی وتر میں شامل ہو جائیں گے کیونکہ نماز ایک ہی ہے۔ صرف رکعات کی تعداد (طاق) کے مدنظر اسے وتر کہہ دیتے ہیں ورنہ یہ سب صلاۃ اللیل ہے، تاہم خالی وتر کے لیے بعض نے کم از کم تین کی حد مقرر کی ہے مگر آپ صلی اللہ علیہ وسلم اور بعض صحابۂ کرام رضی اللہ عنہم سے صرف ایک رکعت بھی ثابت ہے، لہٰذا ایک رکعت پڑھنا بھی جائز ہے۔ لیکن اس پرہمیشگی اسوۂ رسول صلی اللہ علیہ وسلم نہیں۔"}],[1316,"سعد رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم (نماز میں) اپنے دائیں اور بائیں سلام پھیرتے تھے۔","الألباني: صحيح",{"u2":"حضرت سعد رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم (نماز کے آخر میں) دائیں بائیں (منہ موڑتے تھے اور) سلام کہتے تھے۔"}],[1317,"سعد رضی اللہ عنہ کہتے ہیں کہ میں رسول اللہ صلی اللہ علیہ وسلم کو دیکھتا تھا کہ آپ اپنے دائیں اور بائیں سلام پھیرتے یہاں تک کہ آپ کے رخسار کی سفیدی دیکھی جاتی۔ ابوعبدالرحمٰن (نسائی) کہتے ہیں: عبداللہ بن جعفر مخرمی میں کوئی حرج نہیں یعنی قابل قبول راوی ہیں، اور علی بن مدینی کے والد عبداللہ بن جعفر بن نجیح، متروک الحدیث ہیں۔","الألباني: صحيح",{"u2":"حضرت سعد رضی اللہ عنہ بیان کرتے ہیں کہ میں رسول اللہ صلی اللہ علیہ وسلم کو دیکھتا تھا کہ آپ (نماز کے اختتام پر) دائیں اور بائیں سلام کہتے تھے اور اس قدر منہ موڑتے تھے کہ آپ کے رخسار اطہر کی سفیدی نظر آنے لگتی تھی۔\nامام ابوعبدالرحمٰن (نسائی) رحمہ اللہ بیان کرتے ہیں کہ یہ (راویٔ حدیث) عبداللہ بن جعفر معتبر راوی ہیں، البتہ علی بن مدینی کے والد عبداللہ بن جعفر بن نجیح متروک ہیں۔ (ان کی حدیث معتبر نہیں ہے۔)","f2":"(۱) اس حدیث کے راوی عبداللہ بن جعفر مخرمی ہیں جو ثقہ ہیں۔ ایک دوسرے عبداللہ بن جعفر ہیں جو مشہور محدث اور نقاد حضرت علی بن مدینی کے والد محترم ہیں لیکن وہ اپنے کمزور حافظے کی وجہ سے علم حدیث میں قابل اعتبار نہیں۔ چونکہ اشتباہ کا خطرہ تھا، اس لیےامام صاحب نے وضاحت فرمائی۔ جزاہ اللہ خیرا۔ (۲) اسلام دونوں جانب کہنا چاہیے۔ کثیر روایات اسی پر دال ہیں۔ لیکن نماز کے آخر میں صرف ایک طرف سلام کہنا بھی جائز ہے کیونکہ رسول اللہ صلی اللہ علیہ وسلم سے ایک طرف سلام کہنا بھی ثابت ہے۔ تفصیل کے لیے دیکھیے: (سلسلۃالأحادیث الصحیحۃ: ۶۲۸/۱، حدیث: ۳۱۶) جبایک سلام کہنا ہو تو سامنے کی طرف منہ کرکے سلام کہا جائے، پھر چہرے کو دائیں جانب مائل کرلیں۔ واللہ أعلم۔"}],[1318,"جابر بن سمرہ رضی اللہ عنہ کہتے ہیں کہ جب ہم نبی اکرم صلی اللہ علیہ وسلم کے پیچھے نماز پڑھتے تو ہم سلام پھیرتے وقت «السلام عليكم السلام عليكم» کہتے تھے، (مسعر نے اپنے ہاتھ سے دائیں بائیں دونوں طرف اشارہ کر کے بتایا) تو آپ نے فرمایا: \"ان لوگوں کو کیا ہو گیا ہے جو اپنے ہاتھ اس طرح کرتے ہیں گویا شریر گھوڑوں کی دم ہیں، کیا یہ کافی نہیں کہ وہ اپنے ہاتھ اپنی ران پر رکھیں، پھر وہ اپنے دائیں طرف اور اپنے بائیں اپنے بھائی کو سلام کریں\"۔","الألباني: صحيح",{"u2":"حضرت جابر بن سمرہ رضی اللہ عنہ بیان کرتے ہیں کہ (ابتدا میں) جب ہم نبی صلی اللہ علیہ وسلم کےپیچھے نماز پڑھتے تھے تو ہم [السلام علیکم، السلام علیکم] کہتے اور ساتھ ہاتھوں کو بھی دائیں بائیں اٹھاتے تھے۔ (یعنی دائیں طرف سلام کے وقت دائیں طرف اور بائیں طرف سلام کے وقت بائیں طرف ہاتھ اٹھاتے۔) آپ نے(دیکھا تو) فرمایا: ’’انھیں کیا ہے کہ اپنے ہاتھوں سے (دائیں بائیں) اشارے کرتے ہیں جیسے سرکش گھوڑوں کی دمیں ہیں۔ کیا یہ کافی نہیں کہ نمازی اپنے ہاتھ اپنی رات ہی پر رکھے اور زبان سے اپنے دائیں اور بائیں اپنے ساتھیوں کو سلام کہہ دے۔‘‘","f2":"اس حدیث سے واضح ہے کہ نبی صلی اللہ علیہ وسلم کا رفع الیدین کو سرکش گھوڑوں کی دموں سے تعبیر کرنا، سلام کے وقت ہاتھوں سے سلام کرنے سے متعلق ہے۔ اس کا اس رفع الیدین سے کوئی تعلق نہیں ہے جو رکوع میں جاتے اور رکوع سے اٹھتے وقت کیا جاتا ہے۔ اسے اس رفع الیدین سے جوڑ کر یہ کہنا کہ اس سے نبی صلی اللہ علیہ وسلم نے روک دیا تھا، علمی خیانت ہے۔ أعادنا اللہ منہ۔ (تفصیل کے لیے دیکھیے، حدیث: ۱۱۸۵، ۱۱۶۸)"}],[1319,"عبداللہ بن مسعود رضی اللہ عنہ کہتے ہیں کہ میں نے رسول اللہ صلی اللہ علیہ وسلم کو دیکھا کہ آپ ہر جھکنے اٹھنے اور کھڑے ہونے اور بیٹھنے میں اللہ اکبر کہتے، پھر اپنی دائیں طرف اور بائیں طرف «السلام عليكم ورحمة اللہ السلام عليكم ورحمة اللہ» کہتے ہوئے سلام پھیرتے، یہاں تک کہ آپ کے رخسار کی سفیدی دیکھی جاتی، اور میں نے ابوبکر اور عمر رضی اللہ عنہم کو بھی اسی طرح کرتے ہوئے دیکھا۔","الألباني: صحيح",{"u2":"حضرت عبداللہ بن مسعود رضی اللہ عنہ بیان کرتے ہیں کہ میں نے رسول اللہ صلی اللہ علیہ وسلم کو دیکھا کہ آپ ہر جھکتے، اٹھتے اور کھڑے ہوتے اور بیٹھتے وقت اللہ أکبر کہتے اور اپنے دائیں اور بائیں سلام کہتے: [السلام علیکم و رحمۃ اللہ، السلام علیکم و رحمۃ اللہ] ’’تم پر اللہ تعالیٰ کا سلام اور رحمت ہو۔‘‘ (اور منہ بھی موڑتے تھے) حتی کہ آپ کے رخسار کی سفیدی نظر آتی تھی اور میں نے حضرت ابوبکر و عمر رضی اللہ عنہما کو بھی ایسے کرتے دیکھا ہے۔"}],[1320,"واسع بن حبان سے روایت ہے کہ انہوں نے عبداللہ بن عمر رضی اللہ عنہم سے رسول اللہ صلی اللہ علیہ وسلم کی نماز کے بارے میں سوال کیا، تو انہوں نے کہا: آپ صلی اللہ علیہ وسلم جب جھکتے تو «اللہ أكبر» کہتے، اور جب اٹھتے تو «اللہ أكبر» کہتے، پھر آپ اپنی دائیں طرف «السلام عليكم ورحمة اللہ» کہتے اور اپنی بائیں طرف «السلام عليكم ورحمة اللہ» کہتے۔","الألباني: صحيح الإسناد",{"u2":"حضرت واسع بن حبان نے حضرت عبداللہ بن عمر رضی اللہ عنہما سے رسول اللہ صلی اللہ علیہ وسلم کی نماز کے بارے میں پوچھا تو انھوں نے فرمایا: آپ جب جھکتے تھے تو اللہ أکبر کہتے تھے اور جب سر اٹھاتے تھے، تب بھی اللہ أکبر کہتے تھے۔ پھر (نماز کے اختتام پر) دائیں طرف منہ کرکے کہتے: [السلام علیکم و رحمۃ اللہ] اور بائیں طرف منہ کرکے کہتے: [السلام علیکم و رحمۃ اللہ]","f2":"شریعت اسلامیہ نے جس طرح نماز کا آغاز اللہ أکبر جیسے بارعب جملے سے کیا تھا جو کہ نمازی کو لوگوں سے منقطع کرنے اور اللہ تعالیٰ سے جوڑنے پر دلالت کرتا ہے اس طرح، اس کے مقابلے میں نماز کا اختتام [السلام علیکم و رحمۃ اللہ] جیسے پرلطف جملے سے کیا جو نمازی کا تعلق پھر سے لوگوں کے ساتھ بطریق احسن جوڑ دیتا ہے۔ یہ نماز کے اختتام کا اعلان بھی ہے اور لوگوں کے ساتھ کلام کا آغاز بھی اور وہ بھی بہترین انداز میں، یعنی دعائیہ کلمات کے ساتھ۔ چونکہ نماز میں ادھر ادھر دیکھنا منع ہے، لہٰذا نماز کے اختتام پر سلام پھیرنا مشروع ہے۔"}],[1321,"واسع بن حبان کہتے ہیں کہ میں نے ابن عمر رضی اللہ عنہم سے کہا کہ مجھے رسول اللہ صلی اللہ علیہ وسلم کی نماز کے بارے میں بتائیے کہ وہ کیسی ہوتی تھی، تو انہوں نے تکبیر کہی، اور اپنی دائیں طرف «السلام عليكم ورحمة اللہ» کہنے، اور بائیں طرف «السلام عليكم» ۱؎ کہنے کا ذکر کیا۔\n§وضاحت\n۱؎: اس حدیث سے یہ بتانا مقصود ہے کہ آپ داہنی جانب والوں کی تکریم لیے داہنی طرف سلام پھیرتے وقت «ورحمۃاللہ» کا اضافہ فرماتے تھے، اور بائیں طرف «السلام عليكم» ہی پر اکتفا کرتے تھے، پچھلی روایت میں بائیں طرف بھی «ورحمۃاللہ» کہنے کا ذکر ہے، اور اسی پر عمل ہے، شاید آپ کبھی کبھی اسے چھوڑ دیتے رہے ہوں۔","الألباني: حسن صحيح",{"u2":"حضرت واسع بن حبان سے روایت ہے کہ میں نے حضرت عبداللہ بن عمر رضی اللہ عنہما سے کہا: مجھے بتائیے کہ رسول اللہ صلی اللہ علیہ وسلم کی نماز کیسے ہوتی تھی؟ آپ نے ذکر کیا کہ رسول اللہ صلی اللہ علیہ وسلم اللہ أکبر کہتے تھے اور (نماز کے اختتام پر) دائیں طرف السلام علیکم و رحمۃ اللہ کہتے تھے اور بائیں طرف السلام علیکم کہتے تھے۔","f2":"-"}],[1322,"عبداللہ بن مسعود رضی اللہ عنہ کہتے ہیں کہ نبی اکرم صلی اللہ علیہ وسلم نے اپنی دائیں طرف «السلام عليكم ورحمة اللہ» کہا، اور اپنی بائیں طرف«السلام عليكم ورحمة اللہ» کہا، گویا میں آپ کے گال کی سفیدی دیکھ رہا ہوں۔","الألباني: صحيح",{"u2":"حضرت عبداللہ بن مسعود رضی اللہ عنہ بیان کرتے ہیں کہ گویا میں نبی صلی اللہ علیہ وسلم کے رخستار کی سفیدی کو دیکھ رہا ہوں، آپ اپنی دائیں طرف فرماتے: [السلام علیکم و رحمۃ اللہ] اور بائیں طرف فرماتے: [السلام علیکم و رحمۃ اللہ]۔"}],[1323,"عبداللہ بن مسعود رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم اپنی دائیں طرف سلام پھیرتے یہاں تک کہ آپ کے گال کی سفیدی دکھائی دیتی، اور آپ بائیں طرف سلام پھیرتے یہاں تک کہ آپ کے گال کی سفیدی دکھائی دیتی۔","الألباني: صحيح",{"u2":"حضرت عبداللہ بن مسعود رضی اللہ عنہ بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم دائیں طرف سلام پھیرتے حتی کہ آپ کے رخسار کی سفیدی نظر آتی، پھر بائیں طرف حتی کہ آپ کے رخسار کی سفیدی نظر آتی۔"}],[1324,"عبداللہ بن مسعود رضی اللہ عنہ کہتے ہیں کہ نبی اکرم صلی اللہ علیہ وسلم اپنی دائیں طرف اور بائیں طرف «السلام عليكم ورحمة اللہ السلام عليكم ورحمة اللہ» کہتے ہوئے سلام پھیرتے، اور (آپ اپنے سر کو اتنا گھماتے) کہ آپ کے رخسار کی سفیدی ادھر سے، اور ادھر سے دکھائی دیتی۔","الألباني: صحيح",{"u2":"حضرت عبداللہ بن مسعود رضی اللہ عنہ سے روایت ہے کہ نبی صلی اللہ علیہ وسلم اپنی دائیں اور بائیں طرف سلام پھیرتے (اور کہتے:) [السلام علیکم و رحمۃ اللہ، السلام علیکم و رحمۃ اللہ] حتی کہ دائیں طرف بھی آپ کے رخسار کی سفیدی نظر آتی اور بائیں طرف بھی آپ کے رخسار کی سفیدی نظر آتی۔"}],[1325,"عبداللہ بن مسعود رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم دائیں طرف «السلام عليكم ورحمة اللہ» کہتے ہوئے سلام پھیرتے یہاں تک کہ آپ کے دائیں گال کی سفیدی دکھائی دینے لگتی، اور بائیں طرف «السلام عليكم ورحمة اللہ» کہتے ہوئے سلام پھیرتے یہاں تک کہ آپ کے بائیں گال کی سفیدی دکھائی دینے لگتی۔","الألباني: صحيح",{"u2":"حضرت عبداللہ بن مسعود رضی اللہ عنہ نے بیان کیا کہ رسول اللہ صلی اللہ علیہ وسلم اپنی دائیں طرف سلام پھیرتے (اور کہتے): [السلام علیکم و رحمۃ اللہ] حتی کہ آپ کے دائیں رخسار کی سفیدی نظر آتی، پھر بائیں طرف سلام پھیرتے (اور کہتے:) [السلام علیکم و رحمۃ اللہ] حتی کہ آپ کے بائیں رخسار کی سفیدی نظر آتی۔","f2":"روایات کے تتبع سے سلام کہنے کے چار طریقے ملتے ہیں، ان میں سے کسی ایک پر بھی عمل کر لیا جائے تو درست ہے۔ (۱) دائیں اور بائیں دونوں جانب [السلام علیکم و رحمۃ اللہ] کہنا اور یہ طریقہ زیادہ مشہور اور معمول بہ ہے کیونکہ اکثر روایات میں یہی طریقہ مروی ہے۔ (۲) دائیں اور بائیں دونوں جانب [السلام علیکم و رحمۃ اللہ و برکاتہ] کہنا۔ (۳) دابئیں جانب [السلام علیکم و رحمۃ اللہ] اور بائیں جانب [السلام علیکم] (۴) صرف سامنے کی طرف منہ کرکے [السلام علیکم] کہنا اور چہرے کا میلان تھوڑا سا دائیں جانبہو۔ بعض علماء دائیں جانب [السلام علیکم و رحمۃ اللہ و برکاتہ] اور بائیں جانب [السلام علیکم و رحمۃ اللہ] کہنے کے قائل ہیں لیکن ان کا یہ موقف محل نظر ہے کیونکہ سنن ابی داود کی جس روایتسے صرف دائیں جانب [وبرکاتہ] کا اضافہ ثابت ہے علمائے محققین اس کی بابت فرماتے ہیں کہ سنن ابی داود کے صحیح اور معتمد نسخوں میں دونوں طرف [وبرکاتہ] کا اضافہ منقول ہے۔ بنابریں دائیں اور بائیں دونوں جانب [وبرکاتہ] کہنا چاہیے۔ واللہ أعلم۔ مزید تفصیل کے لیے دیکھیے: (أصل صفۃ صلاۃ النبي، للألباني، ص:۱۰۳۶-۱۰۲۳، وذخیرۃ العقبی شرح سنن النسائي: ۳۰۶-۲۹۶/۱۵)"}],[1326,"جابر بن سمرہ رضی اللہ عنہ کہتے ہیں کہ میں نے رسول اللہ صلی اللہ علیہ وسلم کے ساتھ نماز پڑھی، جب ہم سلام پھیرتے تو اپنے ہاتھوں سے اشارہ کرتے ہوئے کہتے:«السلام عليكم السلام عليكم» رسول اللہ صلی اللہ علیہ وسلم نے ہمیں اس طرح کرتے ہوئے دیکھا تو فرمایا: \"تم لوگوں کو کیا ہو گیا ہے کہ تم لوگ اپنے ہاتھوں سے اشارے کرتے ہو، گویا کہ وہ شریر گھوڑوں کی دم ہیں، جب تم میں سے کوئی سلام پھیرے تو وہ اپنے ساتھ والے کی طرف متوجہ ہو جائے، اور اپنے ہاتھ سے اشارہ نہ کرے\"۔","الألباني: صحيح",{"u2":"حضرت جابر بن سمرہ رضی اللہ عنہ فرماتےہیں کہ میں نے رسول اللہ صلی اللہ علیہ وسلم کے ساتھ نماز پڑھی۔ جب ہم سلام پھیرتے تھے تو ہاتھوں کے ساتھ بھی اشارہ کرتے اور کہتے [السلام علیکم، السلام علیکم] ہمیں اللہ کے رسول صلی اللہ علیہ وسلم نے دیکھ لیا تو آپ نے فرمایا: ’’تمھیں کیا ہوا کہ تم اپنے ہاتھوں سے اشارے کرتے ہو جیسے یہ سرکش گھوڑوں کی دمیں ہیں۔ جب تم میں سے کوئی آدمی (نماز کے آخر میں) سلام کہے تو اپنے ساتھی کی طرف منہ موڑے۔ ہاتھ سے اشارہ نہ کرے۔","f2":"دیکھیے، حدیث: ۱۱۸۶، ۱۳۱۹۔"}],[1327,"محمود بن ربیع رضی اللہ عنہ کہتے ہیں کہ میں نے عتبان بن مالک رضی اللہ عنہ کو کہتے سنا کہ میں اپنی قوم بنی سالم کو نماز پڑھایا کرتا تھا تو میں رسول اللہ صلی اللہ علیہ وسلم کے پاس آیا، اور آپ سے عرض کیا کہ میری آنکھیں کمزور ہو گئی ہیں، اور برسات میں میرے اور میری قوم کی مسجد کے درمیان سیلاب حائل ہو جاتا ہے، لہٰذا میری خواہش ہے کہ آپ میرے گھر تشریف لاتے، اور کسی جگہ میں نماز پڑھ دیتے تو میں اس جگہ کو اپنے لیے مسجد بنا لیتا، نبی اکرم صلی اللہ علیہ وسلم نے فرمایا: \"اچھا ان شاءاللہ عنقریب آؤں گا\"، چنانچہ رسول اللہ صلی اللہ علیہ وسلم خوب دن چڑھ آنے کے بعد میرے پاس تشریف لائے، آپ کے ساتھ ابوبکر رضی اللہ عنہ بھی تھے، نبی اکرم صلی اللہ علیہ وسلم نے اندر آنے کی اجازت مانگی، میں نے آپ کو اندر تشریف لانے کے لیے کہا، آپ بیٹھے بھی نہیں کہ آپ نے پوچھا: \"تم اپنے گھر کے کس حصہ میں چاہتے ہو کہ میں نماز پڑھوں؟\" تو میں نے اس جگہ کی طرف اشارہ کیا جہاں میں چاہتا تھا کہ آپ اس میں نماز پڑھیں، چنانچہ رسول اللہ صلی اللہ علیہ وسلم نماز کے لیے کھڑے ہوئے، اور ہم نے آپ کے پیچھے صف باندھی، پھر آپ نے سلام پھیرا، اور ہم نے بھی سلام پھیرا جس وقت آپ نے سلام پھیرا۔","الألباني: صحيح",{"u2":"حضرت عتبان بن مالک رضی اللہ عنہ بیان کرتے ہیں کہ میں اپنی قوم بنو سالم کو نماز پڑھایا کرتا تھا۔ میں رسول اللہ صلی اللہ علیہ وسلم کے پاس حاضر ہوا اور عرض کیا کہ میں تقریباً نابینا ہوچکا ہوں۔ (موسم برسات میں) بارشی اور سیلابی پانی میرے اور میری قوم کی مسجد کے درمیان رکاوٹ بن جاتا ہے، اس لیے میں چاہتا ہوں کہ آپ تشریف لائیں اور میرے گھر میں کسی جگہ نماز ادا فرمائیں جسے میں (گھریلو) مسجد بنالوں۔ نبی صلی اللہ علیہ وسلم نے فرمایا: ’’ان شاء اللہ میں عنقریب آؤں گا۔‘‘ اگلے دن رسول اللہ صلی اللہ علیہ وسلم میرے پاس تشریف لائے۔ حضرت ابوبکر رضی اللہ عنہ بھی آپ کے ساتھ تھے۔ دن کافی اونچا آچکا تھا، نبی صلی اللہ علیہ وسلم نے اجازت طلب کی۔ میں نے اجازت دے دی۔ آپ بیٹھے نہیں بلکہ فرمایا: ’’تم کس جگہ چاہتے ہو کہ میں نماز پڑھوں؟‘‘ میں نے اس جگہ کی طرف اشارہ کیا جہاں میں چاہتا تھا کہ آپ نماز پڑھیں۔ رسول اللہ صلی اللہ علیہ وسلم کھڑے ہوئے، ہم نے آپ کے پیچھے صف بندی کی، (آپ نے نماز ادا کی) پھر آپ نے سلام پھیرا اور آپ کے سلام پھیرتے ہی ہم نے بھی سلام پھیر دیا۔","f2":"(۱) جب امام سلام کہے تو اگر مقتدی کی نماز مکمل ہوگئی ہے تو وہ بھی سلام کہہ دے۔ اگر اس کی نماز مکمل نہیں ہوئی تو وہ نماز مکمل کرنےکے بعد سلام پھیرے۔ (۲) آدمی کو اگر کوئی تکلیف ہو تو وہ اس کے متعلق بتلا سکتا ہے، یہ شکوہ نہیں سمجھا جائے گا۔ (۳) مدینہ منورہ میں نبی صلی اللہ علیہ وسلم کی مسجد کےعلاوہ بھی مسجدیں تھیں۔ (۴) اگر بارش وغیرہ جیسے شرعی عذر کی بنا پر جماعت رہ جائے تو گناہ نہیں۔ (۵) شرعی عذر کی وجہ سے گھر میں نماز کے لیے جگہ متعین کر لینا جائز ہے۔ (۶) نماز کے لیے صف درست کرنا لازم ہے۔ (۷) اس حدیث مبارکہ سے وعدہ وفا کرنے کی حیثیت نمایاں ہوتی ہے۔ (۸) کسی کے گھر میں داخل ہونے سے پہلے اجازت لینا ضروری ہے، بغیر اجازت کوئی بھی کسی کے گھر میں داخل نہیں ہوسکتا جیسا کہ نبیٔ اکرم صلی اللہ علیہ وسلم اپنے صحابہ کے گھر میں بھی بغیر اجازت داخل نہیں ہوئے تھے۔ اگر صاحب خانہ اندر داخل ہونے کی اجازت نہ دیں تو برا محسوس نہیں کرنا چاہیے۔ (۹) نفل نماز میں جماعت کرانا مشروع ہے۔"}],[1328,"ام المؤمنین عائشہ رضی اللہ عنہا کہتی ہیں کہ رسول اللہ صلی اللہ علیہ وسلم عشاء سے فجر تک کے بیچ میں گیارہ رکعتیں پڑھتے تھے، اور ایک رکعت کے ذریعہ وتر کرتے۱؎، اور ایک سجدہ اتنا لمبا کرتے کہ کوئی اس سے پہلے کہ آپ سجدہ سے سر اٹھائیں پچاس آیتیں پڑھ لے۔ اس حدیث کے رواۃ (ابن ابی ذئب، عمرو بن حارث اور یونس بن یزید) ایک دوسرے پر اضافہ بھی کرتے ہیں اور یہ حدیث ایک لمبی حدیث سے مختصر کی گئی ہے۔\n§وضاحت\n۱؎: مؤلف نے اس سے یہ استدلال کیا ہے کہ یہ سجدہ سلام کے بعد ہوتا تھا، حالانکہ یہاں تہجد کے اندر آپ کے سجدے کی طوالت بیان کرنی مقصود ہے، اس روایت میں صحیح بخاری کی عبارت یوں ہے «فیسجد السجدۃ من ذٰلک قدرما یقرأ أحدکم خمسین آیۃ قبل أن یرفع» :(کتاب الوتر باب ۱ ) یعنی: تہجد میں آپ کا ایک سجدہ اتنا طویل ہوتا تھا کہ کوئی دوسرا اتنے میں پچاس آیتیں پڑھ لے، مؤلف رحمہ اللہ سے اس بابت وہم ہوا ہے عفا اللہ عنہ … ایسے کسی سجدہ کا کوئی بھی قائل نہیں ہے۔","الألباني: صحيح",{"u2":"حضرت عائشہ رضی اللہ عنہا فرماتی ہیں کہ رسول اللہ صلی اللہ علیہ وسلم عشاء کی نماز سے فارغ ہونے کے بعد فجر کے طلوع ہونے تک گیارہ رکعت پڑھتے تھے اور ان میں سے ایک رکعت الگ (سلام سے) پڑھتے اور اتنا لمبا سجدہ کرتے کہ آپ کے سر اٹھانے سے پہلے تم میں سے کوئی شخص پچاس (۵۰) آیات پڑھ سکتا تھا۔\n(ابن وہب فرماتے ہیں) بعض راوی بعض کی نسبت (کچھ) اضافے کے ساتھ یہ حدیث بیان کرتے ہیں۔ یہ حدیث مختصر ہے۔","f2":"(۱) امام صاحب رحمہ اللہ کا اس روایت سے نماز سے فارغ ہونے کے بعد سجدہ کرنے پر استدلال کرنا محل نظر ہے کیونکہ اس روایت میں جو سجدے کا ذکر ہے، اس سے مراد نماز سے فراغت کے بعد کا سجدہ نہیں بلکہ نماز میں کیے جانے والے سجدے کی طوالت کا بیان ہے جیسا کہ صحیح بخاری کی روایت سے معلوم ہوتا ہے۔ حضرت عائشہ رضی اللہ عنہا بیان کرتی ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نماز (تہجد) گیارہ رکعات پڑھا کرتے تھے۔ رات کے وقت آپ کی یہی نماز ہوتی تھی، اس نماز میں سجدہ اس قدر طویل کرتے کہ آپکے سر اٹھانے سے پہلے تم میں سے کوئی شخص پچاس آیات تلاوت کرسکتا تھا۔ دیکھیے: (صحیح البخاري، الوتر، حدیث: ۹۹۴) (۲) اس روایت میں عشاء کی مابعد سنتوں کو عشاء ہی میں شمار کیا گیا ہے، یعنی یہ گیارہ رکعات عشاء کی سنتوں کے علاوہ تھیں۔ (۳) اگر صرف تین وتر پڑھنے ہوںتو پھر دو رکعت نماز الگاور ایک رکعت الگ پڑھنا بہتر اور افضل ہے۔ احادیث کی روشنی میں اسی طریقے کی افضیلت متی ہے۔ احناف کسی حال میں ایک رکعت الگ پڑھنے کو جائز نہیں سمجھتے۔ صحیح، کثیر اور صریح احادیث کی موجودگی میں ان کاایک وتر سے انحراف قابل افسوس ہے۔ (۴) رات کی نماز لمبی پڑھنا مستحب ہے۔"}],[1329,"عبداللہ بن مسعود رضی اللہ عنہ سے روایت ہے کہ نبی اکرم صلی اللہ علیہ وسلم نے سلام پھیرا، پھر آپ نے گفتگو کی، پھر سہو کے دو سجدے کیے۔","الألباني: صحيح",{"u2":"حضرت عبداللہ بن مسعود رضی اللہ عنہ سے مروی ہے کہ نبی صلی اللہ علیہ وسلم نے (بھول کر) سلام پھیر دیا، پھر کچھ باتیں کیں، پھر آپ نے سہو کے دو سجدے کیے۔","f2":"جب امام یہ سمجھتا ہو کہ میں نماز مکمل کرچکا ہوں اور نماز سے فارغ ہوں، اس حالت میں اگر وہ کوئی کلام کرلے یا مقتدی ہونے کی صورت میں امام کو متنبہ کرے اور اس سے کچھ کلام کرنا پڑے یا تحقیق کی غرض سے آپس میں بات چیت ہو جائے، تو معلوم ہو جانے کے بعد سلام اور کلام نماز کے لیے قاطع نہیں ہوں گے۔بقیہ نماز پڑھ کر سجود سہو کر لیے جائیں تو نماز بلاریب درست ہے۔ یہ بات احادیث سے صاف سمجھ میں آتی ہے، البتہ احناف اور حنابلہ کلام کی صورت میں نئے سرے سے نماز پڑھنے کے قائل ہیں۔ لیکن احادیث سے ان کے موقف کی تائید نہیں ہوتی۔ (مزید تفصیل کے لیے دیکھیے، حدیث: ۱۲۲۵، ۱۲۳۰)"}],[1330,"ابوہریرہ رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے سلام پھیرا، پھر سہو کے دو سجدے بیٹھے بیٹھے کئے، پھر سلام پھیرا، راوی کہتے ہیں: اس کا ذکر ذوالیدین والی حدیث میں بھی ہے۔","الألباني: حسن صحيح",{"u2":"حضرت ابوہریرہ رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے سلام پھیرا، پھر بیٹھے بیٹھے سہو کے دو سجدے کیے، پھر سلام پھیرا۔ (امام نسائی رحمہ اللہ نے) فرمایا: ذوالیدین کی حدیث میں بھی اس کا ذکر ہے۔","f2":"دیکھیے‘حدیث:1225۔"}],[1331,"عمران بن حصین رضی اللہ عنہما سے روایت ہے کہ نبی اکرم صلی اللہ علیہ وسلم نے تین رکعت نماز پڑھ کر سلام پھیر دیا، تو خرباق رضی اللہ عنہ نے عرض کیا: آپ نے تین ہی رکعت نماز پڑھی ہے، چنانچہ آپ نے انہیں وہ رکعت پڑھائی جو باقی رہ گئی تھی، پھر آپ نے سلام پھیرا، پھر سجدہ سہو کیا، اس کے بعد سلام پھیرا۔","الألباني: صحيح",{"u2":"حضرت عمران بن حصین رضی اللہ عنہما سے مروی ہے کہ نبی صلی اللہ علیہ وسلم نے تین رکعتوں کے بعد سلام پھیر دیا۔ حضرت خرباق رضی اللہ عنہ نے کہا: آپ نے تین رکعتیں پڑھی ہیں۔ آپ نے انھیں بقیہ رکعت پڑھائی، پھر سلام پھیرا، پھر سہو کے دو سجدے کیے، پھر سلام پھیرا۔","f2":"(۱) سجود سہو کے بعد سلام اتفاقی مسئلہ ہے، البتہ تشہد میں اختلاف ہے۔ تشہد کی روایات ضعیف ہیں۔ عام روایات میں تشہد کا ذکر نہیں ہے، اس لیے راجح اور صحیح موقف یہی ہے کہ تشہد نہیں ہے۔ احناف لازمی سمجھتے ہیں۔ (۲) ’’خرباق‘‘ کی تفصیل کے لیے دیکھیے، حدیث: ۱۲۳۰ کا فائدہ۔"}],[1332,"براء بن عازب رضی اللہ عنہ کہتے ہیں کہ میں نے رسول اللہ صلی اللہ علیہ وسلم کی نماز کو بغور دیکھا، تو میں نے پایا کہ آپ کا قیام ۱؎، آپ کا رکوع، اور رکوع کے بعد آپ کا سیدھا کھڑا ہونا، پھر آپ کا سجدہ کرنا، اور دونوں سجدوں کے درمیان بیٹھنا، پھر دوسرا سجدہ کرنا، پھر سلام پھیرنے اور مقتدیوں کی طرف پلٹنے کے درمیان بیٹھنا تقریباً برابر برابر ہوتا تھا۔\n§وضاحت\n۱؎: اس حدیث میں «قیام» کا اضافہ \"ہلال بن أبی حمید\" کی روایت میں ہے، ان کے ساتھی \"حکم بن عتیبہ\" کی روایت میں «قیام» کا ذکر نہیں ہے، اور \"حکم\" \"ہلال\" کے مقابلہ زیادہ ثقہ ہیں، اس لیے ان کی روایت محفوظ ہے، نیز نبی اکرم صلی اللہ علیہ وسلم کا قیام تو اکثر رکوع، قومہ، جلسہ بین السجدتین وغیرہ سے لمبا ہی ہوا کرتا تھا، بلکہ کبھی کبھی آپ ساٹھ سے سو آیتیں پڑھا کرتے رہے ہیں، اور ظہر کی پہلی رکعت دوسری سے لمبی ہوا کرتی تھی، اس لیے ہلال کی روایت یا تو شاذ ہے، یا کبھی کبھار آپ ایسا کرتے رہے ہوں، اور اسی وقت براء رضی اللہ عنہ نے دیکھا ہو۔","الألباني: صحيح",{"u2":"حضرت براء بن عازب رضی اللہ عنہ بیان کرتے ہیں کہ میں نے رسول اللہ صلی اللہ علیہ وسلم کو نماز کی حالت میں بغور دیکھا تو میں نے آپ کے قیام، رکوع، رکوع کے بعد سیدھا کھڑا ہونا، سجدہ، دو سجدوں کے درمیان بیٹھنا، پھر دوسرا سجدہ کرنا، پھر سلام پھیرنے اور مقتدیوں کی طرف منہ پھیرنے کے درمیان (قبلہ رخ) بیٹھنا، تقریباً برابر پایا۔","f2":"سلام پھیرنے کے بعد امام کو کچھ دیر قبلہ رخ بیٹھے رہنا چاہیے۔ اس حدیث کے ظاہر الفاظ سے معلوم ہوتا ہے کہ نبی صلی اللہ علیہ وسلم کا قیام، رکوع اور سجود دوسرے ارکان، مثلاً: قومہ، جلسہ وغیرہ کے برابر ہوتے تھے۔ بہت سی روایات سے معلوم ہوتا ہے کہ قیام کافی لمبا ہوتا تھا۔ اسی طرح رات کی نماز میں رکوع و سجود بھی طویل ہوتے تھے۔ ممکن ہے کبھی کبھار سب ارکان برابر بھی ہوتےہوں۔ یہ مطلب بھی ہوسکتا ہے کہ آپ سب ارکان میں تناست رکھتے تھے۔ اگر قیام لمبا ہوتا تو باقی ارکان میں بھی اسی تناسب سے اضافہ ہوتا تھا اور اگر اختصار ہوتا تو دیگر ارکان میں بھی اسی تناسب سے اختصار ہوتا تھا۔"}],[1333,"ام المؤمنین ام سلمہ رضی اللہ عنہا کہتی ہیں کہ رسول اللہ صلی اللہ علیہ وسلم کے زمانے میں عورتیں جب نماز سے سلام پھیرتیں تو کھڑی ہو جاتیں، اور رسول اللہ صلی اللہ علیہ وسلم اور مردوں میں سے جو لوگ نماز میں ہوتے بیٹھے رہتے جب تک اللہ چاہتا، پھر جب رسول اللہ صلی اللہ علیہ وسلم کھڑے ہوتے تو مرد بھی کھڑے ہو جاتے۔","الألباني: صحيح",{"u2":"حضرت ام سلمہ رضی اللہ عنہا نے بتایا کہ رسول اللہ صلی اللہ علیہ وسلم کے دور میں عورتیں نماز سے سلام پھیرتے ہی اٹھ کر چلی جاتی تھیں جب کہ رسول اللہ صلی اللہ علیہ وسلم اور آپ کے ساتھ نماز پڑنے والے مرد نمازی، جب تک اللہ تعالیٰ چاہتا (کافی دیر تک) بیٹھے رہتے۔ پھر جب اللہ کے رسول صلی اللہ علیہ وسلم اٹھتے تو مرد بھی اٹھ کر چلے جاتے۔","f2":"(۱)اس روایت سے معلوم ہوتا ہے کہ باب کا مقصد یہ ہے کہ سلام پھیرنے اور اٹھ کر جانے کے درمیان کچھ دیر تک ذکر اذکار کے لیے بیٹھنا چاہیے۔ ممکن ہے دونوں جگہ بیٹھنا مراد ہو۔ مقتدیوں کی طرف متوجہ ہونے سے پہلے قبلہ رخ بیٹھنا اور اٹھ کر چلے جانے سے پہلے ذکر اذکار کے لیے مقتدیوں کی طرف متوجہ ہو کر بیٹھنا دونوں مسنون ہیں۔ جماعت ختم ہونے کے فوراً بعد اٹھ جانا معیوب اور سنت کے خلاف ہے الا یہ کہ کوئی عذر ہو بلکہ نماز کے اختتام کے بعد قبلہ رخ بیٹھ کر ذکر اذکار اور ادعیۂ ماثورہ پڑھنا مستحب و مسنون ہے، علاوہ امام کے کہ وہ مقتدیوں کی طرف رخ کرکے بیٹھے گا۔ (۲) امام کو مقتدیوں کے احوال کا خیال رکھنا چاہیے۔ (۳) اس حدیث مبارکہ سے معلوم ہوا کہ ان اسباب سے بھی بچنا چاہیے جو ممنوعات تک پہنچانے والے ہوں۔ (۴) تہمت والے مقامات سے بچنا چاہیے۔ (۵) عورتیں مسجد میں نماز باجماعت کے ساتھ شامل ہوسکتی ہیں۔"}],[1334,"یزید بن اسود رضی اللہ عنہ روایت کرتے ہیں کہ انہوں نے رسول اللہ صلی اللہ علیہ وسلم کے ساتھ نماز فجر پڑھی، جب نماز پڑھ چکے تو آپ نے اپنا رخ پلٹ کر مقتدیوں کی طرف کر لیا۔","الألباني: صحيح",{"u2":"حضرت یزید بن اسود رضی اللہ عنہ سے روایت ہے کہ انھوں نے رسول اللہ صلی اللہ علیہ وسلم کے ساتھ صبح کی نماز پڑھی، جب آپ نماز پڑھ چکے تو آپ نے اپنا رخ (قبلے سے) موڑ لیا۔","f2":"(۱) قبلے سے رخ موڑنا شاید اس لیے ہے کہ دور سے دیکھنے والے کو بھی نماز کے ختم ہونے کا علم ہو جائے۔ ویسے بھی امام کا مقتدیوں کی طرف بیٹھنا نماز کی حد تک تو مجبوری تھی، نماز کے بعد مناسب ہے کہ وہ لوگوں کی طرف منہ کرکے بیٹھے جیسے سردار لوگوں کے ساتھ بیٹھتا ہے، اس لیے امام کو اپنا رخ قبلے کی طرف سے بدل لینا چاہیے۔ پھر چاہے تو بالکل مقتدیوں کی طرف منہ کرکے بیٹھے، خصوصاًً اگر کوئی خطاب کرنا ہو اور چاہے تو دائیں یا بائیں منہ کرکے بیٹھ جائے۔ دائیں کو ترجیح دینا مستحسن ہے کیونکہ رسول اللہ صلی اللہ علیہ وسلم عموماً دائیں جانب کو ترجیح دیتے تھے۔ (۲) اس حدیث کے معنی یہ بھی ہوسکتے ہیں کہ جب آپ نماز پڑھ چکے تو اٹھ کر گھر چلے گئے مگر نماز کے بعد دیر تک ذکر اذکار آپ کا معمول تھا، خصوصاً صبح کی نماز کے بعد۔ احادیث میں اس کی فضیلت بھی وارد ہے۔ ہوسکتا ہے کوئی کام ہو، اس لیے فوراً چلے گئے لیکن یہ معنی مراد لینے بعید ہیں کیونکہ یہ حجۃ الوداع کے موقع پر مسجد خیف کی بات ہے جیسا کہ حدیث: ۸۵۹ میں گزر چکا ہے۔ اور مسند احمد کے الفاظ ہیں: [ثم انحرف جالسا] ’’پھر آپ بیٹھے بیٹھے مڑے۔‘‘ (مسند أحمد: ۴/۱۶۱) لہٰذا پہلی بات ہی زیادہ درست معلوم ہوتی ہے۔ تاہم ضرورت کے پیش نظر امام فوراً اٹھ کر بھی جا سکتا ہے۔ واللہ أعلم۔"}],[1335,"عبداللہ بن عباس رضی اللہ عنہم کہتے ہیں میں رسول اللہ صلی اللہ علیہ وسلم کی نماز کے ختم ہونے کو تکبیر کے ذریعہ جانتا تھا ۱؎۔\n§وضاحت\n۱؎: عبداللہ بن عباس رضی اللہ عنہم کی اس حدیث اور ثوبان رضی اللہ عنہ کی حدیث :(رقم: ۱۳۳۸ ) کا خلاصہ یہ ہے کہ سلام کے بعد ایک بار زور سے«اللہ اکبر» اور تین بار «استغفراللہ» کہتے، اور یہ تکبیر ۳۳، ۳۳ بار تسبیح تحمید اور تکبیر کے علاوہ ہے۔","الألباني: صحيح",{"u2":"حضرت ابن عباس رضی اللہ عنہما بیان کرتے ہیں کہ میں رسول اللہ صلی اللہ علیہ وسلم کی نماز کا اختتام لوگوں کے اللہ أکبر کہنے سے معلوم کرتا تھا۔","f2":"(۱) نماز سے فراغت کے بعد ذکر مسنون ہے۔ اس کی ابتدا اللہ أکبر سے کی جائے۔ آواز درمیانی ہو، نہ بہت بلند ہو اور نہ بالکل آہستہ تاکہ سب مقتدیوں کی آواز مل کر ایک گونج سی پیدا ہو جائے باقی ذکر آہستہ کیا جائے۔ (۲) حضرت ابن عباس رضی اللہ عنہما نابالغ ہونے کی وجہ سے پچھلی صفوں میں کھڑے ہوتے تھے، اس لیے ان تک سلام کی آواز نہیں پہنچتی تھی۔ سلام کے بعد جب تکبیر کی آوازگونجتی تو انھیں نماز کے ختم ہونے کا پتہ چلتا۔ ممکن ہے تکبیر بلند آواز سے کہنے میں یہ حکمت بھی ہو کہ لوگوں کو نماز ختم ہونے کا پتہ چل جائے، جیسے نماز میں تکبیرات انتقال بلند آواز سے کہی جاتی ہیں، اذان بلند آواز سے کہی جاتی ہے وغیرہ، لہٰذا یہ بات کمزور ہ کہ ذکر میں اخفا مناسب ہے، اس لیے سلام کے بعد تکبیر آہستہ کہی جائے جیسا کہ یہ جمہور اہل علم کا موقف ہے۔"}],[1336,"عقبہ بن عامر رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے مجھے حکم دیا کہ میں ہر نماز کے بعد معوذتین «قل أعوذ برب الفلق» اور «قل أعوذ برب الناس» پڑھا کروں۔","الألباني: صحيح",{"u2":"حضرت عقبہ بن عامر رضی اللہ عنہ فرماتے ہیں کہ مجھے رسول اللہ صلی اللہ علیہ وسلم نے حکم دیا کہ میں ہر (فرض) نماز کے بعد موذات پڑھوں۔","f2":"بعض روایات میں ’’معوذتین‘‘ کا ذکر ہے، یعنی قرآن مجید کی آخری دو سورتیں (قل اعوذ برب الفلق) اور (قل اعوذ برب الناس) معوذات کا مطلب ہے کہ یہ کلمات اپنے پڑھنے والے کو ہر شر سے بچاتے ہیں یا ان کے ذریعے اللہ کی پناہ طلب کی جاتی ہے۔ یہ سورتیں بھی اسی لیے نازل ہوئیں کہ لوگوں کے حسد، جادو، شر اور شیطانوں سے ان کے ذریعے سے بچا جائے یا پناہ طلب کی جائے۔"}],[1337,"ثوبان رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم جب نماز سے فارغ ہو کر پلٹتے تو تین بار «استغفر اللہ» کہتے، پھر کہتے: «اللهم أنت السلام ومنك السلام تباركت يا ذا الجلال والإكرام» \"اے اللہ! تو سلام ہے، اور تجھ سے ہی تمام کی سلامتی ہے، تیری ذات بڑی بابرکت ہے، اے بزرگی اور عزت والے\"۔","الألباني: صحيح",{"u2":"رسول اللہ صلی اللہ علیہ وسلم کے آزاد کردہ غلام حضرت ثوبان رضی اللہ عنہ بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم جب اپنی نماز سے فارغ ہوتے تو تین دفعہ [استغفراللہ] ’’میں اللہ تعالیٰ سے بخشش طلب کرتا ہوں۔‘‘ پڑھتے اور یہ دعا پڑھتے: [اللھم أنت السلام ……… والاکرام] ’’اے اللہ! تو سلام ہے۔ تیری ہی طرف سے سلامتی ملتی ہے۔ اے احترام و عزت والے! تو بابرکت ہے۔‘‘","f2":"(۱) سلام پھیرنے کے بعد استغفار کرنا مستحب ہے۔ (۲) اس حدیث مبارکہ سے نبیٔ اکرم صلی اللہ علیہ وسلم کی اپنے رب کے سامنے کمال عاجزی اور اظہار بندگی کا اثبات ہوتا ہے باوجود اس کے کہ اللہ تعالیٰ نے آپ کی تمام تغزشیں معاف کر دی تھیں۔ (۳) بندے کو یہ نہیں سمجھنا چاہیے کہ میں اطاعت میں کامل ہوں بلکہ اسے یہی سمجھنا چاہیے کہ میرے اطاعت کرنے میں نقص ہے، میں نے عبادت کا حق ادا نہیں کیا، اسے استغفار کے ساتھ اس کمی کو پورا کرنے کی کوشش کرتے رہنا چاہیے۔ (۴) ’’بابرکت ہے‘‘ یعنی تیرے پاس کسی چیز کی کمی نہیں، کثرت ہی کثرت ہے۔ یا جہاں تیرا ذکر ہو، وہاں برکت ہوتی ہے۔"}],[1338,"ام المؤمنین عائشہ رضی اللہ عنہا سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم جب سلام پھیرتے تو کہتے: «اللهم أنت السلام ومنك السلام تباركت يا ذا الجلال والإكرام» \"اے اللہ! تو سلام ہے، اور تجھی سے تمام کی سلامتی ہے، اے عزت و بزرگی والے تیری ذات بڑی بابرکت ہے\"۔","الألباني: صحيح",{"u2":"حضرت عائشہ رضی اللہ عنہا سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم جب سلام پھیرتے تو یوں فرماتے: [اللھم أنت السلام ……… والإکرام] ’’اے اللہ! تو سلام ہے اور تجھی سے سلامتی ملتی ہے۔ اے احترام و عزت والے! تو بابرکت ہے۔‘‘","f2":"’’تو سلام ہے‘‘ یعنی تو ہر قسم کے عیب اور نقص سے پاک ہے، یا تو لوگوں کو سلامتی دینے والا ہے۔"}],[1339,"ابوالزبیر کہتے ہیں کہ میں نے عبداللہ بن زبیر رضی اللہ عنہم کو اس منبر پر بیان کرتے ہوئے سنا، وہ کہہ رہے تھے کہ رسول اللہ صلی اللہ علیہ وسلم جب سلام پھیرتے تو کہتے: «لا إله إلا اللہ وحده لا شريك له له الملك وله الحمد وهو على كل شىء قدير لا حول ولا قوة إلا باللہ لا إله إلا اللہ لا نعبد إلا إياه أهل النعمة والفضل والثناء الحسن لا إله إلا اللہ مخلصين له الدين ولو كره الكافرون» \"نہیں ہے کوئی حقیقی معبود سوائے اللہ کے جو اکیلا ہے، اس کا کوئی شریک نہیں، اسی کے لیے بادشاہت ہے، اور اسی کے لیے حمد ہے، اور وہ ہر چیز پر قدرت رکھتا ہے، نہیں طاقت و قوت مگر اللہ ہی کی توفیق سے، نہیں ہے کوئی حقیقی معبود سوائے اللہ کے، ہم صرف اسی نعمت، فضل اور بہترین تعریف والے کی عبادت کرتے ہیں، نہیں ہے کوئی حقیقی معبود سوائے اللہ کے، ہم دین کو اسی کے لیے خالص کرنے والے ہیں، اگرچہ کافروں کو برا لگے\"۔","الألباني: صحيح",{"u2":"حضرت ابوزبیر بیان کرتے ہیں کہ میں نے حضرت عبداللہ بن زبیر رضی اللہ عنہا کو اس منبر (منبر کعبہ) پر بیان کرتے ہوئے سنا، وہ فرما رہے تھے: رسول اللہ صلی اللہ علیہ وسلم جب سلام پھیرتے تو یوں فرماتے: [لا إلہ إلا اللہ ___ ولوکرہ الکافرون] ’’اللہ تعالیٰ کے سوا کوئی معبود نہیں۔ وہ یکتا ہے۔ اس کا کوئی شریک نہیں۔ اسی کے لیے بادشاہی ہے اور اسی کے لیے کل حمد ہے۔ اور وہ ہر چیز پر خوب قادر ہے۔ گناہ سے بچنے کی طاقت اور نیکی کرنے کی قوت اللہ کی مدد کے بغیر حاصل نہیں ہوسکتی۔ اللہ تعالیٰ کے سوا کوئی (حقیقی) معبود نہیں۔ ہم اس کے سوا کسی کی عبادت نہیں کرتے۔ اے نعمت، فضل اور اچھی تعریف والے! اللہ تعالیٰ کے سوا کوئی معبود نہیں۔ ہم خالص اسی کی اطاعت کرتے ہیں۔ چاہے کافر برا ہی سمجھیں۔‘‘","f2":"[لاحول ولا قوۃ الا باللہ] جامع کلمہ ہے۔ حول سے مراد ہر نقصان اورخرابی سے بچنے کی طاقت اور قوۃ سے مراد ہر اچھی چیز حاصل کرنے کی قوت ہے۔ ظاہر ہے ہر چیز ان میں آ جاتی ہے۔ شاید اسی لیے اس کلمے کو جنت کا خزانہ کہا گیا ہے۔"}],[1340,"ابو الزبیر کہتے ہیں کہ عبداللہ بن زبیر رضی اللہ عنہم نماز کے بعد تہلیل کرتے اور کہتے: «لا إله إلا اللہ وحده لا شريك له له الملك وله الحمد وهو على كل شىء قدير لا إله إلا اللہ ولا نعبد إلا إياه له النعمة وله الفضل وله الثناء الحسن لا إله إلا اللہ مخلصين له الدين ولو كره الكافرون» \"نہیں ہے کوئی حقیقی معبود سوائے اللہ کے، جو تنہا ہے، اس کا کوئی شریک نہیں، اسی کی بادشاہت ہے سب پر، اور اسی کے لیے تمام تعریفیں ہیں، اور وہ ہر چیز پر قادر ہے، نہیں ہے کوئی حقیقی معبود سوائے اللہ کے، اور ہم اسی کی عبادت کرتے ہیں، نعمت، فضل اور بہترین ثنا اسی کے لیے ہے، نہیں ہے کوئی حقیقی معبود سوائے اللہ کے، ہم دین کو اسی کے لیے خالص کرنے والے ہیں، اگرچہ کافروں کو برا لگے\" پھر ابن زبیر رضی اللہ عنہم کہتے: رسول اللہ صلی اللہ علیہ وسلم نماز کے بعد انہیں کلمات کے ذریعہ تہلیل کیا کرتے تھے۔","الألباني: صحيح",{"u2":"حضرت ابوزبیر بیان کرتے ہیں کہ حضرت عبداللہ بن زبیر رضی اللہ عنہا (فرض) نماز کے بعد اس طرح تہلیل پڑھتے تھے: [لا إلہ إلا اللہ ……… ولوکرہ الکافرون] ’’اللہ تعالیٰ کے سوا کوئی (حقیقی) معبود نہیں۔ وہ یکتا ہے۔ اس کا کوئی شریک نہیں۔ اسی کے لیے حکومت اور بادشاہی ہے اور اسی کے لیے ہر تعریف ہے اور وہ ہر چیز پر خوب قدرت رکھنے والا ہے۔ اللہ تعالیٰ کے سوا کوئی (حقیقی) معبود نہیں۔ ہم اس کے سوا کسی کی عبادت نہیں کرتے۔ اسی کی ہیں سب نعمتیں اور اسیکے ہیں سب احسان و فضل اور اسی کے لیے ہیں اچھی تعریفیں۔ اللہ تعالیٰ کے سوا کوئی (حقیقی) معبود نہیں۔ ہم خالص اسی کی اطاعت کرتے ہیں، خواہ کافر برا ہی سمجھیں۔‘‘ پھر حضرت ابن زبیر رضی اللہ عنہا فرماتے تھے: رسول اللہ صلی اللہ علیہ وسلم نماز کے بعد ان کلمات کے ساتھ تہلیل پڑھتے تھے۔"}],[1341,"مغیرہ بن شعبہ رضی اللہ عنہ کے منشی وراد کہتے ہیں کہ معاویہ رضی اللہ عنہ نے مغیرہ بن شعبہ رضی اللہ عنہ کو لکھا کہ مجھے کوئی ایسی چیز بتائیے جسے آپ نے رسول اللہ صلی اللہ علیہ وسلم سے سنی ہو، تو انہوں نے کہا: رسول اللہ صلی اللہ علیہ وسلم جب نماز پڑھ چکتے تو کہتے: «لا إله إلا اللہ وحده لا شريك له له الملك وله الحمد وهو على كل شىء قدير اللہم لا مانع لما أعطيت ولا معطي لما منعت ولا ينفع ذا الجد منك الجد» \"نہیں ہے کوئی حقیقی معبود سوائے اللہ کے، وہ تنہا ہے، اس کا کوئی شریک نہیں، اسی کے لیے بادشاہت ہے، اور اسی کے لیے حمد ہے، اور وہ ہر چیز پر قادر ہے، اے اللہ! جو تو دے اسے کوئی روکنے والا نہیں، اور جو تو روک لے اسے کوئی دینے والا نہیں، اور مالدار کی مالداری تیرے عذاب سے بچا نہیں سکتی\"۔","الألباني: صحيح",{"u2":"حضرت مغیرہ بن شعبہ رضی اللہ عنہ کے کاتب حضرت وراد نے بیان کیا کہ حضرت معاویہ رضی اللہ عنہ نے حضرت مغیرہبن شعبہ رضی اللہ عنہ کو لکھا: مجھے کسی ایسی چیز کی خبر دیجیے جو آپ نے رسول اللہ صلی اللہ علیہ وسلم سے سنی ہو۔ تو انھوں نے فرمایا: رسول اللہ صلی اللہ علیہ وسلم جب نماز مکمل فرما لیتے تو یوں پڑھتے: [لا إلہ إلا اللہ ……… منک الحد] ’’اللہ تعالیٰ کے سوا کوئی (حقیقی) معبود نہیں۔ وہ یکتا ہے۔ کوئی اس کا شریک نہیں۔ اسی کے لیے ہے بادشاہ اور تمام تعریفیں، اور وہ ہر چیز پر خوب قدرت رکھنے والا ہے۔ اے اللہ!نہیں کوئی روکنے والا اس چیز کو جو تو دے اور نہ کوئی اس چیز کو عطا کرنے والا ہے جو تو نے دے اور کسی صاحب حیثیت کو اس کی حیثیت تیرے مقابلے میں مفید نہیں۔‘‘","f2":"(۱) نماز کے بعد یہ ذکر کرنا مستحسن ہے کیونکہ اس میں خالص توحید اور اللہ تعالیٰ کی کمال قدرت کا بیان ہے۔ (۲) کسی کو حدیث لکھ کر بھیجنا اور اسے آگے بیان کرنا درست ہے۔ (۳) ایک آدمی کی خبر بھی حجت ہے جبکہ وہ ثقہ ہو۔ (۴) ’’تیرے مقابلے میں‘‘ یعنی اگر تو پکڑنا چاہے تو کسی کی حیثیت یا اس کا مال اسے کوئی فائدہ دے سکتا ہے، نہ بچا سکتا ہے۔ یا تیرے ہاں کسی مال والے کو اس کا مال فائدہ نہیں ہوتا۔"}],[1342,"وراد کہتے ہیں کہ مغیرہ بن شعبہ رضی اللہ عنہ نے معاویہ رضی اللہ عنہ کو لکھا کہ رسول اللہ صلی اللہ علیہ وسلم نماز کے بعد جب سلام پھیرتے تو کہتے: «لا إله إلا اللہ وحده لا شريك له له الملك وله الحمد وهو على كل شىء قدير اللہم لا مانع لما أعطيت ولا معطي لما منعت ولا ينفع ذا الجد منك الجد» \"نہیں ہے کوئی حقیقی معبود سوائے اللہ کے، وہ تنہا ہے، اس کا کوئی شریک نہیں، اسی کے لیے سلطنت و حکومت ہے، اور اسی کے لیے تمام تعریفیں ہیں، اور وہ ہر چیز پر قادر ہے، اے اللہ! جو تو دے اسے کوئی روکنے والا نہیں، اور جو تو روک دے اسے کوئی دینے والا نہیں، اور نہ مالدار کی مالداری تیرے عذاب سے بچا سکے گی\"۔","الألباني: صحيح",{"u2":"حضرت وراد سے روایت ہے کہ حضرت مغیرہ بن شعبہ رضی اللہ عنہ نے حضرت معاویہ رضی اللہ عنہ کو لکھا کہ رسول اللہ صلی اللہ علیہ وسلم نماز سے سلام پھیر کر یوں پڑھتے: [لا إلہ الا اللہ ………… منک الحد] ’’اللہ تعالیٰ کے سوا کوئی (حقیقی) معبود نہیں۔ وہ یکتا ہے۔ اس کا کوئی شریک نہیں۔ اسی کے لیے ہے بادشاہی اور اسی کے لیے ہے سب تعریف اور وہ ہر چیز پر خوب قدرت رکھنے والا ہے۔ اے اللہ! کوئی اس چیز کو روکنے والا نہیں جو تو دے اور نہ کوئی وہ چیز دینے والا ہے جو تو روک دے اور کسی صاحب حیثیت کو اس کی حیثیت تیرے مقابلے میں مفید نہیں۔‘‘"}],[1343,"مغیرہ رضی اللہ عنہ کے منشی وراد سے روایت ہے کہ معاویہ رضی اللہ عنہ نے مغیرہ رضی اللہ عنہ کو لکھا: مجھے کوئی حدیث لکھ بھیجو جسے تم نے رسول اللہ صلی اللہ علیہ وسلم سے سنی ہو، تو مغیرہ رضی اللہ عنہ نے انہیں لکھا میں نے آپ صلی اللہ علیہ وسلم کو سلام پھیر کر پلٹتے وقت «لا إله إلا اللہ وحده لا شريك له له الملك وله الحمد وهو على كل شىء قدير» \"نہیں ہے کوئی حقیقی معبود سوائے اللہ کے، وہ اکیلا ہے، اس کا کوئی شریک نہیں، اسی کی بادشاہت ہے، اور تمام تعریفیں اسی کے لیے ہیں اور وہ ہر چیز پر قدرت رکھتا ہے\" تین بار کہتے سنا ہے۔","الألباني: شاذ بزيادة الثلاث",{"u2":"حضرت مغیرہ رضی اللہ عنہ کے کاتب وراد سے روایت ہے کہ حضرت معاویہ رضی اللہ عنہ نے حضرت مغیرہ رضی اللہ کو لکھا کہ مجھے ایک ایسی حدیث لکھ دیجیے جو آپ نےرسول اللہ صلی اللہ علیہ وسلم سے سنی ہو تو حضرت مغیرہ رضی اللہ عنہ نے انھیں لکھا: تحقیق میں نے نبی صلی اللہ علیہ وسلم کو نماز سے فارغ ہونے کے وقت یہ پڑھتے سنا ہے: [لا إلہ إلا اللہ………] ’’اللہ تعالیٰ کے سوا کوئی (حقیقی) معبود نہیں۔ وہ یکتا ہے۔ اس کا کوئی شریک نہیں۔ اسی کے لیے بادشاہی ہے اور اسی کے لیے حمد ہے اور وہ ہر چیز پر خوب قادر ہے۔‘‘ آپ یہ ذکر تین دفعہ پڑھتے۔","f2":"مذکورہ روایت کے آخری الفاظ [ثلاث مرات] کی بابت محقق کتاب اور شیخ البانی رحمہ اللہ لکھتے ہیں یہ الفاظ شاذ ہیں جبکہ بعض علمائے محققین نے نزدیک [ثلاث مرات] والے الفاظ صحیح ثابت ہیں۔ صرف نسخوں میں اختلاف ہے۔ صحیح بخاری کے صحیح اور معتمد نسخوں میں یہ الفاظ ثابت ہیں۔ تفصیل کے لیے دیکھیے: [(سلسلۃ الأحادیث الضعیفہ للألبانی: ۲۲۰-۲۰۹/۱۲، و ذخیرۃ العقبی شرحسنن النسائي: ۳۶۲-۳۶۰/۱۵)"}],[1344,"ام المؤمنین عائشہ رضی اللہ عنہا سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم جب کسی مجلس میں بیٹھتے یا نماز پڑھتے تو کچھ کلمات کہتے، تو عائشہ رضی اللہ عنہا نے آپ سے ان کلمات کے بارے میں پوچھا، تو آپ صلی اللہ علیہ وسلم نے فرمایا: \"اگر اس نے کوئی بھلی بات کی ہو گی تو یہ کلمات اس پر قیامت کے دن تک بطور مہر ہوں گے، اور اگر اس کے علاوہ اس نے کوئی اور بات کی ہو گی تو یہ کلمات اس کے لیے کفارہ ہوں گے، وہ یہ ہیں: «سبحانك اللہم وبحمدك أستغفرك وأتوب إليك» \"تیری ذات پاک ہے اے اللہ! اور تیری حمد کے ذریعہ سے میں تجھ سے مغفرت چاہتا ہوں، اور تیری ہی طرف رجوع کرتا ہوں\"۔","الألباني: صحيح",{"u2":"حضرت عائشہ رضی اللہ عنہا سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم جب کسی مجلس میں بیٹھتے یا نماز سے فارغ ہوتے تو کچھ کلمات پڑھتے۔ حضرت عائشہ رضی اللہ عنہا نے آپ سے ان کلمات کے بارے میں پوچھا تو آپ نے فرمایا: ’’اگر کسی شخص نے (اس مجلس میں) اچھی باتیں کی ہوں گی تو یہ کلمات قیامت تک کے لیے ان باتوں کے لیے مہر بن جائیں گے اور اگر اس نے اور قسم کی (غلط یا فضول) باتیں کی ہوں گی تو یہ اس کے لیے کفارہ (گناہ مٹانے والے) بن جائیں گے۔ (اوروہ کلمات یہ ہیںJ [سبحانک اللھم! و بحمدک اسغتفرک و أتوب إلیک] ’’اے اللہ! تو ہر قسم کے نقص و عیب سے پاک ہے اور تمام تعریفوں اور خوبیوں والا ہے۔ میں تجھ سے معافی طلب کرتا ہوں اور تیری طرف رجوع کرتا ہوں۔‘‘ (یعنی ہر قسم کی غلطی سے توبہ کرتا ہوں۔)","f2":"(۱) اس دعا کو ’’کفارۂ مجلس‘‘ کہا جاتا ہے، لہٰذا ہر مجلس کے بعد پڑھنی چاہیے۔ (۲) ’’مہر بن جائیں گے،‘‘ یعنی ان اچھی باتوں کے ثواب کوقائم رکھیں گے اور ان کی قبولیت کی ضمانت ہوں گے اور انھیں رد نہیں ہونے دیں گے۔"}],[1345,"ام المؤمنین عائشہ رضی اللہ عنہا کہتی ہیں کہ ایک یہودی عورت میرے پاس آئی اور کہنے لگی: پیشاب سے نہ بچنے پر قبر میں عذاب ہوتا ہے تو میں نے کہا: تو جھوٹی ہے، تو اس نے کہا: سچ ہے ایسا ہی ہے، ہم کھال یا کپڑے کو پیشاب لگ جانے پر کاٹ ڈالتے ہیں، اتنے میں رسول اللہ صلی اللہ علیہ وسلم نماز کے لیے باہر تشریف لائے، ہماری آواز بلند ہو گئی تھی، آپ نے پوچھا: \"کیا ماجرا ہے؟\" میں نے آپ کو جو اس نے کہا تھا بتایا، تو آپ صلی اللہ علیہ وسلم نے فرمایا: \"وہ سچ کہہ رہی ہے\"، چنانچہ اس دن کے بعد سے آپ جو بھی نماز پڑھتے تو نماز کے بعد یہ کلمات ضرور کہتے: «رب جبريل وميكائيل وإسرافيل أعذني من حر النار وعذاب القبر»\"اے جبرائیل وم یکائیل اور اسرافیل کے رب! مجھے جہنم کی آگ کی تپش، اور قبر کے عذاب سے بچا\"۔","الألباني: ضعيف الإسناد",{"u2":"حضرت عائشہ رضی اللہ عنہا فرماتی ہیں کہ ایک یہودی عورت میرے پاس آئی اور کہنے لگی کہ پیشاب کے چھینٹےپڑنے سے قبر میں عذاب ہوتا ہے۔ میں نے کہا: تو غلط کہتی ہے۔ اس نے کہا: نہیں، بلکہ سچ ہے۔ ہم پیشاب کے چھیٹنے پڑنے سے چمڑا اور کپڑا کاٹتے تھے۔ (اسی دوران میں) رسول اللہ صلی اللہ علیہ وسلم نماز کے لیے نکلے تو ہم اونچی اونچی بول رہی تھیں۔ آپ نے فرمایا: ’’کیا ہوا؟‘‘ میں نے آپ سے بات بیان کی۔ آپ نے فرمایا: ’’یہ صحیح کہتی ہے۔‘‘ اس دن کے بعد آپنے جب بھی نماز پڑھی تو نماز کے بعد یہ دعا ضرور پڑھی: [رب جبریل و میکائیل و إسرافیل أعدنی من حرالنار و عذاب القبر] ’’اے جبریل، میکائیل اور اسرافیل کے رب! مجھے آگ کی تپش اور قبر کے عذاب سے بچا۔‘‘","f2":"(۱) پیشاب کے چھینٹوں سے پرہیز نہ کرنا عذاب قبر کا سبب ہے۔ یہ بات دیگر روایات میں بھی بیان کی گئی ہے۔ حضرت عائشہ رضی اللہ عنہا کو ان کا علم نہ ہوگا یا یہ واقعہ پہلے کا ہے جیسا کہ حدیث کے آخر سے معلوم ہوتا ہے کہ آپ اس کے بعد ہمیشہ عذاب قبر سے پناہ مانگتے رہے۔ (۲) ’’چمڑا اور کپڑا کاٹتے تھے۔‘‘ چمڑے سے مراد بھی پہنا ہوا چمڑا ہے جسے پیشاب لگتا تھا نہ کہ اپنے جسم کا چمڑا کیونکہ پیشاب تو نکلتا ہی جسم سے ہے اور اس کا جسم کو لگنا لازمی ہے، تبھی تو استنجا ضروری ہے۔ اگر وہاں دھونا کفایت کرتا تھا تو جسم کے دیگر حصوں کو بھی کاٹنے کی ضرورت نہیں ہوگی۔ ہاں، ملبوس کپڑایا چمڑا چونکہ جسم سے جدا ہے، اسے پیشاب کے قطرے لگنا انسان کی غلطی اور سستی کا نتیجہ ہے، لہٰذا انھیں کاٹنے کی سزا دی جا سکتی ہے۔ بعض علماء نے اس سے جسم کا چمڑا بھی مراد لیا ہے مگر یہ درست نہیں۔ ویسے بھی یہ تکلیف مالا یطاق ہے، یعنی اس پرعمل ناممکن ہے۔ بعض روایات میں [جسد] کا لفظ بھی آیا ہے۔ لیکن یہ عاصم بن بہدلہ کا وہم ہے کہ اس نے نسخ سے جسم کا چمڑا سمجھا اور پھر اس کی جگہ لفظ [جسد] (جسم) بول دیا۔ شیخ البانی رحمہ اللہ نے ’’جسد احدھم‘‘ کو منکر کہا ہے۔ دیکھیے: (ضعیف سن أبي داود (مفصل) للألباني، رقم الحدیث: ۵) (شاذ (بات) کی تاویل کی جانی چاہیے، عقلا شاذ ہو یا نقلا‘‘ وہ غیر معتبر ہے۔ (مزید دیکھیے، حدیث: ۳۰ کا فائدہ نمبر: ۳) (۳) ’’جبریل علیہ السلام میکائیل علیہ السلام، اسرافیل کے رب!‘‘ اس قسم کے الفاظ سے مقصود رب تعالیٰ کی عظمت کا اظہار ہے، یعنی اتنی عظیم الشان مخلوق کو پیدا کرنے والا۔ اسی طرح آسمانوں، زمینوں کے رب برحق، مغرب کے رب وغیرہ۔"}],[1346,"ابومروان روایت کرتے ہیں کہ کعب رضی اللہ عنہ نے ان سے اس اللہ کی قسم کھا کر کہا جس نے موسی کے لیے سمندر پھاڑا کہ ہم لوگ تورات میں پاتے ہیں کہ اللہ کے نبی داود علیہ السلام جب اپنی نماز سے سلام پھیر کر پلٹتے تو کہتی: «اللہم أصلح لي ديني الذي جعلته لي عصمة وأصلح لي دنياى التي جعلت فيها معاشي اللہم إني أعوذ برضاك من سخطك وأعوذ بعفوك من نقمتك وأعوذ بك منك لا مانع لما أعطيت ولا معطي لما منعت ولا ينفع ذا الجد منك الجد» \"اے اللہ! میرے لیے میرے دین کو درست فرما دے جسے تو نے میرے لیے بچاؤ کا ذریعہ بنایا ہے، اور میرے لیے میری دنیا درست فرما دے جس میں میری روزی ہے، اے اللہ! میں تیری ناراضگی سے تیری رضا مندی کی پناہ چاہتا ہوں، اور تیرے عذاب سے تیرے عفو و درگزر کی پناہ چاہتا ہوں، اور میں تجھ سے تیری پناہ چاہتا ہوں، نہیں ہے کوئی روکنے والا اس کو جو تو دیدے، اور نہ ہی ہے کوئی دینے والا اسے جسے تو روک لے، اور نہ مالدار کو اس کی مالداری بچا پائے گی۔ ابومروان کہتے ہیں: اور کعب رضی اللہ عنہ نے مجھ سے بیان کیا کہ صہیب رضی اللہ عنہ نے ان سے بیان کیا ہے کہ محمد صلی اللہ علیہ وسلم ان کلمات کو نماز سے سلام پھیر کر پلٹنے پر کہا کرتے تھے۔","الألباني: ضعيف الإسناد",{"u2":"حضرت ابو مروان سے روایت ہے کہ حضرت کعب نے مجھ سے حلفاً کہا: قسم اس ذات کی جس نے حضرت موسیٰ علیہ السلام کے لیے سمندر کو پھاڑ کر راستے بنائے! ہم تو رات میں یہ لکھا پاتے ہیں کہ اللہ کے نبی حضرت داود علیہ السلام جب نماز سے فارغ ہوتے تھے تو یوں کہتے تھے: [اللھم! أصلح لی …… منک الجد] ’’اے اللہ! میرے لیے میرے دین کو درست فرما جسے تو نے میرے لیے (دنیا و آخرت میں رسوائی سے) بچاؤ کا ذریعہ بنایا ہے۔ اور میرے لیے میری دنیا کو درست فرما جسے تو نے میرے لیے زندگی گزارنے کا سبب بنایا ہے۔ اے اللہ! میں تیری ناراضی سے بچنے کے لیے تیری رضا مندی کی پناہ چاہتا ہوں اور تیری سزا سے بچنے کے لیے تیری معافی کی پناہ چاہتا ہوں اور تیرے غضب سے بچنے کے لیے تیری (رحمت کی پناہ چاہتا ہوں۔ جو چیز تو دے، اسے کوئی روکنے والا نہیں اور جو چیز تو روک لے، اسے کوئی دینے والا نہیں اور کسی مال والے کو تیرے ہاں مال فائدہ نہیں دیتا (بلکہ عمل فائدہ دیتا ہے۔)‘‘ حضرت کعب نے کہا: مجھے حضرت صہیب رضی اللہ عنہ نے بتایا کہ حضرت محمد صلی اللہ علیہ وسلم بھی نماز سے فراغت کے وقت یہ کلمات کہا کرتے تھے۔","f2":"(۱)یہاں ’’تورات‘‘ سے مراد وہ کتاب نہیں جو حضرت موسیٰ علیہ السلام پر نازل کی گئی کیونکہ وہ کتاب تو حضرت داود علیہ السلام سےبہت پہلے کی ہے۔ اس میں ان کا تذکرہ (مندرجہ بالا صورت میں) کیسے آسکتا ہے؟ یہاں تورات سےصحف مراد ہیں جو بہت سےانبیاء پر اترے اور ان میں ’’زبور‘‘ بھی شامل ہے جو خود حضرت داود علیہ السلام پر اتری۔ آج کل ان تمام صحف کے مجموعہ کو بائبل کہتے ہیں۔ اس میں تورات بھی آ جاتی ہے، بلکہ اس میں ان انبیاء علیہم السلام کے شاگردوں کیباتیں بھی داخل ہیں، حتی کہ یہ تعین مشکل ہے کہ اس میں کون سا کلام اللہ تعالیٰ کا ہے اور کون سا انبیاء کا یا انکے شاگردوں کا؟ یہ امتیاز صرف مسلمانوں کو حاصل ہے کہ اللہ کی کتاب کلیتاً ممتاز ہے، کسی دوسرے کا ایک لفظ بھی اس میں شامل نہیں۔ اور رسول اللہ صلی اللہ علیہ وسلم کی باتیں (اقوال و افعال) اپنی جگہ الگ ممتاز اور واضح ہیں۔ آپ کے شاگردانِ رشید کے فتاوی و بیانات بالکل الگ ہیں۔ کوئی کسی سے خلط ملط نہیں۔ والحمد للہ علی ذالک۔ (۲) اس حدیث مبارکہ سے پتہ چلتا ہے کہ داود علیہ السلام کی شریعت میں بھی نماز مشروع تھی۔ (۳) ’’دین‘‘ انسان کے لیے بچاؤ کا ذریعہ ہے جو انسان کو دنیا اور آخرت کی تمام مکروہات سے بچاتا ہے، لہٰذا بندے کو چاہیے کہ وہ اپنے رب کے سامنے آہ و زاری کرتا رہے اور اپنے دین کی درستی کے لیے دعا مانگتا رہے۔ (۴) دنیا انسان کے زندگی گزارنے کا سبب ہے اور پاکیزہ معاش انسان کو جنت میں لے جانے کا سبب ہے، اس لیے اپنی دنیا کی اصلاح کے لیےبھی دعا کرتے رہنا چاہیے۔"}],[1347,"ابوبکرہ رضی اللہ عنہ کہتے ہیں کہ میرے والد (ابوبکرہ رضی اللہ عنہ) نماز کے بعد یہ دعا پڑھتے: «اللہم إني أعوذ بك من الكفر والفقر وعذاب القبر» \"اے اللہ میں کفر سے، محتاجی سے اور قبر کے عذاب سے تیری پناہ چاہتا ہوں\" تو میں بھی انہیں کہا کرتا تھا، تو میرے والد نے کہا: میرے بیٹے! تم نے یہ کس سے یاد کیا ہے؟ میں نے کہا: آپ سے، تو انہوں نے کہا: رسول اللہ صلی اللہ علیہ وسلم انہیں نماز کے بعد کہا کرتے تھے۔","الألباني: صحيح الإسناد",{"u2":"حضرت مسلم بن ابوبکرہ سے منقول ہے کہ میرے والد محترم ہر نماز کے بعد یہ پڑھا کرتے تھے: [اللھم! انی اعوذبک من الکفر و الفقر وعذاب القبر] ’’اے اللہ! میں کفر، فقر اور عذاب قبر سے تیری پناہ چاہتا ہوں۔‘‘ تو میں بھی یہ کلمات کہنے لگا۔ والد محترم پوچھنے لگے: بیٹا! یہ کلمات کس سے سیکھے ہیں؟ میں نے کہا: آپ سے۔ انھوں نے فرمایا: رسول اللہ صلی اللہ علیہ وسلم بھی نماز کے بعد یہ کلمات کہا کرتے تھے۔","f2":"اس روایت میں فقر کو کفرکےساتھ ذکر کیا گیا ہے۔ مشہور روایت ہے: [کاد الفقران یکون کفرا] (کشف الخفاء: ۱۰۸/۲، حدیث: ۱۹۱۹) ’’قریب ہے فقر کقر ہو۔‘‘ یہ روایت ضعیف ہے لیکن فقر سے بچنے کی دعا ضرور کرنی چاہیے۔ فضیلت اس فقر کی ہے جس میں دل غنی ہو۔ اس کے باوجود فقر کی دعا درست نہیں۔ اگر فقر کی حالت ہو جائے تو اللہ تعالیٰ سے فقر کا ثواب مانگا جائے اور غنیٰ کی دعا کی جائے۔ مصیبت مانگنا جائز نہیں۔ ہاں، اگر منجاب اللہ فقر آ جائے، پھر انسان دل غنی رکھے اور شکوہ شکایت سے اجتناب کرے تو اجر عظیم کا مستحق ہوگا، جیسے فقراء مہاجرین۔"}],[1348,"عبداللہ بن عمرو رضی اللہ عنہم کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"دو ایسی خصلتیں ہیں کہ کوئی مسلمان آدمی انہیں اختیار کر لے تو وہ جنت میں داخل ہو گا، یہ دونوں آسان ہیں لیکن ان پر عمل کرنے والے کم ہیں، پانچ نمازیں تم میں سے جو کوئی ہر نماز کے بعد دس بار «سبحان اللہ» دس بار «الحمد لله» اور دس بار «اللہ أكبر» کہے گا، تو وہ زبان سے کہنے کے لحاظ سے ڈیڑھ سو کلمے ہوئے، مگر میزان میں ان کا شمار ڈیڑھ ہزار کلموں کے برابر ہو گا، (عبداللہ بن عمرو رضی اللہ عنہم کہتے ہیں) میں نے رسول اللہ صلی اللہ علیہ وسلم کو انہیں اپنے ہاتھوں (انگلیوں) پر شمار کرتے ہوئے دیکھا ہے)، اور جب تم میں سے کوئی اپنے بستر پر سونے کے لیے جائے، اور تینتیس بار «سبحان اللہ» تینتیس بار «الحمد لله» اور چونتیس بار «اللہ أكبر» کہے، تو وہ زبان پر سو کلمات ہوں گے، مگر میزان (ترازو)میں ایک ہزار شمار ہوں گے، تو تم میں سے کون دن و رات میں دو ہزار پانچ سو گناہ کرتا ہے، عرض کیا گیا: اللہ کے رسول! ہم یہ دونوں تسبیحیں کیوں کر نہیں گن سکتے؟۱؎ تو آپ نے فرمایا: شیطان تم میں سے کسی کے پاس آتا ہے، اور وہ نماز میں ہوتا ہے تو وہ کہتا ہے: فلاں بات یاد کرو، فلاں بات یاد کرو اور اسی طرح اس کے سونے کے وقت اس کے پاس آتا ہے، اور اسے (یہ کلمات کہے بغیر ہی) سلا دیتا ہے\"۔\n§وضاحت\n۱؎: یعنی ان تسبیحات کو وقت پر پڑھ لینا کیا مشکل ہے ؟","الألباني: صحيح",{"u2":"حضرت عبداللہ بن عمرو رضی اللہ عنہما سے روایت ہے، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’دو کام ایسے ہیں کہ جو مسلمان بھی ان پر پابندی کرے، وہ جنتمیں داخل ہوگا۔ یہ دونوں کام بہت آسان ہیں اور ان پر عمل کرنے والے بہت کم ہیں۔‘‘ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’(وہ دو کام یہ ہیں:) پانچ فرض نمازوں میں سے ہر فرض نماز کے بعد دس دفعہ سبحان اللہ پڑھے۔ دس دفعہ الحمدللہ پڑھے اور دس دفعہ اللہ أکبر پڑھے۔ اس طرح زبان پر (پڑھنے میں) یہ کل ڈیڑھ سو کلمات ہیں مگر میزان میں (ثواب کے لحاظ سے) ڈیڑھ ہزار ہیں۔‘‘ (کیونکہ ہر نیکی کے بدلے میں اللہ تعالیٰ دس گناہ جزا دیتا ہے۔) میں نے دیکھا، اللہ کے رسول صلی اللہ علیہ وسلم ان کلمات کو ہاتھ سے شمار کرتے تھے۔ (دوسرا کام یہ ہے کہ) ’’جب تم میں سے کوئی شخص اپنے بستر یا چارپائی پر لیٹے تو تینتیس دفعہ سبحان اللہ پڑھے، تینتیس دفعہ الحمدللہ پڑھے اور چونتیس دفعہ اللہ أکبر پڑھے۔ یہ زبان پر (پڑھنے کے لحاظ سے) سو کلمات ہیں اور میزان میں (ثواب کے لاظ سے) ایک ہزار ہیں۔‘‘ رسول اللہ صلی اللہ علیہ وسلمنے فرمایا: ’’تم میں سے کون ایسا شخص ہے جو ہر دن رات میں دو ہزار پانچ سوگناہ کرتا ہے؟‘‘ پوچھا گیا: اے اللہ کے رسول! ایک آدمی ان دو کاموں کی پابندی کیسے نہیں کرسکتا؟ آپ نے فرمایا: ’’جب کوئی آدمی نماز میں ہوتا ہے تو شیطان اس کے پاس آکر کہتا ہے‘‘ فلاں چیز یاد کر، فلاں چیز یاد کر۔ (اس طرح اس کی توجہ ادھر ادھر ہوجاتی ہے اوروہ نماز کے فوراً بعد اٹھ کر چلا جاتا ہے۔) اسی طرح سوتے وقت بھی شیطان آکر (ادھر ادھرکے خیالات میں پھنسا دیتا ہے اور) اسے سلا دیتا ہے۔ (اسے اس ذکر کی طرف توجہ ہی نہیں ہوتی)۔‘‘","f2":"(۱) سچ فرمایا رسول اللہ صلی اللہ علیہ وسلم نے، اس قدر آسان کام جو چند منٹوں میں مکمل ہو جاتا ہے، شیطان کی کوشش سے شاذ و نادر لوگ ہی اس پر عمل کرتے ہیں (وقلیل من عبادی الشکور) (سبا ۱۳:۳۴) (۲) اس حدیث مبارکہ میں ان اذکار کی اور اس امت کی فضیلت بیان کی گئی ہے کہ معمولی س کام پر کس قدر عظیم ثواب ہے۔ (۳) اس میں ان اذکار پر پابندی کرنے، زیادہ سےزیادہ نیکیاں اکٹھی کرنے اور سستی ترک کرنے کی ترغیب دلائی گئی ہے۔ (۴) اس حدیث مبارکہ سے یہ بھی معلوم ہوا کہ ہاتھوں کی انگلیوں پر تسبیح شمار کرنا مستحب ہے۔ (۵) شیطان ہر وقت انسان کو بھلائی کے کاموں سے روکنے میں مصروف عمل ہے، وہ انسان کو اللہ کے ذکر سے غافل کرکے اس پر اپنے داؤ پیچ لڑاتا ہے۔ جو بھی اس کی پیروی کرلے وہ خسارہ پانے والوں میں سے ہوگیا۔"}],[1349,"کعب بن عجرہ رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"کچھ ایسے الفاظ ہیں جنہیں ہر نماز کے بعد کہا جاتا ہے ان کا کہنے والا ناکام و نامراد نہیں ہو سکتا، یعنی جو ہر نماز کے بعد تینتیس بار «سبحان اللہ» تینتیس بار «الحمد لله» اور چونتیس بار «اللہ أکبر» کہے۔","الألباني: صحيح",{"u2":"حضرت کعب بن عجرہ رضی اللہ عنہ سے مروی ہے، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’فرض نمازوں کے بعد پڑھے جانےوالے کچھ ایسے کلمات ہیں جنھیں پڑھنے والا کبھی ناکام نہیں ہوتا۔ ہر نماز کے بعد تینتیس دفعہ سبحان اللہ، تینتیس دفعہ الحمدللہ اور چونتیس دفعہ اللہ اکبر پڑھے۔","f2":"’’ناکام نہیں ہوتا۔‘‘ یعنی جس طرح بھی پڑھے ثواب ضرور ملتا ہے، خواہ کچھ غفلت بھی ہو جائے۔ یا جنت میں ضرور داخل ہوگا۔"}],[1350,"زید بن ثابت رضی اللہ عنہ کہتے ہیں کہ لوگوں کو حکم دیا گیا کہ وہ ہر نماز کے بعد تینتیس بار «سبحان اللہ» تینتیس بار «الحمد لله» اور چونتیس بار «اللہ أکبر» کہیں، پھر ایک انصاری شخص سے اس کے خواب میں پوچھا گیا کہ رسول اللہ صلی اللہ علیہ وسلم نے تمہیں ہر نماز کے بعد تینتیس بار «سبحان اللہ»تینتیس بار «الحمد لله» اور چونتیس بار «اللہ أکبر» کہنے کا حکم دیا ہے؟ اس نے کہا: ہاں، تو پوچھنے والے نے کہا: تم انہیں پچیس، پچیس بار کر لو، اور باقی پچیس کی جگہ «لا الٰہ إلا اللہ» کہا کرو، تو جب صبح ہوئی تو وہ نبی اکرم صلی اللہ علیہ وسلم کے پاس آئے، اور آپ سے سارا واقعہ بیان کیا، تو آپ نے فرمایا: \"اسے اسی طرح کر لو\"۔","الألباني: صحيح",{"u2":"حضرت زید بن ثابت رضی اللہ عنہ فرماتے ہیں کہ لوگوں کو حکم دیا گیا (استحاباً) کہ ہر فرض نماز کے بعد تینتیس دفعہ سبحان اللہ، تینتیس دفعہ الحمدللہ اور چونتیس دفعہ اللہ اکبر کہیں۔ ایک انصاری صحابی کو خواب آیا۔ اسے کہا گیا: تمھیں رسول اللہ صلی اللہ علیہ وسلم نےحکم دیا ہے کہ تم ہر نماز کے بعد تینتیس دفعہ سبحان اللہ، تینتیس دفعہ الحمدللہ اور چونتیس دفعہ اللہ اکبر کہو؟ اس نے کہا: ہاں۔ خواب میں نظر آنے والے شخص نے کہا: تم انھیں پچیس دفعہ کرلو اور ان میں لا الہ الا اللہ کا اضافہ کرلو۔ جب صبحہوئی تو وہ انصاری صحابی نبی صلی اللہ علیہ وسلم کے پاس حاضر ہوئے اور پورا خواب بیان کیا۔ آپ نے فرمایا: ’’ایسے کرلو۔‘‘","f2":"(۱) خواب حجت نہیں ہوگا کیونکہ یقین نہیں ہوتا کہ وہ منجانب اللہ ہے یا منجانب شیطان یا اپنے دماغی خیالات، البتہ رسول اللہ صلی اللہ علیہ وسلم کی تصدیق کے بعد خواب حجت ہے کیونکہ اس کا منجانب اللہ ہونا یقینی ہوگیا، لہٰذا اب یہ بھی امر رسول ہی ہے۔ (۲) لوگوں کا عام عمل تینتیس والی تعداد پر ہے کیونکہ وہ روایات بہت زیادہ مشہور ہیں جب کہ پچیس والی روایات اس قدر معروف نہیں ہیں، البتہ یہ بھی بلاشبہ جائز اور درست ہے۔ اسی طرح کبھی کبھی دس والی روایات پر بھی عمل کر لینا چاہیے۔ (۳) جب صحابی کہے: ’’ہمیں حکم دیا گیا‘‘ یا ’’لوگوں کو حکم دیا گیا‘‘ تو وہحدیث مرفوع کے حکم میں ہوتی ہے۔ جمہور محدثین اسی کے قائل ہیں۔"}],[1351,"عبداللہ بن عمر رضی اللہ عنہم سے روایت ہے کہ ایک آدمی نے دیکھا جیسے سونے والا خواب دیکھتا ہے، اس سے خواب میں پوچھا گیا: تمہارے نبی کریم صلی اللہ علیہ وسلم نے تمہیں کس چیز کا حکم دیا ہے؟ اس نے کہا: آپ نے ہمیں حکم دیا کہ ہم تینتیس بار «سبحان اللہ» تینتیس بار «الحمد لله» اور چونتیس بار «اللہ أكبر» کہیں، تو یہ کل سو ہیں، تو اس نے کہا: تم پچیس بار «سبحان اللہ» پچیس بار «الحمد لله» پچیس بار «اللہ أكبر» اور پچیس بار «لا إله إلا اللہ»کہو، یہ بھی سو ہیں، چنانچہ جب صبح ہوئی تو اس آدمی نے اسے نبی اکرم صلی اللہ علیہ وسلم سے ذکر کیا، تو آپ صلی اللہ علیہ وسلم نے فرمایا: \"تم لوگ ایسے ہی کر لو جیسے انصاری نے کہا\"۔","الألباني: حسن صحيح",{"u2":"حضرت ابن عمر رضی اللہ عنہما سے روایت ہے کہ ایک صحابی نے خواب میں دیکھا۔ ان سے پوچھا گیا: تمھارےنبی صلی اللہ علیہ وسلم نے تمھیں کس چیز کا حکم دیا ہے؟ انھوں نے کہا: آپ نے ہمیں حکم دیا ہے کہ ہم (فرض نماز کے بعد) تینتیس دفعہ سبحان اللہ، تینتیس دفعہ الحمدللہ اور چونتیس دفعہ اللہ آکبر کہیں۔ یہ ایک سو ہوجائیں گے۔ اس نے کہا: تم پچیس دفعہ سبحان اللہ، پچیس دفعہ الحمدللہ، پچیس دفعہ اللہ أکبر اور پچیس دفعہ لا إلہ إلا اللہ پڑھ لیا کرو۔ یہ بھی ایک سو ہو جائیں گے۔ جب صبح ہوئی تو اس صحابی نے یہ خواب نبی صلی اللہ علیہ وسلم سے بیان کیا۔ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’جیسے یہ انصاری کہتا ہے، اسی طرح کرلو۔‘‘"}],[1352,"ام المؤمنین جویریہ بنت حارث رضی اللہ عنہا سے روایت ہے کہ نبی اکرم صلی اللہ علیہ وسلم ان کے پاس سے گزرے، اور وہ مسجد میں دعا مانگ رہی تھیں، پھر آپ ان کے پاس سے دوپہر کے قریب گزرے (تو دیکھا وہ اسی جگہ دعا میں مشغول ہیں) تو آپ نے ان سے فرمایا: \"تم اب تک اسی حال میں ہو؟\" انہوں نے کہا: جی ہاں، آپ صلی اللہ علیہ وسلم نے فرمایا: \"کیا میں تمہیں ایسے کلمات نہ بتاؤں کہ جنہیں تم کہا کرو؟ وہ یہ ہیں: «سبحان اللہ عدد خلقه سبحان اللہ عدد خلقه سبحان اللہ عدد خلقه سبحان اللہ رضا نفسه سبحان اللہ رضا نفسه سبحان اللہ رضا نفسه سبحان اللہ زنة عرشه سبحان اللہ زنة عرشه سبحان اللہ زنة عرشه سبحان اللہ مداد كلماته سبحان اللہ مداد كلماته سبحان اللہ مداد كلماته» \"اللہ کی پاکی اس کی مخلوق کی تعداد کے برابر، اللہ کی پاکی بیان ہو اس کی مخلوق کی تعداد کے برابر، اللہ کی پاکی بیان ہو اس کی مخلوق کی تعداد کے برابر، اللہ کی پاکی بیان ہو جتنا وہ چاہے، اللہ کی پاکی بیان ہو جتنا وہ چاہے، اللہ کی پاکی بیان ہو جتنا وہ چاہے، اللہ کی پاکی بیان ہو اس کے عرش کے وزن کے برابر، اللہ کی پاکی بیان ہو اس کے عرش کے وزن کے برابر، اللہ کی پاکی بیان ہو اس کے عرش کے وزن کے برابر، اللہ کی پاکی بیان ہو اس کے بے انتہا کلمات کے برابر، اللہ کی پاکی بیان ہو اس کے بے انتہا کلمات کے برابر، اللہ کی پاکی بیان ہو اس کے بے انتہا کلمات کے برابر\"۔","الألباني: صحيح",{"u2":"حضرت ابن عباس رضی اللہ عنہا سے روایت ہے کہ نبی صلی اللہ علیہ وسلم اپنی زوجہ محترمہ جویریہ بنت حارث رضی اللہ عنہا کےپاس سے گزرے جب کہ وہ اپنی جائے نماز پر بیٹھی ذکر اذکار کر رہی تھیں۔ پھر آپ دوپہر کے قریب دوبارہ ان کے پاس سے گزرے۔ (وہ اس وقت بھی بیٹھی تھیں) آپ نے ان سے فرمایا: ’’تم اس وقت سے اسی حالت میں ہو؟‘‘ انھوں نے کہا: جی ہاں۔ آپ نے فرمایا: ’’میں تمھیں کچھ کلمات نہ سکھا دوں جنھیں تم پڑھا کرو: [سبحان اللہ عدد خلقہ] ’’اللہ کی تسبیح ہے، اس کی مخلوقات کی تعداد کے برابر۔‘‘ تین دفعہ [سبحان اللہ رضا نفسہ] ’’اللہ کی تسبیح ہے اس کی رضا مندی کے مطابق۔‘‘ تین دفعہ [سبحان اللہ زنۃ عرشہ] ’’اللہ کی تسبیح ہے اس کے عرش کے وزن کے مطابق۔‘‘ تین دفعہ [سبحان اللہ مداد کلماتہ] ’’اللہ کی تسبیح ہے اس کے کلمات کی روشنائی کے برابر۔‘‘ تین دفعہ۔","f2":"(۱) صحیح مسلم کی حدیث میں یہ بھی صراحت ہے کہ آپ صلی اللہ علیہ وسلم نے فرمایا: ’’آج جو کچھ تم نے کہا ہے، یہ کلمات ان سے وزن کیے جائیں تو وزن میں ان (تمھارے کہے ہوئے) کلمات سے بڑھ جائیں گے۔‘‘ اور وہ کلمات اس طرح مذکور ہیں [سبحان اللہ و بحمدہ عدد خلقہ و رضا نفسہ وزنۃ عرشہ و مداد کلماتہ] (صحیح مسلم، الذکر والدعاء، حدیث: ۲۷۲۶) ان کلمات کا مطلب یہ ہے کہ اللہ تعالیٰ بے انتہا تسبیحات کا مستحق ہے اور ان مذکورہ چیزوں کی تعداد اور مقدار و وزن کو کوئی نہیں جانتا۔ وہ انتہائی وزنی اوربے انتہا ہیں۔ (۲) یہ بھی ثابت ہوا کہ بعض ذکر، بعض سے افضل ہوتےہیں اور ان کا ثواب زیادہ ہوتا ہے کیونکہ سب کلام برابر نہیں ہوتے۔ (۳) اس سے یہ بھی پتہ چلتا ہے کہ نبی صلی اللہ علیہ وسلم کے عہد میں عورتیں بہت زیادہ ذکر اذکار اور عبادت کرتی تھیں۔ (۴) نماز فجر سے لے کر دن چھڑنے تک ذکر اذکار کرنا مستحسن امر ہے۔"}],[1353,"عبداللہ بن عباس رضی اللہ عنہم کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم کے پاس کچھ فقراء نے آ کر عرض کیا: اللہ کے رسول! مالدار لوگ (بھی) نماز پڑھتے ہیں جیسے ہم پڑھتے ہیں، وہ بھی روزے رکھتے ہیں جیسے ہم رکھتے ہیں، ان کے پاس مال ہے وہ صدقہ و خیرات کرتے ہیں، اور (اللہ کی راہ میں) خرچ کرتے ہیں، (اور ہم نہیں کر پاتے ہیں تو ہم ان کے برابر کیسے ہو سکتے ہیں) یہ سن کر نبی اکرم صلی اللہ علیہ وسلم نے فرمایا: \"جب تم لوگ نماز پڑھ چکو تو تینتیس بار «سبحان اللہ»تینتیس بار «الحمد لله» اور تینتیس بار «اللہ أكبر» اور دس بار «لا إله إلا اللہ» کہو، تو تم اس کے ذریعہ سے ان لوگوں کو پا لو گے جو تم سے سبقت کر گئے ہیں، اور اپنے بعد والوں سے سبقت کر جاؤ گے\"۔","الألباني: منكر بتعشير التهليل",{"u2":"حضرت ابن عباس رضی اللہ عنہ بیان کرتے ہیں کہ فقیر صحابہ رسول اللہ صلی اللہ علیہ وسلم کے پاس آئے اور عرض کیا: اے اللہ کے رسول! مالدار لوگ ہماری طرح نمازیں پڑھتے ہیں اور ہماری طرح روزے رکھتے ہیں، لیکن ان کے پاس مال ہے جس سے وہ صدقہ کرتے ہیں اور غلام آزاد کرتے ہیں۔ (ہم ان کے درجے کو کیسے پہنچ سکتے ہیں؟) نبی صلی اللہ علیہ وسلم نے فرمایا: ’’جس تم نماز پڑھ چکو تو تینتیس مرتبہ سبحان اللہ، تینتیس مرتبہ الحمدللہ، تینتیس مرتبہ اللہ أکبر اور دس دفعہ لا الہ الا اللہ پڑھ لیا کرو۔ تم اس عمل کی بدولت اپنے سے آگے بڑھ جانے والے لوگوں کو جا ملو گے اور ان لوگوں سے بہت آگے بڑھ جاؤ گے جو تم سے پیچھے ہیں۔‘‘ (یا جو یہ عمل نہیں کرتے۔)","f2":"(۱) مذکورہ روایت کو محقق کتاب نے سنداً ضعیف قرار دیا ہے اور مزید لکھا ہے کہ دس دفعہ [لا إلہ إلا اللہ] والے الفاظ کے علاوہ باقی روایت کی اصل صحیح ہے کیونکہ مذکورہ روایت اس اضافہ کے بغیر صحیح بخاری اور صحیح مسلم میں موجود ہے، نیز اس اضافے کو شیخ البانی رحمہ اللہ اور شارح سنن النسائی علامہ اتیوبی نے منکر قرار دیا ہے۔ بنابریں مذکورہ روایت ’’دس دفعہ [لا إلہ إلا اللہ] کےاضافے کے علاوہ صحیح ہے۔ تفصیل کے لیے دیکھیے: (ذخیرۃ العقبی شرح سنن النسائي: ۴۲۴-۴۲۱/۱۵، و ضعیف سنن النسائي، رقم: ۱۳۵۳) (۲) غنی اور فقر اگرچہ اللہ تعالیٰ کی تقدیر سے ہیں مگر مالدار کو اپنا مال خرچ کرنے کا ثواب تو ملے گا جس سے فقیر شخص خرچ نہ کرنے کی وجہ سے محروم رہے گا جیسے لنگڑا اگرچہ اللہ تعالیٰ کی تقدیر سے ہے مگر وہ بہت سارے ان مفادات ومنافع سے محروم رہتا ہے جن سے دو ٹانگوں والے بہرہ ور ہوتے ہیں اور اس پر کوئی اعتراض نہیں ہے۔ اس اعتبار سے یہ روایت معنا صحیح ہے، البتہ اس روایت میں دس مرتبہ [لا إلہ إلا اللہ] والے الفاظ کا اضافہ منکر ہے۔ (۳) بلندیٔ درجات کے لیے نیک اعمال میں مقابلہ کرنا جائز ہے۔ (۲) کسی پر اللہ کے انعامات دیکھ کر رشک کرنا اور اس جیسی نعمتوں کی خواہش کرنا درست ہے۔ (۵) کبھی چھوٹے سے عمل کی بناپر بہت بڑے عمل کی فضیلت اور ثواب حاصل ہو جاتا ہے۔"}],[1354,"ابوہریرہ رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"جو شخص فجر کی نماز کے بعد سو بار «سبحان اللہ» اور سو بار «لا إله إلا اللہ» کہے گا، اس کے گناہ بخش دیے جائیں گے، اگرچہ وہ سمندر کے جھاگ کے برابر ہوں\"۔","الألباني: صحيح الإسناد",{"u2":"حضرت ابوہریرہ رضی اللہ عنہ سے روایت ہے، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’جو شخص صبح کی نماز کے بعد سو دفعہ سبحان اللہ اور سو دفعہ لا إلہ إلا اللہ پڑھے، اس کے سب گناہ معاف ہو جائیں گے اگرچہ وہ سمندر کی جھاگ کےبرابر ہوں۔‘‘","f2":"(۱) مذکورہ روایت کو محقق کتاب نے سنداً ضعیف قرار دیا ہے جبکہ دیگر محققین نے اسےصحیح قرار دیا ہے، نیز شارح سنن النسائی نے اس پر تفصیلی کلام کرتے ہوئے اسے صحیح قرار دیا ہے اور ان کے کلام سے یہی بات راجح معلوم ہوتی ہے کہ مذکورہ روایت صحیح اور قابل حجت ہے۔ واللہ أعلم۔ مزید تفصیل کے لیے دیکھیے: (صحیح سنن النسائي: ۳۴۵/۵، رقم: ۱۳۵۳، و ذخیرۃ العقبی شرح سنن النسائي: ۴۲۶،۴۲۵/۱۵) (۲) یہ رب کریم کا کرم ہے کہ چھوٹے سے کام پر عظیم جزا سےسرفراز فرماتا ہے۔ اس میں یہ احتمال بھی ہے کہ یہ عظیم خوشخبری اس شخص کے لیے ہے جو اس عمل پر ہمیشگی کرتا ہے اور اس پر ہمیشگی خوش بخت مومن ہی کرسکتا ہے۔ اللھم! اجعلنا منھم۔ (۳) سمندر کی جھاگ کنایہ ہے بے انتہا سے۔ ہمارے علم کے لحاظ سے سمندر کی جھاگ بے انتہا ہی ہے۔ اسے کثرت بھی کہا جا سکتا ہے۔ واللہ أعلم۔"}],[1355,"عبداللہ بن عمرو رضی اللہ عنہم کہتے ہیں کہ میں نے رسول اللہ صلی اللہ علیہ وسلم کو تسبیح گنتے ہوئے دیکھا ۱؎۔\n§وضاحت\n۱؎: مگر نبی اکرم صلی اللہ علیہ وسلم اور صحابہ کرام رضی اللہ عنہم اجمعین بھی یہ تسبیحات اپنی انگلیوں کے پوروں پر گنا کرتے تھے کسی اور چیز پر نہیں۔","الألباني: صحيح",{"u2":"حضرت عبداللہ بن عمرو رضی اللہ عنہما بیان کرتے ہیں کہ میں نے رسول اللہ صلی اللہ علیہ وسلم کو تسبیحات شمار کرتے دیکھا۔","f2":"مذکورہ احادیث میں معین مقدار میں ذکر کرنے کا حکم ہے، لہٰذا تسبیحات اور دیگر اذکار کو شمار کرنا مشروع عمل ہے۔ رسول اللہ صلی اللہ علیہ وسلم سے اس کا طریقہ بھی منقول ہے جیسا کہ حضرت عبداللہ بن عمرو رضی اللہ عنہا فرماتے ہیں: میں نے رسول اللہ صلی اللہ علیہ وسلم کو دائیں ہاتھ کےساتھ تسبیحات شمار کرتے دیکھا۔ (سنن أبي داود، الوتر، حدیث: ۱۵۰۲) البتہ جس شخص نے کےلیے دائیں ہاتھ کی انگلیوں پر تسبیحات شمار کرنا واقعی مشکل اور دشوار ہو تو اس کے لیے اس مقصد کی خاطر بایاں ہاتھ یا کوئی دوسرا ذریعہ استعمال کرنا ان شاء اللہ جائز ہوگا۔ (لا یکلف اللہ نفسا الا وسعھا) (البقرۃ ۲۸۶:۲) واللہ أعلم۔"}],[1356,"ابو سعید خدری رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم (رمضان کے) مہینہ کے بیچ کے دس دنوں میں اعتکاف کرتے تھے، جب بیسویں رات گزر جاتی اور اکیسویں کا استقبال کرتے تو آپ اپنے گھر واپس آ جاتے، اور وہ لوگ بھی واپس آ جاتے جو آپ کے ساتھ اعتکاف کرتے تھے، پھر ایک مہینہ ایسا ہوا کہ آپ جس رات گھر واپس آ جاتے تھے اعتکاف ہی میں ٹھہرے رہے، لوگوں کو خطبہ دیا، اور انہیں حکم دیا جو اللہ نے چاہا، پھر فرمایا: \"میں اس عشرہ میں اعتکاف کیا کرتا تھا پھر میرے جی میں آیا کہ میں ان آخری دس دنوں میں اعتکاف کروں، تو جو شخص میرے ساتھ اعتکاف میں ہے تو وہ اپنے اعتکاف کی جگہ میں ٹھہرا رہے، میں نے اس رات(لیلۃ القدر) کو دیکھا، پھر وہ مجھے بھلا دی گئی، تم اسے آخری دس دنوں کی طاق راتوں میں تلاش کرو، اور میں نے اپنے آپ کو دیکھا کہ میں پانی اور مٹی میں سجدہ کر رہا ہوں\"، ابو سعید خدری کہتے ہیں: اکیسویں رات کو بارش ہوئی تو مسجد رسول اللہ صلی اللہ علیہ وسلم کی نماز کی جگہ پر ٹپکنے لگی، چنانچہ میں نے آپ کو دیکھا کہ آپ صبح کی نماز سے فارغ ہو کر لوٹ رہے ہیں، اور آپ کا چہرہ مٹی اور پانی سے تر تھا۔","الألباني: صحيح",{"u2":"حضرت ابوسعید خدری رضی اللہ عنہ بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم ماہ رمضان المبارک کے درمیان والے دس دنوں میں اعتکاف بیٹھتے تھے۔ پھر جب بیس راتیں گزر جاتیں اور اکیسویں رات آ جاتی تو آپ اور آپ کے ساتھ اعتکاف بیٹھنے والے گھروں کو چلے جاتے۔ پھر ایک سال اس رات بھی اعتکاف میں بیٹھے رہے جس رات آپ گھر کولوٹ جایا کرتے تھے۔ پھر آپنے لوگوں کو خطبہ دیا اور جو اللہ نے چاہا اس کا انھیں حکم دیا۔ پھر فرمایا: ’’میں درمیان والے دس دنوں کا اعتکاف بیٹھا کرتا تھا۔ اب مجھے خیال آیا ہے کہ میں آخری دس دنوں کا بھی اعتکاف بیٹھوں، اس لیے جو شخص میرے ساتھ اعتکاف بیٹھا ہے، وہاپنی اعتکاف گاہ میں بیٹھا رہے۔ تحقیق میں نے لیل القدر خواب میں دیکھی تھی مگر مجھے وہ بھلوا دی گئی، لہٰذا اس رات کو آخری دس دنوں کی طاق راتوں میں تلاش کرو۔ میں نےخواب میں دیکھا ہے کہ میں کیچڑ میں سجدہ کر رہا ہوں۔‘‘ حضرت ابوسعید رضی اللہ عنہ بیان کرتے ہیں کہ اکیسویں رات ہی ہم پر بارش برسی۔ رسول اللہ صلی اللہ علیہ وسلم کی سجدہ گاہ میں مسجد ٹپکنے لگی۔ میں نے دیکھا کہ جب آپ صبح کی نماز سے فارغ ہوکر ہماری طرف مڑے تو آپ کا چہر ہ (یعنی ماتھا اور ناک کا کنارہ) کیچڑ سے تر تھا۔","f2":"(۱) خواب میں نبی صلی اللہ علیہ وسلم کو لیلۃ القدر معین رات میں بتلائی گئی تھی مگر دوسری روایات کے مطابق بعض لوگوں کے جھگڑے کی وجہ سے آپ کے ذہن سے نکل گئی۔ آپ کو صرف نشانی یاد رہ گئی کہ میں کیچڑ میں سجدہ کر رہا ہوں، لیکن یہ یاد رہے کہ یہ نشانی صرف اس سال کے لیے تھی، نہ کہ ہمیشہ کے لیے کیونکہ آپ نے بعض دوسرے مواقع پر اور نشانیاں بھی بتائی ہیں، نیز یہ رات ہر سال بدلتی رہتی ہے مگر آخری عشرے کی طاق راتوںہی میں۔ (۲) نماز سے فارغ ہونے کے بعد ماتھا وغیرہ پونچھ لینا چاہیے تاکہ سجدے میں اگر کوئی تنکا یا مٹی لگی ہو تو صاف ہو جائے۔ اس طرحریا کاری کا خطرہ نہیں رہے گا۔ مندرجہ بالا روایات میں تو ابھی آپ نے سلام پھیرا ہی تھا۔"}],[1357,"جابر بن سمرہ رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم جب نماز فجر سے فارغ ہو جاتے تو آپ اپنے مصلی ہی پر بیٹھے رہتے یہاں تک کہ سورج نکل آتا۔","الألباني: صحيح",{"u2":"حضرت جابر بن سمرہ رضی اللہ عنہ فرماتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم جب فجر کی نماز پڑھ چکتے تو سورج طلوع ہونے تک اپنی نماز والی جگہ میں بیٹھے رہتے۔"}],[1358,"سماک بن حرب کہتے ہیں کہ میں نے جابر بن سمرہ رضی اللہ عنہ سے پوچھا: آپ رسول اللہ صلی اللہ علیہ وسلم کے ساتھ بیٹھا کرتے تھے؟ تو انہوں نے کہا: ہاں (پھر انہوں نے بیان کیا) کہ رسول اللہ صلی اللہ علیہ وسلم جب نماز فجر پڑھ لیتے تو اپنی نماز کی جگہ پر بیٹھے رہتے یہاں تک کہ سورج نکل آتا، پھر آپ کے صحابہ آپ سے میں بات چیت کرتے، جاہلیت کے دور کا ذکر کرتے، اور اشعار پڑھتے، اور ہنستے اور رسول اللہ صلی اللہ علیہ وسلم بھی مسکراتے۔","الألباني: صحيح",{"u2":"حضرت سماک بن حرب سے روایت ہے کہ میں نے حضرت جابر بن سمرہ رضی اللہ عنہ سے کہا: آپ رسول اللہ صلی اللہ علیہ وسلم کے پاس بیٹھا کرتےتھے؟ انھوں نے فرمایا: ہاں! رسول اللہ صلی اللہ علیہ وسلم جب فجر کی نماز پڑھ لیتے تو سورج طلوع ہونے تک اپنی نماز والی جگہ میں بیٹھے رہتے۔ آپ کے صحابۂ کرام رضی اللہ عنہم آپ کے سامنے باتیں کرتے رہتے۔ کبھی جاہلیت کی باتیں ذکر کرتے، کبھی شعر پڑھتے اور ہنستے۔ اللہ کے رسول صلی اللہ علیہ وسلم مسکراتے رہتے۔","f2":"نماز کے بعد مسنون ذکر اذکار کے لیے بیٹھنا تو متفق علیہ چیز ہے۔ امام کو دوسروں کی نسبت زیادہ پابندی کرنی چاہیے۔ ذکر اذکار کے علاوہ جن نمازوں کے بعد مؤکدہ سنتیں نہیں، مثلاً: فجر اور عصر تو مناسب ہے کہ امام بیٹھا رہے تاکہ لوگ اپنے مسائل پیش کریں۔ اس طرح عوام الناس سے امام کا رابطہ قائم ہوگا۔ معلومات عامہ سے واقفیت رہے گی۔ لوگوں کے ساتھ خوش طبعی کے ساتھ میل جول رکھنا بھی نیکی ہے۔ فرض نماز کے بعد ذکر اذکار مؤکدہ سنتوں سے پہلےپڑھنے چاہئیں۔ عام احادیث سے یہی معلوم ہوتا ہے۔ باقی رہی حضرت عائشہ رضی اللہ عنہا کی یہ حدیث کہ آپ سلام کے بعد صرف [اللھم انت السلام ……… الخ] والی دعا پڑھنے کے برابر ہی بیٹھتے تھے تو اس سے مراد قبلہ رخ بیٹھنا ہے نہ کہ مطلقاً، یعنی اتنی دیر آپ قبلہ رخ بیٹھتے، پھر مقتدیوں کی طرف متوجہ ہو جاتے۔ صحابہ آپ کے پاس ایسے شعر ہی پڑھتے ہوں گے جو شاعرانہ یا وہ گوئی سے پاک ہوں گے۔ اچھے اشعار تھوڑی مقدار میں باقاعدہ مجلس قائم کیے بغیر پڑھنے میں کوئی حرج نہیں، البتہ مساجد میں باقاعدہ شعر گوئی کی مجالس منعقد کرنا درست نہیں۔ شعروں سے زیادہ دلچسپی قرآن مجید سے دور کرتی ہے۔"}],[1359,"سدی (اسماعیل بن عبدالرحمٰن) کہتے ہیں کہ میں نے انس بن مالک رضی اللہ عنہ سے پوچھا کہ میں اپنے داہنے اور بائیں سلام پھیر کر کیسے پلٹوں؟ تو انہوں نے کہا: رہا میں تو میں نے اکثر رسول اللہ صلی اللہ علیہ وسلم کو دائیں طرف سے پلٹتے دیکھا ہے۔","الألباني: صحيح",{"u2":"حضرت سدی سے روایت ہے کہ میں نے حضرت انس بن مالک رضی اللہ عنہ سے پوچھا کہ جب میں نماز سے فارغ ہو جاؤں تو کیسے اٹھوں؟ دائیں جانب سے یا بائیں جانب سے؟ انھوں نے فرمایا: میں نے تو رسول اللہ صلی اللہ علیہ وسلم کو عمومی طور پر دائیں جانب مڑ کر اٹھتے دیکھا ہے۔","f2":"باب کا مقصود یہ معلوم ہوتا ہے کہ فراغت کے بعد گھر جاتے وقت کس طرف سے مڑنا چاہیے، دائیں سے یا بائیں سے؟ ظاہر ہے جس طرف کو حاجت ہو اٹھ کر جا سکتا ہے مگر دائیں جانب کو ترجیح دینا اچھی بات ہے۔ پھر جس طرف جی چاہے چلا جائے، البتہ دائیں جانب کو لازم نہ سمجھے۔ رسول اکرم صلی اللہ علیہ وسلم نماز کے بعد مقتدیوں کی طرف منہ کرکے بیٹھتے تھے۔ اس طرح آپ کا گھر دائیں جانب بن جاتا تھا تو آپ عموماً دائیں جانب کو ہی اٹھ کر تشریف لے جاتے تھے۔ کبھی گھر نہ جانا ہوتا تو دوسری جانب بھی اٹھتے تھے۔ اگر آپ قبلہ رخ بیٹھے ہوتے تو آپ کا گھر بائیں جانب تھا۔ حضرت ابن مسعود رضی اللہ عنہ نے دائیں جانب سے اٹھنے کو لازم قرار دینا برا سمجھا ہے۔ باب کا مقصود یہ بھی ہوسکتا ہے کہ امام نماز کے بعد مقتدیوں کی طرف کس جانب سے مڑے؟ دونوں طرف سے مڑ سکتا ہے مگر دائیں جانب افضل ہے کیونکہ نبیٔ اکرم صلی اللہ علیہ وسلم ہر کام میں دائیں جانب کو زیادہ پسند فرماتے تھے۔ صحابۂ کرام رضی اللہ عنہم قصداً دائیں جانب کھڑے ہوتے تھے کہ رسول اللہ صلی اللہ علیہ وسلم کا رخ انور پہلے ہماری طرف ہوگا۔ واللہ أعلم۔"}],[1360,"اسود کہتے ہیں کہ عبداللہ بن مسعود رضی اللہ عنہ نے کہا: تم میں سے کوئی خود سے شیطان کا کوئی حصہ نہ کرے کہ غیر ضروری چیز کو اپنے اوپر لازم سمجھ لے، اور داہنی طرف ہی سے پلٹنے کو اپنے اوپر لازم کر لے، میں نے تو رسول اللہ صلی اللہ علیہ وسلم کو اکثر بائیں طرف سے پلٹتے دیکھا ہے۔","الألباني: صحيح",{"u2":"حضرت عبداللہ بن مسعود رضی اللہ عنہ فرماتے ہیں کہ تم میں سے کوئی شخص اپنے آپ پر شیطان کا حصہ نہ رکھے کہ وہ اپنے آپ پر ضروری قرار دے کہ صرف دائیں جانب ہی سے مڑے گا۔ بلاشبہ میں نے تو رسول اللہ صلی اللہ علیہ وسلم کو اکثر بائیں جانب سے مڑتے دیکھا ہے۔","f2":"’’اپنے آپ پر شیطان کا حصہ نہ رکھے۔‘‘ یعنی غیرواجب کو خود ہی واجب کر لینا شریعت میں مداخلت ہے، شیطان کی پیروی ہے اور رسول اللہ صلی اللہ علیہ وسلم کے طریقے کی مخالفت ہے۔ گویا دائیں جانب سے مڑنے کو ضروری سمجھنا درست نہیں۔ ہاں، اگر کوئی دونوں جانب سے مڑنے کو جائز سمجھ کر دائیں جانب کو ترجیح دے تو کوئی حرج نہیں۔"}],[1361,"ام المؤمنین عائشہ رضی اللہ عنہا کہتی ہیں کہ میں نے رسول اللہ صلی اللہ علیہ وسلم کو کھڑے ہو کر اور بیٹھ کر، اور ننگے پاؤں اور جوتے پہن کر بھی نماز پڑھتے دیکھا ہے، اور آپ سلام پھیر نے کے بعد (کبھی) اپنے دائیں طرف پلٹتے، اور (کبھی) اپنے بائیں طرف۔","الألباني: صحيح الإسناد",{"u2":"حضرت عائشہ رضی اللہ عنہا فرماتی ہیں کہ میں نے دیکھا کہ رسول اللہ صلی اللہ علیہ وسلم کھڑے ہوکر بھی پانی پی لیتے تھے اور بیٹھ کر بھی۔ ننگے پاؤں بھی نماز پڑھ لیا کرتے تھے اور جوتے پہن کر بھی اور نمازیوں کی طرف دائیں طرف سے بھی مڑ جاتے تھے اور بائیں طرف سے بھی۔","f2":"بلاوجہ تشدد درست نہیں۔ جب دونوں طرف دلائل ہوں تو بجائے جھگڑنے اور بات کو طول دینے کے وجہ ترجیح ڈھونڈنے کی کوشش کرنی چاہیے۔ بلاوجہ کسی ایک بات پر جم جانا مناسب نہیں۔ اسی طرح وہ مسائل جو صحابۂ کرام رضی اللہ عنہم کے دور میں مختلف فیہ رہے اور ان پر اتفاق نہ ہو سکا، ان میں دونوں صورتوں کے جواز کا فتویٰ دیا جائے بشرطیکہ معاملہ جواز و استحباب کا ہو، وگرنہ بصور تِ تعارض جواز و اباحت پر حرمت و ممانعت کو مقدم کرنا ہی محتاط راستہ ہے، البتہ جو مسئلہ صحابۂ کرام رضی اللہ عنہم میں متفق علیہ ہو، اسے مضبوطی سے پکڑا جائے کیونکہ صحابۂ کرام رضی اللہ عنہم غلطی پر متفق نہیں ہوسکتے تھے۔"}],[1362,"ام المؤمنین عائشہ رضی اللہ عنہا کہتی ہیں کہ عورتیں رسول اللہ صلی اللہ علیہ وسلم کے ساتھ نماز فجر ادا کرتی تھیں، جب آپ سلام پھیرتے تو وہ اپنی چادروں میں لپٹی ہوئی نکل جاتیں، اور اندھیرے کی وجہ سے پہچانی نہ جاتیں ۱؎۔\n§وضاحت\n۱؎: اس حدیث سے معلوم ہوا کہ عورتیں امام کے سلام پھیرتے ہی اپنے گھروں کو واپس چلی جاتیں، تاکہ مردوں کی بھیڑ بھاڑ سے انہیں واسطہ نہ پڑے۔","الألباني: صحيح",{"u2":"حضرت عائشہ رضی اللہ عنہا فرماتی ہیں کہ عورتیں رسول اللہ صلی اللہ علیہ وسلم کے پیچھے فجر کی نماز پڑھتی تھیں۔ جب آپ سلام پھیرتے تو وہ فوراً اٹھ کر چلی جاتیں۔ انھوں نے بڑی چادریں لپیٹی ہوتی تھیں اور اندھیرے کی وجہ سے انھیں پہچانا نہیں جا سکتا تھا۔","f2":"عورتوں کو سلام پھیرتے ہی اٹھ جانا چاہیے۔ مرد بیٹھے رہیں۔ مردوں کو ذکر اذکار اور سنن مؤکدہ کی ادائیگی کے بعد گھر جانا چاہیے تاکہ عورتیں ان سے پہلے گھروں میں پہنچ جائیں اور اختلاط نہ ہو۔ چادر میں لپٹی ہونے کے باوجود عورت کی چال ڈھال سے اسے پہچانا جا سکتا ہے مگر اندھیرے میں یہ چیز بھی ممکن نہیں ہوتی تھی۔ معلوم ہوتا ہے کہ رسول اکرم صلی اللہ علیہ وسلم کی نماز سے فراغت غلس (اندھیرے) ہی میں ہو جاتی تھی۔"}],[1363,"انس بن مالک رضی اللہ عنہ کہتے ہیں کہ ایک دن رسول اللہ صلی اللہ علیہ وسلم نے ہمیں نماز پڑھائی، پھر ہماری طرف متوجہ ہو کر فرمایا: \"میں تمہارا امام ہوں، تو تم مجھ سے رکوع و سجود اور قیام میں جلدی نہ کرو، اور نہ ہی سلام میں، کیونکہ میں تمہیں اپنے آگے سے بھی دیکھتا ہوں، اور پیچھے سے بھی\"، پھر آپ نے فرمایا: \"قسم ہے اس ذات کی جس کے ہاتھ میں میری جان ہے، اگر تم وہ چیزیں دیکھتے جو میں دیکھتا ہوں تو تم ہنستے کم، اور روتے زیادہ\"، ہم نے عرض کیا: اللہ کے رسول! آپ نے کیا دیکھا ہے؟ آپ نے فرمایا: \"میں نے جنت اور جہنم دیکھی ہے\"۔","الألباني: صحيح",{"u2":"حضرت انس بن مالک رضی اللہ عنہ فرماتے ہیں کہ ایک دن رسول اللہ صلی اللہ علیہ وسلم نے ہمیں نماز پڑھائی، پھر ہماری طرف متوجہ ہوئے اور فرمایا: ’’میں تمھارا امام ہوں،لہٰذا رکوع، سجدے، اٹھنے اور سلام پھیرنے میں مجھ سے جلدی نہ کیا کرو۔ میں تمھیں ہرحال میں دیکھتا ہوں، تم آگے ہو یا پیچھے۔‘‘ پھر فرمایا: ’’قسم ہے اس ذات کی جس کے ہاتھ میں میری جان ہے! اگر تم وہ چیزیں دیکھ لو جو میں دیکھ چکا ہوں تو تم بہت کم ہنسو اور بہت زیادہ روؤ۔‘‘ ہم نے عرض کیا: اے اللہ کے رسول! آپ نے کیا دیکھا ہے؟ آپ نے فرمایا: ’’میں نے جنت اور دوزخ دیکھی ہے۔‘‘","f2":"(۱) بعض نے ’’انصراف‘‘ کے معنی سلام کے بعد اٹھ کر جانا‘‘ مراد لیے ہیں لیکن یہ معنی مراد لینا بعید ہیں کیونکہ سیاق کلام تقاضا کرتا ہے کہ اس سے مراد نماز میں سلام پھیرنا ہی ہے کیونکہ آپ نے رکوع، سجود اور قیام کا ذکر فرمایا، سلام کا ذکر نہیں کیا تو یہاں انصراف سے سلام ہی مراد ہے۔ اسی طرح آپ کا یہ فرمان کہ ’’میں تمھیں اپنے پیچھے سے دیکھتا ہوں۔‘‘ بھی دلالت کرتا ہے کہ جس جلدی سے منع کیا گیا ہے وہ نماز سے سلام پھیرنے میں جلدی ہے۔ امام نووی رحمہ اللہ نے بھی اس سے ’’سلام‘‘ ہی مراد لیا ہے۔ دیکھیے: (شرح صحیح مسلم للنووي، الصلاۃ، باب تحریم سبق الإمام……… حدیث: ۴۲۶) (۲) نماز میں امام سے جلدی کرنے کے متعلق دیکھیے، حدیث: ۹۲۲ کا فائدہ۔ (۳) نبیٔ اکرم صلی اللہ علیہ وسلم کا نماز میں پیچھے دیکھنا آپ کا معجزہ تھا۔ (تفصیل کے لیے دیکھیے، حدیث: ۸۱۴ کا فائدہ: ۲)"}],[1364,"ابوذر رضی اللہ عنہ کہتے ہیں کہ ہم نے رمضان میں رسول اللہ صلی اللہ علیہ وسلم کے ساتھ روزے رکھے، لیکن رسول اللہ صلی اللہ علیہ وسلم ہمیں تراویح پڑھانے کھڑے نہیں ہوئے یہاں تک کہ رمضان کے مہینہ کی سات راتیں رہ گئیں، تو آپ ہمیں تراویح پڑھانے کھڑے ہوئے (اور پڑھاتے رہے) یہاں تک کہ تہائی رات کے قریب گزر گئی، پھر چھٹی رات آئی لیکن آپ ہمیں پڑھانے کھڑے نہیں ہوئے، پھر جب پانچویں رات آئی تو آپ ہمیں تراویح پڑھانے کھڑے ہوئے (اور پڑھاتے رہے) یہاں تک کہ تقریباً آدھی رات گزر گئی، تو ہم نے عرض کیا: اللہ کے رسول! کاش آپ یہ رات پوری پڑھاتے، آپ نے فرمایا: \"آدمی جب امام کے ساتھ نماز پڑھتا ہے یہاں تک کہ وہ فارغ ہو جائے تو اس کے لیے پوری رات کا قیام شمار کیا جاتا ہے\"، پھر چوتھی رات آئی تو آپ ہمیں تراویح پڑھانے نہیں کھڑے ہوئے، پھر جب رمضان کے مہینہ کی تین راتیں باقی رہ گئیں، تو آپ نے اپنی بیٹیوں اور بیویوں کو کہلا بھیجا اور لوگوں کو بھی جمع کیا، اور ہمیں تراویح پڑھائی یہاں تک کہ ہمیں خوف ہوا کہیں ہم سے فلاح چھوٹ نہ جائے، پھر اس کے بعد مہینہ کے باقی دنوں میں آپ نے ہمیں تراویح نہیں پڑھائی۔ داود بن ابی ہند کہتے ہیں: میں نے پوچھا: فلاح کیا ہے؟ تو انہوں نے (ولید بن عبدالرحمٰن نے) کہا: سحری کھانا۔","الألباني: صحيح",{"u2":"حضرت ابوذر رضی اللہ عنہ بیان کرتے ہیں کہ ہم نے اللہ کے رسول صلی اللہ علیہ وسلم کے ساتھ رمضان المبارک کے روزے رکھے۔ نبی صلی اللہ علیہ وسلم نے ہمیں رات کو (تراویح کی) نماز پڑھائی حتی کہ رات کا تقریباً تیرسا حصہ گزر گیا۔ پھر چوبیسویں رات ہوئی تو ہمیں نماز نہیں پڑھائی۔ جب پچیسویں رات ہوئی تو پھر ہمیں نماز پڑھائی حتی کہ تقریباً نصف رات گزر گئی۔ ہم نے عرض کیا: اے اللہ کے رسول! اگر آپ ساری رات ہمیں نفل نماز پڑھاتے رہتے تو کیا ہی خوب ہوتا۔ آپ نے فرمایا: ’’جب کوئی شخص امام کے ساتھ نماز پڑھے اور امام کے واپس جانے تک ساتھ رہے تو اس کےلیے پوری رات کا قیام شمار کیا جاتا ہے۔‘‘ پھر چھبیسویں رات ہوئی تو آپ نے ہمیں نفل نماز نہ پڑھائی۔ جب ماہ مقدس کے تین دن باقی رہ گئے (یعنی ستائیسویں رات کو) تو آپ نے اپنی بیٹیوں اور بیویوں کو بھی بلابھیجا اور بہت لوگ جمع ہوگئے تو آپ نے ہمیں نفل نماز پڑھائی حتی کہ ہمیں خطرہ محسوس ہوا کہ ’’فلاح‘‘ رہ جائے گی۔ پھر اس کے بعد اس ماہ مقدس کی کسی رات کو ہمیں نفل نماز (تراویح) نہیں پڑھائی۔\n(راویٔ حدیث) داود (بن ابو ہند) نے کہا: میں نے (اپنے استاد ولید سے) پوچھا: ’’فلاح‘‘ کیا ہے؟ انھوں نے کہا: سحری ہے۔","f2":"(۱) نبی صلی اللہ علیہ وسلم کا بعد کی راتوں میں تراویح نہ پڑھانا فرضیت کے ڈر سے تھا جیسا کہ آپ نے خود فرمایا ہے۔ آپ کی وفات کے بعد یہ ڈر نہ رہا، لہٰذا حضرت عمر رضی اللہ عنہ نے مستقل جماعت شروع کرا دی جس پر آج تک امت متفق ہے۔ سواب یہی سنت ہے۔ خصوصاً جب کہ قراء اور حفاظ کی کثرت نہیں رہی اور لمبی نماز کا شوق بھی عنقا ہے۔ (۲) عہدِ رسالت اور عہد صحابہ و تابعین میں رات کے قیام، یعنی تہجد کو قیام اللیل یا تہجد کہا جاتا تھا، اس حدیث میں بھی اس کے لیے قیام ہی کا لفظ استعمال ہوا ہے۔ بعد میں رمضان کے قیام کو ’’تراویح‘‘ کہا جانے لگا جو ترویحہ کی جمع ہے، تاہم تہجد، قیام اللیل اور تراویح ایک ہی نماز (تہجد) کا نام ہے، البتہ رمضان کے قیام کےل یے تراوی کا لفظ معروف ہوگیا ہے، علاوہ ازیں عوام کی سہولت کے پیش نظر اسے عشاء کی نماز کے فوراً بعد پڑھ لیا جاتا ہے کیونکہ تہجد کے وقت کا آغاز نماز عشاء کے بعد شروع ہو جاتا اور طلوع فجر تک رہتا ہے۔ گو اس کا عام دنوں میں افضل وقت ثلث لیل کا آخری پہر ہی ہے، تاہم اسے رمضان المبارک کے اول وقت میں باجماعت پڑھنا افضل ہے۔ (۳) اس حدیث مبارکہ سے یہ بھی معلوم ہوا کہ رمضان کے آخری عشرے کی طاق راتوں میں قیام کا خاص اہتمام کرنا چاہیے کیونکہ لیلۃ القدر انھی میں سے ایک رات ہوتی ہے۔"}],[1365,"عقبہ بن حارث رضی اللہ عنہ کہتے ہیں کہ میں نے نبی اکرم صلی اللہ علیہ وسلم کے ساتھ مدینہ میں نماز عصر پڑھی، پھر آپ تیزی سے لوگوں کی گردنیں پھلانگتے ہوئے گئے یہاں تک کہ لوگ آپ کی تیزی سے تعجب میں پڑ گئے، کچھ صحابہ کرام رضی اللہ عنہم آپ کے پیچھے گئے (کہ کیا معاملہ ہے) آپ اپنی ایک بیوی کے حجرہ میں داخل ہوئے، پھر باہر نکلے اور فرمایا: \"میں نماز عصر میں تھا کہ مجھے سونے کا وہ ڈلا یاد آ گیا جو ہمارے پاس تھا، تو مجھے یہ بات اچھی نہیں لگی کہ رات بھر وہ ہمارے پاس پڑا رہے، لہٰذا جا کر میں نے اسے تقسیم کرنے کا حکم دے دیا\"۔","الألباني: صحيح",{"u2":"حضرت عقبہ بن حارث رضی اللہ عنہ بیان کرتے ہیں میں نے ایک دفعہ مدینہ منورہ میں نبی صلی اللہ علیہ وسلم کے ساتھ عصر کی نماز پڑھی۔ نماز سے فارغ ہوت ہی آپ جلدی سے لوگوں کی گردنیں پھلانگتے ہوئے گھر چلے گئے حتی کہ لوگوں نے آپ کی جلدی پر تعجب کیا۔ کچھ صحابہ آپ کے پیچھے گئے۔ آپ اپنی کسی بیوی کے گھر داخل ہوئے، پھر باہر تشریف لائے اور فرمایا: ’’مجھے عصر کی نماز کے دوران میںیاد آیا کہ کچھ سونا ہمارے گھر پڑا ہے۔ میں نے پسند نہ کیا کہ وہ رات کو ہمارے گھر رہے، اس لیے میں نے وہ تقسیم کرنے کا حکم دیا ہے۔‘‘","f2":"(۱) اللہ! اللہ! نبی صلی اللہ علیہ وسلم کی بے نفسی کہ اللہ کے مال کو ایک رات کے لیے بھی اپنے گھر رکھنے کو تیار نہیں۔ صلی اللہ علیہ وسلم۔ فجزاہ اللہ عنا خیر الجزاء۔ (۲) معلوم ہوا کہ نماز کے اندر اتفاقاً کسی خیال کا آ جانا نماز کو ختم نہیں کرتا۔ (۳) اس حدیث مبارکہ سے یہ بھی معلوم ہوا کہ آپ کی عادت مبارکہ نماز کے بعد کچھ دیر بیٹھنے ہی کی تھی ورنہ صحابۂ کرام رضی اللہ عنہم کو تعجب نہ ہوتا، نیز کسی عذر کی بنا پر ایسے کرسکتے ہیں، اسے عادت نہیں بنانا چاہیے۔ (۴) امام جب کوئی خلاف معمول کام کرے تو اسے اپنے ساتھیوں کے سامنے اس کی وضاحت کر دینی چاہیے تاکہ ان کے دلوں میں شکوک و شبہات جنم نہ لیں۔"}],[1366,"جابر بن عبداللہ رضی اللہ عنہم سے روایت ہے کہ عمر بن خطاب رضی اللہ عنہ غزوہ خندق کے دن سورج ڈوب جانے کے بعد کفار قریش کو برا بھلا کہنے لگے، اور انہوں نے عرض کیا: اللہ کے رسول! میں نماز نہیں پڑھ سکا یہاں تک کہ سورج ڈوب گیا، تو رسول اللہ نے فرمایا: \"قسم اللہ کی! میں نے بھی نہیں پڑھی ہے\"، چنانچہ ہم رسول اللہ صلی اللہ علیہ وسلم کے ساتھ وادی بطحان میں اترے، پھر آپ نے نماز کے لیے وضو کیا، اور ہم نے بھی وضو کیا پھر آپ نے سورج ڈوب جانے کے باوجود(پہلے) عصر پڑھی، پھر اس کے بعد مغرب پڑھی۔","الألباني: صحيح",{"u2":"حضرت جابر بن عبداللہ رضی اللہ عنہ سے روایت ہے کہ حضرت عمر بن خطاب رضی اللہ عنہ جنگ خندق کے دن سورج غروب ہونے کے بعد کفار قریش کو برا بھلا کہنے لگے اور کہا: اے اللہ کے رسول! میں تو بڑی مشکل سے عین غروب شمس کے قریب نماز عصر پڑھ سکا۔ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’اللہ کی قسم! میں نے تو ابھی تک نماز نہیں پڑھی۔‘‘ پھر ہم رسول اللہ صلی اللہ علیہ وسلم کےساتھ وادیٔ بطحان میں گئے۔ آپ نے بھی وضو کیا اور ہم نے بھی۔ پھر غروب شمس کے بعد پہلے عصر کی نماز پڑھی، پھر مغرب کی۔","f2":"(۱) باب کا مقصد دراصل کچھ فقہاء کے اس خیال کی تردید ہے کہ اگر نماز نہ پڑھی ہو تو یوں نہ کہے: ’’میں نے نماز نہیں پڑھی۔‘‘ بلکہ یوں کہے: ’’ابھی پڑھنی ہے۔‘‘ کیونکہ پہلے جملے میں کچھ بے نیازی سی جھلکتی ہے، جب کہ دوسرے جملے میں اپنی کوتاہی کا اعتراف اور تلافی کا عزم ہے۔ امام صاحب کا خیال ہے کہ اس طرح بھی کہہ سکتا ہے۔ یہ حدیث دلیل ہے۔ (۲) فوت شدہ نمازوں کی جماعت کرانا مشروع ہے، نیز اگر فوت شدہ نمازیں ایک سے زیادہ وہں تو انھیں ترتیب کے ساتھ پڑھنا چاہیے۔ واللہ أعلم۔"}],[1367,"ابوہریرہ رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"(دنیا میں) ہم پیچھے آنے والے ہیں اور (قیامت میں) آگے ہوں گے، صرف اتنی بات ہے کہ انہیں (یعنی یہود و نصاری کو) کتاب ہم سے پہلے دی گئی ہے، اور ہمیں ان کے بعد دی گئی ہے، یہ (جمعہ کا دن) وہ دن ہے جس دن اللہ نے ان پر عبادت فرض کی تھی مگر انہوں نے اس میں اختلاف کیا ۱؎، تو اللہ تعالی نے اس سے (یعنی جمعہ کے دن سے) ہمیں نواز دیا، تو لوگ اس میں ہمارے تابع ہیں ۲؎، یہود کل کی یعنی ہفتہ(سنیچر) کی تعظیم کرتے ہیں، اور نصاری پرسوں کی (یعنی اتوار کی)\"۔\n§وضاحت\n۱؎: یہود نے اپنے لیے ہفتہ :(سنیچر ) کا دن تجویز کر لیا اور نصای نے اتوار کا۔ ۲؎: کیونکہ جمعہ ہی کے دن اللہ تعالی نے دنیا کو پیدا کیا۔","الألباني: صحيح",{"u2":"حضرت ابوہریرہ رضی اللہ عنہ سے روایت ہے، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’ہم (زمانے کے لحاظ سے) سب سے پیچھے ہیں (مگر مرتبے کے لحاظ سے) سب سے آگے ہیں۔ علاوہ اس بات کے کہ ان (یہود و نصاریٰ) کو ہم سے پہلے کتاب دی گئی اور ہمیں ان کے بعد دی گئی۔ اور یہ (خصوصی عبادت والا) دن ان پر بھی اللہ تعالیٰ نے فرض کیا تھا لیکن انھوں نے اس میں اختلاف کیا (یہود نے ہفتے کا دن تجویز کیا اور نصاریٰ نے اتوار کا۔) چنانچہ اللہ تعالیٰ نے ہمیں اس دن، یعنی جمعے کے دن تک پہنچایا۔ اب وہ لوگ (عبادت والے دن کے لحاظ سے) ہم سے پیچھے ہیں۔ یہودی ہم سے (یعنی جمعے کے دن سے) اگلے دن اور عیسائی اس سے اگلے دن (خصوصی عبادت کرتے ہیں)۔‘‘","f2":"(۱) امت مسلمہ سب سے آخری امت ہے اور اس کے نبی آخری نبی ہیں۔ زمانے کے لحاظ سے تاخیر ان کے مرتبے میں کمی کا سبب نہیں بلکہ آخری ہونے کے لحاظ سے یہ افضل امت ہے اور اس کے نبی صلی اللہ علیہ وسلم، افضل نبی ہیں۔ (۲) ’’سب سے آگے‘‘ مرتبے کے علاوہ افراد کی تعداد، حشر و نشر، حساب و کتاب، الٰہی فیصلے اور دخول جنت میں بھی سب سے آگے ہوگی۔ جنت میں نصف تعداد امت محمدیہ کی ہوگی اور باقی نصف تعداد دیگر تمام امتیوں کی۔ شرفھا اللہ تعالیٰ۔ دیکھیے: (فتح الباري: ۳۸۷/۱۱) (۳) ’’علاوہ اس بات کے‘‘ یہ ایک الگ فضیلت ہے۔ چونکہ ہماری کتاب ان کتابوں کےبعد نازل ہوئی ہے، لہٰذا ہماری کتاب اور شریعت ان کی کتابوں اور شریعتوں کو منسوخ کرنے والی ہے۔ اور ناسخ افضل ہوتا ہے۔ ظاہراً اس جملے کا انداز اہل کتاب کی فضیلت بیان کرنے کا ہے مگر جو کچھ بیان کیا گیا ہے، وہ امت محمدیہ کی فضیلت ہے۔ یہ بھی کسی کی تعریف کرنے کا ایک بلیغ انداز ہے۔ بیدہ کے ایک معنی ’’نیز‘‘ بھی ہیں۔ پھر مطلب بالکل واضح ہے۔ (۳) ظاہراً یہ معلوم ہوتا ہے کہ اللہ تعالیٰ نے ان پر جمعے کا دن خصوصی عبادت کے لیے مقرر کیا تھا مگر انھوں نے اسے قبول نہ کیا، اس سے اختلاف کیا، اور یہود نے اس دن کے بجائے ہفتہ اور عیسائیوں نے اتوار کا دن منتخب کیا جب کہ جمعے کا دن افضل ہے۔ لیکن صحیح بات یہ ہے کہ اللہ تعالیٰ نے ان امتوں کو اتخیار دیا کہ ہفتے کے دنوں میںسے کوئی دن خصوصی عبادت کے لیے مقرر کرلیں۔ یہودیوں نے ہفتہ اختیار کیا کہ اللہ تعالیٰ تخلیق سے جمعے کے دن فارغ ہوا اور ہفتے کو فارغ رہا۔ ہم بھی ہفتے کے دن عبادت کے لیے فارغ رہیں گے۔ عیسائیوں نے اتوار کو اختیار کیا کہ اس دن خلق کی ابتداہوئی تھی۔ بطور تشکر ہم اس دن عبادت کریںگے۔ یہ وجوہات خود ساختہ تھیں۔ عبادات سے ان وجوہ کا تعلق نہ تھا جب کہ جمعہ بذات خود افضل دن ہے جسے نبی صلی اللہ علیہ وسلم نے اختیار فرمایا۔ (۵) ویسے تو دنوں کی ترتیب کسی دن سے بھی شروع کی جاسکتی ہے، مگر عبادت کا مقررہ دن ہونے کے لحاظ سے جمعۃ المبارک ان تینوں میں ترتیب کے لحاظ سےاول ہے۔ ہفتہ دوم اور اتوار سوم۔ اس لحاظ سے بھی امت محمدیہ ان سے مقدم ہے۔ (۶) جمعۃ المبارک کے دن ظہر کی بجائے جمعہ پڑھنا (خطبہ اور نماز) فرض ہے۔ یہ متفق علیہ مسئلہ ہے، البتہ اگر کسی سے رہ جائے یا کوئی شخص معذور ہو (مثلاً مریض، مسافر وغیرہ) تو وہ ظہر پڑھے۔ عورتیں اگر جمعہ پڑھنے مسجد میں جائیں تو وہ مردوں کی طرح ان کے ساتھ جمعہ پڑھیں گی، ورنہ گھروں میں ظہر کی نماز پڑھیں۔"}],[1370,"عبداللہ بن عباس اور ابن عمر رضی اللہ عنہم کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے اپنے منبر کے زینے سے فرمایا: \"لوگ جمعہ چھوڑنے سے باز آ جائیں، ورنہ اللہ تعالی ان کے دلوں پر مہر لگا دے گا ۱؎ اور وہ غافلوں میں سے ہو جائیں گے\" ۲؎۔\n§وضاحت\n۱؎: گویا مسلسل جمعہ کا چھوڑنا ایسا خطرناک فعل ہے جس سے دلوں پر مہر لگ سکتی ہے جس کے بعد انسان کے لیے اخروی فلاح و نجات کی امید ختم ہو جاتی ہے۔ ۲؎: \" غافلوں میں سے ہو جائیں \" کا مطلب ہے کہ اللہ کے ذکر اور اس کے احکام سے بالکل بے پرواہ ہو جائیں گے۔","الألباني: صحيح",{"u2":"حضرت ابن عباس اور حضرت ابن عمر رضی اللہ عنہم سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے منبر کی سیڑھیوں پر کھڑے ہوکر فرمایا: ’’لوگ جمعے چھوڑنے سے باز آ جائیں ورنہ اللہ تعالیٰ ان کے دلوں پر مہر لگا دے گا اور وہ یقینی طور پر غافلین میں سے ہو جائیں گے۔‘‘","f2":"جو شخص جمعے جیسی اہم عبادت کو چھوڑتا ہے اور بار بار چھوڑتا ہے، وہ دوسری عبادات کو بھی اہمیت نہ دے گا اور ایک ایک کرکے دیگر عبادات بھی اس سے چھوٹ جائیں گی۔ اس کا نتیجہ یہ نکلے گا کہ وہ شخص عملاً منافق بن جائے گا اور اس کے دل پر زنگ لگ جائے گا جس سے اللہ تعالیٰ کی محبت اور رسول اللہ صلی اللہ علیہ وسلم کی محبت مغلوب ہو جائے گی۔ مہر لگنے سے مراد بھی یہی کچھ ہے۔ واللہ أعلم۔"}],[1371,"ام المؤمنین حفصہ رضی اللہ عنہا سے روایت ہے کہ نبی اکرم صلی اللہ علیہ وسلم نے فرمایا: \"جمعہ کے لیے (مسجد) جانا ہر بالغ مرد پر فرض ہے\"۔","الألباني: صحيح",{"u2":"نبی صلی اللہ علیہ وسلم کی زوجۂ محترمہ حضرت حفصہ رضی اللہ عنہا سے مروی ہے، نبی صلی اللہ علیہ وسلم نے فرمایا: ’’جمعے کے لیے جانا ہر بالغ مسلمان پر فرض ہے۔‘‘"}],[1373,"ابوہریرہ رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"بہترین دن جس میں سورج نکلا جمعہ کا دن ہے، اسی دن آدم علیہ السلام پیدا کیے گئے، اسی دن انہیں جنت میں داخل کیا گیا، اور اسی دن انہیں جنت سے نکالا گیا\" ۱؎۔\n§وضاحت\n۱؎: اس سے جمعہ کے دن کی فضیلت ظاہر ہوتی ہے کیونکہ اس میں بڑے بڑے امور سر انجام پائے۔","الألباني: صحيح",{"u2":"حضرت ابوہریرہ رضی اللہ عنہ سے روایت ہے، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’بہترین دن جس میں سورج طلوع ہوا ہے، جمعہ کا دن ہے۔ اسی دن حضرت آدم علیہ السلام پیدا ہوئے، اسی دن جنت میں داخل کیے گئے اور اسی دن جنت سے نکالے گئے۔‘‘","f2":"(۱) بعض روایات میں مزید ذکر ہے کہ اسی دن آدم علیہ السلام فوت ہوئے اور اسی دن قیامت قائم ہوگی۔ کیا ان واقعات کا تعلق بھی جمعے کی فضیلت سے ہے یا انھیں ویسے ذکر کر دیا گیا ہے؟ علماء نے دونوں پہلو اختیار کیے ہیں۔ اگر یہ واقعات فضیلت سے متعلق ہیں تو اخراج آدم اس لیے فضیلت کا سبب ہے کہ ان کا اراج انبیاء و رسل علیہم السلام کی بعثت کا سبب بنا اور ان کا وجود انسانی فضیلت کا باعث ہے۔ اسی طرح وفات آدم اور قیامت کا واقع ہونا، اللہ تعالیٰ کی ملاقات، دخول جنت اور حصول کرامت کا سبب ہیں۔ (۲) ’’جمعے کا دن افضل ہے یا عرفے کا دن؟‘‘ علمائے کرام اس کی بابت فرماتے ہیں کہ ہفتے کے دنوں میںسے جمعہ افضل ہے اور سال کے دنوں میںسے عرفے کا دن افضل ہے۔ اس لحاظ سے عرفہ جمعے سے افضل ہے کیونکہ جمعہ بھی تو سال کے دنوں میں شامل ہے، علاوہ ازیں عرفے کا اجتماع جمعے کے اجتماع سے بہت بڑا ہوتا ہے اور مومنین کا اجتماع جتنا بڑا ہو، ثواب اور فضیلت اسی قدر زائد ہوتی ہے، البتہ جمعے کے دن سب اجتماعات جمعہ کو ملایا جائے تو وہ یقیناً عرفے سے بہت بڑھ جاتے ہیں۔ اس دن میں ہونے والے اہم واقعات، مثلاً: خلق آدم وغیرہ مزید فضیلت کا تقاضا کرتے ہیں، لہٰذا قطیعت سے کوئی ایک بات کہنا مشکل ہے۔ واللہ أعلم۔"}],[1374,"اوس بن اوس رضی اللہ عنہ کہتے ہیں کہ نبی اکرم صلی اللہ علیہ وسلم نے فرمایا: \"تمہارے دنوں میں سب سے افضل (بہترین) جمعہ کا دن ہے، اسی دن آدم علیہ السلام پیدا ہوئے، اسی میں ان کی روح قبض کی گئی، اور اسی دن صور پھونکا جائے گا، اور اسی دن بیہوشی طاری ہو گی، لہٰذا تم مجھ پر زیادہ سے زیادہ صلاۃ (درود و رحمت) بھیجو کیونکہ تمہاری صلاۃ (درود و رحمت) مجھ پر پیش کیے جائیں گے\" ۱؎ لوگوں نے عرض کیا: اللہ کے رسول! ہماری صلاۃ (درود و رحمت) آپ پر کس طرح پیش کی جائیں گی حالانکہ آپ ریزہ ریزہ ہو چکے ہوں گے یعنی وہ کہنا چاہ رہے تھے، کہ آپ بوسیدہ ہو چکے ہوں گے، آپ نے فرمایا: \"اللہ تعالی نے زمین پر حرام کر دیا ہے کہ وہ انبیاء علیہم السلام کے جسم کو کھائے\"۔\n§وضاحت\n۱؎: تمہارے درود مجھ پر پیش کیے جائیں گے، سے معلوم ہوتا ہے کہ آپ براہ راست کسی کا درود نہیں سنتے نہ قریب سے نہ بعید سے، قریب سے سننے کی ایک روایت مشہور ہے لیکن وہ صحیح نہیں، صحیح یہی ہے کہ آپ خود کسی کا درود نہیں سنتے فرشتے ہی آپ کا درود پہنچاتے ہیں۔","الألباني: صحيح",{"u2":"حضرت اوس بن اوس رضی اللہ عنہ سے مروی ہے، نبی صلی اللہ علیہ وسلم نے فرمایا: ’’تحققتمھارے دنوں میںسےافضل دن جمعہ ہے۔ اس میں آدم علیہ السلام پیدا ہوئے۔ اسی دن فوت ہوئے اور اسی دن صور پھونکا جائے گا۔ اسی دن بے ہوشی ہوگی۔ پس اس دن مجھ پر کثرت سے درود پڑھا کرو۔ یقیناً تمھارا درود مجھ پر پیش کیا جاتا ہے۔‘‘ لوگوںنے کہا: اے اللہ کے رسول! (وفات کے بعد) آپ پر درود کیسے پیش کیا جائے گا جب کہ آپ بوسیدہ ہوچکے ہوں گے؟ آپ نے فرمایا: ’’اللہ تعالیٰ نے زمین پر حرام کر دیا ہے کہ وہ انبیاء علیہم السلام کے جسموں کو کھائے۔‘‘","f2":"(۱) مذکورہ روایت کو ہمارے فاضل محقق نے سنداً ضعیف قرار دیا ہے جبکہ دیگر محقین نے اسے سنداً صحیح قرار دیا ہے۔ اور دلائل کی رو سے انھیں کی رائے اقرب الی الصواب معلوم ہوتی ہے۔ تفصیل کے لیے دیکھیے: (الموسوعۃ الحدیثیۃ مسند الإمام أحمد: ۸۶-۸۴/۶۲، و إرواہ الغلیل: ۳۵،۳۴/۱، رقم الحدیث: ۴) (۲) چونکہ جمعہ افضل دن ہے، لہٰذا اس دن کی نیکی بھی افضل ہے اور درود جو کہ قربت الٰہی کا عظیم ذریعہ ہے، اس دن مزید افضلہو جائے گا، نیز درود رسول اللہ صلی اللہ علیہ وسلم کے لیے تحفے کی طرح ہے جو آپ کو پیش کیا جاتا ہے۔ تو اس کی فضیلت کے کیا کہنے! (۳) ’زمین پر حرام کر دیا ہے‘‘ سائلین کا مطلب یہ ہے کہ وفات کے بعد تو جسم باقی نہیں رہتا، لہٰذا سلام کس پر پیش کیا جائے گا؟ آپ کے فرمان کا مطلب یہ ہے کہ میرے جسم پر پیش کیا جائے گا کیونکہ انبیاء کے جسم مٹی نہیں بنتے۔ علیہم السلام۔ (۴) صلاۃ و سلام کا آپ پر پیش کیا جانا برزخی معاملہ ہے، نہ کہ آپ براہ راست سنتے یا محسوس فرماتے ہیں بلکہ فرشتے آپ تک پہنچاتے ہیں۔ قریب سے سننے کی روایت سنداً صحیح نہیں۔ انبیاء و شہداء کی مابعد الموت زندگی بھی برزخی زندگی ہے۔ اور ان کی برزخی زندگی سب سے اعلی اور بہتر ہے۔ ویسے تو برزخی زندگی ہر میت کو حاصل ہوتی ہے مگر ’’چہ نسبت خاک رابا عالم پاک‘‘۔ انبیاء علیہم السلام کے جسم بھی سلامت رہتے ہیں اور شہداء کو جنتی جسم مل جاتے ہیں لیکن وہ زندگی بہرصورت برزخی ہوتی ہے، نہ کہ دنیوی کیونکہ وہ دنیا میں نہیں رہے۔"}],[1375,"ابو سعید خدری رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"جمعہ کے دن ہر بالغ شخص پر غسل کرنا واجب ہے، مسواک کرنا بھی، اور خوشبو جس پروہ قادر ہو لگانا بھی ۱؎\"۔","الألباني: صحيح",{"u2":"حضرت ابوسعید رضی اللہ عنہ سے روایت ہے، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’جمعے کے دن غسل کرنا ہر بالغ پر ضروری ہے۔ اسی طرح مسواک کرنا بھی۔ اور جو خوشبو اسے مل سکے، لگائے، خواہ وہ خوشبو عورت (اس کی بیوی) کی ہو۔‘‘","f2":"(۱) ’’واجب ہے‘‘ اس روایت اور حدیث نمبر ۱۳۷۷، ۱۳۷۸ اور ۱۳۷۹ کے بموجب اہل علم کا ایک طبقہ جمعے کے دن غسل کے واجب ہونے کا قائل ہے جب کہ ایک بڑا طبقہ اس کے وجوب کا قائل نہیں لیکن پہلے طبقے کے اہل علم کی رائے نصوص صریحہ کے قریب تر ہے۔ واللہ أعلم۔ جیسا کہ تفصیل ابتدائیے میں گزر چکی ہے۔ (۲) مسواک عام حالت میں بھی مؤکد چیز ہے،جمعۃ المبارک کے لیے تو خصوصاً، خوشبو لگانا تو مؤکد بھی نہیں صرف مستحب ہے۔ (۳) عورتوں کی خوشبو (جس میں رنگ ہو) مردوں کے لیے جائز نہیں مگر مجبوری کی حالت میں گنجائش ہے، مثلاً: شادی کے موقع پر یا جمعۃ المبارک کے لیے۔ (۴) صفائی ایمان کا حصہ ہے۔ اسلام نے نظافت پر بہت زور دیا ہے۔ ایک مسلمان کے لیے ضروری ہے کہ وہ اپنا جسم، لباس اور مکان وغیرہ صاف ستھرا رکھے اور اگر کسیایسی جگہ جائے جہاں لوگ اکٹھے ہوں تو بالخصوص صفائی کا اہتمام کرے اور حسب استطاعت خوشبو وغیرہ کا استعمال کرے تاکہ لوگ اذیت محسوس نہ کریں۔"}],[1376,"ابوہریرہ اور حذیفہ رضی اللہ عنہم کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"اللہ تعالی نے ہم سے پہلے والوں کو جمعہ سے بھٹکا دیا، یہود کے لیے ہفتہ (سنیچر)کا دن مقرر ہوا، اور نصرانیوں کے لیے اتوار کا، پھر اللہ تعالی ہمیں لایا تو اس نے ہمیں جمعہ کے دن سے نوازا، تو اب (پہلے) جمعہ ہے، پھر ہفتہ (سنیچر) پھر اتوار، اس طرح یہ لوگ قیامت تک ہمارے تابع ہوں گے، ہم دنیا میں بعد میں آئے ہیں مگر قیامت کے دن پہلے ہوں گے\" ۱؎۔\n§وضاحت\n۱؎: یعنی تمام مخلوقات سے پہلے ہمارا فیصلہ ہو گا۔\nعبداللہ بن عمر رضی اللہ عنہم سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"جب تم میں سے کوئی جمعہ (کی نماز) کے لیے آئے تو اسے چاہیئے کہ غسل کر لے\"۔","الألباني: صحيح",{"u2":"حضرت ابن عمر رضی اللہ عنہا سے روایت ہے، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’جب تم میں سے کوئی آدمی جمعے کے دن (جمعہ پڑھنے کے لیے) آئے تو وہ غسل کرے۔‘‘","f2":"(۱)غسل کے وجوب کی بحث سابقہ حدیث کے تحت گزر چکی ہے۔ (۲) اس حدیث سے معلوم ہوتا ہے کہ جمعے کا غسل جمعۃ المبارک کو آتے وقت کرنا چاہیے، نہ کہ بہت پہلے کیونکہ غسل کا مقصد میل کچیل اور پسینے کی صفائی ہے، اگر بہت پہلے غسل کر لیا جائے تو میل کچیل پھر جمع ہوسکتا ہے اور پسینہ بھی آسکتا ہے۔ اجتماع میں بدبو پھیلنے کا امکان ہے، لہٰذا غسل جمعۃ المبارک کے لیے آتے وقت کرنا چاہیے، یعنی اس غسل کے ساتھ جمعہ پڑھنا چاہیے۔ بعض حضرات کا خیال ہے کہ یہ جمعے کے دن کا غسل ہے، اس لیے کسی وقت بھی کیا جا سکتا ہے مگر جمعے سے پہلے پہلے۔اہل ظاہر تو جمعے کے بعد بھی غسل کو کافی سمجھتے ہیں۔ مگر علت و سبب یا دیگر احادیث پر غور کیا جائے تو یہ موقف محل نظر لگتا ہے۔ واللہ أعلم۔ (۳) غسل جمعہ، غسل جنابت کی طرح ہونا چاہیے۔ غسل جنابت کی تفصیل پیچھے متعلقہ باب میں گزر چکی ہے۔"}],[1377,"ابو سعید خدری رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"جمعہ کے دن کا غسل ہر بالغ شخص پر واجب ہے\" ۱؎۔\n§وضاحت\n۱؎: جمعہ کی نماز کے لیے غسل شروع میں واجب تھا، جو بعد میں منسوخ ہو گیا، دیکھئیے حدیث رقم: ۱۳۸۰، ۱۳۸۱۔","الألباني: صحيح",{"u2":"حضرت ابوسعید خدری رضی اللہ عنہ سے روایت ہے، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’جمعے کے دن کا غسل ہر بالغ پر ضروری ہے۔‘‘"}],[1378,"جابر رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"ہر مسلمان شخص پر ہر سات دن میں ایک دن کا غسل ہے، اور وہ جمعہ کا دن ہے\"۔","الألباني: صحيح لغيره",{"u2":"حضرت جابر رضی اللہ عنہ سے منقولہے، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’ہر مسلمان آدمی کے لیے ہر سات دنوں میںایک دن غسل کرنا ضروری ہے اور وہ دن جمعۃ المبارک ہے۔‘‘","f2":"غسل جمعہ کی بحث کے لیے دیکھیے حدیث نمبر: ۱۳۷۶ اور ۱۳۷۷۔"}],[1379,"قاسم بن محمد ابن ابی بکر کہتے ہیں کہ لوگوں نے ام المؤمنین عائشہ رضی اللہ عنہا کے پاس جمعہ کے دن کے غسل کا ذکر کیا، تو انہوں نے کہا: لوگ «عالیہ» میں رہتے تھے، تو وہ وہاں سے جمعہ میں آتے تھے، اور ان کا حال یہ ہوتا کہ وہ میلے کچیلے ہوتے، جب ہوا ان پر سے ہوتے ہوئے گزرتی تو ان کی بو پھیلتی، تو لوگوں کو تکلیف ہوتی، رسول اللہ صلی اللہ علیہ وسلم سے اس کا ذکر کیا گیا تو آپ صلی اللہ علیہ وسلم نے فرمایا: \"کیا یہ لوگ غسل کر کے نہیں آ سکتے\"۔\n§وضاحت\n۱؎: «عالیہ» شہر مدینہ سے جنوب مشرق میں جو آباد یاں تھیں انہیں «عالیہ» :(یا عوالی ) کہا جاتا تھا، آج بھی انہیں \"عوالی\" کہا جاتا ہے۔","الألباني: صحيح",{"u2":"حضرت قاسم بن محمد بن ابی بکر رمہ اللہ سے مروی ہے کہ لوگوں نے حضرت عائشہ رضی اللہ عنہا کے پاس غسل جمعہ کا ذکر کیا تو انھوں نے فرمایا: دراصل کچھ لوگ مدینہ منورہ کی بالائی بستیوں میں رہتے تھے (جو کئی میل دور تھیں۔) وہ جمعے کے لیے (مسجد نبوی میں) آتے تھے۔ انھیں میل کچیل لگا ہوتا۔ جب ہوا چلتی تو ان سے بدبو پھیلتی۔ دوسرے لوگ اس سے تکلیف محسوس کرتے۔ اس بات کا ذکر اللہ کے رسول صلی اللہ علیہ وسلم سے کیا گیا تو آپ نے فرمایا: ’’تم غسل کرکے نہیں آتے؟‘‘","f2":"باب کا مقصد واضح ہے کہ غسل جمعہ مندرجہ بالا مجبوری کی بنا پر تھا۔ جمہرو کی یہ دوسری دلیل ہے کہ اگر ایسی صورت حال نہ ہو تو غسل ضروری نہیں کیونکہ وہ لوگ کئی کئی میل سے آتے تھے۔ کام کاج کرنے کیوجہ سے جسم پر میل کچیل ہتا تھا، آتے ہوئے پسینہ آ جاتا تھا، کپڑے بھی اون وغیرہ کے ہوتے تھے، رش ہو جاتا تو اس سے ناگوار بو پھیل جاتی، اس لیے غسل کا حکم دیا گیا، لیکن دلائل کی رو سے یہ دلیل بھی زیر بحث مسئلے میں فیصلہ کن نہیں، علت اور سبب کے زائل ہونے سے اصل حکم کا زائل ہونا ضروری نہیں اور نہ ہی کوئی عام قاعدہ کلیہ ہے، اگرچہ آغاز میں یہی وجہ تھی لیکن بعد ازاں رسول اللہ صلی اللہ علیہ وسلم نے انھیں اس پر برقرار رکھا اور اس کے متعلق مزید احکام صادر فرما کر اسے لازمی قرار دے دیا۔ طواف قدوم کے ابتدائی تین چکروں میں رمل کا بھی تو آغاز میں ایک سبب اور وجہ تھی لیکن زوال علت کے باوجود یہ عمل تاحال مشروع مطلوب ہے۔ واللہ أعلم۔ مزید تفصیل کے لیے کتاب الغسل کا ابتدائیہ دیکھیے۔"}],[1380,"سمرہ بن جندب رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"جو شخص بنا کسی عذر کے جمعہ چھوڑ دے تو وہ ایک دینار صدقہ کرے، اور اگر ایک دینار نہ ہو تو آدھا دینار ہی کرے\"۔\nسمرہ رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"جس نے جمعہ کے دن وضو کیا، تو اس نے رخصت کو اختیار کیا، اور یہ خوب ہے ۱؎ اور جس نے غسل کیا تو غسل افضل ہے\"۔ ابوعبدالرحمٰن (نسائی) کہتے ہیں: \"حسن بصری\" نے سمرہ رضی اللہ عنہ سے اس حدیث کو ان کی کتاب سے روایت کیا ہے، کیونکہ حسن نے سمرہ سے سوائے عقیقہ والی حدیث کے کوئی اور حدیث نہیں سنی ہے ۲؎ واللہ اعلم۔\n§وضاحت\n۱؎: «فبہا» کا مطلب ہے «فبالرخصۃ أخذ» یعنی اس نے رخصت کو اختیار کیا، اور «نِعْمَتْ» کا مطلب «نعمت ہی الرخصۃ» ہے یہ رخصت خوب ہے، اس حدیث سے جمعہ کے غسل کے عدم وجوب پر استدلال کیا گیا ہے کیونکہ ایک تو اس میں وضو کی رخصت دی گئی ہے، اور دوسرے غسل کو افضل بتایا گیا ہے جس سے ترک غسل کی اجازت نکلتی ہے۔ ۲؎: صحیح بخاری میں حدیث عقیقہ کے علاوہ بھی حسن بصری کی سمرہ رضی اللہ عنہ سے روایات موجود ہیں، اس بابت اختلاف ہے، مگر علی بن المدینی اور امام بخاری کی ترجیح یہی ہے کہ حسن بصری نے حدیث عقیقہ کے علاوہ بھی سمرہ رضی اللہ عنہ سے سنا ہے۔","الألباني: ضعيف",{"u2":"حضرت سمرہ بن جندب رضی اللہ عنہ سے روایت ہے، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’جس شخص نے جمعے کے دن وضو کیا تو یہ کافی ہے اور اچھی بات ہے اور جو شخص غسل کرے تو غسل افضل ہے۔‘‘\nابو عبدالرحمٰن (امام نسائی) بیان کرتے ہیں کہ حسن بصری، سمرہ بن جندب کی کتاب سے بیان کرتے ہیں اور انھوں نے سمرہ رضی اللہ عنہ سے عقیقے والی حدیث کے علاوہ کوئی روایت نہیں سنی۔ واللہ تعالیٰ أعلم۔","f2":"(۱)امام نسائی رحمہ اللہ کا مقصود یہ ہے کہ یہ روایت حسن بصری نے حضرت سمرہ بن جندب رضی اللہ عنہ سے براہِ راست نہیں سنی بلکہ ان کی کتاب سے بیان کی ہے، اس میں وہ سماع کی تصریح نہیں کرتے۔ حسن کی حضرت سمرہ سے روایت کے بارے میں محدثین کی تین آرائ ہیں، حسن کا سمرہ سے علی الاطلاق سماع ثابت ہے۔ گویا اس طرح ان کی تمام مرویات سماع پر محمول ہوں گی۔ یہ موقف امام بخاری رحمہ اللہ کے استاد علی بن مدینی رحمہ اللہ کا ہے۔ امام بخاری رحمہ اللہ نے تاریخ اوسط میں ذکر کیا ہے، نیز امام ترمذی اور امام حاکم رحما اللہ کا بھی یہی موقف ہے۔ حسن نے سمرہ رضی اللہ عنہ سے کچھ بھی نہیں سنا، یعنی سرے سے ان کا حضرت سمرہ سے سماع ہی ثابت نہیں۔ یہ رائے امام ابن حبان رحمہ اللہ کی ہے۔ امام یحییٰ بن معین اور امام شعبہ بھی اسی کے قائل ہیں، لیکن اس دعوے کی کوئی دلیل نہیں۔ امام حسن کا حضرت سمرہ سے صرف حدیث عقیقہ میں سماع ثابت ہے اور بس۔ یہ موقف امام نسائی رحمہ اللہ کا ہے۔ امام دارقطنی رحمہ اللہ کا بھی اپنی سنن میں اسی طرف رجحان ہہے۔ امام عبدالحق اور امام بزار وغیرہ بھی اس کے قائل ہیں۔ تاہم دلائل کی رو سے راجح موقف امام نائی وغیرہ ہی کا ہے، یا جس روایت میں وہ خود حضرت سمرہ سے سماع کی تصریح فرما یں، یا شواہد کی روشنی میں اسے تقویت ملتی ہو تو وہی روایت قابل حجت ہوگی وگرنہ نہیں۔ حدیث عقیقہ میں امام حسن نے حضرت سمرہ رضی اللہ عنہ سے خود سماع کی تصریح فرمائی ہے۔ واللہ أعلم۔ مزید تفصیل ملاحظہ فرمائیے: (ذخیرۃ العقبی شرح سنن السنائي: ۱۳۱/۱۶، ۱۳۲) (۲) جمہور علماء اس حدیث کے پیش نظر غسل جمعہ کو مستحب قرار دیتے ہیں لیکن ان کی رائے محل نظر ہے کیونکہ حدیث کے الفاظ: ’’جس نے غسل کیا تو یہ افضل ہے۔‘‘ وجوب کے منافی نہیں، کسی چیز کی افضیلت سے اس کے وجوب کی نفی نہیں ہوتی۔ واللہ أعلم۔ اس حدیث کے مفہوم کو مزید سمجھنے کے لیے اسی کتاب کا ابتدائیہ دیکھیے۔"}],[1381,"اوس بن اوس رضی اللہ عنہ سے روایت ہے کہ نبی اکرم صلی اللہ علیہ وسلم نے فرمایا: \"جو غسل کرائے ۱؎ غسل کرے، سویرے سویرے (مسجد) جائے، شروع خطبہ سے موجود رہے، اور امام سے قریب بیٹھے، اور کوئی لغو کام نہ کرے، تو اس کو اس کے ہر قدم کے بدلے ایک سال کے روزے اور قیام کا ثواب ملے گا\"۔\n§وضاحت\n۱؎: یعنی جمعہ کے لیے اپنے غسل سے پہلے بیوی سے صحبت کرے کہ اسے بھی غسل کی ضرورت ہو جائے۔","الألباني: صحيح",{"u2":"حضرت اوس بن اوس رضی اللہ عنہ سے روایت ہے، نبی صلی اللہ علیہ وسلم نے فرمایا: ’’جس نے (اپنے سر یا کپڑوں کو) اچھی طرح دھویا اور غسل کیا اور اول وقت مسجد میں گیا۔ اور خطبے کو شروع سے سنا اور امام کے قریب بیٹھا اور کئوی فضول کام نہ کیا، تو اسے ہر قدم کے عوض ایک سال کے صیام و قیام کا ثواب ملے گا۔‘‘","f2":"(۱)حدیث میں بیان شدہ ثواب صرف غسل کی بنا پر نہیں بلکہ بہت سے کاموں پر ہے۔ مگر ان کاموں میں چونکہ غسل بھی شامل ہے، لہٰذا اس فضیلت میں غسل کا بھی دخل ہے۔ (۲) ’’سر یا کپڑوں کو دھویا‘‘ یہ عربی لفظ [غسل] کا ترجمہ ہے۔ بعض لوگوں نے اس کے معنی یہ کیے ہیں کہ اپنی بیوی کو بھی غسل کرائے، یعنی اس سے جماع کرے تاکہ وہ بھی غسل کرلے، تاہم ہمارے نزدیک پہلا معنی راجح ہے۔ واللہ أعلم۔ (۳) ’’فضول کام‘‘ مثلاً: باتیں کرنا، کپڑوں، صفوں کے تنکوں یا دریوں وغیرہ کے دھاگوں سے کھیلنا۔ (۴) ’’ایک سال کے صیام و قیام‘‘ یعنی دن کو روزہ اور رات کو مسلسل قیام کرنا۔ ان میں کبھی ناغہ ہو، نہ سستی۔ یہ اس قدر مشکل کام ہے کہ کوئی انسان اسے نہیں کرسکتا۔ لیکن مذکورہ اعمال کرنے والا اس عظیم اجر کا مستحق قرار پائے گا۔"}],[1382,"عبداللہ بن عمر رضی اللہ عنہم سے روایت ہے کہ عمر بن خطاب رضی اللہ عنہ نے (ریشم کا) ایک جوڑا (بکتے) دیکھا، تو عرض کیا: اللہ کے رسول! کاش آپ اسے خرید لیتے، اور جمعہ کے دن، اور باہر کے وفود کے لیے جب وہ آپ سے ملنے آئیں پہنتے، تو رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"اسے تو وہی پہنے گا جس کا آخرت میں کوئی حصہ نہ ہو\"، پھر رسول اللہ صلی اللہ علیہ وسلم کے پاس اس طرح کے کچھ جوڑے آئے، آپ نے ان میں سے ایک جوڑا عمر رضی اللہ عنہ کو دیا، تو انہوں نے عرض کیا: اللہ کے رسول! آپ نے مجھے اسے پہننے کے لیے دیا ہے حالانکہ عطارد کے جوڑے کے بارے میں آپ نے ایسا ایسا کہا تھا؟ تو آپ صلی اللہ علیہ وسلم نے فرمایا:\"میں نے یہ جوڑا تمہیں اس لیے نہیں دیا ہے کہ اسے تم خود پہنو\"، تو عمر رضی اللہ عنہ نے اسے اپنے مشرک بھائی کو دے دیا جو مکہ میں تھا۔","الألباني: صحيح",{"u2":"حضرت عبداللہ بن عمر رضی اللہ عنہما سے روایت ہے کہ حضرت عمر بن خطاب رضی اللہ عنہ نے ایک (ریشمی) جوڑا (فروخت ہوتے) دیکھا تو کہنے لگے: اے اللہ کے رسول! اگر آپ یہ جوڑا خرید لیں اور جمعے کے دن پہنا کریں اور جب وفد آئیں، تب بھی پہنیں (تو کیا ہی خوب ہو۔) رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’اسے (یعنی رشیمی کپڑے کو) تو وہ لوگ پہنتے ہیں جن کا آخرت میں کوئی حصہ نہیں۔‘‘ پھر (اس کے بعد) رسول اللہ صلی اللہ علیہ وسلم کے اس اسی قسم کے جوڑے آئے تو آپ نے ان میں سے ایک جوڑا حضرت عمر رضی اللہ عنہ کو دیا۔ حضرت عمر رضی اللہ کہنہ کہنے لگے: اے اللہ کے رسول! آپ یہ جوڑا مجھے پہناتے ہیں جب کہ پ نے عطارد کے لائے ہوئے جوڑے کے بارے میں جو الفاظ ارشاد فرمائے تھے (وہ تو اس کےبرعکس حرمت پر دلالت کرنے والے تھے؟) آپ نے فرمایا: ’’میں نے تجھے پہننے کے لیے نہیں دیا۔‘‘ تو حضرت عمر ری اللہ عنہ نے وہ جوڑا مکہ مکرمہ میں رہنے والے اپنے ایک مشرک بھائی کو دے دیا۔","f2":"(۱)اس حدیث سے بالواسطہ یہ پہلو نکلتا ہے کہ جمعے کے دن اچھا لباس (طاقت کے مطابق) پہننا چاہیے، اسی لیے حضرت عمر رضی اللہ عنہ نے نبی صلی اللہ علیہ وسلم کو مذکورہ مشورہ دیا تھا، آپ نے اس کی نفی نہیں فرمائی بلکہ اس لباس کو نہ خریدنے کی وجہ یہ بتلائی کہ وہ رشیمی ہے اور ریشمی لباس مردوں کے لیے حرام ہے۔ (۲) ’’جن کا آخرت میں کویئ حصہ نہیں۔‘‘ اس کا مطلب یہ ہے کہ اس قسم کا لباس کافر لوگ پہنتے ہیں، مسلمان نہیں پہنتے، یعنی مسلمانوں کو ایسا لباس نہیں پہننا چاہیے کیونکہ انھیں رشیمی لباس آخرت میں ملے گا۔ (۳) ’’مشرک بھائی‘‘ یہ حضرت عمر رضی اللہ عنہ کا ماں کی طرف سے یا رضاعی بھائی تھا۔ واللہ أعلم۔"}],[1383,"ابو سعید خدری رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"جمعہ کے دن غسل کرنا، مسواک کرنا، اور خوشبو لگانا جس پر وہ قادر ہو، ہر بالغ شخص پر واجب ہے\" ۱؎۔\n§وضاحت\n۱؎: بعد میں یہ حکم منسوخ ہو گیا۔","الألباني: صحيح",{"u2":"حضرت ابوسعید خدری رضی اللہ عنہ سے روایت ہے، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’جمعے کے دن غسل کرنا ہر بالغ مرد پر ضروری ہے، نیز وہ مسواک کرے اور جو خوشبو حاصل کرسکے، لگائے۔‘‘"}],[1384,"اوس بن اوس رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"جو شخص جمعہ کے دن غسل کرے، اپنی بیوی کو غسل کرائے، صبح سویرے ہی جمعہ کے لیے نکلے، شروع خطبہ ہی سے موجود رہے، پیدل چل کر مسجد جائے، سواری نہ کرے، امام سے قریب بیٹھے، اور خاموش رہے کوئی لغو کام نہ کرے، تو اس کے ہر قدم پر ایک سال کے عمل کا ثواب ملے گا\"۔","الألباني: صحيح",{"u2":"رسول اللہ صلی اللہ علیہ وسلم کے ایک صحابی حضرت اوس بن اوس رضی اللہ عنہ سے مروی ہے، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’جو آدمی جمعے کے دن غسل کرے اور اپنے جسم وغیرہ کو اچھی طرح دھوئے اور اول وقت جائے، خطبہ شروع سے سنے، پیدل جائے، سوار نہ ہو، امام کے قریب بیٹھے، خاموش رہے اور فضول بات نہ کرے، تو اسے ہر قدم کے عوض ایک سال کے عمل (یام و قیام) کا ثواب ملے گا۔‘‘"}],[1385,"ابوہریرہ رضی اللہ عنہ سے روایت ہے کہ نبی اکرم صلی اللہ علیہ وسلم نے فرمایا: \"جب جمعہ کا دن آتا ہے تو فرشتے (اس دن) مسجد کے دروازوں پر بیٹھ جاتے ہیں، اور جو جمعہ کے لیے آتا ہے اسے لکھتے ہیں، اور جب امام (خطبہ دینے کے لیے) نکلتا ہے تو فرشتے رجسٹر لپیٹ دیتے ہیں\"، پھر رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"جمعہ کے لیے سب سے پہلے آنے والا ایک اونٹ کی قربانی کرنے والے کی طرح ہے، پھر اس کے بعد والا ایک گائے کی قربانی کرنے والے کی طرح ہے، پھر اس کے بعد والا ایک بکری کی قربانی کرنے والے کی طرح ہے، پھر اس کے بعد والا ایک بطخ کی قربانی کرنے والے کی طرح ہے، پھر اس کے بعد والا ایک مرغی کی قربانی کرنے والے کی طرح ہے، پھر اس کے بعد والا ایک انڈے کی قربانی کرنے والے کی طرح ہے\" ۱؎۔\n§وضاحت\n۱؎: اس سے معلوم ہوا کہ نماز جمعہ کے لیے جو جتنی جلدی پہنچے گا اتنا ہی زیادہ اجر و ثواب کا مستحق ہو گا، اور جتنی تاخیر کرے گا اتنا ہی ثواب میں کمی آتی جائے گی۔","الألباني: صحيح",{"u2":"حضرت ابوہریرہ رضی اللہ عنہ سے روایت ہے، نبی صلی اللہ علیہ وسلم نے فرمایا: ’’جب جمعے کا دن ہوتا ہے تو فرشتے مسجد کے دروازو پر بیٹھ جاتے ہیں اور جمعۃ المبارک کے لیے آنے والوں کے نام لکھتے ہیں۔ جب امام خطبے کے لیے نکلتا ہے تو فرشتے اپنے رجسٹر بند کر لیتے ہیں۔‘‘ (راویٔ حدیث) حضرت ابوہریرہ رضی اللہ عنہ بیان کرتے ہیں کہ پھر رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’جمعے کے لیے سب سے پہلے آنے والا (عبے کی طرف) قربانی کے لیے اونٹ بھیجنے والے کی طرح ہے۔ پھر اس کے بعد آنے والا (کعبے کی طرف) قربانی کے لیے گائے بھیجنے والے کی طرح ہے۔ پھر اس کے بعد آنے والا (کعبے کی طرف) قربانی کے لیے بکری بھیجنے والے کی طرح ہے۔ پھر اس کے بعد آنے والا (کعبے کی طرف) قربانی کے لیے بطخ بھیجنے والے کی طرح ہے۔ پھر اس کے بعد آنے والا (کعبے کی طرف) قربانی کے لیے مرغی بھیجنے والے کی طرح ہے۔ پھر اس کے بعد آنے والا (کعبے کی طرف) قربانی کے لیے انڈا بھیجنے والے کی طرح ہے۔‘‘","f2":"(۱)’’فرشتے‘‘ یہ مخصوص فرشتے ہیں جو صرف جمعے سے قبل آنے والوں کے نام اور ثواب لکھنے کے لیے مقرر ہیں۔ (عموماً اعمال لکھنے والے فرشتے تو ہر وقت لکھتے رہتے ہیں۔) پھر یہ خطبہ بھی سنتے ہیں۔ اس سے جمعۃ المبارک کی عظمت ظاہر ہوتی ہے، اسی لیے اس دن کو قرآن مجید میں ’’شاہد‘‘ کہا گیا ہے اور اگر اس سے عام ’’کراما کاتبین‘‘ مراد ہوں تو پھر جمعۃ المبارک کے لیے خطبے سے پہلے آنے والوں کے لیے مخصوص رجسٹر ہوں گے جنھیں خطبہ شروع ہونے سے قبل بند کر دیا جاتا ہے۔ اس میں پہلے آنے والوں کی عظیم فضیلت ہے کہ ان کی حاضری کے لیے فرشتے دروازوں پر آکر بیٹھتے ہیں۔ ذلک فضل اللہ یوتیہ من یشآء۔ (۲) ’’سب سے پہلے آنے والا‘‘ بعض علماء کا خیال ہے کہ فرشتوں نے خطبے سے پہلے کچھ اوقات مقرر کر رکھے ہوں گے۔ ان اوقات کے لحاظ سے لوگوں کے درجات بنتے ہوں گے ورنہ ظاہراً تو یہ معلوم ہوتا ہے کہ سب سے پہلے آنے والے صرف چھ سات افراد کے نام لکھے جاتے ہیں مگر یہ درست نہیں کیونکہ ممکن ہے بیک وقت کئی افراد داخل ہوں، لہٰذا اوقات کا تقرر ہوگا مگر ان اوقات کی تفصیل کسی حدیث میں نہیں آئی۔ یہی وجہ ہے کہ علماء کے مابین اس بارے میں اختلاف ہے۔ جمعے کے لیے جلدی نکلنا بالاتفاق مستحب ہے لیکن اختلاف صرف اس بات میں ہے کہ حدیث میں وارد پانچ گھڑیوں سے مراد کیا ہے؟ کیا پانچ یا چھ گھڑیوں سے مقصود صرف وقت کے چحند اجزاء ہیں یا وہ معروف گھڑیاں ہیں جن میں دن رات ۲۴ گھنٹوں میں تقسیم ہوتے ہیں؟ جمہور علماء و فقہاء اس سے مراد معروف زمانی ساعات (گھنٹے) لیتے ہیں۔ امام شافعی، امام احمد، سفیان ثوری اور امام ابوحنیفہ رحمہم اللہ وغیرہ کی یہی رائے ہے۔ ایک دن میں بارہ گھڑیاں ہوتی ہیں جیسا کہ اس کی تائید حضرت جابر رضی اللہ عنہ کی حدیث سے ہوتی ہے کہ جمعے کے دن کی بارہ گھڑیاں ہتوی ہیں۔ اس کی سند صحیح ہے۔ (سنن أبي داود، لاصلاۃ، حدیث: ۱۰۴۸، و صحیح سنن أبي داود (مفصل) للألباني، حدیث: ۹۶۳) اس لحاظ سے ان کے ہاں سورج کے بلند ہونے سے پہلی گھڑی کا آغاز ہو جاتا ہے۔ اس طرح زوال شمس تک، وقت کے اس دورانیے کو پانچ گھڑیوں میں تقسیم کر لیا جائے، خواہ پہلی گھڑی گھنٹے پر مشتمل ہو یا سوایا ڈیڑھ گھنٹے پر کیونکہ گرمی سردی کے اعتبار سے وقت کے لحاظ سے گھڑیوں میں کمی بیشی ہوتی رہتی ہے لیکن دن کبھی بارہ گھڑیوں سے کم نہیں ہوتا۔ اس طرح پہلی گھڑی میں آنے والے افراد، خواہ تعداد میں زیادہ ہی ہوں، وہ اونٹ کی قربانی کا ثواب پائیں گے۔ اسی طرح ترتیب وار دیگر گھڑیوں میں آنے والے حضرات بھی اسی حساب سے ثواب میں شریک ہوں گے۔ ’’الساعۃ‘‘ کے عرف میں بھی یہی معنی متبادر ہیں۔ دوسرا موقف امام مالک رحمہ اللہ اور بعض شوافع کا ہے۔ ان کے نزدیک احادیث میں وارد ساعات سے مراد معروف گھڑیاں نہیں بلکہ زوال کے بعد چند لحظات یا لمحات ہیں، یعنی زوال کے بعد چھٹی گھڑیکے یہ چند اجزاء یا لمحات ہوتے ہیں جن میں فرشتے آنے والوں کے ترتیب وار نام لکھتے ہیں۔ اس دعوے کی ان کے پاس چند دلیلیں ہیں:\nپہلی دلیل: حدیث میں لفظ [راح] (فعل ماضی) استعمال ہوا ہے جس کے معنی بعداز زوال جانے یا روانہ ہونے کے ہیں۔ اس سے معلوم ہوا کہ بعد از زوال جلدی نکلنے کی ترغیب ہے نہ کہ دن کے آغاز میں۔ اس کا جواب یہ ہے کہ لفظ راح صرف بعد از زوال جانے پر نہیں بولا جاتا، بلکہ مطلق جانے پر بھی اس کا اطلاق ہوتا ہے، خواہ جانا کسی وقت بھی ہو، یہ اہل حجاز کی لغت ہے، جیسا کہ امام زہری رحمہ اللہ نے کہا ہے، لہٰذا سفر دن کے آغازم یں یا آخر میں یا رات کے وقت ہو، اس پر یہ لفظ بولا جاتا ہے، اس کی بعد از زوال وقت کے ساتھ تخصیص درست نہیں۔\nدوسری دلیل: حدیث میں وارد لفظ [الھجر] ہے، نیز اس حدیث میں بجائے ساعات کے لفظ [ثم] استعمال ہوا ہے، جس کے معنی یہ ہیں کہ لوگ ایک دوسرے کے بعد آئیں، اور اس میں گھڑیو کا ذکر نہیں ہے۔ اور [المھجر، تھجیر] سے مشتق ہے جس کے معنی عین دوپہر کا وقت ہیں جسے عربی میں الھاجرۃ کہتے ہیں۔ اس سے بھی پتہ چلا کہ آغاز دن مراد نہیں۔ اس کا جواب یہ ہے کہ جن روایات میں ساعات کا ذکر ہے، وہ مفصل ہیں اور لفظ [ثم] کے ساتھ منقول حدیث مبہم ہے۔ قاعدے کی رو سے مجمل کو مفصل پر محمول کیا جاتا ہے، یعنی جو وضاحت مفصل میں ہوتی ہے، اسے ہی لینا ضروری ہے، اس لیے الساعات کی تصریح سے منقول روایات مقدم ہیں، نیز سب طرق و روایات میں صرف لفظ [الھجر] ہی نہیں آتا بلکہ ابن حجر رحمہ اللہ بیان کرتے ہیں کہ بعض میں لفظ [غدا] اور بعض میں [المتعجل] ’’جلدی کرنے والے‘‘ کے الفاظ وغیرہ بھی ہیں۔ اس سے لفظ [المھجر] کے معنی متعین ہو جاتے ہیں، نیز لغت میں یہ لفظ تبکیر و تعجیل کے معنی میں بھی آتا ہے جس سے پتہ چلتا ہے کہ اگرچہ اس کے معنی میں عین دوپہر یا شدید دھوپ میں نکلنے کے بھی آتے ہیں لیکن لغت کی روشنی میں تبکیر و تعجیل کے معنی سے بھی مفر نہیں، بلکہ مجموعی طور پر دیکھا جائے تو یہاں اسی مؤخر الذکرمعنی میں استعمال ہوا ہے۔\nتیسری دلیل: لفظ [الساعۃ] معروف گھنٹے کے معنی میں نہیں بلکہ زمانے یا وقت کے ایک جز یا حصے پر بولا جاتا ہے۔ اردو میں اس کے معنی ’’گھڑی‘‘ کے کیے جاتے ہیں، یہ عام ہے، خواہ تھوڑے وقت کو محیط ہو یا زیادہ کو، اسی لیے اس کے معنی لمحے یا لحظات کیے جاتے ہیں۔ اس کا جواب تین طرح دیا جا سکتا ہے: (۱) شرعاً ایک دن کے بارہ گھڑیوں میں تقسیم ہونے کا ذکر ملتا ہے جیسا کہ سنن ابی داود کی حدیث میں ہے۔ زثر بحث مسئلے میں اس سے تائید لی جا سکتی ہے۔ (۲) عرف میں بھی الساعۃ کے متبادر معنی یہی ہیں جو جمہرو مراد لیتے ہیں۔ (۳) اگر الساعات سے مراد چھٹی گھڑی کے چند لمحات یا لحظے ہی ہوتے تو رسول اللہ صلی اللہ علیہ وسلم کے پانچ گھڑیوں کے ذکر کے کیا معنی ہیں؟ اس سے ظاہر ہوتا ہے کہ اس سے مراد وہی پانچ گھڑیاں ہیں جو بارہ گھڑیوں کا حصہ ہیں۔ جن پر، گرمی ہو یا سردی، ایک دن محیط ہوتا ہے۔\nچوتھی دلیل: اگر احادیث میں وارد ساعات سے مراد چند لمحے یا لحظات مراد نہ ہوں تو اس سے ان گھڑیوں کی طوالت لازم آتی ہے، یعنی ان گھڑیوں کا دورانیہ لمبا ٹھہرتا ہے جس سے، سابق اور لاحق، یعنی پہلے اور بعد میں آنے والوں کا فرق ختم ہو جاتا ہے، اور ان گھڑیوں میں یکے بعد دیگرے آنے والوں کی فضیلت میں برابری اور یکسانیت لازم آتی ہے، مثلاً: پہلی گھڑی اگر ایک یا سوا گھنٹے پر مشتمل ہو تو ممکن ہے اس گھڑی میں وہ چار یا آٹھ دس آدمی یکے بعد دیگرے آئیں۔ اسی طرح باقی گھڑیوں میں بھی یہ ہوتا ہے یا اس کا قوی امکان ہے۔ کیا اس گھڑی میں پنے والے ان تمام افراد کو اونٹ کی قربانی کا ثواب ملتا ہے یا صرف ان کو جو ان میں سے پہلے آئے اور بس؟ اسی اعتراض سے بچنے کے یے امام مالک رحمہ اللہ وغیرہ ان سے مراد چند لمحات یا لحظات لیتے ہیں۔ اس اشکال کا جواب یہ دیا جاتا ہے کہ اگرچہ پہلی گھڑی میں یکے بعد دیگرے آنے والے تمام افراد نفس اونٹ کی قربانی کا ثواب تو پاتے ہیں جیسا کہ حدیث میں ہے، لیکن اس سے ہر لحاظ سے اونٹ کی قربانی میں تمام افراد کی برابری اور یکسانیت لازم نہیں آتی، وہ اس طرح کہ جو سب سے پہلے آئے اسے خوب موٹے تازے فربے اونٹ کی قربانی کا ثواب ملتا ہو، جو اس کے بعد آئے اسے اس سے کم تر اور جو اس کے بعد آئے اسے اس سے کمزور یا کم تر اونٹ کی قربانی کا ثواب ملتا ہو، یعنی مذکورہ تفاوت اور فرق یا اختلاف مراتب نفس اونٹ وغیرہ کی ذات کی بنا پر تو نہ ہو بلکہ ان کی صفات میں ہو اور برابری صرف اونٹ وغیرہ کی ذات کی حد تک ہو جیسا کہ ذکر ہوا، اور یہی بات درست ہے۔ حدیث کو اس طرح سمجھنے سے اشکال و اعتراض رفع ہو جاتا ہے۔ واللہ أعلم۔\nپانچویں دلیل: اہل مدینہ کا عمل اس کے برعکس تھا۔ وہ آغاز دن ہی سے نہیں آتے تھے بلکہ صحابۂ کرام رضی اللہ عنھم کا بھی یہ عمل نہ تھا، اس لیے اگر حدیث میں وارد لفظ الساعات سے جمہور والی گھڑیاں مراد لی جائیں تو صحابۂ کرام رضی اللہ عنھم نیکی کی شدید رغبت و حرص کے باوجود اول النہار حاضر نہ ہوتے تھے۔ جو اس بات کی دلیل ہے کہ یہاں ساعات سے مراد زوال کے بعد چھٹی گھڑی کے چند مختصر لمحے یا لحظے ہی ہیں۔ اس کا جواب یہ ہے کہ اہل مدینہ کل امت نہیں کہ ان کا اتفاق یا عدم عمل قابل حجت اور اجماع کی حیثیت ا حامل ہو۔ پھر اول النہار مسجد کی طرف جانا بھی تو کوئی واجبی عمل نہیں، بلکہ بعض دیگر امور دینی یا دیگر مصالح اس عمل سے کہیں زیادہ اہمیت و فضیلت کے حامل ہوتے ہیں، اس لیے اسے ترک کیا جا سکتا ہے اور یہ جائز ہے۔ اس سے یہ نہیں نکلتا کہ اس درجہ تعجیل ان کے ہاں مکروہ یا ناجائز تھی۔ یقیناً جو آدمی نماز فجر پڑھ کر اسی جگہ ذکراذکار میں مشغول رہے اور سورج طلوع ہونے کے بعد دو رکعت پڑھ لے، وہ اس آدمی سے جو صرف اشراق ہی پڑھتا ہے، کہیں زیادہ فضیلت اور ثواب کا حامل ہے۔ اسی طح وہ آدمی، جو نماز فجر کی ادائیگی کے بعد غسل وغیرہ کرے اور تیار ہو، اور اشراق پڑھ کر نماز جمعہ کے انتظار میں بیٹھا رہے، یقیناً اس شخص کی نسبت یہ کہیں زیادہ فضیلت پاتا ہے جو خطیب کے آنے سے صرف چند لمحے قبل مسجد میں پہنچتا ہے، جبکہ احادیث کی روشنی میں اس طرح انتظار کرنے والے کو بدستور نماز کی حالت میں شمار کیا گیا ہے۔ بلاشبہ ایسے آدمی کی فضیلت کا کسی کو انکار نہیں اور نہ ہونا چاہیے۔ اس قسم کے اعمال کی مشرعیت عمومی دلائل و احادیث سے اخذ ہوتی ہے۔ کی صحابی یا تابعی کے عدم عمل یا ان کے متعلق عدم نقل کی بنا پر اسے رد نہیں کیا جا سکتا۔ واللہ أعلم۔\nچھٹی دلیل: اگر حدیث میں موجود الساعات کو فلکی ساعات، یعنی گھنٹوں کے معنی میں لیا جائے تو اس صورت میں خطیب کا قبل از زوال نکلنا لازم آتا ہے۔ وہ اس طرح کہ آفتاب کے ےبلند ہونے سے امام کے خروج سے قبل تک، وقت کے دورانیے ککو پانچ گھڑیوں میں تقسیم کیا جائے تو پانچویں گھڑی کے بعد خروجِ امام کا ذکر ہے جیسا کہ حدیث میں آتا ہے۔ یہ چھٹی گھڑی کا ابتدائی اور قبل از زوال کا وقت ہوتا ہے۔ اور جمہور کے نزدیک قبل از زوال نماز جمعہ درست نہیں۔ لیکن جن کے نزدیک یہ جائز ہے ان کے لیے یہ حدیث قابل اعتراض نہیں بلکہ ان کے حق میں ہے۔ حافظ ابن حجر رمہ اللہ اس اعتراض کا جدواب دیتے ہوئے لکھتے ہیں: اس حدیث کے کسی طریق میں امام کے اول النہار نکلنے کا ذکر نہیں ہے ہوسکتا ہے پہلی گھڑی نہانے اور جمعے کی تیاری وغیرہ کے لیے ہو۔ اور مسجد میں آنا دوسری گھڑی کے آغاز میں ہو۔ اس طرح دن کے اعتبار سے یہ دوسری گھڑی ہوگی اور جانے کے اعتبار سے پہلی۔ بنا بریں پانچویں گھڑی کے پخری لحظے زوال کے ابتدائی لمحات ہوں گے۔ (فتح الباري: ۳۶۸/۲)\nالغرض مذکورہ معروضات سے واضح ہوتا ہے کہ امام مالک رحمہ اللہ کا موقف مرجوح ہے۔ جمہور علماء ک دلائل قوی اور قرین قیاس ہیں۔ اگرچہ قرآن و حدیث کی روشنی میں حدیث میں منقول ساعات کی واضح طور پر تحدید مشکل ہے لیکن فریق مخالف کے مقابلے میں جمہور کی رائے ہی مضبوط ہے۔ شیخ البانی رحمہ اللہ کی تحقیق بھی یہی ہے۔ واللہ أعلم۔ مزید تفصیل کے لیے ملاحظہ فرمائیے: (إحکام الأحکام شرح عمدۃ الأحکام لابن دقیق العبد، مع حاشیۃ العدۃ: ۵۳۱-۵۲۲/۲، وزاد المعاد: ۴۰۷-۳۹۹/۱ بتحقیق شعیب الأرناؤط، و فتح الباري: ۳۷۰-۳۶۶/۲، رقم الحدیث: ۸۸۱، و مرعاۃ المفاتیح: ۲۹۵-۲۹۳/۲، طبعہ أولی، و موسوعہ فقھیہ از حمین بن عودہ: ۳۶۲/۲)\n(۳)رجسٹر بند ہونے کے بعد آنے والے سبقت کے ثواب سے محروم رہتے ہیں مگر انھیں جمعے کی حاضری، خطبے کے سماع، نماز میں شرکت اور ذکر و دعا وغیرہ کا ثواب ملتا ہے۔ لیکن درجات میں فرق پڑ جاتا ہے۔ (۴) ببعض لوگ اس سے حدیث سے اس بات پر استدلال کرتے ہیں کہ مرغی کی قربانی بھی جائز ہے لیکن اگر اس استدلال کو درست سمجھ لیا جائے تو پھر انڈے کی قربانی کا جواز بھی تسلیم کرنا پڑے گا، جسے یہ خود بھی تسلیم نہیں کرتے۔ بنا بری یہ استدلال درست نہیں۔ اس حدیث میں مذکورہ چیزوں کی قربانی سے مراد وہ اجر و ثواب ہے جو ان چیزوں کے صدقہ کرنے سے ملتا ہے، اسی لیے بعض لوگ [مھدی] کے معنی ہی ’’صدقہ کرنے والا‘‘ کرتے ہیں۔ بہرحال جو معنی بھی کیے جائیں، اس سے مرغی یا انڈے کی قربانی کا جواز کشید کرنا یکسر غلط ہے۔ (۵) ادنیٰ سی چیز بھی اللہ کی راہ میں دینے سے ہچکچانا نہیں چاہیے۔ اخلاص کے ساتھ دی ہوئی معمولی سی چیز بھی عنداللہ بہت زیادہ اجر و ثواب کا باعث ہے۔ نبیٔ اکرم صلی اللہ علیہ وسلم ن فرمایا: ’’آگ سے بچو، چاہے کھجور کے ایک ٹکڑے (کے صدقے) کےساتھ ہی۔‘‘ (صحیح البخاري، الزکاۃ، حدیث: ۱۴۱۷)"}],[1386,"ابوہریرہ رضی اللہ عنہ کہتے ہیں کہ نبی اکرم صلی اللہ علیہ وسلم نے فرمایا: \"جب جمعہ کا دن آتا ہے تو مسجد کے دروازوں میں سے ہر دروازے پر فرشتے لوگوں کو ان کے درجات و مراتب کے مطابق یعنی ترتیب وار لکھتے ہیں، جو پہلے آتا ہے اسے پہلے لکھتے ہیں، جب امام خطبہ دینے کے لیے نکلتا ہے تو رجسٹر لپیٹ دیے جاتے ہیں، اور فرشتے خطبہ سننے لگتے ہیں، جمعہ کے لیے سب سے پہلے آنے والا ایک اونٹ قربان کرنے والے کی طرح ہے، پھر جو اس کے بعد آئے وہ ایک گائے قربان کرنے والے کی طرح ہے، پھر جو اس کے بعد آئے وہ ایک مینڈھا قربان کرنے والے کی طرح ہے\"، یہاں تک کہ آپ نے مرغی اور انڈے کا (بھی) ذکر کیا۔","الألباني: صحيح",{"u2":"حضرت ابوہریرہ رضی اللہ عنہ سے روایت ہے اور وہ اسے نبی صلی اللہ علیہ وسلم تک پہنچاتے ہیں (یعنی مرفوعاً بیان کرتے ہیںJ ’’جب جمعے کا دن ہوتا ہے تو مسجد کے ہر دروازے پر فرشتے مقرر ہوتے ہیں جو لوگوں کے نام ان کے (ججمعۃ المبارک کے لیے آنے کے لحاظ سے) مراتب کے مطابق لکھتے ہیں، یعنی سب سے پہلے آنے والے، پھر ان کے بعد پہلے آنے والے (کا نام لکھتے ہیں)، پھر جب امام (خطبہ دینے کے لیے) نکلتا ہے تو وہ اپنے رجسٹر بند کرکے خطبۂ جمعہ سنتے ہیں، لہٰذا سب سے پہلے نماز جمعہ کے لیے آنے والا (کعبے کی طرف) قربانی کے لیے اونٹ بھیجنے والے کی طرح ہے، پھر اس کے بعد آنے والا (کعبے کی طرف) قربانی کے لیے گائے بھیجنے والے کی طرح ہے، پھر اس کے بعد آنے والا (کعبے کی طرف) قربانی کے لیے مینڈھا بھیجنے والے کی طرح ہے۔‘‘ حتی کہ آپ نے مرغی اور انڈے کا بھی ذکر فرمایا۔"}],[1387,"ابوہریرہ رضی اللہ عنہ سے مروی ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا جمعۃ المبارک کے دن فرشتے مسجد کے دروازوں پر بیٹھ جاتے ہیں اور لوگوں کے نام ان کے آنے کی ترتیب کے مطابق لکھتے ہیں۔ ان میں سے کوئی تو اس آدمی کی طرح ہوں گے جس نے اعلی درجے کا اونٹ صدقہ کیا، کچھ اس آدمی کی طرح جس نے کم درجے کا اونٹ صدقہ کیا، کچھ اس آدمی کی طرح جس نے اعلی درجے کی گائے صدقہ کی، کچھ اس آدمی کی طرح جس نے کم درجے کی گائے صدقہ کی، کچھ اس آدمی کی طرح جس نے اعلی درجے کی بکری صدقہ کی، کچھ اس آدمی کی طرح جس نے کم درجے کی بکری صدقہ کی، کچھ اس آدمی کی طرح جس نے بہترین مرغی صدقہ کی اور کچھ اس آدمی کی طرح جس نے کم درجے کی مرغی صدقہ کی، کچھ اس آدمی کی طرح جس نے قیمتی چڑیا صدقہ کی اور کچھ اس آدمی کی طرح جس نے عام چڑیا صدقہ کی، کچھ اس آدمی کی طرح جس نے بہترین انڈہ صدقہ کیا اور کچھ اس آدمی کی طرح جس نے عام انڈہ صدقہ کیا۔","الألباني: حسن صحيح لكن قوله عصفور منكر والمحفوظ دجاجة",{"u2":"حضرت ابوہریرہ رضی اللہ عنہ سے مروی ہے، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’جمعۃ المبارک کے دن فرشتے مسجد کے دروازوں پر بیٹھ جاتے ہیں اور لوگوں کے نام ان کے آنے کی ترتیب کے مطابق لکھتے ہیں۔ ان میں سے کوئی تو اس آدمی کی طرحہوں گے جس نے اعلیٰ درجے کا اونٹ صدقہ کیا۔ اور کچھ اس آدمی کی طرح جس نے کم درجے کا اونٹ صدقہ کیا۔ کچھ اس آدمی کی طرح جس نے اعلیٰ درجے کی گائے صدقہ کی اور کچھ اس کی طرح جس نے کم درجے کی گائے صدقہ کی۔ کچھ اس آدمی کی طرح جس نے اعلیٰ درجے کی بکری صدقہ کی، کچھ اس آدمی کی طرح جس نے کم درجے کی بکری صدقہ کی۔ کچھ اس آدمی کی طرح جس نے بہترین مرغی صدقہ کی اور کچھ اس آدمی کی طرح جس نے کم درجے کی مرغی صدقہ کی۔ کچھ اس آدمی کی طرح جس نے قیمتی چڑیا صدقہ کی اور کچھ اس آدمی کی طرح جس نے عام چڑیا صدقہ کی۔ کچھ اس آدمی کی طرح جس نے بہترین انڈہ صدقہ کیا اور کچھ اس آدمی کی طرح جس نے عام انڈہ صدقہ کیا۔","f2":"(۱) حدیث کا مقصد یہ ہے کہ آنے والوں کے اجروں میں فرق اوقات و ساعات کے لحاظ سے ہے، یعنی اونٹ کے ثواب کے لیے ایک وقت مقرر ہے۔ اس دوران میں جتنے لوگ بھی آئیں گے سب کو اونٹ کا ثواب ملے گا، البتہ یہ ہوسکتا ہے کہ اس وقت کے دوران میں بھی پہلے آنے والے اعلیٰ اونٹ کے صدقے کے ثواب کے مستحق قرار پائیں اور آخر میں آنے والے ادنیٰ اونٹ کے۔ درمیان میں آنے والے درمیانے درجے کے اونٹ کا۔ اسی طرح باقی جانوروں کا حساب ہے۔ جوں جوں تاخیر ہوتی جائے گی، ثواب کم ہوتا جائے گا۔ واللہ أعلم۔ (۲) مذکورہ روایت کو محقق کتاب نے سنداً ضعیف قرار دیا ہے جبکہ دیگر محققین اس کی بابت لکھتے ہیں کہ اس میں [عصفور] (چڑیا کا ذکر) منکر ہے۔ محفوظ [دجاجۃ] (مرغی) کا لفظ ہے۔ باقی روایت قابل حجت ہے۔ شیخ البانی رحمہ اللہ نے عصفور کو منکر اور دجاجہ کے لفظ کو محفوظ قرار دیتے ہئے باقی روایت کو حسن صحیح کہا ہے۔ بنابریں دلائل کی رو سے یہی بات راجح معلوم ہوتی ہے۔ واللہ أعلم۔ مزید تفصیل کے لیے دیکھیے: (صحیح سنن النسائي للألباني، رقم: ۱۳۸۶، و ذخیرۃ العقبی شرح سنن النسائي: ۱۶۴-۱۶۲/۱۶)"}],[1388,"ابوہریرہ رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"جس نے جمعہ کے دن غسل جنابت کے مانند (خوب اہتمام سے) غسل کیا، پھر وہ(جمعہ میں شریک ہونے کے لیے) پہلی ساعت (گھڑی) میں مسجد گیا، تو گویا اس نے ایک اونٹ اللہ کی راہ میں پیش کیا، اور جو شخص اس کے بعد والی گھڑی میں گیا، تو گویا اس نے ایک گائے پیش کی، اور جو تیسری گھڑی میں گیا، تو گویا اس نے ایک مینڈھا پیش کیا، اور جو چوتھی گھڑی میں گیا، تو گویا اس نے ایک مرغی پیش کی، اور جو پانچویں گھڑی میں گیا، تو گویا اس نے ایک انڈا پیش کیا، اور جب امام (خطبہ دینے کے لیے) نکل آتا ہے تو فرشتے مسجد کے اندر آ جاتے ہیں، اور خطبہ سننے لگتے ہیں\" ۱؎۔\n§وضاحت\n۱؎: یعنی نام درج کرنے والا رجسٹر بند کر دیتے ہیں، اس میں نماز جمعہ کے لیے جلد سے جلد جانے کی ترغیب و فضیلت کا بیان ہے، جو جتنی جلدی جائے گا اتنا ہی زیادہ ثواب کا مستحق ہو گا۔","الألباني: صحيح",{"u2":"حضرت ابوہریرہ رضی اللہ عنہ سے منقول ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’جس آدمی نے جمعۃ المبارک کے دن غسل جنابت کی طرح (اچھی طرح) غسل کای، پھر پہلے وقت میں (جمعے کے لیے) چل پڑا تو یوں سمجھو کہ اس نے اونٹ صدقہ کیا اور جو شخص دوسرے وقت میں چلا، گویا اس نے گائے صدقہ کی اور جو تیسرے وقت میں چلا، گویا اس نے مینڈھا صدقہ کیا اور جو آدمی چوتھے وقت وقت میں چلا، گویا اس نے مرغی صدقہ کی اور جو پانچویں وقت میں گیا، گویا اس نے انڈہ صدقہ کیا۔ پھر جب امام (خطبے کے لیے) نکلتا ہے تو (خصوصی درجات لکھنے والے) فرشتے بھی مسجد میں آکر ذکر سننے لگتے ہیں۔‘‘","f2":"(۱) ان ساعات یا اوقات سے مراد قبل از زوال کی وہ گھڑیاں ہیں جن کا آغاز سورج چڑھنے کے بعد ہوتا ہے جیسا کہ جمہور کا موقف ہے۔ اور یہی موقف دلائل کی رو سے درست ہے۔ واللہ أعلم۔ جس کی تفصیل گزشتہ حدیث (۱۳۸۶) کے فوائد میں گزر چکی ہے۔ (۲) باب کے عنوان سے لگتا ہے کہ امام صاحب رحمہ اللہ کا موقف ممکن ہے یہ ہو کہ نماز جمعہ کا وقت زوال کے بعد شروع ہوتا ہے۔ امام بخاری رحمہ اللہ سمیت اکثر اہل علم کا یہی مذہب ہے لیکن ابوہریرہ رضی اللہ عنہ کی مذکورہ حدیث سے اس مسئلے کا استنباط محل نظر ہے کیونکہ اس حدیث میں پانچ گھڑیوں کا ذکر ہے، اور پانچویں کے اختتام اور چھٹی گھڑی کے آغاز میں خروج امام کا ذکر ہے اور یہ قبل از زوال کا وقت ہے، اس طرح یہ حدیث ان اہل علم کی دلیل بنتی ہے جو قبل از زوال بھی نماز جمعہ کے قائل ہیں۔ ہاں اگر ان پانچ گھڑیوں کا شمار دوسری گھڑی سے ہو اور پہلی گھڑی غسل اور جمعے کی تیاری کے لیے ہو، جیسا کہ ابن حجر رحمہ اللہ نے توجیہ کی ہے تو پھر یہ حدیث قبل از زوال جمعہ کے موقف کے حاملین کی دلیل نہیں بنتی۔ امام نسائی رحمہ اللہ کا مذکورہ حدیث سے استدلال تب محل نظر ہوگا جب احادیث میں [بطۃ] بطخ اور [عصفور] ’’چڑیا‘‘ کا ذکر شاذ اور ضعیف تصور کیا جائے اور حق بھی یہی ہے کہ یہ دونوں اضافے ضعیف ہیں، لیکن اگر انہیں صحیح سمجھا جائے تو پھر مذکورہ اشکال وارد نہیں ہوتا کیونکہ اس صورت میں کل چھ گھڑیاں بنتی ہیں جس سے خطیب کا نکلنا ساتویں گھڑی کے پغاز میں لازم ٹھہرتا ہے اور یہ وقت بعد از زوال کا ہوتا ہے۔ امام نسائی رحمہ اللہ کا یہ ذہن ہوسکتا ہے کیونکہ انھوں نے مذکورہ اضافات والی روایات کے بعد یہ عنوان قائم کیا ہے۔ واللہ أعلم۔"}],[1389,"جابر بن عبداللہ رضی اللہ عنہم کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"جمعہ کا دن بارہ ساعتوں (گھڑیوں) پر مشتمل ہے، اس کی ایک ساعت ایسی ہے کہ اس میں جو بھی مسلمان بندہ اللہ تعالی سے کچھ مانگتے ہوئے پایا جاتا ہے، تو اسے وہ دیتا ہے، تو تم اسے آخری گھڑی میں عصر کے بعد تلاش کرو\" ۱؎۔\n§وضاحت\n۱؎: اس گھڑی کے بارے میں علماء میں بہت اختلاف ہے، بعض علماء کے نزدیک راجح قول یہی ہے جو اس حدیث میں بیان کیا گیا ہے، کچھ لوگ کہتے ہیں: یہ گھڑی امام کے منبر پر بیٹھنے سے نماز کے ختم ہونے تک کے درمیانی وقفے میں ہوتی ہے، واللہ اعلم۔","الألباني: صحيح",{"u2":"حضرت جابر بن عبداللہ رضی اللہ عنہا سے روایت ہے، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’جمعے کا دن بارہ گھنٹے ہے۔ (ان میں سے ایک وقت ایسا ہے کہ) اس میں جو شخص بھی اللہ تعالیٰ سے کوئی چیز مانگتا پایا جائے، اللہ تعالیٰ اسے ضرور وہ چیز دے دیتا ہے۔ تو تم اس وقت کو عصر کے بعد آخری گھنٹے میں تلاش کرو۔‘‘","f2":"(۱) اس روایت میں ساعات سے مراد، معروف (ساعات نجومیہ) گھنٹے ہیں، یعنی اللہ تعالیٰ کی مقرر کردہ چند گھڑیاں ہیں جو فضیلت رکھتی ہیں اور ان میں سے سب سے افضل وہ گھڑی ہے جس میں کوئی دعا رد نہیں ہوتی۔ (۲) محقق روایات کے مطابق وہ وقت یا گھڑی عصر کے بعد کسی وقت ہے۔ اگرچہ اس بارے میں اور اقوال بھی ہیں۔ واللہ أعلم۔"}],[1390,"جابر بن عبداللہ رضی اللہ عنہم کہتے ہیں کہ ہم رسول اللہ صلی اللہ علیہ وسلم کے ساتھ جمعہ پڑھتے تھے، پھر ہم لوٹتے تو اپنے اونٹوں کو آرام دیتے، میں نے کہا: وہ کون سا وقت ہوتا؟، انہوں نے کہا: سورج ڈھلنے کا۔","الألباني: صحيح",{"u2":"حضرت جابر بن عبداللہ رضی اللہ عنہما بیان کرتے ہیں کہ ہم رسول اللہ صلی اللہ علیہ وسلم کے ساتھ جمعے کی نماز پڑھتے، پھر واپس آکر اپنے پانی ڈھونے والے اونٹوں کو آرام کا موقع دیتے۔ حضرت محمد باقر نے (حضرت جابر رضی اللہ عنہ سے) پوچھا: کس وقت؟ انھوں نے فرمایا: زوال کے وقت۔","f2":"یہ سوال و جواب نماز جمعہ پڑھنے کے بارے می بھی ہوسکتا ہے اور واپس لوٹنے اور اونٹوں کو آرام دینے کے بارے میں بھی۔ گویا روایت مبہم ہے، لہٰذا اس سے قبل از زوال جمعہ پڑھنے پر استدلال درست نہیں بلکہ اسے مشہور روایات پر محمول کرنا چاہیے۔ واللہ أعلم۔"}],[1391,"سلمہ بن الاکوع رضی اللہ عنہ کہتے ہیں کہ ہم رسول اللہ صلی اللہ علیہ وسلم کے ساتھ جمعہ کی نماز پڑھتے تھے، پھر ہم اس حال میں لوٹتے کہ دیواروں کا سایہ نہ ہوتا جس سے سایہ حاصل کیا جا سکے ۱؎۔\n§وضاحت\n۱؎: یعنی زوال ہوئے ابھی تھوڑا سا وقت گزرا ہوتا۔","الألباني: صحيح",{"u2":"حضرت سلمہ بن اکوع رضی اللہ عنہ فرماتے ہیں کہ ہم رسول اللہ صلی اللہ علیہ وسلم کے ساتھ جمعے کی نماز پڑھ کر واپس لوٹتے تھے تو دیواروں کا سایہ اتنا نہیں ہوتا تھا کہ ان سے (اپنے آپ کو) سایہ مہیا کیا جا سکے۔","f2":"اس روایت سے بھی قبل از وال جمعہ پڑھنے پر استدلال کیا جاتا ہے، حالانکہ اس روایت میں کوئی لفظ اس معنی پر دلالت نہیں کرتا۔ صرف اتنا سمجھ میں آتا ہے کہ جمعہ ختم ہونے تک اتنا سایہ نہیں ہوتا تھا کہ جسم دھوپ سے بچ سکے۔ ظاہر ہے زوال کے بعد جمعہ پڑھنے سے قطعاً اتنا سایہ نہیں بنتا جو جسم کو دھوپ سے بچائے، ہاں اس سے یہ سمجھ میں آتا ہے کہ جمعہ زوال کے بعد جلدی پڑھ لیا جائے اور خطبہ لمبا نہ ہو۔ سخت گرمیوں میں کچھ تاخیر بھی کی جا سکتی ہے جیسے کہ پیچھے گزرا۔"}],[1392,"سائب بن یزید رضی اللہ عنہ کہتے ہیں رسول اللہ صلی اللہ علیہ وسلم اور ابوبکر و عمر رضی اللہ عنہم کے زمانے میں جمعہ کے دن پہلی اذان اس وقت ہوتی تھی جس وقت امام منبر پر بیٹھتا، پھر جب عثمان رضی اللہ عنہ کا دور خلافت آیا، اور لوگ بڑھ گئے تو انہوں نے جمعہ کے دن تیسری اذان کا حکم دیا ۱؎، وہ اذان مقام زوراء پر دی گئی، پھر اسی پر معاملہ قائم رہا۔\n§وضاحت\n۱؎: تکبیر کو شامل کر کے تیسری اذان ہوئی، یہ ترتیب میں پہلی اذان ہے جو خلیفہ راشد عثمان غنی رضی اللہ عنہ کی سنت ہے، دوسری اذان اس وقت ہو گی جب امام خطبہ دینے کے لیے منبر پر بیٹھے گا، اور تیسری اذان تکبیر ہے، اگر کوئی صرف اذان اور تکبیر پر اکتفا کرے تو اس نے نبی اکرم صلی اللہ علیہ وسلم اور ابوبکر و عمر رضی اللہ عنہم کی سنت کی اتباع کی۔","الألباني: صحيح",{"u2":"حضرت سائب بن یزید رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم اور حضرت ابوبکر و عمر رضی اللہ عنہما کے دور میں پہلی اذان اس وقت ہوتی تھی جب امام منبر پر بیٹھتا تھا، لیکن جب حضرت عثمان رضی اللہ عنہ کا دور خلافت آیا اور لوگ زیادہ ہوگئے تو حضرت عثمان رضی اللہ عنہ نے جمعے کے دن تیسری اذان کا حکم دیا جو زوراء (مقام) پر کہی جاتی تھی۔ پھر (جمعے کی اذان کا) معاملہ اسی کے مطابق جاری ہوگیا۔","f2":"(۱) اس روایت میں پہلی اذان سے مراد وہ اذان ہے جو خطبۂ جمعہ کے آغاز میں کہی جاتی ہے۔ آج کل اسے دوسری اذان کہا جاتا ہے۔ حدیث میں مذکور تیسری اذان سے مراد وہ اذان ہے جو خطبے کی اذان سے کچھ دیر قبل کہی جاتی ہے تاکہ لوگ جمعے کی تیاری کرلیں۔ آج کل اسے پہلی اذان کہا جاتا ہے۔ اس روایت میں اقامت کو بھی اذان کہا گیا ہے تبھی خطبے کی اذان کو پہلی اذان کہا گیا ہے۔ گویا اقامت دوسری اذان تھی۔ (۲) ’’لوگ زیادہ ہوگئے‘‘ مدینہ منورہ کی آبادی آہستہ آہستہ بڑھ گئی اور مسلمانوں کی تعداد میں بھی اضافہ ہوگیا تھا جب کہ خطبۂ جمعہ صرف مسجد نبوی ہی میں ہوتا تھا۔ اگر ایک ہی اذان (اذان خطبہ) ہوتی تو شہر کے اطراف سے آنے والے نمازی خطبۂ جمعہ بلکہ نماز جمعہ سے بھی محروم رہ جاتے۔ پھر جمعے کے دن بازار لگتا تھا، لوگ خرید و فروخت میں مشغول ہوتے۔ گھڑیاں تھی نہیں۔ جمعے کے وقت کا محق اندازہ کرتے تھے، اس میں غلطی اور تاخیر کے قوی احتمالات تھے، لہٰذا وہیں بازار میں زوراء پر وقت سے اتنی دیر پہلے اذان کہی جاتی تھی کہ اسے سن کر خریدار جلدی جلدی ضرورت کی چیز خرید کر اور دکاندار سامان سمیٹ کر گھر واپس جائیں۔ پھر غسل اور وضو کریں، کپڑے بدلیں، خوشبو لگائیں اور خطبے سے پہلے پہلے مسجد نبوی میں آکر حسب توفیق نماز پڑھیں۔ ان تفصیلات کو سامنے رکھتے ہئے آج کل خطبے کی اذان سے صرف ۱۵، ۲۰ منٹ پہلے، وہ بھی مسجد کے اندر کہی جاتی ہے، اس کے بارے میں غور کریں کہ حضرت عثمان رضی اللہ عنہ کی اذان سے اس کا کیا تعلق ہے؟ اور دونوںمیں کون سی مناسبت ہے؟ مزید یہ کہ آج کل گھڑیوں وغیرہ سے یہ ضرورت پوری ہوتی ہے۔ بہرحال حضرت عثمان رضی اللہ عنہ نے مذکورہ ضرورت کے تحت ایک اذان کا اضافہ فرمایا اور ان کے پاس اس اذان کی نظیر موجود تھی۔ رسول اکرم صلی اللہ علیہ وسلم کے دور مبارک میں صبح کی دو اذانیں ہوتی تھیں۔ ایک وقت پر اور ایک وقت سے پہلے تاکہ زیادہ مصروفیت والے لوگ پہلی اذان پر اٹھ کھڑے ہوں اور جماعت کے ساتھ مل سکیں۔ ایک اذان کی صورت میں بہت سے لوگ جماعت سے رہ جاتے، لہٰذا ایک اذان وقت سے کچھ دیر قبل کہی جاتی تھی۔ حضرت عثمان رضی اللہ عنہ نے اسی کو مدنظر رکھ کر خطبے سے پہلے ایک اذان کا اضافہ فرمایا جسے صحابۂ کرام رضی اللہ عنہم نے قبول فرمایا اور آہستہ آہستہ یہ تمام عالم اسلام میں رائج ہوگئی۔ اور یہ سنت المسلمین بن گئی جسے صحابہ کرام رضی اللہ عنہم سے لے کر ہر دور کے مجتہدین اور ائمہ کا اجماع میسر رہا ہے۔ گویا یہ اذان ضرورت ہے، خلیفۂ راشد کی سنت ہے اور اس پر صحابہ کرام رضی اللہ عنہم سے لے کر اب تک اجماع ہے، لہٰذا مذکورہ بالا پس منظر مدنظر رکھ کر اس پر عمل کیا جا سکتا ہے۔ [فعلیکم بسنتی و سنۃ الخلفاء الراشدین المھدیین] (سنن أبي داود، السنۃ، حدیث: ۴۶۰۷)، البتہ اگر کہیں ضرورت محسوس نہ ہو تو ایک ہی اذان پر اکتفا کرنا بہتر ہے کیونکہ سنتِ رسول صلی اللہ علیہ وسلم اور خلیفہ اول و ثانی، ابوبکر اور عمر فاروق رضی اللہ عنہما کا عمل بھی یہی تھا۔ حضرت ابن عمر رضی اللہ عنہما کا اس (پہلی اذان) کو بدعت کہنا لغوی معنی کے لحاظ سے ہے، جیسے حضرت عمر رضی اللہ عنہ نے تراویح کی جماعت کو بدعت کہا تھا، حالانکہ انھوں نے خود اس کو مستقلاً رائج کیا تھا۔ واللہ أعلم۔ (۳) ’’زوراء‘‘ بازار میں ایک بلند مکان تھا۔ وہاں یہ اذان کہی جاتی تھی تاکہ بلندی کی وجہ سے سارے مدینہ منورہ میں اذان سنائی دے کیونکہ اس (جمعہ) میں سب اہل مدینہ کی شمولیت ضروری تھی بخلاف دیگر نمازوں کے کہ وہ ہر محلے کی مقامی مساجد میں بھی باجماعت پڑھی جاتی تھیں۔ (۴) ’’جاری ہوگیا‘‘ کیونکہ وہ خلیفۂ راشد تھے، لہٰذا لوگوں نے اسے قبول کر لیا۔ بعض روایات کے مطابق مکہ مکرمہ میں حجاج کے دور میں شروع ہوئی اور بصرہ میں زیاد کے دور میں۔ واللہ أعلم۔"}],[1393,"سائب بن یزید رضی اللہ عنہ کہتے ہیں کہ تو تیسری اذان کا حکم عثمان رضی اللہ عنہ نے دیا تھا جب اہل مدینہ زیادہ ہو گئے تھے، حالانکہ رسول اللہ صلی اللہ علیہ وسلم کا صرف ایک ہی مؤذن تھا، اور جمعہ کے دن اذان اس وقت ہوتی تھی جب امام (منبر پر) بیٹھ جاتا تھا۔","الألباني: صحيح",{"u2":"حضرت سائب بن یزید رضی اللہ عنہ فرماتے ہیں کہ تیسری اذان کا حکم حضرت عثمان رضی اللہ عنہ نے اس وقت دیا جب مدینے والے زیادہ ہوگئے تھے۔ رسول اللہ صلی اللہ علیہ وسلم کے دوران میں ایک اذان ہی تھی (اذان خطبہ)۔ اور جمعے کے دن اذان اس وقت ہوتی تتھی جب امام منبر پر بیٹھتا تھا۔"}],[1394,"سائب بن یزید رضی اللہ عنہ کہتے ہیں کہ بلال رضی اللہ عنہ اس وقت اذان دیتے جب رسول اللہ صلی اللہ علیہ وسلم جمعہ کے دن منبر پر بیٹھ جاتے، پھر جب آپ اترتے تو وہ اقامت کہتے، اسی طرح ابوبکر اور عمر رضی اللہ عنہم کے زمانے میں بھی ہوتا رہا۔","الألباني: صحيح",{"u2":"حضرت سسائب بن زیدی رضی اللہ عنہ نے فرمایا: جب رسول اللہ صلی اللہ علیہ وسلم جمعے کے دن منبر پر بیٹھتے تھے تو حضرت بلال رضی اللہ عنہ اذان کہتے، پھر جب (دو خطبوں کے بعد) آپ منبر سے اترتے تو بلال اقامت کہتے۔ حضرت ابوبکر و عمر رضی اللہ عنہما کے زمانے میں بھی ایسے ہی رہا۔","f2":"ان دونوں روایات میں جمعے کی صرف ایک ہی اذان کو عہدِ رسالت و شیخین کا معمول بتلایا گیا ہے، اس لیے جہاں ضرورت نہ ہو، اور درحقیقت فی زمانہ غالباً اس کی ضرورت بھی نہیں ہے، وہاں اس کے مطابق ایک ہی اذان کا اہتمام کرنا چاہیے، البتہ جہاں اس کی ضرورت ہو، وہاں جمعے کی پہلی اذان دی جا سکتی ہے۔"}],[1395,"جابر بن عبداللہ رضی اللہ عنہم کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"جب تم میں سے کوئی (مسجد) آئے اور امام (خطبہ کے لیے) نکل چکا ہو ۱؎ تو چاہیئے کہ وہ دو رکعت پڑھ لے\"۔ شعبہ کی روایت میں ہے: \"جب تم میں سے کوئی جمعہ کے دن آئے\"۔\n§وضاحت\n۱؎: خواہ اس نے خطبہ شروع کر دیا ہو یا ابھی نہ کیا ہو، بلکہ ایک روایت میں «والإمام یخطب» کے الفاظ وارد ہیں، اس میں اس بات کی تصریح ہے کہ امام کے خطبہ دینے کی حالت میں بھی یہ دونوں رکعتیں پڑھی جائیں۔","الألباني: صحيح",{"u2":"حضرت جابر بن عبداللہ رضی اللہ عنہما نے کہا، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’جب تم میں سے کوئی شخص (جمعے کے لیے) آئے جب کہ امام (خطبے کے لیے) نکل چکا ہو تو وہ (مختصر سی) دو رکعتیں پڑھے۔‘‘","f2":"(۱) ان دو رکعتوں کو تحیۃ المسجد کہا جاتا ہے بعض اسے سنت جمعہ سے تعبیر کرتے ہیں۔ (۲) ’’امام (خطبے کے لیے) نکل چکا ہو۔‘‘ یعنی امام صاحب خطبہ شروع کرچکے ہوں، تب بھی یہ دو رکعتیں پڑھنی چاہییں کیونکہ بہت سی صحیح روایات میں ان کے پڑھنے کا خصوصی حکم ہے، لہٰذا احناف کا یہ کہنا کہ ’’خطبہ شروع ہونے کے بعد نماز شروع نہیں کی جا سکتی‘‘ صحیح احادیث کے خلاف ہے۔ صحیح بخاری اور صحیح مسلم کی حدیث میں ہے کہ ایک شخص بغیر دو رکعت پڑھے بیٹھ گیا تو آپ نے اسے اٹھنے اور دو رکعت پڑھنے کا حکم دیا۔ (صحیح البخاري، الجمعۃ، حدیث: ۹۳۰، ۹۳۱، و صحیح مسلم، الجمعۃ، حدیث: ۸۷۵) البتہ دو رکعت ہلکی پڑھنی چاہییں۔ (۳) خطیب دوران خطبہ مقتدیوں سے کوئی بات پوچھ سکتا ہے اور وہ اس کا جواب دے سکتے ہیں۔ اس سے مقتدیوں کے استماع پر کوئی اثر نہیں پڑتا۔ لیکن مقتدی آپس میں ایک دوسرے سے بات نہیں کرسکتے۔ یہ آداب خطبہ کے منافی ہے۔"}],[1396,"جابر بن عبداللہ رضی اللہ عنہم کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم جب خطبہ دیتے تو مسجد کے ستونوں میں سے کھجور کے ایک تنا سے آپ ٹیک لگاتے تھے، پھر جب منبر بنایا گیا، اور آپ اس پر کھڑے ہوئے تو وہ ستون (جس سے آپ سہارا لیتے تھے) بیقرار ہو کر رونے لگا جس طرح اونٹنی روتی ہے، یہاں تک کہ اسے مسجد والوں نے بھی سنا، یہاں تک کہ رسول اللہ صلی اللہ علیہ وسلم اتر کر اس کے پاس گئے، اور اسے گلے سے لگایا تو وہ چپ ہوا۔","الألباني: صحيح",{"u2":"حضرت جابر بن عبداللہ رضی اللہ عنہما سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم جب خطبہ دیتے تھے تو مسجد کے ستونوں میں سے ایک کھجور کے تنے کے ساتھ سہارا لیا کرتے تھے۔ جب منبر تیار ہوا اور آپ (خطبے کے لیے) اس پر تشریف فرما ہوئے تو وہ ستون بے چین ہوکر اونٹنی کی طرح رونے لگا حتی کہ سب مسجد والوں نے اس کی آواز سنی۔ رسول اللہ صلی اللہ علیہ وسلم منبر سے اتر کر اس کی طرف آئے اور اسے گلے سے لگایا، پھر وہ (آہستہ آہستہ) چپ ہوگیا۔","f2":"(۱) رسول اللہ صلی اللہ علیہ وسلم کے دور میں مسجد نبوی کے تام ستون کھجور کے تنے کے تھے۔ مذکورہ تنے پر نبی صلی اللہ علیہ وسلم ٹیک لگاتے تھے، اس لیے جب آپ منبر پر تشریف فرما ہوئے تو وہ غم جدائی میں رونے لگا۔ (۲) ’’رونے لگا‘‘ یہ نبی صلی اللہ علیہ وسلم کا ظاہر معجزہ تھا کہ خشک تنے سے قریب الولادت اونٹنی کی آواز جیسی آواز آنے لگی۔ سب موجود لوگوں نے سنا، پھر آپ کے اس کے ساتھ پیار کرنے پر اس کا چپ ہونا دوسرا معجزہ ہے۔ صلی اللہ علیہ وسلم۔ دیگر روایات میں صراحت ہے کہ وہ تنا آپ کے فراق میں رویا تھا۔ (۳) حدیث سے معلوم ہوا کہ امام کو خطبۂ جمعہ کے دوران میں منبر پر کھڑا ہونا چاہیے کیونکہ آپ کی آخری سنت یہی ہے۔ باب کا مقصد بھی یہی ہے۔ (۴) منبر پر کھڑا ہونے میں امام کی فضیلت ہے، نیز وہ سب کو نظر آئے گا۔ سب اس کی آواز سنیں گے۔ دو خطبوں کے درمیان بیٹھنے میں سہولت ہوگی۔ (۵) امام اپنے پاؤں منبر پر رکھے حضرت عمر رضی اللہ عنہ منبر کی پہلی سیڑھی پر، حضرت ابوبکر صدیق رضی اللہ عنہ دوسری پر اور رسول اللہ صلی اللہ علیہ وسلم تیسری پر پاؤں رکھتے تھے۔ بعد میں احتراماً تیسری اور دوسری سیڑھی کو چھوڑ دیا گیا۔"}],[1397,"کعب بن عجرہ رضی اللہ عنہ کہتے ہیں کہ وہ مسجد میں آئے اور عبدالرحمٰن بن ام الحکم بیٹھ کر خطبہ دے رہے تھے تو انہوں نے کہا: اس شخص کو دیکھو بیٹھ کر خطبہ دے رہا ہے، حالانکہ اللہ تعالی نے فرمایا ہے: «وإذا رأوا تجارة أو لهوا انفضوا إليها وتركوك قائما» \"اور جب وہ کوئی سودا بکتا دیکھیں یا کوئی تماشا نظر آ جائے تو اس کی طرف دوڑ جاتے ہیں اور آپ کو کھڑا ہی چھوڑ دیتے ہیں\" (الجمعہ: ۱۱)۔","",{"u2":"حضرت کعب بن عجرہ رضی اللہ عنہ مسجد میں داخل ہوئے تو عبدالرحمٰن بن ام الحکم بیٹھ کر خطبہ دے رہا تھا۔ وہ فرمانے لگے: اسے دیکھو بیٹھ کر خطبہ دے رہا ہے جب کہ اللہ تعالیٰ نے قرآن مجید میں فرمایا ہے: (واذا راوا تجارۃ اولھوا انقضوا الیھا وترکوک قائما) ’’جب وہ کوئی تجارت یا کوئی تماشا دیکھتے ہیں تو اٹھ کر اس طرف چلے جاتے ہیں اور آپ کو کھڑا چھوڑ جاتے ہیں۔‘‘","f2":"یہ سورۂ جمعہ کی آخری آیت ہے۔ اس میں جمعے ہی کا ذکر ہے۔ ایک دفعہ نبی صلی اللہ علیہ وسلم خطبہ دے رہے تھے کہ تجارتی قافلے کی گھنٹیاں بجنے لگیں، لوگ غلہ حاصل کرنے کے لیے آہستہ آہستہ کھسک گئے، چند ایک باقی رہ گئے تھے۔ آپ کھڑے خطبہ دے رہے تھے۔ اسی سے استدلال ہے، آپ کی سنت پر عمل کرنا بھی ضروری ہے۔ آپ خطبہ ہمیشہ کھڑے ہوکر دیا کرتے تھے۔"}],[1398,"اوس بن اوس ثقفی رضی اللہ عنہ کہتے ہیں رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"جو شخص غسل کرائے اور خود بھی غسل کرے، اور مسجد کے لیے سویرے نکل جائے، اور امام سے قریب رہے، اور خاموشی سے خطبہ سنے، پھر کوئی لغو کام نہ کرے، تو اسے ہر قدم کے عوض ایک سال کے روزے، اور قیام کا ثواب ملے گا\"۔","الألباني: صحيح",{"u2":"حضرت اوس بن اوس ثقفی رضی اللہ عنہ سے روایت ہے، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’جو شخص اپنے جسم اور کپڑوں کو دھوئے اور غسل کرے اور اول وقت (مسجد میں) جائے اور شروع خطبہ کو پائے، امام کے قریب بیٹھے اور خاموش رہے، پھر کوئی لغو بات یا کام نہ کرے، اس کے لیے ہر قدم کے عوض ایک سال کے صیام و قیام کا ثواب ہے۔","f2":"دیکھیے‘حدیث:1382)"}],[1399,"ابوالزاہریہ کہتے ہیں کہ میں جمعہ کے روز عبداللہ بن بسر رضی اللہ عنہ کے بغل میں بیٹھا تھا تو انہوں نے کہا: ایک آدمی لوگوں کی گردنیں پھلانگتا ہوا آیا، تو رسول اللہ صلی اللہ علیہ وسلم نے اس سے فرمایا: \"اے فلان! بیٹھ جاؤ تم نے (لوگوں کو) تکلیف دی ہے\" ۱؎۔\n§وضاحت\n۱؎: یہ اس صورت میں ہے جب اگلی صفوں میں خالی جگہ نہ ہو لیکن اگر لوگوں نے خالی جگہ چھوڑ رکھی ہو تو گردنیں پھلانگ کر جانا درست ہو گا، یا یہ اس وقت کے ساتھ خاص ہے جب امام منبر پر بیٹھا ہو۔","الألباني: صحيح",{"u2":"حضرت ابو زاہریہ بیان کرتے ہیں کہ میں جمعے کے دن حضرت عبداللہ بن بسر رضی اللہ عنہ کے پہلو میں بیٹھا ہوا تھا تو انھوں نے کہا: (رسول اللہ صلی اللہ علیہ وسلم کے دور میں) ایک آدمی لوگوں کی گردنیں پھلانگتا ہوا آیا تو اس سے رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’او! بیٹھ جاؤ۔ تم نے لوگوں کو تکلیف دی ہے۔‘‘","f2":"یہ تب ہے جب آگے صفوں میں جگہ خالی نہ ہو۔ اگر آگ جگہ خالی ہے مگر لوگوں کی گردنیں پھلانگے بغیر وہاں پہنچا نہیں جا سکتا تو گردنیں پھلانگنا جائز ہے کیونکہ اس میں ان لوگوں کا قصور ہے کہ خالی جگہ چھوڑ کر پیچھے بیٹھے۔ اسی طرح امام بھی لوگوں کی گردنیں پھلانگ کر منبر تک پہنچ سکتا ہے کیونکہ اس کے بغیر چارہ نہیں۔"}],[1400,"جابر بن عبداللہ رضی اللہ عنہم کہتے ہیں کہ نبی اکرم صلی اللہ علیہ وسلم جمعہ کے دن منبر پر تھے، ایک آدمی (مسجد میں) آیا تو آپ نے اس سے پوچھا: \"کیا تم نے دو رکعتیں پڑھ لیں؟\" اس نے کہا: نہیں، تو آپ نے فرمایا: \"تو پڑھ لو\" ۱؎۔\n§وضاحت\n۱؎: اس حدیث میں اس کی وضاحت نہیں کہ جمعہ سے پہلے کتنی سنتیں ہیں، اس سے صرف اتنا معلوم ہوتا ہے کہ مسجد میں آنے والا دو رکعت پڑھ کر بیٹھے حتی کہ اگر کوئی شخص خطبہ جمعہ کے دوران بھی آئے تو وہ بھی مختصر طور پر دو رکعت ضرور پڑھے پھر خطبہ سنے تاہم خطبہ سے پہلے آنے والا شخص دو رکعت تحیۃالمسجد ادا کرنے کے بعد دو دو کر کے جتنے چاہے نوافل پڑھ سکتا ہے۔","الألباني: صحيح",{"u2":"حضرت جابر بن عبداللہ رضی اللہ عنہما سے روایت ہے کہ ایک آدمی آیا جب کہ نبی صلی اللہ علیہ وسلم جمعے کے دن منبر پر (خطبہ دے رہے) تھے۔ آپ نے اس سے فرمایا: ’’تو نے دو رکعتیں پڑھی ہیں؟‘‘ اس نےکہا: نہیں۔ آپ نے فرمایا: ’’پھر پڑھ۔‘‘","f2":"دیگر روایات میں صراحت ہے کہ آپ خطبہ دے رہے تھے، لہٰذا احناف کا یہ کہنا کہ ابھی آپ نے خطبہ شروع نہیں کیا تھا، احادیث سے اعراض کی دلیل ہے، نیز صحیح مسلم کی صریح قولی روایت کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’جب کوئی آئے اور امام خطبہ دے رہا ہو تو وہ مختصر سی دو رکعت نماز پڑھے۔‘‘ (صحیح مسلم، الجمعۃ، حدیث: ۸۷۵)، ہر قسم کی تاویل کو رد کرتی ہے، لہٰذا آنے والے کو بیٹھنے سے پہلے دو رکعت پڑھنا لازم ہے۔ (ممزید دیکھیے: حدیث: ۱۳۹۶)"}],[1401,"ابوہریرہ رضی اللہ عنہ کہتے ہیں کہ نبی اکرم صلی اللہ علیہ وسلم نے فرمایا: \"جس شخص نے جمعہ کے دن اپنے ساتھی سے کہا: \"خاموش رہو\" اور امام خطبہ دے رہا ہو تو اس نے لغو حرکت کی\"۔","الألباني: صحيح",{"u2":"حضرت ابوہریرہ رضی اللہ عنہ سے مروی ہے، نبی صلی اللہ علیہ وسلم نے فرمایا: ’’جس شخص نے جمعے کے دن خطبے کی حالت میں اپنے ساتھی سے کہا: ’’چپ رہ‘‘ اس نے بھی لغوبات کی۔‘‘","f2":"(۱) جمعے میں کثیر تعداد ہوتی ہے۔ اگر معمولی بات کرنے کی بھی اجازت ہوتی تب بھی شور و شغب پڑ جاتا، اس لیے مطلقاً کلام سے روک دیا گیا، حتی کہ زبان سے کسی کو چپ بھی نہ کرائے کیونکہ بسا اوقات چپ کرانے والوں کا شور باتیں کرنے والوں سے بڑھ جاتا ہے اور ’’یک نہ شد دو شد‘‘ والا معاملہ بن جاتا ہے۔ ہاں بامر مجبوری اشارے سے چپ کرا سکتا ہے۔ (۲) احناف اس سے استدلال کرتے ہیں کہ اگر ’’چپ رہ‘‘ نہیں کہہ سکتا تو دورانِ خطبہ نماز کیسے پڑھ سکتا ہے؟ اس کا جواب یہ ہے کہ یہ لغو کام ہے۔ کیا نماز بھی لغو ہے؟ (نعوذ باللہ) پھر نماز تو آہستہ پڑھی جاتی ہے، شور نہیں ہوتا۔ بات کرنے سے شور ہوتا ہے، نیز نماز کی روایات صریح حکم والی ہیں۔ کیا ان صریح روایات کو ایسے عمومی دلائل سے رد کیا جا سکتا ہے؟ (۳) ’’لغو بات کی‘‘ لہٰذا اس کا اجر ضائع ہو گیا، یعنی فرض تو ادا ہوگیا، البتہ جمعے کی فضیلت حاصل نہ ہوئی۔ گویا ظہر پڑھ لی۔ یہ مطلب نہیں کہ اس کا فرض بھی ادا نہ ہوا کیونکہ خطبہ عین نماز نہیں۔ واللہ أعلم۔"}],[1402,"ابوہریرہ رضی اللہ عنہ کہتے ہیں کہ میں نے رسول اللہ صلی اللہ علیہ وسلم کو فرماتے سنا: \"جب تم اپنے ساتھ والے سے جمعہ کے دن کہو: \"خاموش رہو\" اور امام خطبہ دے رہا ہو تو تم نے لغو کام کیا\"۔","الألباني: صحيح",{"u2":"حضرت ابوہریرہ رضی اللہ عنہ سے منقول ہے کہ میں نے رسول اللہ صلی اللہ علیہ وسلم کو یہ فرماتے ہوئے سنا: ’’جب تو نے جمعے کے دن، جبکہ امام خطبہ دے رہا ہو، اپنے ساتھی سے کہا: ’’چپ ہو جا‘‘ تو تو نے لغو کام کیا۔‘‘"}],[1403,"سلمان رضی اللہ عنہ کہتے ہیں کہ مجھ سے رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"جو بھی آدمی پاکی حاصل کرتا ہے جیسا کہ اسے حکم دیا گیا، پھر وہ اپنے گھر سے نکلتا ہے یہاں تک کہ وہ جمعہ میں آتا ہے، اور خاموش رہتا ہے یہاں تک کہ وہ اپنی نماز ختم کر لے، تو (اس کا یہ عمل) اس کے ان گناہوں کے لیے کفارہ ہو گا جو اس سے پہلے کے جمعہ سے اس جمعہ تک ہوئے ہیں\"۔","الألباني: صحيح",{"u2":"حضرت سلمان رضی اللہ عنہ سے روایت ہے کہ مجھ سے رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’جو بھی شخص جمعے کے دن اس طرح طہارت کرے جس طرح اسے حکم دیا گیا ہے، پھر اپنے گھر سے نکلے حتی کہ جمعے میں حاضر ہو اور خاموش رہے، یہاں تک کہ نماز پوری کرے، تو یہ گزشتہ جمعے سے اب تک ہونے والے گناہوں کا کفارہ بن جائے گا۔‘‘","f2":"(۱) ’’جس طرح اسے حکم دیا گیا ہے‘‘ سے مراد وضو ہو یا غسل ہر دو صورت میں مسنون طریقے سے ہی مذکورہ فضیلت کا حامل ہوگا۔ (۲) مندرجہ بالا فضیلت ان تمام کاموں کی بنا پر ہے جن کا حدیث میں ذکر ہے۔ چونکہ ان میں خاموش رہنا بھی داخل ہے، لہٰذا فضیلت کی نسبت اس کی طرف بھی کی جا سکتی ہے۔"}],[1404,"عبداللہ بن مسعود رضی اللہ عنہ کہتے ہیں کہ نبی اکرم صلی اللہ علیہ وسلم نے ہمیں خطبہ حاجة ۱؎ سکھایا، اور وہ یہ ہے: «الحمد لله نستعينه ونستغفره ونعوذ باللہ من شرور أنفسنا وسيئات أعمالنا من يهده اللہ فلا مضل له ومن يضلل فلا هادي له وأشهد أن لا إله إلا اللہ وأشهد أن محمدا عبده ورسوله» \"تمام تعریفیں اللہ کے لیے ہیں، ہم اسی سے مدد اور گناہوں کی بخشش چاہتے ہیں، اور ہم اپنے نفسوں کی شر انگیزیوں اور اپنے اعمال کی برائیوں سے اللہ تعالی کی پناہ چاہتے ہیں، جسے اللہ تعالی ہدایت دیدے اسے کوئی گمراہ نہیں کر سکتا، اور جسے وہ گمراہ کر دے اسے کوئی ہدایت نہیں دے سکتا، اور میں گواہی دیتا ہوں کہ نہیں ہے کوئی حقیقی معبود سوائے اللہ کے، اور میں گواہی دیتا ہوں کہ محمد اس کے بندے اور رسول ہیں\"، پھر آپ یہ تین آیتیں پڑھتے: «يا أيها الذين آمنوا اتقوا اللہ حق تقاته ولا تموتن إلا وأنتم مسلمون» \"اے ایمان والو! اللہ تعالی سے اتنا ڈرو جتنا کہ اس سے ڈرنا چاہیئے، اور دیکھو مرتے دم تک مسلمان ہی رہنا\" (آل عمران: ۱۰۲)۔ «يا أيها الناس اتقوا ربكم الذي خلقكم من نفس واحدة وخلق منها زوجها وبث منهما رجالا كثيرا ونساء واتقوا اللہ الذي تساءلون به والأرحام إن اللہ كان عليكم رقيبا» \"اے لوگو! اپنے رب سے ڈرو جس نے تمہیں ایک جان سے پیدا کیا، اور اسی سے اس کا جوڑا پیدا کیا، اور ان دونوں سے بہت سے مرد اور عورتیں پھیلا دیں، اور اس اللہ سے ڈرو جس کے نام پر تم ایک دوسرے سے مانگتے ہو، اور رشتے ناطے توڑنے سے بھی بچو، بیشک اللہ تعالی تم پر نگہبان ہے\" (الاحزاب: ۷۰) «يا أيها الذين آمنوا اتقوا اللہ وقولوا قولا سديدا» \"اے ایمان والو! اللہ سے ڈرو اور صحیح و درست بات کہو\" (النساء: ۱)۔ ابوعبدالرحمٰن (نسائی) کہتے ہیں: ابوعبیدہ نے اپنے والد عبداللہ بن مسعود رضی اللہ عنہ سے نہیں سنا ہے، نہ ہی عبدالرحمٰن بن عبداللہ ابن مسعود نے، اور نہ ہی عبدالجبار بن وائل بن حجر نے، (یعنی ان تینوں کا اپنے والد سے سماع نہیں ہے)۔\n§وضاحت\n۱؎: حاجۃ کا لفظ عام ہے نکاح اور بیع وغیرہ سبھی چیزوں کو شامل ہے، اسی وجہ سے امام شافعی نے بیع و نکاح وغیرہ تمام عقود میں اس خطبہ کے پڑھنے کو مسنون قرار دیا ہے۔ نسائی کی اس سند میں بھی ابوعبیدہ ہیں، مگر ابوداؤد اور دیگر کی سندوں میں \"ابو عبیدہ\" کی جگہ ابوالاحوص ہیں، جن کا سماع ابن مسعود رضی اللہ عنہ سے ثابت ہے۔","الألباني: صحيح",{"u2":"حضرت عبداللہ بن مسعود رضی اللہ عنہ سے منقول ہے کہ نبی صلی اللہ علیہ وسلم نے ہمیں ضرورت کے موقع پر (یوں) خطبہ سکھایا: [الحمد للہ نستعینہ و نستغفرہ ……… ورسولہ] ’’ہر تعریف اللہ تعالیٰ کے لیے ہے۔ ہم اس سے مدد طلب کرتے ہیں اور اس سے بخشش طلب کرتے ہیں۔ اور اپنے نفس کی شرارتوں اور اپنے اعمال کی خرابیوں سے اللہ تعالیٰ کی پناہ چاہتے ہیں۔ جس شخص کو اللہ تعالیٰ ہدات دے، کوئی اسے گمراہ کرنے والا نہیں اور جسے وہ گمراہ کرے دے، اسے کوئی ہدایت دینے والا نہیں۔ اور میں گواہی دیتا ہوں کہ اللہ تعالیٰ کے سوا کوئی (سچا) معبود نہیں اور میں گواہی دیتا ہوں کہ حضرت محمد (صلی اللہ علیہ وسلم) اس کے بندے اور رسول ہیں۔‘‘ پھر آپ تین آیات پڑھتے: (یایھا الذین امنوا ……… وانتم مسلمون) ’’اے ایمان والو! اللہ تعالیٰ سے ڈرو جیسے اس سے ڈرنے کا حق ہے اور تمھیں جب بھی موت آئے، اسلام ہی کی حالت میں آئے۔‘‘ (یایھا الناس اتقوا ……… ان اللہ کان علیکم رقیبا) ’’اے لوگو! اپنے رب سے ڈرو جس نے تمھیں ایک جان (حضرت آدم علیہ السلام) سے پیدا کیا اور اسی سے اس کی بیوی (حضرت حواء علیہا السلام) کو پیدا کیا اور ان دونوں سے بہت سے مرد اور عورتیں پھیلا دیے۔ اور اللہ تعالیٰ سے ڈرو جس کے واسطے سے تم ایک دوسرے سے سوال کرتے ہو اور رشتے توڑنے سے ڈرو۔ یقیناً اللہ تعالیٰ تم پر نگران ہے۔‘‘ (یایھا الذین امنوا اتقوا اللہ وقولوا قولا سدیدا) ’’اے ایمان والو! اللہ تعالیٰ سے ڈرو اور سیدھی سچی بات کرو۔‘‘\nامام ابو عبدالرحمٰن (نسائی) رحمہ اللہ بیان کرتے ہیں کہ حضرت عبیدہ نے اپنے والد محترم (حضرت عبداللہ بن مسعود رضی اللہ عنہ) سے کوئی روایت نہیں سنی اور اسی طرح حضرت عبدالرحمٰن بن عبداللہ بن مسعود نے بھی اپنے والد محترم سے کوئی روایت نہیں سنی۔ اس طرح عبدالجبار بن وائل نے بھی اپنے والد محترم (حضرت وائل بن حجر رضی اللہ عنہ) سے کوئی روایت نہیں سنی۔","f2":"(۱) مذکورہ روایت سند کے لحاظ سے منقطع ہے۔ محقق کتاب نے بھی اسے سنداً ضعیف قرار دیا ہے جبکہ دیگر محققین نے اسے دیگر شواہد کی بنا پر صحیح قرار دیا ہے۔ دلائل کی رو سے راجح اور درست بات یہی ہے کہ مذکورہ روایت شواہد کی بنا پر قابل عمل اور قابل حجت ہے۔ واللہ أعلم۔ مزید تفصیل کے لیے دیکھیے: (خطبۃ الحاجۃ لشیخ ناصر الدین الألباني، وذخیرۃ العقبی، شرح سنن النسائي: ۲۳۸،۲۳۷/۱۶) (۲) متعلقہ حدیث میں تو صرف ابوعبیدہ کا ذکر ہے۔ باقی دو حضرات کا ذکر بالقبع کر دیا گیا ہے کیونکہ تینوں بزرگ اس بات میں شریک ہیں کہ انھوں نے اپنے والد سے کچھ نہیں سنا۔ تینوں کے والد صحابی ہیں۔ (۳) ’’ضرورت کے موقع پر‘‘ یعنی جب بھی خطبے کی ضرورت ہو، خواہ وعظ ہو یا نکاح یا کچھ اور۔ اسی وجہ سے امام نسائی رحمہ اللہ اس روایت کو خطبۂ جمعہ میں لائے ہیں کیونکہ یہ بھی ایک حاجت اور ضرورت ہے۔ بعض حضرات نے مذکورہ آیات کی مناسبت سے یہاں حاجت نکاح مراد لی ہے۔ استاد محترم حضرت الحافظ محمد گوندلوی محدث رحمہ اللہ درس بخاری کے پغاز میں یہی خطبہ پڑھا کرتے تھے۔ ان آیات میں تقوے کا حکم ہے اور تقویٰ ہر کام میں ضروری ہے، نہ کہ صرف نکاح میں۔ واللہ أعلم۔ (۴) ’’جسے وہ گمراہ کر دے‘‘ اللہ تعالیٰ کسی کو اپنی طرف سے گمراہ نہیں کرتا بلکہ اللہ تعالیٰ کے گمراہ کرنے کا مطلب یہ ہے کہ اللہ تعالیٰ گمراہ کو گمراہی سے زبردستی نہیں روکتا بلکہ وہ اپنی مرضی سے جس طرف جاتا ہے، جانے دیتا ہے کیونکہ ہر چیز کا خالق اللہ تعالیٰ ہی ہے، اسی لیے اس کا انتاسب بھی اسی کی طرف کر دیا جاتا ہے، ورنہ درحقیقت اس میں انسان کے اپنے اس ارادے و اختیار کا دخل ہوتا ہے جس سے اللہ تعالیٰ نے بطور امتحان انسان کو نوازا ہے۔"}],[1405,"عبداللہ بن عمر رضی اللہ عنہم کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے خطبہ دیا تو آپ صلی اللہ علیہ وسلم نے فرمایا: \"جب تم میں سے کوئی جمعہ کے لیے جائے تو اسے چاہیئے کہ غسل کر لے\"۔","الألباني: صحيح",{"u2":"حضرت ابن عمر رضی اللہ عنہما سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے خطبہ دیا، اس میں فرمایا: ’’جب تم میں سے کوئی شخص جمعے کے لیے جائے تو وہ غسل کرے۔‘‘"}],[1406,"ابراہیم بن نشیط سے روایت ہے کہ انہوں نے ابن شہاب زہری سے جمعہ کے دن کے غسل کے بارے میں سوال کیا تو انہوں نے کہا: سنت ہے، اور اسے مجھ سے سالم بن عبداللہ نے بیان کیا ہے، اور انہوں نے اپنے والد (عبداللہ بن عمر رضی اللہ عنہم) سے روایت کی ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے اسے منبر پر بیان کیا ہے۔","الألباني: صحيح الإسناد",{"u2":"ابراہیم بن نشیط نے حضرت ابن شہاب زہری سے جمعے کے دن غسل کرنے کے بارے میں پوچھا تو انھوں نے کہا: سنت ہے اور مجھے یہ بات حضرت سالم نے اپنے والد محترم سے بیان کی کہ اللہ کے رسول صلی اللہ علیہ وسلم نے یہ بات منبر پر ارشاد فرمائی۔"}],[1407,"عبداللہ بن عمر رضی اللہ عنہم کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے منبر پر کھڑے کھڑے فرمایا: \"جو شخص تم میں سے جمعہ کے لیے آئے تو چاہیئے کہ وہ غسل کر لے\"۔ ابوعبدالرحمٰن (نسائی) کہتے ہیں: میں کسی کو نہیں جانتا جس نے اس سند پر لیث کی متابعت کی ہو سوائے ابن جریج کے، اور زہری کے دیگر تلامذہ «عن عبداللہ بن عبداللہ بن عمر» کے بدلے «سالم بن عبداللہ عن أبيه» کہتے ہیں۔","الألباني: صحيح",{"u2":"حضرت عبداللہ بن عمر رضی اللہ عنہما سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے منبر پر ارشاد فرمایا: ’’تم میں سے جو شخص جمعے کے دن آئے، وہ غسل کرے۔‘‘\nامام ابو عبدالرحمٰن (نسائی) رحمہ اللہ بیان کرتے ہیں کہ میں نہیں جانتا کہ حضرت ابن جریج کے علاوہ کسی راوی نے اس سند کے بیان میں حضرت لیث کی متابعت (موافقت) کی ہو۔ امام زہری کے دوسرے شاگرد عبداللہ بن عمر کی بجائے سالم بن عبداللہ عن ابیہ کہتے ہیں۔","f2":"(۱) یہ روایت امام زہری سے بیان کرنے والے بہت سے راوی ہیں، جیسے ابراہیم بن نشیط، محمد بن ولید زبیدی، سفیان بن عینیہ اور ابن جریج۔ یہ سب امام زہری کا استاد حضرت سالم بن عبداللہ بن عمر بتاتے ہیں۔ صرف حضرت لیث اور ابن جریج نے ان کا استاد عبداللہ بن عبداللہ بن عمر بتایا ہے۔ دیگر شاگردان کی طرح ابن جریج امام زہری کا استاد سالم بھی بتاتے ہیں۔ اس طرح وہ جمہور تلامذہ کی موافقت بھی کرتے ہیں۔ غرضیکہ مذکورہ کلام سے امام نسائی رحمہ اللہ امام لیث کی، جن پر ابن جریج نے بھی ان کی موافقت کی ہے، روایت کی تضعیف نہیں فرما رہے، بلکہ ان کا مقصد صرف ذکر اختلاف ہے کیونکہ امام لیث رحمہ اللہ ثقہ اور ثبت (انتہائی قابل اعتماد) ہیں۔ گویا یہ اختلاف ثقہ راوی کی زیادتی کے قبیل سے ہے جو کہ محدثین کے نزدیک سبب ضعف میں سے نہیں، اس سے معلوم ہوا کہ یہ روایت میں امام زہری کے دو شیخ ہیں، سالم اور عبداللہ بن عبداللہ۔ امام مسلم رحمہ اللہ نے بھی اپنی صحیح میں دونوں شیوخ کے واسطے سے روایت نقل کی ہے۔ مزید تفصیل کے لیے ملاحظہ فرمائیے: (ذخیرۃ العقبی شرح سنن النسائ: ۲۴۲/۱۶) الحاصل: یہاں کثرت رواۃ کی بنا پر ترجیح نہیں بلکہ تطبیق ہی درست ہے۔ واللہ أعلم۔ (۲) جمعے کے دن غسل کی بحث کے لیے دیکھیے، حدیث: ۱۳۷۶، ۱۳۷۷ اور اسی کتاب کا ابتدائیہ۔"}],[1408,"ابو سعید خدری رضی اللہ عنہ کہتے ہیں کہ جمعہ کے دن جب نبی اکرم صلی اللہ علیہ وسلم خطبہ دے رہے تھے، تو ایک آدمی خستہ حالت میں (مسجد میں) آیا اس سے رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"کیا تم نے نماز پڑھی؟\" اس نے عرض کیا: نہیں، آپ نے فرمایا: \"دو رکعتیں پڑھ لو\"، اور آپ نے (دوران خطبہ) لوگوں کو صدقہ پر ابھارا، لوگوں نے صدقہ میں کپڑے دیئے، تو آپ صلی اللہ علیہ وسلم نے ان میں سے دو کپڑے اس شخص کو دیے، پھر جب دوسرا جمعہ آیا تو وہ شخص پھر آیا، اس وقت بھی رسول اللہ صلی اللہ علیہ وسلم خطبہ دے رہے تھے، آپ نے لوگوں کو پھر صدقہ پر ابھارا، تو اس شخص نے بھی اپنے کپڑوں میں سے ایک کپڑا ڈال دیا، تو رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"یہ شخص (پچھلے) جمعہ کو بڑی خستہ حالت میں آیا، تو میں نے لوگوں کو صدقے پر ابھارا، تو انہوں نے صدقے میں کپڑے دیئے، میں نے اس میں سے دو کپڑے اس شخص کو دینے کا حکم دیا، اب وہ پھر آیا تو میں نے پھر لوگوں کو صدقے کا حکم دیا تو اس نے بھی اپنے دو کپڑوں میں سے ایک کپڑا صدقہ میں دے دیا\"، پھر آپ نے اسے ڈانٹا اور فرمایا: \"اپنا کپڑا اٹھا لو\" ۱؎۔\n§وضاحت\n۱؎: رسول اللہ صلی اللہ علیہ وسلم نے اس کا صدقہ قبول نہیں کیا کیونکہ اس کے پاس صرف دو ہی کپڑے تھے جو اس کی ضرورت سے زائد نہیں تھے۔","الألباني: حسن",{"u2":"حضرت ابوسعید خدری رضی اللہ عنہ بیان کرتے ہیں کہ جمعے کے دن ایک آدمی فقیرانہ حالت میں آیا جب کہ نبی صلی اللہ علیہ وسلم خطبہ دے رہے تھے۔ آپ نے اس سے پوچھا: ’’تو نے نماز پڑھی ہے؟‘‘ اس نے کہا: نہیں، آپ نے فرمایا: ’’دو رکعتیں پڑھ۔‘‘ پھر آپ نے لوگوں کو صدقہ کرنے کی رغبت دلائی۔ لوگوں نے (صدقے میں) کپڑے دینے شروع کیے تو آپ نے اسے ان میں سے دو کپڑے دیے۔ جب دوسرا جمعہ ہوا تو وہ پھر آیا۔ اس وقت بھی آپ خطبہ ارشاد فرما رہے تھے۔ آپ نے پھر لوگوں کو صدقے کی طرف رغبت دلائی تو اس نے بھی اپنا ایک کپڑا اتار دیا۔ آپ نے فرمایا: ’’یہ پچھلے جمعے کو پراگندہ حالت میں آیا تھا تو میں نے لوگوں کو صدقے کا حکم دیا۔ لوگوں نے اپنے (زائد) کپڑے صدقے میں دیے۔ میں نے اسے دو کپڑے دینے کا حکم دیا۔ اب یہ پھر آیا تو میں نے لوگوں کو پھر صدقے کا حکم دیا تو اس نے بھی انھی دو کپڑوں میں سے ایک کپڑا اتار کر دے دیا۔ پھر آپ نے اسے ڈانٹا اور فرمایا: ’’اٹھالے اپنا کپڑا۔‘‘","f2":"(۱) آپ نے خطبے میں صدقے کی رغبت اس آنے والے شخص کی وجہ سے نہیں دلائی تھی بلکہ یہ تو آپ کے خطبے کا حصہ تھا۔ بعد میں اس کی فقیرانہ حالت کے پیش نظر اس کو بھی دوسرے فقراء کے ساتھ دو کپڑے دے دیے گئے۔ احناف کہتے ہیں: ’’آپ نے اسے دو رکعت پڑھنے کا حکم اس لیے دیا تھا کہ لوگ اس کی خستہ حالت دیکھ کر اس پر صدقہ کریں، لہٰذا دو رکعت پڑھنے کا حکم عام نہیں بلکہ اس کے ساتھ خاص تھا‘‘ حالانکہ اگر ایسے ہوتا تو پھر سب کپڑے اور صدقہ اسی کو ملنا چاہیے تھا، نیز الگ سے بھی ان دو رکعتوں کا حکم آیا ہے۔ (۲) امام کو اپنے مقتدیوں کے حال احوال کا خیال رکھنا چاہیے۔ (۳) جس چیز کی آدمی کو خود شدید ضرورت ہو، اس کا صدقہ نہیں کرنا چاہیے۔"}],[1409,"جابر بن عبداللہ رضی اللہ عنہم کہتے ہیں کہ جمعہ کے دن نبی اکرم صلی اللہ علیہ وسلم خطبہ دے رہے تھے کہ اسی دوران ایک آدمی آیا ۱؎ (اور بیٹھ گیا) تو آپ صلی اللہ علیہ وسلم نے اس سے کہا: \"تم نے سنت پڑھ لی؟\"، اس نے کہا: نہیں، آپ نے فرمایا: \"کھڑے ہو جاؤ اور (سنت) پڑھو\"۔\n§وضاحت\n۱؎: یہ سلیک غطفانی تھے جیسا کہ ابوداؤد کی حدیث میں اس کی صراحت موجود ہے۔","الألباني: صحيح",{"u2":"حضرت جابر بن عبداللہ رضی اللہ عنہما بیان کرتے ہیں کہ ایک دفعہ نبی صلی اللہ علیہ وسلم جمعے کے دن خطبہ دے رہے تھے کہ ایک آدمی آیا۔ نبی صلی اللہ علیہ وسلم نے اس سے فرمایا: ’’تو نے نماز پڑھی ہے؟‘‘ اس نے کہا: نہیں۔ آپ نے فرمایا: ’’اٹھ اور (دو رکعتیں) پڑھ۔‘‘"}],[1410,"ابوبکرہ رضی اللہ عنہ کہتے ہیں کہ میں نے رسول اللہ صلی اللہ علیہ وسلم کو منبر پر دیکھا، حسن رضی اللہ عنہ آپ کے ساتھ تھے، آپ کبھی لوگوں کی طرف متوجہ ہوتے، تو کبھی ان کی طرف، اور آپ فرما رہے تھے: \"میرا یہ بچہ سردار ہے، اور شاید اللہ تعالی اس کے ذریعہ سے مسلمانوں کے دو بڑے گروہوں میں صلح کرا دے\" ۱؎۔\n§وضاحت\n۱؎: الحمدللہ نبی اکرم صلی اللہ علیہ وسلم کی یہ پیش گوئی سچ ثابت ہوئی اور امت مسلمہ کے دو گروہ باہم متفق ہو گئے ہوا یہ کہ حسن رضی اللہ عنہ نے خلافت سے دستبرداری فرمائی اور ساری امت معاویہ رضی اللہ عنہ کی امارت پر متفق ہو گئے۔","الألباني: صحيح",{"u2":"حضرت ابوبکر رضی اللہ عنہ بیان کرتے ہیں کہ میں نے رسول اللہ صلی اللہ علیہ وسلم کو منبر پر (خطبہ دیتے) دیکھا جب کہ حضرت حسن رضی اللہ عنہ بھی آپ کے ساتھ تھے۔ آپ کبھی لوگوں کی طرف متوجہ ہوتے اور کبھی اس کی طرف۔ آپ فرما رہے تھے: ’’یقیناً میرا یہ بیٹا سردار ہوگا، قوی امید ہے کہ اللہ تعالیٰ اس کے ذریعے سے مسلمانوں کی دو بڑی جماعتوں کے درمیان صلح کروائے گا۔‘‘","f2":"(۱) رسول اللہ صلی اللہ علیہ وسلم کی یہ پیش گوئی حرف بحرف پوری ہوئی۔ والحمد للہ علی ذالک۔ حضرت حسن، حضرت علی رضی اللہ عنہما کی شہادت کے بعد خلیفہ (سردار) بنائے گئے۔ آپ نصف اسلامی مملکت کے سربراہ تھے۔ ہزاروں کی تعداد میں فوج آپ کے ساتھ تھی۔ چالیس ہزار افراد آپ کے ہاتھ پر موت کی بیعت کرچکے تھے۔ دوسری طرف حضرت معاویہ رضی اللہ عنہ اور ان کی فوج تھی۔ حضرت حسن رضی اللہ عنہ نے خون ریزی کو اچھا نہ سمجھا اور صلح کا عندیہ دیا۔ حضرت معاویہ رضی اللہ عنہ نے بھی سفید کاغذ بھیج دیا کہ جو شرائط آپ طے فرمائیں، لکھ دیں۔ میرے دستخط پہلے ہی ہوچکے ہیں۔ اس طرح حضرت حسن رضی اللہ عنہ نے حکومت کی قربانی دے کر امت کے ان دو عظیم گروہوں کو لڑائی سے بچا لیا۔ رضی اللہ عنہ و أرضاہ۔ ورنہ کشتوں کے پشتے لگ جاتے اور معاملہ پھر بھی حل نہ ہوتا۔ حضرت حسن رضی اللہ عنہ کا امت پر یہ عظیم احسان ہے جس کا بدلہ اللہ تعالیٰ ہی انھیں دے گا کہ وہ جنت میں نوجوانوں کے سردار ہوں گے۔ صحابہ کے درمیان ہونے والی لڑائیوں کے بارے میں اہل علم نے خاموشی اختیار فرمائی ہے کہ ہمیں بزرگوں کے بکھیڑے میں نہیں پڑنا چاہیے۔ کسی میں غلطی اور نقص نکال کر اپنی زبانوں کو گستاخی اور گناہ سے آلودہ نہیں کرنا چاہیے۔ یہ مغفورلھم لوگ تھے۔ انھیں جنت کی خوش خبری سچے رسول صلی اللہ علیہ وسلم کی زبان سے مل چکی ہے۔ ہم کون ہیں اور ان کی عیب جوئی کرنے والے۔ پھر اس دور کی صحیح تاریخ کا ملنا بھی یقینی نہیں، لہٰذا یہ معاملات اللہ خبیر و بصیر پر چھوڑ دیے جائیں۔ یہی بات برحق ہے۔ (۲) خوارج کا رد ہے جو کہ دونوں گروہوں کو کافر کہتے ہیں۔ نبیٔ اکرم صلی اللہ علیہ وسلم نے دونوں گروہوں کے مسلمان ہونے کی گواہی دی ہے۔ (۳) لوگوں کے درمیان اصلاح بہت فضیلت والا کام ہے، خصوصاً جب خون خرابہ ہونے کا خطرہ ہو۔ (۴) حضرت معاویہ رضی اللہ عنہ رعایا پر بہت شفیق اور مہربان تھے، نیز امور مملکت میں بڑی کڑی نظر رکھتے تھے۔ آپ کا صلح کا غیر مشروط مطالبہ اس بات کی بین دلیل ہے۔ (۵) کم مرتبے والا شخص، زیادہ فضیلت والے کی موجودگی میں حکمران بن سکتا ہے۔ حضرت حسن اور معاویہ رضی اللہ عنہما حکمران بنے جبکہ حضرت سعد بن ابی وقاص اور سعید بن زید رضی اللہ عنہما بدری صحابہ موجود تھے۔ (۶) خلیفہ بذات خود دستبردار ہوسکتا ہے خصوصاً جبکہ یہ استغفیٰ وسیع تر قومی و ملی مفاد میں ہو۔"}],[1411,"حارثہ بن نعمان رضی اللہ عنہ کی بیٹی (ام ہشام) کہتی ہیں کہ میں نے «ق والقرآن المجيد» کو جمعہ کے دن منبر پر رسول اللہ صلی اللہ علیہ وسلم کے منہ سے سن سن کر یاد کیا ۱؎۔\n§وضاحت\n۱؎: اس سے ثابت ہوتا ہے کہ رسول اللہ صلی اللہ علیہ وسلم جمعہ کے خطبے میں پوری سورۃ ق پابندی سے پڑھا کرتے تھے۔","الألباني: صحيح",{"u2":"حضرت حارثہ بن نعمان رضی اللہ عنہ کی بیٹی ام ہشام رضی اللہ عنہا بیان کرتی ہیں کہ میں نے سورۂ (قo والقرآن المجید) جمعے کے دن منبر پر رسول اللہ صلی اللہ علیہ وسلم کی زبان مبارک سے سن سن کر یاد کی۔‘‘","f2":"(۱) یعنی رسول اللہ صلی اللہ علیہ وسلم ہمیشہ یا اکثر جمعے کے دن خطبے میں یہ سورت مکمل پڑھتے۔ اس کی وجہ یہ ہے کہ اس سورت میں بعث بعد الموت، ذکر موت اور وعظ و زجر بڑے مؤثر پیرائے میں بیان کیے گئے ہیں۔ صوتی آہنگ اس پر مستزاد ہے۔ چھوٹی چھوٹی آیات ہیں۔ توجہ سے پڑھی جائیں تو دل کی دنیا بدل جاتی ہے۔ (۲) امام شافعی رحمہ اللہ کے نزدیک جمعے کے ہر خطبے میں پانچ چیزیں ضرور ہونی چاہییں: حمد باری تعالیٰ، نبی صلی اللہ علیہ وسلم پر درود، قراءت قرآن، وعظ اور دعا، ورنہ خطبہ ناقص ہوگا۔ رسول اللہ صلی اللہ علیہ وسلم کا عمل اس کی تائید کرتا ہے۔"}],[1412,"حصین سے روایت ہے کہ بشر بن مروان نے جمعہ کے دن منبر پر (خطبہ دیتے ہوئے) اپنے دونوں ہاتھوں کو اٹھایا، تو اس پر عمارہ بن رویبہ ثقفی رضی اللہ عنہ نے انہیں برا بھلا کہا، اور کہا: رسول اللہ صلی اللہ علیہ وسلم نے اس سے زیادہ نہیں کیا، اور انہوں نے اپنی شہادت کی انگلی سے اشارہ کیا۔","الألباني: صحيح",{"u2":"حضرت حصین سے روایت ہے کہ بشر بن مروان نے جمعے کے دن منبر پر (جوش خطابت میں) دونوں ہاتھ اٹھائے تو حضرت عمارہ بن رویبہ ثقفی رضی اللہ عنہ نے اسے ڈانٹا اور فرمایا: رسول اللہ صلی اللہ علیہ وسلم اس سے زائد اشارہ نہیں کرتے تھے، پھر انھوں نے اپنے دائیں ہاتھ کی انگشت شہادت سے اشارہ کیا۔","f2":"(۱) جمعے کا خطبہ عبادت ہے، اس میں سنجیدگی ضروری ہے دونوں ہاتھوں کو اٹھانا سنیجدگی کے خلاف ہے، تقریر میں ایک ہاتھ یا انگلی سے اشارہ کافی ہے۔ بعض نے اس سے دوران خطبہ دعا کے لیے ہاتھ اٹھانا مراد لیا ہے، حالانکہ بعض روایات میں خطبۂ جمعہ کے دوران میں بارش کی دعا کے لیے نبی صلی اللہ علیہ وسلم کا ہاتھ اٹھا کر اور آپ کے ساتھ سامعین کا ہاتھ اٹھا کر دعا کرنا منقول ہے۔ (صحیح البخاري، الاستسقاء، حدیث: ۱۰۲۹)، ہاں یہ کہا جا سکتا ہے کہ معمول نہ بنایا جائے۔ کبھی کبھار اہم موقع پر ہاتھ اٹھا لیے جائیں تو کوئی حرج نہیں۔ (۲) خلاف سنت کام کرنے والے کو روکنا چاہیے اگرچہ وہ بڑی وجاہت والا اور چودھری یا وڈیرا آدمی ہو۔ ایک مسلمان کے اوصاف میں سے ہے کہ وہ اللہ کے احکام کے بارے میں کسی ملامت گر کی ملامت سے نہیں ڈرتا۔"}],[1413,"بریدہ رضی اللہ عنہ کہتے ہیں کہ نبی اکرم صلی اللہ علیہ وسلم خطبہ دے رہے تھے اتنے میں حسن اور حسین رضی اللہ عنہم لال رنگ کی قمیص پہنے گرتے پڑتے آئے، آپ صلی اللہ علیہ وسلم (منبر سے) اتر پڑے، اور اپنی بات بیچ ہی میں کاٹ دی، اور ان دونوں کو گود میں اٹھا لیا، پھر منبر پر واپس آ گئے، پھر فرمایا: \"اللہ تعالی نے سچ کہا ہے «إنما أموالكم وأولادكم فتنة» \"تمہارے مال اور اولاد فتنہ ہیں\" میں نے ان دونوں کو ان کی قمیصوں میں گرتے پڑتے آتے دیکھا تو میں صبر نہ کر سکا یہاں تک کہ میں نے اپنی گفتگو بیچ ہی میں کاٹ دی، اور ان دونوں کو اٹھا لیا\"۔","الألباني: صحيح",{"u2":"حضرت بریدہ رضی اللہ اللہ عنہ بیان کرتے ہیں کہ ایک دفعہ نبی صلی اللہ علیہ وسلم (بروز جمعہ) خطبہ ارشاد فرما رہے تھے کہ حضرت حسن و حسین رضی اللہ عنہما آگئے۔ انھوں نے سرخ رنگ کی (لمبی) قمیصیں پہن رکھی تھیں۔ وہ ان میں لڑکھڑا رہے تھے۔ نبی صلی اللہ علیہ وسلم نے اپنا خطبہ روک دیا اور منبر سے نیچے اتر کر ان دونوں کو اٹھایا، پھر منبر پر تشریف فرما ہوگئے اور فرمایا: ’’اللہ تعالیٰ نے سچ فرمایا ہے: (انما اموالکم واولادکم فتنۃ) ’’بلاشبہ تمھارے اموال اور تمھاری اولاد فتنہ ہیں۔‘‘ میں نے انھیں دیکھا کہ قمیصوں میں لڑکھڑاتے (گرتے پڑتے) آ رہے ہیں۔ میں صبر نہ کر سکا حتی کہ میں نے خطبہ روکا اور انھیں اٹھایا۔‘‘","f2":"(۱) إنصات کا حکم مقتدیوں کے لیے ہے۔ امام صاحب خطبۂ جمعہ کے دوران میں کی کے ساتھ بات چیت بھی کرسکتے ہیں اور کوئی ضروری کام بھی کرسکتے ہیں۔ اگر نبی صلی اللہ علیہ وسلم انھیں نہ اٹھاتے تو آپ کی توجہ انھی کی طرف مبذول رہتی۔ خطبہ تو پھر بھی منقطع ہونا ہی تھا، اس لی آپ نے مناسب نہ سمجھا کہ وہ بار بار گرتے اٹھتے رہیں۔ پ نے نبوی شفقت اور اپنی شان رحیمی کو عمل میں لاتے ہوئے خطبہ منقطع فرمایا، انھیں اٹھایا اور پھر خطبہ شروع کر دیا۔ پ کا اس آیت کریمہ کا تلاوت فرمانا یہ عنی نہیں رکھتا کہ میں نے جو بچوں کو اٹھایا ہے، وہ غلط کام کیا ہے کیونکہ یہ کام تو عین تقاضائے شفقت و رحمت ہے۔ اگر نہ اٹھاتے تو مناسب نہ ہوتا، بلکہ اس آیت کریمہ کو تلاوت فرمانے کا مقصد یہ ہے کہ انسان اس آزمائش میں پورا اترے اور اس کے ساتھ ساتھ گمراہ بھی نہ ہو، حقوق اللہ میں کوتاہی نہ کرے اور ان کے حقوق میں بھی سستی نہ کرے۔ جس طرح رسول اللہ صلی اللہ علیہ وسلم نے اس موقع پر بہترین نمونہ پیش فرمایا۔ صلی اللہ علیہ وسلم۔ (۲) کسی شدید ضرورت کے پیش نظر خطبے کا تسلسل توڑ دینا، منبر سے اترنا، موضوع سے ہٹ کر کوئی اور بات کر لینا اور پھر جہاں سے چھوڑا وہیں سے خطبہ شروع کر لینا جائز ہے۔"}],[1414,"عبداللہ بن ابی اوفی رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم ذکرو اذکار زیادہ کرتے، لایعنی باتوں سے گریز کرتے، نماز لمبی پڑھتے، اور خطبہ مختصر دیتے تھے، اور بیواؤں اور مسکینوں کے ساتھ جانے میں کہ ان کی ضرورت پوری کریں، عار محسوس نہیں کرتے تھے۔","الألباني: صحيح",{"u2":"حضرت عبداللہ بن ابی اوفی رضی اللہ عنہ سے منقول ہے کہ رسول اللہ صلی اللہ علیہ وسلم کثرت سے ذکر کرتے تھے اور ضرورت سے زائد کلام کم ہی کرتے تھے۔ نماز لمبی پڑھتے تھے اور خطبہ مختصر رکھتے تھے۔ اور اس بات میں کوئی بے عزتی محسوس نہ فرماتے تھے کہ کسی بے سہارا اور بیوہ خاتون اور مسکین شخص کے ساتھ جاکر اس کا کام کر دیں۔","f2":"(۱) ’’کم ہی کرتے تھے‘‘ کہا گیا ہے کہ اس سے نفی مراد ہے، یعنی آپ بلاضرورت کلام نہیں کرتے تھے۔ عربی کا لفظ لغو استعمال ہوا ہے، لغو کے کئی معانی ہیں: گناہ والے کلام کو لغو کہتے ہیں اور بالضرورت کلام کو بھی لغو کہتے ہیں۔ آخری معنی ہوں تو ’’کم‘‘ والے معنی بھی صحیح ہیں۔ پہلے معنی کے لحاظ سے نفی والے معنی ہی صحیح ہیں۔ (۲) نماز اور خطبے کا آپس میں تقابل نہیں بلکہ نمازوں سے لمبی نماز اور خطبوں میں سے مختصر خطبہ مراد ہے۔ خطبہ ایسا نہ ہو جو سامعین کے لیے اکتاہٹ اور دل کی تنگی کا سبب ہو۔ (۳) أرملۃ محتاج اور بے سہارا بیوہ ہی کو کہا جاتا ہے۔ مالدار بیوہ کو أرملۃ نہیں کہا جاتا۔"}],[1415,"جابر بن سمرہ رضی اللہ عنہ کہتے ہیں کہ میں نے نبی اکرم صلی اللہ علیہ وسلم کی ہم نشینی کی، تو میں نے آپ کو کھڑے ہو کر ہی خطبہ دیتے دیکھا، آپ بیچ میں بیٹھتے، پھر کھڑے ہوتے، اور دوسرا خطبہ دیتے۔","الألباني: صحيح",{"u2":"حضرت جابر بن سمرہ رضی اللہ عنہ سے روایت ہے کہ میں نبی صلی اللہ علیہ وسلم کے ساتھ بیٹھتا رہا ہوں۔ میں نے کبھی آپ کو خطبہ دیتے نہیں دیکھا مگر کھڑے ہوکر ہی۔ آپ درمیان میں بیٹھتے، پھر دوبارہ کھڑے ہوتے اور دوسرا خطبہ ارشاد فرماتے","f2":"(۱) جمعہ میں دو خطبے مسنون ہیں اور یہ متفقہ بات ہے۔ بعض نے عیدین کو بھی جمعے پر قیاس کیا ہے لیکن راجح بات یہی ہے کہ عیدین کا ایک ہی خطبہ ہے، عام روایات سے اسی کی تائید ہوتی ہے۔ دو خطبوں کی روایات ضعیف ہیں، نیز احادیث کے عموم کی روشنی میں عیدین کا جمعے پر قیاس درست نہیں۔ واللہ أعلم۔ (۲) ثابت ہوا کہ خطبہ کھڑے ہوکر دینا سنت ہے۔ کسی شرعی عذر کے بغیر بیٹھ کر خطبہ دینا درست نہیں۔ (۳) دو خطبوں کے درمیان بیٹھنا مسنون ہے جیسا کہ آئندہ حدیث میں آ رہا ہے۔ (۴) خطبہ مختصر ہونا چاہیے جیسے کہ پیچھے گزرا۔"}],[1416,"عبداللہ بن عمر رضی اللہ عنہم سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم کھڑے ہو کر دو خطبے دیتے تھے، ان دونوں کے بیچ میں بیٹھ کر فصل کرتے تھے۔","الألباني: صحيح",{"u2":"حضرت عبداللہ بن عمر رضی اللہ عنہما سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم کھڑے ہوکر دو خطبے ارشاد فرماتے تھے اور درمیان میں بیٹھتے تھے۔"}],[1417,"جابر بن سمرہ رضی اللہ عنہ کہتے ہیں کہ میں نے رسول اللہ صلی اللہ علیہ وسلم کو جمعہ کے دن کھڑے ہو کر خطبہ دیتے دیکھا، پھر آپ کچھ دیر چپ چاپ بیٹھتے پھر کھڑے ہوتے اور دوسرا خطبہ دیتے، جو تم سے بیان کرے کہ رسول اللہ صلی اللہ علیہ وسلم بیٹھ کر خطبہ دیتے تھے تو وہ غلط گو جھوٹا ہے۔","الألباني: حسن",{"u2":"حضرت جابر بن سمرہ رضی اللہ عنہ بیان کرتے ہیں کہ میں نے دیکھا کہ رسول اللہ صلی اللہ علیہ وسلم جمعے کے دن کھڑے ہوکر خطبہ ارشاد فرماتے۔ پھر کچھ دیر کے لیے بیٹھ جاتے۔ اس دوران میں کلام نہ فرماتے۔ پھر کھڑے ہوکر دوسرا خطبہ ارشاد فرماتے۔ جو شخص تمھیں یہ بیان کرے کہ رسول اللہ صلی اللہ علیہ وسلم بیٹھ کر خطبہ ارشاد فرماتے تھے وہ قطعاً جھوٹا ہے۔","f2":"(۱) ’’کلام نہ فرماتے‘‘ یعنی تقریر نہ فرماتے تھے۔ اس میں آہستہ ذکر کی نفی نہیں۔ حدیث شریف میں ہے: [کان النبی صلی اللہ علیہ وسلم یذکر اللہ علی کل أحیانہ] (صحیح البخاري، الحیض، باب: ۷، و صحیح مسلم، الحیض، حدیث: ۳۷۳) ’’نبی صلی اللہ علیہ وسلم ہر وقت اللہ تعالیٰ کا ذکر فرماتے تھے۔‘‘ لہٰذا اس دوران میں اگر کوئی دل میں ذکر کرے تو کوئی حرج نہیں۔ (۲) دوسرا خطبہ الگ سے شروع کرنا چاہیے، یعنی حمد و ثنا، درود اور قراءت قرآن سے ابتدا کی جائے، پھر ذکر اور دعا۔"}],[1418,"جابر بن سمرہ رضی اللہ عنہ کہتے ہیں کہ نبی اکرم صلی اللہ علیہ وسلم کھڑے ہو کر خطبہ دیتے تھے، پھر آپ بیچ میں بیٹھتے، پھر کھڑے ہوتے، اور کچھ آیتیں پڑھتے، اور اللہ تعالی کا ذکر کرتے ۱؎ اور آپ کا خطبہ درمیانی ہوتا تھا، اور نماز بھی درمیانی ہوتی تھی۔\n§وضاحت\n۱؎: صحیح مسلم میں جابر بن سمرہ رضی اللہ عنہ ہی کی ایک روایت میں یہ صراحت ہے کہ آپ جمعہ میں دو خطبے دیتے تھے، اور دونوں میں تلاوت قرآن اور وعظ و تذکیر کیا کرتے تھے، اس لیے وعظ و تذکیر کے لیے صرف پہلے خطبے کو خاص کر لینا خلاف سنت ہے۔","الألباني: حسن",{"u2":"حضرت جابر بن سمرہ رضی اللہ عنہ بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم کھڑے ہوکر خطبہ ارشاد فرماتے تھے، پھر بیٹھ جاتے، پھر کھڑے ہو جاتے اور قرپن مجید کی چند آیات تلاوت فرماتے اور اللہ تعالیٰ کا ذکر کرتے۔ آپ کا خطبہ بھی درمیانہ ہوتا تھا اور نماز بھی درمیانی۔‘‘","f2":"دونوں (نماز اور خطبے) کے درمیانے ہونے سے یہ لازم نہیں آتا کہ دونوں برابر ہوتے تھے بلکہ نماز، نمازوں کے لحاظ سے درمیانی ہوتی اور خطبہ، خطبوں کے لحاظ سے درمیانہ ہوتا کیونکہ یہ دونوں الگ الگ چیزیں ہیں۔"}],[1419,"انس رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم منبر سے اترتے پھر کوئی آدمی آپ کے سامنے آ جاتا تو آپ اس سے گفتگو کرتے، اور نبی اکرم صلی اللہ علیہ وسلم اس کے ساتھ کھڑے رہتے جب تک کہ وہ اپنی ضرورت پوری نہ کر لیتا یعنی اپنی بات ختم نہ کر لیتا، پھر آپ اپنی جائے نماز کی طرف بڑھتے، اور نماز پڑھاتے۔","الألباني: شاذ والمحفوظ أن ذلك كان في صلاة العشاء",{"u2":"حضرت انس رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم (دو خطبوں کے بعد) منبر سے اترتے تو کبھی کوئی آدمی آپ کے سامنے آکر آپ سے باتیں شروع کر دیتا۔ نبی صلی اللہ علیہ وسلم اس کے ساتھ کھڑے رہتے حتی کہ وہ بات چیت مکمل کرتا۔ پھر آپ اپنی مخصوص جائے نماز کی طرف بڑھتے اور نماز پڑھتے، یعنی پڑھاتے۔","f2":"مذکورہ روایت سنداً ضعیف ہے تاہم اس قسم کا ایک واقعہ صحیح مسلم میں ہے، جس میں دوران خطبہ میں، خطبہ چھوڑ کر سائل سے گفتگو کرنے کا ذکر ہے۔ دیکھیے: (صحیح مسلم، الجمعۃ، حدیث: ۸۷۶) علاوہ ازیں اس قسم کا واقعہ کسی نماز کے موقع پر بھی پیش آیا تھا جیسا کہ جامع ترمذی میں ہے کہ نماز کی اقامت کہہ دی گئی تو ایک شخص نے نبی صلی اللہ علیہ وسلم کا ہاتھ پکڑ لیا اور پ سے باتیں کرنے لگا حتی کہ کچھ لوگوں کو اونگھ آنے لگی۔‘‘ دیکھیے: (جامع الترمذي، الجمعۃ، حدیث: ۵۱۸) نیز محققین علماء کے نزدیک مذکورہ روایت میں جمعے کا ذکر شاذ ہے، یعنی یہ واقعہ جمعے کا نہیں بلکہ عشاء کی نماز کا ہے۔ بنابریں اگر کوئی شخص یا امام کوئی ضروری بات کرنا چاہے تو کوئی حرج نہیں مگر دیگر لوگوں کی مصروفیت اور اذیت کا خیال رکھنا چاہیے۔ واللہ أعلم۔ مزید تفصیل کے لیے دیکھیے: (ضعیف سنن النسائي، للألباني، رقم: ۱۴۱۸، و ذخیرۃ العقبی شرح سنن النسائي: ۲۷۷/۱۶)"}],[1420,"عبدالرحمٰن بن ابی لیلی کہتے ہیں کہ عمر رضی اللہ عنہ نے کہا کہ جمعہ کی نماز، عید الفطر کی نماز، اور عید الاضحی کی نماز، اور سفر کی نماز، دو دو رکعتیں ہیں، اور یہ بزبان محمد صلی اللہ علیہ وسلم پوری ہیں، ان میں کوئی کمی نہیں ہے۔ ابوعبدالرحمٰن (نسائی) کہتے ہیں کہ عبدالرحمٰن بن ابی لیلی نے عمر رضی اللہ عنہ سے نہیں سنا ہے ۱؎۔\n§وضاحت\n۱؎: محقق بات یہ ہے کہ عبدالرحمٰن بن ابی لیلی کا سماع عمر رضی اللہ عنہ سے ثابت ہے، دیکھئیے مسند احمد، ونصب الرایہ :(۲/۱۸۹ ) نیز ابن ماجہ کی دوسری سند :(۱۰۶۴ ) میں عبدالرحمٰن بن ابی لیلی اور عمر رضی اللہ عنہ کے درمیان \" کعب بن عجرہ رضی اللہ عنہ \" کا واسطہ ہے۔","الألباني: صحيح",{"u2":"\"حضرت عمر رضی اللہ عنہ بیان کرتے ہیں کہ جمعہ، عیدالفطر، عیدالاضحیٰ اور سفر کی (رباعی) نماز رسول اللہ صلی اللہ علیہ وسلم کی زبانی دو دو رکعت ہے اور یہ مکمل نماز ہے۔ اس میں کوئی کمی نہیں۔\nامام عبدالرحمٰن (نسائی) رحمہ اللہ بیان کرتے ہیں کہ حضرت عبدالرحمن بن ابی لیلیٰ نے حضرت عمر رضی اللہ عنہ سے کوئی روایت نہیں سنی۔ (لہٰذا اس روایت کی سند منقطع ہے۔) \"","f2":"(۱) سفر کی نماز ان دوسری نمازوں کے ساتھ اس لیے شامل ہے کہ یہ بھی اگر رباعی (چار رکعت والی) ہوں تو دو رکعت ہے، سوائے مغرب کی نماز کے، مغرب کی نماز تین رکعت ہی ہے، چاہے سفر ہو یا حضر، جب کہ باقی مذکورہ نمازیں ہیں ہی دو رکعت۔ (۲) مذکورہ روایت کی بابت امام نسائی رحمہ اللہ بیان کرتے ہیں کہ عبدالرحمن بن ابی لیلیٰ نے حضرت عمر رضی اللہ عنہ سے یہی نہیں بلکہ کوئی روایت نہیں سنی۔ علمائے محققین اس کے بارے میں لکھتے ہیں کہ مذکورہ روایت دیگر اسناد اور طرق سے بھی مروی ہے اور ان طرق کو محققین نے صحیح قرار دیا ہے۔ بنا بریں مذکورہ روایت منقطع ہونے کے باوجود دیگر شواہد اور متابعات کی بنا پر صحیح ہے۔ واللہ أعلم۔ مزید تفصیل کے لیے دیکھیے: (ذخیرۃ العقبی شرح سنن النسائي: ۲۸۰/۱۶)"}],[1421,"عبداللہ بن عباس رضی اللہ عنہم سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم جمعہ کے روز نماز فجر میں «الم * تنزيل» اور «هل أتى على الإنسان»پڑھتے، اور جمعہ کی صلاۃ میں سورۃ \"جمعہ\" اور سورۃ \"منافقون\" پڑھتے تھے۔","الألباني: صحيح",{"u2":"حضرت ابن عباس رضی اللہ عنہما سے مروی ہے کہ رسول اللہ صلی اللہ علیہ وسلم جمعے کے دن صبح کی نماز میں سورۂ (المo تنزیل) اور سورۂ (ھل اتی علی الانسان) اور جمعے کی نماز میں سورۂ جمعہ اور سورۂ منافقوں پڑھا کرتے تھے۔"}],[1422,"سمرہ رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم جمعہ میں «سبح اسم ربك الأعلى» اور «هل أتاك حديث الغاشية» پڑھتے تھے ۱؎۔\n§وضاحت\n۱؎: اس روایت میں اور اس سے پہلے والے باب کی روایت میں بظاہر تعارض ہے، پر یہ اختلاف دونوں کے جواز اور دونوں کے مسنون ہونے پر دلالت کرتا ہے، مطلب یہ ہے کہ کبھی آپ جمعہ کی پہلی رکعت میں \"سورۃ جمعہ\" اور دوسری رکعت میں \"سورۃ منافقون\" پڑھتے اور کبھی «سبح اسم ربك الأعلى»اور «هل أتاك حديث الغاشية» پڑھتے تھے۔","الألباني: صحيح",{"u2":"حضرت سمرہ بن جندب رضی اللہ عنہ بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم جمعے کی نماز (کی پہلی رکعت) میں سورۂ (سبح اسم ربک الاعلی) اور (دوسری رکعت میں) (ھل اتک حدیث الغاشیۃ) پڑھا کرتے تھے۔"}],[1423,"عبیداللہ بن عبداللہ سے روایت ہے کہ ضحاک بن قیس نے نعمان بن بشیر رضی اللہ عنہم سے پوچھا: رسول اللہ صلی اللہ علیہ وسلم جمعہ کے دن سورۃ الجمعہ کے بعد کون سی سورۃ پڑھتے تھے؟ تو انہوں نے کہا: آپ «هل أتاك حديث الغاشية» پڑھتے تھے۔","الألباني: صحيح",{"u2":"حضرت ضحاک بن قیس نے حضرت نعمان بن بشیر رضی اللہ عنہما سے پوچھا کہ رسول اللہ صلی اللہ علیہ وسلم جمعے کے دن سورۂ جمعہ کے بعد (دوسری رکعت میں) کون سی سورت پڑھا کرتے تھے؟ انھوں نے فرمایا: (ھل اتک حدیث الغاشیۃ)"}],[1424,"حبیب بن سالم نعمان بن بشیر رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم جمعہ میں «سبح اسم ربك الأعلى» اور «هل أتاك حديث الغاشية» پڑھتے تھے اور جب کبھی عید اور جمعہ دونوں جمع ہو جاتے تو ان دونوں میں بھی آپ انہی دونوں سورتوں کو پڑھتے تھے۔","الألباني: صحيح",{"u2":"حضرت نعمان بن بشیر رضی اللہ عنہما بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم جمعے کی نماز میں (سبح اسم ربک الاعلی) اور (ھل اتک حدیث الغاشیۃ) پڑھا کرتے تھے۔ کبھی عید اور جمعہ ایک دن آ جاتے تو یہی دو سورتیں دونوں میں پڑھتے۔","f2":"(۱) اگرچہ نماز جمعہ میں کوئی سی سورت بھی پڑھی جا سکتی ہے مگر مندرجہ بالا چار سورتیں مسنون و مستحب ہیں۔ امام نسائی رحمہ اللہ نے نماز جمعہ کی قراءت کے متعلق حضرت نعمان بن بشیر رضی اللہ عنہما سے مروی روایات میں راویوں کے اختلاف کو ذکر کیا ہے کہ عبیداللہ بن عبداللہ کی روایت میں ہے کہ رسول اللہ صلی اللہ علیہ وسلم جمعے کی پہلی رکعت میں سورۂ جمعہ اور دوسری میں سورۂ غاشیہ پڑھا کرتے تھے اور حبیب بن سالم کی روایت میں ہے کہ رسول اللہ صلی اللہ علیہ وسلم جمعے کی پہلی رکعت میں سورۂ اعلیٰ اور دوسری میں سورۂ غاشیہ پڑھا کرتے تھے۔ لیکن یہ اختلاف حدیث کی صحت پر اثر انداز نہیں ہوتا کیونکہ یہ اختلاف صرف سورتوں کی تعیین میں ہے جس کی بابت علماء نے لکھا ہے کہ ممکن ہے کہ رسول اللہ صلی اللہ علیہ وسلم کبھی نماز جمعہ میں سورۂ اعلیٰ اور سورۂ غاشیہ اور کبھی سورۂ جمعہ اور سورۂ منافقون پڑھتے ہوں اور کبھی سورۂ جمعہ اور سورۂ غاشیہ۔ بنابریں کبھی سورۂ اعلیٰ اور سورۂ غاشیہ پڑھ لی جائیں اور کبھی جمعہ اور منافقون۔ انھیں آپس میں ملایا بھی جا سکتا ہے، مثلاً: سورۂ جمعہ اور سورۂ غاشیہ جیسا کہ حدیث نمبر ۱۴۲۴ میں بیان ہے۔ (۲) اس حدیث سے ثوابت ہوا کہ جمعے کے دن عید آ جائے تو عید بھی پڑھی جائے اور جمعہ بھی، خطیب اور قرب و جوار کے لوگوں کے لیے یہی افضل ہے، اگر وہ جمعے کی بجائے ظہر پڑھ لیں تو بھی جائز ہے۔ واللہ أعلم۔"}],[1425,"ابوہریرہ رضی اللہ عنہ کہتے ہیں کہ نبی اکرم صلی اللہ علیہ وسلم نے فرمایا: \"جس نے جمعہ کی نماز میں سے ایک رکعت پا لی تو اس نے (جمعہ کی نماز) پا لی\"۔","الألباني: شاذ بذكر الجمعة والمحفوظ الصلاة",{"u2":"حضرت ابوہریرہ رضی اللہ عنہ سے روایت ہے، نبی صلی اللہ علیہ وسلم نے فرمایا: ’’جو شخص جمعے کی نماز سے ایک رکعت (باجماعت) پالے تو اسے جمعہ مل گیا۔‘‘","f2":"(۱)اس روایت کے مفہوم سے معلوم ہوا کہ اگر کسی شخص کو ایک رکعت سے کم ملے، یعنی وہ سجدہ اور تشہد میں ملے تو وہ جمعہ کی بجائے ظہر کی نماز پڑھے۔ جمہور اہل علم، یعنی امام مالک، امام شافعی، امام احمد، امام اسحاق حتی کہ احناف میں سے امام محمد رحمہ اللہ اسی کے قائل ہیں۔ صحابہ سے بھی یہی ملتا ہے مگر امام ابوحنیفہ رحمہ اللہ کا خیال ہے کہ سلام سے پہلے جب بھی مل جائے تو جمعہ ہی پڑھے کیونکہ ایک حدیث ہے: [ما ادرکتم فصلوا وما فاتکم فاتموا] حالانکہ یہ حدیث خاص جمعے کے بارے میں نہیں جب کہ باب کی روایت خاص جمعے کے بارے میں ہے۔ عام و خاص کے تعارض کے وقت دلیل خاص کو ترجیح دی جاتی ہے۔ (۲) ’’اس کو جمعہ مل گیا‘‘ یعنی وہ ایک اور رکعت ملالے تو اس کا جمعہ ہوگیا۔ سنن ابن ماجہ کی ایک روایت میںصراحت ہے۔ دیکھیے: (سنن ابن ماجہ، إقامۃ الصلوات، حدیث: ۱۱۲۱، و إرواءالغلیل، حدیث: ۶۲۲)"}],[1426,"ابوہریرہ رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"جب تم میں سے کوئی جمعہ پڑھے تو اسے چاہیئے کہ اس کے بعد چار رکعتیں پڑھے\" ۱؎۔\n§وضاحت\n۱؎: اس حدیث میں چار رکعت کا ذکر ہے، اور اس کے بعد والی حدیث میں دو رکعت کا، اس سے معلوم ہوا کہ یہ دونوں صورتیں جائز ہیں بعض لوگوں نے دونوں رایتوں میں اس طرح سے تطبیق دی ہے کہ جو مسجد میں پڑھے وہ چار رکعت پڑھے، اور جو گھر جا کر پڑھے وہ دو رکعت پڑھے، اسی طرح چار رکعت کس طرح پڑھی جائیں، اس میں بھی دو رائے ہے ایک رائے تو یہ ہے کہ ایک سلام کے ساتھ چاروں رکعتیں پڑھی جائیں، اور دوسری رائے یہ ہے کہ دو دو کر کے چار رکعتیں پڑھی جائیں، کیونکہ صحیح حدیث میں ہے «صلاۃ اللیل والنہارمثنی مثنی» رات اور دن کی :(نفلی نمازیں ) دو دو کر کے ہیں۔","الألباني: صحيح",{"u2":"حضرت ابوہریرہ رضی اللہ عنہ سے روایت ہے، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’جب تم میں سے کوئی شخص جمعہ پڑھے تو اس کے بعد چار رکعت (سنت) پڑھے۔‘‘","f2":"حدیث میں مسجد میں پڑھنے کا ذکر نہیں۔ دراصل امام نسائی رحمہ اللہ احادیث میں تطبیق دے رہے ہیں کیونکہ ایک روایت میں رسول اللہ صلی اللہ علیہ وسلم کے دو رکعت پڑھنے ککا ذکر ہے۔ دیکھیے: (صحیح البخاري، الجمعۃ، حدیث: ۹۳۷، و صحیح مسلم، الجمعۃ، حدیث ۸۸۲) مصنف رحمہ اللہ نے چار رکعت والی روایت کو مسجد سے خاص کر دیا اور دو رکعت والی کو گھر کے ساتھ کیونکہ اس میں گھر کا ذکر ہے، یعنی گھر میں آکر پڑھے تو دو رکعتیں اور مسجد میں پڑھے تو چار رکعتیں لیکن راجح بات یہ ہے کہ دو رکعت بھی پڑھی جا سکتی ہیں اور چار بھی۔ واللہ أعلم۔ جبکہ بعض لوگ قولی و فعلی دونوں روایات پر عمل کے قائل ہیں، یعنی چار بھی پڑھ لے اور دو بھی، کل چھ ہوگئیں، لیکن یہ بات بلا دلیل ہے۔"}],[1427,"عبداللہ بن عمر رضی اللہ عنہم سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم جمعہ کے بعد نماز نہیں پڑھتے تھے یہاں تک کہ گھر لوٹ آتے، پھر دو رکعتیں پڑھتے۔","الألباني: صحيح",{"u2":"حضرت ابن عمر رضی اللہ عنہما سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم جمعے کے بعد نماز (نوافل) نہیں پڑھتے تھے حتی کہ گھر تشریف لے جاتے اور دو رکعتیں پڑھتے۔"}],[1428,"عبداللہ بن عمر رضی اللہ عنہم کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم جمعہ کے بعد دو رکعت اپنے گھر میں پڑھتے تھے۔","الألباني: صحيح",{"u2":"حضرت ابن عمر رضی اللہ عنہما بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم جمعے کے بعد اپنے گھر میں دو رکعتیں پڑھتے تھے۔","f2":"یہ ایک اور تطبیق ہے جو امام نسائی رحمہ اللہ نے ان دو روایات (چار رکعت اور دو رکعت والی) میں اختیار کی ہے کہ چار پڑھنے کا حکم مقتدیوں کو ہے۔ دیکھیے: (صحیح مسلم، الجمعۃ، حدیث: ۸۸۱) اور دو رکعت پڑھنے کا ذکر آپ کے ساتھ خاص ہے۔ گویا امام دو رکعت پڑھے اور مقتدی چار رکعت پڑھیں۔ لیکن امام صاحب کا یہ استدلال محل نظر ہے کیونکہ رسول اللہ صلی اللہ علیہ وسلم کا ہر فرمان ہمارے لیے اسوۂ اور نمونہ ہے، اس لیے دو رکعات آپ علیہ الصلوٰۃ والسلام کے ساتھ خاص نہیں، لہٰذا دو بھی پڑھی جا سکتی ہیں اور چار بھی، کسی حدیث پر بھی عمل کر لیا جائے۔ واللہ أعلم۔"}],[1429,"عبداللہ بن عمر رضی اللہ عنہم سے روایت ہے کہ وہ جمعہ کے بعد دو رکعتیں پڑھتے تھے، اور ان کو لمبی کرتے تھے اور کہتے: رسول اللہ صلی اللہ علیہ وسلم ایسا ہی کرتے تھے۔","الألباني: شاذ بذكر إطالتهما",{"u2":"حضرت ابن عمر رضی اللہ عنہما جمعے کے بعد دو رکعتیں پڑھتے تھے اور انھیں لمبا کرتے تھے، نیز وہ فرماتے تھے: رسول اللہ صلی اللہ علیہ وسلم بھی اسی طرح کیا کرتے تھے۔","f2":"(۱)جمعے سے پہلے کتنی رکعات پڑھی جائیں؟ نبیٔ اکرم صلی اللہ علیہ وسلم سے جمعے سے قبل رکعتوں کی کوئی تعیین کسی صحیح حدیث سے ثابت نہیں، نہ قول سے اور نہ آپ کے عمل ہی سے بلکہ رسول اللہ صلی اللہ علیہ وسلم جب منبر پر رونق افروز ہو جاتے تو اذان شروع ہو جاتی اور اذان کے بعد آپ کسی وقفے کے بغیر خطبہ شروع فرما دیتے، لہٰذا جو شخص امام کے خطبہ شروع ہونے سے پہلے مسجد میں پہنچ جائے تو وہ بلاتعیین جتنی سنتیں اور نوافل پڑھنا چاہے پڑھ لے اور جونہی امام خطبہ شروع کرے، نوافل پڑھنا بند کر دے۔ مزید تفصیل کے لیے دیکھیے: (فتاویٰ ابن تیمیۃ: ۲۰-۱۸۸/۲۴، و زادالمعاد: ۴۴۰-۴۳۲/۱) ابن ماجہ کی جس روایت میں جمعے سے پہلے چار رکعت پڑھنے کا ذکر ہے، وہ سخت ضعیف ہے۔ دیکھیے: (سنن ابن ماجہ، إقامۃ الصلوات، حدیث ۱۱۲۹، و ضعیف سنن ابن ماجہ للألباني، رقم: ۱۱۳۹) عموماً اسی کے مطابق عمل ہوتا ہے۔ لیکن درست بات وہی ہے جو ذکر ہوچکی ہے۔ (۲) شیخ البانی رحمہ اللہ نے ’’لمبا کرنے‘‘ کے الفاظ کو شاذ قرار دیا ہے۔ دیکھیے: (إرواء الغلیل: ۹۰،۸۹/۳)"}],[1430,"ابوہریرہ رضی اللہ عنہ کہتے ہیں کہ میں طور پہاڑی پر آیا تو وہاں مجھے کعب (کعب احبار) رضی اللہ عنہ ملے تو میں اور وہ دونوں ایک دن تک ساتھ رہے، میں ان سے رسول اللہ صلی اللہ علیہ وسلم کی حدیثیں بیان کرتا تھا، اور وہ مجھ سے تورات کی باتیں بیان کرتے تھے، میں نے ان سے کہا: رسول اللہ صلی اللہ علیہ وسلم نے فرمایا ہے:\"بہترین دن جس میں سورج نکلا جمعہ کا دن ہے، اسی میں آدم پیدا کئے گئے، اسی میں (دنیا میں) اتارے گئے، اسی میں ان کی توبہ قبول کی گئی، اسی میں ان کی روح نکالی گئی، اور اسی دن قیامت قائم ہو گی، زمین پر رہنے والی کوئی مخلوق ایسی نہیں ہے جو جمعہ کے دن قیامت کے ڈر سے صبح کو سورج نکلنے تک کان نہ لگائے رہے، سوائے ابن آدم کے، اور اس دن میں ایک گھڑی ایسی ہے کہ کسی مومن کو یہ گھڑی مل جائے اور نماز کی حالت میں ہو اور وہ اللہ سے اس ساعت میں کچھ مانگے تو وہ اسے ضرور دے گا\"، کعب نے کہا: یہ ہر سال میں ایک دن ہے، میں نے کہا: نہیں، بلکہ یہ گھڑی ہر جمعہ میں ہوتی ہے، تو کعب نے تورات پڑھ کر دیکھا تو کہنے لگے: رسول اللہ صلی اللہ علیہ وسلم نے سچ فرمایا ہے، یہ ہر جمعہ میں ہے۔ پھر میں (وہاں سے) نکلا، تو میری ملاقات بصرہ بن ابی بصرہ غفاری رضی اللہ عنہ سے ہوئی، تو انہوں نے پوچھا: آپ کہاں سے آ رہے ہیں؟ میں نے کہا: طور سے، انہوں نے کہا: کاش کہ میں آپ سے وہاں جانے سے پہلے ملا ہوتا، تو آپ وہاں نہ جاتے، میں نے ان سے کہا: کیوں؟ میں نے رسول اللہ صلی اللہ علیہ وسلم کو سنا، آپ فرما رہے تھے: \"سواریاں استعمال نہ کی جائیں یعنی سفر نہ کیا جائے مگر تین مسجدوں کی طرف: ایک مسجد الحرام کی طرف، دوسری میری مسجد یعنی مسجد نبوی کی طرف، اور تیسری مسجد بیت المقدس ۱؎ کی طرف۔ پھر میں عبداللہ بن سلام رضی اللہ عنہ سے ملا تو میں نے کہا: کاش آپ نے مجھے دیکھا ہوتا، میں طور گیا تو میری ملاقات کعب سے ہوئی، پھر میں اور وہ دونوں پورے دن ساتھ رہے، میں ان سے رسول اللہ صلی اللہ علیہ وسلم کی حدیثیں بیان کرتا تھا، اور وہ مجھ سے تورات کی باتیں بیان کرتے تھے، میں نے ان سے کہا: رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"دنوں میں بہترین دن جمعہ کا دن ہے جس میں سورج نکلا، اسی میں آدم پیدا کئے گئے، اسی میں دنیا میں اتارے گئے، اسی میں ان کی توبہ قبول ہوئی، اسی میں ان کی روح نکالی گئی، اور اسی میں قیامت قائم ہو گی، زمین پر کوئی ایسی مخلوق نہیں ہے جو قیامت کے ڈر سے جمعہ کے دن صبح سے سورج نکلنے تک کان نہ لگائے رہے سوائے ابن آدم کے، اور اس دن میں ایک گھڑی ایسی ہے کہ جس مسلمان کو وہ گھڑی نماز کی حالت میں مل جائے، اور وہ اللہ سے کچھ مانگے تو اللہ تعالی اس کو وہ چیز ضرور دے گا، اس پر کعب نے کہا: ایسا دن ہر سال میں ایک ہے، تو عبداللہ بن سلام رضی اللہ عنہ نے کہا: کعب نے غلط کہا، میں نے کہا: پھر کعب نے (تورات) پڑھی اور کہا: رسول اللہ صلی اللہ علیہ وسلم نے سچ فرمایا ہے، وہ ہر جمعہ میں ہے، تو عبداللہ بن سلام رضی اللہ عنہ نے کہا: کعب نے سچ کہا، پھر انہوں نے کہا: میں اس گھڑی کو جانتا ہوں، تو میں نے کہا: اے بھائی! مجھے وہ گھڑی بتا دیں، انہوں نے کہا: وہ گھڑی جمعہ کے دن سورج ڈوبنے سے پہلے کی آخری گھڑی ہے، تو میں نے کہا: کیا آپ نے رسول اللہ صلی اللہ علیہ وسلم سے یہ نہیں سنا کہ آپ نے فرمایا: \"جو مومن اس گھڑی کو پائے اور وہ نماز میں ہو\" جبکہ اس گھڑی میں کوئی نماز نہیں ہے، تو انہوں نے کہا: کیا آپ نے نہیں سنا ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا ہے:\"جو شخص نماز پڑھے پھر بیٹھ کر دوسری نماز کا انتظار کرتا رہے، تو وہ نماز ہی میں ہوتا ہے\"، میں نے کہا: کیوں نہیں سنا ہے؟ اس پر انہوں نے کہا: تو وہ اسی طرح ہے۔\n§وضاحت\n۱؎: لہٰذا ان تین مساجد کے علاوہ کسی اور مسجد کے لیے ثواب کی نیت سے سفر جائز نہیں ہے، ایسے ہی مقام کی زیارت کے لیے ثواب کی نیت سے جانا خواہ وہ کوئی قبر ہو یا شہر درست نہیں۔","الألباني: صحيح",{"u2":"حضرت ابوہریرہ رضی اللہ عنہ بیان کرتے ہیں کہ میں کوہِ طور پر گیا۔ وہاں میں نے کعب احبار کو پایا۔ ہم دونوں ایک دن اکٹھے رہے۔ میں انھیں رسول اللہ صلی اللہ علیہ وسلم کی احادیث بیان کرتا تھا اور وہ مجھے تورات کی باتیں بتاتے تھے۔ میں نے ان سے کہا: رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’بہترین دن جس میں سورج طلوع ہو، جمعے کا دن ہے۔ اس دن حضرت آدم علیہ السلام پیدا ہوئے۔ اسی دن وہ زمین پر اتارے گئے۔ اسی دن ان کی توبہ قبول ہوئی۔ اسی دن فوت ہوئے اور اسی دن قیامت قائم ہوگی۔ ابن آدم (انسان) کے سوا زمین پر جو بھی حرکت کرنے والا جانور ہے، وہ جمعے کے دن صبح سے لے کر سورج طلوع ہونے تک قیامت کے ڈر سے چپ چاپ کان لگائے رکھتا ہے (کہ کہیں صور نہ پھونک دیا جائے) مگر انسان (بے خوف رہتا ہے)۔ اور اس دن میں ایک ایسی گھڑی ہے جسے کوئی مومن نماز کی حالت میں پالے، پھر وہ اللہ تعالیٰ سے اس وقت کوئی چیز مانگے تو اللہ تعالیٰ اسے وہ چیز ضرور دے دیتا ہے۔‘‘ کعب کہنے لگے: ایسا دن ہر سال میں ایک ہوتا ہے۔ میں نے کہا: نہیں وہ گھڑی ہر جمعے میں ہوتی ہے۔ پھر کعب نے تورات پڑھی تو کہنے لگے: رسول اللہ صلی اللہ علیہ وسلم نے سچ فرمایا ہے۔ یہ ہر جمعے کے دن ہوتا ہے۔ میں ان کے پاس سے نکلا تو میں بصرہ بن ابوبصرہ غفری رضی اللہ عنہ کو ملا۔ وہ کہنے لگے: کہاں سے آئے ہو؟ میں نے کہا: کوہِ طور سے۔ وہ کہنے لگے: اگر تمھارے طور پر جانے سے پہلے میری اور تمھاری ملاقات ہو جاتی تو تم وہاں نہ جاتے۔ میں نے کہا: کیوں؟ انھوں نے کہا: میں نے رسول اللہ صلی اللہ علیہ وسلم کو یہ فرماتے سنا: ’’سواریوں کو کام میں نہ لایا جائے مگر ان تین مساجد کی طرف جانے کے لیے: مسجد حرام، میری یہ مسجد (مسجد نبوی) اور بیت المقدس کی مسجد۔‘‘ پھر میں عبداللہ بن سلام رضی اللہ عنہ کو ملا۔ میں نے ان سے کہا: اگر آپ میرے ساتھ گزرنے والا واقعہ دیکھتے (تو محظوظ ہوتے۔) میں طور پہاڑ کی زیارت کے لیے گیا۔ وہاں میں کعب احبار کو ملا۔ میں اور وہ ایک دن اکٹھے رہے۔ میں انھیںرسول اللہ صلی اللہ علیہ وسلم کی حدیثیں بیان کرتا تھا اور وہ مجھے تورات سے بیان کرتے تھے۔ میں نے ان سے کہا کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’بہترین دن جس میں سورج طلوع ہوتا ہے، جمعے کا دن ہے۔ اس دن آدم علیہ السلام پیدا ہوئے۔ اسی دن جنت سے نکالے گئے۔ اسی دن ان کی توبہ قبول ہوئی۔ اسی دن فوت ہوئے اور اسی دن قیامت قائم ہوگی۔ انسان کے سوا روئے ارض پر جو بھی حرکت کرنے والا جانور ہے، وہ جمعے کے دن قیامت کے ڈر سے صبح سے لے کر طلوع شمس تک کان لگائے رکھتا ہے (کہ کہیں صور نہ پھونک دیا جائے)، نیز اس دن میں ایک ایسی گھڑی ہے کہ جو بھی مومن بندہ اسے نماز کی حالت میں پالے، پھر وہ اللہ تعالیٰ سے کوئی چیز مانگے تو اللہ تعالیٰ وہ چیز اسے ضرور دے دیتا ہے۔‘‘ کعب کہنے لگے: ایسا تو سال میں ایک دن ہوتا ہے۔ عبداللہ بن سلام رضی اللہ عنہ کہنے لگے: کعب نے غلط کہا۔ میں نے کہا: پھر کعب نے تورات پڑھی اور کہا کہ رسول اللہ صلی اللہ علیہ وسلم نےسچ فرمایا ہے۔ یہ ہر جمعے کو ہوتا ہے۔ عبداللہ بن سلام رضی اللہ عنہ کہنے لگے: کعب نے سچ کہا۔ میں یقیناً اس گھڑی کو جانتا ہوں۔ میں نے کہا: برادر محترم! مجھے ضرور بتائیے۔ انھوں نے کہا: یہ جمعے کے دن غروب شمس سے پہلے آخری گھڑی ہے۔ میں نے کہا: کیا آپ نے رسول اللہ صلی اللہ علیہ وسلم کو یہ فرماتے نہیں سنا: ’’مومن اسے نماز کی حالت میں پائے۔‘‘ جب کہ یہ گھڑی (دن کی آخری گھڑی) تو نماز کا وقت ہی نہیں۔ وہ کہنے لگے: کیا آپ نے رسول اللہ صلی اللہ علیہ وسلم کو یہ فرماتے نہیں سنا: ’’جو آدمی نماز پڑھ کر اگلی نماز کے انتظار میں بیٹھا رہے تو وہ نماز ہی میں ہوتا ہے حتی کہ بعد والی نماز کا وقت ہو جائے۔‘‘ میں نے کہا: کیوں نہیں (بلکہ سنا ہے۔) انھوں نے کہا: یہاں بھی یہی مراد ہے۔ (یعنی نماز کے انتظار میں ہو۔)","f2":"(۱)’’کوہِ طور‘‘ جہاں حضرت موسیٰ علیہ السلام اللہ تعالیٰ سے ہم کلام ہوئے۔ قرآن میں اسے ’’وادیٔ مقدس‘‘ کہا گیا ہے۔ (۲) ’’کان لگائے رکھتا ہے‘‘ یعنی توجہ رکھتا ہے اور منتظر رہتا ہے۔ شاید جانوروں کو جمعے کے دن کا علم ہو جاتا ہوگا یا ان میں یہ چیز طبعی ہوگی کہ ہر جمعے کے دن وہ خوف زدہ رہتے ہوں گے اور یہی بات زیادہ صحیح معلوم ہوتی ہے کیونکہ جانوروں کے سب کام طبعاً اور فطرتاً ہوتے ہیں جب کہ انسان فطرت کے خلاف بھی کام کر لیتا ہے۔ (۳) ’’ایسی گھڑی ہے‘‘ حضرت عبداللہ بن سلام رضی اللہ عنہ کی مرفوع روایت کے مطابق عصر کے بعد آخری گھڑی ہے۔ بعض روایات کے مطابق وہ گھڑی امام کے منبر پر چڑھنے سے لے کر نماز سے فارغ ہونے تک ہے۔ شاہ ولی اللہ رحمہ اللہ نے یوں تطبیق دی ہے کہ ساعت یومی تو عصر کے بعد ہی ہے مگر جمعہ میں اجتماع مومنین کی برکت سے خطبہ و نماز کا وقت بھی افضل ہو جاتا ہے، لہٰذا وہ بھی قبولیت کا وقت بن جاتا ہے۔ یہ بھی کہا جا سکتا ہے کہ کبھی یہ گھڑی ہوتی ہے کبھی وہ۔ اکثر اہل علم نے حضرت عبداللہ بن سلام رضی اللہ عنہ کی روایت کو ترجیح دی ہے۔ (۴) ’’سواریوں کو کام میں نہ لایا جائے‘‘ یعنی قربت و ثواب کے حصول کے لیے لمبا سفر نہ کیا جائے یہ سمجھ کر کہ فلاں جگہ مقدس ہے۔ وہاں قرب و ثواب زیادہ ہوگا، سوائے ان تین مساجد کے۔ راویٔ حدیث حضرت بصرہ غفاری رضی اللہ عنہ نے کسی بھی مقدس مقام (خواہ وہ مسجد ہو یا کوئی اور مقام) کی طرف قربت اور ثواب کی نیت سے لمبا سفر کرنا درست نہیں سمجھا۔ حضرت ابوہریرہ رضی اللہ عنہ نے بھی یہی مفہوم درست سمجھا۔ تبھی تو ان کی بات کا انکار نہیں کیا۔ اور یہی مفہوم درست ہے۔ یہ بحث تفصیلاً پیچھے گزر چکی ہے۔ دیکھیے، حدیث: ۷۰۱۔ (۵) بیت المقدس کی مسجد سے مراد بیت المقدس ہی ہے کیونکہ جو جگہ اللہ تعالیٰ کی عبادت کے لیے خاص کی گئی ہے، وہ مسجد ہے۔ اور بیت المقدس بھی اللہ تعالیٰ کی عبادت کے لیے بنایا گیا تھا۔ (۶) ’’وہ نماز ہی میں ہے‘‘ حضرت عبداللہ بن سلام رضی اللہ عنہ کی یہ تاویل ایک فقیہ صحابی کی تاویل ہے جو معتبر ہے لیکن درج ذیل روایت (۱۴۳۳) میں یہ الفاظ ہیں: [قائم یصلی] ’’یعنی وہ کھڑا نماز پڑھتا ہو۔‘‘ حالانکہ نماز کا انتظار عموماً بیٹھ کر ہوتا ہے۔ تو علماء نے ان کے درمیان یوں تطبیق دی ہے کہ حضرت ابوہریرہ رضی اللہ عنہ کی حدیث میں قائم کے معنی حضرت عبداللہ بن سلام کی حدیث کی روشنی میں ’’ثابت‘‘ کے ہیں، یعنی بیٹھ کر انتظار کرنے کے ہیں کیونکہ عموماً نماز کا انتظار بیٹھ کر ہی کیا جاتا ہے۔ یا پھر یہاں قائم کی قید ’’قید و صفی‘‘ ہے، یعنی یہ قید نمازی کی عمومی حالت کے پیش نظر ہے کیونکہ نماز کھڑے ہو کر ہی ادا کی جاتی ہے، لہٰذا مذکورہ الفاظ کی روشنی میں نماز کا انتظار کھڑے ہوکر لازمی قرار نہیں پاتا۔ واللہ أعلم۔ مزید دیکھیے: (التعلیقات السلفیہ (طبع جدید): ۳۳۳/۲، ۳۳۴)"}],[1431,"ابوہریرہ رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"جمعہ میں ایک گھڑی ایسی ہے کہ اگر کوئی مسلمان بندہ اس گھڑی کو پا لے، اور اس میں اللہ تعالی سے کچھ مانگے تو اللہ تعالی اس کو ضرور دے گا\"۔","الألباني: صحيح",{"u2":"حضرت ابوہریرہ رضی اللہ عنہ سے منقول ہے کہ حضرت ابوالقاسم صلی اللہ علیہ وسلم نے فرمایا: ’’یقیناً جمعے کے دن ایک ایسا مخصوص وقت ہے جسے جو بھی مسلمان شخص کھڑا نماز پڑھتا ہوا پالے اور اس میں اللہ تعالیٰ سے کوئی چیز مانگتا ہو تو اللہ تعالیٰ اسے ضرور وہ چیز دے دیتا ہے۔‘‘ پ صلی اللہ علیہ وسلم (ہاتھ کے اشارے سے) اس وقت کو بہت قلیل بتاتے تھے۔","f2":"جو چیز جتنی زیادہ قیمتی، بلند مرتبہ اور افضل ہو، اتنی ہی کم ہوتی ہے۔ یہ فطری اصول ہے۔ یہ وقت بھی بہت فضیلت والا ہے، اس لیے قلیل ہے، نیز ایسی چیز بڑی چھپا کر رکھی جاتی ہے اور اس کے حصول میں بڑی جدوجہد کی ضرورت ہوتی ہے، لہٰذا اس وقت کو مبہم رکھا گیا تاکہ اس کی خصوصی شان ظاہر ہو۔ مباک ہیں وہ لوگ جو ایسی ساعات لطیفہ سے بہرہ ور ہوتے ہیں۔ لمثل ھذا فلیعمل العاملون۔ وفقنا اللہ لما یحبہ ویرضی۔"}],[1432,"ابوہریرہ رضی اللہ عنہ کہتے ہیں کہ ابوالقاسم صلی اللہ علیہ وسلم نے فرمایا: \"جمعہ والے دن ایک گھڑی ایسی ہے کہ کوئی مسلمان بندہ اسے نماز میں کھڑا پا لے، پھر اللہ تعالی سے کچھ مانگے، تو اللہ تعالی اسے ضرور دے گا\"، اور آپ اسے ہاتھ کے اشارے سے کم کر کے بتا رہے تھے۔ ابوعبدالرحمٰن (نسائی) کہتے ہیں: ہم کسی کون ہیں جانتے جس نے اس حدیث کو عن معمر، عن الزهري، عن سعيد (المقبري) کے طریق سے روایت کیا ہو، سوائے رباح کے، البتہ ایوب بن سوید نے اس کو عن يونس، عن الزهري، عن سعيد وأبي سلمة کے طریق سے روایت کیا ہے، لیکن ایوب بن سوید متروک الحدیث ہے۔","الألباني: صحيح",{"u2":"حضرت ابوہریرہ رضی اللہ عنہ سے روایت ہے، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’جمعے کے دن میں ایک ایسی گھڑی (وقت) ہے جسے کوئی بھی مسلمان آدمی پالے، پھر اللہ تعالیٰ سے اس میں کوئی چیز مانگے تو اللہ تعالیٰ اسے وہ چیز ضرور دے گا۔‘‘\nامام ابو عبدالرحمٰن (نسائی) رحمہ اللہ بیان کرتے ہیں کہ ہم نہیں جانتے کہ حضرت رباح کے علاوہ کسی نے یہ روات عن معمر عن الزھری کی سند سے اس طرح بیان کی ہو، البتہ حضرت ایوب بن سوید نے یہ روایت عن یونس عن الزھری عن سعید و أبی سلمۃ کی سند سے بیان کی ہے۔ لیکن ایوب بن سوید (کی حدیث معتبر نہیں، وہ) متروک الحدیث ہے۔"}],[1433,"یعلی بن امیہ کہتے ہیں کہ میں نے عمر بن خطاب رضی اللہ عنہ سے آیت کریمہ: «ليس عليكم جناح أن تقصروا من الصلاة إن خفتم أن يفتنكم الذين كفروا» \"تم پر نمازوں کے قصر کرنے میں کوئی گناہ نہیں، اگر تمہیں ڈر ہو کہ کافر تمہیں ستائیں گے\" (النساء: ۱۰۱)، کے متعلق عرض کیا کہ اب تو لوگ مامون اور بےخوف ہو گئے ہیں؟ تو عمر رضی اللہ عنہ نے کہا: مجھے بھی اس سے تعجب ہوا تھا جس سے تم کو تعجب ہے، تو میں نے اس کے متعلق رسول اللہ صلی اللہ علیہ وسلم سے پوچھا، تو آپ نے فرمایا: \"یہ ایک صدقہ ہے ۱؎ جسے اللہ تعالی نے تم پر کیا ہے، تو تم اس کے صدقہ کو قبول کرو\"۔\n§وضاحت\n۱؎: یعنی اسے اللہ تعالی نے تمہاری کمزوری اور درماندگی کو دیکھتے ہوئے تمہاری پریشانی اور مشقت کے ازالہ کے لیے بطور رحمت تمہارے لیے مشروع کیا ہے، لہٰذا آیت میں «إن خفتم» :(اگر تمہیں ڈر ہو ) کی جو قید ہے وہ اتفاقی ہے احترازی نہیں۔","الألباني: صحيح",{"u2":"حضرت یعلی بن امیہ رضی اللہ عنہما بیان کرتے ہیں کہ میں نے حضرت عمر بن خطاب رضی اللہ عنہ سے پوچھا کہ (قرآن کی آیت) (فلیس علیکم جناح ان تعصروا من الصلوٰۃ ان خفتم ان یفتنکم الذین کفروا) ’’تم پر کوئی گناہ نہیں کہ تم نماز قصر کرلو بشرطیکہ تمھیں ڈر ہو کہ کافر تمھیں نقصان پہنچائیں گے۔‘‘ (سے معلوم ہوتا ہے کہ قصر نماز خوف ہی کی حالت کے ساتھ خاص ہے) اب تو لوگ امن کی حالت میں ہیں۔ (لہٰذا نماز قصر نہیں کرنی چاہیے۔) حضرت عمر رضی اللہ عنہ نے فرمایا: مجھے بھی اس بات پر تعجب ہوا تھا جس پر تجھے تعجب ہوا ہے تو میں نے اس بارے میں رسول اللہ صلی اللہ علیہ وسلم سے پوچھا۔ آپ نے فرمایا: ’’یہ صدقہ ہے جو اللہ تعالیٰ نے تم پر کیا ہے، تو تم اللہ تعالیٰ کا صدقہ قبول کرو۔‘‘","f2":"(۱)مندرجہ بالا آیت میں بظاہر سفر اور خوف دونوں کو قصر کے لیے شرط قرار دیا گیا ہے، لہٰذا یہ سوال بجا ہے لیکن نبی صلی اللہ علیہ وسلم کے جواب سے یہ بات واضحہوتی ہے کہ جب قصر کا حکم نازل ہوا، اس وقت تو واقعتاً سفر بھی تھا اور خوف بھی مگر بعد میں خوف کی شرط ساقط کر دی گئی۔ لفظ ’’صدقہ‘‘ بھی اس سقوط پر دلالت کرتا ہے۔ مگر اس سقوط کا ذکر قرآن میں نہیں بلکہ رسول اللہ صلی اللہ علیہ وسلم کی زبانی معلوم ہوا۔ اس بات کو یوں بھی بیان کیا جا سکتا ہے کہ قصر کے لیے صرف سفر ہی شرط تھا، خوف کا ذکر درپیش صورتِ حال کے طور پر تھا کیونکہ اس وقت خوف کی حالت بھی تھی۔ بعد میں وضاحت کر دی گئی کہ خوف قصر کے لیے شرط نہیں، لہٰذا ’’صدقہ‘‘ قصر کے حکم کو کہا جائے گا۔ یہ بھی کہا گیا ہے کہ قرآن مجید میں ذکر قصر خوف کا ہے نہ کہ قصر سفر کا۔ اور قصر خوف سے مراد طریقۂ جماعت میں سہولت کے مطابق تبدیلی ہے جیسا کہ آیت کے مابعد الفاظ اور احادیث میں اس کی تفصیل وارد ہے۔ گویا قصر ہیئت مراد ہے۔ قصر سفر کا ذکر صرف احادیث میںہے۔ بعض حضرات کے نزدیک (ان خفتم) یعنی خوف کی قید قصر کی بجائے مابعد کلام سے متعلق ہے، یعنی اگر تمھیں خوف ہو تو نماز کی ادائیگی کے وقت دو گروپ بنالو۔ اور (ان خفتم) سے پہلے الگ جملہ ہے، یعنی جب تم سفر میں ہو تو قصر کرنے میں کوئی گناہ نہیں۔ بہرصورت صحابہ رضی اللہ عنھم سے لے کر اب تک اتفاق ہے کہ قصر کے لیے خوف کی شرط نہیں۔ (۲) ’’قصر‘‘ سے مراد یہ ہے کہ رباعی نماز (یعنی ظہر، عصر اور عشاء) کی دو رکعت پڑھ لیا جائے۔ مغرب اور فجر اپنی اصلی حالت پر رہیں گی۔ (۳) ’’قبول کرو‘‘ اس لفظ سے بعض حضرات نے استدلال کیا ہے کہ قصر واجب ہے، حالانکہ قرآن مجید کے صریح الفاظ وجوب کی نفی کرتے ہیں۔ رسول اللہ صلی اللہ علیہ وسلم نے بھی قصر کے لیے ’’صدقہ‘‘ کا لفظ استعمال فرمایا ہے جس سے وجوب ثابت نہیں ہوتا۔ صحیح بات یہی ہے کہ قصر رخصت ہے اور اللہ تعالیٰ اس بات کو پسند کرتا ہے کہ اس کی رخصت کو قبول کیا جائے۔ اس بنا پر ہمارے نزدیک یہی فاضل ہے کہ دوران سفر نماز قصر پڑھی جائے، لیکن اگر کوئی رخصت سے فائدہ نہ اٹھاتے ہوئے نماز پوری ادا کرتا ہے تو اس کا جواز ہے جیسا کہ حضرت عائشہ اور حضرت عثمان رضی اللہ عنہما سے صراحتاً مکمل نماز (یعنی چار رکعت) پڑھنے کی صحیح روایات مذکور ہیں۔ دیکھیے: (صحیح البخاري، التقصیر، حدیث: ۱۰۹۰، و صحیح مسلم، صلاۃ المسافرین و قصرھا، حدیث: ۶۸۵، ۶۹۴) جبکہ احناف قصر کو واجب اور چار رکعت پڑھنے کو ممنوج سمجھتے ہیں، مگر اس کی کوئی دلیل پیش نہیں کی جاسکتی۔ (۴) مقام و مرتبے میں کم شخص اپنے سے افضل شخصیت سے قابل اشکال چیز کی وضاحت طلب کرسکتا ہے۔"}],[1434,"امیہ بن عبداللہ بن خالد سے روایت ہے کہ انہوں نے عبداللہ بن عمر رضی اللہ عنہم سے کہا کہ ہم قرآن میں حضر کی صلاۃ ۱؎ اور خوف کی صلاۃ کے احکام ۲؎ تو پاتے ہیں، مگر سفر کی صلاۃ کو قرآن میں نہیں پاتے؟ تو ابن عمر رضی اللہ عنہما نے ان سے کہا: بھتیجے! اللہ تعالی نے محمد صلی اللہ علیہ وسلم کو ہم میں بھیجا، اور ہم اس وقت کچھ نہیں جانتے تھے، ہم تو ویسے ہی کریں گے جیسے ہم نے محمد صلی اللہ علیہ وسلم کو کرتے ہوئے دیکھا ہے ۳؎۔\n§وضاحت\n۱؎: قرآن کے سلسلہ میں جو مطلق اوامر وارد ہیں ان کا محمل یہی حضر کی صلاۃ ہے۔ ۲؎: خوف کی صلاۃ کا ذکر آیت کریمہ: «وإذا ضربتم في الأرض فليس عليكم جناح أن تقصروا» :(النساء: 101 ) میں ہے۔ ۳؎: اور آپ نے بغیر خوف کے بھی قصر کیا ہے، لہٰذا یہ ایسی دلیل ہے جس سے اسی طرح حکم ثابت ہوتا ہے جیسے قرآن سے ثابت ہوتا ہے۔","الألباني: صحيح",{"u2":"حضرت امیہ بن عبداللہ بن خالد نے حضرت عبداللہ بن عمر رضی اللہ عنہما سے کہا: ہم قرآن مجید میں گھر کی نماز اور خوف کی نماز پاتے ہیں لیکن سفر کی نماز قرآن مجید میں نہیں پاتے۔ حضرت ابن عمر رضی اللہ عنہما نے ان سے کہا: اے میرے بھتیجے! تحقیق اللہ تعالیٰ نے حضرت محمد صلی اللہ علیہ وسلم کو ہماری طرف (نبی بنا کر) بھیجا جب کہ ہم کچھ نہیں جانتے تھے۔ ہم تو صرف اس طرح کریں گے جس طرح ہم نے محمد صلی اللہ علیہ وسلم کو کرتے دیکھا ہے۔","f2":"قرآن مجید کو بھی ہم رسول اللہ صلی اللہ علیہ وسلم ہی کی تصدیق سے مانتے ہیں، لہٰذا اصل حیثیت تو رسول اللہ صلی اللہ علیہ وسلم کی ہے۔ آپ جو فرمائیں گے، وہ ہمارے لیے حجت ہے، قرآن مجید میں ہو یا نہ ہو۔ قرآن مجید میں تو نماز کا طریقہ بھی ذکر نہیں اور نہ ان کی تعداد وغیرہ ہی کا ذکر ہے۔ جب ان باتوں کو ہم قرآن مجید میں نہ ہونے کے باوجود مانتے ہیں تو قصر سفر کو بھی ماننا چاہیے کیونکہ یہ بھی رسول اللہ صلی اللہ علیہ وسلم سے صراحتاً ثابت ہے۔ قولاً بھی فعلاً بھی۔ مزید تفصیل پیچھے گزر چکی ہے۔"}],[1435,"عبداللہ بن عباس رضی اللہ عنہم سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم مکہ سے مدینہ کے لیے نکلے، آپ صرف رب العالمین سے ہی ڈر رہے تھے ۱؎ (اس کے باوجود) آپ (راستہ بھر) دو رکعتیں ہی پڑھتے رہے۔\n§وضاحت\n۱؎: مطلب یہ ہے کہ کسی دشمن کا کوئی خوف نہیں تھا۔","الألباني: صحيح",{"u2":"حضرت ابن عباس رضی اللہ عنہما سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم مکہ سے مدینہ کی طرف نکلے (اور چار رکعت والی نمازیں) دو رکعت ہی پڑھتے رہے، حالانکہ رب العالمین کے سوا آپ کو کسی کا ڈر نہ تھا۔","f2":"حضرت ابن عباس رضی اللہ عنہ کا اشارہ حجۃ الوداع کے سفر کی طرف تھا۔ اس وقت سب دشمن مغلوب ہوچکے تھے بلکہ ختم ہوچکے تھے۔ خوف کا امکان بھی نہیں تھا۔"}],[1436,"عبداللہ بن عباس رضی اللہ عنہم کہتے ہیں کہ ہم رسول اللہ صلی اللہ علیہ وسلم کے ساتھ مکہ اور مدینہ کے درمیان سفر کرتے تھے، ہمیں اللہ تعالی کے سوا کسی کا ڈر نہیں ہوتا تھا، پھر بھی ہم دو رکعتیں ہی پڑھتے تھے۔","الألباني: صحيح",{"u2":"حضرت ابن عباس رضی اللہ عنہما بیان کرتے ہیں کہ ہم مکہ مکرمہ اور مدینہ منورہ کے درمیان رسول اللہ صلی اللہ علیہ وسلم کے ساتھ سفر کر رہے تھے۔ ہمیں اللہ تعالیٰ کے سوا کسی کا خوف نہ تھا مگر ہم (رباعی نماز) دو رکعت پڑھتے تھے۔"}],[1437,"ابن سمط کہتے ہیں کہ میں نے عمر بن خطاب رضی اللہ عنہ کو ذوالحلیفہ ۱؎ میں دو رکعت نماز پڑھتے دیکھا، تو میں نے ان سے اس سلسلہ میں سوال کیا، تو انہوں نے کہا: میں تو ویسے ہی کر رہا ہوں جیسے میں نے رسول اللہ صلی اللہ علیہ وسلم کو کرتے دیکھا ہے۔\n§وضاحت\n۱؎: جو مدینہ سے بارہ کیلو میٹر کی دوری پرہے۔","الألباني: صحيح",{"u2":"حضرت ابن سمط بیان کرتے ہیں کہ میں نے حضرت عمر بن خطاب رضی اللہ عنہ کو ذوالحلیفہ کے مقام پر (کوئی رباعی نماز) دو رکعت پڑھتے دیکھا۔ میں نے ان سے اس بارے میں پوچھا تو انھوں نے فرمایا: میں تو اسی طرح کرتا ہوں جس طرح میں نے رسول اللہ صلی اللہ علیہ وسلم کو کرتے دیکھا ہے۔"}],[1438,"انس رضی اللہ عنہ کہتے ہیں کہ میں رسول اللہ صلی اللہ علیہ وسلم کے ساتھ مدینہ سے مکہ جانے کے لیے نکلا تو آپ برابر قصر کرتے رہے یہاں تک کہ آپ واپس لوٹ آئے، آپ نے وہاں دس دن تک قیام کیا تھا۔","الألباني: صحيح",{"u2":"حضرت انس رضی اللہ عنہ بیان کرتے ہیں کہ میں رسول اللہ صلی اللہ علیہ وسلم کے ساتھ مدینہ منورہ سے مکہ مکرمہ گیا۔ آپ واپس مدینہ منورہ آنے تک نماز قصر کرتے رہے۔ آپ مکے میں دس دن ٹھہرے تھے۔","f2":"(۱) یہ حجۃ الوداع کی بات ہے اور یہ دس دن صرف مکے میں نہیں ٹھہرے تھے بلکہ مقامات حج منیٰ، مزدلفہ اور عرفات بھی اسی میں شامل ہیں۔ چار ذوالحجہ کو آپ مکہ مکرمہ پہنچے تھے۔ حج و عمرہ کے تمام ارکان ادا کرنے کے بعد چودہ ذوالحجہ کو آپ واپس مدینہ منورہ روانہ ہوگئے۔ کسی بھی جگہ آپ کا قیام چار دن سے زائد نہ تھا۔ اور چوتھا دن بھی دخول یا خروج کو شامل کرکے ہے، اسی لیے راجح بات یہ ہے کہ اگر قیام کی نیت تین (یا چار) دن کی ہے تو پھر وہ مسافر قصر نماز پڑھے، ورنہ شروع دن ہی سے پوری نماز پڑھنے، وہ اپنے آپ کو مسافر نہ سمجھے۔ (۲) کم از کم وہ کتنی مسافت ہے جس کا ارادہ ہو تو انسان اس دوران میں نماز قصر کرسکتا ہے؟ اس بارے میں علمائے کرام کا اختلاف ہے۔ مختلف آراء ہیں۔ ایک رائے یہ ہے کہ اگر کسی کا اڑتالیس میل سفر کا قصد ہو تو وہ اپنے شہر یا بستی کی حدود سے نکلنے کے بعد قصر کرسکتا ہے۔ بطور دلیل ابن عباس رضی اللہ عنہا کی حدیث پیش کی جاتی ہے۔ آپ علیہ الصلوٰۃ والسلام نے فرمایا: ’’اے اہل مکہ! چار برید (اڑتالیس میل) سے کم سفر میں نماز قصر نہ کرو، جیسے مکہ سے عسفان تک۔‘‘(سنن الدارقطني مع التعلیق المغني: ۳۸۷/۲، و السنن الکبریٰ للبیھقی: ۱۳۷/۳، ۱۳۸) لیکن یہ روایت ضعیف اور ناقابل حجت ہے۔ اس کی سند میں ایک تو اسماعیل بن عیاش ہیں، غیر شامیوں سے ان کی روایت ضعیف ہوتی ہے۔ دوسرے عبدالوہاب بن مجاہد ہیں۔ یہ بھی ضعیف ہیں۔ تفصیل کے لیے ملاحظہ ہو: [إرواء الغلیل، حدیث: ۵۶۵] لہٰذا قصر کے لیے کم از کم اڑتالیس میل کی شرط درست نہیں، نیز کسی اور مستند دلیل سے بھی اس کی تائید نہیں ہوتی۔ اس کے متعلق صحیح اور صریح ترین جو حدیث منقول ہے وہ حضرت انس بن مالک کی حدیث ہے۔ یحییٰ بن یزید ہنائی کہتے ہیں: میں نے حضرت انس بن مالک رضی اللہ عنہ سے نماز قصر کرنے کے بارے میں سوال کیا تو انھوں نے فرمایا: رسول اللہ صلی اللہ علیہ وسلم جب تین میل یا تین فرسخ کی مسافت پر جاتے تو دو رکعتیں پڑھا کرتے تھے۔ یہ شک شعبہ کو ہوا ہے۔ تین میل کی مسافت کو فرسخ (فارسی میں فرسنگ) کہتے ہیں۔ اس طرح قصر کے لیے کم از کم مسافت نو میل ہوئی۔ تین میل کی بات چونکہ مشکوک ہے، اس لیے حجت نہیں اور تین فرسخ کی مسافت احتیاط و یقین پر مبنی ہے، اس لیے سفر کی مسافت (اپنے شہر کی حد چھوڑ کر) کم از کم نو میل، یعنی تقریباً ۲۲ کلومیٹر ہوگی کیونکہ عربی میل کی مسافت انگریزی میل کی بہ نسبت زیادہ ہے۔ اور یہی موقف راحج ہے۔ واللہ أعلم۔"}],[1439,"عبداللہ بن مسعود رضی اللہ عنہ کہتے ہیں کہ میں نے رسول اللہ صلی اللہ علیہ وسلم کے ساتھ سفر میں دو رکعتیں پڑھیں، ابوبکر رضی اللہ عنہ کے ساتھ بھی دو رکعتیں پڑھیں، اور عمر بن خطاب رضی اللہ عنہ کے ساتھ بھی دو رکعتیں ہی پڑھیں۔","الألباني: صحيح الإسناد",{"u2":"حضرت عبداللہ بن مسعود رضی اللہ عنہ فرماتے ہیں کہ میں نے رسول اللہ صلی اللہ علیہ وسلم کے ساتھ سفر میں (چار رکعت والی نماز) دو رکعت پڑھی۔ حضرت ابوبکر رضی اللہ عنہ کے ساتھ بھی دو رکعت پڑھی اور حضرت عمر رضی اللہ عنہ کے ساتھ بھی دو رکعت پڑھی۔"}],[1440,"عمر رضی اللہ عنہ کہتے ہیں کہ جمعہ کی نماز دو رکعت ہے، عید الفطر کی نماز دو رکعت ہے، عید الاضحی کی نماز دو رکعت ہے، اور سفر کی نماز دو رکعت ہے، اور بزبان نبی اکرم صلی اللہ علیہ وسلم یہ سب پوری ہیں، ان میں کوئی کمی نہیں ہے۔","الألباني: صحيح",{"u2":"حضرت عمر رضی اللہ عنہ بیان کرتے ہیں کہ جمعے کی نماز، عید الفطر کی نماز، قربانی (عید الاضحیٰ) کی نماز اور سفر کی نماز نبی صلی اللہ علیہ وسلم کی زبانی دو دو رکعت ہے اور یہ مکمل ہے۔ اس میں کوئی نقص اور کمی نہیں۔","f2":"’’نقص اور کمی نہیں‘‘ کا مطلب ہے کہ یہ نمازیں مکمل ہیں، اس لیے کہ اللہ کی طرف سے یہ اتنی ہی تعداد مں مقرر ہیں۔ اسی طرح سفر میں دو رکعتیں بھی ثواب میں چار رکعتوں سے کم نہیں، اس لیے کہ یہ رخصت بھی اللہ ہی کی طرف سے ہے۔"}],[1441,"عبداللہ بن عباس رضی اللہ عنہم کہتے ہیں کہ حضر (اقامت) کی نماز تمہارے نبی کریم صلی اللہ علیہ وسلم کی زبان پر چار رکعتیں فرض ہوئیں، اور سفر کی نماز دو رکعت، اور خوف کی نماز ایک رکعت ۱؎۔\n§وضاحت\n۱؎: حذیفہ رضی اللہ عنہ کی روایت میں اس کی صراحت ہے، بعض صحابہ کرام اور ائمہ عظام اس کے قائل بھی ہیں۔","الألباني: صحيح",{"u2":"حضرت ابن عباس رضی اللہ عنہما بیان کرتے ہیں کہ گھر کی نماز تمھارے نبی صلی اللہ علیہ وسلم کی زبانی چچاار رکعت، سفر کی نماز دو رکعت اور خوف کی نماز ایک رکعت فرض کی گئی ہے۔","f2":"(۱) بظاہر روایت سے معلوم ہوتا ہے کہ سفر کی نماز ہے ہی دو رکعت، چار نہیں پڑھی جا سکتیں مگر یہ مفہوم قرآن کی آیت کریمہ اور دیگر احادیث کے صراحتاً خلاف ہے۔ اگر ایسے ہوتا تو اسے قصر نہ کہا جاتا، لہٰذا یہ مفہوم غیرمعتبر ہے۔ (۲) ’’خوف کی نماز ایک رکعت۔‘‘ جمہور اہل علم نے اس بات کو قبول نہیں کیا، وہ اس حدیث کی تاویل کرتے ہیں کہ ایک رکعت سے مراد امام کے ساتھ ایک رکعت ہے نہ کہ فی الواقع ایک رکعت کہ دوسری رکعت پڑھی نہ جائے۔ بلکہ وہ دوسری رکعت اپنے طور پر پڑھے۔ لیکن جمہور اہل علم کا یہ موقف دلائل کی روشنی میں محل نظر ہے۔ ایک رکعت نماز خوف بھی متعدد صحیح احادیث سے ثابت ہے، لہٰذا موقع و محل کی مناسبت سے ایک رکعت بھی بلاتامل پڑھی جاسکتی ہے۔ نماز خوف کی تقریباً چھ سات صورتیں احادیث میں وارد ہیں۔ تو خوف کی صورت حال کو مدنظر رکھ کر کسی بھی صورت پر عمل کیا جا سکتا ہے۔ ان میں کوئی تعارض نہیں۔ تمام واقعات اور طریقوں کو ایک ثابت کرنے کی کوشش کرنا غیر ضروری تکلیف ہے۔ موقع و محل اور ضرورت کے مطابق کسی بھی طریقے پر عمل کیا جا سکتا ہے۔ واللہ أعلم۔ مزید تفصیل کے لیے دیکھیے: (ذخیرۃ العقبی، شرح سنن النسائي، کتاب الخوف)"}],[1442,"عبداللہ بن عباس رضی اللہ عنہم کہتے ہیں کہ اللہ تعالی نے تمہارے نبی کریم صلی اللہ علیہ وسلم کی زبان پر حضر (اقامت) میں چار رکعتیں، اور سفر میں دو رکعتیں، اور خوف میں ایک رکعت نماز فرض کی ہے۔","الألباني: صحيح",{"u2":"حضرت ابن عباس رضی اللہ عنہما فرماتے ہیں: اللہ تعالیٰ نے تمھارے نبی صلی اللہ علیہ وسلم کی زبانی گھر کی نماز چار رکعت، سفر میں دو رکعت اور خوف کی الت میں ایک رکعت فرض کی ہے۔"}],[1443,"موسی بن سلمہ کہتے ہیں کہ میں نے ابن عباس رضی اللہ عنہم سے پوچھا کہ میں مکہ میں کس طرح نماز پڑھوں کہ جب میں جماعت سے نہ پڑھوں؟ تو انہوں نے کہا: دو رکعت پڑھو، ابوالقاسم صلی اللہ علیہ وسلم کی سنت (پر عمل کرو)۔","الألباني: صحيح",{"u2":"حضرت موسیٰ بن سلمہ بیان کرتے ہیں کہ میں نے حضرت ابن عباس رضی اللہ عنہما سے پوچھا کہ اگر میں باجماعت نماز نہ پاسکوں تو مکہ مکرمہ میں نماز کیسے پڑھوں؟ انھوں نے فرمایا: دو رکعتیں۔ یہ ابو القاسم صلی اللہ علیہ وسلم کی سنت ہے۔","f2":"مطلب یہ ہے کہ مسافر اگر باجماعت نماز پڑھے تو ظاہر ہے امام کے مطابق ہی پڑھے گا۔ امام حرم چونکہ مقیم ہوتے ہیں، لہٰذا وہ چار رکعتیں ہی پڑھیں گے لیکن اگر جماعت چھوٹ جائے تو مسافر دو رکعت پڑھے گا، بشرطیکہ وہ مدت اقامت سے کم ٹھہرا ہو۔ اگر اسے مدت اقامت سے زائد ٹھہرنا ہے تو وہ نماز پوری پڑھے گا۔ اس حکم میں مکہ اور غیر مکہ کا کوئی فرق نہیں۔ واللہ أعلم۔"}],[1444,"موسی بن سلمہ سے روایت ہے کہ انہوں نے ابن عباس رضی اللہ عنہم سے پوچھا: میں نے کہا: مجھ سے باجماعت نماز چھوٹ جاتی ہے اور میں بطحاء میں ہوتا ہوں، تو میں کتنی رکعت پڑھوں؟ انہوں نے کہا: دو رکعت پڑھو، ابوالقاسم صلی اللہ علیہ وسلم کی سنت (پر عمل کرو)۔","الألباني: صحيح",{"u2":"حضرت موسیٰ بن سلمہ بیان کرتے ہیں کہ میں نے حضرت ابن عباس رضی اللہ عنہما سے پوچھا: مجھ سے نماز باجماعت رہ جائے، جب کہ میں وادیٔ مکہک میں ہوں، تو آپ کے خیال کے مطابق میں کتنی رکعت نماز پڑھوں؟ انھوں نے فرمایا: دو رکعت۔ یہ رسول اللہ صلی اللہ علیہ وسلم کی سنت ہے۔"}],[1445,"حارثہ بن وہب خزاعی رضی اللہ عنہ کہتے ہیں کہ میں نے نبی اکرم صلی اللہ علیہ وسلم کے ساتھ منی میں دو ہی رکعت پڑھی، ایک ایسے وقت میں جس میں کہ لوگ سب سے زیادہ مامون و بےخوف تھے، اور تعداد میں زیادہ تھے۔","الألباني: صحيح",{"u2":"حضرت حارثہ بن وہب خزاعی رضی اللہ عنہ بیان کترے ہیں کہ میں نے نبی صلی اللہ علیہ وسلم کے ساتھ منیٰ میں دو رکعتیں پڑھیں، حالانکہ آپ انتہائی امن کی حالت میں تھے اور آپ کے ساتھی بھی بہت زیادہ تھے۔","f2":"منیٰ می چونکہ سب حاجی مسافر ہی ہوتے ہیں، لہٰذا منیٰ میں سب حاجی قصر کریں گے۔ امام احمد رحمہ اللہ کے نزدیک یہ قصر حج کی بنا پر ہے سفر کی بنا پر نہیں۔ احناف کے نزدیک جو لوگ منیٰ سے مسافت قصر کے اندر اندر رہتے ہیں، وہ پوری نماز پڑھیں گے، مگر یہ کسی حدیث سے ثابت نہیں اور نہ کسی حدیث میں یہ ذکر ہے کہ رسول اللہ صلی اللہ علیہ وسلم کے ساتھ حج کرنے والوں میں کوئی ایسی تفریق کی گئی ہو، مثلاً: یہ نہیں کہا گیا کہ مکہ والے قصر نہ کریں وغیرہ۔ صحیح بات یہی ہے کہ سب حاجی منیٰ میں قصر کریں گے۔ (قصر کے لیے خوف کی بحث پیچھے گزر چکی ہے۔)"}],[1446,"حارثہ بن وہب رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے ہمیں منی میں دو رکعت پڑھائی، ایک ایسے وقت میں جس میں لوگ تعداد میں زیادہ تھے، اور سب سے زیادہ مامون و بےخوف تھے۔","الألباني: صحيح",{"u2":"حضرت حارثہ بن وہب خزاعی رضی اللہ عنہ بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے ہمیں منی میں دو رکعتیں پڑھائیں حالانکہ لوگ بہت زیادہ تھے اور انتہائی امن کی حالت میں تھے۔"}],[1447,"انس بن مالک رضی اللہ عنہ کہتے ہیں کہ میں نے رسول اللہ صلی اللہ علیہ وسلم کے ساتھ اور ابوبکر اور عمر رضی اللہ عنہم کے ساتھ منی میں دو رکعت پڑھی، اور عثمان رضی اللہ عنہ کے ساتھ بھی ان کی خلافت کے شروع میں دو ہی رکعت پڑھی۔","الألباني: صحيح لغيره",{"u2":"حضرت انس بن مالک رضی اللہ عنہ فرماتے ہیں کہ میں نے منیٰ میں رسول اللہ صلی اللہ علیہ وسلم کے ساتھ، حضرت ابوبکر اور حضرت عمر رضی اللہ عنہما کے ساتھ دو رکعتیں پڑھیں اور حضرت عثمان رضی اللہ عنہ کے ساتھ بھی ان کی امارت کے ابتدائی زمانے میں دو رکعتیں ہی پڑھیں۔","f2":"’’ابتدائی زمانے میں‘‘ یعنی بعد میں حضرت عثمان رضی اللہ عنہ نے منیٰ میں پوری نماز شروع کر دی تھی، کیوں؟ اس کی مختلف وجوہات بیان کی جاتی ہیں: ایک یہ کہ پوری پڑھنا بھی جائز ہے۔ لوگوں کو غلط فہمی ہونے لگی تھی کہ نماز ہر حال میں دو رکعت ہی ہے کیونکہ خلیفہ جب بھی آتا ہے، دو رکعت پڑھاتا ہے، ہمارے ائمہ خواہ مخواہ چار پڑھاتے ہیں۔ یہ غلط فہمی دور کرنے کے لیے نماز مکمل پڑھائی۔ حضرت عثمان رضی اللہ عنہ کا خیال تھا کہ قصر صرف سفر کی حالت میں ہوتی ہے۔ جب آدمی کسی جگہ ٹھہر جائے اور اسے سفر کی مشکلات درپیش نہ ہوں تو قصر نہ کرے، خواہ تھوڑے دن ہی ٹھہرے۔ چونکہ منیٰ میں تتین دن (یا چار دن) آرام و سکون سے رہائش ہوتی ہے، لہٰذا پوری نماز پڑھنی چاہیے۔ آپ نے مکہ مکرمہ میں شادی کرلی تھی۔ ان کے علاوہ اور بھی وجوہات بیان کی گئی ہیں لیکن حافظ ابن حجر رحمہ اللہ نے ان تمام کارد کرتے ہوئے لکھا ہے یہ وجوہات درست نہیں۔ بنابریں سنت یہی ہے کہ سفر میں دو رکعت نماز ادا کی جائے جیسا کہ رسول اللہ صلی اللہ علیہ وسلم کے عمل سے ثابت ہے۔ و خیر الھدي ھدي محمد صلی اللہ علیہ وسلم۔ نیز حضرت ابوبکر اور حضرت عمر رضی اللہ عنہا کا بھی اسی پر عمل تھا۔ حضرت عثمان رضی اللہ عنہ کا پوری نماز پڑھنا ان کا ذاتی اجتہاد تھا، وہ شاید اس لیے پڑھتے ہوں کہ سفر میں پوری نماز پڑھنا بھی جائز ہے۔ واللہ أعلم۔ مزید تفصیل کے لیے دیکھیے: (ذخیرۃ العقبی شرح سنن النسائي: ۳۵۸-۳۵۴/۱۶)"}],[1448,"عبداللہ بن مسعود رضی اللہ عنہ کہتے ہیں کہ میں نے منی میں رسول اللہ صلی اللہ علیہ وسلم کے ساتھ دو رکعت پڑھی۔","الألباني: صحيح",{"u2":"حضرت عبداللہ بن مسعود رضی اللہ عنہ سے منقول ہے، فرمایا: میں نے رسول اللہ صلی اللہ علیہ وسلم کے ساتھ منیٰ میں دورکعتیں پڑھیں۔"}],[1449,"عبدالرحمٰن بن یزید کہتے ہیں کہ عثمان رضی اللہ عنہ نے منی میں چار رکعت پڑھی یہاں تک کہ اس کی خبر عبداللہ بن مسعود رضی اللہ عنہ کو ہوئی تو انہوں نے کہا: میں نے تو رسول اللہ صلی اللہ علیہ وسلم کے ساتھ دو ہی رکعت پڑھی ہے۔","الألباني: صحيح",{"u2":"حضرت عبدالرحمٰن بن یزید سے مروی ہے کہ حضرت عثمان رضی اللہ عنہ نے منیٰ میں چار رکعتیں پڑھیں حتی کہ یہ بات حضرت عبداللہ بن مسعود رضی اللہ عنہ کو پہنچی تو انھوں نے فرمایا: میں نے تو رسول اللہ صلی اللہ علیہ وسلم کے ساتھ دو رکعتیں ہی پڑھی ہیں۔"}],[1450,"عبداللہ بن عمر رضی اللہ عنہم کہتے ہیں کہ میں نے نبی اکرم صلی اللہ علیہ وسلم کے ساتھ منی میں دو رکعت پڑھی، اور ابوبکر رضی اللہ عنہ کے ساتھ بھی دو رکعت، اور عمر رضی اللہ عنہ کے ساتھ بھی دو ہی رکعت پڑھی۔","الألباني: صحيح",{"u2":"حضرت ابن عمر رضی اللہ عنہما بیان کرتے ہیں کہ میں نے نبی صلی اللہ علیہ وسلم کے ساتھ منیٰ میں دو رکعتیں پڑھیں۔ حضرت ابوبکر رضی اللہ عنہ کے ساتھ دو رکعتیں پڑھیں اور حضرت عمر رضی اللہ عنہ کے ساتھ بھی دو رکعتیں پڑھیں۔"}],[1451,"عبداللہ بن عمر رضی اللہ عنہم کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے منی میں دو رکعت پڑھی، اور ابوبکر اور عمر رضی اللہ عنہم نے بھی وہاں دو ہی رکعت پڑھی، اور عثمان رضی اللہ عنہ نے بھی اپنی خلافت کے شروع میں دو ہی رکعت پڑھی۔","الألباني: صحيح",{"u2":"حضرت عبداللہ بن عمر رضی اللہ عنہما بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے منیٰ میں دو رکعتیں پڑھیں۔ حضرت ابوبکر رضی اللہ عنہ نے بھی یہاں دو رکعتیں ہی پڑھیں۔ حضرت عمر رضی اللہ عنہ نے بھی دو ہی پڑھیں۔ اور حضرت عثمان رضی اللہ عنہ نے بھی اپنی خلافت کی ابتدا میں دو رکعتیں ہی پڑھیں۔","f2":"(۱) بعد میں کسی وجہ سے اجتہادی طور پر حضرت عثمان رضی اللہ عنہ نے حج کے موقع پر منیٰ میں چار رکعتیں شروع کر دی تھیں۔ اور محدثین نے اس کی متعدد وجوہ بیان فرمائی ہیں جس کی تفصیل پیچھے گزر چکی ہے۔ اور اسی طرح حضرت عائشہ رضی اللہ عنہا کی بابت بھی مروی ہے کہ وہ بھی دوران سفر میں پوری نماز پڑھ لیتی تھیں۔ ان احادیث کے پیش نظر علمائے محققین نے یہ موقف اختیار کیا ہے کہ انسان کو اللہ تعالیٰ کی دی ہوئی اس رخصت سے فائدہ اٹھانا چاہیے، نیز فرمان نبوی بھی ہے کہ اللہ تعالیٰ اس کو پسند کرتا ہے کہ اس کی رخصت کو قبول کیا جائے۔ بنابریں ہمارے نزدیک افضل یہ ہے کہ دوران سفر نماز قصر پڑھی جائے، لیکن اگر کوئی رخصت سے فائدہ نہ اٹھائے اور پوری نماز پڑھے تو اس کی بھی گنجائش ہے اسے بدعت وغیرہ نہیں کہنا چاہیے۔ واللہ أعلم۔ (۲) مندرجہ بالا تمام روایات میں دو رکعت سے مراد صرف وہ نماز ہے جو اصل رباعی، یعنی چار رکعت والی ہے، ورنہ مغرب ہر حال میں تین رکعت ہے اور فجر ہر حال میں دو رکعت۔ اور یہ متفقہ بات ہے۔"}],[1452,"انس بن مالک رضی اللہ عنہ کہتے ہیں کہ ہم لوگ رسول اللہ صلی اللہ علیہ وسلم کے ساتھ مدینہ سے مکہ جانے کے لیے نکلے، تو آپ ہمیں دو رکعت پڑھاتے رہے یہاں تک کہ ہم واپس لوٹ آئے، یحیی بن ابی اسحاق کہتے ہیں: میں نے انس رضی اللہ عنہ سے پوچھا: کیا آپ نے مکہ میں قیام کیا تھا؟ انہوں نے کہا: ہاں، ہم نے وہاں دس دن قیام کیا تھا۔","الألباني: صحيح",{"u2":"حضرت انس بن مالک رضی اللہ عنہ سے منقول ہے، فرماتے ہیں، ہم رسول اللہ صلی اللہ علیہ وسلم کے ساتھ مدینہ منورہ سے مکہ مکرمہ کو نکلے۔ آپ واپس مدینہ تشریف لانے تک ہمیں دو رکعت ہی پڑھاتے رہے۔ (شاگرد ابواسحق بیان کرتے ہیں کہ) میں نے کہا: کیا آپ مککہ میں ٹھہرے تھے؟ انھوں نے فرمایا: ہاں، ہم مکہ میں دس دن ٹھہرے تھے۔","f2":"یہ حجۃ الوداع کی بات ہے۔ لیکن آپ دس دن صرف مکہ میں نہیں بلکہ منی، مزدلفہ، عرفات میں مجموعی طور پر دس دن ٹھہرے تھے۔ مکہ میں آپ کی مسلسل رہائش پورے چار دن رہی ہے۔ چار ذوالحجہ کی صبح کو مکہ میں داخل ہوئے اور آٹھ کی صبح کو منی روانہ ہوگئے۔ اسی بنا پر امام احمد بن حنبل رحمہ اللہ کا یہ خیال ہے کہ اکیس نمازیں ایک جگہ ٹھہر کر پڑھنی ہوں تو قصر کرے، زیادہ ٹھہرنا ہو تو شروع سے مکمل پڑھے۔ امام شافعی رحمہ اللہ کا خیال ہے کہ آنے جانے کا دن نکال کر تین دن ٹھہرنا ہو تو قصر کرے اور اگر اس سے زائد ٹھہرنا ہو تو شروع دن سے پوری پڑھے۔ یہ دونوں اقوال ملتے جلتے ہیں اور ان کا نتیجہ ایک ہی ہے۔ اوری ہی صحیح اور راجح موقف ہے۔ واللہ أعلم۔ احناف پندرہ دن کے قیام میں قصر کے قائل ہیں اور زائد کی صورت میں پوری نماز پڑھنے کے قائل ہیں۔ جس کی تفصیل آگے آ رہی ہے۔"}],[1453,"عبداللہ بن عباس رضی اللہ عنہم سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم مکہ میں پندرہ دن ٹھہرے رہے ۱؎ اور آپ دو دو رکعتیں پڑھتے رہے۔\n§وضاحت\n۱؎: یہ فتح مکہ کی بات ہے اور دس دن کے قیام والی روایت حجۃ الوداع کے موقع کی ہے، فتح مکہ کے موقع پر مکہ میں نبی اکرم صلی اللہ علیہ وسلم نے کتنے دنوں تک قیام کیا اس سلسلہ میں روایتیں مختلف ہیں، صحیح بخاری کی روایت میں ۱۹ دن کا ذکر ہے، اور ابوداؤد کی ایک روایت اٹھارہ دن، اور دوسری میں سترہ دن کا ذکر ہے، تطبیق اس طرح دی جاتی ہے کہ جس نے دخول اور خروج کے دنوں کو شمار نہیں کیا، اس نے سترہ کی روایت کی ہے اور جس نے دخول کا شمار کیا اور خروج کا نہیں یا خروج کا شمار کیا اور دخول کا نہیں، اس نے اٹھارہ کی روایت کی ہے، رہی پندرہ دن والی مؤلف کی روایت تو یہ شاذ ہے، اور اگر اسے صحیح مان لیا جائے تو یہ کہا جا سکتا ہے کہ راوی نے سمجھا کہ اصل ۱۷ دن ہے، پھر اس میں سے دخول اور خروج کو خارج کر کے ۱۵ دن کی روایت کی۔","الألباني: صحيح بلفظ تسعة عشر يوما",{"u2":"حضرت ابن عباس رضی اللہ عنہما سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم مکہ مکرمہ میں پندرہ دن ٹھہرے۔ دو دو رکعت پڑھتے رہے۔","f2":"مکہ کی بات ہے جو سنہ ۸ ہجری میں ہوا تھا۔ صحیح بخاری میں ابن عباس رضی اللہ عنہما سے انیس دن ٹھہرنے کی روایت ہے۔ اور ان کا قول بھی یہی ہے کہ جب ہم انیس دن سے زائد ٹھہریں گے تو نماز پوری پڑھیں گے۔ بعض روایات میں مکہ میں آپ کی اقامت اٹھارہ یا سترہ دن بھی ہے، یعنی آنے جانے کا دن شامل کرکے انیس دن، خالص اقامت سرہ دن۔ کسی ایک دن کو نکال لیں تو اٹھارہ دن۔ گویا کوئی اختلاف نہیں، البتہ پندرہ دن کی روایت صحیح نہیں کیونکہ یہ اصح روایات کے خلاف ہے بلکہ یہ کسی راوی کا تصرف ہے۔ محقق عصر شیخ البانی رحمہ اللہ نے"}],[1454,"علاء بن حضرمی رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"مہاجر حج و عمرہ کے ارکان و مناسک پورے کرنے کے بعد (مکہ میں) تین دن تک ٹھر سکتا ہے\"۔","الألباني: صحيح",{"u2":"حضرت علا ء بن حضرمی رضی اللہ عنہ سے منقول ہے،\nرسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \" مہاجر شخص اپنا حج و عمرہ پورا\nکرنے کے بعد صرف تین دن مکے میں رہ سکتا ہے۔\"","f2":"یہ حدیث ائمہ ثلا ثہ (امام مالک، امام شافعی اور امام احمد رحمتہ اللہ علیہ) کی دلیل ہے کہ نبی صلی اللہ علیہ وسلم نے مہاجرین کوتین دن سے زائد مکہ میں ٹھہرنے سے اسی لیے روکا ہے کہ اگر ان میں سے کو ئی تین دن سے زائد ٹھہر تا تو وہ مقیم بن جاتا اور مہاجر کو اپنی ہجرت والی جگہ مین مقیم ہونا جائز نہیں، ورنہ ہجر ت ختم ہوجائے گی۔ اس سے ثابت ہو ا کہ کسی جگہ میں تین دن تک ٹھہرنے والا تو مسا فر ہے مگر زائد ٹھہرنے والا مقیم ہے، لٰہذا وہ نماز پور ی پر ھے گا۔ باقی ر اہ رسو ل اللہ صلی اللہ علیہ وسلم کا مکہ میں فتح پر تین دن سے زائد ٹھہرنا تو ہ فتح کی تکمیل کے لیے تھا نہ، نہ کہ زائد ازشرعی ضروریات یا وہ قصد، یعنی تر دو کی صورت میں تھا۔"}],[1455,"علاء بن حضرمی رضی اللہ عنہ کہتے ہیں کہ نبی اکرم صلی اللہ علیہ وسلم نے فرمایا: \"مہاجر اپنے نسک (حج و عمرہ کے ارکان) پورے کرنے کے بعد مکہ میں تین دن ٹھر سکتا ہے\"۔","الألباني: صحيح",{"u2":"حضرت علاء بن حضرمی رضی اللہ عنہ سے روایت ہے، نبی صلی اللہ علیہ وسلم نے فرمایا:\" (مکے سے) ہجرے کرنے والا اپنا حج و عمرہ کرنے کے بعد تین دن (مکے میں) ٹھہرسکتا ہے۔\""}],[1456,"ام المؤمنین عائشہ رضی اللہ عنہا سے روایت ہے کہ وہ رسول اللہ صلی اللہ علیہ وسلم کے ساتھ عمرہ کرنے کے لیے مدینہ سے مکہ کے لیے نکلیں یہاں تک کہ جب وہ مکہ آ گئیں، تو انہوں نے عرض کیا: اللہ کے رسول! میرے ماں باپ آپ پر قربان ہوں! آپ نے نماز قصر پڑھی ہے، اور میں نے پوری پڑھی ہے، اور آپ نے روزہ نہیں رکھا ہے اور میں نے رکھا ہے تو آپ نے فرمایا: \"عائشہ! تم نے اچھا کیا\"، اور آپ نے مجھ پر کوئی نکیر نہیں کی۔","الألباني: منكر",{"u2":"حضرت عائشہ رضی اللہ عنہا سے روایت ہے کہ میں رسو اللہ صلی اللہ علیہ وسلم کے ساتھ مدینہ منورہ سے مکہ مکرمہ عمرہ کرنے گئی حتٰی کہ جب میں مکہ آئی تو میں نے کاکہا: اے اللہ کے رسو ل! میرے ماں با پ ا ٓپ پر فدا ہوں ْ! آپ نماز قصر کرتے رہے، میں پوری پڑ ھتی رہی۔ ا ٓپ روزہ چھوڑتے رہے، میں رکھتی رہی۔ ا ٓ پ نے فر مایا:\"عائشہ! تونے ٹھیک کیا۔\" ا ٓپ نے مجھ پر اس بات کا عیب نہیں لگا یا-","f2":"اس حدیث کا باب سے تعلق یہ ہے کہ سفر کتنا بھی لمبا ہو اور اس میں کتنا عرصہ بھی لگے،نماز قصر کی جا سکتی ہے۔ سفر کے دوران میں کوئی حد نہیں۔"}],[1457,"وبرہ بن عبدالرحمٰن کہتے ہیں کہ ابن عمر رضی اللہ عنہم سفر میں دو رکعت پر اضافہ نہیں کرتے تھے، نہ تو اس سے پہلے نماز پڑھتے اور نہ ہی اس کے بعد، تو ان سے کہا گیا: یہ کیا ہے؟ تو انہوں نے کہا: میں نے رسول اللہ صلی اللہ علیہ وسلم کو اسی طرح کرتے دیکھا ہے۔","الألباني: حسن صحيح لغيره",{"u2":"حضرت وبرہ بن عبدالرحمان سے روایت ہے عبداللہ بن عمر سفر میں دو رکعت فرض سے ذیا دہ نہیں پڑتے تھے نہ فرض سے پہلے سنت پڑتے تھے نہ فرض کے بعد ایک شخص نے پوچھا یہ کیا ہے انہوں نے کہا میں نے رسول اللہ صلی اللہ علیہ وسلم کو ایسا کرتے دیکھا ہے۔","f2":"فرض نمازوں کی تمام سنن رواتب کے سوا سفر میں نفل پڑھنا قطعاً منع نہیں بلکہ رسول اللہ صلی اللہ علیہ وسلم اور صحابۂ کرام رضی اللہ عنھم سے مطلق نوافل پڑھنا ثابت ہیں۔ رسول اللہ صلی اللہ علیہ وسلم اور آپ کے صحابۂ کرام رضی اللہ عنھم سفر میں سواری پر نفل نماز (وتر وغیرہ) پڑھ لیا کرتے تھے۔ اس میں وہ استقبال قبلہ (قبلہ رخ ہونے) کا بھی سوائے وقتِ آغاز کے، کوئی اہتمام نہیں کرتے تھے، بلکہ سواری کا رخ اور منہ جس طرف بھی ہوتا اسی طرف نماز پڑھ لیتے۔ اس طرح صرف نوافل میں کرتے، فرض نماز سواری سے اتر کر اور قبلہ رخ ہوکر پڑھا کرتے تھے۔ رسول اللہ صلی اللہ علیہ وسلم اور صحابۂ کراام رضی اللہ عنھم کا سفر میں یہ عام معمول تھا۔ صحیحین کی احادیث میں اس کی مکمل صراحت موجود ہے۔ دیکھیے: (صحیح البخاري، التقصیر، حدیث: ۱۱۰۰-۱۱۹۳، و صحیح مسلم، صلاۃ المسافرین……، حدیث: ۷۰۲-۷۰۰)\nرسول اللہ صلی اللہ علیہ وسلم نے صبح کی سنتوں کی بہت تاکید فرمائی ہے۔ آپ صلی اللہ علیہ وسلم خود بھی صبح کی سنتوں کا خاص اہتمام و التزام فرمایا کرتے تھے۔ ام المومنین سیدہ عائشہ صدیقہ عفیفہ طاہرہ رضی اللہ عنہا فرماتی ہیں: رسول اللہ صلی اللہ علیہ وسلم جس قدر صبح کی سنتوں کا التزام و اہتمام اور ان پر محافظت و مداومت فرماتے تھے، اس قدر کسی اور نفل نماز پر نہیں فرماتے تھے۔ (صحیح البخاري، التھجد، حدیث: ۱۱۲۹) نبی صلی اللہ علیہ وسلم نے صبح کی سنتوں کی بابت فرمایا ہے: ’’فجر کی دو رکعت (سنتیں) دنیا و مافیہا، یعنی جو کچھ دنیا میں ہے، اس سب سے بہتر ہیں۔‘‘ (صحیح مسلم، صلاۃ المسافرین، حدیث: ۷۲۵) نیز یہ سنتیں نبی صلی اللہ علیہ وسلم کو ازحد محبوب اور پیاری تھیں۔ رسول اللہ صلی اللہ علیہ وسلم صبح کی سنتوں کا کس قدر التزام فرماتے تھے؟ اس کا اندازہ اس بات سے بخوبی ہوتا ہے کہ جب رسول اللہ صلی اللہ علیہ وسلم غزوۂ خیبر سے واپس آتے ہوئے رات کے پچھلے پہر سو گئے اور آپ صلی اللہ علیہ وسلم سمیت صحابۂ کرام رضی اللہ عنھم میں سے کوئی بھی طلوع آفتاب سے پہلے نہ اٹھ سکا تو آپ نے صحابۂ کرام رضی اللہ عنھم سے فرمایا: ’’اپنی سواریاں لے کر اس وادی سے نکل چلو، اس جگہ شیطان رہتا ہے۔‘‘ پھر آپ نے وضو کیا اس کے بعد صبح کی دو سنتیں پڑھیں اور پھر صبح کے فرض باجماعت ادا کیے۔ (صحیح مسلم، المساجد، حدیث: ۶۸۰) البتہ جو نماز قصر کی جاتی ہے، یعنی ظہر، عصر اور عشاء، ان میں آپ سے سنتیں پڑھنے کا ذکر نہیں ملتا، لہٰذا قصر کی جائے تو سنتیں نہ پڑھی جائیں کیونکہ قصر تو تخفیف کے لیے ہے۔ سنتیں پڑھنے سے تخفیف ختم ہو جاتی ہے۔ مغرب و عشاء کو جمع کرتے وقت مغرب کی سنتیں نہیں پڑھی جائیں گی۔ سفر کے دوران میں تہجد وغیرہ بھی پڑھی جا سکتی ہے۔ دلائل کے عموم سے اس کی تائید ہوتی ہے۔ واللہ أعلم۔"}],[1458,"حفص بن عاصم کہتے ہیں کہ میں ابن عمر رضی اللہ عنہم کے ساتھ ایک سفر میں تھا تو انہوں نے ظہر اور عصر کی نمازیں دو دو رکعت پڑھیں، پھر اپنے خیمے کی طرف لوٹنے لگے، تو لوگوں کو دیکھا کہ وہ نماز پڑھ رہے ہیں، تو انہوں نے پوچھا: یہ لوگ (اب) کیا کر رہے ہیں؟ میں نے کہا: یہ لوگ سنت پڑھ رہے ہیں، تو انہوں نے کہا: اگر میں اس سے پہلے یا بعد میں کوئی نماز پڑھنے والا ہوتا تو میں فرض ہی کو پورا کرتا، میں رسول اللہ صلی اللہ علیہ وسلم کے ساتھ رہا، آپ سفر میں دو رکعت سے زیادہ نہیں پڑھتے تھے، ابوبکر کے ساتھ رہا یہاں تک کہ ان کا انتقال ہو گیا، عمر اور عثمان رضی اللہ عنہم کے ساتھ بھی رہا یہ سب لوگ اسی طرح کرتے تھے۔","الألباني: صحيح",{"u2":"حضرت حفص بن عاصم بیان کرتے ہیں کہ میں حضرت ابن عمر رضی اللہ عنہما کے ساتھ ایک سفر میں تھا انھوں نے ظہر اور عصر دو دو رکعت پڑھیں۔ پھر اپنی بچھی ہوئی چٹائی کی طرف گئے۔ انھوں نے کچھ لوگوں کو دیکھا کہ وہ نفل (سنتیں) پڑھ رہے ہیں۔ انھوں نے پوچھا: یہ لوگ کیا پڑھ رہے ہیں؟ میں نے عرض کیا: نفل پڑھ رہے ہیں۔ انھوں نے فرمایا: اگر میں فرضوں سے پہلے یا بعد میں سنتیں پڑھتا تو میں فرض ہی مکمل پڑھ لیتا۔ میں رسول اللہ صلی اللہ علیہ وسلم کے ساتھ رہا ہوں، آپ تو سفر میں دو رکعتوں سے زائد نہ پڑھتے تھے۔ اسی طرح حضرت ابوبکر رضی اللہ عنہ کے ساتھ رہا۔ حتی کہ وہ فوت ہوگئے۔ اسی طرح حضرت عمر اور حضرت عثمان رضی اللہ عنہما کے ساتھ۔","f2":"حضرت عبداللہ بن عمر رضی اللہ عنہما نے سنتیں پڑھنے پر انکار کیا کہ اگر سنتیں ہی پڑھنی ہیں تو اس کی بجائے بہتر تھا کہ فرض چار پڑھ لیے جاتے کیونکہ فرض نوافل سے زیادہ ثواب رکھتے ہیں جب کہ شریعت کا مقصد مسافر سے تخفیف کرنا ہے۔"}],[1459,"ابوبکرہ رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"سورج اور چاند اللہ تعالی کی نشانیوں میں سے دو نشانیاں ہیں، ان دونوں کو کسی کے مرنے اور کسی کے پیدا ہونے سے گرہن نہیں لگتا، بلکہ اللہ تعالی ان کے ذریعہ اپنے بندوں کو ڈراتا ہے\"۔","الألباني: صحيح",{"u2":"حضرت ابوبکرہ رضی اللہ عنہ سے روایت ہے، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’سورج اور چاند اللہ تعالیٰ کی دو نشانیاں ہیں۔ انھیں کسی کی موت اور پیدائش کی وجہ سے گرہن نہیں لگتا بلکہ اللہ تعالیٰ ان کے ذریعے سے اپنے بندوں کو ڈراتا ہے۔‘‘","f2":"(۱) ’’دو نشانیاں‘‘ یعنی بذات خود سورج اور چاند اللہ کی نشانیاں ہیں۔ جن سے اللہ تعالیٰ کی عظیم قدرت کا پتہ چلتا ہے۔ یا انھیں گرہن لگنا اللہ تعالیٰ کی نشانیاں ہیں۔ جب یہ دونوں اللہ تعالیٰ کے قبضہ و قدرت اور تصرف میں ہیں تو کسی کی موت اور پیدائش ان میں کیا اثر کرسکتی ہے؟ (۲) اس دور کے لوگ اعتقاد رکھتے تھے کہ کوئی بڑا شخص فوت یا پیدا ہو تو سورج یا چاند کو گرہن لگت ہے۔ مذکورہ گرہن نبیٔ اکرم صلی اللہ علیہ وسلم کے فرزند حضرت ابراہیم رضی اللہ عنہ کی وفات پر لگا تھا۔ لوگوں نے اسے ان کی وفات سے متعلق کیا تو رسول اللہ صلی اللہ علیہ وسلم نے تردید فرمائی۔ (صحیح البخاري، الکسوف، حدیث: ۱۰۴۳، و صحیح مسلم، الکسوف، حدیث: ۹۱۵) (۳) ماہرین فلکیات کے نزدیک چاند کی روشنی اپنی نہیں بلکہ سورج کی روشنی اس پر پڑنے سے یہ روشن نظر آتا ہے۔ جب سورج کی روشنی اس پر نہیں پڑتی تو یہ نظر نہیں آتا، لہٰذا جب زمین سورج اور چاند کے درمیان میں آ جائے تو زمین کی رکاوٹ کی وجہ سے چاند پر روشنی نہیں پڑتی۔ اسے چاند گرہن کہتے ہیں۔ اور یہ قمری مہینے کی تیرہ یا چودہ تاریخ کو ہوسکتا ہے، آگے پیچھے نہیں۔ اور جب زمین اور سورج کے درمیان چاند آ جائے تو سورج کے جتنے حصے کے سامنے چاند آ جائے گا، وہ زمین پر نظر نہیں آئے گا۔ اسے سورج گرہن کہتے ہیں اور یہ قمری مہینے کے آخری ایک دو دنوں میں ہوسکتا ہے، آگے پیچھے نہیں۔ سورج اور چاند کا گہنا زمین اور چاند کی رفتار کے حساب سے ہے، لہٰذا وقت سے پہلے ان کا ٹھیک ٹھیک حساب لگا کر بتایا جا سکتا ہے۔ (۴) ’’ڈراتا ہے‘‘ ویسے سورج کا غروب ہونا اور مہینے کے شروع اور آخر میں پورے چاند کا نظر نہ آنا بھی گرہن کے مثل ہی ہے مگر چونکہ یہ روز مرہ ہیں، اس لیے ان پر کوئی حیرت یا اچنبھا نہیں ہوتا مگر گرہن کبھی کبھار ہوتا ہے، اس لیے اس پر حیرت ہوتی ہے اور انسان خوف زدہ ہو جاتا ہے اور اللہ تعالیٰ کی نشانیوں سے نصیحت حاصل کرنے کے زیادہ قریب ہو جاتا ہے۔ اور ایسے موقع پر حکم بھی یہی ہے کہ توبہ و استغفار اور اللہ کی طرف رجوع کیا جائے۔"}],[1460,"عبدالرحمٰن بن سمرہ رضی اللہ عنہ کہتے ہیں کہ میں مدینہ میں تیر اندازی میں مشغول تھا، اتنے میں سورج کو گرہن لگ گیا، میں نے اپنے تیروں کو سمیٹا اور دل میں ارادہ کیا کہ رسول اللہ صلی اللہ علیہ وسلم نے سورج گرہن کے موقع پر کیا نئی بات کی ہے، اسے چل کر ضرور دیکھوں گا، میں آپ کے پیچھے کی جانب سے آپ کے پاس آیا، آپ مسجد میں تھے، تسبیح و تکبیر اور دعا میں لگے رہے، یہاں تک کہ سورج صاف ہو گیا، پھر آپ کھڑے ہوئے، اور دو رکعت نماز پڑھی، اور چار سجدے کیے ۱؎۔\n§وضاحت\n۱؎: ظاہر حدیث سے پتہ چلتا ہے کہ آفتاب صاف ہو جانے کے بعد آپ صلی اللہ علیہ وسلم نے نماز پڑھی، حالانکہ کسوف کی نماز گرہن صاف ہو جانے کے بعد درست نہیں، لہٰذا اس کی تاویل اس طرح کی جاتی ہے کہ عبدالرحمٰن بن سمرہ رضی اللہ عنہ نے آپ کو نماز ہی کی حالت میں کھڑا پایا، آپ تسبیح و تکبیر نماز ہی میں کر رہے تھے جیسا کہ مسلم کی ایک روایت میں ہے۔ «فأتیناہ وھو قائم فی ال صلاۃ، رافع یدیہ، فجعل یسبح ویحمد ویہلل ویکبر ویدعو» \" چنانچہ ہم نبی اکرم صلی اللہ علیہ وسلم کے پاس آئے اور آپ کو اس حال میں پایا کہ آپ نماز میں کھڑے اپنے ہاتھوں کو اٹھائے ہوئے تھے اور اللہ کی تسبیح و تحمید اور تہلیل و تکبیر کے ساتھ ساتھ دعا بھی کر رہے تھے \"، بعضوں نے کہا ہے یہ دونوں رکعتیں نماز کسوف سے الگ بطور شکرانہ کے تھیں، لیکن یہ قول ضعیف ہے، اور دوسری روایات کے ظاہر کے خلاف ہے۔","الألباني: صحيح",{"u2":"حضرت عبدالرحمٰن بن سمرہ رضی اللہ عنہ بیان کرتے ہیں کہ میں مدینہ منورہ میں تیر اندازی کر رہا تھا کہ سورج کو گرہن لگ گیا۔ میں نے اپنے تیر اکٹھے کیے اور دل میں عزم کیا کہ میں ضرور جاکر دیکھوں گا کہ اللہ کے رسول صلی اللہ علیہ وسلم اس موقع پر کیا طریقہ اختیار فرماتے ہیں۔ میں آپ کی پچھلی جانب سے آپ کے قریب آیا۔ اس وقت آپ مسجد میں تھے۔ آپ تسبیح و تکبیر پڑھنے لگے اور دعا کرنے لگے حتی کہ گرہن ختم ہوگیا، پھر آپ اٹھے اور آپ نے دو رکعتیں پڑھیں اور چار سجدے کیے۔","f2":"(۱) سورج یا چاند گرہن لگنے سے پہلے دو رکعتی پڑھی جائیں گی، جس قدر لمبی پڑھی جا سکیں۔ پھر تسبیحات، تکبیرات پڑھی اور دعائیں مانگی جائیں گی تا آنکہ گرہن ختم ہو جائے۔ (۲) مذکورہ حدیث سے معلوم ہوتا ہے کہ شاید تسبیحات، تکبیرات اور دعائیں پہلے ہیں اور نماز بعد میں۔ لیکن یہ بات درست نہیں کیونکہ اس موضوع سے متعلق جمیع روایات اس کے خلاف ہیں بلکہ صحیح مسلم میں عبدالرحمن بن سمرہ رضی اللہ عنہ ہی سے مروی ہے، وہ بیان کرتے ہیں کہ میں جب مسجد میں پہنچا تو رسول اللہ صلی اللہ علیہ وسلم نماز میں تھے۔ دیکھیے: (صحیح مسلم، الکسوف، حدیث: ۹۱۲) بنابریں اگرچہ بعض ائمہ و محققین نے اس کی مختلف تاویلیں کی ہیں لیکن دلائل کی رو سے اور جمیع روایات کو جمع کرنے سے یہی موقف راجح معلوم ہوتا ہے کہ مذکورہ روایت میں نماز سے پہلے تسبیح و تکبیر اور دعا کا ذکر کرنا کسی راوی کی غلطی اور وہم ہے۔ واللہ أعلم۔ نیز شیخ البانی رحمہ اللہ بھی اس حدیث کی تحقیق میں یہی کچھ لکھتے ہیں، فرماتے ہیں: [أما نحن فنراھا خطاأ من بعض الرواۃ عن الجریری، واللہ أعلم۔] مزید تفصیل کے لیے دیکھیے: (صفۃ صلاۃ النبی صلی اللہ علیہ وسلم لصلاۃ الکسوف، ص: ۷۴-۶۸، رقم الحدیث: ۱۴، ذخیرۃ العقبی شرح سنن النسائي: ۳۹۱-۳۸۹/۱۶) (۳) گرہن کے موقع پر نماز، توبہ اور تسبیحات کا حکم ہے۔ گویا مظاہر قدرت میں کسی قسم کی تبدیلی سے ہم میں بھی عبرت پذیری آنی چاہیے اور دنیا سے منہ موڑ کر اللہ تعالیٰ کی طرف متوجہ ہونا چاہیے۔"}],[1461,"عبداللہ بن عمر رضی اللہ عنہم کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"سورج اور چاند گرہن کسی کے مرنے اور کسی کے پیدا ہونے سے نہیں لگتا ہے، بلکہ یہ اللہ تعالی کی نشانیوں میں سے دو نشانیاں ہیں، تو جب تم انہیں دیکھو تو نماز پڑھو\"۔","الألباني: صحيح",{"u2":"حضرت عبداللہ بن عمر رضی اللہ عنہما سے روایت ہے، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’سورج اور چاند کسی کی موت و حیات کی وجہ سے بے نور نہیں ہوتے بلکہ یہ تو اللہ تعالیٰ کی نشانیوں میں سے دو نشانیاں ہیں۔ جب تم انھیں گرہن کی حالت میں دیکھو تو نماز پڑھو۔‘‘"}],[1462,"ابومسعود رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"سورج گرہن اور چاند گرہن کسی کے مرنے سے نہیں لگتا، بلکہ یہ اللہ تعالی کی نشانیوں میں سے دو نشانیاں ہیں، جب تم انہیں دیکھو تو نماز پڑھو\"۔","الألباني: صحيح",{"u2":"حضرت ابومسعود رضی اللہ عنہ سے منقول ہے، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’سورج اور چاند کسی کی موت کی بنا پر بے نور نہیں ہوتے بلکہ یہ تو اللہ تعالیٰ کی نشانیاں ہیں۔ جب تم انھیں (اس حال میں) دیکھو تو نماز پڑھو۔‘‘"}],[1463,"ابوبکرہ رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"سورج اور چاند اللہ تعالی کی نشانیوں میں سے دو نشانیاں ہیں، ان دونوں کو نہ تو کسی کے مرنے سے گرہن لگتا ہے نہ کسی کے پیدا ہونے سے، جب تم ان دونوں کو گرہن لگا ہوا دیکھو تو نماز پڑھو یہاں تک کہ یہ صاف ہو جائیں\"۔","الألباني: صحيح",{"u2":"حضرت ابوبکرہ رضی اللہ عنہ سے مروی ہے، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’سورج اور چاند اللہ تعالیٰ کی نشانیوں میں سے دو نشانیاں ہیں۔ انھیں کسی کی موت و حیات کی بنا پر گرہن نہیں لگتا۔ جب تم انھیں گرہن کی حالت میں دیکھو تو نماز پڑھو حتی کہ یہ حالت ختم ہو جائے۔‘‘"}],[1464,"ابوبکرہ رضی اللہ عنہ کہتے ہیں کہ ہم لوگ نبی اکرم صلی اللہ علیہ وسلم کے ساتھ بیٹھے ہوئے تھے کہ سورج کو گرہن لگ گیا، تو آپ اپنا کپڑا گھسیٹتے ہوئے جلدی سے اٹھے، اور دو رکعت نماز پڑھی یہاں تک کہ وہ چھٹ گیا۔","الألباني: صحيح",{"u2":"حضرت ابوبکرہ رضی اللہ عنہ بیان کرتے ہیں کہ ہم نبی صلی اللہ علیہ وسلم کے پاس بیٹھے تھے کہ سورج کو گرہن لگ گیا۔ آپ اپنا کپڑا گھسیٹتے ہئے اٹھے، پھر آپ نے دو رکعتیں پڑھیں حتی کہ سورج صاف روشن ہوگیا۔"}],[1465,"ام المؤمنین عائشہ رضی اللہ عنہا کہتی ہیں کہ رسول اللہ صلی اللہ علیہ وسلم کے زمانے میں سورج گرہن لگا تو نبی آپ صلی اللہ علیہ وسلم نے ایک منادی کو حکم دیا، تو اس نے ندا دی کہ نماز کے لیے جمع ہو جاؤ، تو سب جمع ہو گئے، اور انہوں نے صف بندی کی تو آپ نے انہیں چار رکوع، اور چار سجدوں کے ساتھ، دو رکعت نماز پڑھائی۔","الألباني: صحيح",{"u2":"حضرت عائشہ رضی اللہ عنہا فرماتی ہیں کہ رسول اللہ صلی اللہ علیہ وسلم کے دور میں سورج کو گرہن لگ گیا۔ تو آپ نے ایک اعلان کرنے والے کو حکم دیا کہ وہ یہ اعلان کرے کہ نماز (نماز کسوف) کے لیے جمع ہو جائیں۔ لوگ جمع ہوگئے اور انھوں نے صف بندی کی تو آپ نے انھیں دو رکعتیں چار رکوع اور چار سجدوں کے ساتھ پڑھائیں۔","f2":"(۱) اذان کے رائج ہونے سے پہلے فرض نماز کے لیے انھی لفظوں [الصلاۃ جامعۃ] سے بلایا جاتا تھا۔ اب اگر کسی نفل نماز کے لیے بلانا ہو تو ان لفظوں سے اعلان کیا جا سکتا ہے۔ اذان صرف فرض نماز کے لیے ہے۔ (۲) ’’چار رکوع‘‘ نماز کسوف کے بارے میں زیادہ معتبر اور اوثق روایات ایک رکعت کے اندر دو رکوع کی ہیں۔ بعض محدثین نے تین، چار اور پانچ رکوع کی روایات کو بھی صحیح مان کر یہ موقف اختیار کیا ہے کہ کسوف کے وقت کے حساب سے رکوع کم و بیش کیے جا سکتے ہیں۔ دو سے پانچ تک۔ لیکن حقیقت یہ ہے کہ احادیث میں صرف ایک کسوف کا ذکر ہے اور وہ کشوف ۲۸ شوال ۱۰ھ کا ہے جس دن آپ کے فرزند ارجمند ابراہیم رضی اللہ عنہ فوت ہوئے تھے کیونکہ ہر روایت میں موت و حیات کا ذکر ہے۔ اور ظاہر ہے کہ ایک نماز کسوف میں آپ صلی اللہ علیہ وسلم ایک ہی طریقہ اختیار فرما سکتے تھے اور وہ معتبر روایات کے مطابق دو رکوع والا ہے۔ اس مسئلے کی تصفیل پیچھے ابتدائیے میں گزر چکی ہے۔ تفصیل کے لیے ابتدائیہ ملاحظہ فرمائیں۔ (۳) احناف عام نماز کی طرح نماز کشوف میں بھی ہر رکعت میں ایک ہی رکوع کے قائل ہیں مگر اس طرح صحیح اور صریح کثیر روایات، یعنی بخاری و مسلم کی اعلیٰ پائے کی روایات عمل سے رہ جائیں گی اور نماز کشوف کی خصوصی علامت ختم ہو جائے گی۔ اگر عیدین میں زائد تکبیرات، جنازے میں قیام کی زائد تکبیرات اور نماز وتر میں دعائے قنوت کا اضافہ احادیث کی بنا پر ہوسکتا ہے تو صلاۃ کسوف میں انتہائی معتبر اور صحیح روایات کی بنا پر ایک رکوع کا اضافہ کیوں قابل تسلیم نہیں؟ سوچیے! ہر صحیح حدیث واجب العمل ہے۔"}],[1466,"ام المؤمنین عائشہ رضی اللہ عنہا کہتی ہیں کہ رسول اللہ صلی اللہ علیہ وسلم کی زندگی میں سورج گرہن لگا تو رسول اللہ صلی اللہ علیہ وسلم مسجد کی طرف نکلے، اور نماز کے لیے کھڑے ہوئے، آپ نے \"اللہ اکبر\"، کہا اور لوگوں نے آپ کے پیچھے صف بندی کی، پھر آپ نے چار رکوع اور چار سجدے مکمل کئے، سورج آپ کے فارغ ہونے سے پہلے ہی صاف ہو گیا۔","الألباني: صحيح",{"u2":"نبی صلی اللہ علیہ وسلم کی زوجۂ محترمہ حضرت عائشہ رضی اللہ عنہا فرماتی ہیں کہ رسول اللہ صلی اللہ علیہ وسلم کی زندگی میں سورج کو گرہن لگ گیا۔ آپ صلی اللہ علیہ وسلم مسجد کی طرف نکلے۔ کھڑے ہوئے اور اللہ أکبر کہا۔ لوگوں نے آپ کے پیچھے صفیں باندھیں۔ اس طرح آپ نے (دو رکعتوں میں) چار رکوع اور چار سجدے مکمل کیے۔ اور پلٹنے (فارغ ہونے) سے پہلے سورج روشن ہوگیا (گرہن ختم ہوگیا)۔"}],[1467,"عبداللہ بن عباس رضی اللہ عنہم سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے سورج گرہن لگنے پر آٹھ رکوع، اور چار سجدوں کے ساتھ نماز پڑھی اور عطاء نے بھی ابن عباس رضی اللہ عنہم سے اسی کے مثل روایت کی ہے ۱؎۔\n§وضاحت\n۱؎: عطاء کی روایت جس کی طرف امام نسائی نے اشارہ کیا ہے، حقیقت میں وہ ابن عباس رضی اللہ عنہم سے مروی نہیں ہے، بلکہ وہ مرسل ہے، جیسا کہ امام مزی نے اسے مراسیل میں ذکر کیا ہے، ملاحظہ ہو: تحفہ الأشراف: ۱۹۰۴۹۔","الألباني: شاذ",{"u2":"حضرت ابن عباس رضی اللہ عنہما سے روایت ہے، رسول اللہ صلی اللہ علیہ وسلم نے سورج کے وقت آٹھ رکوع اور چار سجدے کیے۔ (یعنی ہر رکعت میں چار رکوع کیے۔)\nحضرت عطاء سے بھی اسی قسم کی روایت آتی ہے۔","f2":"اس (مذکورہ) روایت میں حضرت ابن عباس رضی اللہ عنہما کے شاگرد طاؤس ہیں۔ امام صاحب کا مقصود یہ ہے کہ یہی روایت حضرت عطاء بھی حضرت ابن عباس سے بیان کرتے ہیں۔ نچلی سند وہی ہے۔"}],[1468,"عبداللہ بن عباس رضی اللہ عنہم کہتے ہیں کہ نبی اکرم صلی اللہ علیہ وسلم نے گرہن لگنے پر نماز پڑھی، آپ نے قرآت کی، پھر رکوع کیا، پھر قرآت کی، پھر رکوع کیا، پھر قرآت کی، پھر رکوع کیا، پھر قرآت کی، پھر رکوع کیا، پھر سجدہ کیا، اور دوسری رکعت بھی ایسے ہی پڑھی۔","الألباني: شاذ والمحفوظ أربع ركوعات في ركعتين",{"u2":"حضرت ابن عباس رضی اللہ عنہما سے روایت ہے کہ نبی صلی اللہ علیہ وسلم نے گرہن کے وقت نماز پڑھی۔ پہلے قراءت کی، پھر رکوع کیا، پھر قراءت کی، پھر رکوع کیا، پھر قراءت کی، پھر رکوع کیا، پھر قراءت کی، پھر رکوع کیا، پھر سجدہ کیا، پھر دوسری رکعت بھی اسی طرح پڑھی۔ (یعنی ہر رکعت میں چار رکوع کیے۔)"}],[1469,"عبداللہ بن عباس رضی اللہ عنہم سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے جس دن سورج گرہن لگا، دو رکعت نماز پڑھی، تو چار رکوع اور چار سجدے کیے۔","الألباني: صحيح",{"u2":"حضرت عبداللہ بن عباس رضی اللہ عنہما سے مروی ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے سورج گرہن کے دن دو رکعتوں میں چار رکوع اور چار سجدے کیے۔ (یعنی ہر رکعت میں دو رکوع کیے۔)"}],[1470,"عبید بن عمیر کہتے ہیں کہ مجھ سے اس شخص نے بیان کیا ہے جسے میں سچا سمجھتا ہوں، میرا گمان ہے کہ ان کی مراد ام المؤمنین عائشہ رضی اللہ عنہا تھیں، وہ کہتی ہیں کہ رسول اللہ صلی اللہ علیہ وسلم کے زمانے میں سورج گرہن لگا، تو آپ نے لوگوں کے ساتھ بڑی دیر تک نماز میں قیام کیا، آپ لوگوں کے ساتھ قیام کرتے، پھر رکوع کرتے، پھر قیام کرتے، پھر رکوع کرتے، پھر قیام کرتے پھر رکوع کرتے، اس طرح آپ نے دو رکعت پڑھی، ہر رکعت میں آپ نے تین رکوع کیا، تیسرے رکوع سے اٹھنے کے بعد آپ نے سجدہ کیا یہاں تک کہ اس دن آدمیوں پر غشی طاری ہو گئی تھی جس کی وجہ سے ان کے اوپر پانی کے ڈول انڈیلنے پڑ گئے تھے، آپ جب رکوع کرتے تو «اللہ اکبر» کہتے، اور جب سر اٹھاتے تو «سمع اللہ لمن حمده» کہتے، آپ فارغ نہیں ہوئے جب تک کہ سورج صاف نہیں ہو گیا، پھر آپ کھڑے ہوئے، اور آپ نے اللہ کی حمد و ثنا بیان کی، اور فرمایا: \"سورج اور چاند کو نہ تو کسی کے مرنے سے گرہن لگتا ہے، اور نہ ہی کسی کے پیدا ہونے سے، لیکن یہ دونوں اللہ تعالی کی نشانیوں میں سے دو نشانیاں ہیں جن کے ذریعہ وہ تمہیں ڈراتا ہے، تو جب ان میں گرہن لگے تو اللہ تعالی کے ذکر کی طرف دوڑ پڑو، اور ذکر الٰہی میں لگے رہو جب تک کہ وہ صاف نہ ہو جائیں\"۔","الألباني: شاذ والمحفوظ عنها في كل ركعة ركوعان",{"u2":"حضرت عطاء بیان کرتے ہیں کہ میں نے حضرت عبید بن عمیر کو کہتے سنا کہ مجھے اس شخصیت نے بیان کیا جنھیں میں قطعاً سچا سمجھتا ہوں۔ میرا خیال ہے ان کا اشارہ حضرت عائشہ رضی اللہ عنہا کی طرف تھا۔ انھوں نے فرمایا: رسول اللہ صلی اللہ علیہ وسلم کے زمانے میں سورج کو گرہن لگ گیا۔ آپ نے لوگوں کو بڑا لمبا قیام کروایا۔ قیام فرماتے تھے، پھر رکوع کرتے تھے، پھر قیام فرماتے تھے، پھر رکوع کرتے تھے، پھر قیام فرماتے تھے، پھر رکوع فرماتے تھے۔ آپ نے دو رکعتیں پڑھیں۔ ہر رکعت میں تین رکوع تھے۔ تیسرا رکوع کرنے کے بعد سجدہ کیا حتی کہ اتنے لمبے قیام کی وجہ سے اس دن کچھ لوگوں پر غشی کی حالت طاری ہوگئی اور ان پر پانی کے ڈول بہائے گئے۔ جب آپ رکوع کو جاتے تو اللہ أکبر کتے اور جب اپنا سر اٹھاتے تو سمع اللہ لمن حمدہ کہتے۔ پ نماز سے اس وقت فارغ ہوئے جب سورج بالکل روشن ہوگیا۔ آپ (تقریر کے لیے) کھڑے ہوئے۔ اللہ تعالیٰ کی حمد و ثنا کی اور فرمایا: ’’سورج اور چاند کسی کی موت و حیات کی وجہ سے بے نور نہیں ہوتے، بلکہ وہ تو اللہ تعالیٰ کی نشانیوں میں سے دو نشانیاں ہیں۔ اللہ تعالیٰ تمھیں ان کے ذریعے سے ڈراتا ہے، لہٰذا جب وہ بے نور ہوجائیں تو خوف زدہ ہوکر اللہ تعالیٰ کا ذکر شروع کردو حتیٰ کہ وہ روشن ہوجائیں۔‘‘"}],[1471,"ام المؤمنین عائشہ رضی اللہ عنہا سے روایت ہے کہ نبی اکرم صلی اللہ علیہ وسلم نے چار سجدوں میں چھ رکوع کئے۔ اسحاق بن ابراہیم کہتے ہیں میں نے معاذ بن ہشام سے پوچھا: نبی اکرم صلی اللہ علیہ وسلم سے مروی ہے نا، انہوں نے کہا: اس میں کوئی شک و شبہ نہیں۔","الألباني: شاذ",{"u2":"حضرت عائشہ رضی اللہ عنہا سے روایت ہے کہ نبی صلی اللہ علیہ وسلم نے چار سجدوں میں (یعنی دو رکعتوں میں) چھ رکوع کیے۔ (راویٔ حدیث اسحاق کہتے ہیں کہ) میں نے معاذ (ابن ہشام) سے کہا: یہ نبی صلی اللہ علیہ وسلم سے ہے؟ انھوں نے کہا: کوئی شک و شبہ نہیں۔","f2":"حدیث نمبر ۱۴۶۸ سے یہاں تک ہر رکعت کے رکوعوں کی تعداد میں اختلاف ہے۔ دو، تین اور چار۔ تینا ور چار رکوع کی روایات قلیل ہیں۔ کثیر روایات (سابقہ اور آئندہ) دو رکوع کے بارے میں ہیں۔ بعض محدثین نے یہ موقف اختیار فرمایا ہے کہ کسوف کے مختلف واقعات میں رسول اللہ صلی اللہ علیہ وسلم نے مختلف رکوع فرمائے۔ یہ تطبیق بہت مناسب تھی اگر واقعتًا احادیث میں مختلف کسوفوں کا ذکر ہوتا مگر تحقیق سے معلوم ہوتا ہے کہ احادیث میں صرف ایک سورج گرہن کا ذکر ہے۔ اگرچہ آپ کی زندگی میں بہت سی دفعہ گرہن لگا ہوگا۔ (اس کی تفصیلی بحث پیچھے حدیث نمبر ۱۴۶۶ اور ابتدائیے میں گزر چکی ہے۔) اسی طرح آپ کی زندگی میں کئی دفعہ چاند گرہن کا وقوع ہوا ہوگا مگر احادیث میں کسی بھی چاند گرہن کا ذکر نہیں آیا، لہٰذا صحیح بات یہی ہے کہ احادیث میں سے دورکوع والی احادیث اصح واکثر ہیں۔ انھی کو ترجیح ہوگی۔ باقی میں وہم ہے۔ واللہ اعلم۔ مزید تفصیل کے لیے سی کتاب کا ابتدائیہ ملاحظہ فرمائیں۔"}],[1472,"ام المؤمنین عائشہ رضی اللہ عنہا کہتی ہیں کہ رسول اللہ صلی اللہ علیہ وسلم کی زندگی میں سورج گرہن لگا تو آپ (نماز کے لیے) کھڑے ہوئے، اور تکبیر کہی، اور لوگوں نے آپ کے پیچھے صفیں باندھیں، پھر رسول اللہ صلی اللہ علیہ وسلم نے بڑی لمبی قرآت کی، پھر «اللہ اکبر» کہا، اور ایک لمبا رکوع کیا، پھر اپنا سر اٹھایا، تو«سمع اللہ لمن حمده ربنا لك الحمد» کہا، پھر آپ کھڑے رہے، اور ایک لمبی قرآت کی مگر پہلی قرآت سے کم، پھر تکبیر کہی، اور ایک لمبا رکوع کیا، مگر پہلے رکوع سے چھوٹا، پھر آپ نے «سمع اللہ لمن حمده ربنا لك الحمد» کہا، پھر سجدہ کیا، پھر دوسری رکعت میں بھی آپ نے اسی طرح کیا، اس طرح آپ نے چار رکوع اور چار سجدے پورے کیے، آپ کے نماز سے فارغ ہونے سے پہلے ہی سورج صاف ہو گیا، پھر آپ نے کھڑے ہو کر لوگوں کو خطاب کیا، تو اللہ تعالی کی ثنا بیان کی جو اس کے شایان شان تھی، پھر فرمایا: بلاشبہ سورج اور چاند اللہ تعالی کی نشانیوں میں سے دو نشانیاں ہیں، انہیں نہ کسی کے مرنے سے گرہن لگتا ہے، نہ کسی کے پیدا ہونے سے، جب تم انہیں دیکھو تو نماز پڑھو، جب تک کہ وہ تم سے چھٹ نہ جائے، نیز رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"میں نے اپنے اس کھڑے ہونے کی جگہ میں ہر وہ چیز دیکھ لی جس کا تم سے وعدہ کیا گیا ہے، تم نے مجھے آگے بڑھتے ہوئے دیکھا، میں نے چاہا کہ جنت کے پھلوں میں سے ایک گچھا توڑ لوں، جب تم نے مجھے دیکھا میں آگے بڑھا تھا، اور میں نے جہنم کو دیکھا، اس حال میں کہ اس کا ایک حصہ دوسرے کو توڑ رہا تھا جب تم نے مجھے پیچھے ہٹتے ہوئے دیکھا، اور میں نے اس میں ابن لحی کو دیکھا ۱؎، یہی ہے جس نے سب سے پہلے سائبہ چھوڑا ۲؎\"۔\n§وضاحت\n۱؎: اس کا نام عمرو ہے اور باپ کا نام عامر ہے اور لقب لحی ہے۔ ۲؎: سائبہ ایسی اونٹنی کو کہتے ہیں جسے بتوں کے نام پر آزاد چھوڑ دیا گیا ہو، اور اس سے سواری اور بار برداری کا کوئی کام نہ لیا جاتا ہو۔","الألباني: صحيح",{"u2":"حضرت عائشہ رضی اللہ عنہا فرماتی ہیں کہ رسول اللہ صلی اللہ علیہ وسلم کی حیات طیبہ میں سورج کو گرہن لگ گیا۔آپ (نماز کے لیے) اٹھے۔ اللہ اکبر کہا۔ لوگوں نے بھی آپ کے پیچھے صفیں باندھیں۔ رسول اللہ صلی اللہ علیہ وسلم نے لمبی قراءت فرمائی، پھر اللہ اکبر کہا اور لمبا رکوع کیا، پھر اپنا سر اٹھایا اور سمع اللہ لمن حمدہ ربنا ولک الحمد کہا، پھر قیام شروع کردیا اور لمبی قراءت کی جو کہ پہلی قراءت سے کم تھی، پھر اللہ اکبر کہا اور لمبا رکوع کیا جو پہلے رکوع سے کم تھا، پھر سمع اللہ لمن حمدہ، ربنا ولک الحمد کہا، پھر سجدہ کیا، پھر دوسری رکعت میں بھی اسی طرح کیا۔ اور چار رکوع اور چار سجدے مکمل کیے۔ آپ کے (نماز سے) فارغ ہونے سے پہلے سورج مکمل روشن ہوچک تھا، پھر آپ کھڑے ہوئے اور لوگوں کو خطبہ دیا۔ اللہ تعالیٰ کی حمدوثنا کی جس کا وہ اہل ہے، پھر فرمایا: ’’سورج اور چاند اللہ تعالیٰ کی نشانیوں میں سے دو نشانیاں ہیں۔ انھیں کسی کی موت و حیات کی وجہ سے گرہن نہیں لگتا۔ جب تم انھیں (گرہن لگا ہوا) دیکھو تو نماز کسوف شروع کردو حتی کہ گرہن کی حالت ختم ہوجائے۔‘‘ نیز رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’میں نے اس (نماز کے) قیام کے دوران میں ہر چیز دیکھ لی جس کا تم سے وعدہ کیا گیا ہے۔ جب تم نے جھے آگے بڑھتے ہوئے دیکھا تھا تو دراصل میں نے جنت سے ایک خوشہ توڑنے کا ارادہ کیا تھا۔ اور جب تم نے مجھے پیچھے ہٹتے ہوئے دیکھا تھا تو دراصل میں نے جہنم کو دیکھا تھا کہ اس کے مختلف حصے ایک دوسرے کو توڑ رہے تھے، نیز میں نے جہنم میں عمروبن لحی کو دیکھا اور یہ وہ شخص ہے جس نے بتوں کے نام پر جانور کھلے چھوڑنے کی رسم ڈالی۔‘‘","f2":"(۱)اس روایت میں نماز کسوف کے دوران جنت و جہنم اور دوسری پوشیدہ چیزیں دیکھنے کا بھی ذکر ہے۔ آپ کا یہ دیکھنا بیدار میں تھا۔ اور صرف آپ کے ساتھ خاص تھا، یعنی صحابہ کو وہ چیزیں نظر نہ آتی تھیں۔ اس قسم کے دیکھنے کو تصوف کی اصطلاح میں کشف کہا جاتا ہے۔ انبیاء علیہم السلام کو یہ اکثر ہوتا تھا۔ کبھی کبھار غیر انبیاء کے ساتھ بھی ایسے واقعات ہوئے ہیں۔ معتبر روایت کی صورت میں ایسا واقعہ تسلیم کیا جائے گا۔ یہ ان کی کرامت اور اس کا شمار اللہ تعالیٰ کی نشانیوں میں ہوگا۔ اس صورت میں صاحب کشف کے علاوہ باقی لوگوں کو وہ چیزیں نظر نہیں آرہی ہوتیں، اس لیے انھیں تعجب ہوتا ہے، جیسے صحابہ کرام رضی اللہ عنہم کو آپ کے آگے بڑھنےا ور پیچھے ہٹنے پر تعجب ہوا۔ ان کے لیے آپ نے وضاحت فرمائی۔ (۲)’’ہر چیز‘‘ بعض شارحین نے اس میں اللہ تعالیٰ کو بھی داخل سمجھا ہے، مگر صراحت کے بغیر اتنی بڑی بات کہنا بہت بڑی جسارت ہے۔ جبکہ قرآن مجید میں ہے: (لن ترانی) (الاعراف۷:۱۴۳) اور (لاتدرکہ الابصار) (الانعام۶:۱۰۳) یعنی اللہ تعالیٰ کو ان آنکھوں سے نہیں دیکھا جاسکتا۔ ہاں اگلے جہاں مومنین کو اللہ تعالیٰ کا دیدار نصیب ہوگا۔ اللہ تعالیٰ ہمیں بھی ان میں شامل فرمائے"}],[1473,"ام المؤمنین عائشہ رضی اللہ عنہا کہتی ہیں کہ رسول اللہ صلی اللہ علیہ وسلم کے زمانے میں سورج گرہن لگا تو «الصلاة جامعة» (صلاۃ باجماعت ہو گی) کی منادی کرائی گئی، چنانچہ لوگ اکٹھا ہوئے تو رسول اللہ صلی اللہ علیہ وسلم نے ان کے ساتھ دو رکعت میں چار رکوع اور چار سجدے کئے۔","الألباني: صحيح",{"u2":"حضرت عائشہ رضی اللہ عنہا فرماتی ہیں کہ رسول اللہ صلی اللہ علیہ وسلم کے زمانے میں سورج کو گرہن لگ گیا تو اعلان کیا: نماز کی جماعت ہونی ہے۔ لوگ اکٹھے ہوگئے تو رسول اللہ صلی اللہ علیہ وسلم نے انھیں نماز پڑھائی۔ اور (دورکعتوں میں) چار رکوع اور چار سجدے کیے۔"}],[1474,"ام المؤمنین عائشہ رضی اللہ عنہا کہتی ہیں کہ رسول اللہ صلی اللہ علیہ وسلم کے زمانے میں سورج گرہن لگا تو رسول اللہ صلی اللہ علیہ وسلم نے لوگوں کو نماز پڑھائی، آپ نے لمبا قیام کیا، پھر لمبا رکوع کیا، پھر لمبا قیام کیا، اور یہ پہلے قیام سے کم تھا، پھر لمبا رکوع کیا، اور یہ پہلے رکوع سے کم تھا، پھر آپ نے رکوع سے سر اٹھایا، اور سجدہ کیا، پھر آپ نے دوسری رکعت میں بھی اسی طرح کیا، پھر آپ فارغ ہوئے اس حال میں کہ سورج صاف ہو چکا تھا، تو آپ نے لوگوں کو خطاب کیا، پہلے آپ نے اللہ کی حمد و ثنا کی، پھر فرمایا: \"سورج اور چاند اللہ تعالی کی نشانیوں میں سے دو نشانیاں ہیں، ان دونوں کو نہ کسی کے مرنے سے گرہن لگتا ہے، اور نہ ہی کسی کے جینے سے، تو جب تم اسے دیکھو تو اللہ تعالی سے دعا کرو، اور اس کی بڑائی بیان کرو، اور صدقہ کرو\"، پھر آپ نے فرمایا: \"اے امت محمد! اللہ تعالی سے زیادہ کوئی اس بات پر غیرت کرنے والا نہیں کہ اس کا غلام یا لونڈی زنا کرے، اے امت محمد! قسم اللہ کی، اگر تم وہ جانتے جو میں جانتا ہوں، تو تم ہنستے کم اور روتے زیادہ\"۔","الألباني: صحيح",{"u2":"حضرت عائشہ رضی اللہ عنہا فرماتی ہیں کہ رسول اللہ صلی اللہ علیہ وسلم کے دور میں سورج کو گرہن لگ گیا تو رسول اللہ صلی اللہ علیہ وسلم نے لوگوں کو نماز کسوف پڑھائی۔ آپ نے قیام فرمایا اور بہت لمبا قیام فرمایا، پھر رکوع فرمایا اور بہت لمبا رکوع فرمایا، پھر قیام فرمایا اور لمبا قیام فرمایا لیکن یہ پہلے قیام سے کم تھا، پھر رکوع فرمایا اور لمبا رکوع فرمایا لیکن یہ پہلے رکوع سے کم تھا، پھر سر اٹھایا، پھر سجدہ کیا، پھر دوسری رکعت میں بھی ایسے ہی کیا، پھر فارغ ہوئے تو سورج پوری طرح روشن ہوچکا تھا، پھر آپ نے لوگوں کو خطبہ دیا۔ اللہ کی حمدوثنا کی، پھر فرمایا: ’’بلاشبہ سورج اور چاند اللہ تعالیٰ کی نشانیوں میں سے دو نشانیاں ہیں۔ انھیں کسی کی موت و حیات کی وجہ سے گرہن نہیں لگتا۔ جب تم یہ صورت حال دیکھو تو اللہ تعالیٰ سے دعائیں کرو اور اللہ تعالیٰ کی بزرگی بیان کرو اور صدقات کرو۔ ‘‘ پھر فرمایا: ’’اے امتِ محمد! کوئی شخص اللہ تعالیٰ سے بڑھ کر اس بات پر غیرت نہیں کرتا کہ اس کا کوئی غلام یا لونڈی زنا کرے۔ اے امت محمد! اللہ کی قسم! اگر تم وہ چیزیں جان لو جو میں جانتا ہوں تو تم بہت کم ہنسو اور بہت زیادہ روو۔‘‘"}],[1475,"ام المؤمنین عائشہ رضی اللہ عنہا کہتی ہیں کہ ایک یہودی عورت ان کے پاس آئی، اور کہنے لگی: اللہ تعالی تمہیں قبر کے عذاب سے بچائے، یہ سنا تو عائشہ نے پوچھا: اللہ کے رسول! لوگوں کو قبر میں بھی عذاب دیا جائے گا؟ تو رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"اللہ کی پناہ\"۔ نبی اکرم صلی اللہ علیہ وسلم کہیں جانے کے لیے نکلے اتنے میں سورج گرہن لگ گیا، تو ہم حجرہ میں چلے گئے، یہ دیکھ کر دوسری عورتیں بھی ہمارے پاس جمع ہو گئیں، اور رسول اللہ صلی اللہ علیہ وسلم ہمارے پاس آئے اور یہ چاشت کا وقت تھا، آپ نماز کے لیے کھڑے ہوئے، آپ نے نماز میں لمبا قیام کیا، پھر لمبا رکوع کیا، پھر رکوع سے سر اٹھایا، تو قیام کیا پہلے قیام سے کم، پھر آپ نے رکوع کیا، اپنے پہلے رکوع سے کم، پھر سجدہ کیا، پھر آپ دوسری رکعت کے لیے کھڑے ہوئے، تو اسی طرح کیا مگر دوسری رکعت میں آپ کا رکوع اور قیام پہلی رکعت سے کم تھا، پھر آپ نے سجدہ کیا، اور سورج صاف ہو گیا، تو جب آپ فارغ ہوئے، تو منبر پر بیٹھے، اور جو باتیں کہنی تھیں کہیں، اس میں ایک بات یہ بھی تھی: \"کہ لوگ اپنی قبروں میں آزمائے جائیں گے، جیسے دجال کے فتنے میں آزمائے جائیں گے\"، ام المؤمنین عائشہ رضی اللہ عنہا کہتی ہیں: اس کے بعد سے برابر ہم آپ کو قبر کے عذاب سے پناہ مانگتے ہوئے سنتے تھے۔","الألباني: صحيح",{"u2":"حضرت عائشہ رضی اللہ عنہا فرماتی ہیں کہ ایک یہودی عورت میرے پاس آئی اور کہنے لگی: اللہ تعالیٰ تجھے قبر کے عذاب سے بچائے۔ حضرت عائشہ رضی اللہ عنہا نے کہا: اے اللہ کے رسول! کیا لوگوں کو قبروں میں عذاب ہوگا؟ تو رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’میں اللہ کی پناہ میں آتا ہوں۔‘‘ حضرت عائشہ رضی اللہ عنہا بیان کرتی ہیں کہ نبی صلی اللہ علیہ وسلم ایک دفعہ نکلے۔ اتنے میں سورج کو گرہن لگ گیا۔ ہم سب حجرے میں چلے آئے۔ ہمارے پاس بہت سی عورتیں اکٹھی ہوگئیں۔ اللہ کے رسول صلی اللہ علیہ وسلم بھی تشریف لے آئے۔ یہ چاشت (دن چڑھنے) کے وقت کی بات ہے، پھر آپ نے لمبا قیام فرمایا، پھر لمبا رکوع فرمایا، پھر سر اٹھا کر دوبارہ قیام کیا لیکن یہ پہلے قیام سے کم تھا، پھر پہلے رکوع سےکم رکوع کیا، پھر سجدہ کیا، پھر دوسری رکعت کے لیے کھڑے ہوئے اور اس میں بھی اسی طرح کیا مگر اس رکعت کے قیام و رکوع پہلی رکعت کے مقابلے میں کم تھے، پھر سجدے کیے اور سورج بھی پورا روشن ہوگیا۔ جب آپ نماز سے فارغ ہوئے تو منبر پر بیٹھ گئے اور (تقریر کے دوران میں) فرمایا: ’’بلاشبہ لوگوں کو قبروں میں فتنۂ دجال کی طرح آزمایا جائے گا۔‘‘ حضرت عائشہ رضی اللہ عنہا فرماتی ہیں کہ اس کے بعد ہم آپ کو اکثر عذاب سے پناہ مانگتے سنتے تھے۔\nحضرت عائشہ رضی اللہ عنہا فرماتی ہیں کہ ایک یہودی عورت میرے پاس آئی اور کہنے لگی: اللہ تعالیٰ تجھے قبر کے عذاب سے بچائے۔ حضرت عائشہ رضی اللہ عنہا نے کہا: اے اللہ کے رسول! کیا لوگوں کو قبروں میں عذاب ہوگا؟ تو رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’میں اللہ کی پناہ میں آتا ہوں۔‘‘ حضرت عائشہ رضی اللہ عنہا بیان کرتی ہیں کہ نبی صلی اللہ علیہ وسلم ایک دفعہ نکلے۔ اتنے میں سورج کو گرہن لگ گیا۔ ہم سب حجرے میں چلے آئے۔ ہمارے پاس بہت سی عورتیں اکٹھی ہوگئیں۔ اللہ کے رسول صلی اللہ علیہ وسلم بھی تشریف لے آئے۔ یہ چاشت (دن چڑھنے) کے وقت کی بات ہے، پھر آپ نے لمبا قیام فرمایا، پھر لمبا رکوع فرمایا، پھر سر اٹھا کر دوبارہ قیام کیا لیکن یہ پہلے قیام سے کم تھا، پھر پہلے رکوع سےکم رکوع کیا، پھر سجدہ کیا، پھر دوسری رکعت کے لیے کھڑے ہوئے اور اس میں بھی اسی طرح کیا مگر اس رکعت کے قیام و رکوع پہلی رکعت کے مقابلے میں کم تھے، پھر سجدے کیے اور سورج بھی پورا روشن ہوگیا۔ جب آپ نماز سے فارغ ہوئے تو منبر پر بیٹھ گئے اور (تقریر کے دوران میں) فرمایا: ’’بلاشبہ لوگوں کو قبروں میں فتنۂ دجال کی طرح آزمایا جائے گا۔‘‘ حضرت عائشہ رضی اللہ عنہا فرماتی ہیں کہ اس کے بعد ہم آپ کو اکثر عذاب سے پناہ مانگتے سنتے تھے۔","f2":"عذاب قبر کے بارے میں حضرت عائشہ رضی اللہ عنہا کے سوال کا جواب مبہم ہے۔ ممکن ہے اس وقت تک رسول اللہ صلی اللہ علیہ وسلم کو عذاب قبر کی تفصیل نہ بتلائی گئی ہو اور نمازکسوف کے دوران میں دوسرے انکشافات کی طرح عذاب قبر کا بھی انکشاف کیا گیا ہو۔ فتنۂ دجال چونکہ بہت بڑی آزمائش ہے، اس لیے عذاب قبر، یعنی قبر کے سوا ل و جواب کو اس سے تشبیہ دی گئی۔ واللہ اعلم۔"}],[1476,"ام المؤمنین عائشہ رضی اللہ عنہا کہتی ہیں کہ ایک یہودی عورت مجھ سے کچھ پوچھنے آئی تو اس نے کہا: اللہ تعالی تمہیں قبر کے عذاب سے بچائے، تو جب رسول اللہ صلی اللہ علیہ وسلم آئے تو میں نے پوچھا: اللہ کے رسول! کیا لوگ قبروں میں بھی عذاب دیئے جاتے ہیں؟ آپ نے فرمایا: \"اللہ کی پناہ\"، پھر آپ (کہیں جانے کے لیے)سواری پر سوار ہوئے کہ ادھر سورج گرہن لگ گیا، اور میں دوسری عورتوں کے ساتھ حجروں کے درمیان بیٹھی تھی کہ رسول اللہ صلی اللہ علیہ وسلم اپنی سواری سے اتر کر آئے، اور اپنے مصلی کی طرف بڑھے، آپ نے لوگوں کو نماز پڑھائی تو لمبا قیام کیا، پھر لمبا رکوع کیا، پھر آپ نے اپنا سر اٹھایا تو لمبا قیام کیا، پھر لمبا رکوع کیا، پھر آپ نے اپنا سر اٹھایا تو لمبا قیام کیا، پھر آپ نے سجدہ کیا تو لمبا سجدہ کیا، پھر آپ (سجدہ سے کھڑے ہوئے) اور آپ نے قیام کیا، مگر اپنے پہلے قیام سے کم، پھر رکوع کیا، اپنے پہلے رکوع سے کم، پھر اپنا سر اٹھایا تو قیام کیا اپنے پہلے قیام سے کم، تو یہ چار رکوع اور چار سجدے ہوئے، اور سورج صاف ہو گیا، تو آپ نے فرمایا: \"تم قبروں میں آزمائے جاؤ گے اسی طرح جس طرح دجال کے فتنے سے آزمائے جاؤ گے\"۔ ام المؤمنین عائشہ رضی اللہ عنہا کہتی ہیں: اس کے بعد سے میں نے برابر آپ کو قبر کے عذاب سے پناہ مانگتے ہوئے سنا۔","الألباني: صحيح",{"u2":"حضرت عائشہ رضی اللہ عنہا سے روایت ہے کہ ایک یہودی عورت میرے پاس کچھ مانگنے آئی۔ وہ کہنے لگی: اللہ تعالیٰ تجھے عذاب قبر سے بچائے۔ جب رسول اللہ صلی اللہ علیہ وسلم تشریف لائے تو میں نے کہا: اے اللہ کے رسول! کیا لوگوں کو قبروں میں عذاب دیا جائے گا؟ آپ نے فرمایا: ’’میں اللہ کی پناہ چاہتا ہوں۔‘‘ پھر آپ سواری پر سوار ہوکر کہیں گئے۔ ادھر سورج کو گرہن لگ گیا۔ میں دوسری عورتوں کے ساتھ حجروں کے درمیان کھڑی تھی کہ رسول اللہ صلی اللہ علیہ وسلم سواری سے اتر کر تشریف لائے اپنی نماز کی جگہ میں پہنچے، پھرلوگوں کو نماز پڑھانا شروع کی، چنانچہ آپ نے قیام کیا اور بہت لمبا قیام کیا، پھر رکوع کیا اور لمبا رکوع کیا، پھر اپنا سر اٹھایا اور دیر تک کھڑے رہے، پھر سجدہ کیا اور لمبا سجدہ کیا، پھر (دوسرے سجدے کے بعد) کھڑے ہوئےاور پہلے قیام سے ہلکا قیام کیا، پھر پہلے رکوع سے ہلکا رکوع کیا، پھر اپنا سر اٹھایا اور پہلے قیام سے ہلکا قیام کیا، پھر اپنے پہلے رکوع سے ہلکا رکوع کیا، پھر سر اٹھایا اور پہلے سے کچھ کم دیر کھڑے رہے اس طرح چار رکوع اور چار سجدے ہوئے۔ ادھر سورج بھی روشن ہوگیا، پھر آپ نے (خطبہ کے دوران میں) فرمایا: ’’تمھیں قبروں میں فتنۂ دجال کی طرح آزمایا جائے گا۔‘‘ حضرت عائشہ رضی اللہ عنہا بیان کرتی ہیں: اس کے بعد میں نے آپ صلی اللہ علیہ وسلم کو عذاب قبر سے پناہ مانگتے سنا۔"}],[1477,"ام المؤمنین عائشہ رضی اللہ عنہا سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے کسوف کی نماز میں زمزم کے چبوترے پر چار چار رکوع اور چار چار سجدے کئے۔","الألباني: صحيح دون ذكر الصفة فإنه شاذ مخالف لكل الروايات السابقة واللاحقة",{"u2":"حضرت عائشہ رضی اللہ عنہا سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے سورج گرہن کے موقع پر زم زم کے چبوترے پر نماز پڑھی، اس میں چار رکوع کیے اور چار سجدے کیے۔","f2":"اس حدیث میں ’’زم زم‘‘ کا ذکر کسی راوی کا وہم ہے کیونکہ رسول اللہ صلی اللہ علیہ وسلم سے نماز کسوف مدینہ منورہ ہی میں ثابت ہے اور محقق قول کے مطابق وہ بھی صرف ایک دفعہ، لہٰذا یہ لفظ لازماً راوی کا وہم ہے۔ واللہ اعلم۔ مزید تفصیل کے لیے دیکھیے: (ذخیرۃ العقبٰی شرح سنن النسائی:۱۶؍۴۲۴، ۴۲۵، وصحیح سنن النسائی للالبانی، رقم:۱۴۷۶)"}],[1478,"جابر بن عبداللہ رضی اللہ عنہم کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم کے زمانے میں ایک انتہائی گرم دن میں سورج گرہن لگا تو رسول اللہ صلی اللہ علیہ وسلم نے اپنے صحابہ کو نماز پڑھائی، اور لمبا قیام کیا یہاں تک کہ لوگ (بیہوش ہو ہو کر) گرنے لگے، پھر آپ نے لمبا رکوع کیا، پھر آپ رکوع سے اٹھے تو آپ نے لمبا قیام کیا، پھر آپ نے لمبا رکوع کیا، پھر آپ رکوع سے اٹھے تو لمبا قیام کیا، پھر دو سجدے کیے، پھر آپ کھڑے ہوئے تو آپ نے پھر اسی طرح کیا، نیز آپ آگے بڑھے پھر پیچھے ہٹنے لگے، تو یہ چار رکوع اور چار سجدے ہوئے، لوگ کہتے تھے کہ سورج اور چاند گرہن ان کے بڑے آدمیوں میں سے کسی بڑے آدمی کی موت کی وجہ سے لگتا ہے، حالانکہ یہ دونوں اللہ کی نشانیوں میں سے دو نشانیاں ہیں جنہیں اللہ تمہیں دکھاتا ہے، تو جب گرہن لگے تو نماز پڑھو جب تک کہ وہ چھٹ نہ جائے۔","الألباني: صحيح",{"u2":"حضرت جابر بن عبداللہ رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم کے زمانے میں ایک سخت گرم دن میں سورج گرہن لگا تو رسول اللہ صلی اللہ علیہ وسلم نے اپنے صحابہ کو نماز کسوف پڑھائی۔ آپ نے بہت لمبا قیام فرمایا حتی کہ لوگ گرنے لگے، پھر آپ نے رکوع فرمایا اور لمبا رکوع فرمایا، پھر آپ نے سر اٹھایا تو لمبا قیام فرمایا، پھر رکوع فرمایا اور لمبا رکوع فرمایا، پھر سر اٹھایا تو کافی دیر کھڑے رہے، پھر دو سجدے کیے، پھر کھڑے ہوئے اور دوسری رکعت بھی اسی طرح پڑھی۔ (قیام کے دوران میں) آپ آگے بڑھتے تھے، پھر پیچھے ہٹتے تھے۔ تو اس طرح یہ چار رکوع اور چار سجدے ہوئے۔ لوگ کہا کرتے تھے کہ سورج اور چاند کو کسی عظیم سردار کی وفات پر ہی گرہن لگتا ہے۔ (آپ نے فرمایا:) ’’یہ دونوں اللہ تعالیٰ کی نشانیوں میں سے دو نشانیاں ہیں جو اللہ تعالیٰ تمھیں دکھاتا ہے۔ تو جب ان میں سے کسی کو گرہن لگ جائے تو نماز پڑھو حتی کہ روہ روشن ہوجائے۔‘‘","f2":"فوائد کے لیے دیکھیے روایت: ۱۴۷۳۔"}],[1479,"عبداللہ بن عمرو رضی اللہ عنہم کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم کے زمانے میں سورج گرہن لگا، تو آپ نے (نماز کا) حکم دیا تو «الصلاة جامعة» (نماز باجماعت پڑھی جائے گی) کی منادی کرائی گئی، تو رسول اللہ صلی اللہ علیہ وسلم نے لوگوں کو نماز پڑھائی (پہلی رکعت میں) آپ نے دو رکوع اور ایک سجدہ کیا ۱؎، پھر آپ کھڑے ہوئے، پھر آپ نے (دوسری رکعت میں بھی) دو رکوع اور ایک سجدہ کیا۔ ام المؤمنین عائشہ رضی اللہ عنہا کہتی ہیں: میں نے کبھی اتنا لمبا رکوع نہیں کیا، اور نہ ہی کبھی اتنا لمبا سجدہ کیا۔ محمد بن حمیر نے مروان کی مخالفت کی ہے ۲؎۔\n§وضاحت\n۱؎: یہاں سجدہ سے مراد مکمل ایک رکعت ہے، کیونکہ کسی بھی نماز میں ایک سجدہ کا کوئی بھی قائل نہیں ہے، مطلب یہ ہے کہ ایک رکعت دو رکوع کے ساتھ پڑھی۔ ۲؎: یہ مخالفت سند اور متن دونوں میں ہے، سند میں مخالفت یہ ہے کہ مروان کی روایت میں یحیی بن ابی کثیر اور عبداللہ بن عمرو کے درمیان ابوسلمہ بن عبدالرحمٰن کا واسطہ ہے، اور محمد بن حمیر کی روایت میں ابوسلمہ بن عبدالرحمٰن کی جگہ ابوطعمہ کا واسطہ ہے، اور متن میں مخالفت یہ ہے کہ مروان کی روایت میں سجدہ کا لفظ آیا ہے، اور محمد بن حمیر کی روایت میں اس کی جگہ سجدتین کا لفظ آیا ہے۔","الألباني: صحيح",{"u2":"حضرت عبداللہ بن عمرو رضی اللہ عنہما بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم کے زمانے میں سورج کو گرہن لگ گیا۔ آپ کے حکم سےاعلان کیا گیا کہ نماز کی جماعت ہونی ہے۔ رسول اللہ صلی اللہ علیہ وسلم نے لوگوں کو دو رکوع کے ساتھ ایک رکعت پڑھائی، پھر آپ کھڑے ہوئے اور دو رکوع کے ساتھ ایک اور رکعت پڑھی۔ حضرت عائشہ رضی اللہ عنہا فرماتی ہیں کہ اس سے زیادہ لمبا رکوع اور سجدہ میں نے کبھی نہیں کیا۔\nمحمد بن حمیر نے (اس روایت کے بیان میں) مروان کی مخالفت کی ہے۔","f2":"یہ مخالفت سند میں بھی ہے اور متن میں بھی جیسا کہ آئندہ حدیث سے واضح ہورہا ہے۔ سند میں مخالفت یہ ہے کہ مروان نے یحییٰ بن ابی کثیر کا استاد ابوسلمہ بتایا ہے جبکہ ابن حمیر نے ابوطعمہ۔ اور متن میں مروان نے سجدہ کہا ہے جب کہ محمد بن حمیر نے سجدتین (دوسجدے) کہا ہے۔"}],[1480,"عبداللہ بن عمرو رضی اللہ عنہم کہتے ہیں کہ سورج گرہن لگا تو رسول اللہ صلی اللہ علیہ وسلم نے دو رکوع کیے، اور دو سجدے کیے، پھر آپ کھڑے ہوئے، اور دو رکوع اور دو سجدے کیے، پھر سورج سے گرہن چھٹ گیا۔ ام المؤمنین عائشہ رضی اللہ عنہا کہتی تھیں: رسول اللہ صلی اللہ علیہ وسلم نے کوئی سجدہ اور کوئی رکوع ان سے لمبا نہیں کیا۔ علی بن مبارک نے معاویہ بن سلام کی مخالفت کی ہے ۱؎۔\n§وضاحت\n۱؎: علی بن مبارک نے اسے مسند عائشہ میں سے قرار دیا ہے، اور معاویہ بن سلام نے مسند عبداللہ بن عمرو میں سے۔","الألباني: صحيح",{"u2":"حضرت عبداللہ بن عمرو رضی اللہ عنہما بیان کرتے ہیں کہ ایک دفعہ سورج کو گرہن لگ گیا تو رسول اللہ صلی اللہ علیہ وسلم نے (پہلی رکعت میں) دو رکوع اور دو سجدے فرمائے۔ اتنے میں سورج روشن ہوگیا۔ حضرت عائشہ رضی اللہ عنہا فرمایا کرتی تھیں: رسول اللہ صلی اللہ علیہ وسلم نے اس سے لمبا رکوع اور سجدہ کبھی نہیں کیا۔\nعلی بن مبارک نے معاویہ بن سلام کی مخالفت کی ہے۔","f2":"اس مخالفت کی وضاحت آئندہ حدیث میں ہورہی ہے کہ علی بن مبارک نے یہ روایت حضرت عائشہ رضی اللہ عنہا کی طرف منسوب کی ہے جبکہ معاویہ بن سلام نے اسے حضرت عبداللہ بن عمرو رضی اللہ عنہما کی طرف منسوب کیا ہے۔"}],[1481,"ام المؤمنین عائشہ رضی اللہ عنہا کہتی ہیں کہ جب رسول اللہ صلی اللہ علیہ وسلم کے زمانے میں سورج گرہن لگا تو آپ نے وضو کیا، اور حکم دیا تو ندا دی گئی: «الصلاة جامعة» (نماز باجماعت ہو گی)، پھر آپ (نماز کے لیے) کھڑے ہوئے، تو آپ نے لمبا قیام کیا، عائشہ رضی اللہ عنہا کہتی ہیں: تو مجھے گمان ہوا کہ آپ نے سورۃ البقرہ پڑھی، پھر آپ نے لمبا رکوع کیا، پھر آپ نے: «سمع اللہ لمن حمده» کہا، پھر آپ نے اسی طرح قیام کیا جیسے پہلے کیا تھا، اور سجدہ نہیں کیا، پھر آپ نے رکوع کیا پھر سجدہ کیا، پھر آپ کھڑے ہوئے اور آپ نے پہلے ہی کی طرح دو رکوع اور ایک سجدہ کیا، پھر آپ بیٹھے، تب سورج سے گرہن چھٹ چکا تھا۔","الألباني: صحيح لغيره",{"u2":"حضرت عائشہ رضی اللہ عنہا بتاتی ہیں کہ جب رسول اللہ صلی اللہ علیہ وسلم کے دور میں سورج کو گرہن لگا تو آپ نے وضو فرمایا اور حکم دیا تو اعلان کیا گیا کہ نماز کی جماعت ہونی ہے، پھر آپ نے قیام شروع فرمایا اور نماز میں بہت لمبا قیام فرمایا۔ حضرت عائشہ رضی اللہ عنہا نے فرمایا: میرا اندازہ ہے کہ آپ نے سورۂ بقرہ پڑھی، پھر آپ نے رکوع فرمایا اور لمبا رکوع فرمایا، پھر فرمایا: سمع اللہ لمن حمدہ، پھر قیام کیا جس طرح پہلا قیام فرمایا تھا۔ سجدہ نہیں کیا، پھر رکوع میں گئے، پھر سجدہ کیا، پھر کھڑے ہوئے اور اس رکعت میں بھی پہلی رکعت کی طرح دو رکوع اور دو سجدے کیے، پھر (تشہد میں) بیٹھے۔ اتنے میں سورج بھی روشن ہوگیا۔","f2":"(۱)’’میرا اندازہ ہے۔‘‘ اس سے استدلال کیا گیا ہے کہ نماز کسوف میں قراءت آہستہ ہونی چاہیے۔ اگر آپ جہر فرماتے تو اندازہ لگانے کی کیا ضرورت تھی؟ حالانکہ آگے صریح روایت (۱۴۹۵) آرہی ہے کہ آپ نے بلند آواز سے قراءت کی اور وہ روایت بھی حضرت عائشہ رضی اللہ عنہا ہی سے ہے۔ اور وہ صحیحین کی روایت ہے۔ دیکھیے: (صحیح البخاری، الکسوف، حدیث:۶۰۶۵ و صحیح مسلم، الکسوف، حدیث:(۵)۔ ۹۰۱) صریح روایت کے مقابلے میں جو اصح بھی ہے، ایک مبہم روایت کو ترجیح نہیں دی جاسکتی۔ بلکہ صریح روایت کو ترجیح ہوگی یا تطبیق دی جائے گی کہ آپ نے قراءت جہراً کی تھی مگر مجمع زیادہ دور ہونے کی وجہ سے قراء ت سنائی نہیں دے سکتی تھی۔ یا دور والوں کو آواز تو سنائی دیتی تھی مگر سمجھ میں نہیں آتی تھی کہ آپ کیا پڑھ رہے ہیں؟ تبھی تو حضرت عائشہ رضی اللہ عنہا جہر کی روایت بھی بیان فرماتی ہیں اور اندازہ بھی لگا رہی ہیں۔ بعض اہل علم نے یہ تطبیق بیان کی ہے کہ طولِ زمانہ کی وجہ سے آپ کو یادنہ رہا کہ نبی صلی اللہ علیہ وسلم نے کیا قراءت کی تھی، اس لیے تخمینہ بیان کیا لیکن پہلی بات ہی درست ہے۔ (۲)اس روایت اور روایت نمبر ۱۴۸۰ میں اختصار ہے کہ دو سجدوں کی تفصیل نہیں صرف سجدے کا ذکر ہے کیونکہ نماز کسوف عام نماز سے صرف رکوع میں مختلف ہے، اس لیے رکوع کی تفصیل بیان کردی کہ وہ ایک رکعت میں دو تھے مگر سجدے تو اتفاقاً ہر نماز میں ایک رکعت میں دو ہی ہیں، لہٰذا اسے مبہم ذکر کردیا۔ کوئی شخص بھی ایک سجدے کا قائل نہیں۔ امام صاحب نے شاید ظاہر الفاظ کے پیش نظر اسے ’’ایک اور صورت‘‘ بنادیا، ورنہ یہ کوئی صورت نہیں، نیز ایک قول یہ بھی ہے کہ یہاں تصحیف واقع ہوئی ہے۔ اصل میں فی سجدۃ تھا، غلطی سے وسجدۃ ہوگیا یا وسجدتین سے وسجدۃ ہوگیا جو یقیناً غلطی ہے۔ تفصیل کے لیے ملاحظہ فرمائیے: (ذخیرہ العقبٰی شرح سنن النسائی: ۱۶؍۴۳۳)"}],[1482,"عبداللہ بن عمرو رضی اللہ عنہم کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم کے زمانے میں سورج گرہن لگا تو رسول اللہ صلی اللہ علیہ وسلم نماز کے لیے کھڑے ہوئے، اور وہ لوگ بھی کھڑے ہوئے جو آپ کے ساتھ تھے، آپ لمبا قیام کیا، پھر لمبا رکوع کیا، پھر رکوع سے اپنا سر اٹھایا، اور لمبا سجدہ کیا، پھر سجدے سے اپنا سر اٹھایا، اور بیٹھے تو دیر تک بیٹھے رہے، پھر آپ سجدہ میں گئے تو لمبا سجدہ کیا، پھر سجدے سے اپنا سر اٹھایا، اور کھڑے ہو گئے، پھر آپ نے دوسری رکعت میں بھی اسی طرح قیام، رکوع، سجدہ اور جلوس کیا جیسے پہلی رکعت میں کیا تھا، پھر دوسری رکعت کے آخری سجدے میں آپ ہانپنے اور رونے لگے، آپ کہہ رہے تھے: \"تو نے مجھ سے اس کا وعدہ نہیں کیا تھا ۱؎، اور حال یہ ہے کہ میں ان میں موجود ہوں، تو نے مجھ سے اس کا وعدہ نہیں کیا تھا، اور ہم تجھ سے (اپنے گناہوں کی) بخشش چاہتے ہیں\"، پھر آپ نے اپنا سر اٹھایا تب سورج صاف ہو چکا تھا، پھر رسول اللہ صلی اللہ علیہ وسلم کھڑے ہوئے، اور آپ نے لوگوں کو خطاب کیا، پہلے اللہ کی حمد و ثنا بیان کی، پھر فرمایا: \"سورج اور چاند اللہ تعالی کی نشانیوں میں سے دو نشانیاں ہیں، تو جب تم ان میں سے کسی کو گرہن لگا دیکھو تو اللہ تعالی کے ذکر کی طرف دوڑ پڑو، قسم ہے اس ذات کی جس کے ہاتھ میں محمد کی جان ہے، جنت مجھ سے قریب کر دی گئی یہاں تک کہ اگر میں اپنے ہاتھوں کو پھیلاتا تو میں اس کے کچھ گچھے لے لیتا، اور جہنم مجھ سے قریب کر دی گئی یہاں تک کہ میں اس سے بچاؤ کرنے لگا، اس خوف سے کہ کہیں وہ تمہیں ڈھانپ نہ لے، یہاں تک کہ میں نے اس میں حمیر کی ایک عورت پر ایک بلی کی وجہ سے عذاب ہوتے ہوئے دیکھا جسے اس نے باندھ رکھا تھا، نہ تو اس نے اسے زمین کے کیڑے مکوڑے کھانے کے لیے چھوڑا، اور نہ ہی اس نے اسے خود کچھ کھلایا پلایا یہاں تک کہ وہ مر گئی، میں نے اسے دیکھا وہ اس عورت کو نوچتی تھی جب وہ سامنے آتی، اور جب وہ پیٹھ پھیر کر جاتی تو اس کے سرین کو نوچتی، نیز میں نے اس میں دو چمڑے کی جوتیوں والے کو دیکھا، جو قبیلہ بنی دعدع کا ایک فرد تھا، اسے دو منہ والی لکڑی سے مار کر آگ میں دھکیلا جا رہا تھا، نیز میں نے اس میں خمدار سر والی لکڑی چرانے والے کو دیکھا، جو حاجیوں کا مال چراتا تھا، وہ جہنم میں اپنی لکڑی پر ٹیک لگائے ہوئے کہہ رہا تھا: میں خمدار سر والی لکڑی چرانے والا ہوں\"۔\n§وضاحت\n۱؎: یعنی میری موجودگی میں انہیں عذاب دینے کا وعدہ نہیں کیا تھا، بلکہ تو نے اس کے برعکس یہ وعدہ کیا تھا کہ تو انہیں میری موجودگی میں عذاب نہیں دے گا۔","الألباني: صحيح",{"u2":"حضرت عبداللہ بن عمرو رضی اللہ عنہما بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم کے زمانے میں سورج کو گرہن لگ گیا تو رسول اللہ صلی اللہ علیہ وسلم نماز کے لیے اٹھے۔ جو لوگ آپ کے ساتھ تھے، وہ بھی اٹھے۔ آپ نے قیام فرمایا اور بڑا لمبا قیام فرمایا، پھر رکوع فرمایا تو بہت لمبا رکوع فرمایا، پھر اپنا سر اٹھایا اور سجدہ فرمایا اور بہت لمبا سجدہ فرمایا، پھر سر اٹھایا اور بیٹھ گئے۔ بہت دیر بیٹھے رہے، پھر دوسرا سجدہ کیا اور بہت لمبا سجدہ کیا، پھر سر اٹھایا اور کھڑے ہوگئے، پھر دوسری رکعت میں بھی اسی طرح قیام، رکوع، سجدہ اور جلسہ کیا جس طرح پہلی رکعت میں کیا تھا۔ دوسری رکعت کے آخری سجدے میں آپ آہیں بھرنے اور رونے لگے۔ آپ فرماتے تھے: ’’اے اللہ! تیرا مجھ سے وعدہ ہے کہ جب تک تو ان کے اندر موجود ہے، میں عذاب نہیں بھیجوں گا۔ اے اللہ! تیرا مجھ سے وعدہ ہے کہ جب تک ہم تجھ سے بخشش طلب کرتے رہیں گے، تو عذاب نازل نہیں کرے گا۔‘‘ پھر آپ نے سر اٹھایا تو سورج روشن ہوچکا تھا، پھر اللہ کے رسول صلی اللہ علیہ وسلم اٹھے اور لوگوں سے خطاب فرمایا۔ پہلے اللہ تعالیٰ کی حمدوثنا بیان فرمائی، پھر فرمایا: ’’بلاشبہ سورج اور چاند اللہ عزوجل کی نشانیوں میں سے دو نشانیاں ہیں۔ جب تم ان میں سے کسی کا گرہن دیکھو تو جلدی سے اللہ تعالیٰ کے ذکر کی طرف چلو۔ قسم اس ذات کی جس کے ہاتھ میں محمد(صلی اللہ علیہ وسلم) کی جان ہے! جنت میرے اتنی قریب کی گئی کہ اگر میں اپنا ہاتھ بڑھاتا تو اس کے (پھلوں کے) کچھ خوشے توڑلیتا۔ اور آگ میرے اس قدر قریب کی گئی کہ میں اس سے بچنے لگا۔ مجھے خطرہ محسوس ہونے لگا تھا کہ کہیں وہ تم پر نہ چھا جائے، نیز میں نے اس میں بنوحمیر کی ایک عورت دیکھی جسے ایک بلی کی وجہ سے عذاب دیا جارہا تھا جسے اس نے باندھے رکھا۔ نہ تو اسے چھوڑا کہ وہ زمین کے کیڑے مکوڑے کھاتی اور نہ اسے خود کھلایا پلایا، حتی کہ وہ (بلی بھوک پیاس سے) مرگئی۔ واللہ! میں نےا سے (بلی کو) دیکھا کہ وہ عورت جب اس کی طرف منہ کرتی تھی تو وہ اسے نوچتی تھی اور جب وہ پیٹھ کرتی تھی تو اس کے سرین کو کاٹتی تھی۔ اور حتی کہ میں نے آگ میں بنودعدع کے ایک جوتا چور کو دیکھا جسے ایک، دوشاخہ لکڑی کے ساتھ آگ میں دھکیلا جارہا تھا۔ اور میں نے آگ میں اس چھڑی والے کو دیکھا جو اپنی چھڑی سے حاجیوں کا سامان چرایا کرتا تھا۔ وہ آگ میں اپنی چھڑی کے سہارا کھڑا کہہ رہا تھا۔ (اے لوگو!) میں ہوں چھڑی سے چوری کرنے والا۔‘‘","f2":"(۱)یہ روایت بھی مختصر ہے۔ اس میں دورکوع کی تفصیل نہیں۔ راویٔ حدیث حضرت عبداللہ بن عمرو رضی اللہ عنہما ہی سے حدیث نمبر ۱۴۸۰ میں صراحتًا مذکور ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے نمازکسوف میں ہر رکعت میں دو رکوع کیے، لہٰذا یہی معتبر ہے۔ امام صاحب رحمہ اللہ نے شاید ظاہر الفاظ کو مدنظر رکھتے ہوئے اسے بھی ’’ایک اور صورت‘‘ بنادیا۔ حقیقتاً یہ کوئی الگ صورت نہیں۔ یا صورت سے مراد نمازکسوف کی اور صورت نہیں ہے بلکہ مراد یہ ہے اس واقعہ کی تفصیل ایک اور انداز میں مذکور ہے۔ واللہ اعلم۔ (۲)’’تیرا مجھ سے وعدہ ہے۔‘‘ اس جملے سے قرآنی آیت: (وما کان اللہ لیعذبھم وانت فیھم) (الانفال۸:۳۳) ’’جب تک تو ان میں موجود ہے، اللہ تعالیٰ انھیں عذاب نہیں دے گا۔‘‘ کی طرف اشارہ ہے۔ رسول اللہ صلی اللہ علیہ وسلم نے نمازکسوف میں جہنم کی آمد کو عذاب کی تمہید خیال فرمایا ہوگا، ورنہ کسوف بذات خود عذاب نہیں۔ (۳)’’خوشے توڑلیتا‘‘ معلوم ہوا حقیقی جنت آپ کو دکھلائی گئی، اسی طرح جہنم بھی۔ (۴)’’چھڑی والا‘‘ اصل لفظ مححن ہے۔ وہ عصا جو آگے سے مڑا ہوا ہو۔"}],[1483,"ابوہریرہ رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم کے زمانے میں سورج گرہن لگا تو آپ کھڑے ہوئے، اور آپ نے لوگوں کو نماز پڑھائی تو لمبا قیام کیا، پھر رکوع کیا تو لمبا رکوع کیا، پھر قیام کیا تو لمبا قیام کیا، اور یہ پہلے قیام سے کم تھا، پھر رکوع کیا تو لمبا رکوع کیا، اور یہ پہلے رکوع سے کم تھا، پھر آپ نے سجدہ کیا تو لمبا سجدہ کیا، پھر آپ نے سجدہ سے سر اٹھایا، پھر سجدہ کیا تو لمبا سجدہ کیا، اور یہ پہلے سجدہ سے کم تھا، پھر آپ (دوسری رکعت کے لیے) کھڑے ہوئے، تو آپ نے دو رکوع کیے، اور ان میں پہلے جیسا ہی کیا، پھر آپ نے دو سجدے کیے، ان دونوں میں اسی طرح کرتے رہے جیسے پہلے کیا تھا یہاں تک کہ اپنی نماز سے فارغ ہو گئے، پھر آپ نے فرمایا: \"سورج اور چاند اللہ تعالی کی نشانیوں میں سے دو نشانیاں ہیں، ان دونوں کو نہ کسی کے مرنے سے گرہن لگتا ہے اور نہ کسی کے پیدا ہونے سے، لہٰذا جب تم انہیں(گرہن لگا) دیکھو، تو تم اللہ کے ذکر اور نماز کی طرف دوڑ پڑو\"۔","الألباني: حسن صحيح",{"u2":"حضرت ابوہریرہ رضی اللہ عنہ بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم کے زمانے میں سورج گہنا گیا۔ آپ اٹھے اور لوگوں کو نماز پڑھائی۔ لمبا قیام کیا، پھر رکوع کیا اور لمبا رکوع کیا، پھر کھڑے ہوئے اور لمبا قیام کیا لیکن یہ پہلے قیام سے کم تھا، پھر رکوع فرمایا اور لمبا رکوع فرمایا مگر یہ پہلے رکوع سے کم تھا، پھر سجدہ کیا اور لمبا سجدہ کیا، پھر سر اٹھایا، پھر دوسرا سجدہ کیا اور لمبا سجدہ کیا لیکن یہ پہلے سجدے سے کم تھا، پھر کھڑے ہوئے اور دورکوع کیے۔ دونوں میں ایسے ہی کیا، پھر دو سجدے کیے۔ دونوں میں ایسے ہی کیا، حتی کہ نماز سے فارغ ہوگئے، پھر فرمایا: ’’یقیناً سورج اور چاند اللہ تعالیٰ کی نشانیوں میں سے دو نشانیاں ہیں اور یہ کسی کی موت و حیات کی وجہ سے نہیں گہناتے۔ جب تم ان کی یہ حالت دیکھو تو فوراً اللہ تعالیٰ کا ذکر اور نماز شروع کردو۔‘‘"}],[1484,"ثعلبہ بن عباد العبدی بیان کرتے ہیں کہ وہ ایک دن سمرہ بن جندب رضی اللہ عنہ کے خطبہ میں حاضر ہوئے، تو انہوں نے اپنے خطبہ میں رسول اللہ صلی اللہ علیہ وسلم سے مروی ایک حدیث ذکر کی، سمرہ بن جندب رضی اللہ عنہ نے کہا کہ رسول اللہ صلی اللہ علیہ وسلم کے زمانے میں ایک دن میں اور ایک انصاری لڑکا دونوں تیر سے نشانہ بازی کر رہے تھے، یہاں تک کہ سورج دیکھنے والے کی نظر میں افق سے دو تین نیزے کے برابر اوپر آ چکا تھا کہ اچانک وہ سیاہ ہو گیا، ہم میں سے ایک نے اپنے دوسرے ساتھی سے کہا: چلو مسجد چلیں، قسم اللہ کی اس سورج کا معاملہ رسول اللہ صلی اللہ علیہ وسلم کے لیے آپ کی امت میں ضرور کوئی نیا واقعہ رونما کرے گا، پھر ہم مسجد گئے تو ہم نے رسول اللہ صلی اللہ علیہ وسلم کو ایسے وقت میں پایا جب آپ لوگوں کی طرف نکلے، پھر آپ آگے بڑھے اور آپ نے نماز پڑھائی، تو اتنا لمبا قیام کیا کہ ایسا قیام آپ نے کبھی کسی نماز میں نہیں کیا تھا، ہم آپ کی آواز سن نہیں رہے تھے، پھر آپ نے رکوع کیا تو اتنا لمبا رکوع کیا کہ ایسا رکوع آپ نے کبھی کسی نماز میں نہیں کیا تھا، ہم آپ کی آواز سن نہیں رہے تھے، پھر آپ نے ہمارے ساتھ سجدہ کیا تو اتنا لمبا سجدہ کیا کہ ایسا سجدہ آپ نے کبھی کسی نماز میں نہیں کیا تھا، ہم آپ کی آواز سن نہیں رہے تھے، پھر آپ نے ایسے ہی دوسری رکعت میں بھی کیا، دوسری رکعت میں آپ کے بیٹھنے کے ساتھ ہی سورج صاف ہو گیا، تو آپ نے سلام پھیرا، اور اللہ کی حمد اور اس کی ثنا بیان کی، اور گواہی دی کہ نہیں ہے کوئی حقیقی معبود سوائے اللہ کے، اور گواہی دی کہ آپ اللہ تعالی کے بندے اور اس کے رسول ہیں، (یہ حدیث مختصر ہے)۔","الألباني: ضعيف",{"u2":"حضرت ثعلبہ بن عباد عبدی سے روایت ہے۔۔۔ وہ بصرہ کے رہنے والے تھے۔۔۔ انھوں نے اپنے خطبے میں رسول اللہ صلی اللہ علیہ وسلم سے ایک حدیث بیان فرمائی۔ فرمایا: ایک دن میں اور انصار کا ایک لڑکا رسول اللہ صلی اللہ علیہ وسلم کے زمانے میں (اپنے مقرر کردہ نشانوںپر) تیراندازی کررہے تھے۔ جب سورج دیکھنے والے کی نظر میں افق سے دوتین نیزے اونچا آگیا تو بے نور ہوگیا۔ ہم میں سے ایک نے دوسرے سے کہا: آؤ مسجد چلیں۔ اللہ کی قسم! سورج کی یہ حالت رسول اللہ صلی اللہ علیہ وسلم کے لیے آپ کی امت میں کسی نئے حکم کا سبب بنے گی۔ ہم مسجد کی طرف چلے تو رسول اللہ صلی اللہ علیہ وسلم ہمیں لوگوں کی طرف نکلتے ہوئے ملے۔ آپ آگے بڑھے اور نماز شروع کردی۔ آپ نے اتنا لمبا قیام فرمایا کہ کبھی کسی نماز میں اتنا لمبا قیام نہیں فرمایا۔ ہم آپ کی آواز نہیں سنتے تھے، پھر آپ نے ہمارے ساتھ رکوع کیا اور اتنا لمبا رکوع کہ کبھی کسی نماز میں اتنا لمبا رکوع نہیں کیا تھا۔ ہم آپ کی آواز نہیں سنتے تھے، پھر آپ نے ہمارے ساتھ سجدہ کیا۔ اتنا لمبا سجدہ کہ کبھی کسی نماز میں اتنا لمبا سجدہ نہیں کیا تھا۔ ہم آپ کی آواز نہیں سنتے تھے، پھر آپ نے دوسری رکعت میں بھی ایسےہی کیا۔ جب آپ دوسری رکعت کے آخر میں بیٹھے تو سورج روشن ہوچکا تھا۔ آپ نے سلام پھیرا، پھر اللہ کی حمدوثنا کی اور اس بات کی شہادت دی کہ اللہ کے سوا کوئی (حقیقی اور سچا) معبود نہیں اور اس بات کی شہادت دی کہ وہ (آپ) اللہ کے بندے اور اس کے بھیجے ہوئے (رسول) ہیں۔ یہ روایت مختصر ہے۔","f2":"(۱)’’ہم آپ کی آواز نہیں سنتے تھے۔‘‘ اس کا یہ مطلب نہیں کہ آپ نے بلند آواز سے قراءت نہیں کی بلکہ اپنے سماع کی نفی کی ہے کہ اجتماع اتنا زیادہ تھا اور ہم اتنی دور تھے کہ ہمیں آپ کی آواز سنائی نہیں دیتی تھی۔ حقیقتاً یہ الفاظ آپ کی جہر پر دلالت کرتے ہیں کہ آپ کی آواز تو تھی مگر ہمیں سنائی نہیں دیتی تھی۔ (۲)اس روایت میں صرف ایک رکوع اور ایک سجدے کا ذکر ہے۔ دراصل یہ روایت مختصر ہے۔ مقصد رکوع اور سجدے کی طوالت کا اظہار ہے نہ کہ تعداد کا بیان۔ حقیقتاً دو رکوع تھے اور دوسجدے جیسا کہ دوسری مشہور روایات میں صراحتاً ذکر ہے، ورنہ ایک سجدے کا تو کوئی بھی قائل نہیں، نیز بعض محققین کے نزدیک یہ روایت ضعیف ہے۔ اس صورت میں مذکورہ بالا تطبیق کی ضرورت نہیں رہتی۔ مزید دیکھیے: (ذخیرۃ العقبٰی شرح سنن النسائی: ۱۷؍۵۔۹، وضعیف سنن النسائی، رقم: ۱۴۸۳، وسنن ابن ماجہ بتحقیق الدکتور بشارعواد، حدیث:۱۲۶۴)"}],[1485,"نعمان بن بشیر رضی اللہ عنہم کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم کے زمانے میں سورج گرہن لگا تو آپ گھبرائے ہوئے اپنے کپڑے کو گھسیٹتے ہوئے باہر نکلے یہاں تک کہ آپ مسجد آئے، اور ہمیں برابر نماز پڑھاتے رہے یہاں تک کہ سورج صاف ہو گیا، جب سورج صاف ہو گیا تو آپ نے فرمایا: \"کچھ لوگ سمجھتے ہیں کہ سورج اور چاند گرہن کسی بڑے آدمی کے مرنے پر لگتا ہے، ایسا کچھ نہیں ہے، سورج اور چاند گرہن نہ تو کسی کے مرنے کی وجہ سے لگتا ہے اور نہ ہی کسی کے پیدا ہونے سے، بلکہ یہ دونوں اللہ تعالی کی نشانیوں میں سے دو نشانیاں ہیں، اللہ تعالی جب اپنی کسی مخلوق کے لیے اپنی تجلی ظاہر کرتا ہے، تو وہ اس کے لیے جھک جاتی ہے، تو جب کبھی تم اس صورت حال کو دیکھو تو تم اس تازہ فرض نماز کی طرح نماز پڑھو، جو تم نے (گرہن لگنے سے پہلے) پڑھی ہے\" ۱؎۔\n§وضاحت\n۱؎: یہ حدیث ضعیف ہے، آپ نے گرہن کی نماز عام نمازوں کی طرح ایک رکوع سے نہیں پڑھی تھی بلکہ دو رکوع سے پڑھی تھی۔","الألباني: ضعيف",{"u2":"حضرت نعمان بن بشیر رضی اللہ عنہما بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم کے زمانے میں سورج گہنا گیا۔ آپ گھبرا کر اپنا کپڑا (بالائی چادر) گھسیٹتے ہوئے گھر سے نکلے حتی کہ مسجد میں آئے اور ہمیں نماز پڑھائی حتی کہ سورج صاف ہوگیا۔ جب سورج صاف ہوگیا تو فرمایا: ’’لوگ کہتے ہیں کہ سورج اور چاند کسی بڑے سردار کی موت ہی پر گہناتے ہیں، حالانکہ یہ حقیقت نہیں۔ سورج اور چاند کسی کی موت و حیات کی وجہ س نہیں گہناتے بلکہ یہ تو اللہ تعالیٰ کی (عظمت و توحید کی) نشانیوں میں سے دونشانیاں ہیں۔ جب اللہ عزوجل اپنی کسی مخلوق پر تجلی فرماتا ہے تو وہ مخلوق فوراً اس کی اطاعت کرتی ہے۔ جب تم یہ صورت حال دیکھو تو اس قریب ترین فرض نماز کی طرح نماز پڑھو جو تم نے (اب سے پہلے) پڑھی ہے، (یعنی فجر کی طرح۔‘‘)","f2":"’’قریب ترین نماز کی طرح‘‘ احناف نے ان الفاظ سے استدلال کیا ہے کہ نمازکسوف میں ایک رکوع ہی کرنا چاہیے، حالانکہ دو رکوع والی روایات اقویٰ اور بالکل صریح ہیں جبکہ اس روایت میں رکوع کا ذکر نہیں۔ باقی رہی تشبیہ تو وہ رکعات کی تعداد میں بھی ہوسکتی ہے، یعنی دورکعات پڑھو۔ کیا مبہم روایت کی وجہ سے بہت سی صریح اور قوی روایات کو چھوڑا جاسکتا ہے؟ پھر لطیفہ یہ ہے کہ صبح کی نماز تو جہراً ہوتی ہے۔ اس تشبیہ کے مطابق تو نمازکسوف جہراً ہونی چاہیے، مگر احناف اس کے قائل نہیں جبکہ جہر کا ذکر صحیح حدیث میں ہے۔ کیا یہ تعجب کی بات نہیں ہے کہ صحیح حدیث کے موافق تو استدلال نہ کیا جائے۔ لیکن دوسری صحیح احادیث کے خلاف استدلال کیا جائے؟ واللہ ھو الموفق۔ علاوہ ازیں مذکورہ روایت کو محققین نے ضعیف قرار دیا ہے، تاہم حدیث کے پہلے حصے: [ان الشمس والقمر لاینکسفان الا لموت عظیم۔۔۔ ولا لحمائۃ] کو تو صحیح قرار دیا جاسکتا ہے، کیونکہ اس کا مجموعی مضمون دیگر صحیح احادیث سے ثابت ہے، البتہ اس سے اگلا حصہ محققین کے نزدیک بالاتفاق ضعیف ہے۔ تفصیل کے لیے دیکھیے: (ذخیرۃ العقبٰی شرح سنن النسائی:۱۷؍۹۔۱۴، وضعیف سنن النسائی للالباتی، رقم:۱۴۸۴)"}],[1486,"قبیصہ بن مخارق الہلالی رضی اللہ عنہ کہتے ہیں کہ سورج گرہن لگا، ہم لوگ اس وقت رسول اللہ صلی اللہ علیہ وسلم کے ساتھ مدینہ میں تھے، آپ گھبرائے ہوئے اپنا کپڑا گھسیٹتے ہوئے باہر نکلے، پھر آپ نے دو رکعت نماز پڑھی، اور اتنا لمبا کیا کہ آپ جب نماز سے فارغ ہوئے تو سورج چھٹ چکا تھا، آپ نے اللہ کی حمد و ثنا بیان کی، پھر آپ نے فرمایا: \"سورج اور چاند اللہ تعالی کی نشانیوں میں سے دو نشانیاں ہیں، ان دونوں کو نہ کسی کے مرنے سے گرہن لگتا ہے اور نہ کسی کے پیدا ہونے سے، تو جب تم اس میں سے کچھ دیکھو تو اس تازہ فرض نماز کی طرح نماز پڑھو جو تم نے (گرہن لگنے پہلے) پڑھی ہے\"۔","الألباني: ضعيف",{"u2":"حضرت قبیصہ بن مخارق ہلالی رضی اللہ عنہ بیان کرتے ہیں کہ ہم رسول اللہ صلی اللہ علیہ وسلم کے ساھ مدینے میں تھے کہ سورج گہنا گیا۔ آپ گھبرا کر اپنا کپڑا گھسیٹتے ہوئے نکلے، پھر آپ نے دو رکعتیں پڑھیں اور خوب لمبی پڑھیں۔ ادھر آپ نماز سے فارغ ہوئے، ادھر سورج بھی روشن ہوگیا۔ آپ نے اللہ تعالیٰ کی حمدوثنا بیان کی، پھر فرمایا: ’’سورج اور چاند اللہ تعالیٰ کی نشانیوں میں سے دو نشانیاں ہیں اور انھیں کسی کی موت و حیات کی بنا پر گرہن نہیں لگتا۔ جب تم اس قسم کی کوئی چیز دیکھو تو اس قریب ترین فرض نماز کی طرح نماز پڑھو جو تم نے پڑھی ہے۔‘‘"}],[1487,"قبیصہ الہلالی رضی اللہ عنہ سے روایت ہے کہ سورج گرہن لگا تو نبی کریم صلی اللہ علیہ وسلم نے دو دو رکعتیں پڑھیں یہاں تک کہ وہ صاف ہو گیا، پھر آپ نے فرمایا:\"سورج اور چاند کو کسی کے مرنے سے گرہن نہیں لگتا، بلکہ یہ دونوں اللہ تعالی کی مخلوقات میں سے دو مخلوق ہیں، اور اللہ تعالی اپنی مخلوق میں جو چاہتا ہے نئی بات پیدا کرتا ہے، اور اللہ تعالی جب اپنی مخلوق میں سے کسی پر تجلی فرماتا ہے تو وہ اس کے لیے جھک جاتی ہے، لہٰذا جب ان دونوں میں سے کوئی رونما ہو تو تم نماز پڑھو یہاں تک کہ وہ چھٹ جائے، یا اللہ تعالی کوئی نیا معاملہ ظاہر فرما دے\"۔","الألباني: ضعيف",{"u2":"حضرت قبیصہ ہلالی رضی اللہ عنہ سے مروی ہے کہ ایک دفعہ سورج گہنا گیا تو نبی صلی اللہ علیہ وسلم نے دو رکعتیں پڑھیں حتی کہ سورج روشن ہوگیا، پھر آپ نے فرمایا: ’’بلاشبہ سورج اور چاند کسی کی موت کی بنا پر نہیں گہناتے بلکہ وہ اللہ تعالیٰ کی مخلوقات میں سے دو مخلوق ہیں اور اللہ تعالیٰ اپنی مخلوق میں جو چاہے تبدیلی لاتا ہے اور اللہ تعالی جب اپنی کسی مخلوق پر تجلی فرماتا ہے تو وہ فوراً اس کی اطاعت کرتی ہے۔ تو جب ان دونوں میں سے کسی میں کوئی تبدیلی واقع ہو(سورج یا چاند کو گرہن لگے) تو نماز پڑھو حتی کہ وہ روشن ہوجائے یا اللہ تعالیٰ کوئی اور امر صادر فرمادے۔‘‘"}],[1488,"نعمان بن بشیر رضی اللہ عنہم سے روایت ہے کہ نبی اکرم صلی اللہ علیہ وسلم نے فرمایا: \"جب سورج اور چاند کو گرہن لگے تو نماز پڑھو، اس تازہ نماز کی طرح جو تم نے(گرہن لگنے سے پہلے) پڑھی ہے\"۔","الألباني: ضعيف",{"u2":"حضرت نعمان بن بشیر رضی اللہ عنہما سے روایت ہے، نبی صلی اللہ علیہ وسلم نے فرمایا: ’’جب سورج یا چاند کو گرہن لگ جائے تو اس قریب ترین نماز کی طرح نماز پڑھو جو تم نے پڑھی ہے، (یعنی فجر کی نماز)۔‘‘"}],[1489,"نعمان بن بشیر رضی اللہ عنہم سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے جس وقت سورج گرہن لگا ہماری نماز کی طرح نماز پڑھی آپ رکوع کر رہے تھے اور سجدہ کر رہے تھے۔","الألباني: ضعيف",{"u2":"حضرت نعمان بن بشیر رضی اللہ عنہما سے مروی ہے کہ جب سورج کو گرہن لگا تو رسول اللہ صلی اللہ علیہ وسلم نے ہماری نماز کی طرح نماز پڑھی۔ آپ رکوع اور سجدہ کرتے تھے۔","f2":"ہماری عام نماز کی طرح اس میں بھی رکوع سجدے تھے۔ وہ صرف قیام ہی پر مشتمل نہ تھی، یا جس طرح ہم نمازکسوف پڑھتے ہیں، اسی طرح آپ صلی اللہ علیہ وسلم نے پڑھی تھی۔ اس روایت میں رکوع کی تعداد کی بحث نہیں۔"}],[1490,"نعمان بن بشیر رضی اللہ عنہم کہتے ہیں کہ ایک دن نبی اکرم صلی اللہ علیہ وسلم بڑی جلدی میں گھر سے مسجد کی طرف نکلے، سورج گرہن لگا تھا، آپ نے نماز پڑھی یہاں تک کہ سورج صاف ہو گیا، پھر آپ نے فرمایا: \"زمانہ جاہلیت کے لوگ کہا کرتے تھے کہ سورج اور چاند گرہن زمین والوں میں بڑے لوگوں میں سے کسی بڑے آدمی کے مر جانے کی وجہ سے لگتا ہے۔ حالانکہ سورج اور چاند نہ تو کسی کے مرنے پر گہناتے ہیں اور نہ ہی کسی کے پیدا ہونے پر، بلکہ یہ دونوں اللہ کی مخلوق میں سے دو مخلوق ہیں، اللہ تعالی اپنی مخلوقات میں جو نیا واقعہ چاہتا ہے رونما کرتا ہے، تو ان میں سے کوئی (بھی) گہنائے تو تم نماز پڑھو یہاں تک کہ وہ صاف ہو جائے، یا اللہ کوئی نیا معاملہ ظاہر فرما دے\"۔","الألباني: ضعيف",{"u2":"حضرت نعمان بن بشیر رضی اللہ عنہما سے منقول ہے کہ ایک دن نبی صلی اللہ علیہ وسلم مسجد کی طرف تیزی سے نکلے کیونکہ سورج کو گرہن لگ گیا تھا۔ آپ نماز پڑھتے رہے حتی کہ سورج روشن ہوگیا۔ پھر آپ نے فرمایا: ’’جاہلیت والے لوگ کہتے تھے کہ سورج اور چاند کو کسی بڑے زمینی سردار کی موت کی وجہ سے گرہن لگتا ہے، جبکہ حقیقت یہ ہے کہ سورج اور چاند کو کسی کی موت و حیات کی وجہ سے گرہن نہیں لگتا بلکہ یہ دونوں تو اللہ تعالیٰ کی مخلوقات میں سے دو مخلوقیں ہیں۔ اللہ تعالیٰ اپنی مخلوق میں جو چاہے تبدیلی لاسکتا ہے، لہٰذا ان میں سے کسی کو گرہن لگ جائے تو نماز پڑھو حتی کہ وہ روشن ہوجائے یا اللہ تعالیٰ کوئی نیا امر جاری فرمادے۔‘‘","f2":"۱۴۸۵ تا ۱۴۹۱ تک تمام روایات ضعیف ہیں، لہٰذا ان سے استدلال درست نہیں۔ کسوف کا اصح طریقہ اور تفصیل گزشتہ صحیح احادیث میں گزر چکی ہے۔"}],[1491,"ابوبکرہ رضی اللہ عنہ کہتے ہیں کہ ہم رسول اللہ صلی اللہ علیہ وسلم کے پاس تھے کہ سورج گرہن لگا، رسول اللہ صلی اللہ علیہ وسلم اپنی چادر گھسیٹتے ہوئے نکلے یہاں تک کہ آپ مسجد پہنچے، اور لوگ (بھی) آپ کی طرف لپکے، پھر آپ نے ہمیں دو رکعت نماز پڑھائی، جب سورج صاف ہو گیا تو آپ نے فرمایا: \"سورج اور چاند اللہ تعالی کی نشانیوں میں سے دو نشانیاں ہیں جن کے ذریعہ اللہ تعالی اپنے بندوں کو ڈراتا ہے، اور یہ دونوں نہ تو کسی کے مرنے پر گہناتے ہیں اور نہ ہی کسی کے پیدا ہونے پر، تو جب تم انہیں گہنایا ہوا دیکھو تو نماز پڑھو یہاں تک کہ وہ چیز چھٹ جائے جو تم پر آن پڑی ہے\"، اور آپ نے یہ اس لیے فرمایا کہ (اسی روز) آپ صلی اللہ علیہ وسلم کے صاحبزادے ابراہیم کا انتقال ہوا تھا، تو کچھ لوگوں نے آپ سے یہ بات کہی تھی۔","الألباني: صحيح",{"u2":"حضرت ابوبکرہ رضی اللہ عنہ بیان کرتے ہیں کہ ہم رسول اللہ صلی اللہ علیہ وسلم کے پاس تھے کہ سورج کو گرہن لگ گیا تو رسول اللہ صلی اللہ علیہ وسلم اپنی بالائی چادر کو گھسیٹتے ہوئے نکلے حتی کہ مسجد میں پہنچے۔ لوگ بھی آپ کے پاس جمع ہوگئے۔ آپ نے ہمیں دو رکعتیں پڑھائیں۔ جب گرہن ختم ہوگیا تو آپ نے فرمایا: ’’سورج اور چاند اللہ تعالیٰ کی دو نشانیاں ہیں۔ اللہ تعالیٰ ان (کے گرہن) کے ذریعے سے اپنے بندوں کو ڈراتا ہے۔ انھیں کسی کی موت و حیات کی بنا پر گرہن نہیں لگتا، چنانچہ جب تم ایسی صورت حال دیکھو تو نماز شروع کردو حتی کہ گرہن ختم ہوجائے۔‘‘ یہ آپ نے، اس لیے ارشاد فرمایا کہ اس دن آپ کا بیٹا (حضرت ابراہیم رضی اللہ عنہ) فوت ہوگیا تھا تو لوگوں نے اس کے بارے میں یہ کہنا شروع کردیا تھا (کہ گرہن ان کی وفات کی وجہ سے لگا ہے)۔"}],[1492,"ابوبکرہ رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے تمہاری اسی نماز کی طرح دو رکعت نماز پڑھی، اور انہوں نے سورج گرہن لگنے کا ذکر کیا۔","الألباني: صحيح",{"u2":"حضرت ابوبکرہ رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے تمھاری اس نماز (نماز کسوف) کی طرح دورکعتیں پڑھی تھیں اور انھوں نے سورج گرہن کا ذکر کیا تھا۔","f2":"بعض حضرات نے ’’اس نماز‘‘ سے مراد عام نماز لی ہے اور پھر نمازکسوف میں ایک رکوع پر استدلال کیا ہے، حالانکہ یہ استدلال صریح اور اقویٰ روایات کے خلاف ہے۔ عمل صریح پر ہوتا ہے نہ کہ اس قسم کے مبہم الفاظ پر۔"}],[1493,"عبداللہ بن عباس رضی اللہ عنہم کہتے ہیں کہ سورج گرہن لگا تو رسول اللہ صلی اللہ علیہ وسلم نے اور آپ کے ساتھ لوگوں نے نماز پڑھی، آپ نے قیام کیا تو لمبا قیام کیا، اور سورۃ البقرہ جیسی سورت پڑھی، پھر آپ نے ایک لمبا رکوع کیا، پھر اپنا سر اٹھایا تو لمبا قیام کیا، اور یہ پہلے سے کم تھا، پھر آپ نے ایک لمبا رکوع کیا، اور یہ پہلے رکوع سے کم تھا، پھر آپ نے سجدہ کیا، پھر ایک لمبا قیام کیا، اور یہ پہلے قیام سے کم تھا، پھر آپ نے ایک لمبا رکوع کیا، اور یہ پہلے رکوع سے کم تھا، پھر آپ نے رکوع سے اپنا سر اٹھایا، پھر ایک لمبا قیام کیا، اور یہ پہلے قیام سے کم تھا، پھر آپ نے ایک لمبا رکوع کیا، اور یہ پہلے رکوع سے کم تھا، پھر آپ نے سجدہ کیا، جب آپ نماز سے فارغ ہوئے تو سورج صاف ہو چکا تھا، تو آپ صلی اللہ علیہ وسلم نے فرمایا: \"سورج اور چاند اللہ تعالی کی نشانیوں میں سے دو نشانیاں ہیں، یہ دونوں کسی کے مرنے سے نہیں گہناتے ہیں، اور نہ کسی کے پیدا ہونے سے، چنانچہ جب تم انہیں گہنایا ہوا دیکھو تو اللہ تعالی کو یاد کرو\"، لوگوں نے آپ سے عرض کیا: اللہ کے رسول! ہم نے آپ کو دیکھا کہ آپ اپنی جگہ میں کسی چیز کو آگے بڑھ کر لے رہے تھے، اور پھر ہم نے دیکھا آپ پیچھے ہٹ رہے تھے؟ تو آپ نے فرمایا: \"میں نے جنت کو دیکھا یا مجھے جنت دکھائی گئی تو میں اس میں سے پھل کا ایک گچھا لینے کے لیے آگے بڑھا، اور اگر میں اسے لے لیتا تو تم اس سے رہتی دنیا تک کھاتے، اور میں نے جہنم کو دیکھا چنانچہ میں نے آج سے پہلے اس بھیانک منظر کی طرح کبھی نہیں دیکھا تھا، اور میں نے اہل جہنم میں زیادہ تر عورتوں کو دیکھا\"، انہوں نے پوچھا: اللہ کے رسول! ایسا کیوں ہے؟ تو آپ نے فرمایا: \"ایسا ان کے کفر کی وجہ سے ہے\"، پوچھا گیا: کیا وہ اللہ کے ساتھ کفر کرتی ہیں؟ آپ نے فرمایا: \"(نہیں بلکہ) وہ شوہر کے ساتھ کفر کرتی ہیں (یعنی اس کی ناشکری کرتی ہیں) اور (اس کے) احسان کا انکار کرتی ہیں، اگر تم ان میں سے کسی کے ساتھ زمانہ بھر احسان کرو، پھر اگر وہ تم سے کوئی چیز دیکھے تو وہ کہے گی: میں نے تم سے کبھی بھی کوئی بھلائی نہیں دیکھی\"۔","الألباني: صحيح",{"u2":"حضرت عبداللہ بن عباس رضی اللہ عنہما بیان کرتے ہیں کہ سورج کو گرہن لگ گیا۔ رسول اللہ صلی اللہ علیہ وسلم نے نماز پڑھی جبکہ لوگ بھی آپ کے ساتھ (نماز میں شامل) تھے۔ آپ نے لمبا قیام فرمایا اور سورۂ بقرہ کے برابر قراءت کی، پھر آپ نے لمبا رکوع فرمایا، پھر سر اٹھایا اور لمبا قیام کیا جبکہ یہ پہلے قیام سے کم تھا، پھر لمبا رکوع کیا اور یہ پہلے رکوع سے کم تھا، پھر سجدے کیے، پھر لمبا قیام کیا اور یہ پہلے قیام سے کم تھا، پھر لمبا رکوع فرمایا اور یہ پہلے رکوع سے کم تھا، پھر سر اٹھایا اور لمبا قیام فرمایا مگر یہ پہلے قیام سے کم تھا، پھر لمبا رکوع فرمایا مگر یہ پہلے رکوع سے کم تھا، پھر سجدے کیے، پھر سلام پھیرا۔ اس وقت تک سورج روشن ہوچکا تھا، پھر آپ نے فرمایا: ’’بلاشبہ سورج اور چاند اللہ تعالیٰ کی دو نشانیاں ہیں۔ انھیں کسی کی موت و حیات کی وجہ سے گرہن نہیں لگتا، لہٰذا جب تم یہ صورت حال دیکھو تو اللہ عزوجل کو یاد کیا کرو۔‘‘ لوگوں نے کہا: اے اللہ ے رسول! ہم نے آپ کو دیکھا تھا کہ آپ نے اپنے قیام کے دوران میں کسی چیز کو پکڑنے کی کوشش کی، پھر ہم نےد یکھا کہ آپ پیچھے ہٹے؟ آپ نے فرمایا: ’’میں نے جنت دیکھی‘‘ یا فرمایا: ’’مجھے جنت دکھائی گئی تو میں نے اس سے ایک خوشہ لینے کی کوشش کی تھی اور اگر میں اسے لے لیتا تو تم رہتی دنیا تک اس سے کھاتے رہتے، نیز میں نے آگ دیکھی۔ میں نے اس جیسا خوف ناک منظر کبھی نہیں دیکھا اور میں نے جہنم میں زیادہ عورتوں کو دیکھا۔‘‘ لوگوں نے کہا: اے اللہ کے رسول! کیوں؟ آپ نے فرمایا: ’’اپنے کفر کی وجہ سے۔‘‘ کہا گیا: وہ اللہ کے ساتھ کفر کرتی ہیں؟ آپ نے فرمایا: ’’نہیں، وہ خاوند کی ناشکری کرتی ہیں اور احسان فراموش ہیں۔ اگر تو ان میں سے کسی کے ساتھ ساری زندگی حسن سلوک کرے، پھر وہ تجھ سے کوئی ناگوار چیز دیکھے تو کہے گی: میں نے تجھ سے کبھی کوئی اچھا سلوک نہیں دیکھا۔‘‘","f2":"(۱)نمازکسوف میں لمبا قیام وغیرہ سورج کو روشن کرنے کے لیے نہیں، اس نے اپنے معمول کے مطابق روشن ہوہی جانا ہوتا ہے، کوئی نماز پڑھے یا نہ پڑھے یا گالیاں دے کیونکہ وہ تکوینی چیز ہے۔ یہ تو صرف وقتی فریضہ ادا کرنے کے لیے ہے، جیسے صبح کی نماز لمبی پڑھی جاتی ہے۔ عموماً کسوف کا وقت طویل ہوتا ہے۔ خصوصاً آپ کے دور کا کسوف مکمل سورج گرہن تھا اور مکمل سورج گرہن ختم ہونے میں کافی وقت لگتا ہے، لہٰذا اس نماز میں طوالت مستحب اور وقتی تقاضا ہے۔ (۲)کفر کے معنی انکار کرنا بھی ہیں، ناشکری کرنا بھی۔ یہاں دوسرے معنی مراد ہیں۔ اور جہنم میں یہ دخول عارضی ہے کیونکہ گناہ گار مومنوں کا اصل اور مستقل ٹھکانا جنت ہے، ہاں حقیقی کافر دائمی جہنمی ہیں اور جہنم ان کا مستقل ٹھکانا ہے۔"}],[1494,"ام المؤمنین عائشہ رضی اللہ عنہا کہتی ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے چار رکوع اور چار سجدوں کے ساتھ (گرہن کی) نماز پڑھی، آپ نے ان میں بلند آواز سے قرآت کی، آپ جب جب رکوع سے سر اٹھاتے تو «سمع اللہ لمن حمده، ربنا ولك الحمد» کہتے۔","الألباني: صحيح",{"u2":"حضرت عائشہ رضی اللہ عنہا سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے چار سجدوں (یعنی دورکعتوں) میں چار رکوع کیے۔ اور نماز کسوف میں بلند آواز سے قراءت فرمائی۔ جب بھی رکوع سے سر اٹھاتے تھے تو کہتے: [سمع اللہ لمن حمدہ، ربنا ولک الحمد]","f2":"گویا دونوں رکوعوں سے اٹھتے وقت سمع اللہ لمن حمدہ۔۔۔ ہی کہنا ہے۔ امام شافعی سے پہلے رکوع کے بعد اللہ اکبر منقول ہے مگر یہ درست نہیں۔ صریح روایت کے مقابلے میں قیاس معتبر نہیں۔"}],[1495,"سمرہ رضی اللہ عنہ سے روایت ہے کہ نبی اکرم صلی اللہ علیہ وسلم نے سورج گرہن کی نماز پڑھائی (وہ کہتے ہیں) کہ ہم آپ کی آواز نہیں سن رہے تھے۔","الألباني: ضعيف",{"u2":"حضرت سمرہ بن جندب رضی اللہ عنہ سے مروی ہے کہ نبی صلی اللہ علیہ وسلم نے ہمیں نمازکسوف پڑھائی۔ ہم آپ کی آواز نہیں سنتے تھے۔","f2":"اس مسئلے کی تفصیلی بحث کے لیے حدیث نمبر:۱۴۸۲ و ۱۴۸۵ کے فوائدومسائل دیکھیے۔"}],[1496,"عبداللہ بن عمرو رضی اللہ عنہم کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم کے عہد میں سورج گرہن لگا، تو آپ نے نماز پڑھی، تو لمبا قیام کیا، پھر آپ نے رکوع کیا تو لمبا رکوع کیا، پھر (رکوع سے) سر اٹھایا تو دیر تک کھڑے رہے (شعبہ کہتے ہیں: میرا گمان ہے عطاء نے سجدے کے سلسلہ میں بھی یہی بات کہی ہے) اور آپ سجدے میں رونے اور پھونک مارنے لگے، آپ فرما رہے تھے: \"میرے رب! تو نے مجھ سے اس کا وعدہ نہیں کیا تھا، میں تجھ سے پناہ طلب کرتا ہوں، تو نے مجھ سے اس کا وعدہ نہیں کیا تھا اور حال یہ ہے کہ میں لوگوں میں موجود ہوں\"، جب آپ نماز پڑھ چکے تو فرمایا: \"مجھ پر جنت پیش کی گئی یہاں تک کہ اگر میں اپنے ہاتھوں کو پھیلاتا تو میں اس کے پھلوں گچھوں میں سے توڑ لیتا، نیز مجھ پر جہنم پیش کی گئی تو میں پھونکنے لگا اس ڈر سے کہ کہیں اس کی گرمی تمہیں نہ ڈھانپ لے، اور میں نے اس میں اس چور کو دیکھا جو رسول اللہ صلی اللہ علیہ وسلم کے اونٹوں کو چرایا تھا، اور میں نے اس میں بنو دعدع کے اس شخص کو دیکھا جو حاجیوں کا مال چرایا کرتا تھا، اور جب وہ پہچان لیا جاتا تو کہتا: یہ (میری اس) خمدار لکڑی کا کام ہے، اور میں نے اس میں ایک کالی لمبی عورت کو دیکھا جسے ایک بلی کے سبب عذاب ہو رہا تھا، جسے اس نے باندھ رکھا تھا، نہ تو وہ اسے کھلاتی پلاتی تھی اور نہ ہی اسے آزاد چھوڑتی تھی کہ وہ زمین کے کیڑے مکوڑے کھا لے، یہاں تک کہ وہ مر گئی، اور سورج اور چاند نہ تو کسی کے مرنے کی وجہ سے گہناتے ہیں، اور نہ ہی کسی کے پیدا ہونے سے، بلکہ یہ دونوں اللہ تعالی کی نشانیوں میں سے دو نشانیاں ہیں، لہٰذا جب ان میں سے کوئی گہنا جائے (یا کہا: ان دونوں میں سے کوئی اس میں سے کچھ کرے، یعنی گہنا جائے) تو اللہ کے ذکر کی طرف دوڑ پڑو\"۔","الألباني: صحيح",{"u2":"حضرت عبداللہ بن عمرو رضی اللہ عنہما بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم کے زمانے میں سورج کو گرہن لگ گیا تو رسول اللہ صلی اللہ علیہ وسلم نے نماز پڑھی۔ قیام بہت لمبا کیا، پھر رکوع کیا تو لمبا رکوع کیا، پھر سر اٹھایا تو بہت دیر کھڑے رہے۔ اسی طرح سجدہ بھی خوب لمبا کیا۔ آپ صلی اللہ علیہ وسلم سجدے میں روتے تھے، آہیں بھرتے تھے اور فرماتے تھے: ’’اے میرے رب! تو نے مجھ سے اس (عذاب) کا وعد نہیں کیا تھا جبکہ میں تو تجھ سے بخشش طلب کررہا ہوں۔ تو نے مجھ سے اس (عذاب) کا وعدہ نہیں کیا تھا جبکہ میں ان میں موجود ہوں۔‘‘ جب آپ نماز سے فارغ ہوئے تو فرمایا: ’’مجھ پر جنت پیش کی گئی، حتی کہ اگر میں اپنا ہاتھ بڑھاتا تو میں اس کے کچھ خوشے لے لیتا، نیز مجھ پر آگ پیش کی گئی تو میں اس میں پھونکیں مارنے لگا کہ کہیں تمھیں اس کی تپش نہ آلے۔ اور میں نے اس میں اپنی دو اونٹنیوں کا چور بھی دیکھا، نیز میں نے اس میں بنودعدع کا وہ شخص دیکھا جو حاجیوں کی چیزیں چرایا کرتا تھا۔ اور اگر پتا چل جاتا تو وہ کہتا کہ یہ چھڑی کی کارستانی ہے۔ اور میں نے اس میں ایک لمبی کالی عورت دیکھی جسے ایک بلی کے بارے میں عذاب دیا جارہا تھا جسے اس نے باندھ دیا تھا۔ نہ تو اسے کھلایا پلایا اور نہ اسے چھوڑا کہ وہ خود زمین کے کیڑے مکوڑے کھالیتی حتی کہ وہ مرگئی۔ اور (یاد رکھو!) سورج اور چاند کسی کی موت و حیات کی وجہ سے نہیں گہناتے، بلکہ یہ اللہ تعالیٰ کی نشانیوں میں سے دو نشانیاں ہیں۔ جب ان میں کسی کو گرہن لگ جائے تو اللہ تعالیٰ کے ذکر کی طرف دوڑو۔‘‘","f2":"یہ حدیث تفصیل کے ساتھ پیچھے گزر چکی ہے۔ دیکھیے حدیث نمبر ۱۴۸۳، لہٰذا اسے اس کی روشنی میں سمجھا جائے، البتہ اس میں بنودعدع کے شخص جو جوتا چور کہا گیا تھا اور یہاں یہ بتایا گیا ہے کہ وہ حاجیوں کی چیزیں چرایا کرتا تھا۔ گویا وہ حاجیوں کے جوتے چھڑی میں پھنسا کر لے بھاگتا تھا۔ (مزید تفصیلات کے لیے حدیث نمبر ۱۴۸۳ کے فوائد دیکھیے۔)"}],[1497,"عبدالرحمٰن بن نمر سے روایت ہے کہ انہوں نے زہری سے گرہن کی نماز کے طریقے کے بارے میں پوچھا تو انہوں نے کہا: مجھے عروہ بن زبیر نے خبر دی ہے وہ ام المؤمنین عائشہ رضی اللہ عنہا سے روایت کرتے ہیں کہ سورج گرہن لگا تو رسول اللہ صلی اللہ علیہ وسلم نے ایک آدمی کو حکم دیا، تو اس نے اعلان کیا کہ نماز جماعت سے ہونے والی ہے، تو لوگ جمع ہو گئے، رسول اللہ صلی اللہ علیہ وسلم نے انہیں نماز پڑھائی، آپ نے اللہ اکبر کہا، پھر ایک لمبی قرآت کی، پھر اللہ اکبر کہا، پھر ایک لمبا رکوع کیا، اپنے قیام کی طرح یا اس سے بھی لمبا، پھر اپنا سر اٹھایا، اور «سمع اللہ لمن حمده» کہا، پھر ایک لمبی قرآت کی یہ پہلی قرآت سے کم تھی، پھر «اللہ اکبر»کہا، اور ایک لمبا رکوع کیا یہ پہلے رکوع سے کم تھا، پھر اپنا سر اٹھایا، اور «سمع اللہ لمن حمده» کہا، پھر آپ نے «اللہ اکبر» کہا، اور ایک لمبا سجدہ کیا اپنے رکوع کی طرح یا اس سے بھی لمبا، پھر آپ نے «اللہ اکبر» کہا، اور اپنا سر اٹھایا، پھر آپ نے «اللہ اکبر» کہا اور سجدہ کیا، پھر آپ نے «اللہ اکبر» کہا اور ایک لمبی قرآت کی، یہ پہلی قرآت سے کم تھی، پھر «اللہ اکبر» کہا، پھر ایک لمبا رکوع کیا یہ پہلے رکوع سے کم تھا، پھر اپنا سر اٹھایا، اور «سمع اللہ لمن حمده» کہا، پھر ایک لمبی قرآت کی لیکن یہ پہلی قرآت سے جو دوسری رکعت میں کی تھی کم تھی، پھر آپ نے «اللہ اکبر» کہا، اور ایک لمبا رکوع کیا، اور یہ پہلے رکوع سے کم تھا، پھر«اللہ اکبر» کہا اور اپنا سر اٹھایا، پھر «سمع اللہ لمن حمده» کہا، پھر «اللہ اکبر» کہا، اور سجدہ کیا، اور یہ پہلے سجدہ سے کم تھا، پھر آپ نے تشہد پڑھا، پھر سلام پھیرا، پھر ان کے بیچ میں کھڑے ہوئے، اور اللہ کی حمد و ثنا بیان کی، پھر فرمایا: \"سورج اور چاند نہ تو کسی کے مرنے سے گہناتے ہیں اور نہ ہی کسی کے پیدا ہونے سے، بلکہ یہ دونوں اللہ تعالی کی نشانیوں میں سے دو نشانیاں ہیں، تو ان میں سے کسی کو گہن لگ جائے تو نماز کو یاد کر کے اللہ تعالی کی طرف دوڑ پڑو\"۔","الألباني: صحيح",{"u2":"حضرت عائشہ رضی اللہ عنہا فرماتی ہیں کہ ایک دفعہ سورج کو گرہن لگ گیا تو رسول اللہ صلی اللہ علیہ وسلم نے ایک آدمی کو حکم دیا تو اس نے اعلان کیا کہ نماز کی جماعت ہونے والی ہے۔ لوگ اکٹھے ہوگئے تو رسول اللہ صلی اللہ علیہ وسلم نے انھیں نماز پڑھائی۔ آپ نے اللہ اکبر کہا، پھر لمبی قراءت کی، پھر اللہ اکبر کہا اور لمبا رکوع کیا، اپنے قیام جتنا یا اس سے بھی لمبا، پھر اپنا سر اٹھایا اور سمع اللہ لمن حمدہ کہا، پھر طویل قراءت کی جو پہلی قراءت سے کم تھی، پھر اللہ اکبر کہا اور لمبا سجدہ کیا، رکوع جتنا یا اس سے بھی لمبا، پھر اللہ اکبر کہہ کر سر اٹھایا اور پھر اللہ اکبر کہہ کر سجدہ کیا، پھر اللہ اکبر کہہ کر اٹھے اور لمبی قراءت کی جو پہلی قراءت سے کم تھی، پھر اللہ اکبر کہا اور لمبا رکوع کیا جو پہلے رکوع سے کم تھا، پھر سرا ٹھایا اور سمع اللہ لمن حمدہ کہا اور پھر لمبی قراءت کی جو دوسرے قیام کی پہلی قراءت سے کم تھی، پھر اللہ اکبر کہا اور لمبا لیکن پہلے رکوع سے کم لمبا رکوع کیا، پھر اٹھایا اور سمع اللہ لمن حمدہ کہا، پھر اللہ اکبر کہہ کر پہلے سجدوں سے کم لمبے سجدے کیے۔ پھر تشہد پڑھا، پھر سلام پھیرا۔ پھر آپ (تقریر کے لیے) کھڑے ہوئے۔ اللہ تعالیٰ کی حمدوثنا کی، پھر فرمایا: ’’سورج اور چاند کسی کی موت و حیات کی بنا پر بے نور نہیں ہوتے بلکہ یہ تو اللہ تعالیٰ کی نشانیوں میں سے دو نشانیاں ہیں۔ ان میں سے جسے گرہن لگ جائے تو گھبرا کر (فوراً) نماز کی صورت میں اللہ کا ذکر شروع کردو۔‘‘"}],[1498,"اسماء بنت ابی بکر رضی اللہ عنہم کہتی ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے گرہن کی نماز پڑھی، تو آپ نے قیام کیا تو لمبا قیام کیا، پھر رکوع کیا تو لمبا رکوع کیا، پھر (اپنا سر رکوع سے) اٹھایا تو لمبا قیام کیا، پھر رکوع کیا تو لمبا رکوع کیا، پھر اپنا سر رکوع سے اٹھایا، پھر سجدہ کیا تو لمبا سجدہ کیا، پھر (اپنا سر سجدہ سے) اٹھایا، پھر سجدہ کیا تو لمبا سجدہ کیا، پھر آپ نے قیام کیا تو لمبا قیام کیا، پھر آپ نے رکوع کیا تو لمبا رکوع کیا، پھر اپنا سر اٹھایا تو لمبا قیام کیا، پھر رکوع کیا تو لمبا رکوع کیا، پھر اپنا سر اٹھایا، پھر سجدہ کیا تو لمبا سجدہ کیا، پھر اپنا سر اٹھایا، پھر سجدہ کیا تو لمبا سجدہ کیا، پھر اپنا سر اٹھایا، اور نماز سے فارغ ہو گئے۔","الألباني: صحيح",{"u2":"حضرت اسماء بنت ابی بکر رضی اللہ عنہما فرماتی ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے سورج گرہن میں نماز پڑھی۔ قیام کیا اور بہت لمبا قیام کیا، پھر رکوع کیا اور بہت لمبا رکوع کیا، پھر سراٹھایا اور لمبا قیام کیا، پھر رکوع کیا اور لمبا رکوع کیا، پھر سر اٹھایا، پھر سجدہ کیا اور لمبا سجدہ کیا، پھر سر اٹھایا، پھر سجدہ کیا اور لمبا سجدہ کیا، پھر کھڑے ہوئے اور لمبا قیام کیا، پھر رکوع کیا اور لمبا رکوع کیا، پھر سر اٹھایا اور لمبا قیام کیا، پھر رکوع کیا اور لمبا رکوع کیا، پھر سر اٹھایا، پھر سجدہ کیا اور لمبا سجدہ کیا، پھر سر اٹھایا، پھر سجدہ کیا اور لمبا سجدہ کیا، پھر سر اٹھایا (اور تشہدودرود وغیرہ پڑھا۔) پھر سلام پھیرا۔"}],[1499,"ام المؤمنین عائشہ رضی اللہ عنہا کہتی ہیں کہ نبی اکرم صلی اللہ علیہ وسلم کہیں جانے کے لیے نکلے کہ سورج کو گرہن لگ گیا، تو ہم حجرے کی طرف چلے، اور کچھ اور عورتیں بھی ہمارے پاس جمع ہو گئیں، رسول اللہ صلی اللہ علیہ وسلم ہمارے پاس تشریف لائے، اور یہ چاشت کا وقت تھا، (آپ نماز پڑھنے کے لیے) کھڑے ہوئے، تو آپ نے ایک لمبا قیام کیا، پھر ایک لمبا رکوع کیا، پھر اپنا سر اٹھایا، پھر قیام کیا پہلے قیام سے کم، پھر رکوع کیا پہلے رکوع سے کم، پھر سجدہ کیا، پھر دوسری رکعت کے لیے کھڑے ہوئے تو بھی ایسے ہی کیا، مگر آپ کا یہ قیام اور رکوع پہلی والی رکعت کے قیام اور رکوع سے کم تھا، پھر آپ نے سجدہ کیا، اور سورج صاف ہو گیا، جب آپ نماز سے فارغ ہو گئے تو منبر پر بیٹھے، اور منبر پر جو باتیں آپ نے کہیں ان میں ایک بات یہ بھی تھی کہ \"لوگوں کو ان کی قبروں میں دجال کی آزمائش کی طرح آزمایا جائے گا\"، یہ حدیث مختصر ہے۔","الألباني: صحيح",{"u2":"حضرت عائشہ رضی اللہ عنہا فرماتی ہیں کہ نبی صلی اللہ علیہ وسلم کسی کام سے نکلے تھے کہ سورج بے نور ہوگیا۔ ہم حجرے کی طرف چلے آئے۔ دوسری عورتیں بھی ہمارے پاس اکٹھی ہوگئیں۔ اتنے میں رسول اللہ صلی اللہ علیہ وسلم بھی ہماری طرف تشریف لے آئے۔ یہ چاشت کا وقت تھا۔ آپ نے لمبا قیام فرمایا، پھر لمبا رکوع فرمایا، پھر سر اٹھا کر پہلے قیام سے کم لمبا قیام کیا، پھر پہلے رکوع سے کم لمبا رکوع کیا، پھر سجدے کیے، پھر دوسری رکعت کے لیے کھڑے ہوئے اور اسی طرح کیا، مگر آپ کے قیام و رکوع پہلی رکعت سے کم لمبے تھے، پھر آپ نے سجدے کیے۔ ادھر سورج بھی روشن ہوگیا۔ جب سلام پھیرا تو منبر پر تشریف فرما ہوئے (اور بہت سی باتیں ارشاد فرمائیں۔) ان میں یہ بھی فرمایا: ’’بلاشبہ لوگ قبروں میں فتنۂ دجال کی طرح آزمائے جائیں گے۔‘‘ یہ روایت مختصر ہے۔","f2":"قبروں میں آزمائش سے مراد فرشتوں کا سوال و جواب ہے جو ایک بہت مشکل مرحلہ ہے اور اسی پر نجات کا دارومدار ہے۔ حشر کے بعد تو اسی کی تفصیل ہوگی۔ اللہ تعالیٰ ہمیں کامیاب فرمائے۔ آمین۔"}],[1500,"ام المؤمنین عائشہ رضی اللہ عنہا کہتی ہیں کہ رسول اللہ صلی اللہ علیہ وسلم کے زمانے میں سورج کو گرہن لگا، تو آپ کھڑے ہوئے اور نماز پڑھائی تو بہت لمبا قیام کیا، پھر رکوع کیا تو بہت لمبا رکوع کیا، پھر (رکوع سے سر) اٹھایا، پھر قیام کیا تو بہت لمبا قیام کیا، اور یہ پہلے قیام سے کم تھا، پھر رکوع کیا تو لمبا رکوع کیا، اور یہ پہلے رکوع سے کم تھا، پھر آپ نے سجدہ کیا، پھر سجدے سے اپنا سر اٹھایا تو لمبا قیام کیا، اور یہ پہلے سے کم تھا، پھر آپ نے رکوع کیا تو لمبا رکوع کیا، اور یہ پہلے رکوع سے کم تھا، پھر آپ نے(رکوع سے سر) اٹھایا تو لمبا قیام کیا، اور یہ پہلے قیام سے کم تھا، پھر آپ نے رکوع کیا تو لمبا رکوع کیا، اور یہ پہلے رکوع سے کم تھا، پھر آپ نے سجدہ کیا یہاں تک کہ جب آپ نماز سے فارغ ہوئے، تو سورج سے گرہن چھٹ چکا تھا، پھر آپ نے لوگوں کو خطبہ دیا، تو اللہ کی حمد اور اس کی ثنا بیان کی، پھر فرمایا: \"سورج اور چاند کو نہ تو کسی کے مرنے کی وجہ سے گرہن لگتا ہے، اور نہ ہی کسی کے پیدا ہونے سے، لہٰذا جب تم اسے دیکھو تو نماز پڑھو، اور صدقہ خیرات کرو، اور اللہ عزوجل کو یاد کرو\"، نیز فرمایا: \"اے امت محمد! کوئی اللہ تعالی سے زیادہ اس بات پر غیرت والا نہیں کہ اس کا غلام یا اس کی باندی زنا کرے، اے امت محمد! اگر تم لوگ وہ چیز جانتے جو میں جانتا ہوں تو تم ہنستے کم اور روتے زیادہ\"۔","الألباني: صحيح",{"u2":"حضرت عائشہ رضی اللہ عنہا فرماتی ہیں کہ رسول اللہ صلی اللہ علیہ وسلم کے زمانے میں سورج کو گرہن لگ گیا۔ آپ کھڑے ہوئے اور نماز شروع کردی تو بہت ہی لمبا قیام فرمایا، پھر رکوع فرمایا تو بہت ہی لمبا رکوع فرمایا، پھر سر اٹھایا تو بہت لمبا قیام فرمایا مگر یہ پہلے قیام سے کم لمبا تھا، پھر دوسرا رکوع فرمایا اور لمبا رکوع فرمایا مگر یہ پہلے رکوع سے کم لمبا تھا، پھر سجدہ فرمایا (دودفعہ)، پھر سر اٹھایا اور لمبا قیام کیا جو پہلے قیام سے کم لمبا تھا اور پھر رکوع فرمایا اور لمبا رکوع فرمایا جو پہلے رکوع سے کم لمبا تھا، پھر سر اٹھایا او رلمبا قیام فرمایا جو پہلے قیام سے کم لمبا تھا، پھر رکوع فرمایا اور لمبا رکوع فرمایا جو پہلے رکوع سے کم لمبا تھا، پھر سجدے فرمائے اور نماز سے فارغ ہوئے تو گرہن ختم ہوچکا تھا، پھر آپ نے لوگوں سے خطاب فرمایا۔ اللہ تعالیٰ کی حمدوثنا بیان فرمائی، پھر فرمایا: ’’سورج اور چاند اللہ تعالیٰ کی عظمت کی دو نشانیاں ہیں۔ یہ کسی کی موت و حیات کی بنا پر بے نور نہیں ہوتے، لہٰذا جب تم یہ حالت دیکھو تو نماز پڑھو، صدقات کرو اور اللہ تعالیٰ کو یاد کرو۔‘‘ اور فرمایا: ’’اے امت محمد! کسی کو اللہ تعالیٰ سے بڑھ کر غیرت نہیں آتی اس بات پر کہ اس کا غلام یا لونڈی زنا کرے۔ اے امت محمد! اگر تم وہ باتیں جان لو جو میں جانتا ہوں تو تم کم ہنسو اور زیادہ روو۔‘‘"}],[1501,"سمرہ رضی اللہ عنہ سے روایت ہے کہ نبی اکرم صلی اللہ علیہ وسلم نے جس وقت سورج گرہن لگا خطبہ دیا تو آپ نے (حمد و ثنا کے بعد) «أما بعد» کہا۔","الألباني: ضعيف",{"u2":"حضرت سمرہ رضی اللہ عنہ سے روایت ہے کہ جب سورج کو گرہن لگا تھا تو نبی صلی اللہ علیہ وسلم نے خطبہ دیا تھا اور فرمایا تھا: اما بعد","f2":"خطبے میں حمدوصلاۃ کے بعد کہا جاتا ہے: اما بعد! یعنی حمدوصلاۃ کے بعد میرا مقصود یہ ہے۔ اور اس کے بعد مقصد بیان کیا جاتا ہے۔ یہ حدیث گزرچکی ہے۔ دیکھیے، حدیث:۱۴۸۵"}],[1502,"ابوبکرہ رضی اللہ عنہ کہتے ہیں کہ ہم نبی اکرم صلی اللہ علیہ وسلم کے پاس تھے کہ سورج گرہن لگ گیا، تو آپ جلدی سے اپنی چادر گھسیٹتے ہوئے مسجد کی طرف بڑھے، تو لوگ بھی آپ کے ساتھ ہو لیے، آپ نے دو رکعت نماز پڑھی، اسی طرح جیسے لوگ پڑھتے ہیں، پھر جب سورج صاف ہو گیا تو آپ نے ہمیں خطبہ دیا، آپ صلی اللہ علیہ وسلم نے فرمایا: \"سورج اور چاند اللہ تعالی کی نشانیوں میں سے دو نشانیاں ہیں جن کے ذریعہ وہ اپنے بندوں کو ڈراتا ہے، اور ان دونوں کو کسی کے مرنے سے گرہن نہیں لگتا، تو جب تم ان دونوں میں سے کسی کو گرہن لگا دیکھو تو نماز پڑھو، اور دعا کرو یہاں تک کہ جو تمہیں لاحق ہوا ہے چھٹ جائے\"۔","الألباني: صحيح",{"u2":"حضرت ابوبکرہ رضی اللہ عنہ بیان کرتے ہیں کہ ہم نبی صلی اللہ علیہ وسلم کے ساتھ تھے کہ سورج کو گرہن لگ گیا۔ آپ جلدی سے اپنی بالائی چادر گھسیٹتے ہوئے مسجد کی طرف چلے۔ لوگ بھی آپ کے پاس آگئے۔ آپ نے دورکعت نماز پڑھائی جیسے وہ (اہل مدینہ نمازکسوف) پڑھتے تھے۔ جب سورج روشن ہوگیا تو آپ نے ہمیں خطبہ دیا اور فرمایا: ’’بلاشبہ سورج اور چاند اللہ تعالیٰ کی نشانیوں میں سے دو نشانیاں ہیں۔ اللہ تعالیٰ ان کے ذریعے سے اپنے بندوں کو ڈراتا ہے اور انھیں کسی کی موت کی بنا پر گرہن نہیں لگتا۔ جب تم ان میں سے کسی کو گرہن لگتا دیکھو تو نماز پڑھو اور دعائیں کرو حتی کہ گرہن ختم ہوجائے۔‘‘","f2":"دعا نمازکسوف کے اندر بھی ہوسکتی ہے، آگے پیچھے بھی، انفرادی بھی اور اجتماعی بھی۔"}],[1503,"ابوموسی اشعری رضی اللہ عنہ کہتے ہیں کہ سورج گرہن لگا تو رسول اللہ صلی اللہ علیہ وسلم گھبرا کر کھڑے ہوئے، آپ ڈر رہے تھے کہ کہیں قیامت تو نہیں آ گئی ہے، چنانچہ آپ اٹھے یہاں تک کہ مسجد آئے، پھر نماز پڑھنے کھڑے ہوئے تو آپ نے اتنے لمبے لمبے قیام، رکوع اور سجدے کیے کہ اتنے لمبے میں نے آپ کو کسی نماز میں کرتے نہیں دیکھا، پھر آپ صلی اللہ علیہ وسلم نے فرمایا: \"یہ وہ نشانیاں ہیں جنہیں اللہ تعالی بھیجتا ہے، یہ نہ کسی کے مرنے سے ہوتے ہیں نہ کسی کے پیدا ہونے سے، بلکہ اللہ تعالی انہیں اپنے بندوں کو ڈرانے کے لیے بھیجتا ہے، تو جب تم ان میں سے کچھ دیکھو تو اللہ کو یاد کرنے اور اس سے دعا اور استغفار کرنے کے لیے دوڑ پڑو\"۔","الألباني: صحيح",{"u2":"حضرت ابوموسیٰ رضی اللہ عنہ بیان کرتے ہیں کہ ایک دفعہ سورج گہنا گیا تو نبی صلی اللہ علیہ وسلم گھبرا کر اٹھے۔ آپ کو خطرہ ہوا کہ قیامت نہ آجائے۔ آپ اٹھے حتی کہ مسجد میں آئے اور کھڑے ہوکر اتنے لمبے قیام، رکوع اور سجدے کے ساتھ نماز پڑھی کہ میں نے کبھی آپ کو کسی نماز میں اتنے لمبے قیام، رکوع اور سجدے کرتے نہیں دیکھا، پھر آپ نے فرمایا: ’’تحقیق یہ نشانیاں جو اللہ تعالیٰ ظاہر فرماتا ہے، کسی کی موت و حیات کی بنا پر نہیں بلکہ اللہ تعالیٰ انھیں، اس لیے ظاہر فرماتا ہے کہ اپنے بندوں کے دلوں میں ان کی بنا پر اپنا خوف پیدا فرمائے۔ جب تم کوئی ایسی چیز دیکھو تو فوراً اللہ کا ذکرکرو، دعائیں کرو اور اس سے اپنے گناہوں کی بخشش طلب کرو۔‘‘","f2":"(۱)راویٔ حدیث نے نبی صلی اللہ علیہ وسلم کی گھبراہٹ اور جلدی سے اندازہ لگایا کہ شاید آپ کو قیامت کا خطرہ محسوس ہوا ہے، یہ نہیں کہ آپ کو واقعی قیامت کا خطرہ پیدا ہوگیا تھا کیونکہ قیامت کی بہت سی نشانیاں آپ نے بیان فرمائی ہیں جن میں سے سوائے آپ کی بعثت کے اور کوئی نشانی بھی پوری نہ ہوئی تھی۔ یہ بھی کہا گیا ہے کہ ممکن ہے گھبراہٹ کی بنا پر آپ کا ذہن ان نشانیوں کی طرف متوجہ نہ ہوسکا یا اس وقت تک ابھی آپ کو دوسری نشانیاں بتلائی ہی نہ گئی تھیں، حالانکہ یہ واقعہ آپ کی وفات سے صرف چار، ساڑھے چار ماہ قبل ہوا ہے۔ آخری دونوں وجوہ کمزور ہیں۔ (۲)چاند گرہن کا کوئی واقعہ احادیث میں منقول نہیں مگر تمام احادیث میں سورج اور چاند کو اکٹھا ہی ذکر کیا گیا ہے اور احکام بھی مشترکہ ہی دیے گئے ہیں، لہٰذا چاند گرہن کے موقع پر بھی نمازکسوف اسی طرح پڑھی جائے گی اور دیگر احکام بھی لاگو ہوں گے۔ احناف نے بعض مصالح کی بنا پر چاند گرہن میں جماعت کو مناسب نہیں سمجھا مگر روایات صراحتاً ان کے خلاف ہیں۔ (۲)نماز کسوف کے بارے میں پینتالیس (۴۵) روایات ذکر کی گئی ہیں جن کا تعلق ایک یہ واقعے سے ہے۔ کچھ مفصل ہیں کچھ مجمل، پھر بعض میں وہم اور غلط فہمی بھی ہے، لہٰذا تمام روایات کو ملا کر مجموعی طور پر جو واقعے کی کیفیت سمجھ میں آتی ہے، وہ معتبر ہوگی، نیز اکا دکا روایات میں اگر کوئی بات کثیر روایات کے خلاف آگئی ہے تو اس کا اعتبار نہیں کیا جائے گا، بلکہ اسے وہم قرار دیا جائے گا، خواہ راوی ثقہ ہی ہوں کیونکہ کسی واقعے کی تحقیق کا یہی طریقہ ہے۔ واللہ اعلم۔"}],[1504,"انس بن مالک رضی اللہ عنہ کہتے ہیں کہ ایک آدمی رسول اللہ صلی اللہ علیہ وسلم کے پاس آیا، اور اس نے عرض کیا: اللہ کے رسول! چوپائے ہلاک ہو گئے، (اور پانی نہ ہونے سے) راستے (سفر) ٹھپ ہو گئے، آپ اللہ تعالی سے دعا کیجئیے۔ تو رسول اللہ صلی اللہ علیہ وسلم نے دعا کی، تو جمعہ سے لے کر دوسرے جمعہ تک ہم پر بارش ہوتی رہی، تو پھر ایک آدمی رسول اللہ صلی اللہ علیہ وسلم کے پاس آیا، اور اس نے عرض کیا: اللہ کے رسول! گھر منہدم ہو گئے، راستے (سیلاب کی وجہ سے) کٹ گئے، اور جانور مر گئے، تو آپ نے دعا کی: «اللہم على رءوس الجبال والآكام وبطون الأودية ومنابت الشجر» \"اے اللہ! پہاڑوں کی چوٹیوں، ٹیلوں، نالوں اور درختوں پر برسا\" تو اسی وقت بادل مدینہ سے اس طرح چھٹ گئے جیسے کپڑا (اپنے پہننے والے سے اتار دینے پر الگ ہو جاتا ہے)۔","الألباني: حسن صحيح",{"u2":"حضرت انس بن مالک رضی اللہ عنہ بیان کرتے ہیں کہ ایک آدمی رسول اللہ صلی اللہ علیہ وسلم کے پاس آیا اور کہنے لگا: اے اللہ کے رسول! جانور (قحط سالی کی بنا پر) ہلاک ہو گئے اور راستے منقطع ہوگئے، اللہ تعالیٰ سے (بارش کی) دعا کیجیے۔ رسول اللہ صلی اللہ علیہ وسلم نے دعا فرمائی تو اس جمعے سے اگلے جمعے تک (مسلسل) بارش ہوتی رہی۔ تو (وہی) آدمی رسول اللہ کے پاس آیا اور کہنے لگا: اے اللہ کے رسول! (زیادہ بارش کی وجہ سے) گھر گرگئے اور راستے منقطع ہوگئے اور جانور مرنے لگے ہیں۔ تو آپ نے دعا فرمائی: ’’اے اللہ! پہاڑوں کی چوٹیوں پر، ٹیلوں پر، وادیوں کے نشیب (نالوں) اور جنگلات میں بارش برسا۔‘‘ تو بادل مدینہ منورہ سے اس طرح چھٹ گئے جس طرح درمیان سے کپڑا پھٹ جاتا ہے۔","f2":"(۱)قحط سالی کی بنا پر جانوروں کو چارہ نہ ملنے سے ان کی ہلاکت واضح ہے۔ راستے منقطع ہونے کی وجہ یا تو گھاس وغیرہ کا ختم ہونا ہے کہ جب گھاس نہ ہوگی تو جانوروں کا گزارا کیسے ہوگا؟ اور سفر جانوروں کے بغیر ممکن نہیں تھا۔ یا جب کچھ ہے ہی نہیں تو سفر کس لیے کرنا ہے؟ تجارتی منڈیاں بھی تبھی چلیں گی جب کوئی فصل ہو، قحط سالی کی وجہ سے فصلیں نہ رہیں تو تجارت بھی ختم۔ (۲)بارش کے بعد بھی جانوروں کی ہلاکت یا تو سردی زیادہ ہونے کی وجہ سے تھی یا اس لیے کہ بارش ختم ہو تو کچھ اگے۔ ہلاکت سے مراد انتہائی کمزوری بھی ہوسکتی ہے، یعنی ہلاکت کے قریب ہوگئے۔ راستے منقطع ہونا تو واضح ہے کہ پانی کی کثرت کی بنا پر چلنا ممکن نہیں رہا، نیز سابقہ وجوہات بھی قائم ہیں۔ بارش رکے تو وہ وجوہات ختم ہوں۔ (۳)’’جس طرح کپڑا پھٹ جاتا ہے‘‘ یعنی مدینہ منورہ کے اوپر سے بادل ہٹ گئے اور اردگرد بادل ہی بادل تھے تو دیکھنے سے ایسے لگتا تھا جیسے درمیان سے کپڑا پھٹ گیا ہے اور جگہ خالی ہوگئی ہے۔ بادل کو کپڑے سے تشبیہ دی گئی ہے۔ (۴)دونوں دعاؤں کی فوری قبولیت علامات نبوت سے ہے۔۔۔ صلی اللہ علیہ وسلم۔ (۵)باب کا مقصد یہ ہے کہ بارش کی دعا اس وقت کی جائے جب بارش نہ ہونے سے نقصان ہو، ورنہ ہر وقت تو بارش نہیں ہوتی اور نہ ہر وقت دعا ہی کی جاتی ہے۔ (۶)قحط سالی کے موقع پر لوگ امام سے بارش کی دعا کے لیے درخواست کرسکتے ہیں۔ (۷)ایک آدمی پوری جماعت کی طرف سے نمائندگی کرسکتا ہے۔ (۸)نیک بزرگوں سے دعا کروانی چاہیے۔ (۹)دعا میں تمام لوگوں کے احوال کو مدنظر رکھنا چاہیے۔ نبی اکرم صلی اللہ علیہ وسلم نے مطلق بارش رکنے کی دعا نہیں کی بلکہ صرف مدینے میں بارش رکنے کی دعا کی۔ اس غرض سے کہ ممکن ہے دوسرے علاقوں میں ابھی بارش کی ضرورت ہو۔ (۱۰)کسی مصیبت اور آزمائش کے خاتمے کی دعا کرنا توکل کے منافی نہیں ہے۔ (۱۱)اس حدیث سے نمازاستسقاء کی نفی نہیں ہوتی بلکہ وہ صحیح احادیث سے ثابت ہے، لہٰذا اس حدیث میں امام ابوحنیفہ رحمہ اللہ کے لیے اس بات کی کوئی دلیل نہیں کہ نماز استسقاء غیرمشروع ہے۔"}],[1505,"عبداللہ بن زید رضی اللہ عنہ (جنہیں خواب میں اذان دکھائی گئی تھی) کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم استسقاء کی نماز پڑھنے کے لیے عید گاہ کی طرف نکلے۔ تو آپ نے قبلہ کی طرف رخ کیا، اور اپنی چادر پلٹی، اور دو رکعت نماز پڑھی۔ ابوعبدالرحمٰن (نسائی) کہتے ہیں: یہ ابن عیینہ کی غلطی ہے ۱؎ عبداللہ بن زید جنہیں خواب میں اذان دکھائی گئی تھی وہ عبداللہ بن زید بن عبد ربہ ہیں، اور یہ جو استسقا کی حدیث روایت کر رہے ہیں عبداللہ بن زید بن عاصم مازنی ہیں۔\n§وضاحت\n۱؎: یعنی سفیان بن عیینہ کا اس حدیث کے راوی کے بارے میں یہ کہنا کہ \" انہیں کو خواب میں اذان دکھائی گئی \" ان کا وہم ہے، اذان \" عبداللہ بن زیدبن عبدربہ \" کو دکھائی گئی، اور اس حدیث کے راوی کا نام \" عبداللہ بن زید بن عاصم \" ہے۔","الألباني: صحيح",{"u2":"حضرت عبداللہ بن زید رضی اللہ عنہ۔۔۔ جنھیں خواب میں اذان سکھلائی گئی تھی۔۔۔ بیان کرتے ہیں رسول اللہ صلی اللہ علیہ وسلم بارش کی دعا کرنے کے لیے عیدگاہ کی طرف نکلے۔ آپ قبلے کی طرف متوجہ ہوئے اور اپنی چادر الٹائی اور دو رکعتیں پڑھیں۔\nامام ابوعبدالرحمن (نسائی) رحمہ اللہ بیان کرتے ہیں کہ یہ ابن عیینہ کی غلطی ہے کیونکہ جس عبداللہ بن زید کو خواب میں اذان دکھلائی گئی تھی وہ عبداللہ بن زید بن عبدربہ ہیں جب کہ مذکورہ حدیث بیان کرنے والے عبداللہ بن زید بن عاصم مازنی ہیں۔","f2":"(۱)عبداللہ بن زید نامی دو صحابی ہیں۔ ایک عبداللہ بن زید بن عاصم مازنی اور دوسرے عبداللہ بن زید بن عبدربہ۔ صرف عبداللہ بن زید کہا جائے تو شبہ ہوسکتا ہے کہ کون سے مراد ہیں؟ جیسا کہ حضرت سفیان بن عیینہ کو غلطی لگی، اس لیے امام صاحب نے وضاحت فرمائی کہ راویٔ حدیث اذان والے عبداللہ بن زید بن عبدربہ نہیں بلکہ یہ عبداللہ بن زید بن عاصم مازنی ہیں۔ (۲)بارش کی دعا، یعنی صلاۃ استسقاء کے لیے بستی سے باہر نکلنا سنت ہے، تاہم بامر مجبوری مسجد میں بھی ادا کی جاسکتی ہے۔ واللہ اعلم۔ (۳)’’چادرالٹانا‘‘ یہ عمل بھی مسنون ہے۔ دراصل فعلی دعا ہے کہ یااللہ! جس طرح ہم نے اپنی چادروں کو پلٹ لیا ہے، تو بھی موجودہ صورت کو اسی طرح بدل دے۔ بارش برسا کر قحط سالی ختم کردے اور تنگی کو خوش حالی میں بدل دے۔ چادر کا دایاں کنارہ بائیں جانب اور بایاں کنارہ دائیں جانب ڈال لیا جائے، نیز نچلا کنارہ اوپر اور اوپر والا کنارہ نیچے کرلیا جائے۔"}],[1506,"اسحاق بن عبداللہ بن کنانہ کہتے ہیں کہ فلاں نے مجھے ابن عباس رضی اللہ عنہم کے پاس بھیجا کہ میں ان سے رسول اللہ صلی اللہ علیہ وسلم کی نماز استسقاء کے بارے میں پوچھوں۔ تو انہوں نے کہا: رسول اللہ صلی اللہ علیہ وسلم (استسقاء کی نماز کے لیے) عاجزی اور انکساری کا اظہار کرتے ہوئے پھٹے پرانے کپڑے میں نکلے، تو آپ نے تمہارے اس خطبہ کی طرح خطبہ نہیں دیا ۱؎ آپ نے دو رکعت نماز پڑھی۔\n§وضاحت\n۱؎: بلکہ آپ کا خطبہ دعا و استغفار اور اللہ سے عاجزی اور گڑگڑانے پر مشتمل تھا۔","الألباني: حسن",{"u2":"حضرت اسحاق بن عبداللہ بن کنانہ رحمہ اللہ سے روایت ہے کہ مجھے فلاں شخص نے حضرت ابن عباس رضی اللہ عنہما کے پاس بھیجا کہ مین ان سے رسول اللہ صلی اللہ علیہ وسلم کی نماز استسقاء کے بارے میں پوچھوں تو انھوں نے فرمایا: رسول اللہ صلی اللہ علیہ وسلم گڑگڑاتے ہوئے، عاجزی کے ساتھ سادہ کپڑوں میں (آرائش اور زینت کے بغیر) نکلے۔ آپ نے تمھارے اس خطبے کی طرح خطبہ نہیں دیا، پھر دو رکعات پڑھیں۔","f2":"(۱)اللہ تعالیٰ سے دعا کے وقت عاجزی، خشوع خضوع اور سادگی بڑی مؤثر چیز ہے۔ (۲)’’تمھارے اس خطبے کی طرح‘‘ یعنی آپ نے خطبہ تو دیا تھا مگر وہ تمھارے خطبوں کی طرح نہیں تھا بلکہ اس میں دعائے استغفار اور عاجزی کا اظہار تھا، کوئی تقریر نہ تھی۔ (۳)جمہورعلماء کے نزدیک امام نماز پڑھا کر خطبہ دے، تاہم قبل از نماز بھی جائز ہے۔ واللہ اعلم۔"}],[1507,"عبداللہ بن زید رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے استسقاء کی نماز پڑھی، اور آپ کے جسم مبارک پر ایک سیاہ چادر تھی۔","الألباني: صحيح",{"u2":"حضرت عبداللہ بن زید رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے نمازاستسقاء پڑھائی تو آپ پر سیاہ اونی چادر تھی۔","f2":"سیاہ اونی چادر بھی سادگی کے ذیل میں آتی ہے۔ یہ قیمت میں بھی معمولی ہوتی ہے۔"}],[1508,"اسحاق بن عبداللہ بن کنانہ کہتے ہیں کہ میں نے ابن عباس رضی اللہ عنہم سے رسول اللہ صلی اللہ علیہ وسلم کے استسقاء کی نماز کے متعلق پوچھا، تو انہوں نے کہا: رسول اللہ صلی اللہ علیہ وسلم پھٹے پرانے کپڑوں میں عاجزی اور گریہ وزاری کا اظہار کرتے ہوئے نکلے، اور منبر پر بیٹھے، تو آپ نے تمہارے اس خطبہ کی طرح خطبہ نہیں دیا، بلکہ آپ برابر دعا اور عاجزی کرتے رہے، اور اللہ کی بڑائی بیان کرنے میں لگے رہے، اور آپ نے دو رکعت نماز پڑھی جیسے آپ عیدین میں پڑھتے تھے۔","الألباني: حسن",{"u2":"حضرت اسحاق بن عبداللہ بن کنانہ رحمہ اللہ بیان کرتے ہیں کہ میں نے حضرت ابن عباس رضی اللہ عنہما سے رسول اللہ صلی اللہ علیہ وسلم کی نمازاستسقاء کے بارے میں پوچھا تو انھوں نے فرمایا: رسول اللہ صلی اللہ علیہ وسلم سادہ کپڑوں میں، عاجزی کے ساتھ، گڑگڑاتے ہوئے نکلے، پھر آپ منبر پر بیٹھے لیکن تمھارے خطبے کی طرح خطبہ نہیں دیا بلکہ آپ دعا کرتے رہے، گڑگڑاتے رہے اور اللہ تعالیٰ کی بزرگی بیان کرتے رہے، پھر آپ نے عیدین کی نماز کی طرح دو رکعات پڑھیں۔","f2":"عیدین کی نماز کے ساتھ مشابہت رکعات کی تعداد، وقت، یعنی اس کا وقت بھی سورج نکلنے کے بعد کا ہے، نیز جگہ، یعنی یہ نماز بھی باہر کھلے میدان میں ادا کی جاتی ہے اور جماعت میں ہے، مکمل طور پر مشابہت نہیں کیونکہ اس میں عیدین کی نماز کی طرح زائد تکبیرات نہیں ہیں۔ واللہ اعلم۔"}],[1509,"عباد بن تمیم کے چچا عبداللہ بن زید رضی اللہ عنہ کہتے ہیں کہ وہ رسول اللہ صلی اللہ علیہ وسلم کے ساتھ استسقاء کی نماز کے لیے نکلے تو آپ نے اپنی چادر پلٹی، اور لوگوں کی جانب اپنی پیٹھ پھیری، اور دعا کی، پھر آپ نے دو رکعت نماز پڑھی، اور قرآت کی تو بلند آواز سے قرآت کی۔","الألباني: صحيح",{"u2":"حضرت عباد بن تمیم کے چچا (حضرت عبداللہ بن زید بن عاصم رضی اللہ عنہ) بیان کرتے ہیں کہ میں بھی دعائے استسقاء کے لیے رسول اللہ صلی اللہ علیہ وسلم کے ساتھ گیا تھا۔ آپ نے اپنی چادر الٹائی اور لوگوں کی طرف پشت کرلی اور دعا کرنے لگے، پھر دو رکعتیں پڑھائیں اور ان میں بلند آواز سے قراءت کی۔","f2":"دعائے استسقاء میں امام کو بھی قبلہ رخ ہونا چاہیے۔ باقی لوگ تو عام دعا میں بھی قبلہ رخ ہوتے ہیں تاکہ ایک دوسرے کی طرف منہ نہ ہو۔ اس طرح خشوع خضوع اعلیٰ درجے کا ہوگا۔ ایک دوسرے کی طرف دیکھنے سے خشوع خضوع میں فرق آسکتا ہے۔"}],[1510,"عباد بن تمیم کے چچا عبداللہ بن زید رضی اللہ عنہ روایت کرتے ہیں کہ نبی اکرم صلی اللہ علیہ وسلم استسقاء کے لیے نکلے، تو آپ نے دو رکعت نماز پڑھی، اور اپنی چادر پلٹی۔","الألباني: صحيح",{"u2":"حضرت عباد بن تمیم کے چچا سے روایت ہے کہ نبی صلی اللہ علیہ وسلم نے بارش کی دعا فرمائی اور دو رکعتیں پڑھیں اور اپنی چادر الٹائی۔"}],[1511,"عبداللہ بن زید رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم (جائے نماز کی طرف) نکلے، تو آپ نے استسقاء کی نماز پڑھی، اور جس وقت آپ قبلہ رخ ہوئے اپنی چادر پلٹی۔","الألباني: صحيح",{"u2":"حضرت عبداللہ بن زید رضی اللہ عنہ بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم (مدینہ منورہ سے) باہر نکلے اور بارش کی دعا کی اور جب (دعا کے لیے) قبلہ رخ ہوئے تو آپ نے اپنی چادر الٹائی۔"}],[1512,"عباد بن تمیم کے چچا عبداللہ بن زید رضی اللہ عنہ کہتے ہیں کہ انہوں نے رسول اللہ صلی اللہ علیہ وسلم کو استسقاء میں دیکھا کہ آپ قبلہ رخ ہوئے، آپ نے اپنی چادر پلٹی، اور (دعا مانگنے کے لیے) اپنے دونوں ہاتھ اٹھائے۔","الألباني: صحيح",{"u2":"حضرت عباد بن تمیم کے چچا سے روایت ہے، انھوں نے رسول اللہ صلی اللہ علیہ وسلم کو دعائے استسقاء میں دیکھا۔ آپ نے قبلے کی طرف منہ فرمایا، چادر کو الٹایا اور (دعا کے لیے) اپنے ہاتھ اٹھائے۔"}],[1513,"انس رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم سوائے استسقاء کے اپنے دونوں ہاتھ کسی دعا میں نہیں اٹھاتے تھے، آپ اس میں اپنے دونوں ہاتھ اتنا بلند کرتے کہ آپ کے بغلوں کی سفیدی نظر آنے لگتی۔","الألباني: صحيح",{"u2":"حضرت انس رضی اللہ عنہ بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم کسی بھی دعا میں اتنے بلند ہاتھ نہیں اٹھاتے تھے جتنے دعائے استسقاء میں۔ آپ اس میں ہاتھ اتنے بلند اٹھاتے کہ آپ کی بغلوں کی سفیدی نظر آتی۔","f2":"عام دعا میں سینے یا چہرے کے برابر ہاتھ اٹھاتے تھے۔ دعائے استسقاء میں کثرت تضرع و تخشع کی بنا پر ہاتھ مزید اونچے فرماتے۔"}],[1514,"آبی اللحم رضی اللہ عنہ سے روایت ہے کہ انہوں نے رسول اللہ صلی اللہ علیہ وسلم کو احجار الزیت کے پاس دیکھا کہ آپ بارش کے لیے دعا کر رہے تھے، اور اپنی دونوں ہتھیلیوں کو اٹھائے دعا کر رہے تھے۔\n§وضاحت\n۱؎: \"احجار الزیت\" مدینہ میں ایک مقام کا نام ہے۔","الألباني: صحيح",{"u2":"حضرت آبی اللحم رضی اللہ عنہ سے رویات ہے انھوں نے نبی صلی اللہ علیہ وسلم کو احجارالزیت کے مقام پر بارش کی دعا کرتے دیکھا۔ آپ نے اپنے ہاتھ اٹھائے ہوئے تھے اور دعا فرما رہے تھے۔","f2":"(۱)آبی اللحم نام نہیں لقب ہے کیونکہ یہ جاہلیت میں بتوں کے نام پر ذبح کیے گئے جانور کا گوشت نہیں کھاتے تھے۔ ان کے نام کی بابت اختلاف ہے۔ بعض نے عبداللہ بن عبدالملک، بعض نے خلف اور حویرث بتایا ہے۔ جنگ صفین میں شہید ہوئے۔ رضی اللہ عنہ۔ (۲)احجار الزیت مدینہ منورہ کے قریب ایک جگہ کا نام ہے کیونکہ وہاں پتھر سیاہ چمکدار تھے جیسے انھیں تیل ملاگیا ہو۔"}],[1515,"انس بن مالک رضی اللہ عنہ کہتے ہیں کہ ہم لوگ جمعہ کے روز مسجد میں تھے، اور رسول اللہ صلی اللہ علیہ وسلم لوگوں کو خطبہ دے رہے تھے کہ اسی دوران ایک آدمی کھڑا ہوا اور اس نے عرض کیا: اللہ کے رسول! راستے (سفر) ٹھپ ہو گئے، جانور ہلاک ہو گئے، اور علاقے خشک سالی کا شکار ہو گئے، لہٰذا آپ اللہ تعالی سے دعا کیجئیے کہ وہ ہمیں سیراب کرے۔ چنانچہ رسول اللہ صلی اللہ علیہ وسلم نے اپنے دونوں ہاتھوں کو اپنے چہرے کے بالمقابل اٹھایا، پھر آپ نے دعا کی: «اللہم اسقنا»\"اے اللہ! ہمیں سیراب کر\" تو قسم اللہ کی! رسول اللہ صلی اللہ علیہ وسلم ابھی منبر سے اترے بھی نہ تھے کہ زور دار بارش ہونے لگی، اور اس دن سے دوسرے جمعہ تک بارش ہوتی رہی۔ چنانچہ پھر ایک آدمی کھڑا ہوا (مجھے یاد نہیں کہ یہ وہی شخص تھا جس نے رسول اللہ صلی اللہ علیہ وسلم سے بارش کے لیے دعا کرنے کے لیے کہا تھا یا کوئی دوسرا شخص تھا) اور اس نے عرض کیا: اللہ کے رسول! پانی کی زیادتی کی وجہ سے راستے بند ہو گئے ہیں، اور جانور ہلاک ہو گئے ہیں، لہٰذا آپ اللہ تعالی سے دعا کیجئیے کہ وہ (اب) ہم سے بارش روک لے۔ چنانچہ رسول اللہ صلی اللہ علیہ وسلم نے دعا کی: «اللہم حوالينا ولا علينا ولكن على الجبال ومنابت الشجر» \"اے اللہ! ہمارے اطراف میں برسا، ہم پر نہ برسا، اور پہاڑوں پر اور درختوں کے اگنے کی جگہوں پر برسا\"۔ انس رضی اللہ عنہ کہتے ہیں: قسم اللہ کی! آپ کا یہ کہنا ہی تھا کہ بادل پھٹ پھٹ کر (آسمان صاف ہو گیا) یہاں تک کہ ہمیں اس میں سے کچھ نہیں دکھائی دے رہا تھا۔","الألباني: حسن صحيح",{"u2":"حضرت انس بن مالک رضی اللہ عنہ بیان کرتے ہیں کہ ایک دفعہ ہم جمعے کے دن مسجد میں تھے اور رسول اللہ صلی اللہ علیہ وسلم لوگوں کو خطبہ دے رہے تھے کہ ایک آدمی کھڑا ہوا اور کہنے لگا: اے اللہ کے رسول! راستے منقطع ہوگئے اور جانور ہلاک ہونے لگے اور شہروں میں قحط پڑگیا۔ اللہ تعالیٰ سے دعا فرمائیے، ہمیں بارش عطا فرمائے۔ رسول اللہ صلی اللہ علیہ وسلم نے چہرۂ مبارک کے برابر اپنے ہاتھ اٹھائے اور فرمایا: (اللھم!اسقنا) ’’اے اللہ! ہم پر بارش نازل فرما۔‘‘ اللہ کی قسم! ابھی اللہ کے رسول صلی اللہ علیہ وسلم منبر سے نہیں اترے تھے کہ ہم پر خوب زور سے بارش برسنے لگی بلکہ اس دن سے اگلے جمعے تک بارش برستی رہی۔ تو ایک آدمی کھڑا ہوا۔۔۔ میں نہیں جانتا یہ وہی شخص تھا جس نے رسول اللہ صلی اللہ علیہ وسلم سے بارش کی دعا کرنے کو کہا تھا یا کوئی اور۔۔۔ اس نے کہا: اے اللہ کے رسول! پانی کی زیادتی کی وجہ سے راستے منقطع ہوگئے اور جانور مرنے لگے۔ اللہ تعالیٰ سے دعا فرمائیے کہ اللہ تعالیٰ ہم سے بارش روک لے۔ تو رسول اللہ صلی اللہ علیہ وسلم نے دعا فرمائی: (اللھم! حرالینا) ’’اے اللہ! ہمارے اردگرد بارش فرما، ہم پر نہ فرما بلکہ پہاڑوں اور جنگلات پر بارش فرما۔‘‘ اللہ کی قسم! جونہی رسول اللہ صلی اللہ علیہ وسلم نے یہ کلمات کہے، بادل چھٹنے لگے حتی کہ ہمیں ایک ٹکڑا بھی نظر نہ آتا تھا۔","f2":"(۱)’’چہرۂ مبارک کے برابر‘‘ یہ مسجد نبوی کے اندر کی بات ہے اور حضرت انس رضی اللہ عنہ ہی کی روایت: (۱۵۱۴) شہر سے باہر کے بارے میں تھی، لہٰذا کوئی تعارض نہیں۔ عام دعا میں ہاتھ سینے یا چہرے کے برابر ہی اٹھائے جاتے ہیں۔ (۲)امام صاحب نے ہاتھ اٹھانے کی کیفیت کا باب نہیں باندھا۔ صحیح مسلم میں حضرت انس رضی اللہ عنہ سے روایت ہے کہ دعائے استسقاء میں آپ کے ہاتھوں کی پشت آسمان کی طرف تھی اور ہتھیلیاں زمین کے رخ تھیں۔ اس سے علماء نے استدلال کیا ہے کہ اگر کسی واقع مصیبت کے رفع کی دعا ہو تو ہاتھ الٹے ہوں، یعنی ان کی پشت آسمان کی طرف ہو اور اگر کسی چیز کا سوال ہو تو ہتھیلیاں آسمان کی طرف ہوں۔ شاید دعائے استسقاء میں ہاتھوں کو الٹنا، چادر الٹانے کی طرح بطورِ فال ہو کہ اللہ تعالیٰ ہماری حالت بدل دے۔ (۳)آپ کی دونوں دعاؤں کی فوری قبولیت علامات نبوت میں سے ہے۔"}],[1516,"انس بن مالک رضی اللہ عنہ سے روایت ہے کہ نبی اکرم صلی اللہ علیہ وسلم نے دعا کی: «اللہم اسقنا» \"اے اللہ! ہمیں سیراب فرما\"۔","الألباني: صحيح",{"u2":"حضرت انس بن مالک رضی اللہ عنہ سے روایت ہے، نبی صلی اللہ علیہ وسلم نے فرمایا: (اللھم! اسقنا) ’’اے اللہ! ہمیں بارش عطا فرما۔‘‘"}],[1517,"انس رضی اللہ عنہ کہتے ہیں کہ نبی اکرم صلی اللہ علیہ وسلم جمعہ کا خطبہ دے رہے تھے کہ کچھ لوگ آپ کی طرف اٹھ کر بڑھے، اور چلا کر کہنے لگے: اللہ کے نبی! بارش نہیں ہو رہی ہے، اور جانور ہلاک ہو رہے ہیں، آپ اللہ تعالی سے دعا کیجئیے کہ وہ ہمیں سیراب کرے۔ تو آپ نے دعا کی: «اللہم اسقنا اللہم اسقنا» \"اے اللہ! ہمیں سیراب فرما، اے اللہ ہمیں سیراب فرما\"۔ انس رضی اللہ عنہ کہتے ہیں: قسم اللہ کی! اس وقت ہم کو آسمان میں بادل کا ایک ٹکڑا بھی نظر نہیں آ رہا تھا (مگر آپ کے دعا کرتے ہی) بدلی اٹھی، اور پھیل گئی، پھر برسنے لگی، رسول اللہ صلی اللہ علیہ وسلم اترے، اور آپ نے نماز پڑھی، اور لوگ فارغ ہو کر پلٹے تو دوسرے جمعہ تک برابر بارش ہوتی رہی۔ تو دوسرے جمعہ کو جب رسول اللہ صلی اللہ علیہ وسلم کھڑے ہو کر خطبہ دینے لگے، تو لوگ پھر چلا کر کہنے لگے: اللہ کے نبی! گھر گر گئے، راستے ٹھپ ہو گئے، آپ اللہ تعالی سے دعا کیجئیے کہ وہ اب اسے ہم سے روک لے، تو رسول اللہ صلی اللہ علیہ وسلم مسکرائے، اور آپ نے دعا فرمائی: «اللہم حوالينا ولا علينا» \"اے اللہ! ہمارے اطراف میں برسا ہم پر نہ برسا\" تو بادل مدینہ سے چھٹ گئے، اور اس کے اطراف میں برسنے لگے، اور مدینہ میں ایک بوند بارش کی نہیں پڑ رہی تھی۔ میں نے مدینہ کو دیکھا کہ وہ ایسا لگ رہا تھا گویا وہ تاج پہنے ہوئے ہے۔","الألباني: صحيح",{"u2":"حضرت انس رضی اللہ عنہ سے روایت ہے کہ نبی صلی اللہ علیہ وسلم جمعے کے دن خطبہ ارشاد فرما رہے تھے کہ لوگ کھڑے ہوکر بلند آواز سے کہنے لگے: اے اللہ کے نبی! بارش (عرصۂ دراز سے) رکی ہوئی ہے اور جانور مررہے ہیں۔ اللہ تعالیٰ سے دعا فرمائیے کہ بارش نازل فرمائے۔ آپ نے فرمایا: (اللھم! اسقنا، اللھم! اسقنا) ’’اے اللہ! ہمیں پانی پلا۔ اے اللہ! ہمیں پانی پلا۔‘‘ اللہ کی قسم! ہم آسمان میں بادل کا ایک ٹکڑا بھی نہیں دیکھتے تھے، پھر ایک چھوٹا سا بادل پیدا ہوا، پھر اس نے پھیلنا شروع کیا، پھر وہ برسنے لگا اور اللہ کے رسول صلی اللہ علیہ وسلم منبر سے اترے اور نماز پڑھائی۔ لوگ (بارش میں) گھروں کو گئے۔ اگلے جمعے تک (مسلسل) بارش ہوتی رہی۔ تو جب اللہ کے رسول صلی اللہ علیہ وسلم خطبے کے لیے کھڑے ہوئے تو لوگوں نے پھر بلند آواز سے کہا: اے اللہ کے نبی! گھر گر گئے اور راستے منقطع ہوگئے۔ اللہ تعالیٰ سے دعا کیجیے، اللہ تعالیٰ بارش روک لے۔ رسول اللہ صلی اللہ علیہ وسلم مسکرائے اور فرمایا: ’’اے اللہ! ہمارے اردگرد بارش فرما، ہم پر نہ فرما۔‘‘ بادل مدینہ منورہ سے چھٹ گئے۔ مدینے کے اردگرد بارش ہوتی تھی اور مدینے میں ایک قطرہ بھی نہیں برستا تھا۔ میں نے مدینہ منورہ کو دیکھا، ایسے لگتا تھا جیسے اس پر تاج ہو۔","f2":"مدینہ منورہ کے اوپر بالکل بادل نہیں تھے، اردگرد بادل تھے۔ درمیان میں گولائی کی صورت میں نیلگوں آسمان نظر آتا تھا۔ تاج بھی ایسا ہی ہوتا ہے، گول اور سر کے گرداگرد لپٹا ہوا۔ یہ ایک بہترین شاعرانہ تخیل ہے جس سے حضرت انس رضی اللہ عنہ کی مدینہ منورہ سے عقیدت اور محبت جھلکتی ہے۔ انھوں نے اس صورت حال کو ایسے پیارے الفاظ سے بیان فرمایا۔ رضی اللہ عنہ وارضاء۔"}],[1518,"انس بن مالک رضی اللہ عنہ سے روایت ہے کہ ایک آدمی مسجد میں داخل ہوا، اور رسول اللہ صلی اللہ علیہ وسلم کھڑے خطبہ دے رہے تھے، تو وہ رسول اللہ صلی اللہ علیہ وسلم کی طرف رخ کر کے کھڑا ہو گیا، اور کہنے لگا: اللہ کے رسول! مال (جانور) ہلاک ہو گئے، اور راستے بند ہو گئے، آپ اللہ تعالی سے دعا کیجئیے کہ وہ ہمیں سیراب کرے، تو رسول اللہ صلی اللہ علیہ وسلم نے اپنے دونوں ہاتھ اٹھائے، اور دعا کی: «اللہم أغثنا اللہم أغثنا» \"اے اللہ! ہمیں سیراب فرما، اے اللہ ہمیں سیراب فرما\"۔ انس رضی اللہ عنہ کہتے ہیں: قسم اللہ کی! ہم کو آسمان میں کہیں بادل یا بادل کا کوئی ٹکڑا دکھائی نہیں دے رہا تھا، اور ہمارے اور سلع پہاڑی کے بیچ کسی گھر یا مکان کی آڑ نہ تھی، اتنے میں ڈھال کے مانند بادل کا ایک ٹکڑا نمودار ہوا، پھر جب وہ آسمان کے درمیان میں پہنچا تو پھیل گیا، اور برسنے لگا۔ انس رضی اللہ عنہ کہتے ہیں: قسم اللہ کی! ہم نے ایک ہفتہ تک سورج نہیں دیکھا۔ پھر اگلے جمعہ میں اسی دروازے سے ایک آدمی داخل ہوا، اور رسول اللہ صلی اللہ علیہ وسلم کھڑے خطبہ دے رہے تھے، تو وہ آپ کی طرف چہرہ کر کے کھڑا ہو گیا، اور اس نے عرض کیا: اللہ کے رسول! اللہ کا سلام و صلاۃ (درود و رحمت) ہو آپ پر! مال ہلاک ہو گئے (جانور مر گئے)، اور راستے بند ہو گئے، آپ اللہ تعالی سے دعا کیجئیے کہ وہ ہم سے اسے روک لے، تو رسول اللہ صلی اللہ علیہ وسلم نے اپنے ہاتھ اٹھائے، اور دعا کی: «اللہم حوالينا ولا علينا اللہم على الآكام والظراب وبطون الأودية ومنابت الشجر» \"اے اللہ! ہمارے اردگرد برسا، ہم پر نہ برسا، اے اللہ! ٹیلوں، چوٹیوں، گھاٹیوں اور درختوں کے اگنے کی جگہوں پر برسا\" یہ کہنا تھا کہ بادل چھٹ گئے، اور ہم نکل کر دھوپ میں چل رہے تھے۔ شریک بن عبداللہ بن ابی نمر کہتے ہیں کہ میں نے انس رضی اللہ عنہ سے پوچھا: کیا یہ وہی پہلا شخص تھا، تو انہوں نے کہا: نہیں ۱؎۔\n§وضاحت\n۱؎: اس حدیث میں جزم ہے، اور اس سے پہلے ایک روایت گزر چکی ہے اس میں ہے کہ انہوں نے کہا «لا أدری ہو الذی قال لرسول اللہ صلی اللہ علیہ وسلم استسق لنا أم لا» دونوں میں اس طرح تطبیق دی گئی ہے کہ شاید انہیں بھول جانے کے بعد یاد آیا ہو، یا یاد رہا ہو پھر بھول گئے ہوں یا «لا» یہاں «لا أدری» کے معنی میں ہو۔","الألباني: حسن صحيح",{"u2":"حضرت انس بن مالک رضی اللہ عنہ سے مروی ہے کہ ایک آدمی مسجد میں داخل ہوا جب کہ رسول اللہ صلی اللہ علیہ وسلم کھڑے خطبہ دے رہے تھے۔ وہ رسول اللہ صلی اللہ علیہ وسلم کے سامنے آکر کھڑا ہوگیا اور کہنے لگا: اے اللہ کے رسول! جانور مرگئے اور راستے منقطع ہوگئے، اللہ تعالیٰ سے دعا کیجیے کہ اللہ تعالیٰ ہم پر بارش برسائے۔ تو رسول اللہ صلی اللہ علیہ وسلم نے اپنے ہاتھ اٹھائے، پھر فرمایا: ’’اے اللہ! ہم پر بارش برسا۔ اے اللہ! ہم پر بارش برسا۔‘‘ حضرت انس رضی اللہ عنہ بیان کرتے ہیں: اللہ کی قسم! آسمان میں بادل کیا بادل کا ٹکڑا بھی نہ دیکھتے تھے، نیز ہمارے اور سلع پہاڑ کے درمیان کوئی مکان یا گھر بھی حائل نہ تھا۔ اچانک ڈھال جتنا چھوٹا سا بادل کا ٹکڑا (پہاڑ کے پیچھے سے) ظاہر ہوا، جب وہ آسمان کے درمیان میں (یعنی ہمارے سروں پر) آیا تو پھیل گیا اور برسنے لگا۔ حضرت انس بیان کرتے ہیں: اللہ کی قسم! پھر ہم نے پورا ہفتہ (سات دن) سورج نہیں دیکھا، پھر آئندہ جمعے اسی دروازے سے ایک آدمی داخل ہوا جب کہ رسول اللہ صلی اللہ علیہ وسلم خطبہ ارشاد فرما رہے تھے۔ وہ آپ کے سامنے آکر کھڑا ہوگیا اور کہنے لگا: اے اللہ کے رسول! اللہ تعالیٰ آپ پر (بے شمار) رحمتیں فرمائے۔ (پانی کی کثرت کی بنا پر) جانور مرنے لگے ہیں اور راستے بھی منقطع ہیں۔ اللہ تعالیٰ سے دعا فرمائیے کہ ہم سے بارش روک لے۔ تو رسول اللہ صلی اللہ علیہ وسلمنے اپنے ہاتھ اٹھائے اور فرمایا: ’’اے اللہ! ہمارے اردگرد بارش برسا، ہم پر نہ برسا۔ اے اللہ! ٹیلوں پر، تودوں پر، وادیوں کے نشیب اور جنگلات میں بارش برسا۔‘‘ حضرت انس رضی اللہ عنہ بیان کرتے ہیں کہ (یہ کہنا تھا کہ) بارش فوراً رک گئی اور ہم مسجد سے نکلے تو دھوپ میں چلتے تھے۔ شریک (راوی) نے کہا: میں نے حضرت انس رضی اللہ عنہ سے پوچھا: کیا یہ پہلا آدمی ہی تھا؟ انھوں نے فرمایا: نہیں۔","f2":"(۱)عربی میں عبادت میں صرف لفظ لا ہے جس کے معنی ہوتے ہیں ’’نہیں‘‘ یعنی یہ وہ آدمی نہیں تھا۔ مگر حدیث نمبر (۱۵۱۶) کی صراحت کے خلاف ہے، وہاں صراحت ہے کہ میں نہیں جانتا کہ یہ وہی شخص تھا یا اور، لہٰذا یہاں یہ معنی مراد ہیں کہ میں نہیں جانتا۔ واللہ اعلم۔ (۲)مذکورہ چاروں روایات میں نمازاستسقاء کے بغیر صرف دعا کا ذکر ہے، گویا نماز ضروری نہیں۔ صرف دعا بھی کافی ہے، الایہ کہ کہا جائے کہ جمعے کی دو رکعت نماز استسقاء کی جگہ کفایت کرتی ہیں۔ امام ابوحنیفہ رحمہ اللہ سرے سے نمازاستسقاء یہ کے قائل نہیں، یعنی ان کے نزدیک نماز استسقاء مسنون نہیں۔ مگر یہ موقف ان صحیح اور صریح روایات کے خلاف ہے جن میں دعائے استسقاء کے لیے نبی صلی اللہ علیہ وسلم کا شہر سے باہر جانا بلکہ منبر ساتھ لے جانا اور دعا کے بعد دو رکعات پڑھانے کا صراحتاً ذکر ہے، لہٰذا یہ امام صاحب کی اجتہادی غلطی ہے جسے غلطی ہی ماننا چاہیے نہ کہ ان کے قول کی وجہ سے صحیح اور صریح روایات کی دور از کار تاویلات کرنی چاہییں کہ یہ دراصل جمعے ہی کی نماز تھی صرف مسجد مسقف (چھت والی) سے باہر مسجد کے صحن میں آئے اور منبر بھی وہیں لایا گیا تھا۔ ایسی پنجگانہ تاویلیں اہل علم کے شایان شان نہیں۔ کوئی شخص بھی غلطی سے پاک اور معصوم نہیں ہے لہٰذا یہ تکلف بے جا ہے۔"}],[1519,"عباد بن تمیم کے چچا عبداللہ بن زید رضی اللہ عنہ کہتے ہیں کہ ایک دن رسول اللہ صلی اللہ علیہ وسلم استسقاء کی غرض سے نکلے، تو آپ نے لوگوں کی جانب اپنی پیٹھ پھیری، اور قبلہ رخ کھڑے ہو کر اللہ سے دعا کی، اور اپنی چادر الٹی، پھر آپ نے دو رکعت نماز پڑھی۔ ابن ابی ذئب کہتے ہیں: حدیث میں یہ بھی ہے: «وقرأ فيهما»\"اور ان دونوں میں قرأت کی\"۔","الألباني: صحيح",{"u2":"حضرت عباد بن تمیم نے اپنے چچا (حضرت عبداللہ بن زید بن عاصم رضی اللہ عنہ) سے سنا جو کہ اصحاب رسول صلی اللہ علیہ وسلم میں سے تھے کہ رسول اللہ صلی اللہ علیہ وسلم ایک دن بارش کی دعا کرنے نکلے۔ آپ نے دعا کے وقت لوگوں کی طرف پیٹھ کرلی (یعنی آپ کا رخ مبارک قبلے کی طرف تھا۔) اور آپ نے اپنی چادر بھی الٹائی تھی، پھر (دعا کے بعد) آپ نے دورکعتیں پڑھیں اور ان دونوں میں قراءت بھی کی۔"}],[1520,"عبداللہ بن زید رضی اللہ عنہ سے روایت ہے کہ نبی اکرم صلی اللہ علیہ وسلم اللہ تعالی سے بارش طلب کرنے نکلے، تو آپ نے دو رکعت نماز پڑھی، اور قبلہ کی طرف منہ کیا۔","الألباني: صحيح",{"u2":"حضرت عبداللہ بن زید رضی اللہ عنہ سے روایت ہے کہ نبی صلی اللہ علیہ وسلم بارش کی دعا کرنے کے لیے (شہرسے) باہر نکلے، پھر آپ نے قبلہ رخ ہوکر (دعا کی اور) دو رکعتیں پڑھیں۔"}],[1521,"اسحاق بن عبداللہ بن کنانہ کہتے ہیں کہ امراء میں سے ایک امیر نے مجھے ابن عباس رضی اللہ عنہم کے پاس بھیجا کہ میں ان سے استسقاء کے بارے میں پوچھوں، تو ابن عباس رضی اللہ عنہم نے کہا: وہ مجھ سے خود کیوں نہیں پوچھتے؟ رسول اللہ صلی اللہ علیہ وسلم عاجزی و انکساری کے ساتھ پھٹے پرانے کپڑوں میں گریہ وزاری کرتے ہوئے نکلے، پھر آپ نے دو رکعت نماز پڑھی، اسی طرح جیسی آپ عیدین میں پڑھتے تھے، اور آپ نے تمہارے اس خطبہ کی طرح خطبہ نہیں دیا ۱؎۔\n§وضاحت\n۱؎: یہاں نفی قید کی ہے، مقید کی نہیں جیسا کہ اس پر وہ احادیث دلالت کرتی ہیں جن میں خطبہ کی تصریح ہے۔","الألباني: حسن",{"u2":"حضرت اسحاق بن عبداللہ بن کنانہ رحمہ اللہ بیان کرتے ہیں کہ مجھے کسی امیر (حاکم) نے حضرت ابن عباس رضی اللہ عنہما کے پاس بھیجا کہ میں ان سے دعا استسقاء کے بارے میں پوچھوں۔ حضرت ابن عباس رضی اللہ عنہما نے فرمایا: اسے کون سی چیز خود مجھ سے سوال کرنے سے مانع ہے؟ رسول اللہ صلی اللہ علیہ وسلم عاجزی کی حالت میں سادہ کپڑے پہن کر خشوع خضوع کے ساتھ گڑگڑاتے ہوئے (مدینہ منورہ سے) باہر نکلے اور عیدین کی نماز کی طرح دو رکعتیں پڑھیں اور تمھارے خطبے کی طرح خطبہ نہیں دیا۔"}],[1522,"عباد بن تمیم کے چچا عبداللہ بن زید رضی اللہ عنہ روایت کرتے ہیں کہ نبی اکرم صلی اللہ علیہ وسلم استسقاء کے لیے نکلے، تو آپ نے دو رکعت نماز پڑھی، ان میں آپ نے بلند آواز سے قرآت کی۔","الألباني: صحيح",{"u2":"حضرت عباد بن تمیم کے چچا سے روایت ہے کہ نبی صلی اللہ علیہ وسلم (مدینہ منورہ سے) باہر نکلے، بارش کی دعا کی، پھر دو رکعتیں پڑھیں اور ان میں بلند آواز سے قراءت کی۔","f2":"مخصوص نمازیں (فرض نمازوں کے علاوہ) جو باجماعت پڑھی جاتی ہیں، خواہ دن کے وقت ہوں، ان میں قراءت جہراً ہی ہوتی ہے، مثلاً: جمعہ، عیدین، نمازکسوف، نمازاستسقاء اور یہی انسب ہے۔"}],[1523,"ام المؤمنین عائشہ رضی اللہ عنہا سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم جب بارش ہوتی تو کہتے: «اللہم اجعله صيبا نافعا» \"اے اللہ! خوب برسا اور اسے فائدہ مند بنا\"۔","الألباني: صحيح",{"u2":"حضرت عائشہ رضی اللہ عنہا سے روایت ہے کہ جب بارش برسنے لگتی تو رسول اللہ صلی اللہ علیہ وسلم فرماتے: ’’اے اللہ! زور سے برسا اسے مفید بارش بنا۔‘‘"}],[1524,"ابوہریرہ رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"اللہ تعالی فرماتا ہے: جب بھی میں نے اپنے بندوں کو بارش کی نعمت سے نوازا تو ان میں سے ایک گروہ اس کی وجہ سے کافر رہا، وہ لوگ کہتے رہے: فلاں ستارے نے ایسا کیا ہے، اور فلاں ستارے کی وجہ سے ایسا ہوا ہے\" ۱؎۔\n§وضاحت\n۱؎: حالانکہ ستاروں میں کوئی طاقت نہیں، وہ تو جماد ہیں، یہ نعمت تو اس ذات باری تعالی نے دی ہے جس نے ستاروں، ساری مخلوقات کو پیدا کیا ہے۔","الألباني: صحيح",{"u2":"حضرت ابوہریرہ رضی اللہ عنہ سے روایت ہے، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’اللہ تعالیٰ نے فرمایا: جب بھی میں اپنے بندوں پر کوئی نعمت (مثلاً: بارش) نازل فرماتا ہوں تو ان میں سے ایک گروہ اس کی وجہ سے کفر کا ارتکاب کرتا ہے۔ کہتا ہے: ہم پر فلاں ستارے نے بارش برسائی ہے یا ہم فلاں ستارے سے سیراب ہوئے۔‘‘","f2":"مذکورہ طریقے پر بارش کی نسبت ستارے کی طرف کرنا (یعنی اس نے برسائی) کفریہ الفاظ ہیں۔ ایک موحد اس قسم کے الفاظ کہنے سے گریز کرتا ہے کیونکہ اس کا عقیدہ یہ نہیں ہوتا، مگر کافر تو اس عقیدے کے بھی قائل تھے۔ بہرصورت یہ الفاظ کفریہ ہیں، البتہ اگر ستارے کے طلوع وغیرہ کو بارش برسنے کی علامت یا وقت کہا جائے تو پھر یہ کفریہ الفاظ نہیں مگر ایک بے تحقیق اور غلط بات ضرور ہے، ہاں اگر بادلوں اورہواؤں کی طرف بارش کی نسبت بطور علامت کرے تو کوئی حرج نہیں۔ احادیث اور کلام عرب اس پر دال ہیں، نیز یہ چیزیں بارش کا ظاہری سبب ہیں، بخلاف ستاروں کے کہ ان کا ظاہراً بارش سے کوئی تعلق نہیں، نیز اس میں ستارہ پرستوں سے مشابہت ہے، لہٰذا منع ہے۔ دوسرے معنی یہ بھی ہوسکتے ہیں کہ ان م یں سے ایک گروہ اس کی ناشکری کرتا ہے یا اس کے نعمت الٰہیہ ہونے کا انکار کرتا ہے۔ یہاں سے ضمناً یہ معلوم ہوا کہ عقائد میں مجازات اور استعارات کا استعمال درست نہیں، خصوصاً توحید جیسے مسئلے میں۔"}],[1525,"زید بن خالد جہنی رضی اللہ عنہ کہتے ہیں کہ نبی اکرم صلی اللہ علیہ وسلم کے زمانے میں بارش ہوئی تو آپ نے فرمایا: \"کیا تم نے سنا نہیں کہ تمہارے رب نے آج رات کیا فرمایا؟ اس نے فرمایا: میں نے جب بھی بارش کی نعمت اپنے بندوں پر کی تو ان میں سے ایک گروہ اس کی وجہ سے کافر رہا، وہ کہتا رہا: فلاں و فلاں نچھتر کے سبب ہم پر بارش ہوئی، تو رہا وہ شخص جو مجھ پر ایمان لایا، اور میرے بارش برسانے پر اس نے میری تعریف کی، تو یہ وہی شخص ہے جو مجھ پر ایمان لایا، اور ستاروں کا انکار کیا، اور جس نے کہا: ہم فلاں فلاں نچھتر کے سبب بارش دیئے گئے، تو یہ وہ شخص ہے جس نے میرے ساتھ کفر کیا، اور ستاروں پر ایمان رکھا\"۔","الألباني: صحيح",{"u2":"حضرت زید بن خالد جہنی رضی اللہ عنہ بیان کرتے ہیں کہ نبی صلی اللہ علیہ وسلم کے دور مسعود میں ایک دفعہ عام بارش ہوئی تو آپ نے فرمایا: ’’کیا تم جانتے نہیں کہ تمھارے رب تعالیٰ نے رات کیا کہا؟ اللہ تعالیٰ نے فرمایا: جب میں اپنے بندوں پر کوئی نعمت (خصوصاً بارش) نازل فرماتا ہوں تو ان میں سے کچھ لوگ اس کے ساتھ کفر کرتے ہیں۔ کہتے ہیں: ہم پر فلاں ستارے کی وجہ سے بارش ہوئی، البتہ جو شخص مجھ پر ایمان رکھتا ہے اور میرے بارش برسانے پر میری تعریف کرتا ہے، وہ حقیقتاً مومن ہے اور ستاروں کا کافر ہے (یعنی ستاروں کی طاقت و اختیار کا منکر ہے) اور جس شخص نے کہا: ہمیں فلاں ستارے سے بارش ہوئی۔ وہ میرے ساتھ کفر کرتا ہے اور ستاروں پر ایمان رکھتا ہے۔‘‘","f2":"ہر نعمت کے مہیا ہونے اور ملنے پر اللہ تعالیٰ کا شکر ادا کرنا ضروری ہے۔ نعمت کا حق بھی ادا ہوگا اور ایمان بھی پختہ ہوگا۔"}],[1526,"ابو سعید خدری رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"اگر اللہ تعالی اپنے بندوں سے پانچ سال تک بارش روکے رکھے، پھر اسے چھوڑے تو بھی لوگوں میں سے ایک گروہ کافر ہی رہے گا، کہے گا: ہم تو مجدح ستارے کے سبب برسائے گئے ہیں۔\n§وضاحت\n۱؎: \"مجدح ستارے\" ان ستاروں میں سے ایک ستارے کا نام ہے جو عربوں کے نزدیک بارش پر دلالت کرتے ہیں۔ اللہ تعالی سے بارش بند ہونے کی دعا کرے۔","الألباني: ضعيف",{"u2":"حضرت ابوسعیدخدری رضی اللہ عنہ سے روایت ہے، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’اگر اللہ تعالیٰ پانچ سال تک اپنے بندوں سے بارش روک رکھے، پھر بھیجے، تب بھی کچھ لوگ ضرور کفر کریں گے۔ وہ کہیں گے: ہمیں مجدح ستارے سے بارش ملی ہے۔","f2":"(۱)امام نسائی رحمہ اللہ عمل الیوم واللیلۃ میں لکھتے ہیں کہ مجدح سے مراد شعری ستارہ ہے جبکہ امام سندھی رحمہ اللہ اس کی بابت لکھتے ہیں کہ یہ ستاروں میں سے ایک ستارہ ہے۔ اسے دبران کہتے ہیں۔ تین ستاروں کے مجموعے کو بھی مجدح کہا جاتا ہے۔ جو عربوں کے خیال میں بارش برساتا تھا، مگر یہ خیال غلط ہے۔ بات صرف اتنی تھی کہ ان تاروں کے طلوع کے زمانے میں بارش ہوتی تھی۔ (۲)’’مجدح‘‘ میم کی زیر اور پیش دونوں کے ساتھ پڑھا جاسکتا ہے۔"}],[1527,"انس رضی اللہ عنہ کہتے ہیں کہ ایک سال بارش نہیں ہوئی تو کچھ مسلمان جمعہ کے دن نبی اکرم صلی اللہ علیہ وسلم کے سامنے کھڑے ہوئے، اور عرض کیا: اللہ کے رسول! بارش نہیں ہو رہی ہے، زمین سوکھ گئی ہے، اور جانور ہلاک ہو گئے ہیں، تو آپ صلی اللہ علیہ وسلم نے اپنے دونوں ہاتھوں کو اٹھایا، اور اس وقت آسمان میں ہمیں بادل کا کوئی ٹکڑا نظر نہیں آ رہا تھا، آپ نے اپنے دونوں ہاتھوں کو خوب دراز کیا یہاں تک کہ مجھے آپ کے بغلوں کی سفیدی دکھائی دینے لگی، آپ اللہ تعالی سے پانی برسنے کے لیے دعا کر رہے تھے۔ ابھی ہم جمعہ کی نماز سے فارغ بھی نہیں ہوئے تھے (کہ بارش ہونے لگی) یہاں تک کہ جس جوان کا گھر قریب تھا اس کو بھی اپنے گھر جانا مشکل ہو گیا، اور برابر دوسرے جمعہ تک بارش ہوتی رہی، جب اگلا جمعہ آیا تو لوگ کہنے لگے: اللہ کے رسول! گھر گر گئے، اور سوار محبوس ہو کر رہ گئے، تو رسول اللہ صلی اللہ علیہ وسلم ابن آدم (انسان) کے جلد اکتا جانے پر مسکرائے، پھر آپ نے اپنے دونوں ہاتھ اٹھا کر یوں دعا کی: «اللہم حوالينا ولا علينا» \"اے اللہ! ہمارے اطراف میں برسا اور (اب) ہم پر نہ برسا\" تو مدینہ سے بادل چھٹ گئے۔","الألباني: صحيح الإسناد",{"u2":"حضرت انس رضی اللہ عنہ سے روایت ہے کہ ایک سال تک بارش رکی رہی تو ایک مسلمان جمعۃ المبارک کے دن (خطبے کے دوران میں) نبی صلی اللہ علیہ وسلم کے سامنے آکھڑا ہوا اور کہنے لگا: اے اللہ کے رسول! بارش (سال بھر سے) رکی ہوئی ہے، زمین بنجر ہوگئی ہے اور جانور مررہے ہیں۔ راوی بیان کرتا ہے کہ نبی صلی اللہ علیہ وسلم نے اپنے ہاتھ اٹھائے جب کہ ہم آسمان پر بادل کا ایک ٹکڑا بھی نہیں دیکھتے تھے۔ آپ نے اپنے دونوں ہاتھ اس قدر اٹھائے کہ میں نے آپ کی بغلوں کی سفیدی دیکھی۔ آپ اللہ عزوجل سے بارش کی دعا کرنے لگے۔ حضرت انس رضی اللہ عنہ فرماتے ہیں کہ ابھی ہم جمعہ پڑھ کر فارغ نہ ہوئے تھے (یعنی ابھی جمعے میں مصروف تھے، اتنی بارش برسی) کہ ہم میں قریب گھر والے نوجوان شخص کو بھی فکر لاحق ہوگئی کہ گھر کیسے پہنچوں گا؟ (دور والے اور بوڑھوں کی تو بات ہی کیا۔) پھر پورا ہفتہ بارش برستی رہی۔ جب اگلا جمعہ آیا تو لوگوں نے کہا: اے اللہ کے رسول! (کثرت بارش کی بنا پر) گھرگرگئے اور قافلے رک گئے۔ آپ انسان کے جلدی اکتاجانے پر مسکرائے، پھر ہاتھ اٹھا کر فرمایا: ’’اے اللہ ہمارے اردگرد بارش برسا، ہم پر نہ برسا۔‘‘ فوراً بادل مدینے سے چھٹ گئے۔","f2":"’’بغلوں کی سفیدی‘‘ بعض لوگوں نے سمجھا ہے کہ شاید آپ کی بغلوں میں بال نہ تھے مگر یہ بات غلط اور بلادلیل ہے۔ آپ کو انسانی عوارض سے مبرا قرار دینے کی کوشش کرنا کوئی عقل مندی کی بات نہیں اور نہ یہ چیز فضیلت کا موجب ہے، رسول اللہ صلی اللہ علیہ وسلم ایک مکمل انسان تھے۔"}],[1528,"انس بن مالک رضی اللہ عنہ کہتے ہیں کہ (ایک بار) رسول اللہ صلی اللہ علیہ وسلم کے زمانے میں لوگوں کو قحط سالی سے دو چار ہونا پڑا، رسول اللہ صلی اللہ علیہ وسلم منبر پر جمعہ کے دن خطبہ دے رہے تھے کہ اسی دوران ایک اعرابی (بدو) کھڑا ہوا، اور کہنے لگا: اللہ کے رسول! مال (جانور) ہلاک ہو گئے، اور بال بچے بھوکے ہیں، لہٰذا آپ ہمارے لیے اللہ تعالی سے دعا کیجئیے۔ تو رسول اللہ صلی اللہ علیہ وسلم نے اپنے ہاتھوں کو اٹھایا، اس وقت ہمیں آسمان پر بادل کا کوئی ٹکڑا دکھائی نہیں دے رہا تھا۔ قسم ہے اس ذات کی جس کے ہاتھ میں میری جان ہے۔ آپ نے اپنے ہاتھوں کو ابھی نیچے بھی نہیں کیا تھا کہ بادل پہاڑ کے مانند امنڈنے لگا، اور آپ ابھی اپنے منبر سے اترے بھی نہیں کہ میں نے دیکھا بارش کا پانی آپ کی داڑھی سے ٹپک رہا ہے، ہم پر اس دن، دوسرے دن اور اس کے بعد والے دن یہاں تک کہ دوسرے جمعہ تک برابر بارش ہوتی رہی، تو وہی اعرابی یا کوئی اور شخص کھڑا ہوا، اور کہنے لگا: اللہ کے رسول! عمارتیں منہدم ہو گئیں، اور مال و اسباب ڈوب گئے، لہٰذا آپ ہمارے لیے اللہ تعالی سے دعا کیجئیے۔ تو پھر رسول اللہ صلی اللہ علیہ وسلم نے اپنے ہاتھوں کو اٹھایا، اور آپ نے یوں دعا کی: «اللہم حوالينا ولا علينا» \"اے اللہ! ہمارے اطراف میں برسا اور (اب) ہم پر نہ برسا\" چنانچہ آپ نے اپنے ہاتھ سے بادل کی جانب جس طرف سے بھی اشارہ کیا، وہ وہاں سے چھٹ گئے یہاں تک کہ مدینہ ایک گڈھے کی طرح لگنے لگا، اور وادی پانی سے بھر گئی، اور جو بھی کوئی کسی طرف سے آتا یہی بتاتا کہ خوب بارش ہوئی ہے۔","الألباني: صحيح",{"u2":"حضرت انس بن مالک رضی اللہ عنہ بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم کے زمانے میں لوگوں پر ایک سال تک قحط پڑگیا۔ ایک دفعہ رسول اللہ صلی اللہ علیہ وسلم جمعۃ المبارک کے دن منبر پر خطبہ ارشاد فرما رہے تھے کہ ایک اعرابی اٹھ کھڑا ہوا اور کہنے لگا: اے اللہ کے رسول! جانور مرنے لگے ہیں اور بال بچے بھوکے ہیں، اللہ تعالیٰ سے ہمارے لیے بارش کی دعا کیجیے۔ رسول اللہ صلی اللہ علیہ وسلم نے اپنے دونوں مبارک ہاتھ اٹھا دیے۔ ہم آسمان پر بادل کا ایک ٹکڑا بھی نہیں دیکھتے تھے۔ قسم اس ذات کی جس کے ہاتھ میں میری جان ہے! ابھی آپ نے ہاتھ نیچے نہ فرمائے تھے کہ پہاڑوں جیسے بادل اٹھے، پھر ابھی اپنے منبر سے نیچے نہیں اترے تھے کہ میں نے بارش کے قطرے آپ کی ڈاڑھی مبارک پر برستے دیکھے۔ وہ دن، اگلا دن، اس سے اگلا دن حتی کہ اگلے جمعے تک بارش برستی رہی، پھر وہی اعرابی یا کوئی اور اٹھا اور کہنے لگا: اے اللہ کے رسول! اب تو عمارتیں ڈھ گئیں، (گھر گر پڑے) جانور ڈوبنے لگے، اللہ تعالیٰ سے ہمارے لیے بارش کے بند ہونے کی دعا فرمائیں۔ رسول اللہ صلی اللہ علیہ وسلم نے پھر اپنے دونوں ہاتھ مبارک اٹھا لیے اور فرمایا: ’’اے اللہ ہمارے اردگرد بارش فرما، ہم پر نہ برسا۔‘‘ آپ جس طرف کے بادل کی طرف بھی دست مبارک سے اشارہ فرماتے، وہ چھٹ جاتا، حتی کہ مدینہ منورہ حوض کی طرح ہوگیا۔ وادیٔ (قتاۃ ایک ماہ تک) بہتی رہی اور جو شخص بھی کسی علاقے سے آیا، اس نے خوب بارش بتلائی۔","f2":"اس واقعے میں چند باتیں قابل غور ہیں: (۱)ایک سال تک نبی صلی اللہ علیہ وسلم اور آپ کے صحابہ کرام رضی اللہ عنہم قحط کی تکلیف، برداشت کرتے رہے مگر اُف تک نہ کی۔ بڑے لوگوں کے ظرف بھی بڑے ہوتے ہیں اور وہ ہر وقت اللہ تعالیٰ کی رضا پر راضی رہتے ہیں۔ شکوے کا لفظ تو دور کی بات ہے، وہ تصور بھی دل و دماغ میں نہیں پاتے۔ (۲)اعرابی سادہ اور بے ساختہ ہوتے تھے۔ انھوں نے آپ کو لوگوں کی خصوصاً بے زبان جانوروں کی تکلیف کی طرف توجہ دلائی تو آپ نے لحاظ رکھتے ہوئے دعا فرما دی۔ (۳)ہفتہ بھر کی بارش کی مشقت بھی رسول اللہ صلی اللہ علیہ وسلم اور صحابہ کرام رضی اللہ عنہم خندہ پیشانی سے برداشت فرماتے رہے۔ شکوہ تو کجا حرف دعا بھی زبان پر نہ لائے حتی کہ وہی اعرابی یا کسی اور غیرمعروف اعرابی کے اظہار مصیبت پر، خصوصاً جانوروں کی بے گناہ ہلاکت کے پیش نظر آپ نے بارش کی بندش کی دعا فرمائی۔ سب لوگوں کے ظرف تو ایک جیسے نہیں۔ یہ کائنات سب قسم کے لوگوں کے لیے ہے۔ (۴)رسول اللہ صلی اللہ علیہ وسلم کی شان عبودیت ملاحظہ کیجیے کہ ہاتھ اٹھاتے ہیں تو خالی آسمان بادلوں سے بھر جاتا ہے۔ ہاتھ گراتے ہیں تو بادل چھا جوں برسنے لگتے ہیں اور جب تک وہی مقدس ہاتھ نہیں اٹھتے، بادل برسنا بند نہیں ہوتے، اگرچہ سات دن گزر گئے، پھر وہ پاک ہاتھ اٹھتے ہیں تو بادل اچانک برسنے سے رک جاتے ہیں۔ ہاتھوں کا اشارہ ہوتا ہے تو بادل چھٹنے لگتے ہیں اور لوگ دھوپ میں چلنے لگتے ہیں۔ یہ مرتبہ ہے عبدہ و رسولہ کا، نہ اپنے لیے بارش مانگی، نہ خود بندش کی دعا کی، پھر فخر ہے نہ تعلیٰ، نداہ ابی وامی وروحی و نفسی و ولدی۔۔۔ صلی اللہ علیہ وسلم۔۔۔"}],[1529,"ثعلبہ بن زہدم کہتے ہیں کہ ہم سعید بن عاصی کے ساتھ طبرستان میں تھے، ہمارے ساتھ حذیفہ بن یمان رضی اللہ عنہ بھی تھے، سعید نے پوچھا: تم میں سے کس نے رسول اللہ صلی اللہ علیہ وسلم کے ساتھ خوف کی نماز پڑھی ہے؟ تو خذیفہ رضی اللہ عنہ نے کہا: میں نے، تو انہوں نے بیان کرتے ہوئے کہا کہ رسول اللہ صلی اللہ علیہ وسلم نے ایک گروہ کو جو آپ کے پیچھے صف باندھے تھا ایک رکعت پڑھائی، اور دوسرا گروہ آپ کے اور دشمنوں کے مابین ڈٹا ہوا تھا، تو جو گروہ آپ کے ساتھ تھا اسے آپ نے ایک رکعت پڑھائی، پھر وہ لوگ ان لوگوں کی جگہوں پر چلے گئے جو دشمن کے سامنے صف باندھے تھے، اور وہ لوگ ان کی جگہ آ گئے تو آپ نے انہیں (بھی)ایک رکعت پڑھائی۔","الألباني: صحيح",{"u2":"حضرت ثعلبہ بن زہدم سے روایت ہے کہ ہم طبرستان میں حضرت سعید بن عاص رضی اللہ عنہ کے ساتھ تھے اور ہمارے ساتھ حضرت حذیفہ بن یمان رضی اللہ عنہ بھی تھے۔ حضرت سعید بن عاص رضی اللہ عنہ نے کہا: تم میں سے کسی نے رسول اللہ صلی اللہ علیہ وسلم کے ساتھ صلاۃ خوف (خوف کی نماز) پڑھی ہے؟ حضرت حذیفہ رضی اللہ عنہ نے فرمایا: میں نے پھر انھوں نے آپ کی نماز کا طریقہ بیان کیا کہ رسول اللہ صلی اللہ علیہ وسلم نے نماز خوف ایک گروہ کو، جس نے آپ کے پیچھے صف باندھی تھی، ایک رکعت پڑھائی اور دوسرا گروہ آپ کے اور دشمن کے درمیان تھا (تاکہ دشمن نماز کی حالت میں حملہ نہ کرسکے۔) تو آپ نے اس گروہ کو جو آپ کے پیچھے تھا، ایک رکعت پڑھائی، پھر یہ گروہ دوسرے گروہ کی لڑائی کی جگہ میں پہنچ گیا اور وہ گروہ ان کی جگہ آگیا۔ آپ نے ان کو بھی ایک رکعت پڑھائی۔"}],[1530,"ثعلبہ بن زہدم کہتے ہیں کہ ہم سعید بن عاصی کے ساتھ طبرستان میں تھے، تو انہوں نے پوچھا: تم لوگوں میں سے رسول اللہ صلی اللہ علیہ وسلم کے ساتھ خوف کی نماز کس نے پڑھی ہے؟ حذیفہ رضی اللہ عنہ نے کہا: میں نے، پھر حذیفہ رضی اللہ عنہ کھڑے ہو گئے، اور لوگوں نے ان کے پیچھے دو صف بنائی، ایک صف ان کے پیچھے تھی، اور ایک صف دشمن کے مقابلہ میں تھی، تو انہوں نے ان لوگوں کو جو ان کے پیچھے تھے ایک رکعت پڑھائی، پھر یہ لوگ دوسری صف والوں کی جگہ پر لوٹ گئے، اور وہ لوگ ان لوگوں کی جگہ پر آ گئے، پھر انہوں نے انہیں بھی ایک رکعت پڑھائی، اور ان لوگوں نے قضاء نہیں کی ۱؎۔\n§وضاحت\n۱؎: یعنی دونوں گروہوں نے ایک ایک رکعت ہی پر بس کیا کسی نے دوسری رکعت نہیں پڑھی۔","الألباني: صحيح",{"u2":"حضرت ثعلبہ بن زہدم بیان کرتے ہیں کہ ہم سعید بن عاص کے ساتھ طبرستان میں (جہاد کر رہے) تھے۔ انھوں نے کہا: تم میں سے کس نے رسول اللہ صلی اللہ علیہ وسلم کے ساتھ نماز خوف پڑھی ہے؟ حضرت حذیفہ رضی اللہ عنہ نے فرمایا: میں نے، پھر حضرت حذیفہ اٹھے اور لوگوں کی دوصفیں بنائیں۔ اپنے پیچھے والی صف کو آپ نے ایک رکعت پڑھائی، پھر یہ ان کی جگہ چلے گئے اور وہ (آپ کے پیچھے) آگئے۔ آپ نے ان کو بھی ایک رکعت پڑھائی، پھر انھوں نے دوسری رکعت نہیں پڑھی۔","f2":"(۱)نماز خوف کی مشروعیت قرآن مجید سے ثابت ہے بلکہ یہ واحد نماز ہے جس کا طریقہ بھی اجمالی طور پر قرآن کریم میں بتلایا گیا ہے۔ رسول اکرم صلی اللہ علیہ وسلم نے مختلف مقامات پر یہ نماز پڑھی۔ مگر حنفیہ میں سے امام ابویوسف رحمہ اللہ اور شوافع میں سے امام مزنی رحمہ اللہ نبی صلی اللہ علیہ وسلم کے بعد اسے قرآن یا احادیث میں مذکور طریقوں سے پڑھنا جائز نہیں سمجھتے۔ ان کا خیال ہے کہ نماز خوف نبی صلی اللہ علیہ وسلم کے ساتھ خاص تھی کیونکہ ہر شخص آپ کے کے پیچھے نماز پڑھنے کا خواہاں تھا۔ جنگ اور خوف کی وجہ سے مجبوری تھی کہ سب اکٹھے نہیں پڑھ سکتے تھے۔ دو دفعہ ایک ہی نماز پڑھنا یا پڑھانا درست نہیں لہٰذا مجبوراً یہ طریقہ اختیار کیا گیا تاکہ ہر شخص آپ کے پیچھے نماز پڑھ سکے۔ رسول اللہ صلی اللہ علیہ وسلم کے بعد کوئی شخص ایسا نہیں جس کے پیچھے نماز پڑھنے کی خصوصی فضیلت ہو یا سب اس کے پیچھے نماز پڑھنے کی خواہش رکھیں۔ قرآن مجید میں بھی نمازخوف کے بیان میں خصوصاً آپ سے خطاب کیا گیا ہے: (واذا کنت فیہم فاقمت لہم الصلوۃ) (النساء۴:۱۰۲) ’’جب آپ ان میں ہوں تو آپ انھیں نماز پڑھائیں‘‘ لہٰذا اب اگر خوف کا مسئلہ ہو تو دو گروہ کرلیے جائیں اورہر گروہ کو ان کے الگ الگ امام نماز پڑھائیں۔ مذکورہ بات عقل کو بہت جچتی ہے مگر صحابہ کرام رضی اللہ عنہم کا طرزعمل اس کے مطابق نہیں۔ بہت سے صحابہ کرام رضی اللہ عنہم سے ثابت ہے کہ انھوں نے رسول اللہ صلی اللہ علیہ وسلم کے بعد بھی نماز خوف مخصوص طریقوں سے پڑھی ہے، لہٰذا جمہور اہل علم کے نزدیک یہ نماز اب بھی مشروع ہے۔ اور یہی بات صحیح ہے۔ واللہ اعلم۔ (۲)احادیث میں نماز خوف کے چھ سات طریقے منقول ہیں کیونکہ خوف کی مختلف صورتیں ہوسکتی ہیں، لہٰذا ہر جگہ ایک ہی طریقے سے نماز پڑھنا ممکن نہیں جیسا کہ آئندہ احادیث سے وضاحت ہوگی۔ یہ سب احادیث صحیح ہیں۔ موقع محل کے مطابق ان میں سے کوئی سا بھی طریقہ اختیار کیا جاسکتا ہے۔ جن حضرات نے ایک طریقہ معین کرنے کی کوشش کی ہے، انھوں نے غیرضروری تکلف برتا ہے۔ حسب حالات تمام احادیث پر عمل کیا جاسکتا ہے۔ واللہ اعلم۔ (۳)اوپر مذکورہ دو احادیث میں ایک ہی واقعے کا بیان ہے۔ نمازخوف کی مخصوص مختلف صورتوں میں سے یہ بھی ایک صورت ہے، یعنی شدید خوف میں ایک رکعت بھی پڑھی جاسکتی ہے۔ مزید دیکھیے، حدیث:۱۵۳۳۔"}],[1531,"زید بن ثابت رضی اللہ عنہ نے نبی اکرم صلی اللہ علیہ وسلم سے حذیفہ رضی اللہ عنہ کی نماز کے مثل روایت کی ہے۔","الألباني: صحيح لغيره",{"u2":"حضرت زید بن ثابت رضی اللہ عنہ نے نبی صلی اللہ علیہ وسلم سےحضرت حذیفہ رضی اللہ عنہم کی نماز جیسی روایت بیان کی ہے۔"}],[1532,"عبداللہ بن عباس رضی اللہ عنہم کہتے ہیں کہ اللہ تعالی نے تمہارے نبی کریم صلی اللہ علیہ وسلم کی زبان پر حضر میں چار رکعت نماز فرض کی، اور سفر میں دو رکعت، اور خوف میں ایک رکعت۔","الألباني: صحيح",{"u2":"حضرت ابن عباس رضی اللہ عنہما بیان کرتے ہیں کہ اللہ تعالیٰ نے تمھارے نبی صلی اللہ علیہ وسلم کی زبانی گھر کی نماز چار رکعت، سفر کی نماز دو رکعت اور خوف کی نماز ایک رکعت فرض کی ہے۔"}],[1533,"عبداللہ بن عباس رضی اللہ عنہم سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے ذی قرد ۱؎ میں نماز پڑھی، لوگوں نے آپ کے پیچھے دو صفیں بنائیں، ایک صف آپ کے پیچھے اور ایک دشمن کے مقابلے میں، تو آپ نے ان لوگوں کو جو آپ کے پیچھے کھڑے تھے ایک رکعت پڑھائی، پھر یہ لوگ دوسری صف والوں کی جگہ پر چلے گئے، اور وہ لوگ ان کی جگہ پر آ گئے، تو آپ نے انہیں بھی ایک رکعت پڑھائی، اور لوگوں نے قضاء نہیں کی۔\n§وضاحت\n۱؎: مدینہ سے دو منزل کی دوری پر ایک جگہ ہے۔","الألباني: صحيح",{"u2":"حضرت ابن عباس رضی اللہ عنہما سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے مقام ذوقرومیں نماز (خوف) پڑھی۔ لوگوں نے آپ کے پیچھے دو صفیں بنائیں۔ ایک صف آپ کے پیچھے اور ایک صف دشمن کے مقابل، پھر آپ نے اپنے پیچھے والی صف کو ایک رکعت پڑھائی، پھر یہ ان کی جگہ چلے گئے اور وہ آگئے۔ آپ نے ان کو بھی ایک رکعت پڑھائی۔ لوگوں نے پھر دوسری رکعت نہیں پڑھی۔","f2":"دیکھیے حدیث نمبر 1531 کا فائدہ نمبر 3۔"}],[1534,"عبداللہ بن عباس رضی اللہ عنہم کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم (خوف کی نماز پڑھانے) کھڑے ہوئے، لوگ بھی آپ کے ساتھ کھڑے ہوئے، تو آپ نے اللہ اکبر کہا، اور لوگوں نے بھی اللہ اکبر کہا، پھر آپ نے رکوع کیا، اور ان میں سے بھی کچھ لوگوں نے رکوع کیا، پھر آپ نے سجدہ کیا، اور ان لوگوں نے بھی سجدہ کیا، پھر آپ دوسری رکعت کے لیے کھڑے ہوئے تو جن لوگوں نے آپ کے ساتھ سجدہ کر لیا تھا وہ لوگ پیچھے ہٹ گئے، اور اپنے بھائیوں کی حفاظت میں لگ گئے، اور دوسرا گروہ آیا پھر انہوں نے نبی اکرم صلی اللہ علیہ وسلم کے ساتھ رکوع کیا، اور سجدہ کیا، اور سبھی لوگ نماز ہی میں تھے، اللہ اکبر کہتے تھے، لیکن ایک دوسرے کی حفاظت (بھی) کرتے تھے۔","الألباني: صحيح",{"u2":"حضرت عبداللہ بن عباس رضی اللہ عنہما بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم (نماز کے لیے) کھڑے ہوئے اور لوگ بھی آپ کے ساتھ کھڑے ہوئے۔ آپ نے اللہ اکبر کہا اور لوگوں نے بھی اللہ اکبر کہا، پھر آپ نے رکوع فرمایا اور ان میں سے کچھ لوگوں (پہلی صف) نے ساتھ رکوع کیا، پھر آپ دوسری رکعت کے لیے کھڑے ہوئے تو جنھوں نے آپ کے ساتھ سجدہ کیا تھا، وہ پیچھے ہٹ کر اپنے ساتھیوں کی حفاظت کرنے لگے اور دوسرا گروہ آگیا (پچھلی صف آگے آگئی)۔ اب انھوں نے نبی صلی اللہ علیہ وسلم کے ساتھ (دوسری رکعت کا) رکوع اور سجدے کیے اور سب لوگ نماز میں تھے اور تکبیریں کہتے تھے لیکن ایک دوسرے کی حفاظت بھی کرتے تھے۔","f2":"اس کی صورت اس طرح بنے گی کہ مقتدی دو صفوں میں کھڑے ہوجائیں اور بیک وقت امام کے پیچھے نماز شروع کردیں، مگر جب امام رکوع اور سجدہ کرے تو صرف اگلی صف والے امام کے ساتھ رکوع و سجود کریں، پچھلی صف والے کھڑے رہیں اور دشمن پر نظر رکھیں۔ مسلح حالت میں دشمن کے حملے کا جواب دینے کے لیے تیار رہیں۔ جب پہلی صف والے پہلی رکعت کے رکوع و سجود سے فارغ ہوجائیں تو وہ پیچھے چلے جائیں اور پچھلی صف والے آگے آجائیں۔ اب یہ امام صاحب کے ساتھ دوسری رکعت میں رکوع سجدہ کریں گے اور پچھلی صف والے آگے آجائیں۔ اب یہ امام صاحب کے ساتھ دوسری رکعت میں رکوع سجدہ کریں گے اور پچھلی صف والے کھڑے رہیں گے اور حفاظت کریں گے، پھر امام صاحب کے ساتھ دونوں صفیں سلام پھیر دیں گی۔ اس صورت میں دونوں گروہوں نے نماز بیک وقت پڑھ لی اور ایک دوسرے کی حفاظت بھی کرتے رہے۔"}],[1535,"عبداللہ بن عباس رضی اللہ عنہم کہتے ہیں کہ خوف کی نماز صرف دو سجدوں پر مشتمل تھی، جیسے آج کل تمہارے ان اماموں کی پیچھے تمہارے نگہبان پڑھتے ہیں، مگر وہ باری باری آگے پیچھے آئے، اس طرح کہ پہلے ایک گروہ (نماز کے لیے آپ کے ساتھ) کھڑا ہوا حالانکہ وہ سب رسول اللہ صلی اللہ علیہ وسلم کے ساتھ تھے، آپ کے ساتھ ان میں سے ایک گروہ نے سجدہ کیا، پھر رسول اللہ صلی اللہ علیہ وسلم کھڑے ہوئے، اور لوگ بھی آپ کے ساتھ کھڑے ہو گئے، پھر آپ نے رکوع کیا، اور سبھی لوگوں نے بھی آپ کے ساتھ رکوع کیا، پھر آپ نے سجدہ کیا، تو آپ کے ساتھ ان لوگوں نے سجدہ کیا جو آپ کے ساتھ پہلی بار کھڑے تھے، پھر جب رسول اللہ صلی اللہ علیہ وسلم اور وہ لوگ جنہوں نے آپ کے ساتھ آخر میں سجدہ کیا تھا بیٹھے تو جو لوگ کھڑے تھے (اور سجدہ نہیں کیا تھا) انہوں نے خود سے سجدہ کیا، پھر وہ لوگ بیٹھے تو رسول اللہ صلی اللہ علیہ وسلم نے سب کے ساتھ سلام پھیرا۔","الألباني: حسن صحيح",{"u2":"حضرت ابن عباس رضی اللہ عنہما بیان کرتے ہیں کہ نماز خوف صرف دو رکعتیں ہے جیسے آج کل تمھارے (حکام کے) محافظ تمھارے اماموں کے پیچھے نماز پڑھتے ہیں، مگر وہ باری باری سجدے کرتے تھے۔ (اس طرح کہ) ان میں سے ایک گروہ کھڑا رہتا، حالانکہ وہ سب رسول اللہ صلی اللہ علیہ وسلم ہی کے ساتھ کھڑے ہوتے تھے اور ایک گروہ کے لوگ (اگلی صف والے) آپ کے ساتھ سجدے کرتے تھے، پھر رسول اللہ صلی اللہ علیہ وسلم کھڑے ہوتے اور وہ سب آپ کے ساتھ کھڑے ہوجاتے، پھر آپ رکوع فرماتے اور وہ سب آپ کے ساتھ رکوع میں جاتے، پھر آپ سجدہ کرتے تو آپ کے ساتھ وہ لوگ سجدہ کرتے جو پہلی رکعت میں کھڑے رہے تھے، پھر جب رسول اللہ صلی اللہ علیہ وسلم اور آپ کے ساتھ سجدہ کرنے والے نماز کے آخر میں بیٹھتے تو جو لوگ کھڑے رہے تھے، انھوں نے اپنے طور پر سجدے کیے، پھر وہ بھی بیٹھ گئے تو رسول اللہ صلی اللہ علیہ وسلم نے (بیک وقت) ان سب کے ساتھ سلام پھیرا۔","f2":"یہ بھی نماز خوف کے طریقوں میں سے ایک طریقہ ہے۔"}],[1536,"سہل بن ابی حثمہ رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے لوگوں کو خوف کی نماز پڑھائی، تو ایک صف آپ کے پیچھے بنی اور ایک صف دشمن کے بالمقابل بنی، پھر آپ نے انہیں ایک رکعت پڑھائی، پھر یہ لوگ چلے گئے، اور دوسری صف والے آئے تو آپ نے انہیں بھی ایک رکعت پڑھائی، پھر لوگ کھڑے ہوئے، اور انہوں نے اپنی ایک ایک رکعت پوری کی۔","الألباني: صحيح",{"u2":"حضرت سہل بن ابو حثمہ رضی اللہ عنہ سے مروی ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے ہمیں نماز خوف (اس طرح) پڑھائی (کہ) آپ نے ایک صف اپنے پیچھے کھڑی کر لی اور دوسری صف دشمن کے مقابل کھڑی رہی۔ آپ نے اپنے پیچھے والی صف کو ایک رکعت پڑھائی، پھر یہ (دشمن کے مقابلے میں) چلے گئے اور وہ دوسرے آگئے۔ آپ نے ان کو بھی ایک رکعت پڑھائی، پھر وہ اٹھے اور ان سب (دونوں گروہوں) نے ایک ایک رکعت اپنے طور پر پڑھ لی۔","f2":"(۱)حدیث نمبر:۱۵۳۵ اور ۱۵۳۶ والی صورت اس وقت ہوگی جب دشمن قبلے کی جانب ہو۔ اس وقت امام کے پیچھے کھڑے ہوکر بھی دشمن پر نظر رکھی جاسکتی ہے، مگر زیادہ خوف ہو تو حدیث:۱۵۳۵ اور خوف کم ہو تو حدیث نمبر ۱۵۳۶ پر عمل کیا جاسکتا ہے۔ مذکورہ حدیث (۱۵۳۷) اس وقت قابل عمل ہوگی جب دشمن قبلے کی بجائے کسی اور جانب ہو اور امام کے پیچھے کھڑے ہوکر اس پر نظر نہ رکھی جاسکتی ہو۔ اس وقت دو حصے کرلیے جائیں گے۔ ایک حصہ امام کے پیچھے اور دوسرا دشمن کے مقابل کھڑا ہوگا اورمذکورہ طریقے کے مطابق نماز پڑھیں گے۔ (۲)اس حدیث میں اپنے طور پر ایک ایک رکعت ادا کرنے کی تفصیل بیان کی گئی۔ ایک طریقہ تو یہ ہے کہ دوسرا گروہ امام کے سلام پھیرنے کے بعد اپنے طور پر ایک رکعت پڑھ لے اور سلام پھیرے، پھر وہ دشمن کے مقابل چلا جائے اور یہ پہلا گروہ واپس آکر اپنی ایک رکعت اپنے طور پر پڑھ لے اور یہ زیادہ مناسب ہوگا کیونکہ اس طرح دوسرے گروہ کی دونوں رکعتیں اکٹھی ہوجائیں گی۔ دوسرا طریقہ یہ ہے کہ دوسرا گروہ امام کے ساتھ ایک رکعت پڑھ کر چلا جائے اور پہلا گروہ آکر ایک رکعت اپنے طور پر پڑھے، پھر یہ چلے جائیں اور دوسرا گروہ آکر پڑھ لے۔ یہ طریقہ بھی بعض احادیث میں آیا ہے۔"}],[1537,"صالح بن خوات اس شخص سے روایت کرتے ہیں کہ جس نے رسول اللہ صلی اللہ علیہ وسلم کے ساتھ غزوہ ذات الرقاع کے دن خوف کی نماز پڑھی (وہ بیان کرتے ہیں) کہ ایک گروہ نے آپ کے ساتھ صف بنائی، اور دوسرا گروہ دشمن کے بالمقابل رہا، آپ نے ان لوگوں کو جو آپ کے ساتھ تھے ایک رکعت پڑھائی، پھر آپ کھڑے رہے، اور ان لوگوں نے خود سے دوسری رکعت پوری کی، پھر وہ لوگ لوٹ کر آئے، اور دشمن کے سامنے صف بستہ ہو گئے، اور دوسرا گروہ آیا تو آپ نے ان لوگوں کو ایک رکعت پڑھائی جو آپ کی نماز سے باقی رہ گئی تھی، پھر آپ بیٹھے رہے، اور ان لوگوں نے اپنی دوسری رکعت خود سے پوری کی، پھر آپ نے ان کے ساتھ سلام پھیرا۔","الألباني: صحيح",{"u2":"حضرت صالح بن خوات نے اس صحابی رضی اللہ عنہ سے بیان کیا جس نے غزوۂ ذات الرقاع میں رسول اللہ صلی اللہ علیہ وسلم کے ساتھ نماز خوف پڑھی تھی کہ ایک گروہ نے آپ صلی اللہ علیہ وسلم کے پیچھے صف بندی کی اور دوسرا گروہ دشمن کے مقابلے میں رہا۔ آپ نے اپنے ساتھ والے لوگوں کو ایک رکعت پڑھائی، پھر آپ کھڑے رہے اور انھوں نے اپنی دوسری رکعت پڑھ لی، پھر وہ چلے گئے اور دشمن کے مقابلے میں صف بندی کرلی اور دوسرا گروہ آپ کے پیچھے آگیا۔ آپ نے انھیں باقی ماندہ (دوسری) رکعت پڑھادی، پھر آپ بیٹھے رہے اور انھوں نے اپنی دوسری رکعت مکمل کرلی، پھر آپ نے ان کے ساتھ سلام پھیرا۔","f2":"(۱)یہ نماز خوف کی ایک اور صورت ہے جس میں ہر گروہ کی دو رکعتیں اکٹھی پڑھی گئیں۔ ایک آپ کے ساتھ اور ایک الگ الگ۔ یہ صورت اس لحاظ سے بہتر ہے کہ اس میں دوران نماز میں آنا جانا نہ ہوگا بلکہ دونوں رکعتیں متصل پڑھی جائیں گی۔ (۲)’’ذات الرقاع‘‘ رقاع جمع ہے ’’رقعہ‘‘ کی، اس کے معنی ہیں: ٹکڑا۔ اس جنگ کو غزوۂ ذات الرقاع یا تو اس لیے کہتے ہیں کہ اس غزوے میں جاتے ہوئے پتھروں کی وجہ سے مسلمانوں کے پاؤں زخمی ہوگئے اور انھیں پاؤں پر کپڑوں کے ٹکڑے باندھنے پڑے، یا اس لیے کہ اس علاقے کی زمین کے ٹکڑے مختلف رنگوں والے تھے، یعنی کچھ پہاڑیاں سرخ تھی، کچھ سفید اور کچھ سیاہ۔ واللہ اعلم۔"}]]);
